Object.assign(window.__LB,{"15000": ["预后", "脉至弦数，弦为肝郁，数为虚火，瘰疬破溃后见此脉，是肝郁化火、阴血耗伤之象。面色㿠白、大便溏薄，乃脾土亦衰，气血生化无源，故称疬劳。弦数之脉与㿠白、溏薄并见，示肝脾两伤、虚实夹杂，故曰最难图治，拟香贝养营汤培本。", ["弦", "数"]], "15001": ["预后", "右脉细弦，细为血少，弦为气滞，合之疽生项部硬如顽石、色紫，正是气血凝滞、郁结不散之征。脉细弦而不洪数，说明非实热壅盛，乃血虚气滞成疽。溃后得脓则气血尚能托毒外泄故吉，出血出水则气不摄血、血不化脓故凶。", ["细", "弦"]], "15002": ["病机", "脉见细数，细主阴血亏少，数主虚热内扰。颈上瘰疬硬而无情，是肝血枯槁、筋脉失养而痰凝。久热不已与细数脉相应，说明水不涵木、木火偏亢。虽有面黄呕吐似宜甘温，但脉细数久热，当以壮水涵木制阳光为要，不可拘泥于甘温补气。", ["细", "数"]], "15003": ["病机", "脉至细数，细为肝血不足，数为木火上炎。肝无血养则木火偏旺，火灼津液则痰凝结疬。细数之脉与痰核并见，正是虚火挟痰之象，故明言此属虚症。既属虚，则攻消峻剂反伤气血，切勿攻消为事，当养血清火化痰。", ["细", "数"]], "15004": ["病机", "左关独见弦滑而有时歇止，弦主肝郁，滑主痰凝，歇止为气机郁滞、脉道不利。疽生项部硬如岩石，系郁结痰滞、肝无血养所致。左关候肝，弦滑歇止正反映肝郁痰凝、气血运行不畅，与硬如岩石之症相应，非单纯虚损可比。", ["弦", "滑", "结", "代"]], "15005": ["病机", "脉至左弦带数，左关候肝，弦为肝郁，数为火旺。颈侧结核木硬无情，是肝无血养、木火上炽，火灼津液挟痰凝结而成。弦数之脉与木硬结核相应，说明火郁痰凝、阴血暗耗，故非急切可愈，治当养血清火、化痰软坚。", ["弦", "数"]], "15006": ["病机", "六脉细涩，细为营阴亏少，涩为血行不畅。面淡黄舌白、经事愆期、纳谷甚少，皆营阴本亏、脾失健运之征。情志不畅，遏壅荣行，结痰成疬，结核累累蔓延上下，溃则腐骨，是形伤及气、阴阳两阻。细涩脉正合营亏气滞、痰凝络阻之机。", ["细", "涩"]], "15007": ["治法", "素有失血，脉见细数，细为阴血亏虚，数为虚火内动。颈侧生疬，虽兼客邪，然细数之脉示阴血已伤、虚火易炽，攻消升散之剂最易耗血动火，故在所宜慎。此段以脉细数定治法禁忌，强调养血清火、扶正为主，不可峻攻升散。", ["细", "数"]], "15008": ["病机", "脉不数，说明余邪未化热，正气尚能约束邪气。耳后项上肿而不红、舌不厚、神情清爽，皆非实热壅盛之象，乃气机不宣达、外邪挟痰滞于络脉所致。脉不数正可排除热毒炽盛，故治宜疏散宣达，而非苦寒攻下。", []], "15009": ["病机", "左三部脉细如丝，为阴血亏虚、脉道不充；右寸关弦滑，为气郁痰凝之象。颐颔结块不红不肿，属虚痰而非实结。脉细主虚，弦滑主痰，合而观之，乃阴亏气滞、痰浊凝聚，故不可专用攻坚克伐，宜金水六君加理气行痰，缓缓图之。", ["细", "弦", "滑"]], "15010": ["预后", "前诊脉细数无根，今脉虽不似前之细数无根，结块亦消，似有起色，然吸吸气短，乃源海无根、肾不纳气之候。脉象稍缓而根本未复，非肺家实喘可比，往往顷刻变生脱绝。故勉以观音梦授散合参麦散纳气、都气丸摄下，倘应手尚有生机，否则危殆。", ["细", "数"]], "15011": ["病机", "脉见细数，著手即空，右更无力，细为阴亏，数为虚热，空而无力则阴不敛阳、气亦不足。内热不已，肝肾阴亏，无形之火上升，有形之痰凝聚，颈侧结块累累按之无情，乃虚痰也。脉症合参，显系阴亏火旺、痰凝络脉，非实症可攻消，故拟育阴制阳、养营软坚。", ["细", "数"]], "15012": ["病机", "复诊左三部脉仍细数，右三部未见有力，说明阴亏未复而气分亦弱。细数主阴亏虚热，右无力主气分不足。所谓阴根于阳、阳根于阴，补阴不能骤生，补气则无形能生有形。脉象未改，故须急为培补气分，兼慎调养，避炎威风寒、忌腥腻生冷，防变生他症。", ["细", "数"]], "15013": ["病机", "左三部脉细数，寸尤甚，右三部细软。细为阴亏，数为虚阳上炽，软为气分有亏。素质阴亏，课读耗气，颈侧结核有红仁，显系气分亏虚、肝肾之阴不足，虚阳上炎，痰随火升凝结血分而成。脉象左右合参，虚实并见，以虚为本，痰火为标。", ["细", "数", "软"]], "15014": ["病机", "左关独见弦细，左关候肝，弦为肝脉，细为血少。左肩内侧痛而不能屈伸，乃肝血不荣于筋，筋脉失养；更兼外寒侵袭络脉，气血凝滞。脉弦细正合肝血不足、寒客络脉之病机，故法当温通活血，养血荣筋。", ["弦", "细"]], "15015": ["病机", "舌苔滑白，脉至迟软。迟主阳气不足、湿阻气机，软主正气虚弱、湿邪偏盛。肩臂酸麻，乃湿痰留滞经络、气血运行不畅所致。脉迟软与滑白苔相应，说明湿痰未清、阳气不充，故犹有湿痰不清，治当化湿祛痰、通络和营。", ["迟", "软"]], "15016": ["病机", "原文称「脉有力有神」，说明正气尚充、毒邪未深陷。脉有力主邪实而正不虚，有神则胃气未败，故毒发手腕内侧虽疑触虫毒，仍可攻邪为主，用仙方活命饮加减清热解毒、消肿散结。脉象有力有神是判断可攻可消、预后尚佳的关键依据。", ["有力"]], "15017": ["预后", "原文「精神脉象不见衰弱」，指脉象未现虚衰之象，与指麻属气虚之说相参。脉不衰弱说明气血根本未亏，指麻仅为局部气虚络滞，非全身虚损重证，故断「放心可也」。此段以脉象判断预后，脉有神不衰则病轻可安。", []], "15018": ["病机", "原文未载具体脉象，以「掌得血而能握」立论，指屈难伸归为血虚不荣脉络。血虚则筋脉失养，故屈伸不利；然补血不能骤生，当先补气，取「无形者能生有形」之意，气旺则血生。此段重在阐发气血相生、血虚筋急之病机，并嘱绝欲以保精血。", []], "15019": ["预后", "原文「脉至沉细，纳谷日减」，沉主里、细主虚，与中脘期门间坚如顽石、硬如牛领之块相参，说明寒气痰积闭结于里，正气已衰、胃气渐败。脉沉细而纳减，攻消难施，故断成功不易，若溃脓更有性命之忧，仅以回阳三建汤希图万一，属危重预后之判。", ["沉", "细"]], "15020": ["病机", "原文「脉至左弦右弱」，左弦应肝，右弱应脾。脐左硬块似痂非痂，乃肝血不足、筋不柔和所致，似块非块，非实积可比。弦为肝脉失养而劲，弱为脾气不足，故攻散消破断断不宜，当养肝血、柔筋脉，不可作癥瘕攻伐。", ["弦", "弱"]], "15021": ["病机", "原文「六脉细弱如无」，细弱主气血大虚。筋无血养则少腹结块、痛连腿膝而不能屈伸，气不流行则络脉滞涩。脉细弱如无说明虚为本、块为标，故宜温培气血，不可攻消。此脉象揭示气血亏虚、筋脉失养之病机。", ["细", "弱"]], "15022": ["病机", "原文未载脉象，以块大径尺、不在皮肤肌肉而附于筋立论，痛则牵连络脉、后连腰脊下连腿，症属阴经阴症，朝轻暮重、蒂固根深。说明阴寒凝滞、血瘀气阻、络脉不通为病机，故消之甚难，议血气兼培中加宣络行血、理气消坚。", []], "15023": ["病机", "原文「脉至左三部迟滞」，迟主寒、滞主气血不畅。腹皮痈块大如盘、色白板硬，色白属寒，板硬属瘀，脉迟滞正合寒凝血脉、瘀阻不行之机，故断为寒积夹瘀所成。脉象与色白板硬相参，揭示寒瘀互结、非热毒壅盛之痈。", ["迟", "滞"]], "15024": ["病机", "左寸关滑数甚于别部，滑主痰，数主热，左寸关候心肝，提示痰火内蕴。原文谓“腋下生痰”，又言“肝肾之阴亏于下，阴亏则阳浮于上，火动风生，风动痰生”，故脉象反映阴亏阳浮、火动痰生之病机，与爪枯、畏风、腋下生痰等症相应。", ["滑", "数"]], "15025": ["病机", "脉至软弱，为气血不足之象。腋疽溃而不敛，日久耗伤气血，故脉见软弱。原文直言“气血亏矣”，脉症相合，说明溃后正虚，无力托毒生肌，主气血两亏之病机。", ["软", "弱"]], "15026": ["病机", "脉浮数，左关为甚，右脉涩滞。浮主表，数主热，涩主血瘀气滞。原文谓“努力伤筋，血凝气滞，更兼重感风寒”，又“肝郁不舒，邪袭太阳、少阳、阳明”，故脉象反映外感风寒、肝郁气滞、血凝毒聚之病机，与漫肿色白、痛连胸背、增寒壮热相应。", ["浮", "数", "涩"]], "15027": ["病机", "六脉细弱，为气血俱亏之象。大脓已得，邪去正伤，故脉见细弱。原文谓“气血俱亏，纯乎虚象”，法当气血兼顾，加重补脾醒胃之品。脉象说明溃后虚象明显，主气血两虚之病机。", ["细", "弱"]], "15028": ["病机", "原文未识脉名，但言“脉至无力”，为气血不足之象。蜂窝搭手肿而不高、束而未束，属外症之重阴者，脉无力提示气血本不充足，正虚无力托毒，故急宜托解以防内陷。脉象反映正虚邪陷之病机。", []], "15029": ["病机", "脉滞迟，滞主气血不畅，迟主寒。背右太少两经交会处患疡，色白漫肿而硬，原文谓“痰注寒凝，气血因之不宣”，故脉见滞迟。脉象反映寒痰凝滞、气血不宣之病机，法宜温通化坚、和卫养营。", ["滞", "迟"]], "15030": ["病机", "六脉俱伏，伏主邪闭。背疽黑陷，似虚陷而实非虚，原文谓“毒闭而火结也”，又“闭结则脉络不通，所以脉伏而便闭也”。脉伏与便闭并见，说明毒火内闭、脉络不通之病机，法当清解透达，火郁发之。", ["伏"]], "15031": ["预后", "六脉洪大，洪大为热盛之象。服清解剂后口舌糜烂，疮形高，黑色转红而痛，原文谓“此毒火外达，是吉兆也”。脉象由伏转洪大，说明毒火外透，正气尚能抗邪，预后转吉，故可加紧清解而愈。", ["洪", "大"]], "15032": ["病机", "六脉虚软，为气血两虚、脾胃受损之象。疮色暗紫、顶平根散、无脓流血、神情委软、饮食减少、唇舌色淡，皆气弱血虚、阳衰不能托毒化腐所致。脉虚软正合“气弱血虚、脾胃两伤”之机，故非大加温补不可。", ["虚", "软"]], "15033": ["病机", "脉至左弱右弦，左弱为正气不足，右弦为邪毒壅盛，故曰“正虚邪盛”。悒郁恚怒气滞血凝，毒发肝肾，疮顶平色紫、散漫不束，正虚不能托邪，邪盛易于内陷，故“极易变陷”，当急予大剂托解。", ["弱", "弦"]], "15034": ["预后", "脉至细弱无根，为毒盛正虚、根本已亏之候。疮色紫顶平、根不收束、腐而不化、按之板硬，正虚不能托毒外出，故断为“凶多吉少”。细弱无根示胃气衰败，托解亦难收功，故有“马到临崖，收缰惟恐已晚”之叹。", ["细", "弱"]], "15035": ["病机", "脉数稍减、脉虚正虚，说明护托透解后邪热略退而正气仍虚。胸腹满闷、按之中空，为气火毒邪盘踞于中而正不胜邪。原文引“脉虚正虚，首尾必行补法”，强调正虚则邪进、正旺则邪退，故仍用前法托补兼施。", ["数", "虚"]], "15036": ["病机", "左关弦大而滑，左关属肝，弦主木郁，滑主痰凝，大示邪实壅聚。中石疽顽硬如岩，正是肝木郁结、痰浊凝滞于局部所致，故断为“木郁痰凝”。若能化脓则痰郁得化、气血流通，故吉；否则顽硬难消，服药不易见功。", ["弦", "大", "滑"]], "15037": ["病机", "脉至沉迟，沉主里、迟主寒，为寒湿痰浊内滞之象。腰脊两旁板硬无情，属足太阳膀胱经所过，膀胱为寒水之府，寒痰湿浊凝滞其间，阳气不运，故宜温通以化寒湿。", ["沉", "迟"]], "15038": ["病机", "产后恶露不清，瘀血留滞，少腹左侧攻撑作痛、结块拒按，瘀久化热，故身热而脉数。数脉在此示瘀热内蕴、势欲成痈，左足屈伸不利亦因瘀阻经络，症非轻浅，当及早消瘀清热。", ["数"]], "15039": ["病机", "脉来细弦，细为血少，弦为气机不畅，合之乃气血不和之象。童儿腹中似有横梗而按之不痛，非实积有形，乃气血运行失和、脉络拘急所致，故曰“气血不和”。延久气滞血瘀，虑成肚痈。", ["细", "弦"]], "15040": ["病机", "脉至细弱，细为血少，弱为气虚，故断为气虚血弱之故。气血不足，肢体失养，故见手麻足痛。脉象与症候相合，虚证显然，非实邪阻滞可比。", ["细", "弱"]], "15041": ["兼症", "表有风寒、里有湿浊，少腹近阴器结块作痛连腰，发热而脉数。数脉主热，示邪郁化热，湿热瘀结于下，故断恐成外疡。脉数与发热、结块并见，为热毒酝酿之征。", ["数"]], "15042": ["病机", "脉至弦洪而大、右关尺更甚，弦主肝郁气滞，洪大主热盛，右关尺甚则湿热下注厥阴。舌苔黄厚，瘀凝所结，势在成痈。年及五旬气血本亏，故商疏托兼施，虑成痈出脓正多时日。", ["弦", "洪", "大"]], "15043": ["病机", "脉至沉而有力，沉主里，有力为实，故断湿热下注肝肾。湿热蕴结下焦，脉沉实应之，非虚寒可比。此以脉之沉实定病位在里、病性属实，与湿热下注之机相应。", ["沉"]], "15044": ["病机", "湿热下注肛门结痈成漏，又经攻伐伤气、湿浊不清，今脉象软弱，软弱主气血不足。故谓气血不可不补，还宜渗湿之品。脉弱示正虚，与攻伐伤气相应，须耐心调养方能痊愈。", ["软", "弱"]], "15045": ["预后", "素体薄弱，疡不敛而成管漏，脓水交流伤气血，故六脉细数。细为阴血亏，数主内热，神情委顿、饮食减少、内热不已，势非浅轻。倘脉数减、饮食增乃转机，此时正在凶险，以脉数增减判预后。", ["细", "数"]], "15046": ["其他", "原文未识脉名，只言尻骨下尾闾患疡不敛。督脉一亏则周身气血无不亏，药力难挽回已坏之气血，故用十全大补合龟鹿固任督，加银花、杜仲。此段重在论督脉亏虚与治法，非凭脉断病。", []], "15047": ["病机", "腿面阳明部位结疽色白木硬，系寒痰，经云先肿后胀者寒伤形也。脉至软弱，软弱主阳气不足、痰湿内凝，与寒痰木硬相应。故主以香贝温散，温化痰湿、散结消疽，脉症合参为虚寒痰凝之候。", ["软", "弱"]], "15048": ["预后", "痈结三阴已自溃、色紫暗，为肝肾营阴不足、湿火下注。脉虽虚，然原文强调“有根有神、不弦不数”，即有胃气而不露弦急数火之象，说明正虚而邪未鸱张，故预后可期，能人事小心则不难就愈，治以托解。", ["虚"]], "15049": ["病机", "大脓已得，毒邪已有出路，而右脉还见数大，数主热、大主邪盛，说明脓虽溃而余热未清、气血尚壅。故补气血之中当佐凉解，既扶正又清余热，紧扣“右脉还见数大”以定清补兼施之法。", ["数", "大"]], "15050": ["病机", "腿外侧痛而不肿，左三部脉弦数。弦主少阳、主痛，数主热，弦数并见说明少阳湿热郁滞经络，故痛而不肿。原文谓“理宜清疏少阳湿热，即是从脉不从症”，并戒“因其不红而为寒”，正以脉弦数断为湿热而非寒证。", ["弦", "数"]], "15051": ["病机", "腿痛难伸、肌肉日削而脉弱无力。弱脉主气血不足，正虚不能充脉，故原文断为“气血有亏”；肌肉削、痛难伸又见沉寒深入、著骨附筋，说明正虚而寒邪深踞筋骨，属虚实夹杂之候。", ["弱"]], "15052": ["病机", "环跳痛而足不能伸，病在筋；所嫌脉数，又兼泄泻，数与症不合。数脉主热，而泄泻伤正，热与虚泻并见，故原文谓“于症不合”，先固正育阴以观效，说明此数非纯实热，须防正虚邪恋。", ["数"]], "15053": ["病机", "喜按而痛甚于夜，环跳肿痛连内侧及委中，两尺脉来微细。微细主肝肾两虚，尺部候肾，故原文断为“肝肾两虚，重寒深湿著于筋骨”，寒欲化火、湿欲化热，遂成附骨环跳疽之重恙，午后寒热、苔黄即其化热之征。", ["微", "细"]], "15054": ["病机", "穿肠腿痈日久难消，近腿缝处隆隆而起、按之微软，为内脓已成。原文谓“色脉两虚”，虚脉示气血不足、正不胜邪，故不宜强消，且为补托，俟顶起脓足再行刀出脓，体现脓成正虚当托毒外出的病机。", ["虚"]], "15055": ["病机", "两膝浮肿、色白而热，脉象带数。数主热，然色白浮肿又属湿，原文断为“寒化为热、湿化为火”，即寒湿久郁化热化火，故宜温凉并用、气血兼培，数脉正是郁热外露之象而非纯寒。", ["数"]], "15056": ["病机", "原文未出脉名，仅述温热夹风，流散肤腠，络脉注于节骱两膝。温热之邪夹风，风性流散，故外走肤腠，内注络脉，聚于膝节骱骨之间。此段重在说明病位在肤腠与络脉，病性属温热夹风，非以脉断，故脉象要素从缺，主旨归于病机传变。", []], "15057": ["病机", "脉见左关尺数而有力，数主热，有力为实，左关尺候下焦肝肾。温化热、热化风，遍体肌肤瘙痒、足踝赤烂浸淫，皆湿热化风外淫之象。脉数实应下焦湿热壅盛，故主清解下焦湿热兼疏泄风邪，脉与症合，病机在湿热风邪搏结下焦。", ["数", "实"]], "15058": ["病机", "原文未出脉名，述腿肿、内侧肝经部络脉肿结成块，刺出血则松，即血痣、血箭之属。良由血热阻位，络脉不宣。血热壅阻肝经络脉，气血不得宣通，故结聚成块，刺血则松。此段以症推机，脉象无载，主旨明血热络阻之病机。", []], "15059": ["病机", "脉致弦数，弦主肝郁气滞，数主火热。诸节属肝，痛而且肿，身见发热，正合木郁气滞、风旋阳亢之机。肝郁化火生风，风阳旋扰，故节肿痛而身热。脉弦数应肝火风阳，故拟逍遥舒郁、加味清火，脉象与病机相印。", ["弦", "数"]], "15060": ["病机", "脉至滑数，滑主痰湿血壅，数主火。肌肤疯如血鳞，乃血燥有火、血热生风之候。滑数之脉应血分有火，火灼血燥，肌肤失养而如鳞。故宜凉血活血，清其血中之火。脉滑数在此主血燥有火之病机，非独痰湿。", ["滑", "数"]], "15061": ["病机", "脉至沉迟细弱，沉主里，迟主寒，细弱主正虚。左足难伸、腰间作痛、结块色白不热不红而痛拒按，乃寒湿深入肝、肾、膀胱三经，气血凝滞。脉沉迟细弱正应寒湿内侵、邪实正虚，故治难速效，以温通宣络、疏理气血为主。", ["沉", "迟", "细", "弱"]], "15062": ["病机", "脉不洪大，舌不焦干而见渴，症属水亏。屈伸不能自如、二便不爽，系肝肾亏损，寒湿乘虚内袭，兼挹郁气滞，营卫不行，结成外疡。脉不洪大说明非实热壅盛，而属水亏正虚，故疏泄消瘀之中宜兼养营育阴，脉象反证其虚。", ["洪", "大"]], "15063": ["预后", "疔生鼻窍名白刃，唇面肿胀连及左肋，心烦呕恶，六脉洪大。洪大为邪毒炽盛、正邪交争之象，疔毒走黄，毒散不收，故脉洪大而症见肿连肋、烦呕。业已走黄，势难挽回，脉症俱示邪盛正溃，预后凶险，故曰勉为图治以翼万一。", ["洪", "大"]], "15064": ["预后", "原文“热退脉平”指脉象由病时的数急转为平和，是邪热已退、正气渐复之征。肿消势减、顶高根束说明疮疡毒势已衰，热退则身热除，脉平则气血调和，故断为“已有可生之机”，属预后良好之象。", ["平"]], "15065": ["病机", "原文“伏毒脉症并无实象可据”指虽有伏毒，但脉症皆不显实象，说明正虚为主、毒邪不盛。身体薄弱、烦劳更伤正气，故治当扶正兼清解，缓缓图痊，不可见症治症而妄攻。", []], "15066": ["病机", "原文“脉至数而无力”为虚数之脉，数主热、无力主虚，合之则示气血不足而兼毒邪。面色不华、饮食减少皆脾虚气血弱之症，故不可作实症攻伐，当培养气血兼理脾胃，佐以化毒清解而不伤正气。", ["数", "虚"]], "15067": ["其他", "此段述医案源流及汪石山“因脉制方，随投辄效”，未出具体脉象，主旨不在论脉主病，而在说明脉诊指导制方之效，故归其他。", []], "15068": ["病机", "原文论“阳有余阴不足”，以日月为喻，言人身气常有余、血常不足，又列举久行伤筋、久立伤骨等数伤皆伤阴，说明阴易亏而难成，故戒人保守阴气，非论治阴虚之病。", []], "15069": ["病机", "原文辨析阳虚与气虚之补，引经云“卫气者水谷之悍气，慓疾不受诸邪”说明阳常有余无益于补；又言“阴气若虚，则阳亦无所依附而飞越”，故丹溪拳拳于补阴，旨在阐明阴阳依附之理。", []], "15070": ["病机", "原文“脉之大小无定、脉为之浮洪而躁扰、脉为之敛小而恬静、脉来浮洪、脉之小而弱者”描述心劳火动时脉浮洪躁扰，火静时敛小恬静，说明动则阳亢火炽、静则阴生，脉随心动而变，主心劳火动、阳亢阴微之病机。", ["浮", "洪", "数", "细"]], "15071": ["治法", "原文“察其脉，切其病”后论治，主张以八物汤为主，双补气血，避免专主四物滋阴加苦寒伤胃、专主四君子加燥热伤阴之偏，体现调和阴阳、因时酌病之治法。", []], "15072": ["病机", "原文未出脉名，然言“心血一亏，则阳热随起”，又谓“心火亢极，故舌生黑胎”，可知病机为心血亏虚、心火亢盛，阳热上炎。所主诸病如夜卧不宁、唇舌焦燥、黑胎，皆由心火亢极、阴血不足所致。静养则阴生阳伏，故治以四物加麦冬、五味、知柏降火滋阴。", []], "15073": ["病机", "初日脉细弱而数，细弱为气阴两虚，数为热；次日浮弦而数，浮弦为邪郁少阳、热势外张。房劳后恶寒发热、头背胃脘痛、呕吐、眼胞青，乃劳倦内伤兼感外邪，正虚邪凑。医投补中益气反致谵语恶热，是误补助热。脉由细弱转浮弦数，示病机由虚转实，邪热渐盛。", ["细", "弱", "数", "浮"]], "15074": ["病机", "脉浮濡无力且过于缓，浮为气虚外浮，濡缓为脾虚湿困、运化无力。年近七十形色苍白，劳倦病疟后胸痞恶痰、不思食、懒倦，皆脾虚痰湿内阻之象；口苦头痛、夜梦纷纭，为虚阳上扰。脉证合参，病机属脾气亏虚、痰湿中阻、清阳不升。", ["浮", "濡", "缓"]], "15075": ["病机", "原文引“脉缓无力者，气虚也”，又云“劳则气耗”“劳倦伤脾”。脾伤不能运化精微以养心，故心神不安。脉缓无力正是脾气虚弱、气血不足之征。所主病机为劳倦伤脾、心脾两虚，故见夜卧不安，治仿归脾汤例补益心脾，药后夜卧颇安。", ["缓"]], "15076": ["病机", "左脉浮濡无力，肝脉颇弦，右脉肺部濡散，脾部浮微，二部似有似无。浮濡无力为气阴两伤，弦为肝郁，濡散为肺气耗散，浮微为脾虚至极。素劳伤脾，又因饮冷酒、头被湿，致湿困脾阳，吐泻大作后气阴更伤，故脉象虚散无根，病机属脾虚湿困、气阴两伤、肝郁不舒。", ["浮", "濡", "弦", "散"]], "15077": ["预后", "久疟后医用丹剂止之，致呕吐不休、粒米不入、大便或泻，面赤妄语身热，脉皆浮而欲绝。浮而欲绝乃阳气浮越于外、根本将脱之象，与面赤身热妄语之假热相应，属阴盛格阳、正气衰败之危候。脉症相悖，提示胃气已败、阳气欲脱，预后不良。", ["浮"]], "15078": ["预后", "面赤身热妄语属阳症，而脉微欲绝则阴脉，阳病得阴脉，脉症相反，故危。又粒米不入为胃气败，数泄泻而热不退为脾阳衰败、虚阳外越。三者皆危，法在不治。脉微欲绝示元气衰微、阴阳离决之势，与阳症假象并见，属真寒假热、正气将脱之候。", ["微"]], "15079": ["病机", "初诊左脉颇和而驶，右脉弱而无力，右弱为脾肺气虚。延至十月，脉皆浮小而濡带数，右尤不足。浮小濡数为气阴两伤、虚热内扰，右不足则脾肺之气尤亏。病疟日久，截药伤正，致脾肺气虚、暑湿未清、气阴耗伤，故脉象虚浮濡数而右部尤弱。", ["浮", "小", "濡", "数"]], "15080": ["病机", "左脉濡小而缓、右脉濡弱无力，濡主湿、缓主脾虚，小弱为气血不足。疟久经截药符水攻伐，脾胃受损，湿滞中焦，故胸膈痞满、饮食少进；脾虚不统血则痔血，湿郁下焦则小便短赤；夜疟寒少热多、自汗，乃气虚湿恋、营卫不和之象。", ["濡", "小", "缓", "弱"]], "15081": ["病机", "脉皆浮濡而缓、按之无力，浮为气虚外浮，濡缓为湿困脾阳。面淡紫、年逾四十，气血已衰；疟夜发渴多汗、呕吐粒食不进，乃脾虚湿浊中阻，胃气上逆，气不化津则渴，卫外不固则汗。脉按之无力，正示中气亏虚、湿邪留恋之病机。", ["浮", "濡", "缓"]], "15082": ["病机", "疟止食进后大便二十日不通，再诊右脉浮小无力、左脉沉弱无力。浮小为肺气不足、无力推动，沉弱为脾虚血少、肠道失润。前用参术草橘补气健脾，气旺而血未充，津亏肠燥故便闭。脉象示气血两虚、肠失濡润，非实热秘结，故加归身、火麻仁养血润肠而病除。", ["浮", "小", "沉", "弱"]], "15083": ["病机", "左脉濡弱、右脉肺部颇洪、关尺亦弱。产后疟止，气血未复，左濡弱为血虚，关尺弱为脾肾不足；右肺洪为虚火上浮、气不归元。才劳气喘咳血、身热脚冷，乃上盛下虚、气阴两伤，虚阳上扰灼肺则咳血，下元不足则脚冷。脉象示本虚标浮之病机。", ["濡", "弱", "洪"]], "15084": ["病机", "脉皆浮大而濡、颇弦，浮大为气虚阳浮，濡为湿困，弦为疟邪郁于少阳。因劳感热，截药增病，过饮吐甚，致脾胃更伤，湿浊上逆，故头痛口渴、呕吐痞塞、自汗倦怠。脉浮大非实热，乃中虚湿恋、邪正交争之象，热多寒少亦示邪郁而正已伤。", ["浮", "大", "濡", "弦"]], "15085": ["病机", "久疟半年，补中益气或止或作，又因劳伤咳嗽，误加半夏、五味致喉痛声哑、夜不能寝。右脉浮濡为脾肺气虚兼湿，左脉小弱为血少。浮濡非表邪，乃气浮于上；小弱示下元亏虚。误用温燥酸收，耗气伤阴，虚火上炎灼喉，故声哑不寐，脉示气阴两虚、虚火上浮。", ["浮", "濡", "小", "弱"]], "15086": ["病机", "脉皆浮虚缓弱而不甚大，浮虚为气不内守，缓弱为脾阳大伤。素劳久疟，三日一发，呕吐不食，小便频数，气喘咳嗽，不能伏枕，头身骨节皆痛。医作疟治反甚，因脉不弦不数，非邪实，乃久病脾肾两虚、气不归元，虚阳浮越，故喘咳骨痛，脉虚缓示正虚为主。", ["浮", "虚", "缓", "弱"]], "15087": ["病机", "左脉浮微似有似无，右脉浮小按之不足，浮微为阳气外脱，浮小为气血大虚。年五十余忧劳，背疮艾灸百余壮，疮散病疟，身热自汗、口渴头晕、呕吐泄泻、不进饮食。灸后气泄，脾阳衰败，清阳不升则晕，浊阴不降则吐泻。脉示气阳两虚、中气欲脱，非暑热实证。", ["浮", "微", "小"]], "15088": ["病机", "脉浮为风邪在表，虚为正气不足，驶示热象。患者冒风病疟，热多寒少，头痛倦怠，食少自汗，显系风邪外袭、卫表不固、正虚邪恋之机。浮虚近驶说明表虚有热，与自汗、倦怠、食少相应，非单纯实疟。", ["浮", "虚", "驶"]], "15089": ["病机", "脉濡主湿、主虚，滑主痰。患者咳嗽有块、呕顽痰、胸膈壅满、背心胀，显系痰湿内蕴；妊已六月，阴血养胎，脉道濡软。濡而近滑说明痰湿内阻、气血不足，与寒战、肢节痛、吐冷气、胸喉如有物碍相应，非伤寒表实。", ["濡", "滑"]], "15090": ["病机", "脉浮濡近驶，浮为虚阳外浮，濡为气血不足，驶为内热。患者形瘦色脆，疟痢反复，腹胁胀痛，气喘溏泻，内热不减，显系脾胃虚弱、气血两亏、虚热内扰。浮濡近驶说明正虚邪恋、虚热不敛，与自汗、倦怠、食少、内热相应。", ["浮", "濡", "驶"]], "15091": ["病机", "脉濡弱近驶稍弦，濡弱为气血两虚，驶为有热，弦为疟邪深入、厥阴受病。患者劳而病疟，寒少热多，自汗体倦，头痛胸痞，咳渴恶食，显系气血两虚、疟邪深入厥阴。濡弱驶弦说明正虚邪恋、虚热内郁，与自汗、体倦、恶食相应。", ["濡", "弱", "驶", "弦"]], "15092": ["病机", "原文未直接描述脉象，但前段脉濡弱近驶稍弦，参形观色，断为气血两虚、疟已深入厥阴。自汗嗽渴、恶食胸痞，说明脾胃肺气俱损，血药独理难效。久疟成痨之虞，在于气血双亏、邪陷阴分，故以补中益气汤倍参、耆、术，扶正达邪。", []], "15093": ["病机", "脉皆濡弱近缓，左尺略驶。濡弱为气血不足，缓为脾胃虚弱，左尺驶为下焦有热。患者形色颇实，但舟行过劳受热，咳嗽病疟，素有热淋，显系劳伤气血、虚热下注。濡弱缓说明正虚，左尺驶与热淋相应，非实热壅盛。", ["濡", "弱", "缓", "驶"]], "15094": ["病机", "原文未直接描述脉象，仅言家人诊之惊曰脉绝，后文指出脉伏耳、非脉绝也。患者因劳取凉、梦遗，恶寒头痛躁闷，显系风暑乘虚入于阴分，阳气内郁，脉道伏匿。脉伏非绝，与头痛躁闷、寒热相应，若进附子汤则误。", []], "15095": ["病机", "脉濡小而驶，脾部兼弦。濡小为气血不足，驶为暑热内迫，弦为疟邪郁于脾。患者寒少热多，头痛躁渴，痞闷呕食，自汗，显系暑热伤气、脾胃虚弱、疟邪内郁。濡小驶弦说明正虚暑热内蕴，与躁渴、自汗、呕食相应，非阴症脉绝。", ["濡", "小", "驶", "弦"]], "15096": ["病机", "脉浮濡而驶略弦，浮为在表，濡为湿滞，驶即数，弦主疟。舟中受热，暑湿外袭，疟邪客于少阳，故寒少热多、头痛躁渴汗多。脉浮濡驶弦，示暑湿郁表、疟邪未解，非七保饮所能胜任。", ["浮", "濡", "驶", "弦"]], "15097": ["病机", "脉皆濡弱颇弦而驶，濡弱为脾虚湿盛，弦为疟邪，驶为热。素善饮则湿伤脾，头痛恶食泄泻、小便短少，皆脾不运湿；午后寒热，疟邪未解。前医二陈平胃五苓反增腰腹拘急，乃渗利伤阴、湿滞未化之故。", ["濡", "弱", "弦", "驶"]], "15098": ["病机", "脉皆六至而数无力，数主热，无力为虚。因劳病疟，劳倦伤脾，气血亏虚，虚热内生，故脉数而无力。此非实疟，乃虚疟也，当补气血为主，不可妄用驱疟劫剂。", ["数", "虚"]], "15099": ["治法", "脉数无力者，血虚也。然汗多乃阳虚表失所卫，消谷善饥乃胃虚火乘其土，皆阳虚也。仲景有凭症不凭脉者，兹当凭症作阳虚治。故以参、耆、术、芍、麦冬、归、地补气血，少佐柏、知母清虚火，二十余帖而安。", ["数", "虚"]], "15100": ["病机", "左脉沉小而数，右脉浮濡无力，脾部弦而颇洪。年逾六十形弱，劳心劳力，疟后左脉沉小数示阴血不足、虚热内扰；右浮濡无力示脾肺气虚；脾部弦洪乃疟邪未净。疟去则脉大小浮沉相等而缓弱，示邪退正虚。", ["沉", "小", "数", "濡"]], "15101": ["病机", "脉皆缓弱，右略弦而涩。久疟后盗汗自汗过多，气血两伤，故脉缓弱；伤食吐泻四日，脾胃更虚，筋惕肉𥆧、惊悸梦遗、小便不禁，皆气血亏虚、筋脉失养、下元不固之候。右弦涩乃土虚木乘、血少滞涩。", ["缓", "弱", "弦", "涩"]], "15102": ["病机", "原文未直接描述脉象，但言「须不见脉见症，必是禀赋素弱」，强调凭症辨治。气升胀闷触痛，脾虚不运、气郁所致；胸膈漉漉水声，留饮为患。用独参汤补气血，加姜安呕吐、黄柏降逆气，后因补塞太过而吐复作，减参加行散佐使而愈。", []], "15103": ["病机", "脉皆浮濡而滑，按之无力。浮濡为气虚湿滞，滑为痰湿，按之无力则正虚。形肥脆、内宠妻，劳热鼻衄久流臭涕，目昏耳重食少体倦，乃脾肺气虚、湿浊上蒙清窍。前用四物凉血、参耆补气罔效，盖未化湿浊也。", ["浮", "濡", "滑"]], "15104": ["病机", "脉细弱为气血两虚，数则虚热内生。年逾五十病痢半载，前医以四物凉血、香连苦寒，愈伤脾胃，故胃脘腹痛、里急后重、下痢频并嗳气，皆中虚气滞、虚热上逆之象。细弱而数，正示本虚标热，非实痢可下，故补益为主。", ["细", "弱", "数"]], "15105": ["病机", "脉细弱近滑，右脉觉弱，细弱为脾胃气虚，滑为湿滞内蕴。面色萎黄、食少无味，脾虚不运；大便不通、后重甚痛，乃气虚无力推荡、湿滞壅于肠道。前用承气峻下不效，正因脉弱非实，攻之反伤中气，故当补脾行滞。", ["细", "弱", "滑"]], "15106": ["病机", "脉濡散颇缓，濡为湿，散为气虚不敛，缓为脾土本象。年逾六十，自用利药三帖，病减而後重滞下未除，是攻利伤脾、中气已虚，湿滞未尽。濡散缓并见，示脾气虚弱、湿浊留连，不可再下，当健脾化湿、升举后重。", ["濡", "散", "缓"]], "15107": ["病机", "脉弦濡而弱，弦为肝郁，濡弱为气血不足。胁痛误补则愈甚，龙荟丸苦寒泻肝痛减，然脉弱非纯实。弦濡弱并见，示肝郁而脾虚血少，胁络失养兼气滞。若再峻泻，必伤中气，故当柔肝养血、健脾理气，不可一味攻伐。", ["弦", "濡", "弱"]], "15108": ["病机", "脉濡弱而缓，濡弱为气血亏虚，缓为脾虚湿滞。越五年腹胁复痛，思类前病欲服龙荟丸，然脉已无弦劲，纯见濡弱缓，是肝郁已减而脾虚湿困为主。此痛由中虚气滞、络脉失养，非实火可泻，龙荟苦寒决非所宜，当温补脾土、调气和络。", ["濡", "弱", "缓"]], "15109": ["病机", "脉濡弱近驶，濡弱为气血两虚，驶即数，为虚热或气陷。病滞下腹痛后重、日夜四五十行，泻利过度更伤中气。濡弱近驶示脾虚气陷、虚热内扰，非实积可攻。当补中升提、健脾止痢，若误下则气愈陷、脉愈弱。", ["濡", "弱", "驶"]], "15110": ["病机", "脉弦细而濡，按之不足，弦为肝郁，细濡为血少湿滞，按之不足示虚。两胁肋痛，小柴胡初效后不效，是肝郁虽在而血虚湿阻为本。弦细濡并见，示肝络失养、气滞湿留，不可再以柴胡升散耗气，当养血柔肝、化湿理气。", ["弦", "细", "濡"]], "15111": ["病机", "脉缓弱无力，缓为脾土之象，弱而无力则脾气大虚。年逾四十春间患胀，胃苓汤利湿、雄黄敷贴外治皆不效，是胀由脾虚不运、气滞水停，非单纯湿盛。缓弱无力正示中气不足、运化无权，当补脾益气以消胀，不可专事攻利。", ["缓", "弱"]], "15112": ["病机", "脉缓为气虚之征，重按则无，示阴亡。原文谓“病属气虚，医反下之，下多亡阴”，误下致阳虚阴亡，故脉缓而重按无力。此脉主气虚中满，与胀病相应，且预后不良，八月水土败时尤可忧。", ["缓"]], "15113": ["主病", "脉细濡近驶，为形瘦弱小者之鼓胀脉；脉缓弱无力，为身肥者之鼓胀脉。二者皆主气虚湿滞，鼓胀大如箕，垂如囊，立则垂坠，有碍行步，乃脾虚水湿不运之候。", ["细", "濡", "驶", "缓"]], "15114": ["主病", "脉皆洪滑，见于瘦长善饮之人，洪为热盛，滑为湿聚，主湿热内蕴。原文未言症候，但结合善饮，可知酒湿化热，鼓胀之由。", ["洪", "滑"]], "15115": ["预后", "原文引《脉诀》云“腹胀浮大，是出厄也”，虽未识脉名，但以浮大为顺，主湿热鼓胀可治。湿热大重，宜远酒色，以香连丸清化，月余良愈，示脉症相应则预后佳。", []], "15116": ["病机", "脉皆浮濡近驶，浮为虚阳外浮，濡为湿滞，驶为热象，主酒色不谨，湿热伤脾，腹胀如鼓。前医以平胃散、广荗溃坚汤不效，因未识此脉属虚中夹湿热，徒攻无益。", ["浮", "濡", "驶"]], "15117": ["病机", "脉皆细濡近驶，细为阴血不足，濡为湿，驶为热，主血虚湿热郁于肌肤。症见身痒，搔之热蒸，皮内肉磊如豆粒，痒止热散磊消，乃湿热浸淫，血虚生风之候。", ["细", "濡", "驶"]], "15118": ["病机", "脉皆浮洪弦虚，浮洪为虚阳外越，弦为气逆，虚为不足，主大虚之症。年逾六十，过劳好酒，膈食不下，化为脓痰，乃酒伤气血，劳伤胃气，虚火上逆所致。", ["浮", "洪", "弦", "虚"]], "15119": ["误治", "脉见浮洪弦虚，本为大虚，医误作热症用凉药，则助阴伤阳；误作痰气用二陈香燥，则耗气伤胃，病益甚。原文强调“非吉兆”，治以人参、白术等补虚敛脉，脉敛而膈宽。", ["浮", "洪", "弦", "虚"]], "15120": ["病机", "脉皆濡弱而缓近驶，濡弱为气血不足，缓为脾虚湿滞，近驶则兼有郁热。形肥苍白、年五十余，脾虚湿盛之体，湿热下注而为淋，砂石涩痛。前医以五苓、琥珀八正散通利，反伤正气，故病益加。脉象示本虚标实，不可纯用清利。", ["濡", "弱", "缓", "驶"]], "15121": ["病机", "脉皆细弱，脾部尤近弦弱，细弱为气血两虚，弦为肝木乘脾。年逾四十，两眼昏昧、咳嗽头痛、恶心似饥，皆中气不足、清阳不升、肝脾不和所致。前医以眼科治之，病甚，盖未识脾虚肝乘之本。脉象示脾虚肝郁，当补脾调肝。", ["细", "弱", "弦"]], "15122": ["病机", "脉皆缓弱无力，左脉缓而略滑，缓弱为脾肾气虚，滑为湿浊内蕴。房劳汗出浴后近女色，致白浊、背痛、梦遗，皆肾虚湿浊下注、督脉失养。前医误用苦寒，口苦膝肿。脉象示本虚标实，脾肾两亏兼湿浊未清。", ["缓", "弱", "滑"]], "15123": ["病机", "脉颇洪滑，洪为热盛，滑为痰壅。秋凉病痰嗽气喘不能卧，春暖即安，病十余年，乃痰热内蕴、肺失肃降。前医发表疏内，暂快复作，未除痰热根本。脉象示痰热壅肺，当清化痰热，不可徒事表散。", ["洪", "滑"]], "15124": ["病机", "脉皆浮缓而濡，浮为气虚外浮，缓濡为脾肺气虚、卫表不固。年逾五十，形色脆弱，秋冬痰嗽气喘、自汗体倦、呕恶，皆脾肺气虚、痰湿内生。脉象示气虚痰湿，当补脾益肺、化痰固表。", ["浮", "缓", "濡"]], "15125": ["病机", "脉皆濡细稍滑，濡细为气血两虚，稍滑为湿滞肠道。滞下、腹痛后重，乃脾虚湿滞、气血不和。脉象示虚中夹滞，不可峻下攻积，当健脾化湿、调气和血。", ["濡", "细", "滑"]], "15126": ["病机", "脉浮濡近驶，浮濡为肺气不足、津液不布，近驶为肺有郁热。产后咳嗽痰多、昼轻夜重、自汗，前医误补，嗽愈甚。脉象示肺热痰壅，非虚寒可比，故用保和汤清肺化痰而安。", ["浮", "濡", "驶"]], "15127": ["病机", "右脉浮濡近驶，按之无力，左脉稍和，浮濡为肺气不足，驶为肺热，按之无力为气分虚。怀妊七月，嗽喘不能伏枕，乃肺热痰壅、气机不利。前医降气、发表、和解皆无效，脉象示肺热兼气虚，当清肺化痰、益气安胎。", ["浮", "濡", "驶"]], "15128": ["病机", "脉洪近驶，洪为邪热亢盛，驶示热势急迫。童子伤寒咳嗽痰少面赤，本属表邪未解，误用参苏饮温散，致热邪内炽，肺失清肃，故嗽甚。脉洪驶与面赤、日夜不休相应，提示热壅于肺，非虚寒之候。", ["洪", "驶"]], "15129": ["病机", "脉皆细微而数，右脉尤弱，细为阴血不足，微为阳气衰微，数为虚热内扰，右弱则脾肺之气尤亏。妇瘦弱久病，走气疼痛、呕食不进，前医作气作痰攻伐，更伤中气。脉症合参，乃脾虚气郁、气血两亏之候，非实邪壅滞。", ["细", "微", "数", "弱"]], "15130": ["预后", "前诊脉数而弱，此诊转稍缓而健，缓为胃气渐复，健则脉来有力，示补脾散郁后中气渐振、郁热渐退。原文以脉之变化印证“诸痛亦减”，说明数弱之脉主脾伤气郁，脉转缓和即病机向愈之兆。", ["数", "弱", "缓"]], "15131": ["病机", "脉皆浮濡而缓，浮为气虚外浮，濡为湿滞气弱，缓为脾胃本脉，然缓而无力则主中虚。患者年逾五十，形肥色紫，气从脐下冲逆，睡卧不安，饮食少，精神倦，脉症相合，显系气虚不摄、冲脉上逆，非阴火实证。", ["浮", "濡", "缓"]], "15132": ["病机", "脉缓亦气虚，缓而无力为脾胃气弱之征。形肥之人多气虚，气从脐下冲逆，乃中虚不能镇摄冲脉。丹溪虽云阴火，然须合形脉参断。今据形肥与脉缓，断为气虚，故以参芪为君补中，佐黄柏、陈皮以制浮火、理气滞。", ["缓"]], "15133": ["病机", "脉皆浮濡缓弱，浮濡为气虚湿滞，缓弱为脾胃不足、气血两虚。妇遍身麻痹、懵不省人事，前医作风治，用乌药顺气散、小续命汤，风药耗散，气血愈虚。脉症合参，乃气虚血弱、肌肤失养、清阳不升之候，非外风中人。", ["浮", "濡", "缓", "弱"]], "15134": ["病机", "脉皆濡细近驶，濡细为气血两虚，驶示虚热内扰；心脉颇大，右脉觉弱，右弱则脾肺气虚。妇劳倦忧惧，又经硝黄三下，中气受戕，故小腹胀痛、二便秘结、自汗食少。脉症合参，乃气血亏虚、肠腑失润、虚中夹滞之候，非实热燥结。", ["濡", "细", "驶", "大"]], "15135": ["病机", "脉涩细而弱，右脉尤弱而似弦，涩为血少精伤，细为阴血不足，弱为气衰，弦则土虚木乘。患者形瘦神悴，性急劳伤酒色，吐血腹胀肠鸣，前医作阴虚、食积误治，更灸中脘、章门，复吐血。脉症合参，乃脾虚气弱、肝木乘土、气血两亏之候。", ["涩", "细", "弱", "弦"]], "15136": ["病机", "脉细而数有五至余，细为阴血亏少、脉道不充，数为虚火内扰、阴不制阳。患者形瘦色脆、咳血二年，前医滋阴清肺不效，反以温补去参致病情加重，说明此脉非实火，乃阴虚火旺、肺络受损之象。细数并见，正合虚劳咳血、阴亏火动之病机，故滋阴降火不应者，当责脾肾根本已虚。", ["细", "数"]], "15137": ["预后", "此段未出具体脉象，以《脉诀》四至五至为平和之则发问，答以经云五藏已衰、六府已极、九候须调犹死。结合肉脱热甚、嗽而加汗、下泄上喘、左不得眠肝胀、右不得眠肺胀等症，皆属死候。脉虽五至余而形症俱败，说明胃气已竭、藏府衰极，故断不可为，越五日果卒，属虚劳危候之预后判断。", []], "15138": ["病机", "脉皆缓弱，缓为脾土之本脉，弱为气血不足之象。患者年三十，过于勤劳而呕血，劳倦伤脾，脾不统血，血溢脉外故呕血。脉缓弱而非弦数，说明非肝火迫血，乃中气亏虚、统摄无权所致。此脉主脾虚气弱、血失所统之病机，与忧惶伤神、劳倦耗气之症相应，治当补脾益气以摄血。", ["缓", "弱"]], "15139": ["病机", "脉或前大后小，或驶或缓，或细或大，或弱或弦，并无常度，细缓弱时常多。脉无常度乃脾虚不能主运、五藏失禀之象；前大后小、乍大乍细，说明中气不足、脉道失于统摄。症见膈塞壅闷、咯红噎酸、便溏滑泄、口苦梦遗，皆脾伤食减、升降失司、湿热内蕴之候。此脉主脾虚为本、诸症丛生之病机。", ["大", "小", "细", "缓"]], "15140": ["病机", "此段未出具体脉象，承上文言脉之不常乃脾之虚也。五藏皆受气于脾，脾伤食减则五藏俱无所禀，故脉失常度。以参、术为君补脾，茯、芍为臣，陈皮、神曲、贝母为佐，甘草、黄柏为使，服之泻止食进，说明脉象不常之根源在脾虚失运，补脾则脉自复。此段主旨阐发脾虚致脉不常的病机及治法依据。", []], "15141": ["其他", "此段论命脉与修身养性之理，非具体诊脉病机。以烛在笼、火在灰为喻，说明人能远色节食、养性存心，使汗不妄泄、精不妄施，则可终其修短之数。脉和者，气血调畅、阴阳和平之象，然寿夭固有定命，不可委之于命而不修。此段主旨在于修身立命、静者寿动者夭，属养生保命之论，非主病之脉。", ["和"]], "15142": ["病机", "脉皆浮细，略弦而驶。浮为气虚外浮，细为血少脉道不充，弦为肝气郁急，驶为热象。患者性急叫号气喊，恼怒劳伤，秽气冲上则嗽极吐，甚则呕血，时发如疟。此脉主肝郁化火、气逆犯肺、脾虚血弱之病机。浮细示正气已虚，弦驶示肝火内动，故以疟、痰、气治皆不效，当责肝脾失调、虚实夹杂。", ["浮", "细", "弦", "驶"]], "15143": ["病机", "脉皆浮濡无力而缓，右手脾部濡弱颇弦。浮濡无力为气虚阳弱、卫外不固，缓为脾土之象，濡弱颇弦则脾虚而肝木乘之。患者咳嗽带红、饮食无味、易感风寒、行步喘促，皆脾肺气虚之候；夜梦纷纭、𤻊疝又示肝虚气陷。此脉主脾肺气虚、肝木乘脾之病机，故初服芩连四物清降俱效而久则不应，当补脾肺以固本。", ["浮", "濡", "缓", "弱"]], "15144": ["病机", "脉皆濡缓而弱，为气虚湿滞之象；独左关沉微、按之不应，左关虽属肝而主血，然概而论之两关俱主中焦而察脾胃，故左关沉微亦反映脾胃气虚。患者房劳后咳血、头眩脚弱、梦遗，看似血病，实因肾关失守、胃气伤而气壅逆，血随气逆而咳，梦遗亦由胃气不固，故脉象主气虚而非血实。", ["濡", "缓", "弱", "沉"]], "15145": ["病机", "原文未出脉象，以议论为主。指出“初病伤肾”，肾为胃之关，关失守则胃伤，气壅逆而咳血；又引“二阳之病发心脾”，肠胃病延及心脾，故梦遗由胃气不固。左关虽属肝主血，然两关俱主中焦察脾胃，故左关亦可察脾胃病。强调凭症凭脉凭形色，不可执一。", []], "15146": ["其他", "原文未出脉象，述右手三部脉皆隐而不见而身无病，属事之异，非病脉。作者借此质疑《太素》脉法片时诊候能知人终身祸福之说，认为非理。此段主旨不在论病机，而在讨论脉诊局限与异象，故归其他。", []], "15147": ["病机", "脉皆濡弱近驶，濡弱为气虚，近驶为虚火或气不敛。患者形瘦色悴，劳则咳血自汗痞满，早晨嗽甚吐痰如腐渣乳汁，乃脾胃气虚、运化失职、痰湿内蕴，虚火灼肺所致。前医以参苏饮、枳缩二陈汤发散破气，弥年弗效，正因未识气虚本虚，反伤正气。", ["濡", "弱"]], "15148": ["病机", "脉皆浮而近驶，浮为气虚阳浮或风邪在表，近驶为虚火。患者形色颇实，病嗽咯血而喘不能伏枕，似实而脉浮驶，说明气虚于内、虚阳上浮，肺失肃降。前医参苏饮、清肺饮不效，因未察脉浮驶属虚，反以清肺发散耗气，故病不愈。", ["浮"]], "15149": ["病机", "脉皆细濡而滑，细濡为气阴两虚，滑为痰湿内蕴。妇人年五十余，久嗽咯脓血，日轻夜重，乃肺脾两虚、痰湿郁而化热、灼伤肺络所致。细濡示正气已虚，滑示痰浊未清，故病久不愈，脓血与痰湿并见。", ["细", "濡", "滑"]], "15150": ["病机", "右脉洪缓无力，左脉缓小而弱，皆气虚之象。右脉洪缓无力为脾胃气虚、虚阳外浮；左脉缓小而弱为气血不足。患者冬月感寒咳嗽痰血，前医发散伤阳，又用四物加柏知寒凉降下，致身热自汗、胸膈痞闷、便泻食少，皆气虚阳陷、脾胃受损之候。", ["洪", "缓", "小", "弱"]], "15151": ["病机", "脉皆缓弱，缓弱无力为气虚之确证。患者痰红咯黑，形色近黑似实，然丹溪云脉缓无力者气虚也。前医作伤寒发散、用寒凉降下，阳气几稀。今脉缓弱，故知气虚，宜温补升举，用参芪等百帖而安，说明凭脉辨虚、不可惑于形色。", ["缓", "弱"]], "15152": ["病机", "脉细濡近驶，细濡为阴血亏虚、濡湿内蕴，驶即数急，示虚火内动。症见咳嗽咯血、声哑、夜热自汗，皆肺阴亏耗、虚热灼津之象。脉细濡近驶正合阴虚火旺、肺失濡养之病机，故主虚劳肺损。", ["细", "濡", "驶"]], "15153": ["病机", "脉皆缓弱，无复驶象，缓弱为脾胃气虚、湿浊内困。症见胸腹痞满、恶心畏食、粪溏，皆脾失健运、升降失常所致。前段脉驶为虚火，今转缓弱，示火退而脾虚湿困之机转，故主脾胃虚弱、湿滞中焦。", ["缓", "弱"]], "15154": ["病机", "脉细濡无力约七至，细濡为阴血不足，无力为气虚，七至为虚数。症见怠惰嗜卧、食后腹痛多痰、吐酸水、声哑、粪溏、肛疖溃脓，皆脾肺气虚、湿痰内阻、虚火下陷。脉病不应，正示虚损日久、气血双亏、湿热下注成瘘之危候。", ["细", "濡", "无力"]], "15155": ["预后", "数脉主热，今不觉热，乃内蒸骨髓或正气已极不能作热。虚劳粪门生疖必成瘘疮，脉不数尚不可为，况脉热乎！肺与大肠相通，肺气久伤下陷肛门生疖瘘，肺伤极矣，非药能济。此段以数脉辨虚劳内热燔灼、肺气下陷之死候，故主预后不良。", ["数"]], "15156": ["病机", "脉皆细弱而缓，右脉尤弱，细弱为气血亏虚，缓为脾虚湿滞，右脉尤弱示脾肺气虚更甚。症见消渴善饥脚弱、冬不寒、小便白浊如油，乃脾虚不能运化水谷、肾虚不能固摄脂液，虚火浮越所致。故主脾肾气阴两虚、膏淋消渴之病机。", ["细", "弱", "缓"]], "15157": ["病机", "左脉沉弱、右脉浮虚颇弦，左沉弱为血虚气陷，右浮虚为脾肺气虚，弦为土虚木乘。症见伤饥雨湿、食冷呕吐、胃脘痛、吐瘀血、便溏、惊惕，皆脾胃虚寒、肝气犯胃、气不摄血。脉象示中虚木乘、气血失和之病机。", ["沉", "弱", "浮", "虚"]], "15158": ["病机", "午间脉皆洪滑，洪为阳热亢盛，滑为痰湿内壅。症见大热膈闷、梦遗盗汗、午后热甚，因劳伤酒肉，湿热痰火内蕴，故脉洪滑。此脉主痰热内盛、食积化火之病机，非阴虚也。", ["洪", "滑"]], "15159": ["病机", "来早再诊脉皆收敛而弱，右脉尤弱，收敛示热退，弱为气虚，右尤弱主脾肺不足。前洪滑为食饱暂象，今弱为本质，故以参芪术补气，麦冬知母清余热，山楂枳实消导。脉弱主脾肺气虚、余热未清之病机，故用补消兼施。", ["弱", "收", "敛"]], "15160": ["病机", "脉皆浮弦细弱，浮为气虚外浮，弦为气郁不舒，细弱为气血两虚。患者形瘦淡紫、气壅腹痛背胀而吐、腹中气块翻动，是脾虚气滞、肝木乘土之象；吐黑水酸气、嗳气不食、便难溺少，皆中虚运化失职、气机升降乖违所致。脉与症合，主脾虚气郁、气血不足之病机。", ["浮", "弦", "细", "弱"]], "15161": ["病机", "左脉小弱而数、右脉散弱而数，俱近六至。数而无力为虚热，小弱散弱为气血亏耗。症见食后吐酸、结痰注胸、劳则头晕鼻衄、粪后红黑、盗汗梦遗脚冷，是脾虚湿郁化热、阴血不足而虚火上炎。脉数非实热，乃虚损之候，主脾虚阴亏、湿热内郁之病机。", ["小", "弱", "数", "散"]], "15162": ["病机", "原文直言“症脉皆属阴虚”，然滋阴降火不效，指出此非单纯阴虚，乃“脾虚湿郁为热而然”。滋阴反滋湿生热，故宜参、耆甘温补脾去湿。此段从脉症合参辨明病机本质在脾虚湿郁，非阴虚火旺，属病机辨析之论，脉象为纯描述故不取要素。", []], "15163": ["治法", "引《脉经》“数脉所主，其邪为热，其疟为虚”，说明数脉虽主热，亦有因虚而数者，不可执丹溪“脉数禁参耆”为定论。本案以参、耆甘温补虚为主，佐黄芩、黄柏清余热，服之而愈。段旨在示人脉数当辨虚实、治法须知变通，故归治法。", ["数"]], "15164": ["病机", "脉皆濡弱而缓，右脉略大尤弱，濡缓为湿，弱为脾虚，右脉主脾，尤弱则脾损明矣。患者幼时误服毒药泄痢，复伤食腹痛大泄，虽能食不作肌肤，善饥多食、胸膈似冷、夜间发热、盗汗阳举、惊悸喉痰，皆脾虚湿郁、肾精不固之象。次日左脉三五不调，为欲动淫精之兆。", ["濡", "弱", "缓", "大"]], "15165": ["病机", "原文点明“左脉不调者，此必欲动淫其精也；右脉尤弱者，由于毒药损其脾也”。左脉不调主肾精欲动，右脉尤弱主脾为毒药所损，故立“固肾养脾”之法，以参、术、苓、芪补脾，归、芍、麦冬、知母、黄柏养阴固肾。此段据脉定位，辨脾肾两虚之病机。", ["弱"]], "15166": ["病机", "脉皆洪数，洪为邪盛，数为热炽。患者年五十余，冒雨劳役受饥、争辩动气、兼有内事，夜半发热恶食、上吐下泻、昏闷烦躁、头痛身痛，因自汗汗遂不止。此表里俱伤、正虚邪盛、虚阳外浮之危候，洪数之脉与吐泻汗多并见，示正气溃散而邪热未解。", ["洪", "数"]], "15167": ["预后", "“脉果洪数，乃危症矣”，因吐泻内虚、汗多表虚，而脉不为汗衰、不为泻减，正虚邪盛，故在法不治。然仍以参、芪救里表，术、姜、草和中安胃，苓、陈理气，勉力施治。此段以脉断预后凶险，属死证危候之判，故归预后。", ["洪", "数"]], "15168": ["主病", "患者形短苍白、善饮，忽发寒热，医作疟治而躁渴益甚，呕吐痰多，头晕昏闷，两关脉浮洪，后脉皆浮洪近数。浮洪为阳热外盛之象，数则热势更急，结合渴甚、便不通、夜梦不安，似属热盛津伤、痰热内扰之证，然原文未断，仅述脉症，故主病机为热盛痰阻、津液受伤。", ["浮", "洪", "数"]], "15169": ["病机", "原文明言“脉洪者，阴虚阳无所附，孤阳将欲飞越，故脉见此，其病属虚，非属热也”。年逾六十，血气已衰，疟药燥烈，壮火食气，致胃虚津少而渴甚。洪脉在此非实热，乃虚阳外浮之象。服参、耆、归、麦等补益后，脉转收敛而缓，非复鼓击而驶，证明洪为虚阳鼓动，缓为胃气来复。", ["洪", "缓"]], "15170": ["病机", "患者形瘦苍白，食则胸膈痞闷，汗多，四肢倦怠或麻，晚食迟则晨泄。脉浮软近驶，两关略大。浮软为脾虚气弱、卫外不固之象；驶为虚而偏数，关脉略大乃脾虚不运、气机壅滞所致。结合汗多、倦怠、晨泄，显系脾虚不足，运化失职，非实邪为患。", ["浮", "软", "驶", "大"]], "15171": ["病机", "前服参术膏而痞闷，改汤剂后胸痞失气，去枳实加陈皮再服，顿觉胸痞宽、精神爽恺，脉皆软缓，不大亦不驶。软缓为脾胃虚弱、气血不足之常脉，非病脉之凶。原文以脉之由略大近驶转为软缓，说明脾胃渐复，气机得畅，故断为脾虚不足，用药宜健脾益气、行气导滞。", ["软", "缓"]], "15172": ["主病", "妇年五十七，因劳夜卧受热，遍身胀痛，胸膈胀痛，咳嗽气壅，吐痰腥臭，自汗浮肿，又作泄，肛门胀急。医谓脉洪数。洪数为热盛之脉，结合咳吐腥臭痰、胸痛、浮肿，似属热毒壅肺、痰热内蕴之证，然原文仅引医言，未加断语，故列为主病脉象，提示热盛痰壅之病机。", ["洪", "数"]], "15173": ["预后", "原文指出“脉洪数，乃热伤元气而然，非热脉也”，年逾五十，血气已衰，酷热劳倦，壮火食气，故脉洪数。所虑者“脉不为汗衰，为泄减耳”，即汗出而脉不衰、泄而脉不减，为正不胜邪之兆。后虽用参、耆、术、苓等补益，脉与病反，终至不救，说明洪数在此为元气耗伤、邪热鸱张之危候。", ["洪", "数"]], "15174": ["病机", "妇年逾三十，形色脆白，久病虚弱。初诊左脉似有似无，右脉浮濡无力；越三日再诊，两手脉皆浮濡，左则不似有似无，右则略近于驶。浮濡为气血虚衰、脉道不充之象，左脉似有似无乃虚极之候。原文强调“脉变不常，昨今异状者，由虚而然也”，说明久病虚弱，脉随气血波动，非一时可定。", ["浮", "濡"]], "15175": ["病机", "右脉濡散，无力而缓，左脉比右颇胜，亦近无力。患者十五年前哭子忒甚，忧思伤脾，哭泣伤气。濡散无力而缓，为脾肺气虚、脉道不充之象；左脉稍胜亦近无力，示气血俱虚而偏于右关脾肺。原文从东垣劳倦伤脾之例，用参、耆、术、芍等补益而愈，证明濡散缓主气虚不足，非实邪之脉。", ["濡", "散", "缓"]], "15176": ["病机", "脉皆濡缓而弱，濡主湿、缓主虚、弱主气血不足。患者色苍黄瘦，久服轻粉致脚拘挛、指节肿、额前肿如鸡卵，乃药毒伤正、脾虚湿滞、气血亏虚之候。脉弱示正气已衰，濡缓示湿浊内停，故非实热疮毒，乃虚中夹湿、毒损筋骨之病机。", ["濡", "缓", "弱"]], "15177": ["病机", "脉皆浮濡近驶，浮为虚阳外浮，濡为湿困，驶示虚数。因服轻粉致痞块、眼丁，又误用硝黄攻克及寒凉，反加腹痛肠鸣、滑泄、胸膈壅闷、身热怠倦，乃脾胃虚寒、湿浊内壅、虚阳上浮之机。脉浮濡近驶正合虚湿内盛、阳气不潜之候。", ["浮", "濡", "驶"]], "15178": ["兼症", "左脉浮滑，右脉稍弱而滑。浮滑主痰热壅肺，弱示正气稍虚。患者妊兼肺痈，吐痰咯脓，故以左脉验之，恐妊兼肺痈。浮滑为肺中痰热之象，弱滑示脾虚湿痰。清肺泻肺后痰脓减，惟恶阻时作，乃妊之常病，脉象与痰热壅肺、妊娠并见相应。", ["浮", "滑", "弱"]], "15179": ["预后", "脉皆稍缓而浮，缓为胃气渐复，浮示余热未清。前热已减，但吐红太多伤胃，故脉缓浮而非数急。后妊六月食鸡病作，九月声哑，产后脾胃病作加泄而卒。脉由浮滑转缓浮，示热减而胃伤，终至脾胃虚败，脉象变化与病情转归相应，属预后判断。", ["缓", "浮"]], "15180": ["病机", "脉皆濡弱近驶，两尺稍滑。濡弱主脾虚湿盛、气血不足，驶示虚数，尺滑主下焦湿浊或血分有热。妇瘦长面紫，春末夏初两脚生疮、脓泡根红、经水不调，乃脾虚湿注下焦、血分郁热之机。濡弱近驶示正虚湿滞，尺滑示湿浊下注，与脚疮、经不调相应。", ["濡", "弱", "驶", "滑"]], "15181": ["病机", "脉皆濡弱，濡主湿、弱主气血虚。年近六十，长瘦色苍，背腿痈肿此起彼伏，俗名流注。医欲用十宣散、五香汤、托里散，皆攻散之剂。脉濡弱示正气已虚、湿毒留滞，非实热壅盛，故痈肿续发乃虚中夹湿、托毒无力之病机，不宜峻攻。", ["濡", "弱"]], "15182": ["误治", "脉皆濡缓而弱略驶，濡缓主湿、弱主虚、驶示虚数。因劳感湿，腿胯结核痛，医用艾灸、针刺、药洗，致阴囊肿胀如升、茎皮肿如水泡，复进人参败毒散不中。脉濡缓弱驶示脾虚湿盛、正气不足，误用针灸洗散反伤正气、湿浊下注，乃误治致变之候。", ["濡", "缓", "弱", "驶"]], "15183": ["病机", "脉皆濡缓，濡主湿、缓主脾虚。六岁儿阴囊胀大如盏、茎皮光肿如泡，医渗湿行气不效。脉濡缓示脾虚湿盛、水湿下注，非单纯气滞。脾虚不能运化水湿，湿浊下注阴囊，故肿胀如泡。脉象与脾虚湿注之病机相应，渗湿行气未效因未培脾土。", ["濡", "缓"]], "15184": ["病机", "脉缓无力，缓为胃气本象，无力则示正气不足，故断为气虚。气虚则膀胱气化无力，津液不能运化而出，致囊皱肿满。经云“膀胱者，津液之府，气化出焉”，正合此机。治以升阳补气，使气旺则运化复常，肿消病愈。", ["缓", "虚"]], "15185": ["兼症", "脉细濡近滑，细濡为血虚湿滞之象，滑为经水将行之候；两尺重按略洪而滑，尺主下焦，洪滑示冲任气血壅盛。合经水紫色、先后不定、临行腹痛恶寒，乃血虚夹湿、冲任失调，故脉见细濡滑而尺部偏洪。", ["细", "濡", "滑", "洪"]], "15186": ["病机", "原文虽未载脉，然据所示症候，断为脾胃不足。脾胃为气血生化之源，虚则运化失职，故见红白带下诸症。以四君子汤补脾，加黄芩清湿热、陈皮神曲理气消滞、归身养血，药后红止白减，继服诸症悉除，印证脾胃不足之病机。", []], "15187": ["病机", "脉皆濡弱，濡为湿象，弱为气虚，合之则脾虚湿盛。脾属血属湿，经水将动时脾血先注血海，脾血亏虚则不能运行其湿，湿浊下流而为经行泄泻。故用参苓白术散健脾渗湿，使脾运复常，则经行不泻。", ["濡", "弱"]], "15188": ["病机", "右脉濡弱无力，右主气，濡弱为脾胃气虚；左脉略洪而驶，左主血，洪驶为血分有热。产后经行不止八月，气血两伤，脾虚不能统血，兼血分伏热，故红白淡杂下。前医补气益加、止涩无效，正因未清血热。", ["濡", "弱", "洪", "驶"]], "15189": ["病机", "右脉弱者，非真病也，因左脉偏盛，相较而觉右弱耳。左脉主血，偏盛则血分有热，故宜主左脉，治以凉血之剂。方用生地、白芍、黄芩、阿胶等凉血养血，佐以理气，使血热得清，则脉自平，崩漏自愈。", ["弱"]], "15190": ["病机", "右脉浮软颇大，浮软为气虚，颇大示虚而无力；左脉软小而缓，左尺尤近微弱，为血虚不足。患者孀居劳倦、食少，年五十二，天癸将竭，气血俱亏，脾不统血，故血崩。苦寒凉血益剧，胶艾少愈，正虚不受攻伐。", ["浮", "软", "大", "小"]], "15191": ["病机", "左脉主血，得软小与血崩相应；右脉主气，诊得浮软，为脾胃气不足。脾虚不能健运其血，胃虚不能升举其血，以致血崩。经曰“阳病竭而下者”，正谓阳气虚陷。法当治阳，补气升举，使血气各守其乡，则崩自止。", ["浮", "软"]], "15192": ["病机", "脉沉细而数，沉细为虚，数为热，然此热非实热，乃久服前药失于加减，藏府习熟，病反化于药，故症反觉虚。数脉所主为热，其症为虚，说明热由药毒所化，正气已伤，脉症不符，故令暂止药以观其变。", ["沉", "细", "数"]], "15193": ["预后", "血崩大下，昏懵气息奄奄，脉仍沉细而数，沉细为血气大脱，数为虚热外浮。五十以后血气大脱，实难求生，脉数略减则虚热稍退，头痛昏弱腰脚痛愈，但小腹微痛清水常流，乃冲任虚损不能约制，阳虚水泛之候。", ["沉", "细", "数"]], "15194": ["病机", "冲脉为经脉之海，阳明虚则冲脉失养，不能渗灌，气化为水而下流，故清水常流不绝。遇严寒小腹腰脚腿痛，由阳虚不御其寒。血气虚脱，来春无以资生发之气，果洞泻而殁，说明胃气衰败、冲任虚极，水湿不化，预后不良。", []], "15195": ["治法", "血病而治以参、耆，似犯丹溪血病补气之戒，然冲任气虚不能约制其血，故忽大下谓之崩中。治宜举养脾胃，大补气血，血脱益气，先理其胃以助生发之气，甘能生血，阳生阴长，纳谷为宝，此古圣人之法，非执泥可论。", []], "15196": ["兼症", "右脉浮软而大，左脉虚软而小近驶，浮软大属气虚湿盛，虚软小驶为血虚有热。经前作泄、经水过多、白带时下、泄泻无时，皆属下多亡阴，血虚论治。然服四物止痛益甚，说明病本在气虚湿滞，非纯血虚，故补血反滞。", ["浮", "软", "大", "虚"]], "15197": ["病机", "脉细软而驶，尺沉弱近驶，细软属湿，数则为热，尺沉属郁，此湿热郁滞也。经行腹痛如刮，难忍求死，乃湿热郁阻胞宫，气血不通。酒煮黄连清湿热，香附五灵脂归尾行气活血，服之得子，说明湿热郁滞为病本。", ["细", "软", "驶", "沉"]], "15198": ["妇人", "产后年余经水不通，呕吐手指麻痹挛拳，声音哑小哕不出声，医视为风病。脉皆细微近滑，细微为气血虚，滑为妊娠之象。此妊娠恶阻病也，非风非闭，乃血虚气弱、胎气上逆所致，故以四君子加二陈治之。", ["微", "细", "滑"]], "15199": ["妇人", "众谓经水不通安有妊理，然脉虽细微似近于滑，又尺按不绝，乃妊娠也。细微为气血不足，滑为胎孕之脉，尺按不绝为胎气未散。天下之事有常有变，此乃事之变，故以四君子加二陈治之，诸症俱减，说明妊娠恶阻当以养胃化痰为治。", ["微", "细", "滑"]], "15200": ["其他", "原文仅言“出部脉”，未描述具体脉象特征，故脉象要素为空。此段主旨在于讨论脉位异常（脉出部）的现象，而非具体病机或主病，故归为其他。原文未提供可分析的脉象与病机关系。", []], "15201": ["妇人", "原文载妇人两手脉皆不应，惟右关轻按隐隐然微觉动，寻按经渠列缺亦不应，后知有孕易产。此属禀赋脉不应，非病脉，故脉象要素为空。主旨言妇人脉异常与胎妊关系，归为妇人。", []], "15202": ["病机", "右脉缓濡而弱，缓濡弱主脾胃气虚，运化无力，故见食少懒倦；左手无脉，脉动于腕臂外廉阳谿偏历之分，属脉离部位，难以脉知。以右脉言，似属脾胃不足，兼经前咯血、心嘈，为脾虚兼热，故以四君子汤加山栀、丹皮等而安。", ["缓", "濡", "弱"]], "15203": ["其他", "原文述脉出部现象，或左或右，或两手俱出部，非具体脉象描述，故脉象要素为空。主旨讨论脉位异常由禀赋所致，非经水之病因，属脉学变例，归为其他。", []], "15204": ["病机", "脉稍洪近驶，洪为气分热盛，驶为热迫脉行急。妊妇八月腰痛便燥，前医补之痛益加，通之燥结行而痛如故，此非纯虚纯实，乃热郁气滞、津亏肠燥，脉洪驶示热象，故补通皆不效。", ["洪", "驶"]], "15205": ["病机", "脉皆细濡颇弦，细濡主气血两虚，弦主热、主肝火。屡患横生逆产、子皆不育，因气血虚兼热，胎失所养而产难。原文直断“此气血两虚兼热也”，脉细濡为虚，弦为热，故主此病机。", ["细", "濡", "弦"]], "15206": ["病机", "形长瘦而脉细濡，属气血两虚；色青脉弦，属肝火时炽；两尺浮滑，示血虚为轻、气虚为重。细濡主虚，弦主肝火，滑主血虚有热。故以补阴丸加参、耆、香附等补气养血，逾年顺产。", ["细", "濡", "弦", "滑"]], "15207": ["病机", "产后滑泄，勺水粒米不容，脉皆濡缓而弱。濡缓弱主脾胃气虚，运化失司，故滑泄不禁；前用五苓、平胃渗利燥湿，更伤脾气，病益甚。脉证合参，此属产后脾虚不运，非湿滞实证。", ["濡", "缓", "弱"]], "15208": ["病机", "产后昏瞀、身热汗多、眩晕口渴，脉浮洪搏指，为阳热亢盛之象。前医误用四物凉血、小柴胡，病益甚，说明非血虚发热，而是热邪内盛，气血壅沸，故脉浮洪搏指。浮为热越于外，洪为火盛于内，搏指则邪实有力，主实热病机。", ["浮", "洪"]], "15209": ["预后", "产后汗多而脉不为汗衰，反浮洪搏指，是邪热不为汗解，正气已伤而邪势仍盛，故法在不治。所幸气不喘、不作泄，说明脾胃未败，尚可救治。脉象如是，恐为凉药所激，致虚阳外浮。后以甘温益气之剂，脉敛病安，反证前脉为药误所致。", []], "15210": ["病机", "六岁女童左手不能举动三年，后病痫，左脉浮洪，右脉颇和。左脉候血候肝，浮洪为风火痰热壅盛于经络，肝风内动，筋脉失养，故肢废而痫作。右脉和，说明病未及气分，主在血分肝经。浮洪为阳盛，风火相煽，故见痫证。", ["浮", "洪"]], "15211": ["病机", "本段论冲任血海与阳明胃脉关系。劳损冲任，血不渗灌而越上，致阳明胃脉失养，见饮食无味、恶心呕吐、胸膈痞闷等症。初因阴虚而终致阳虚，故滋阴降火难用，当从东垣阳生阴长，用甘温之剂。脉象未明，但病机为阴虚及阳、胃阳亏虚，心神肝筋失养。", []], "15212": ["病机", "脉皆细驶，右大于左，脾脉弦滑，右脉细数，为酒肉积热伤脾，痰热内蕴之象。细驶为阴伤热伏，弦滑为痰饮内停，右大于左示病在脾胃。虽下之而痛不减，后脉隐不见、四肢逆冷、烦躁汗出，是壮火食气、热深厥深，非阴症，乃热厥之候。", ["细", "驶", "弦", "滑"]], "15213": ["病机", "脉皆细数，面色近赤，酒后病作，为热邪内盛。六脉虽绝，四肢逆冷，乃壮火食气，气不能营于四肢，故脉绝而逆冷，属热厥而非寒厥。细数为阴虚热伏，绝为热极似寒。仲景谓热厥者多，急用大承气下之，不可用四逆汤助火添病。", ["细", "数"]], "15214": ["预后", "连进温补，脉仍不应，逆冷不回，渴饮烦躁，小便不通，粪溏反频，是热耗津液、阳气不固。更进人参白虎汤，脉渐隐隐见如蛛丝，为胃气渐复之兆。仲景论绝脉服药微续者生，脉暴出者死，此脉微续如蛛丝，故曰有生意，预后可期。", ["微", "细"]], "15215": ["病机", "小便不利、烦渴未除，由内热耗津液；大便尚溏，由内热损阳气，阳气不固。脉象未载，但症见逆冷、脉伏，为热厥后期气阴两伤。用参、术、茯苓、门冬、五味等益气养阴，至第九日逆冷回，脉复见，诸症减，说明气阴渐复，病向安。", []], "15216": ["病机", "左脉沉弱而缓，右脉浮软无力，续诊心肺脉浮虚按不应指，脾脉轻按阁指重按不足，脉变动无定准。此皆气血虚衰之象：沉弱缓为气虚阳弱，浮软无力为血虚不充，脉无定准乃血气虚极、正气不守。故见声哑、不寐、口苦舌干、畏寒、疝痔遇劳而发等症，总属气虚劳伤、脾肺两损。", ["沉", "弱", "缓", "虚"]], "15217": ["病机", "原文谓“夫脉不常，血气虚也”，以虚伪之人朝更夕改喻脉无定准，的实之人朝斯夕斯喻脉常久不移。脉不常即气血虚极之征，虚属气虚为重。劳则气耗肺伤而声哑，脾伤食积，气虚下陷则疝痔遇劳而发；寒凉药复伤脾肺，故舌胎、不寐、痰血、胸痛嗳气，皆气虚不运、脾不裹血所致。", []], "15218": ["病机", "脉皆浮虚洪数，不任寻按，坐起略小，此虚热之象。脉书谓数脉所主为热，其症为虚。浮洪数似热，然不任寻按、坐起则小，正见中气不足、虚阳外浮。三日后左脉小而滑、右脉大而滑，独肺部浮软按之蛰蛰有声，脉象变动不常，皆虚之故，非实热可比。", ["浮", "虚", "洪", "数"]], "15219": ["病机", "原文未出具体脉象，以“阳气者清纯冲和之气”立论。劳动过度或酒食过伤，扰动其阳，变而为邪热；脾胃以阳气为主，阳变为热则血沸腾越上，故昏晕类风、下焦热上、胸膈壅塞。脾脉从足入腹至胸，脾火循经上扰，心肺之神魄昏乱，五藏失胃气所养而神志躁扰，总属阳气扰动、邪热伤中之病机。", []], "15220": ["病机", "左脉浮虚而缓，右脉浮弦而缓，此阳虚也。浮虚缓为阳气不足、鼓动无力；右脉浮弦缓，弦为虚风内动、缓为脾阳不振。虽见易饥善食、梦遗甚频似阴虚，然两足时冷、身多恶寒、日见消瘦，实由伤寒过汗亡阳，阳虚不能温煦，故断为阳虚而非阴虚。", ["浮", "虚", "缓", "弦"]], "15221": ["病机", "脉皆浮虚弦缓，浮虚为阳虚外浮，弦缓为阳气不足、脾土失温。古人谓脉缓而无力者阳虚也，今脉不数而缓，且参症两足时冷、身多畏寒，皆阳虚之验。易饥善食非阴虚火动，乃脾胃阳虚无以运化，借谷气自救；汗多亡阳，苦寒泻阳，阳愈虚而内空竭，故食不生肌。", ["浮", "虚", "弦", "缓"]], "15222": ["病机", "左手心脉浮小而驶，肝肾沉小而驶，右脉皆虚散而数。浮小驶数似热，然虚散不敛，乃正气不足、虚阳躁动之象。原文恐其乘舆远来、脉未定耳，来早脉稍敛不及五至，非比日前甚数，可见数非实热，乃虚而失守、脉无根蒂之候，主气血虚衰。", ["浮", "小", "虚", "数"]], "15223": ["病机", "原文未出脉象，以经络气血立论。头左及耳前后属少阳，少阳多气少血，风药痰药皆燥，燥之则血愈虚少，血少则涩滞壅肿；复以寒剂凝之，血逢冷则凝，郁而为热，腐肉成脓。久则气血已虚，年六十血气日涸，劳伤及燥剂、脓泄更竭气血，故虚而又虚，当以滋养气血为治。", []], "15224": ["病机", "原文谓脉皆微弱、似有似无，又见一二至一止或三五至一止，显系阳气大虚、鼓动无力，故脉道不充而微弱，气血不能接续而见止歇。断为阳气大虚，与独参补气而愈相合，主虚证、阳气衰微之病机。", ["微", "弱", "结", "代"]], "15225": ["病机", "原文分述心脉浮数而滑、肾肝沉弱颇缓、肺脉浮虚而驶、脾脉偏弦而驶、命门散弱而驶，次日又见细软、过弱、浮软、颇软、略坚。诸脏脉象不一，反映气血两虚、脏腑失调，虚而兼驶为虚阳躁动，弦为脾虚木乘，软弱为气衰，故属病机分析。", ["浮", "数", "滑", "沉"]], "15226": ["病机", "原文未明指脉名，仅言脉时或变易不常，归因于气血两虚。论淋由气馁不能运化、津液郁结为热，嗽由肺虚脾弱、脾肺之气不能荣养皮肉，又因服寒凉伤脾肺致腹胀作痛、胁气触上。脉象无常正是气血两虚、脾肺受损之征，故属病机。", []], "15227": ["病机", "原文言脉与前颇同，但不数不驶而已。前诊脉见浮数而驶、弦驶等，今数驶已去，说明虚阳躁动之势渐平，气血渐复，故仍用参、耆补气，麦冬、归身养阴，厚朴、枳实、黄芩调畅。脉不数不驶为病机向缓之象，属病机分析。", ["数", "驶"]], "15228": ["平脉", "原文以喜者少病、百脉舒和之故作结，说明情志调畅则气血和利、脉道舒和，属平脉之论。文中列举悲治怒、喜治悲、恐治喜等情志相胜之法，及热治寒、寒治热、逸治劳、习治惊，皆言治法，而脉舒和一句点出平和之脉，故归平脉。", ["和平"]], "15229": ["其他", "原文未载具体脉象，仅言庄医切脉后失声、佯称取药而遁，以惧胜喜之法愈其喜病。此段重在情志相胜治验，脉象无征，故脉象要素为空。所论非脉主病机，亦非平脉死脉，属情志疗法之其他类。", []], "15230": ["其他", "原文仅言一医至、脉已，未述具体脉象，随即以指计甲子预言天雨，贵人喜而起行，疾若脱去。此段记情志愈疾之验，脉象无具体描述，故脉象要素为空。主旨不在脉主病机，而属情志治病之其他类。", []], "15231": ["其他", "原文仅存一脉字，后文尽佚，无脉象描述、无病机症候可据。既不能定脉象要素，亦无从判其主病或病机，仅可识其为论脉之残段，故脉象要素为空，类别暂归其他，俟原篇补全再议。", []], "15232": ["病机", "原文言积热之久而脉反沉细、外症又寒，是热郁于内、阳气不能外达，脉与症相反，故曰难求。沉细为气血内敛、阳郁不伸之象，非真寒可比。作者强调须兼望闻问切，正因脉症相违易致误诊，此段主旨在于脉症合参以辨真假寒热之病机。", ["沉", "细"]], "15233": ["病机", "原文未明写脉象，仅言脉之始知为亡阳症。患者口唇舌疮、白带如注、凉剂则下疾愈甚、热剂则热晕欲绝，是阳浮于上、虚寒在下之亡阳格局。上热为假，下寒为真，故以附子为君温阳，佐薄荷防风引药上行，冷服以顺其势，此段重在辨亡阳之病机而非脉形。", []], "15234": ["病机", "脉初皆细软而缓，细软为血虚筋失所养，缓属脾胃虚弱。原文以过汗亡血、筋失所养释筋急痛，以细流浅濑壅阻释腿骹肿，又言脾胃太虚、呕逆嗳气、饮食少进，复加灸砭焦骨伤筋耗血。脉之细软缓正合血虚脾弱、筋脉失养之痿痛病机。", ["细", "软", "缓"]], "15235": ["病机", "再诊脉变为滑数，原文引脉书言疮科滑脉未溃宜内消、已溃宜补益，又言数脉所主为热、其症为虚，故断为脉与症皆属于虚。滑数本主热，然此处由误灸凉剂、胃气不能回所致，是虚中夹热之象，须大补托而出之，不可歧为两途，此段辨疑似之病机。", ["滑", "数"]], "15236": ["病机", "原文未载脉象，纯以症推病机。儿本气怯，暑月过劳，劳则气耗、劳倦伤脾，故身热、头痛、吐泻、目闭、咽哑。作者以阳气烦劳则张释身热，以清浊升降失常释吐泻，以脾络失养释咽哑，归结为伤脾之病，五藏皆失所养，全段主论劳倦伤脾之病机。", []], "15237": ["预后", "脉皆浮缓、不及四至，浮缓为脾胃气虚、阳气未复之象，四至以下示脉率偏迟、正气尚弱。原文言药病相宜、可减附子，渐次苏醒，是脉症相符、预后向善之征。前医作风热惊痰误用损胃之剂，今得生实赖知医，此段以脉测预后，主在判断病情转归。", ["浮", "缓"]], "15238": ["主病", "脉虚小而数，虚小为气血不足、正气亏虚，数为阴虚内热或虚阳浮动。产后咳嗽痰臭、两脚渐肿至膝、便溏腹胀、午后发热面红气促，是产后气血大虚、虚热上浮、水湿下注之候。脉虚小数为虚损夹热之象，非实热肺痈可比，故前治愈剧，此段以脉主虚损之病。", ["虚", "小", "数"]], "15239": ["主病", "脉细弱而缓，细弱为气血两虚，缓为脾胃气弱、病势尚缓。原文言此妇患咳嗽痰臭类肺痈，前医以百合煎汤煮粥反剧，今脉细弱而缓，治以参、芪甘温二三帖而愈，是因治之早。细弱缓之脉示虚证未深，甘温补气正合病机，此段以脉定虚证之主病与治法方向。", ["细", "弱", "缓"]], "15240": ["主病", "左脉浮洪虚豁而数，右脉虚小散数，为劳后入房感风，正气已虚而邪热内扰。浮洪为风热外扬，虚豁散数为气阴两伤。症见自汗、寒少热多、头眩耳鸣、四肢懒倦、手足麻、便溏、疟母、梦遗，皆脾虚气弱、虚火内动之象，脉症相合，主虚人疟疾。", ["浮", "洪", "虚", "数"]], "15241": ["预后", "前用大剂参、耆、归、术等补气养阴，初服痞块反高、小腹胀痛，乃药力攻邪之瞑眩反应。继服数帖后脉皆稍静不数，说明虚火渐平、气阴来复，数脉得减为向愈之兆，故列预后。", ["静", "数"]], "15242": ["病机", "此段以脉平而病不减为引，阐明疟邪深伏、非旦夕可解，须久服待春分阳气发扬。原文论疟因感风暑寒水而作，气属阳、血属阴，阳邪中气、阴邪中血，故有先寒后热、先热后寒及热多寒少之别，悍卫之气运行不息则不受邪，全段重在发挥疟疾气血受邪之病机。", []], "15243": ["主病", "脉虚而数，为劳心思虑、梦遗吐血后阴精亏耗、虚火内炽之象。虚为气阴不足，数为火动。症见畏风寒、呕恶倦动、粪溏、气促，乃脾肺气虚、虚火上炎，金虚不能平木，木火凌脾所致，主虚劳兼感之候。", ["虚", "数"]], "15244": ["病机", "此段无脉名，专论病机。劳思则神志不宁而梦遗，水不升则心火独亢，引动龙雷之火载血上窍；火胜金则肺虚干咳、发疹，金虚不能平木则木火凌脾，呕恶食减，壮火食气故倦动易感风寒，两胁为阴阳往来之路，火扰则痛，全属火亢金虚木旺之机。", []], "15245": ["预后", "用参、耆、白术、麦门冬等补气养阴，佐干姜、山楂、神曲、贝母，服十余帖后脉数减、咳少除、精神稍健。数脉为虚火之征，数减则火渐降、气阴渐复，故为向愈之预后。", ["数"]], "15246": ["预后", "原文反复言数脉属火，咳而脉数乃火克金，冬月水旺反见数脉为违时。大凡病见数脉多难治疗，病久脉数尤非所宜，又适新婚耗损真阴，无以制虚妄之火，故深为之虑，全段以数脉判断病情深重、预后不良。", ["数"]], "15247": ["主病", "右脉浮大弦数，左脉稍敛而数，热来左右皆大而数，寒来沉微似有似无。浮大弦数为气火郁勃、木旺克土，沉微为阳衰寒战。症见寒热、咳痰、战栗、肌肉瘦削、月水不通、食少恶心，乃肝脾失调、气血壅滞、虚实错杂之候，主痼疾重症。", ["浮", "大", "弦", "数"]], "15248": ["病机", "脉浮为虚，大则病进，大如葱管主大虚；弦脉属木见于右手，为肝木克脾土；数脉主热，甚则为虚。诸脉合参，示胃气本弱、脾虚不运，故胃脘痛、泄泻不禁、小便难独行，兼寒热互发，总由气血少而滞，阳虚不固。", ["浮", "大", "弦", "数"]], "15249": ["其他", "此段述汪居士行医声名及《石山医按》成书经过，未及具体脉象与病机。文中“脉色及方症”仅泛言记录内容，非论脉主病，故脉象要素从缺，主旨属医案传记类其他。", []], "15250": ["病机", "脉浮小濡缓，浮为虚，小濡缓为脾虚气弱、劳倦伤中之象。患者年逾五十，过劳怠倦、烦闷恶食，正合东垣劳倦伤脾之论。后诊“浮沉各得其位，大小不逾其矩”，为脉和平有子之兆，非病脉。", ["浮", "小", "濡", "缓"]], "15251": ["病机", "脉浮小而弦，按之无力，浮小为气虚，弦为气滞，无力则非实。中满朝宽暮急，由脾虚不运、气机壅滞所致。虽见胀满，脉不实，故宜补，取“塞因塞用”之法，人参、白术等补脾而胀自消。", ["浮", "小", "弦"]], "15252": ["病机", "右脉大无伦，时复促而中止，左脉略小而软亦中止。大而促结为邪热炽盛、气机不续；软小为虚。合形实病咳痰少声嘶咯血，断为肺脾肾三经病：燥热伤肺、劳倦伤脾、女色伤肾，子盗母气，肺愈虚。", ["大", "促", "结", "软"]], "15253": ["病机", "脉浮细而结，止脉频疏不一。浮细为阴虚，结为脉道不利。痛甚时止脉疏，因热动脉速；痛轻时止脉频，因热退脉迟。合劳欲病因，断为阴虚火动，心火动而肾水亏，故腹痛午后甚。", ["浮", "细", "结", "迟"]], "15254": ["病机", "脉八至而数，数为热，八至则疾急。仲夏得此，暑邪深入，邪气自甚。上吐下泻、不纳水谷七日，形瘦体弱，脉反数疾，为暑热内迫、正气耗伤之象，故宜以暑治。", ["数", "疾"]], "15255": ["预后", "脉浮洪六七至，中有一结。喘病脉洪为阳热壅盛，可治；结为痰凝经隧、脉道不利。洪而结，非死脉，故曰可治。后误服三拗、五拗汤致危，复以生脉汤加竹沥久服而安，印证脉洪可治之断。", ["浮", "洪", "结"]], "15256": ["妇人", "两尺脉皆沉微，尺部候肾与胞宫，沉微示肾气与阴血不足，冲任失养，故艰于育子。形肥色淡紫，肥人气虚，色淡紫为血滞，脉证合参，法当补血益气。然孕后两尺如旧，说明脉象与孕非必相应，原文叹“脉难尽凭”，提示临证不可单凭脉断孕。", ["沉", "微"]], "15257": ["病机", "脉沉细而数，约七至，沉细为阴血不足，数为内热，合形肥色黑、素畏热好饮，显系肺热叶焦、阳明土亏之痿证。前医作风治，误用独活寄生、小续命，反伤正气。原文引“痿有五，皆起于肺热”“治痿独取阳明”，以脉数应肺热，沉细应土亏金失所养，故四肢痿而自汗如雨。", ["沉", "细", "数"]], "15258": ["病机", "脉浮缓而弱，不任寻按，浮缓为土虚，弱而无力为脾气不足，故曰“土虚木实”。脾虚则谷气偏行于右，不能左达，饮食减而大便滞；木实则左腹痞满。原文以人参补脾、枳实泄肝，佐芍药引金泄木，正合脉弱主虚、缓主湿滞之机，非单纯攻伐可解。", ["浮", "缓", "弱"]], "15259": ["预后", "脉皆浮洪如指，脉虽大，按之不鼓，浮洪大示内火燔灼、虚阳外浮，然按之不鼓为虚火而非实热，故原文断为“虚极矣”。形类肥而色尚苍，胃气未绝，尚可救。前医外感发表，虚其虚，致昏愦、消谷善饥、梦遗。脉大为虚，非肝衰之死脉，故曰可治。", ["浮", "洪", "大"]], "15260": ["病机", "脉濡缓而虚，按之不足，濡缓主湿与脾虚，虚而无力为阳明中气不足。形肥色白，酒中折辱，情志郁怒伤肝，木乘土位，阳明虚而痰湿内扰，故发心恙、披发大叫。原文断“此阳明虚也，宜变例以实之”，以脉虚为据，非痰火实狂，故不可峻攻。", ["濡", "缓", "虚"]], "15261": ["病机", "脉濡缓而弱，左脉比右较小，或涩，尺脉尤弱，濡缓弱主湿与气血不足，涩为血少，尺弱为肾虚。善饮则肺热，肺热叶焦，阳明土亏，湿重则筋缓痿软，热多则筋急作痛，故肢痛亦属痿证。原文辨“痿兼湿重者筋缓而痿软，兼热多者筋急而作痛”，以脉之濡弱涩示湿、虚、血少夹杂。", ["濡", "缓", "弱", "涩"]], "15262": ["妇人", "脉近和，惟尺部觉洪滑，尺部候胞宫，洪滑为热，故曰“子宫有热，血海不固”。每行人道经水则来，正是热扰冲任、血海不藏之象。原文以丹溪大补丸加山茱萸、白龙骨止涩治内，乱发灰、白矾灰、黄连、五倍子外治，脉洪滑主热，非虚寒漏下，故清补兼施。", ["洪", "滑"]], "15263": ["病机", "脉浮细缓弱，按之无力，尺脉尤甚，浮细缓弱为气血衰少，按之无力为虚，尺甚则肾血亦亏。年逾五十，血衰可知，血不荣筋则左脚膝挛痛，夜甚于昼，小腹亦痛，皆血虚失养之征。原文断“病属血衰”，以四物汤加牛膝、红花、黄柏、乌药养血行滞，脉虚不受峻补，故缓缓调之。", ["浮", "细", "缓", "弱"]], "15264": ["病机", "两手寸关浮软，两尺独洪而滑，此肾虚火旺而然也。尺脉洪滑为肾中相火妄动，火旺则刑金，故咳嗽咯血、吐黑痰；寸关浮软示脾肺气虚，参术愈甚者，误补其气而火愈炽。治以四物加知柏滋肾泻火，尺脉稍平则肾热减，终以健脾滋肾收功。", ["浮", "软", "洪", "滑"]], "15265": ["病机", "脉皆浮濡而弱，按之无力，晨则近驶，午后则缓，此忧思伤脾病也。脾伤则气结，肺失所养，故咳嗽；甚则吐食呕血、发热恶寒自汗，皆脾虚气弱、营卫不和之象。晨驶午后缓者，气虚不能升举，阳分尤甚。治以安脾散郁、清肺和血，渐加参芪而愈。", ["浮", "濡", "弱"]], "15266": ["病机", "脉浮缓而濡，两尺尤弱，此得之酒色，肾水虚而水气泛滥也。水极似土，面光腹大脚肿，饮食减少，皆水湿壅盛、脾肾阳虚之虚象。若通利渗泄则下多亡阴，愈伤本病。治以六味补肾，四物加柏、通、朴、陈、参、术，肿减而愈。", ["浮", "缓", "濡", "弱"]], "15267": ["病机", "脉或浮大，或小弱无常，此虚之故也。年逾五十，眩晕溲涩、体倦梦遗、心跳不寐、易感风寒，皆气虚不能统摄、心神失养之候。脉无常者，虚风内动、气血不充也。色黑而气虚，当从形治，以参芪为君补气，佐以安神滋肾，逾年病安。", ["浮", "大", "小", "弱"]], "15268": ["病机", "脉皆缓弱颇弦，此木火乘土之病也。缓弱为胃土本虚，弦为肝木偏旺，木火乘虚犯胃，故痫发晨盥、目见黄狗而昏仆瘛疭。早晨阳分，黄土色，胃属阳土，虚为木火所乘。治宜实胃泻肝，用参芪归术补中，黄芩麦冬清火，火息而病安。", ["缓", "弱", "弦"]], "15269": ["病机", "脉皆沉细不利，心部散涩，此阴脉也。脾与心必因忧思所伤，故眩晕倦怠、夜寐心悸言乱。沉细为气血内损，散涩为心脉失养。后因懊恼脉变三五不调、或数或止，此促脉也，怒激其火而然，非怪脉，调气散服之即安。", ["沉", "细", "散", "涩"]], "15270": ["病机", "脉浮小而滑，颈项少阳痈肿如碗。浮小为气虚，滑为痰热壅结，然少阳多气少血之经，形肥色紫年逾五十，正气已虚，若寻常驱热败毒，痈溃后难免别患。故先以参芪归术膏补托，茶引至少阳，旬余痈溃而起，此托里消痈之法。", ["浮", "小", "滑"]], "15271": ["病机", "脉浮小而濡，按之不足，兼形瘦色白而脆，知其为虚症矣。身如虫行有声，乃汗多亡阳、气虚不能温煦肌肤之象。浮小濡弱为阳气虚馁，按之不足尤显中气亏虚。仿补中益气汤多加参芪，佐酒炒黄柏五分，服二三十帖而愈。", ["浮", "小", "濡"]], "15272": ["预后", "脉细数无复伦次，细为阴血亏虚，数为虚热内扰，脉律失序乃肾水涸竭、五脏逆传之候。原文谓“七传者，逆经传也”，肾邪传心则发热夜重，传肺则咳嗽汗泄，传肝则胁痛气壅，传脾则肠鸣作泄，脾复传肾而肾不受邪，故断死不出旬日。脉象与五脏传变症候相应，示脏气败绝。", ["细", "数"]], "15273": ["病机", "六脉沉濡而缓、按之无力，沉主里，濡缓主气虚湿滞，重按无力为脾胃气衰不能统血。原文断为“气病，非血病也”，血崩由中气下陷、血失统摄所致，故用甘温健脾理胃，使胃气上腾、血行经络而崩愈。脉症相合，示崩漏之因在气不在血。", ["沉", "濡", "缓"]], "15274": ["病机", "脉弦细而缓、按之似涩，弦主痛主积，细缓为血少气滞，涩示血行不畅。原文断“此血病也”，疝痛腹中磊块起落如滚浪，乃血积气滞作痛，故变法治之，用小承气加桃仁下之。后脉轻弦大重散涩，因食鸡卵滞气，探吐而解，示脉随病机而变。", ["弦", "细", "缓", "涩"]], "15275": ["死脉", "脉萦萦如蛛丝，细弱欲绝、按之若无，乃元气衰败、胃气将竭之死脉。年逾六十病气喘，喘促而脉微细如丝，示肺肾之气不能相续，根本已离。原文“若有难言者”，患者自悟不得济，是夜书讫而逝，脉象与预后相应，属真脏脉见之危候。", ["细"]], "15276": ["病机", "脉浮缓弦小、重按似涩，浮缓为气机不利，弦小主痛主积，涩为血滞。原文断“此血病也”，腹痛磊块起落如波浪、昼轻夜重，乃血积血滞作痛，非气病。前医作气治不验，用四物加三棱、蓬术、乳香、没药活血破积而痛脱然，脉症相符。", ["浮", "缓", "弦", "涩"]], "15277": ["妇人", "脉右大于左，原文引《脉诀》“左大为男，右为女”，然此妇右脉浮大而前次生男，今妊又得是脉，后果生男。居士谓“脉书但道其常，莫能尽其变”，示妊娠辨男女不可拘执右大主女之说，当合望闻问切，此段主旨为妇人妊脉之变。", ["大", "浮"]], "15278": ["病机", "脉缓弱稍弦，缓弱为脾土虚衰，弦为肝木偏旺。原文断“非气非痰，亦非寒也，乃肝凌脾之病”，患者面青性急为肝木甚，食入良久复出为脾虚不运。脉症合参，用四君子加陈皮、神曲，少佐姜炒黄连泄气逆，服月余而愈，示脉色相合之要。", ["缓", "弱", "弦"]], "15279": ["主病", "脉洪缓而濡，洪为热盛，缓为营卫不利，濡主湿滞，合之示痈肿虽大而热毒尚浅、气血未至大伤。原文谓痈肿如碗、皮肉不变、按之不甚痛、微发寒热，乃太阳经分疮疡，尚可治。用黄耆、当归、羌活、甘草节托里透邪，令微汗而肿消，脉象与痈疡顺证相应。", ["洪", "缓", "濡"]], "15280": ["病机", "脉浮缓而濡，浮为虚阳外浮，缓濡为胃气虚弱、湿滞中焦。忍饥劳倦伤胃，胃虚火动，延及心脾，神意失守而狂言。此非实热痰火，故不可吐下，法当补之，独参汤加竹沥取效。", ["浮", "缓", "濡"]], "15281": ["病机", "脉浮缓而弱，两尺尤甚，尺弱主肾虚，浮缓为虚阳外越。渴热昏闷面赤乃肾虚寒极生热之假象，非真热。故用附子理中汤温热冷服，热退后以清暑益气汤调补，体现治病求本。", ["浮", "缓", "弱"]], "15282": ["预后", "原文未载脉象，但以脉病同而心宽可治、二人急于名利果没，说明脉病相应之外，情志宽急关乎预后。心宽者气血易调，急名利者神耗难复，故一之可治，二人逾年果没。", []], "15283": ["预后", "原文未出脉象，但言「病与脉应，无虑也」，知脉证相符，虽痢久瘦弱、食入即吐，胃气未绝。故不劳以药，饲米饮养胃气，待白露节后金气渐旺，胃气来复而愈，属脉证相应之顺候。", []], "15284": ["预后", "原文未载具体脉象，仅言「脉危矣」，又断「不利于春」。秋间病酒，脉已见危，虽暂愈而疮痍遍身，是邪毒未净、根本已伤。春属木，肝气当令，脏气不胜时令，故至立春果卒，示脉危主预后不良。", []], "15285": ["病机", "脉浮濡而缓，右寸略弦，浮濡缓为劳倦伤酒、湿滞肌表，右寸弦主肺气不利、痰湿内蕴。症见恶寒发热头痛自汗恶心咯痰，似疟而非疟，实为过劳伤酒、暑湿内伤，故以清暑益气汤而愈。", ["浮", "濡", "缓", "弦"]], "15286": ["病机", "脉大如指，非实热，乃脉气虚也。衄血如注、嗽喘不能伏枕，肺气大虚，金极似火，火浮于上。前医寒凉降火愈甚，不知「亢则害，承乃制」。脉大而虚，主肺气虚极，故用甘温补肺气，火自退。", ["大"]], "15287": ["病机", "脉皆柔软无力，两尺浮而弱，不任寻按，主气血耗甚、肾气不固。屡次坠胎，气血大伤，胎无所养，如「水涸而禾枯，土削而木倒」。尺浮弱为肾虚不摄，故频坠在三、五、七月少阳火动之时，治宜大补气血兼清火。", ["软", "弱", "浮"]], "15288": ["兼症", "右脉浮滑，左细滑，浮为在表，滑为痰热内蕴，细为血虚。患者久疟后疟止有妊五月，忽腹痛泄泻头痛发渴，乃疟后余热未清，痰热内扰，兼胎前血虚。右脉浮滑主脾胃痰热，左细滑主血虚有热。故先以四君子加石膏、黄芩清解，后以四物加酒大黄、槟榔通利，胎亦无损。", ["浮", "滑", "细"]], "15289": ["病机", "脉皆细弱而缓，细弱为气血不足，缓为脾土之象。患者心悸恐惧如人捕之，不能安寝，前医作心病治不效。细弱缓脉示非心火亢盛，乃胆气虚怯、痰浊内扰，胆主决断，虚则善恐。故用温胆汤化痰宁胆而安，脉象与胆病相应。", ["细", "弱", "缓"]], "15290": ["病机", "脉皆濡小近驶，濡小为气虚，驶即数，示有郁热。患者体弱色脆，腹痛恶寒发热呕泄倦卧吐虫，前医作气、寒、积、痰治皆不效。濡小近驶说明气虚为本、郁热为标，非纯寒纯积。故用参耆归术补气，香附陈皮调郁，黄芩芍药清热的安。", ["濡", "小", "驶"]], "15291": ["病机", "病发时脉皆结止，苏则如常但浮虚。结为血少气劣，气血不能接续，故发瞀昧目系急、合眼昏懵。浮虚示气血不足。患者年逾七十形肥色紫，虚象明显。前医作风治加重，正因误辨。此虚病，发时脉结乃血少气劣，苏时气血流通故脉如常，以大补汤去桂加麦冬、陈皮补气血而安。", ["结", "浮", "虚"]], "15292": ["病机", "脉皆浮缓而濡，按之无力，濡缓为脾虚湿盛，浮为虚阳外浮。患者因祈雨过劳，手足瘛疭如惊状，语言艰涩。此劳倦伤脾，土极似木，脾主四肢，土虚则木发而风动，故瘛疭。非痰火风症，若作风痰治必死。当补脾土之虚，则肝木之风自息，参术为君即此意。", ["浮", "缓", "濡"]], "15293": ["病机", "脉皆浮小而缓，按之虚豁，浮小缓而虚豁为气阴两虚、暑热伤气之象。患者暑月过劳，饥饮烧酒，病热汗昏懵语乱。暑伤心、劳伤脾，心藏神脾藏意，二脏被伤故神昏语乱。脉虚豁示正气不足，非实热。法宜清暑安心、益脾宁意，用八物汤加麦冬、山栀、陈皮而愈。", ["浮", "小", "缓", "虚"]], "15294": ["预后", "脉皆弦涩而缓，尺脉浮而无根。尺当沉反浮，主肾水亏虚；弦属木，涩为血少，缓属脾。合观为血液枯槁、肝木凌脾，非膈即噎。患者形瘦而苍，年逾五十，胸膈微有碍，脉证相符。居士断不久膈病成，非药可济，后果病膈而卒。此段以脉论预后，弦涩缓示血枯木旺，尺浮无根示肾竭，故主凶。", ["弦", "涩", "缓", "浮"]], "15295": ["病机", "脉细且数，约六至。细为血虚，数为热，数脉所主其邪为热其症为虚。患者面黑形瘦，鼻衄发热恶寒，消谷善饥，疲倦自汗呕吐，乃虚热内扰、气血不足。丹溪谓瘦黑鼻衄脉数者参耆当禁，然《脉经》明言数脉主热主虚，不可执定。故用人参、黄耆补虚，配黄柏、山栀、生地清热，服之果安。", ["细", "数"]], "15296": ["病机", "脉或浮濡而驶，或沉弱而缓，脉象不常，乃虚之故。浮濡而驶为心火亢而阴血不足，沉弱而缓为脾肾两虚。症见溲精、梦乱心跳，因肾水亏致心火乘金、木侮脾，属心脾肾三经之病，故脉无恒定，虚象迭现。", ["浮", "濡", "驶", "沉"]], "15297": ["其他", "此段述黄公著作《重集脉诀刊误》等惠及后学，非论脉象病机，故脉象要素为空。文中未涉及具体脉诊内容，仅赞其学术贡献，与脉学病机无关。", []], "15298": ["病机", "脉浮紧而数，左大于右，浮紧为表寒，数为里有热，左大为邪盛于表。症见咳嗽恶寒胸痞口干心微痛，乃表盛里虚，素嗜酒肉有积，复因行房涉寒，外寒束表，内热郁积，故脉浮紧数。", ["浮", "紧", "数"]], "15299": ["病机", "脉弦大散弱，左大为甚，弦大为劳倦感寒，散弱为气耗血伤。因误服辛甘燥热动血，致咳痰如脓、声不出、血线自口出，脉散未收示正气耗散，恐成肺痿，乃劳倦感寒、强汗动血之坏证。", ["弦", "大", "散", "弱"]], "15300": ["病机", "脉大而弱，右关稍实略数，重则涩。大弱为形气不足，右关实数为酒热内郁，涩为郁滞。症见大恶寒发战、渴不饮，乃酒热内郁不得外泄，表热而虚，故脉大弱中见实涩，非纯虚可补。", ["大", "弱", "实", "数"]], "15301": ["治法", "脉细微而迟者，为气血虚寒，故用参、芪；然血虚脉大、阴虚脉大无伦者，东垣、丹溪亦用参、芪。脉大无伦为阴虚阳暴绝，脉大为血虚阳浮，故不可拘泥细微迟者方用参芪，当辨虚实。", ["细", "微", "迟", "大"]], "15302": ["病机", "脉虚为气血不足，仲景治亡血脉虚以人参补之，取甘能生血、阴生于阳。人参不惟补气亦能补血，黄耆得当归引亦补血。脉虚主血虚气弱，故用参芪补气生血，非辛热助火之品。", ["虚"]], "15303": ["其他", "此段论营卫运行，营行脉中、卫行脉外，未涉及具体脉象，故脉象要素为空。文中辨析营中亦有卫，以阴阳奇偶为说，属脉学理论探讨，非主病、病机或预后之列。", []], "15304": ["病机", "原文论营卫运行，谓“营行脉中而亦行脉外”“卫行脉外，亦行脉中”，强调营卫内外相通、气血相贯。虽未及脉象，然脉为血之府，营行脉中，卫行脉外，二者相谐则脉道通利；若营卫失和，则脉象可现浮沉失常。此段旨在阐明营卫互根之理，为脉诊中察营卫盛衰提供理论依据。", []], "15305": ["病机", "原文引《灵枢》论营卫同源，“营卫者，精气也”“营卫一气”，指出营中有卫，异名同类。脉象虽未明言，然营卫和谐则脉道充盈和缓；营卫一有偏衰，则脉现虚实。此段从营卫一气论脉之根本，示人诊脉当察营卫精气之盛衰，非独辨浮沉迟数而已。", []], "15306": ["其他", "此段为医案序言，称许杏轩先生“审脉处方，深得古人四然二反之理”，强调“理明则意得，意得则审脉处方”。文中未及具体脉象，然“审脉”二字点明脉诊须以理意为先，非执方习针者所能望其项背。此段主旨在于医家素养与脉诊境界，非论病机。", []], "15307": ["主病", "产后十二朝，脉弦数，舌苔黄，发热口渴心烦，胸闷便闭。弦主气郁，数主热，乃产后感邪，温散温补姑息，邪无出路，郁而化热。脉弦数应邪郁化热之机，与舌黄、便闭相合，故断为产后感邪、郁热内结，非阴证虚寒。", ["弦", "数"]], "15308": ["病机", "患者食减形倦、心悸少寐、浮火上升间或见血，医作肝肺火盛清降不效。脉散，散为气耗不收，主心脾内亏、先天不足，虚火浮越。散脉应虚火不敛之机，故投黑归脾汤合生脉散补益心脾、敛浮火而效。", ["散"]], "15309": ["病机", "脉虚弦细急，症见通宵不寐、闻声即惊、胸膈嘈痛、食入呕半、粪如羊矢。虚细为心脾内亏，弦急为抑郁气结，木郁克土，脾不能为胃行津液，故食阻便干。脉虚弦细急正合情志内伤、心脾郁结之病机，非膈证之脉。", ["虚", "弦", "细", "急"]], "15310": ["预后", "高年中风，身僵神昏、声鼾痰鸣、遗尿手撒，脉虚大歇至。虚大为脏真亏竭、元气外浮，歇至为脉气断续，合五绝之候，故断为中脏殆证。后服药脉证大转，虚大渐敛，乃元气渐复之兆，故预后由危转安。", ["虚", "大"]], "15311": ["病机", "禀质向亏，诵读烦劳，心神伤耗，阳强不密，精时自下。脉虚细无力，为水火失济、心肾两虚，虚阳不敛而精关不固。虚细应精亏阳弱之机，故用六味加减滋阴敛阳，后参脾药补化源，合乎“滑者涩之”之意。", ["虚", "细"]], "15312": ["病机", "原文未明言脉象，仅述“诊脉神根未败”，强调虽见肢掣痰鸣、身热烦躁等危候，但脉有神根，示胃气未绝，故断可生。其病机为肾水下虚，肝失所养，木逢金制，故作寒热；误投疏散，津液更伤，肝风鼓动，发为惊搐。脉神未败正是生机所在，与“形瘦阴虚”“本非外因”相呼应。", []], "15313": ["病机", "脉沉细无力，沉主里，细主阴血不足，无力为虚。儿质亏感邪，便泻多日，脾元受伤，中阳不振，故四肢冰冷而脉沉细无力；脾虚肝木失养，虚风内动，故作抽掣。此脉不任金石镇坠，宜六君子汤加炮姜桂枝温运脾阳，使肢温泻止而惊不作。", ["沉", "细"]], "15314": ["病机", "原文以“脉细质亏、脉洪质实”对举，示暑风急惊须辨体质虚实。脉细质亏者，阴血不足，暑热易陷心肝；脉洪质实者，邪热鸱张，风火相煽。此证暑喜伤心、风喜伤肝，热生惊，故肢搐体僵、目斜口啮。治当清暑疏风，金石镇坠反锢邪，故概置不用。", ["细", "洪"]], "15315": ["病机", "脉数主热。大头时疫，热毒郁于上焦，故头颅红肿、渐及面目颐颊、舌焦口渴而脉数。热郁于内，外反见寒象，故病人自觉喉冷、吸气如冰；诸逆冲上皆属于火，故饮药旋吐。此非真寒，乃热深厥深之象，脉数正是火热内郁之据。", ["数"]], "15316": ["病机", "脉震动，因久嗽不已，周身百脉震动，胎火上冲，肺金被制，治节不行，故嗽喘胸痹、夜不安卧。嗽则百脉震动，必致动胎，故脉见震动之象。治以补肺阿胶汤清金降火、润肺安胎，使胎病两调，则震动可平。", ["动"]], "15317": ["病机", "脉大无力，大而无力为虚。年逾四旬，外腴内亏，邪乘虚入，故寒热咳嗽、头身疼痛而脉大无力，此正虚邪恋之候。迁延数日，面红目赤、舌黑唇焦、神识昏乱，脉息豁大空虚，乃元气溃散、势欲内陷之危象，故用壮中温托、六味回阳饮方法。", ["大", "虚"]], "15318": ["病机", "脉细面青，细为阳虚阴盛，青为寒凝；脉浮大者，虚阳外浮之象。寒湿内伏，加感外邪，故上热下冷、痰多汗少、咳嗽作呕，酷热犹盖毡被，舌苔白滑，胸腹胀闷。此非肝火，乃寒湿内伏、虚阳上浮，治宜温中逐邪，用苍白二陈汤加姜附、白蔻、桂枝、秦艽。", ["细", "浮", "大"]], "15319": ["病机", "脉大主邪盛，数主热。冬不藏精，又伤于寒，邪伏少阴，乘春触发，即春温两感证。神昏脉大、面赤舌黑，为邪伏于里、真元内亏；热盛舌干、烦躁脉数，为热郁阴伤。脉大数示邪热鸱张而正虚难逐，故先以理阴煎补中托邪，继用六味回阳饮，后易左归。", ["大", "数"]], "15320": ["病机", "脉细如丝，为阳气衰微、脉道不充之象。患者年逾五旬，酒色伤阳，寒夜仆地，面白肢厥、口鼻气冷、神昏遗溺，皆阳脱之候。脉细如丝，正气欲绝，故断为阳脱。急灸气海关元、灌姜汤，后以参附汤回阳救逆，脉色渐回，说明脉细主阳衰危候。", ["细"]], "15321": ["预后", "脉弦劲无胃，乃真脏脉见，失柔和胃气；形瘦脉大，胸中多气，经云主死。患者咳嗽寒热、形倦肌瘦、食少便溏，经闭三月，证属二阳之病发心脾，传为风消。脉弦劲无胃，提示胃气已败，故断为不治，逾旬而殁。", ["弦", "大"]], "15322": ["预后", "脉细数，为阴虚火旺、痨瘵内热之象。室女腹痛、咳嗽寒热、形瘦食少、经事愆期，证属痨瘵。脉数经闭，阴血亏耗，虚热煎熬，故多不可治。原文历见妇人咳嗽寒热、脉数经闭者多死，室女更无一生，强调此脉此证预后极差。", ["细", "数"]], "15323": ["病机", "脉芤虚，为血脱气耗之象。患者年近七旬，久患腹痛，瘀蓄已久，忽吐下紫瘀血块数碗，头晕自汗、目阖神疲，乃血脱证。芤主失血，虚主气虚，气为血帅，高年气虚，切虑晕脱。故用黑归脾汤资化源、固统摄，未几获痊。", ["芤", "虚"]], "15324": ["病机", "脉虽虚细，尚未散乱，为血脱而气未绝之象。患者久患痞积，误用炙法、末药，致吐下紫瘀成碗成盆，昏晕手战咬牙，血脱之候。虚细脉主气血亏虚，然未散乱，说明生机尚存，故戒勿惊扰，先灌米饮、党参汤，再与八珍汤，血止而安。", ["虚", "细"]], "15325": ["病机", "脉虚数无力，为暑热伤阴、元气被伐之象。小儿夏月病逾两旬，发热不退、汗多口渴、色白肌瘦，前医悉用清散，热久伤阴，故脉虚数无力。虚为气阴不足，数为余热未清，急宜养阴保金生水，尚有生机。", ["虚", "数"]], "15326": ["病机", "脉弦急，为肝木不舒、气郁化火之象。患者寒热胁痛、口苦食少、呻吟不寐，情志抑郁，肝失条达，病似外感而实内伤。弦急脉主肝郁气滞，与胁痛口苦相应，故用加味逍遥散疏肝解郁，一服而效。", ["弦", "急"]], "15327": ["病机", "脉虚濡无力，为气血亏虚、肝肾下亏之象。患者体虚多劳，足痹日久，腓肉枯瘪、膝盖肿大，干脚气也。虚濡无力主正虚，邪乘虚伏，医者泛从标治，血气耗伤。治宜温补托邪，用大营煎加附子、党参等，渐得康复。", ["虚", "濡"]], "15328": ["误治", "脉细肢冷为阴暑感证，寒邪伤阳，阳气不能温煦四肢，故肢冷；脉细主阳气虚弱。前医误以痰火常方治之，反致病重，说明阴证误用凉药可致坏病。后食馄饨得汗反安，属偶然，不可为训。", ["细"]], "15329": ["预后", "无故发癍而诊脉和平，寝食如常，别无他疾，说明气血未乱，非实火邪毒所致。前医误投凉药致变损怯，乃药误伤正。此脉和平示病轻浅，故勿药自愈，预后良好。", ["和平"]], "15330": ["病机", "初诊脉沉细，为体虚感邪，邪乘虚陷，少阴下亏；投温托后脉转浮大，舌黑面红，奄奄欲脱，乃正虚邪陷，虚阳外越之危候。脉由沉细转浮大，示病机由虚陷转为阴阳离决之势，故用大剂党参熟地固脱。", ["沉", "细", "浮", "大"]], "15331": ["妇人", "手少阴脉微动，问经事两月未行，脉象似属妊娠。微动为气血充盛之象，少阴脉动主胎孕。口吐清涎乃冲脉上逆，非病态。此段以脉测孕，说明妊娠脉象可表现为少阴脉微动，当结合经事判断。", ["微", "动"]], "15332": ["病机", "脉沉细无力，为脾肺肾三脏内亏之水肿。肺虚不化精而化水，脾虚水无所制，肾虚水无所主，故水湿泛滥，腹大足冷，阴囊光亮。脉沉细无力正是三脏虚衰、水气内停之征，故用金匮肾气丸温阳化水。", ["沉", "细", "无", "力"]], "15333": ["病机", "脉细肢冷，舌白面青，畏寒不热，腰痛无汗，为夹阴伤寒，正亏邪伏。脉细主正虚，肢冷为寒邪伤阳。醉后入房，邪乘虚伏，交秋而发。治当温中托邪，照顾真元，故用附子理阴煎加参耆枸杞杜仲。", ["细"]], "15334": ["病机", "脉息沉细无力，身热足冷，喉红肿痛，为少阴伤寒，上热下寒。肾元下虚，寒邪客之，雷龙不安其宅，故喉痹。沉细无力主肾阳虚衰，非风热实证。若误清散，则阳气更伤，故用镇阴煎温补下元，引火归根。", ["沉", "细", "无", "力"]], "15335": ["病机", "胎堕血崩，昏晕汗淋，面白如纸，身冷脉伏，为血脱阳亡之危候。脉伏乃阳气衰微，不能鼓动血脉，气血暴脱所致。急用参附汤回阳固脱，续以补益气血，旬日始安。此脉伏主血脱阳亡，非邪闭之伏。", ["伏"]], "15336": ["病机", "脉沉伏而肢厥，非寒厥，乃吐泻频作，津液顿伤，脾不能为胃行其津液，四肢不得禀水谷之气，故脉伏肢冷。此脉主津伤气耗、脾失健运之病机，与伤暑发热、吐泻、口渴、烦躁相应。", ["沉", "伏"]], "15337": ["病机", "脉伏而肌肉青紫，面赤烦躁，呃逆频频，乃少阴下亏，寒邪乘之，逼真阳外越，阴阳不相顺接，故脉伏肢冷。此脉主真阳飞越、重阴用事之病机，与寒热身痛、肢冷、面赤、烦躁、呃逆相应。", ["伏"]], "15338": ["病机", "脉虚细而涩，年高病久，正气亏虚，肠腑失润，传导无力，故便闭腹痛肛胀。此脉主虚闭之病机，与便闭、腹痛、肛胀、寝食俱废相应。虚细涩为气血不足、津亏肠燥之象。", ["虚", "细", "涩"]], "15339": ["病机", "脉沉细无力，外状丰腴而内虚，房劳感寒，逼虚阳外露，即格阳证。沉细无力主里虚阳衰，与寒热烦躁、头身疼痛、面红目赤、舌吐唇外相应。此脉说明真阳不足、虚阳上浮之病机。", ["沉", "细"]], "15340": ["病机", "脉细涩，面赤烦躁，便秘经旬，汗不出而肤熇枯，乃阳证阴脉，表寒外束，郁热内闭，营卫不通。细涩主阴血不足、脉道不利，与寒热头痛、昏谵口渴、便闭相应。此脉说明表实里热、营卫郁滞之病机。", ["细", "涩"]], "15341": ["病机", "脉细无力，热盛汗多，神昏体倦，呓语音低，乃虚证谵语，非阳明实热。细无力主气阴两虚，与发热、胸闷干呕、汗多、神昏、语低相应。此脉说明正气亏虚、心神失养之病机。", ["细"]], "15342": ["病机", "脉弦急搏指，因郁生火，因火生痰，痰火扰神明，蒙心窍，故神迷谵妄、语言不正。弦急主肝郁化火、痰火内盛，与情志不舒、神迷谵妄、举动异常相应。此脉说明痰火扰心之病机，非阳明胃实。", ["弦", "急"]], "15343": ["病机", "脉息弦数，夏日浴罢，暑风相搏，邪热燔炽，故发热烦渴呕吐、谵妄不安、手指掣动。弦数主热盛动风，与舌尖绛苔黄、热盛、掣动相应。此脉说明暑热内盛、肝风欲动之病机，亟宜清解以杜痉厥。", ["弦", "数"]], "15344": ["病机", "原文脉息细涩而见呕吐、汗冷、肢麻、言微气短、胸膈胀闷，医者断为郁病而非虚脱。细涩乃气机郁滞、血行不畅之象，非真元虚损，故投补剂反剧。其性躁多郁、曾患吐血、发厥，皆肝郁化火、血菀于上之征；以手捶胸、叫喊声彻户外，更证气机阻闭而非脱证，故用越鞠丸开郁。", ["细", "涩"]], "15345": ["其他", "此段仅存标题「陈某子感证体脉俱厥」，未载具体脉象描述，故脉象要素为空。题旨言感证而体脉俱厥，提示外感热病中出现脉与四肢俱厥的证候，当与后段阳证似阴之沉细厥冷互参，属病案提纲性质，非独立脉学论断。", []], "15346": ["病机", "壮热神昏、面赤烦渴、唇燥舌焦、口鼻牙根出血俱属热象，而脉息沉细、四肢厥冷，诸医不效。此非阴证，乃阳证热邪深伏、郁遏于里，气血不能外达，故脉沉细而肢厥，属热深厥深之象。后脉竟绝、肢冷更甚，示邪盛正溃、生机将竭，为误失凉解、迁延致危之候。", ["沉", "细"]], "15347": ["兼症", "病妇忧劳传染，初起头疼寒热，汗解后劳复发热，口苦耳聋，适值经期，恐热入血室。面赤舌黄、谵语脉数，为邪犯少阳阳明、热扰神明之征。数脉主热盛，与谵语、舌黄并见，说明邪已由表入里化热；继而咬牙闭目、昏厥遗尿，乃热极动风、内陷心包之变。", ["数"]], "15348": ["病机", "腹痛拒按、舌苔黄中心焦燥、大便未行，脉沉细甚至痛剧而伏。沉细非必虚，乃实邪内结、气血壅滞不得外达；痛剧脉伏尤为常理。原文强调「质虽虚而病则实」「腑病以通为补」，脉证合参当属下证，故主以大承气汤，说明脉沉细不可拘作虚论。", ["沉", "细", "伏"]], "15349": ["兼症", "妇病感证，两进逍遥散不应，热盛脉数、口渴舌黄，加生地黄芩后证不减，反神昏舌苔干黑。数脉主热，与口渴舌黄并见，示邪热炽盛、耗伤津液；舌苔干黑、神昏则热入营血、阴液将涸。此段以脉数点出热盛之机，为改用大剂甘露饮养阴清热之依据。", ["数"]], "15350": ["病机", "脉弦数搏指，壮热谵狂、面目都赤、舌黑便秘、腹痛拒按，皆邪踞阳明、胃实热盛之象。弦主邪实气壅，数主热盛，搏指示邪势鸱张。饮冷水一碗而甘如饴、心地顿快，更证内热炽盛、津液受灼，故断为极重感证已成胃实，当从阳明实热论治。", ["弦", "数"]], "15351": ["病机", "壮热不退、目赤唇干、舌黑起刺、便闭溲赤，脉弦数有力，脉证均属阳热。虽喜饮沸汤似有阴象，然弦数有力之脉与诸热证相合，当从重者论，断为胃热炽盛而非阴寒。故先与小白汤不效，继进大剂白虎汤重用石膏，终得热退神清、便通舌润，说明脉弦数有力为实热内盛之确据。", ["弦", "数"]], "15352": ["病机", "脉沉细为阴寒内盛之象。患者夏月发热口渴，但舌白面青、身热反近衣、渴喜热饮，显系阴暑证，寒邪内侵，阳气被遏，故脉沉细。沉主里，细主虚，说明寒伤阳气，非真热证。前医误用凉剂，更伤阳气，故投附子理中汤温中散寒而愈。", ["沉", "细"]], "15353": ["病机", "脉虚细，经云“脉虚身热，得之伤暑”，为暑伤气阴之象。然服清暑益气汤后脉更细，舌苔紫碎、渴嗜冷饮，显系热邪蕴伏未透，阳证阴脉。此脉细非虚寒，乃热邪内郁、气血不畅所致，故舍脉从证，用白虎汤清透热邪。", ["虚", "细"]], "15354": ["病机", "脉虚神倦，自汗如雨，舌苔白滑、分开两歧如刀划，乃阴证误服凉药，阳气衰微之候。脉虚主阳气不足，神倦为气衰，舌象人字纹为阴寒内盛、误下伤阳之征。故用六味回阳饮温阳救逆，继以左右二归饮调补而痊。", ["虚"]], "15355": ["病机", "脉息沉细，下体如冰，饮沸汤不知热，阴寒脉证悉具。沉细主里寒阳虚，阴寒内盛，逼阳外越，故舌色如朱，似热实寒。凭脉用药，先以小剂理中汤探之，继用六味回阳饮温补，数服病痊，舌色亦退，乃肾水凌心、心阳外越之故。", ["沉", "细"]], "15356": ["病机", "经脉动惕，为肝风内动之象。患者质亏多郁，头痛巅顶，误投温散，致痛剧而厥，呕吐不食。经云“诸风掉眩，皆属于肝”，下虚上实，水不涵木，怒木生风，故脉动惕。治以地黄汤加熄风潜阳之品，使肝肾之气归原而愈。", ["动"]], "15357": ["死脉", "原文仅存“汪某头痛预见真脏脉”一句，未载具体脉象。真脏脉见，乃胃气衰败、五脏真气外露之死候。头痛而见真脏脉，说明病非单纯外感，而是脏腑精气将竭，预后不良。此段主旨为死脉，提示脉无胃气则死。", []], "15358": ["预后", "脉弦急而枯，为真脏脉见。弦急主肝木亢盛，枯则无胃气，阴血亏竭。患者质薄多斫丧，头痛时作，夏见真脏脉，至冬而逝。此脉示本实先拨，枝叶未害，预后极差，故嘱静养补药，终至不治。", ["弦", "急", "枯"]], "15359": ["误治", "脉伏，肢厥舌吐，为寒下耗伤真阳，阳气暴脱之危候。本体血虚，误用芩连大黄清下，致阳气骤脱，脉伏不出。伏脉主邪闭或阳衰，此处为阳脱。急投通脉四逆汤，灸气海关元，回阳救逆而苏，续进左归饮等调补而痊。", ["伏"]], "15360": ["主病", "脉细弱为气血两虚之象。患者处境艰难，多忧虑，脘痛经岁，望色萎黄，痛喜按，得食痛缓，皆虚痛之征。细弱脉主气血不足，脾胃虚弱，故订归脾汤补益心脾，多服乃效。", ["细", "弱"]], "15361": ["病机", "脉伏为气机闭阻，阳气不达。食积少腹，撑迫膀胱，便溺俱闭，气反上行而呕，肢冷脉伏，此食厥证也。脉伏非寒凝，乃实邪内闭，故姜附吴萸反剧，通便则诸证自释。", ["伏"]], "15362": ["病机", "脉弦搏为肺胃火盛，热迫血妄行。齿衄吐血鼻衄大流，脉弦搏示火气上逆，非寒凉折之不可。后用太谿穴掐定止血，血去阴伤，脉转虚，故改用滋阴。", ["弦", "搏", "动"]], "15363": ["病机", "脉细濡两尺尤弱，为气血大亏之象。体虚多劳，服疏风药后口不能张，四肢挛急，此痉病也，非外感。细濡弱脉主气血不足，筋脉失养，故用大剂补元煎，守服渐愈。", ["细", "濡", "弱"]], "15364": ["其他", "原文仅言“王木工反关脉”，未描述具体脉象。反关脉为脉位异常，非病脉，属生理变异。此段主旨为记录反关脉现象，故脉象要素为空。", []], "15365": ["其他", "诊脉全无，按脉乃血派，此必血脱之故。然血脱益气，用党参得活。再诊两手仍无脉，悟为反关脉。原文未识脉名，脉象要素为空，主旨为反关脉之辨识。", []], "15366": ["病机", "原文未识脉名，但言“据兹脉证，责诸肺肾阴亏，肝阳上僭”。咳血由火炎血溢，脉当细数，治以滋水生木，润肺保金。此段主旨在辨病机，非具体脉象。", []], "15367": ["预后", "脉数舌黄为热病，用竹叶石膏汤后战汗，脉虽虚耎而和缓，不急疾，知为战汗而非脱证。虚耎示本气不足，和缓为胃气尚存，故预后无妨。", ["数", "虚", "耎", "缓"]], "15368": ["预后", "脉急数而自汗如雨、躁烦不安、神志不宁，是阳气外越、元气欲脱之候。急数非热盛，乃虚阳浮越、气不归元之象，故曰“气脱阳越”。此与寻常外感发热脉数截然不同，速宜大剂回阳救逆，迟则脱绝。原文以“大相悬绝”强调辨证关键在脉之急数兼汗出神躁。", ["急", "数"]], "15369": ["病机", "幼年质弱，热退痛止后反卧床倦怠、气怯懒言，脉细软无神，是元气不支、虚脱将成之候。细软无神非邪留，乃正气溃败、脏气易虚之征。原文“切恐虚脱，亟宜峻补”点明脉证疲惫至此，舍补别无他策，与攻实之法迥异。", ["细", "软"]], "15370": ["病机", "暴注下迫而脉细弱乏神、按之则空，胎微黑不渴，是寒邪直中太阴、脾阳衰败之候。细弱乏神主正气虚，按空为阳衰不能鼓脉，故非热泻，乃虚寒内盛。原文以“非附子理中汤不可”明其病机在寒中太阴，脉证合参方不致为肤见所阻。", ["细", "弱"]], "15371": ["病机", "冬月重感寒邪，脉细紧而寒热无汗、头疼体痛，是寒邪束表、营卫凝涩之候。细为素体不足，紧主寒主痛，细紧并见示正虚寒束。原文以附子理阴煎加人参麻黄，取补散兼施、阳根于阴之义，说明此脉非单纯表实，须顾其虚。", ["细", "紧"]], "15372": ["病机", "夏月纳凉痛饮后壮热憎寒、目赤口燥不饮，脉洪大而空、沉按若无，是肾阳为阴暑所迫、阳气上戴之候。洪大而空非实热，乃虚阳浮越于上、根本空虚，故原文断为“戴阳证”，以附子理中加香薷人参温阳祛暑。", ["洪", "大", "空"]], "15373": ["妇人", "孕妇胎动血崩发晕，胎未下而晕先见，是血脱气随、元气欲脱之险候。原文未及脉象，然“血脱益气”四字点明病机：血崩则气无所附，晕为气脱先兆。故舍独参汤别无良药，虽俗见胎产忌参，亦当以性命安危为重而峻补元气。", []], "15374": ["病机", "痢久清利过剂，肛如竹筒、直下无度，脉细濡而色憔悴，是脾肾两亏、元气下夺之候。细濡主虚，濡为湿滞兼虚，久痢滑脱则下元不固。所幸尚能纳谷，胃气未败，故仿胃关煎温补固涩，佐四神丸以收脾肾两脱。", ["细", "濡"]], "15375": ["病机", "秋咳入冬不止，渐潮热脉数、食减肌瘦，是燥伤肺阴、久嗽阴亏之候。脉数非实热，乃阴伤内热、虚火浮动之象。原文引喻西昌“秋伤于燥，冬生咳嗽”，说明诸清润方不应者，缘童质向亏、嗽久阴伤，草木之剂只濡时邪之燥，未及根本。", ["数"]], "15376": ["病机", "脉弦急数，弦主风动，急数主热盛，结合季夏发病、壮热头痛呕吐，显系暑风外袭，邪热内炽。暑为阳邪，风性急迫，故脉弦急而数。舌苔白腻为暑湿初起，继转黄、尖绛起刺，示暑热内陷心包，故神昏肢厥，脉象反映邪势鸱张，有内闭外脱之虞。", ["弦", "急", "数"]], "15377": ["病机", "脉弦数，弦为肝风，数为热盛。患者身热肢凉、昏迷瘛疭，乃暑热内陷心包，引动肝风。脉证俱殆，弦数之脉在此非单纯表热，而是邪已入脏、热极风动之象，与肢凉并见，属热深厥深，故断为不治。", ["弦", "数"]], "15378": ["病机", "脉细，细主虚，亦主湿遏。长夏患病，热盛神昏、舌黄口渴，而肢冷脉细，此非阴寒，乃暑邪内犯心包，热极似寒，阳郁不达，故脉道不利而细。前医误认阴寒用姜附，反致助邪，原文强调“热极似寒，实非阴寒”，脉细正是暑热内闭、正气受困之征。", ["细"]], "15379": ["病机", "原文未识脉名，但述“脉证如故”，结合形瘦质弱、忧劳交集、溽暑发病，症见寒热头痛呕吐，继而神识欠慧、热盛烦躁，显系暑风相搏，正气不足，邪易内陷。虽无具体脉象，从证候推断，脉当见虚数或弦细，主暑热伤气、邪犯心包，故防肝风内动。", []], "15380": ["病机", "脉沉伏，沉主里，伏主邪闭。年高伏暑，形寒怕热、溺短便涩，继而神蒙口牵指搐、目闭溲遗，舌苔干燥黄厚，此暑湿内闭，阳气不达，故脉沉伏。沉伏非虚寒，乃邪热深伏、气机闭塞之象，故有内闭外脱之险，治宜芳香开窍、辛凉豁痰。", ["沉", "伏"]], "15381": ["病机", "脉弦急欠柔，弦主肝，急为燥。右胁刺痛、皮肤如烙、便闭，肺燥金失其柔，木失所制而转刚，故脉弦急不柔。原文谓“金失其刚，转而为柔，致令木失其柔，转而为刚”，辛香苦寒反助燥，脉象反映燥证由肺及肝，非单纯气火，故易治在润燥柔肝。", ["弦", "急"]], "15382": ["病机", "脉散，散主气散不收。三龄儿暑月发热，误投清散，致颏脱音哑、食饮不能，乃元气益漓，肾虚不纳。散脉为真气涣散之兆，故断为肾虚气脱，再行疏泄则肝风慢惊立至。治以左归饮合生脉散，补肾敛气，正合散脉所主之虚脱病机。", ["散"]], "15383": ["病机", "脉虚细涩，虚为气弱，细为血少，涩为血行不畅。患者禀弱，屡服狠药戕胃，又温肝行气活血，胃气益伤，神疲倦卧、痛呕不食、面青自汗，脉象反映气血两虚、胃气衰败，有脱陷之机。故治先救胃，后大补气血，脉虚细涩正是药戕胃气、本元亏损之征。", ["虚", "细", "涩"]], "15384": ["病机", "脉沉细而耎，沉主里，细耎为阴血不足，正虚毒陷，故疽形平塌、溃脓无多、不痛楚，属阴证；后脉迟细欲伏，迟细为阳虚，欲伏为阳气欲脱，面青肢冷、呕恶频频，乃阴寒内盛、阳气衰微之候。", ["沉", "细", "迟", "伏"]], "15385": ["病机", "脉细面青，细为气血两虚，面青为肝风内动之象。患儿头昏、腹痛呕吐便泻，久病胃气空虚，脾虚木乘，故脉细而面青，呻吟疲惫，乃虚风内扰、中气告竭之机。", ["细"]], "15386": ["病机", "脉迟细无力，迟为阳虚，细为血少，无力为气虚。症见单寒不热、肢麻指凉、口吐冷涎、脐腹隐痛、便溏畏食，显系伏寒凝冱、脾阳不振，故脉迟细无力，面白舌润，正合“无热恶寒，发于阴也”之旨。", ["迟", "细"]], "15387": ["病机", "脉伏，伏为阳气内郁、不能外达。患者质亏恙久，新感阴暑，微觉怯寒体痛，然脉伏不见，乃正虚邪陷、阳气被遏之象，故虽新感而不可表散，须参附汤温阳益气，使邪从汗解。", ["伏"]], "15388": ["病机", "脉沉细无力，沉主里，细为阴血不足，无力为阳气虚衰。齿痛甚而形寒足冷，非风热外因，乃虚寒内生、肾阳不足，虚火上浮所致，故用八味地黄汤温补下元，一服痛已。", ["沉", "细"]], "15389": ["病机", "脉虚浮大而数，虚为正气不足，浮大数主邪热外张。夏月病温，先寒后热、头痛汗出、口渴心烦，舌干无胎，乃春温两感，肾水素亏，邪伏少阴，津液劫烁，故脉虚浮大数而舌干涸，病势危急。", ["虚", "浮", "大", "数"]], "15390": ["预后", "脉细如丝，细为气血衰微，如丝为胃气将绝之象。患儿禀质向亏，暑邪发热便泻，久服清散消导，致形疲气馁、食入作呕，脉细如丝，乃胃气告竭、慢惊欲来，故断为不可为。", ["细"]], "15391": ["病机", "原文未识脉名，然述头痛久而不愈，神迷肢掣，手足瘛疭，乃肝风内动之候。患儿先天不足，木失水涵，风阳上冒，辛散更耗阴液，致痛剧而厥，肝风鸱张，故不可救。", []], "15392": ["病机", "脉弦劲欠柔，弦为肝脉，劲为失柔，反映肝木郁滞、失于条达。患者少腹痈起，痛连中脘，呕恶纳减，形羸肉脱，皆肝气横逆、厥阴络脉不和所致。脉证相参，病机为情怀不适，木郁失条，肝病及胃，故见诸痛与呕吐。", ["弦", "劲"]], "15393": ["病机", "脉虚弦劲急，虚为阴虚，弦劲急为肝风内动。孕妇重身九月，头痛呕吐，神迷肢掣，目吊口噤，乃子痫证。原文谓“阴虚火炽，经脉空疏，精不养神，柔不养筋”，故脉虚弦劲急，主精血亏虚、风火相煽之病机。", ["虚", "弦", "劲", "急"]], "15394": ["病机", "脉胃少弦多，弦为肝脉，胃少为胃气不足。患者素体虚寒，腹痛移上脘，气逆呕吐，食不纳，形羸气怯。原文谓“木郁不达，厥阴干犯阳明，肝气逆横，胃降失职”，故脉弦多主肝气横逆，胃少主胃气受戕，病机为肝木犯胃。", ["弦"]], "15395": ["病机", "脉象数犹带弦，数为热，弦为疟邪伏于膜原。患者暑湿烦蒸，感伏膜原，交秋寒热似疟，继则单热不寒，热时口犹作渴。原文谓“秋时晚发，感证似疟之候”，脉数弦主邪伏膜原、少阳不和之病机。", ["数", "弦"]], "15396": ["病机", "脉洪大数疾，洪大为热盛，数疾为邪热急迫。患者风温犯肺，单热不寒，口渴烦躁，嗽痰带血，面目俱赤，舌黄耳聋，汗出热不衰。原文谓“风温犯肺，邪在上焦”，脉洪大数疾主邪热炽盛、肺失清肃之病机。", ["洪", "大", "数", "疾"]], "15397": ["病机", "脉细，细为阴血不足。患者头筋抽痛，口眼歪斜，肢凉，肢掣头昏，心悸汗浆。原文谓“水不涵木，阳化内风，乘虚绕络”，脉细主阴虚血少、内风旋动之病机，非外感风寒，故温散益剧。", ["细"]], "15398": ["其他", "脉如平时，即脉象无明显异常。患者年近八旬，本质阴虚，秋初患痢，延至次春，昼夜十余行，腹痛后重，粪带鲜红，形疲食少。脉如平时说明久痢而脉未显败象，病机为脾虚肠滑、湿热留滞，故以异功散加味治之。", []], "15399": ["治法", "本段未识别脉名，主论齿衄治法。患者齿衄，服生地、丹皮、赤芍、连翘、石膏、升麻反甚，去升麻加犀角即止。原文谓“升麻性升，犀角性降”，借犀角下降之气清心肝之火，使血下行归经。病机为血随气升，故治法宜降火止血。", []], "15400": ["病机", "脉虚大不敛、脉散，为水火失济之候。阳欲上脱，阴不下吸，故脉虚大不敛而散，阴不敛阳。原文云“阳但上越，阴不下吸”，血涌不止，势欲晕脱，脐下热气上冲，皆阴阳相抱不脱之常已失，故主脱证危候。", ["虚", "大", "散"]], "15401": ["预后", "脉弦劲少胃、脉散，为脱证之兆。年近古稀，体虚多忧，久服辛香耗气，又因目盲痰嗽，药伤致心慌晕汗，畏食懒言。弦劲少胃为胃气衰败，脉散为元气欲脱，故曰“脱机甚速”，预后凶险。", ["弦", "劲", "散"]], "15402": ["病机", "本质虚寒，风寒乘虚袭络，颈脊酸痛，喜暖畏寒，欲人揉打。初痛在经，久痛在络，经主气，络主血。督脉并于脊里，寒则泣而不流，温则消而去之。故病机为风寒袭络，非驱风理气所能治，当养血温通脉络。", []], "15403": ["病机", "寒热经年，神采更倦，服温补后痰红不再吐，口不渴。原文引“身大热而反近衣者，热在皮肤，寒在骨髓也”，又云“热之不热，是无火也”，阳维为病苦寒热。脉证合参，总属阳虚无火，阴寒内盛，格阳于外，故当温补益火。", []], "15404": ["病机", "脉沉伏模糊，肢厥声鼾，口鼻气冷，人事迷惑。真元内戕，阴寒直中，阳气外脱，故脉沉伏模糊。阳气若天与日，今冱寒凝泣，阳霾用事，火熄则寂然不动，势属危殆，当用参附回阳救逆。", ["沉", "伏"]], "15405": ["病机", "脉沉细缓，外腴内虚，饮多谷少，恙经三载，发时脘痞嗳噫，小便欠利。酒为熟谷之液，气慓悍，入胃则胃胀气上逆，满于胸中。病虽愈而仓廪之官未复清和，故脉沉细缓，主脾胃虚弱、运化失职，治当调养脾胃。", ["沉", "细", "缓"]], "15406": ["病机", "脉沉细，咳久不已。形寒饮冷则伤肺，肺为娇脏，金寒水冷亦为咳。医者频投滋润清火，适燕指南，药愈服而咳愈频。沉细为脏寒，肺寒内外合邪，故咳不离肺，当温肺散寒，非清火所能治。", ["沉", "细"]], "15407": ["病机", "脉细涩，细为气少，涩主血虚。先天禀薄，情志欠舒，心脾抑郁，月事失调，经期洒淅寒热，腰膂酸疼。冲为血海，任主胞胎，二脉交通乃能有子。脉证若此，冲任亏虚，恐难孕育，治当调养心脾、补益冲任。", ["细", "涩"]], "15408": ["病机", "原文未出脉名，以冲脉为经水之本立论，引《内经》太冲脉盛则月事以时下，说明冲任充盈则经候如期。毓麟珠补益冲任，正合此旨，故本段所主在冲任亏虚、经水乏源之病机，而非具体脉象。", []], "15409": ["病机", "诊得尺虚细涩，寸关大于平时。尺为肾部，细涩为精血不足、脉道不充，故断为肾虚；寸关大于平时，乃阴弱阳浮之象。原文以水火阴阳立论，指出阴精早泄、四十阴气自半，脉证相合，主肾虚阴亏、虚阳上浮之病机。", ["虚", "细", "涩"]], "15410": ["病机", "原文据脉与证断为肾元下亏、水火失济，虽未出具体脉名，然以脉证互参立论。魄汗淋漓、玉关滑泄为肾不固摄，面赤颈热为虚阳上炎，喘咳由肺肾子母相盗，血淋由心热移于小肠，虚里跳动、昔肥今瘦皆虚象，主水火不交、肾虚不摄之病机。", []], "15411": ["病机", "原文未出脉名，据睪肿、少腹形坚痛甚、攻冲腰俞等证，断为奇经受病。引任脉内结七疝、督脉为冲疝之说，又采叶氏冲气从背从腹之辨，说明疝病虽属肝而实冲任督三脉所生，病根深远，主奇经受损、气冲攻痛之病机。", []], "15412": ["病机", "脉沉弦缓。沉主里，弦主疟邪伏于膜原、枢机不利，缓为湿土之象。原文谓暑必兼湿，太阴司天湿土主事，邪伏膜原，外走少阳则为疟，故寒热往来。脉证相参，主暑风湿邪相搏、伏于膜原之病机，与疟证相应。", ["沉", "弦", "缓"]], "15413": ["病机", "原文未出脉名，由多胎自乳、阴血耗损，推及腰膂刺痛、小便血淋痛引少腹，断为血海空虚、损及奇经八脉。冲任起于气街、中极之下，淋痛寒热皆奇经为病，寻常草木无功，故宗《内经》血枯治以四乌鲗骨虑茹丸，主奇经虚损之病机。", []], "15414": ["病机", "此段仅一句，古言病久入八脉，未及脉象。其意为病程缠绵日久，邪气由脏腑气血深入奇经八脉，故久病当从八脉论治。所主为久病入络、奇经受累之病机，属理论提示，非具体脉证。", []], "15415": ["病机", "原文未出脉名，述痱风后元虚未复，腰膂虽能转侧而足膝软弱，断为肝肾真元下亏、八脉不司约束。腰为肾府、膝为筋府，转摇不能、行则振掉，皆精髓亏虚之征；参耆归地仅益气血，未能通及八脉，主奇经精髓亏损之病机。", []], "15416": ["病机", "脉弱质亏，操持多劳，产后少腹痞块，痛于早晨。脉弱主元气亏虚，质亏则血行不畅，瘀血凝结成症，病在血分。任脉循腹里，其病若结，女子瘕聚。久痛攻冲，滋腻非宜，须待元气充旺，始能消磨，急攻反伤正气。", ["弱"]], "15417": ["病机", "时疫十朝，正虚挟邪，神卷耳聋，热发不退，脉息沉细无力。阳证阴脉，原属不宜。邪伏于里，脉多沉细，不同伤寒邪自外来脉多浮大。复诊脉仍虚细，唇齿干枯，舌苔黄燥变黑，邪热真阴之贼，高年肾阴本亏，热甚津液更耗，存津液为第一义。", ["沉", "细", "虚"]], "15418": ["病机", "卫虚恶寒，营虚发热，日晡寒热往来数月，洵为营卫二气之虚，非客邪外感。病属虚当补，昨服补剂胸鬲反增滞闷，乃胃气不行药力。上损过胃，下损过脾，虚痨不足当与甘药。两进甘药寒热依然，惟粥食稍增，咳嗽略缓，补虚关键以脾胃为主脑，土母倾颓难输化药力。", []], "15419": ["病机", "恙经半载，脉证合参，质亏烦劳，坎离不交，水火失济，五液内涸，虚阳不藏。脉大为劳，为真气泄越。误服苦寒重伐胃气，诸证蜂生。劳伤之火，虚乎实乎，泻之可乎。阴虚之火如盏中油干灯焰自炽，须以膏油养之。然食少欲呕，脘闷不快，难强投滋腻，惟培养脾胃，默运坤元。", ["大"]], "15420": ["病机", "两寸关脉候俱大，左关尤急。情志抑郁先见此脉，心烦不安，咳嗽不止，舌苔时黄时退。肝为受病之源，肾为传病之所。肝阳吸引肾阴，如折花枝插瓶，瓶水日为吸干。肺为肾母，子虚盗母气，金不制木，木反侮金。肝阳上升冲心为烦，冲肺为咳，脉大不敛，阳亢阴亏。", ["大", "急"]], "15421": ["病机", "水肿面目无缝，阴大如栲，小水点滴不爽，切脉沉细模糊，苔腻白滑，不渴。肾气虚则水泛为肿，沉细模糊为肾阳衰微、水气不化之象。前医开鬼门、洁净府、五子五皮、肾气法皆不效，盖徒治水而不温肾气。益气阳送肾气丸，温肾化气，气行则水行，服之竟验。", ["沉", "细"]], "15422": ["病机", "产后十朝，发热昏冒，肢掣烦躁，夜卧欠安，脉息数大无力。断非蓄瘀风邪，显属阴伤血耗。数大无力为血虚阳浮之象，百脉空虚，心脾两虚。血生于心，统于脾，脾虚肌肉发热，心虚神明失藏。黑归脾汤补心脾、益气血，对证之药。", ["数", "大", "虚"]], "15423": ["病机", "厥证分别阴阳虚实，病由情怀不释，肝失条达，血气日偏，阴阳不相顺接，因而致厥。脉应带滑，脉细兼弦涩，为情志郁勃、气血郁滞之象。与全虚全实者有间，理偏就和，宜用其平。妇人常有，昼夜频发则阴阳脏气俱伤，乍发乍止疏而且轻无妨。戒怒舒怀，惜劳静养。", ["滑", "细", "弦", "涩"]], "15424": ["病机", "原文未出脉名，以“厥来”言肝气上逆之病机。五行木克土，肝气顺乘阳明，故脘中有块、按之则痛、食下阻滞，皆肝犯胃、胃失和降之候。气药多燥而肝阴胃液已亏，故治先理气兼护阴，佐桑叶泻肝胆郁热，乙癸同源以补肝母，待痞消厥定再作善后。", []], "15425": ["病机", "脉虚弦带急，虚为质亏，弦急为肝风内动之象。烦劳抑郁则水不涵木，肝风上扰清空，故头痛乍轻乍重、精神欠充、夜寐少逸。非外因寒热，乃身中阳气化风，迅速如风火，发散寒凉皆非所宜，当以阳和熄风、滋苗灌根，即下虚上实、病疗下之法。", ["虚", "弦", "急"]], "15426": ["病机", "原文以“脉尚和平”与“脉必浮大无根”对举。脉和平则非真阳飞越，乃肾元下虚、水不生木、肝风鸱张，发时状如中厥；若雷龙不藏则脉必浮大无根、烦躁无暂安时。温补药重激动肝阳，肝风扰胃，故胸胀呕吐、不饥不便，治当制肝安胃、介潜酸敛。", ["浮", "大"]], "15427": ["病机", "脉大不敛，为阳虚不能固摄、精气本虚之征。旧病喘汗，复因烦劳水火不交，气随血脱，故吐多不止、鼻衄痰红、口苦食减、头昏气促。此非寻常肝肺之火，清降则损真致阴阳离决，故从黑归脾培养心脾、生脉保金摄纳肾气，服后血止脉敛，正合“见血休治血”之旨。", ["大"]], "15428": ["病机", "脉数不静，为阴不恋阳、水不制火之象。血去阴伤，金燥秉权，肺被火刑，故肌肉咽干、呛咳不能正偃、咳甚血来。冲为血海，冲脉动则诸脉皆动，下焦阴火上逆，血随火升，故胸脘烦冤即咳频血溢。火在丹田为少火，出丹田为壮火，壮火食气，欲止血须止嗽、熄火，非寻常清火可治。", ["数"]], "15429": ["治法", "原文仅载“拟一阴煎，加青铅山萸，收纳冲脉之逆”，未出脉象。此为承前冲脉上逆、阴火上炎之证而立治法：一阴煎滋阴，青铅镇降，山萸酸收，共奏收纳冲脉逆气之功，属滋水制火、引逆下行之方，非主病脉象之论。", []], "15430": ["病机", "脉见弦急，为邪郁未解、正气受亏之象。寒热仍来、口不渴、怕风，盛夏姜附四剂无火象，属阴暑正虚邪留。由阴转阳则脉弦急，为顺机；汗出热退而脉仍弦急、舌苔转黄、疮刺俱见，是寒邪化热，恐热盛伤阴，故酌补阴益气，辅正驱邪，中病即止。", ["弦", "急"]], "15431": ["病机", "原文未出脉名，以“虚里跳动”“一派虚象”言病机。喉痛叠进清凉，伤及脾胃，舌强语涩、食少形疲、头昏足麻，皆肾真下虚、水不涵木之候。午后口眼歪斜、心悸肢掣，为内风鼓动、痉厥之险，故用复脉甘缓，并虑清凉过度伤胃，以胃气为本。", []], "15432": ["病机", "脉急未和，示暑热伤胃阴后，正虚邪留，脉道未复柔和；脉大稍敛，为热缓而气阴渐伤。原文谓“正虚邪留”，热久呕多，形倦少神，不独伤阴亦复伤气，故脉急大而不静，主暑热内伏、气阴两伤之病机，与神昏齿噤、舌苔黄腻等症相应。", ["急", "大"]], "15433": ["病机", "脉空虚为暴崩气随血脱、久崩血耗阴伤之象。原文引“阴虚阳搏谓之崩”，又言“气为血之帅”，暴崩则气脱，久崩则阴伤，故脉空虚不实。主冲任不固、气血两亏之崩中病机，与晕汗、躁热诸证相应。", ["虚", "空"]], "15434": ["病机", "脉虚近数，为形瘦阴亏、脏真内伤之征；脉动甚者，原文辨非孕子，乃阴虚阳动、虚劳内热之象。经停九月、失红三次、咳嗽汗多食少，皆阴亏火动、脾肺俱病之候，故脉虚数而动，主虚劳血痹、阴亏阳扰之病机。", ["虚", "数", "动"]], "15435": ["病机", "此段未出脉象，专论女子以血为主、冲任为要。原文谓“胃为冲脉本，故阳明气旺，则月事行”，先生以育阴调胃为法，良由冲任隶于阳明。所主病机为冲任血虚、阳明气弱，致月事不调，治当养血培中，与脉象无直接对应。", []], "15436": ["病机", "此段未出脉象，系按语辨暑邪犯心肝之机理。原文谓暑邪由肺逆传，肺病则肝无所制，故手足制动；又言邪入下焦阴分，日久方见肝风。所论为暑邪传变、肺肝同病之病机，非以脉断证，故脉象要素从缺。", []], "15437": ["病机", "脉濡无神，为阴阳衰惫、邪正交争之象。年届五旬，心事内伤，兼挟外邪，误药因循，邪留不解，故脉濡软而神气不充。原文谓“邪陷正亏”，汗多头晕、交午寒热，非传经少阳之寒热，乃正虚邪陷、元气不守之病机。", ["濡"]], "15438": ["病机", "脉细濡，为脾虚酿湿、阴络受伤之征。始而便泻，继则下血，辛温动血，清凉减食，故脉细濡不充。原文谓“脾为血之统”，刚燥过剂则内溢不已，养阴腻滞又碍脾胃，主脾虚湿盛、统血失职之病机，与食少欲呕、形疲心愦相应。", ["细", "濡"]], "15439": ["病机", "脉虚身热，经云得之伤暑，暑伤气故倦怠口渴；脉仍虚急，为热甚心烦、夜不安寐，气阴两伤而阳不潜藏；脉散者，则元气欲脱之兆。病躯加受暑邪，形倦肤干，热熇溲数，主暑伤气阴、正虚邪恋之病机，脉散尤示预后堪虞。", ["虚", "数", "急", "散"]], "15440": ["病机", "原文诊得「脉不数」，且无风消息贲、寒热咳嗽等痨瘵兼证，说明病非阴虚火旺之痨瘵。脉不数则热象不显，结合呕吐日久、经闭，病本在呕吐，致仓廪失藏、气血不流。脉不数正是排除痨瘵、确立以呕吐为本的关键脉证。", ["数"]], "15441": ["病机", "原文「脉不细数」与痨瘵阴亏阳升之脉不符，故屡治无效。饮食如常、脉不细数，说明非内伤虚损，而是外邪入肺、胶黏酝酿、郁热伤津之「因病致虚」。脉不细数正是辨明病源在肺、非纯虚劳的要点。", ["细", "数"]], "15442": ["病机", "半产后气随血脱，脉「急无力」「右脉虚要」，又见热发不退、怯寒、舌白喜热饮，显系气血两虚、阴阳两亏，正气不胜。脉急无力为虚象，非实热；纵有外邪，亦当以甘温除大热，不可妄攻。", ["急", "虚", "数"]], "15443": ["病机", "孕妇脉来滑数，为热象；证见便溺不通、二阴牵胀、足膝浮肿，乃肺热金燥、清肃失降，二肠交阻。滑数主热，热壅肺气，水道不利。治当清肺润燥，气行则壅通，非滋阴疏利所能解。", ["滑", "数"]], "15444": ["病机", "鼻渊数载，脉「数大无力」，是恙久阴虚阳浮，非新病实热。数大为热象，无力为虚，故苦寒伤胃非宜。热胜则肿，溃口不收，皆阴液受伤、虚火上炎所致，治宜壮水保金，使水升火降。", ["数", "大"]], "15445": ["病机", "原文未识脉名，但述「色悴神疲，喝喝不继」，结合喘证，明是气本弱、元本亏。肺主出气、肾主纳气，金水相生。喘生毋耗气，若以耗散收功，则抱薪救火，脱机甚速。此段重在阐发喘证虚损病机及误治之害。", []], "15446": ["病机", "脉大而急，证见呛咳气筑、胸满背胀、夜卧气冲、目烂舌赤，是肺感燥邪、抑郁痰结、肺窍阻闭，酿成肺痹。脉大急为邪实气逆之象，诸气𪱥郁皆属于肺，故补剂不投，当清燥宣痹。", ["大", "急"]], "15447": ["病机", "原文未识脉名，专论妇人月经反常之因。血生于心、藏于肝、统于脾，冲为血海。血枯者木郁生火、火灼阴伤；崩决者阴虚阳搏、阳气内动。此段从脏腑气血阐发调经病机，强调经调则百病不生。", []], "15448": ["病机", "原文未明言脉象，但述行痹由风寒湿杂至、风气胜所致，右膝痛引腿胛渐移于左，属风邪流窜。童质禀薄，肾元未充，过用桂麻羌独驱逐，血气受亏，肝筋失养则挛急，脾肉失煦则枯瘦，终致腓干髀肿、足不任地。此论强调驱邪过猛伤正，酿成废疾，病机在气血亏虚、筋脉失养。", []], "15449": ["病机", "脉虚近急，虚为元亏未复，急为寒热愈而复作、邪正交争之象。原文谓“脉虚近急，是属节外生枝”，非本证变幻，乃质虚加感、腠理空疏所致。寒热偶然发作，状洒淅亦不若内伤之重，且大便旬余未解，腹中欠舒，病由湿凝气滞、胃腑欠和，故脉虚急示正虚邪扰、输化失职。", ["虚", "急"]], "15450": ["病机", "脉俱沉象，沉主里、主伏邪。时热四日，头痛身热，舌苔腻白，胸闷，口干喜热饮，症似表而脉不浮，知邪不在表，已伏于募原。募原为半表半里之地，湿浊痰热阻遏，气机不畅，故胸闷苔腻；热饮自救，亦湿郁之征。脉沉与症合，断为邪伏募原，非单纯外感。", ["沉"]], "15451": ["病机", "脉象惟有细数，细为阴血不足，数为余热未清。午后大汗因棉被过遏，非虚脱之汗；病者清爽、问答明白，表邪已从汗解，里热亦渐退。然脉细数示汗后津伤、余热留恋，故无虚脱之象。原文强调“察脉审证”，凭脉细数断非虚脱，汗解后当清其余热，勿轻信旁言。", ["细", "数"]], "15452": ["病机", "左寸关数而带滑，数为热盛，滑为痰壅。时热半月，人事不知，狂叫呼骂，不避亲疏，显系热邪入里，痰火壅闭心肝之窍。左寸关候心肝，数滑并见，正合痰火内闭、神明扰乱之机。故治当清心肝之火，佐开窍豁痰，以图转机。脉症相参，病机昭然。", ["数", "滑"]], "15453": ["预后", "原文未载具体脉象，仅言“筋脉渐有活动之机”。服前方并敷药后，膝盖温暖松爽，稍能伸，右膝坚硬渐软，此乃药后气血渐通、筋脉得养之象。前段论行痹因驱邪过猛致废，此则治后活动有机，属预后向善之征，故列预后。", []], "15454": ["病机", "左关虚弦，两尺虚数。左关候肝，虚弦为肝阴不足、相火不静；两尺候肾，虚数为肾水亏虚、水火未济。右耳常鸣七载，正是肾水不能上济心火，相火妄动，循经上扰清窍所致。脉症合参，病机为水火未济、相火未静，治宜养水济火，使火降鸣平。", ["虚", "弦", "数"]], "15455": ["病机", "脉象虚弦，虚为脾虚气弱，弦为土虚木乘、气机壅滞。病后脾虚，四肢面目浮肿，腹大脐凸，肿及阴囊，鼓胀将成，舌旁紫红胎两条，夜睡不久即醒，腹胀兼疼，食饮稍减。脾虚失运，水湿泛滥，肝木乘土，气血瘀滞，故脉虚弦。此将成鼓胀之候，幸未过投杂药，尚可挽回。", ["虚", "弦"]], "15456": ["病机", "风痰上壅而喘哮声急、气逆不能卧，脉象沉细，说明痰气壅阻于里，气机不得宣畅，故脉沉；久病正虚，脉道不充，故脉细。沉细非表证之浮，提示病本在里，风痰上逆、气逆不降，与喘哮、不得卧相应，故议代赭旋覆法降逆化痰。", ["沉", "细"]], "15457": ["预后", "原文未载具体脉名，仅言“服后喘定哮平，脉亦渐起”，以脉由沉细不起转为渐起，说明药后气机渐通、正气渐复。喘哮既平、脉能渐起、进粥安妥，皆为向愈之象，故再剂而痊，属预后转佳之判断。", []], "15458": ["病机", "身热有汗五日未解，脉象浮缓，浮为风邪在表，缓主湿滞、亦主胃气不充；兼腹膨，是食饮中停于里。风邪外束而食滞内停，表里同病，故脉浮缓而不数不紧，治宜表里疏通，俾邪外达。", ["浮", "缓"]], "15459": ["病机", "腰腿酸痛偏于右畔，寒湿内郁，阳气不运，故脉沉迟；病偏右侧，故沉迟独见于右。沉主里、迟主寒，寒湿凝滞经络，气血运行不畅，与腰腿酸痛相应，法宜温通以散寒湿。", ["沉", "迟"]], "15460": ["其他", "此段为肩痛筋脉抽掣治验的案题及附药酒方，原文未载脉象，故无从论脉。所述两肩疼痛、筋脉抽掣，属寒湿郁于经络、筋脉失养之候，本条主旨在于记录治验与方药，不涉脉象病机分析。", []], "15461": ["病机", "两肩疼痛不能举动，筋脉抽掣，病经半载，脉象虚细。虚细为气血不足、脉道不充之象；寒湿郁于经络日久，正气渐伤，故脉虚细而非弦紧。脉症合参，知正虚邪恋，先宜温疏，再商善后。", ["虚", "细"]], "15462": ["病机", "右寸关细数而滑，左关尺弦细。细数而滑主痰火内蕴，弦细主郁、主饮。痰火郁闭，升降不灵，上逆则蹙頞头摇，下奔则转脬甚急，脉与症合，故用黄连汤合小陷胸汤加减清化痰火、调畅升降。", ["细", "数", "滑", "弦"]], "15463": ["病机", "大便已解，体虚脉耎，耎即软弱无力，与虚脉同见，说明邪去而正气未复，气血不足、脉道不充。故用六君子汤去白术，加山药、杜仲、木瓜、怀牛膝、建莲肉健脾益肾、强健腰膝，服后可以起身，稍可步行。", ["虚", "耎"]], "15464": ["病机", "原文谓「色滞顶平，脉象虚数，毒火未透」，虚为正气不足，数为毒火内郁，正虚而火不能外达，故痘毒难透。色滞顶平亦示气血不畅、托毒无力，故仍宜升散，以助正气托毒外出，非单纯清火可解。", ["虚", "数"]], "15465": ["预后", "原文「平者渐起，滞者渐活」示痘势有转机，但「脉虚无力」，正气不足，恐行浆时不能充足。脉虚无力为气血亏虚之象，痘疮行浆需气血充盛以化毒成浆，正虚则浆难充盈，故预后须防浆不足而变证。", ["虚"]], "15466": ["病机", "喘咳旧疾复发，痰厚喘急不能卧，喉中水鸡声，为痰饮壅肺、气逆不降。脉沉细而滑，沉主里，细为饮邪阻遏、脉道不利，滑主痰湿。痰饮内伏，肺失宣降，故喘急不能卧；心中热闷不渴，亦痰湿内郁、热不外达之象。", ["沉", "细", "滑"]], "15467": ["病机", "原文「兼参色脉」未明言脉象，然述体肥多痰、好饮浓茶、喜啖厚味，断为「脾中之湿热素盛，胃中之湿痰常存，兼挟湿郁之火而上升头项，发为湿毒」。湿毒浸淫后项，滋水淋漓、痛痒出血，穴近太阳而关乎脾胃，故先以表里双解。", []], "15468": ["误治", "原文列「脉数、躁烦、口干咽痛、面赤火盛、阴虚内热等症，俱不宜灸」，脉数为火热内盛之征，灸法助阳，反以火助火，故「不当灸而灸之，灾害立至」。此段借脉数说明灸法禁忌，属误治警示，非论病机主病。", ["数"]], "15469": ["其他", "原文述灸后「气脉温和流通，越灸越快」，引《灵光赋》「灸时气下砻砻然如流水之降」，此脉温和流通为灸法得气、气血畅行之征，非病脉。兼内服煎剂后湿痰止、呕哕平、食增卧安，示内外调治见效，故列其他。", ["缓"]], "15470": ["治法", "原文未言脉象，专述方药配伍：内用六味地黄丸以猪苓易茯苓，固里入阴兼通督脉；外用六君子合玉屏风散为衣，固表通阳。合而用之「表里两固、气血并调」，属治法范畴，说明内服外用相配以固本通阳。", []], "15471": ["预后", "原文未明言脉象，述串疬有年，初从足小腿广疮起，疡科攻伐太过致腹痛便泄、本元日亏，后颈发瘰疬溃烂不合，又结核坚硬，兼屡屡梦泄、上腐下遗，牵连两载。断为「从外走内，由浅入深，一转虚损，尤难许治」，属预后判断。", []], "15472": ["病机", "原文未出脉名，仅言「察脉审证」「色脉合参」，强调瘰疬成因有湿痰、湿火、风毒、热毒、气弱血滞、阳虚阴亏、纵欲火窜之异。其病机关键在「下焦阴亏，相火与湿毒相绊」，木生相火挟湿毒上升项侧，故结为贯珠、梅核之状。脉当随标本虚实而辨，不可执一，示人凭脉分因、审标本缓急以定治。", []], "15473": ["预后", "痘疹热起至收完，专看右手一指脉。洪大有力，为气血尚充、毒能外达之象，故「虽有别症亦不为害」，属可治可期之脉。若洪大中兼虚散无根，则非此论。原文以此为「定存亡之要诀」，是从脉之有力无力判断正气能否胜邪、痘毒能否透发，故归预后。", ["洪", "大"]], "15474": ["病机", "右寸关浮缓，左尺浮小。浮主表邪，缓属风与湿，寸关应肺胃，故知足太阳受邪而兼肺胃；太阳经脉上通巅顶，邪客则巅顶痛、鼻塞、目眶疼、齿浮痛。左尺浮小示下元不足。因每早远行冒风而得，脉证相合，凭脉断因，非臆测也。", ["浮", "缓", "小"]], "15475": ["病机", "两关弦硬，肺脉短促。关候脾胃，弦硬为戊土壅滞、卯木横冲之象，土壅木贼，故食减呃增、多涎痰；肺脉短促，是痰湿阻遏、肺气不畅，浮肿虽退而气机未和。原文谓「大非所宜，当静养调摄，以免变迁」，正虑土败木横、肺气受困，故议四君子合左金以扶土清木。", ["弦", "硬", "短", "促"]], "15476": ["病机", "原文论呃逆即哕，本于「胃气逆为哕」。其机在胃土伤损，木气侮之，为土败木贼；阴为火乘不得内守，木挟相火直冲清道而上。然呃有虚实寒热表里之不同，未可概论，故须「临时切脉审证」。此段虽未出具体脉名，却明示凭脉辨呃之虚实寒热，属病机与辨证纲要。", []], "15477": ["病机", "右寸关沉滑而细。沉主里，滑主痰，细为湿滞血少。寸关应肺脾，故断为「湿痰为患」。背心酸疼三载，正痰湿阻于脾肺、气机不利所致。前医屡试不效，因未得其窍；今就脉论治，拟胃苓汤法，燥湿化痰、运脾利气，使湿去痰消而酸疼可解。", ["沉", "滑", "细"]], "15478": ["病机", "此丸方段承前案，证脉合参而言病源。酸疼见于三椎肺穴，然「揆其源则受累于脾土者居多」。土虚生湿成痰，痰湿交阻，脾阳不运则肺金愈弱，外易冒风，内则痰凝湿郁，故背心酸疼波及肩臂腰脊。虽未列脉名，实以脉证互参定脾肺虚实之机，服煎剂减半后继以丸缓图。", []], "15479": ["病机", "风疹八载，不时举发，肤热燥痒、色红成块，甚则小腹㽲痛。脉浮弦，浮为风邪在表，弦主风动、亦主痛。风热郁于血分，外搏肌肤则疹块燥痒，内扰则腹痛。故治宜凉血疏风，使血凉风散，疹块自消。脉证相合，明示久病风疹之病机在血热挟风。", ["浮", "弦"]], "15480": ["病机", "右寸虚浮，左关尺虚濡，虚浮为卫气不固，虚濡为营血不充。卫外不固则易冒风，营血不足则血热生风，外风引动内风，故肤热痛痒、风疹随起。原文谓“风独不利于血热之人”，正指营虚血热之体易召外风，治宜固表养血，血行风自灭。", ["虚", "浮", "濡"]], "15481": ["治法", "本段未载脉象，仅言“色脉合参”后以清火解毒之剂兼五宝丹内服。色脉合参示凭脉辨证以定火毒之机，故用清火解毒直折其热毒，土茯苓汤调送五宝丹，日三次，属针对火毒内蕴之治法，非单论脉。", []], "15482": ["误治", "右脉软小乏力、左脉濡虚，为阴阳两虚之象。友人传种子壮阳方，多纯热兴阳助火燥药，阴亏者服之助火耗阴，阳虚阴弱者亦非所宜。原文强调“阳密乃固”，阴阳不和则如春无秋、如冬无夏，故力阻其服，属警示误服温燥之误治。", ["软", "小", "濡", "虚"]], "15483": ["病机", "左脉弦硬、尺稍涩，右寸关虚细、尺浮无力。弦硬为肝木偏亢，涩为血少，右寸关虚细示脾肺气虚，尺浮无力为肾虚不摄。合色黄晦暗辨为阴黄在脏在里，病关脾肺、波及肝肾，故脉见虚细弦涩并见，主本虚标实之机。", ["弦", "硬", "涩", "细"]], "15484": ["病机", "本段未录具体脉象，以“色脉合参”立论。疸经两载，久用清热利湿攻伐太过，致脾阳不运、肝肾有亏，故溲赤。原文虑“脾土败而肾阳亏”生中满之变，主张虚则补母，使脾阳运动、肺气通调水道，肾水不凌土、肝木不侮脾，不治黄而黄自退。", []], "15485": ["病机", "本段未载脉象，以“证脉合参”断为肝阴有亏、肾水不足。水不涵木则虚风内生，风疹经年不愈。治以壮水滋木、养血润燥，兼用补气之品，因气能生血而血不能扶气。全段重在阐发肝肾阴亏、血燥生风之病机与治法。", []], "15486": ["病机", "右关细而软，左关尺濡小兼数、按之不足。细软为脾虚，濡小为阴亏，兼数为阴虚有热。素有内痔脱肛，纵啖西瓜，暑热为寒凉所逼，脾土受伤而中气下陷于至阴之地，故脉见右关细软、左尺濡小，主脾肾同病、气陷阴亏之机。", ["细", "软", "濡", "数"]], "15487": ["预后", "脉来细数，细为阴血不足，数为虚热内扰。幼年咳呛痰红，细数之脉示阴虚火旺、灼伤肺络，最防渐成虚怯之证。原文谓“速于调治，尚可图维”，以脉细数判断预后，强调及早调治可挽，属凭脉论预后之段。", ["细", "数"]], "15488": ["病机", "外邪已解而夜热晨退，脉见濡小，濡为湿滞、小为阴血不足，合而示阴分素亏、余热未清。邪去而正虚，故热势轻微且随昼夜起伏；濡小非实邪之象，恰说明当以养阴退热为治，不可再事攻散。", ["濡", "小"]], "15489": ["病机", "右数急为卫虚营亏、虚热内扰，左弦劲为肝木失养、阳不潜藏。患者素体薄弱，幼有鼻衄风疹，成婚后少不节欲，盗汗腰疼并见，正合卫虚营亏之候。数急弦劲并见，说明阴亏于下而阳扰于上，故先议固表养血。", ["数", "急", "弦", "劲"]], "15490": ["病机", "左右脉来弦数而急，弦属肝木，数为火象，急则气逆之势。金虚不能平木，肝火上逆，木来乘金，故鼻洪复发而兼咳嗽。脉之弦数急正是肝火亢逆、木侮肺金的明征，与衄血咳嗽相应，故治法当清肺养肝。", ["弦", "数", "急"]], "15491": ["病机", "数象稍缓示虚热渐退，汗止咳减；而弦急之势未平，说明肝木偏亢的根本未除。原文点明「弦主于肝」，故治法宜清肺以养肝，使肺气旺则木不侮金，金足生水、水能养木而木自平，正合隔三之治，脉象变化与治法相应。", ["数", "缓", "弦", "急"]], "15492": ["病机", "盗汗、咳呛未已而脉仍弦急，弦为肝旺，急为气逆，说明肝木亢盛、金受其侮的病机仍在。汗出伤营，咳呛损肺，脉不急缓而仍弦急，是邪势未衰、正虚未复之象，故以益气养营为治法，从本图之。", ["弦", "急"]], "15493": ["病机", "左右寸口弦劲为火乘金，两关弦急为木侮土，左尺虚数为水不足。水亏则木失所养，肾阴亏则肺金愈虚，故鼻衄、咳呛、盗汗常发。原文谓「脉仍未平，攸关心病，有诸内而形诸脉」，说明脉象未复即病本未除，不可强留异地。", ["弦", "急", "劲", "虚"]], "15494": ["其他", "本段详述当脐作胀、午后为甚、痰黏口干不喜饮、饮酒则上焦觉热等症，并历数前医香燥破气、纯用滋阴腻补及知柏地黄加破气之误。原文未明写脉象，仅言「证脉合参」，故脉象要素无从摘取，主旨在于剖析久胀不瘳之由，属其他类。", []], "15495": ["治法", "本段仅言「证脉合参」，未出具体脉象，故脉象要素为空。其主旨在于确立治法：于滋肾养肝中寓补火生土，以治其本。结合前段当脐作胀、痰黏口干之症，可知其意在培补下元、温养中土，使胀满自消，属治法类。", []], "15496": ["病机", "右脉虚软，左脉虚弦，面白无神，盗汗淋漓，气逆痰稠且腥，此脾肺气阴两虚，肝木乘虚而亢。寒热咳嗽日久，误用清肺，更伤肺胃，致肌肉日削，食饮不贪，痰腥防痈痿。虚软为气阴不足，弦为肝郁，木火刑金，故咳呛日盛，危险极矣。", ["虚", "软", "弦"]], "15497": ["预后", "服前方后气逆稍缓，但脉仍如昨，说明病机未变，虚软弦之象依然。气逆暂缓仅属症状小效，而脉象未改，示根本未复，痰热未清，正虚未复，预后仍当谨慎调治，不可因小效而松懈。", []], "15498": ["病机", "右关尺虚软无力，关候脾，尺候肾，虚软为不足之象。素喜浓茶，又服滋阴，更伤脾阳，致脾阴弱而肾阳不足，脐下作疼，食饮渐减。脾肾阳虚，气化不行，恐成中满，故当及早温补脾肾，扶阳化气。", ["虚", "软"]], "15499": ["病机", "右寸浮数，左关弦数。右寸候肺，浮数为肺有风热；左关候肝，弦数为肝火偏亢。目珠松爽而白珠红未退，乃肝肺火未清，风自火出，故流泪。脉症相合，当清肝肺之火，兼散风邪。", ["浮", "数", "弦"]], "15500": ["其他", "合参色脉，阴亏痰结，内服养阴化痰软坚，外用艾灸，半月而疬消。此段未明脉象，但以色脉合参断为阴亏痰结，灸法取效，说明病机为阴虚痰凝，非单纯攻散所宜，当养阴化痰软坚并施。", []], "15501": ["病机", "脉象虚数，虚为阴亏，数为温邪。素体阴亏，温邪内陷，乍寒乍热，两颧甚红，舌苔边白中黄，误投滋阴腻补，邪热愈陷。虚数之脉示正虚邪盛，邪烁真阴，劫夺胃津，势属重险，治宜育阴祛热，复脉汤法。", ["虚", "数"]], "15502": ["病机", "脉象虚滑，虚为正气不足，滑为痰湿内蕴。间日疟后胸腹满闷，口吐稠痰，大便十日未解，此脾虚痰湿壅滞，气机不畅。前医寒凉过抑，热药居半，致痰湿胶结，虚实夹杂，当辨脉审症，不可草菅人命。", ["虚", "滑"]], "15503": ["病机", "痢久而得虚弦之脉，左关不弦而反弦于右关，肝木乘脾，克伐脾土。肠胃伤而肺脾肾肝俱累，肝气上冲清阳扰乱，下泄浊阴留连。病已九月，补气助邪，理气伤正，治当化气调阴阳，使氤氲化醇。", ["弦"]], "15504": ["病机", "右关虚大，主脾虚不运，湿浊内蕴；左关浮弦，主肝木偏旺。脾虚则运化失职，湿郁化热，蕴久生虫，故见腹外膨内坚、便溏溲赤、手足心热。色脉合参，断为脾虚积蓄、湿郁虫生之虫蛊证，治以扶土疏木、佐以调运引虫。", ["虚", "大", "浮", "弦"]], "15505": ["治法", "原文未出具体脉象，仅言「色脉合参」，以脉证互参定治法。补脾以固后天之本，和肝以平木亢，佐祛积引虫以除宿积。脉象虽未明载，然由前案虫蛊之证推之，其脉当不离脾虚肝郁之象，故治法以稳当为要，不骤攻伐。", []], "15506": ["预后", "原文未载脉象，仅言「证脉详谛」。昨以辅正驱虫法下虫九条，形色若鳖，知虫积未尽。详审证脉，尚有残留，故仍宜固本养胃，少佐祛虫，攻补兼施。此段重在据脉证判断虫未尽除、须缓图收功，属预后调治之论。", []], "15507": ["病机", "原文未出脉名，然「察脉辨色」而知积虫满腹。虫积日久，脾愈伤胃愈弱，积愈滞虫愈增，故见颈细腹胀、食减体羸、脐突筋青、时痛时止、好啖生冷肥甘。脉虽未明言，由证推之当见脾虚积滞之象。深悉脾土久亏，不敢骤攻，必先调元辅正。", []], "15508": ["预后", "六脉虽洪大，然冲阳脉尚平，右关虚大无力，知洪大为胃气外浮之假象，冲阳平和则胃气犹存一线生机。脾胃久亏，纵啖生冷肥甘，积蓄虫生，故头大颈细、腹膨筋青、脐突面黄、呕出红扁怪虫。凭冲阳未败判为可治，属预后判断。", ["洪", "大", "虚"]], "15509": ["其他", "此段为答客诘问之辞，未载脉象。强调「因脉定证，因证制方」，反对执古方以治今病，主张学古而不泥古。脉象虽未出，然其旨在于凭脉辨证、随证制方之理，非论具体病机，故归其他。", []], "15510": ["病机", "脉形细涩，细主血虚，涩主气血凝滞不畅。风寒湿三气杂合而成痹，气血凝滞，筋脉失养，故右腿疼痛、大筋急缩、足不任地、屈而不伸，渐成鹤膝。新婚之后阴血暗耗，更非所宜。脉细涩正合血虚寒凝之痹，法当养血佐温疏。", ["细", "涩"]], "15511": ["主病", "右脉紧滑，紧主寒邪收引，滑主食积痰滞。大腹疼痛而右脉紧滑，乃感寒夹食之征，寒凝气滞、食积中焦，故腹中作痛。治宜温疏以散寒、运食以消积，紧滑并见正合寒食交阻之病机，故以温疏运食为主。", ["紧", "滑"]], "15512": ["预后", "原文述服药后寒热轻、口不甚渴、大便解结粪成条、胸闷渐宽，脉之弦滑者亦渐平，说明邪退正复。弦滑主痰饮、气滞，今渐平则痰化气畅，故为向愈之兆，与胸闷宽、便通相应。", ["弦", "滑"]], "15513": ["主病", "时值七月，头胀身热欲呕、苔腻黄，脉浮小。浮主表邪，小主湿阻，风暑夹食，邪郁肌表而食滞中焦，故脉浮小。治宜清疏，疏风清暑兼消食滞。", ["浮", "小"]], "15514": ["病机", "秋令感寒停食而腹痛旧恙发，气口脉紧滑。紧主寒邪收引，滑主食积痰滞，寒食交阻中焦，气机不通，故脉紧滑。速宜疏通，防转寒热，即防邪郁化热。", ["紧", "滑"]], "15515": ["病机", "脉沉数，暑湿热内阻，秋凉外袭，邪闭中宫，致头疼腹痛呕泻、胸闷溲短，霍乱之征。沉主里，数主热，暑湿热郁遏于里，故脉沉数。当和其中，俾邪解湿降。", ["沉", "数"]], "15516": ["病机", "卒然昏默、流涎、语蹇、目呆鼾睡、肢冷，脉浮小而软，左关弦，右关滑。浮小软为正气虚，弦滑为风火痰升，外风引动内风，类中之征。故拟调卫和荣、顺气化痰。", ["浮", "小", "软", "弦"]], "15517": ["预后", "服后神识渐安、痰减、手足活动、溲便如常、可进粥，语言似清非清，身畏寒，脉形如昨。脉象未变而症减，示邪渐退而正未复，故原方加黄耆、防风固表祛风，畏寒渐止。", []], "15518": ["病机", "喘咳有年，发则气逆痰壅，脉右寸软小不疏，关滑数，左尺濡小按之无力。软小濡小为气火虚，滑数为痰火实，虚实夹杂，痰火不易出。故治本为主，少佐治标。", ["软", "小", "滑", "数"]], "15519": ["主病", "上下齿痛不止兼头胀，脉浮缓小数。浮为风，数为火，缓小示风火相搏而正气不足，风火循经上攻齿龈头目，故齿痛头胀。用蔓荆、甘菊、薄荷疏风，元参、生地清火。", ["浮", "缓", "小", "数"]], "15520": ["病机", "原文未载脉象，然述“胸背疼痛，咽嗌不爽”，断为“气闭痰凝，脉络不利”。气机闭阻则胸背痛，痰凝络脉则咽嗌不爽，故用瓜蒌仁、丝瓜络、半夏曲等化痰通络。此段重在阐发气痰交阻之病机，非凭脉断证。", []], "15521": ["主病", "脉象浮小，浮主表邪，小为正气不足。症见畏寒发热、无汗、舌白腻，乃冒风受凉，邪郁肌表。高年足冷，恐阳气式微，难以胜任疏解。脉浮小与表证相应，提示邪在表而正已虚，故法宜疏解，使邪达表。", ["浮", "小"]], "15522": ["病机", "原文辨温病与伤寒，谓温邪“脉多在肌肉之分而不甚浮”，且右手反甚，由怫热在内。此证脉浮小、不渴恶寒，舌苔白腻，非温病，乃风寒表证。脉浮主邪在表，不甚浮说明热未内炽，与温病脉象形成对比，以脉论证之属性。", ["浮"]], "15523": ["主病", "脉象浮弦，浮主表邪，弦主气机郁滞。症见乍寒乍热、头重胸闷、舌白恶心、溲少腹疼、骨节痛，为春温初起，温邪内蕴，表气不和。脉浮弦与邪郁肌表、气机不畅相应，故以豆豉、苏梗、蔻仁等疏解为治。", ["浮", "弦"]], "15524": ["主病", "脉象浮小，浮为邪在表，小为正气不足。春温身热六日未解，汗出遍身而仍微热，胸闷不饥，舌腻溲少，便闭。素多劳苦思虑，正虚邪恋。脉浮小提示表邪未净而正已伤，故拟轻疏退热，兼顾正气。", ["浮", "小"]], "15525": ["预后", "脉右弱左虚弦，右弱主肺气不足，左虚弦主肝阴亏虚而肝阳偏亢。素有吐血症，今咳喘气逆、痰块凝结、肌肉消瘦，值春令木旺，防其肝火犯肺、络伤见血。脉弱虚弦示正虚阳亢，故预后需防出血。", ["弱", "虚", "弦"]], "15526": ["病机", "右寸虚数，关脉见芤，左关弦数。虚数主气阴两虚，芤主失血，弦数主肝火偏亢。症见咳呛气逆、呛血色红无块、火升面热，为气火上逆、络伤血溢。脉芤与吐血相应，虚数弦数示火盛阴伤，故宜益气养阴、引血归经。", ["虚", "数", "芤", "弦"]], "15527": ["预后", "脉右虚左弦尺濡，右虚主肺气弱，左弦主肝阳亢，尺濡主肾阴亏。吐血过多，气随血耗，故右虚；肝火未靖，故左弦；阴液受损，故尺濡。趺阳太谿尚存，胃肾之气未绝，然防陡然汗脱，亟亟固气统血、益阴降火。", ["虚", "弦", "濡"]], "15528": ["病机", "脉象沉细，沉主里，细主虚，亦主湿。患者舟中受寒，睾丸胀疼牵连两腰，乃寒湿闭于下焦。寒湿阻滞，气血不畅，故脉沉细。沉细之脉反映寒湿内闭，阳气不伸，与腰痛、睾丸胀疼相应，治宜散寒却湿，防引动旧恙。", ["沉", "细"]], "15529": ["病机", "脉形两关虚耎，虚耎为气血不足之象。先粪后血，此远血也，病在脾胃，关脉候中焦。两关虚耎，说明脾胃气虚，统摄无权，血不循经而下溢。法宜益气养荣，使血止肛收。仲冬水冷金寒，更伤阳气，故尤宜温补。", ["虚", "耎"]], "15530": ["病机", "原文未识脉名，然述风癣湿毒起于肝脾，波及肺肾。土虚挟湿而金弱，金弱而水亏，水亏则木火动而筋脉不荣。此乃肝脾肺肾俱病，湿毒浸淫，筋脉失养。病机关键在土虚湿盛、金弱水亏、木火内动，故治宜益气养水，润燥除湿，兼壮筋健力。", []], "15531": ["病机", "脉象数而不浮，数主热，不浮说明邪不在表而在里。身热头胀，舌淡绛，胎腻，先凛凛而后热，此湿温内蕴之象。湿温之邪蕴于气分，故脉数而不浮；湿阻热蒸，故舌绛胎腻、寒热如疟。法从清解，使湿化热清。", ["数"]], "15532": ["病机", "脉象沉滞，沉主里，滞主气血不畅。痢起于六月下旬，先腹痛水泻，转白痢，今纯下红痢，一痛即下，无寒热外感。此暑湿交阻于肠腑，气血壅滞，传导失常。沉滞之脉反映湿阻气机，与腹痛下痢相应，法宜疏通，使暑湿去而痢自止。", ["沉", "滞"]], "15533": ["病机", "寸关小数不浮，左关尺弦细。数主热，弦主痛、主邪郁，细主湿。壮热不解，肢疼头痛，便溏溲赤，舌胎满布皆白，此邪挟湿伏于募原。脉不浮说明邪未外达，弦细为湿遏气机。所虑邪不外泄而内陷，致劫津昏厥，故速宜疏解。", ["数", "弦", "细"]], "15534": ["治法", "原文未及脉象，专述治法。方中加灵仙、木通，既能除经脉肢节之湿痹，木通又治历节痛且利小便，一举两得。此段说明疏解时邪兼除湿治痛之法，通过通利经脉、渗利小便使湿邪有出路，体现治湿当利小便之旨。", []], "15535": ["预后", "服疏解除湿方后，臂痛渐缓，余症未减，忽烦热无宁，脉见浮，得汗而解。浮脉主表，为邪气外达之象。药后正气奋起抗邪，邪从表解，故见浮脉而汗出病解。此段说明药后脉浮得汗，是邪有出路、预后良好之征。", ["浮"]], "15536": ["病机", "脉浮为邪在表，正气抗邪外出，故见壮热无汗、齿板干燥、筋脉抽掣。原文谓“脉见浮者必得汗而解”，说明邪伏半表半里，服前方后臂痛渐缓而脉转浮，是邪有外达之机，将作汗而解。然痰多稠、便稀溲赤、胸热闷，仍属邪阻三焦，气机不利，非单纯表证。", ["浮"]], "15537": ["病机", "脉形弦数，弦主邪阻气机，数主热。原文谓“邪阻中宫，深虑陷阴劫津”，症见时热、便溏、溲少、胸闷、口干、舌苔干糙、不饥不纳，显系湿热或温邪困阻中焦，热势鸱张，有内陷营阴、劫烁津液之虞。故法宜清解，使热退泄止。", ["弦", "数"]], "15538": ["病机", "复诊脉仍弦数，说明邪热未清，气机仍为邪阻。虽舌苔渐润、干糙改善，但口干、胸中热未除，舌中央仍带腻黄苔，是湿热余邪留恋中焦，热未全退。脉弦数持续，提示病机仍以邪阻中宫、热郁气滞为主，不可因苔润而遽补。", ["弦", "数"]], "15539": ["病机", "右寸关脉细耎兼滑，细耎为肺气亏虚，滑为痰湿内蕴。咳嗽十余月，昼轻夜重，内热喉痒，痰不易出，而食饮如常、神识不倦，说明病在肺脾，气阴耗伤而痰湿未化。前医作阴虚治不效，正因脉非细数，乃细耎兼滑，故宜清补肺脾，使金旺水生、土旺气充。", ["细", "耎", "滑"]], "15540": ["病机", "脉小数不浮，数主热，小主邪郁，不浮说明邪未在表。原文谓“时邪内伏”，症见身热头胀、骨节兼疼，是邪伏于里，郁而化热，不能外达肌表。脉不浮则不可纯用表散，法宜疏解内伏之邪，使邪有出路，热退痛止。", ["小", "数"]], "15541": ["误治", "本段未识脉名，纯述误治。患者年逾五旬，酒色过度，元阴元阳大亏，阳事不举。土医概以兴阳助火之剂，如桂、附、鹿茸辈，致阳事虽举而交媾无精，徒劳空阵。又见遍体不疏、肢节酸疼、腰膝无力、口燥喉干，皆妄投温燥、耗竭真阴所致。原文责医者“不究水火阴阳之偏盛”，是误治之咎。", []], "15542": ["病机", "右寸短涩欠浮，关虚小滑，尺举数按不足；左寸浮数，关虚弦，尺濡耎。合而审之，原文谓“水少于火，而阴阳犹有未平”。短涩为肺气不足，虚弦为肝阴亏虚，尺数按不足为肾水亏而虚火动，濡耎为阴精不充。服丸后诸症虽减，脉仍见水火未济、阴阳偏衰之象，故宜继续调补，尤须节欲保精。", ["短", "涩", "数", "虚"]], "15543": ["病机", "六脉沉细乏力，沉主里，细主虚，乏力为气弱。体小形瘦，痛起左乳下，因痛而呕，呕出食物酸水，病起七月。前医作肝胃气治，用左金、归芍、厚朴、郁金及参附川楝吴茱萸等，似效非效。脉沉细乏力说明中气亏虚、肝胃不和，气逆上冲，非单纯气滞实痛，故疏气平肝温中未能取效。", ["沉", "细"]], "15544": ["病机", "原文未识脉名，但述“痛呕皆从左乳下起，正阳明胃络也”，又见“所呕之物，或稠痰兼酸，或仍是所食之原物”，且有“冷气自下冲上”，足征“脾土之不运，胃底之无火”。医者误用香燥破气、辛凉治标，致胃气弥伤、脾阳愈弱，故病机为脾胃虚寒、痰饮内停、木来乘土，久则虑成下膈反胃。", []], "15545": ["预后", "脉两手细软无根，乃阴血亏极、阳气无依之象。前因误汗误下、苦寒迭进，致壮热昏沉、呓语戴眼、口开鼾睡、头汗如珠分颗不散，此油汗也，为真阳外越、阴阳离决之危候。细软无根正合“无胃气”之败脉，故主预后凶险，款证毕集，难以挽回。", ["细", "软"]], "15546": ["治法", "脉散为真气涣散、阳亡外脱之征。原文谓“真阳既已外亡，万难挽回”，故勉拟生脉散合四逆汤，以人参、麦冬、五味敛散越之气，附子、干姜回垂绝之阳，少入黄连一分泡服，取热因寒用、反佐通拒之义，尽人力以救万一。此脉散主阳亡，治当回阳固脱。", ["散"]], "15547": ["治法", "此段未出脉象，专释回阳返本汤方义。方以参、附、姜、草、麦、味合生脉、四逆，回阳敛阴；加腊茶、陈皮芳香苦降通气为向导；面戴阳者下虚，加葱白通阳、黄连少许热因寒用。所论皆针对真阳外亡、虚阳上浮之病机，示人用药配伍法度，故归治法。", []], "15548": ["病机", "右举不足按似数，左关虚弦，尺脉濡小，皆阴脉也，非病脉，乃先天禀质。虚弦为肝血不足、相火内动，濡小为坎水亏虚、下元不充。厚味不禁、嗜欲过度，水愈亏火愈旺，灼津成痰，结于颈侧而为瘰疬。故脉示气弱血亏、相火旺而水不济火，虚中挟毒。", ["虚", "弦", "濡", "小"]], "15549": ["兼症", "脉右滑、左弦。右滑主痰饮内停，左弦主肝木偏旺。证见身热呕吐、到口即吐、稍带酸味，发则先头痛、痛则呕吐随至，乃肝气挟痰饮上逆，木乘土位，胃失和降。脉与症合，故知呕痛由痰饮与肝逆相兼为患，属兼症之脉。", ["滑", "弦"]], "15550": ["病机", "六脉细小，右关虚弦。细小为脾胃久亏、气血不足；右关虚弦乃木来乘土之象。脾虚不运，肝木乘之，曲直作酸，故呕痛常发、食入即吐、酸水如涌。脉症相参，病机为脾胃久亏、木乘土位，先议和法治标，再图扶本。", ["细", "小", "虚", "弦"]], "15551": ["预后", "疟延日久虽止，而脉右虚数，肢跗浮肿。右脉虚数为脾弱胃强、虚热内扰之象；脾弱不运则水湿下流，故足跗浮肿。原文虑“恐转中满”，亟宜益胃调脾，使清升浊降。脉虚数示中气已伤而余热未清，故主脾弱胃强、有转中满之虞，属预后判断。", ["虚", "数"]], "15552": ["病机", "脉象沉小，沉主里、小主虚，与身热不退、胸闷呕恶、神识昏语并见，说明冬邪伏藏，春发而正气已弱，邪欲内陷。原文谓“邪伏于冬，而发于春”，脉沉小正示邪不在表而渐入里，故用疏解而热不减，反增胸闷，恐有陷阴之变。", ["沉", "小"]], "15553": ["病机", "脉形沉小弦细，沉小为邪郁于里、正气不足，弦细为邪留少阳、阴分受扰。原文谓“邪气留恋，深虑内陷”，虽身热、周身疼痛、夜有乱语，而日间应答尚清，说明邪尚未全陷，脉沉小弦细正是邪恋正虚、表里同病之象。", ["沉", "小", "弦", "细"]], "15554": ["病机", "脉象稍起而究嫌弦细，稍起示正气渐复、汗出热退，弦细则余邪未清、阴分未和。原文谓“热势虽退，余邪未清”，遍身疼痛减、胸脘痞闷去其七，而脉仍弦细，说明邪退未尽，正气尚弱，故须加意图维，防其复聚。", ["弦", "细"]], "15555": ["病机", "脉形右大、左耎，右大主气分邪实或阳气不潜，左耎主血分不足。腰痛偏左、小溲混浊，结合脉右大左耎，说明肾阳不足、水湿不化，故原文立法“壮水温阳”，以右大示水气偏盛，左耎示下元亏虚，非单纯外邪腰痛。", ["大"]], "15556": ["病机", "脾肺脉虚，虚为气血不足之象。素有肠红廿余年，近又泄泻日数十次，原文谓“气虚不能统，土弱不能运”，故得油腻肥甘即泻。脉虚正合脾肺气虚、统摄无权，故用益气扶土、佐收涩止血止泻，服后血止泻减，脉虚为病本所在。", ["虚"]], "15557": ["病机", "脉右浮滑，右候肺胃，浮主邪在表分或上焦，滑主痰湿内蕴。体倦食少、咳痰浓厚，与右浮滑相应，说明痰湿阻于肺胃，肺失宣降、胃失和降。原文谓“法宜肺胃并治”，正因脉右浮滑示病位在肺胃、病性属痰湿。", ["浮", "滑"]], "15558": ["病机", "脉来弦细，右关滑数。弦细主少阳邪郁、阴分不足，右关滑数主痰食交阻、胃有郁热。原文谓“痰食交阻，少阳之邪未楚”，故疟发间日、热重寒轻。弦细示邪在少阳，滑数示痰食内滞，脉症相合，故须节食避风以杜缠延。", ["弦", "细", "滑", "数"]], "15559": ["病机", "脉象滞涩，涩主气滞血瘀、积垢内阻。痢下色红、腹痛后重、昼夜数十次，舌苔白腻，原文谓“积垢犹存”，说明湿热积滞壅阻肠腑，气血不畅，故脉滞涩。病起半月表里俱病，法宜导滞温中，脉涩正示积滞未去、气机不利。", ["涩"]], "15560": ["病机", "脉象细小、按之无力，为正气不足之征。年高汗多，暑湿内伏，感寒挟食，暴呕痰涎，舌白腻，皆湿浊中阻、胃气上逆之象。脉细无力说明中气已虚，不耐表散，故不宜解表，宜和胃调中，使呕停眩止。", ["细", "小"]], "15561": ["病机", "脉仍细小而软，示正虚未复。服前方后呕吐渐停、冷汗止、身温，是阳回之兆；然又呕酸水、便稀，舌仍白，说明暑湿中停、胃中虚寒未净。脉软为正气虚弱，故舍温中和胃一法难许治，加左金丸以清肝降逆。", ["细", "小", "软"]], "15562": ["病机", "右脉浮小，左尺虚数上过于关，为相火挟外邪上炎之象。尺虚数示肾精亏虚，浮小为外邪袭表，火性上炎故咽喉疼痛色红。原文言必从泄精而致，脉证相符，方用元参、牛蒡、荆芥等以滋阴降火、疏解外邪。", ["浮", "小", "虚", "数"]], "15563": ["病机", "脉左右弦细沉紧，弦主气滞，紧主寒，沉细为里虚寒痰内结。痛起于腰，波及肝胃，腹痛块现如葫瓜，痛止块消，遍体不疏，乃气滞兼寒痰为患。脉沉紧说明寒痰深伏，痛甚欲呕、口吐冷痰，不速治恐痛剧见厥。", ["弦", "细", "沉", "紧"]], "15564": ["病机", "脉象沉滞，沉主里，滞为气血运行不畅，合风寒湿三气杂至而成痹。痹者闭也，气血闭阻故遍体酸疼兼腹痛便结。前医屡用大黄推荡，便通而证不减，反伐胃阳，食减阳衰，病日加深，法宜祛风寒、渗湿和胃、疏理经隧。", ["沉", "滞"]], "15565": ["病机", "脉虚涩而小，虚为气弱，涩为血少，小为气血不足。进前方后疼痛大减、食饮渐增，惟大便甚结、欲解不能，此气弱血燥、肠胃不滋所致。前医妄用大承气推荡，反增恶心不食、腹胀痛，故宜养荣润燥，侑以通幽，最为稳当。", ["虚", "涩", "小"]], "15566": ["病机", "右脉尚微细，左脉虚涩，微细为阳气虚弱，虚涩为阴血不足。服余方后疼痛减六七、饮粥增半，虽是好消息，但脉象仍示气血两虚未复，故犹恐变迁，须继续调治，不可松懈。", ["微", "细", "虚", "涩"]], "15567": ["病机", "脉象细小沉滑，细为湿滞，沉主里，滑主痰湿。体肥身长，素有脚气，发则腿膝胀痛、呕吐痰涎、胸脘闭闷，乃湿浊壅滞、痰湿内阻之象。脚气古称壅疾，最虑上冲，冲则虚阳上越而防脱，法当祛湿兼疏通，通则不痛。", ["细", "小", "沉", "滑"]], "15568": ["病机", "痢起两月，点滴色红，缠绵不已，左脉细微难寻。左脉候血，细微难寻乃阴血大伤、脉道不充之象；阴伤则脾阳不运，故食少体瘦、口味不禁。脉细微与久痢伤阴、脾阳困顿相应，故言难图奏功，用补中益气汤加减扶脾养阴。", ["微", "细"]], "15569": ["病机", "原文谓痢疾脉不拘浮沉迟数，但指下无神便属虚象；所谓无神者，短而松、按之虚软也。脉短松虚软，为正气不足、脾胃虚弱之征，故不论脉之浮沉迟数，皆当从虚论治，此以脉之有无神气辨痢疾虚实之要。", ["虚", "软", "短"]], "15570": ["病机", "右手无脉，因手腕交际处手坏，无脉可凭，故不以脉断。然观面色痿黄、食少肌瘦、肛门时坠而不痛，知脾阳不运。面色痿黄、食少肌瘦为脾虚失运之征，肛门坠而不痛属气虚下陷，故虽无脉可凭，仍可据症推知脾阳不运。", []], "15571": ["病机", "脉象细小无力，而尚东奔西走、日行数里。细小无力为肺气虚、气血不足之象；咳血未除，又加劳力、冬寒不避，更耗肺气。脉虚细与咳血、劳力相应，故言难胜任，讥西人不自量，示肺气虚者当静养避寒。", ["细", "小", "虚"]], "15572": ["病机", "畏寒欲呕、胸脘作疼、舌白胎腻、溲赤，脉象浮紧。浮紧为风寒束表、卫阳被遏之象；寒邪犯胃则欲呕、胸脘疼，舌白胎腻为寒湿内蕴。脉浮紧与畏寒、腿冷相应，故法宜解表和中，用桂枝、秦艽、干姜等温散。", ["浮", "紧"]], "15573": ["病机", "次日复诊脉仍如昨，畏寒稍缓而遍体拘束，两大腿冷疼，近火炉亦不见暖。脉仍如昨，示表寒未解、阳气未复；遍体拘束、腿冷疼为寒邪凝滞经络、阳气不达之征，故法宜温散，继用温通之品以散寒邪。", []], "15574": ["病机", "十一朝遍体浆回、头面痂渐结，脉虚小数。虚小为气血亏虚之象，数为余火未尽之征；痘后气血耗伤而余热未清，故脉虚小数与浆回痂结、气血亏而余火未尽相应，宜清补兼施，既补气血又清余火。", ["虚", "小", "数"]], "15575": ["病机", "感寒误治，恶寒身热无汗，咳痰稠盈碗有浮泡，口中作甜，舌绛有津，右寸浮紧、左脉浮弦。浮紧为风寒束肺、表邪未透之象，浮弦为邪郁少阳、肝肺气机不舒；风寒射肺，究未透表，故始终无汗，遍体不疏，终非疟也，速宜疏肺透邪。", ["浮", "紧", "弦"]], "15576": ["病机", "举之软小、按之沉滑，软小示病后脾土虚弱、正气不足，沉滑则主气滞食凝、实邪内阻。原文言\"不食痛减，食则痛增\"，正合食积中脘、气机壅滞之象；又值病后脾运失职，故虚中夹实，胀痛并作。脉象虚实并见，与\"气滞食凝\"之病机相应。", ["软", "小", "沉", "滑"]], "15577": ["病机", "右脉虚弦，右寸关候肺脾。虚为气亏，弦主气机不畅。原文谓\"肺气亏而中气虚\"，咳嗽痰稠不易出，正是肺气不足、无力鼓痰外出，兼中气虚弱、运化失司而生痰。虚弦并见，说明本虚为主、痰气内阻为标，故言\"速治为妥\"，防其正虚邪恋。", ["虚", "弦"]], "15578": ["病机", "左脉细数，细为阴血不足，数为阳热有余。原文断为\"阳有余，阴不足，相火上炎\"，故见彻夜不寐、两耳常鸣。患者素嗜酒厚味，积热伤阴，阴不制阳，相火循经上扰清窍，扰动心神。细数之脉正合阴虚火旺之机，故以四物养阴为君、镇肝舒气为佐而取效。", ["细", "数"]], "15579": ["病机", "右脉浮数，浮主邪在气分、病位偏表浅，数主热盛。原文谓\"热在气分，几成消症\"，症见渴饮无度、舌纯红起芒刺无津，皆暑湿化燥、邪热燔灼气分之象。前医误投温燥、清利，反伤津助热。浮数之脉与渴饮无度相应，故用白虎汤清透气分热邪而渴减热彻。", ["浮", "数"]], "15580": ["病机", "右大左弦细，右大主暑湿蕴于气分、邪势鸱张，左弦细主阴分受灼、肝木失柔。原文述寒轻热盛、头重且胀、小溲浓赤、舌腻如粉，为暑湿内蕴、由单寒转疟之候。大与弦细并见，示邪实正伤、湿热交蒸，故云\"延绵有日，速治为妥\"，恐久延生变。", ["大", "弦", "细"]], "15581": ["病机", "脉数不洪，数为热，不洪则热未炽盛于气分。原文谓\"单热不寒，瘅疟之象\"，舌苔尚白、口干不喜多饮，说明暑热内伏而邪未全化燥，兼有湿浊未净。前医早投黄连苦寒，反遏伏邪气。数而不洪，正合暑热内伏、邪郁不透之机，故主以和解透达为法。", ["数"]], "15582": ["病机", "脉大身热，大为阳热亢盛、邪正剧争之象。原文谓瘅疟十数发不止，有汗而渴，入夜发、天明退，断为\"先伤于暑，而后伤于风\"。暑热内伏、风邪外袭，两邪相合，正盛邪实，故脉大而身热汗渴并见。脉大与壮热多汗相应，故仿白虎加桂、小柴胡意清透和解而愈。", ["大"]], "15583": ["病机", "脉象沉滑，沉主病在里，滑主痰食内积。原文述得食则呕、病经四日，为食滞中脘、胃气上逆之候。食积内停，胃失和降，故得食即呕；脉沉滑正应里实食滞之机。故拟和胃运食法，消导积滞、复其和降，使胃气和而呕止。", ["沉", "滑"]], "15584": ["病机", "右三部细软如绵，左脉寸小，细软为气血不足，寸小示阳弱。素有喘症，咳从脐下逆上属肾气不固，汗出如雨、舌根强、气急神呆为肾虚气逆、痰浊上蒙。脉症合参，病机为肾气亏虚、痰浊壅肺，本虚标实。", ["细", "软"]], "15585": ["病机", "脉象软小乏力，尺脉濡细，软小为气血未复，尺濡细主肾虚湿滞。喘止咳平，痰味带咸，咸味入肾，示肾虚水泛。法宜调坤土以助干金，壮坎水以滋震木，即补脾益肺、滋肾养肝，病机为脾肾两虚、肺金失养。", ["软", "小", "濡", "细"]], "15586": ["预后", "第六脉未知，肌体未丰，精神未足，元气未充，此际首重在节欲养气。原文强调积气以成精，积精以全神，虽脉未详，但据症知元气未复，预后需慎守，以养气节欲为紧要，否则难收全功。", []], "15587": ["病机", "脉象沉细，沉主里，细主湿，体肥好啖厚味湿面，湿气内侵，腿膝胀痛，右甚于左。湿性下趋，下达为顺，最怕上升，脉沉细正合湿滞于里，病机为湿浊内阻、下注腿膝，治拟疏通法。", ["沉", "细"]], "15588": ["病机", "脉形浮弦，左大右小，浮主表，弦主风热，左大右小示风热偏于外。症见寒热、喉疼、丹毒外发，舌苔白腻，时有呓语，此风热蕴于肺卫，丹毒外达之象，病机为风热郁表、毒邪外透。", ["浮", "弦"]], "15589": ["病机", "右寸浮紧，关脉小滑，浮紧主风寒闭肺，小滑主痰凝气滞。因伤风而起，喘不能卧，胸脘闷，背板如缚，喘声如抽风箱，此风寒闭肺、痰凝气滞，阻塞清道，病机为外寒引动痰浊、肺气壅塞。", ["浮", "紧", "小", "滑"]], "15590": ["病机", "脉寸、尺小数，小为阴虚，数为相火未静。白浊半月，服通利罔效，溺端不封，小便时针刺感，此相火妄动、阴亏不济，病机为阴虚火旺、相火扰于下焦，宜养阴济火，浊自止。", ["小", "数"]], "15591": ["病机", "脉左大于右，左主外邪，大示邪盛。身热不壮，口干不多饮，舌苔中央腻滞淡黄，耳聋，此暑伏湿闭之象，病机为暑湿内伏、气机闭阻，故以清解和之，后见宿垢内蕴，转以解表通里。", ["大"]], "15592": ["主病", "脉浮软小数，浮为风邪上攻，软小为高年气血不足，数为邪郁化热。风邪袭扰脑后、鱼尾，故牵掣抽痛而寒热；舌苔淡黄边白，示风热在表兼有湿滞。脉症合参，病机为风邪上攻、正虚邪恋，治宜舒解退热，然高年体弱，恐难胜任峻剂。", ["浮", "软", "小", "数"]], "15593": ["病机", "脉左小右大，尺浮，左小为肾阳虚衰，右大为脾土亏虚，尺浮乃肾气不固。肾阳虚则脾土失温，运化无力，兼食积中宫，故大小腹俱痛而便溏泄，日数次。病起月余，虚中夹积，治当理脾温肾，不可泛泛止痛，服后痛减泄止，正合病机。", ["小", "大", "浮"]], "15594": ["病机", "右脉细软，左脉弦急，尺数，细软为阳明宗筋失养，弦急为厥阴肝木郁滞，尺数示下焦湿热。溺情过度耗伤肝肾，肝木失柔则筋急，宗筋拘挛故溺时如刀割刺痛，曲腰则少安。病涉厥阴、阳明，波及膀胱、肺、肾，年逾六旬，病根已久，脉象正合肝急筋挛之机。", ["细", "软", "弦", "急"]], "15595": ["误治", "两关弦细不静，弦为暑湿郁遏肝脾，细为阴伤，不静乃邪热内扰。暑湿内蕴未经疏解，反以熟地、归、芍、鹿角胶等滋腻，参、耆、升、柴、术、草温补，更投附子、牡蛎温凉杂进，致热终不退，奄奄一息。脉象示邪未透而正已伤，此段主旨在于警示误治之害。", ["弦", "细"]], "15596": ["预后", "脉象软小濡细，软小为气血未复，濡细为阴津不足。诸恙俱平，头热退、苔渐化、鼻洪止、二便转常，惟脉尚软小濡细，精神疲而耳鸣，乃大病后气血亏虚、余邪已尽之象。脉症合参，预后良好，加意调补自可痊安，不可因脉小而妄投温补。", ["软", "小", "濡", "细"]], "15597": ["其他", "此段为复诊记录，未识别出脉名，仅述「可扶起诊脉，究未能多坐」，反映患者大病后正气未复、不耐久坐之状。虽无脉象可析，然从起居动态可窥气血尚虚、体力未充，属病后调摄阶段，须缓缓将养，不可遽补遽攻。", []], "15598": ["预后", "六脉尚虚小乏力，虚小为气血久亏之象。连进五六剂后肝肾之阴渐复，耳鸣减半、食饮亦增，惟脉仍虚小乏力，乃大病两三月气血未充、肌瘦神疲之故。脉症相应，示正气渐回而未全复，宜节食戒怒、淡蔬调养，俾食饮旺而精气充，庶无他虞。", ["虚", "小"]], "15599": ["病机", "右脉小数，左弦细，小数为暑湿郁于气分，弦细为湿阻肝脾、阴分受灼。暑湿内侵十八日，余热未尽，有汗喜饮、溲短赤、苔腻淡黄、便六七日未解，皆湿阻兼暑未彻之征。脉症合参，病机为湿阻中焦、暑热未清，表散清涼均非所宜，当和中祛湿，使暑湿由中下达。", ["小", "数", "弦", "细"]], "15600": ["其他", "原文未识别脉名，仅述“脉如前”，结合前诊当为湿热未清之脉。热退复作、舌胎腻滞、小便短赤，说明湿热余邪未尽，蕴阻三焦，气化不利。虽汗出热减，但午后复热，知饥能寐，示胃气尚存，正邪交争。去渗利加养阴透热之品，旨在清余热、化湿浊，防其缠绵。", []], "15601": ["病机", "脉象虚软为劳苦伤气、脾肾两亏；左关弦劲乃肝郁化火、疏泄失职；尺脉濡细小数主下焦湿热蕴结、阴络受损。尿血涓滴、茎中鲜血频滴、大便难解，皆由肝肾阴虚、湿热下注、气化不利所致。面带虚浮为水气上泛，深虑头倾背曲，示肾精亏耗、骨痿将成。", ["虚", "软", "弦", "濡"]], "15602": ["病机", "左关、尺弦急小数，弦主肝郁，急数主火旺，示肝肾相火内炽、湿热瘀阻精窍。尿血如箭、紫块、溺管血块，为热伤血络、瘀血内停；大便欲解不能、前后胀急，乃二阴气机壅滞。病在精窍非膀胱，故茎痛不显。更医投龟板熟地知柏麦冬，滋腻寒凉，反增胸胀、二便秘、面浮，乃气壅于上、中焦不运之误。", ["弦", "急", "数"]], "15603": ["病机", "右脉如昨，左关、尺弦紧小数未平，弦紧主肝郁气滞、寒湿内结，小数主郁热。药后二阴稍通、小腹并紧减，但呕出盈碗之水带酸黄色，乃下焦秘结、上焦壅塞、中宫阻滞，寒凉伤胃、米饮不化所致。呕后上部稍宽，示气机暂得升降，然弦紧小数未平，肝郁湿热未解，故胀急虽减而病根未除。", ["弦", "紧", "数"]], "15604": ["病机", "右脉虚耎为脾肺气虚，左关、尺弦细小数乃肝肾阴虚、相火内动。气不固血则尿血，水不涵木则肝阳偏亢。故治以固气养荣、兼理肝肾，使二阴气调、气旺水充，肝木得滋而相火不升，心火不下荡，血自归经。此脉示本虚标热，虚耎为气虚之征，弦细数为阴虚火旺之象。", ["虚", "耎", "弦", "细"]], "15605": ["病机", "六脉虚大，虚为正气不足，大为邪气有余，主脾肾两亏而肝气横逆。病延日久，值春令木旺，土受木乘，脾主四末，故手足掌心痛剧且肿。二目水光外含，为肾水不足、肝风内动之先声。虚大之脉示本虚标实，脾肾亏于下，肝气亢于上，深虑骤变，故先治筋脉、调脾和肝。", ["虚", "大"]], "15606": ["兼症", "原文未载脉象，述服药后手足心疼痛申酉后渐增、胸中气闷、两胁作痛，引动肝气。申酉属金，金旺克木，肝气郁滞加重，故胁痛胸闷；手足心为脾所主，脾虚肝乘，故疼痛定时而增。此示肝郁气滞、脾运不健，气血不和，筋脉失养，故当理气血、和筋脉。", []], "15607": ["病机", "肺脉数急已缓，示肺中郁热渐退；左关弦劲未舒，乃肝木过旺、侮土之象。木旺则脾土受克，故食不贪、痰饮黏腻呕出；常多怒，怒则火升，肝亦自伤。四肢无力、遍体不疏、筋惕，皆脾虚肝旺、筋脉失养所致。治以调脾温中、佐舒肝和筋，使木土相和，则诸症渐减。", ["数", "急", "弦", "劲"]], "15608": ["预后", "原文述服药三帖后“行步可不用人扶，手足不痛，筋脉安舒”，虽未明言脉象，但以症状改善推断脉象必趋和缓。此段主旨在于说明治疗后筋脉拘急得舒、气血渐通，故属预后佳兆，非直接论脉。", []], "15609": ["病机", "原文谓“脉之虚软、弦劲俱渐平可”，说明原先虚软与弦劲并见，今渐缓和；但“左尺濡耎、右尺浮虚乏力”，左尺候肾阴，右尺候命火，濡耎浮虚并见，故断为“阴气亏而命火不足”，主腰疼膝冷，乃元阴元阳两虚之病机。", ["虚", "软", "弦", "濡"]], "15610": ["病机", "右浮大主春温未解、湿热壅于气分；左弦细主少阳甲胆之火郁。淋症半载，溲赤茎中胀刺，乃脾湿下注兼胆火郁遏，故脉见右浮大左弦细，与“春温未解，兼之湿热下注”相应，非单纯淋症。", ["浮", "大", "弦", "细"]], "15611": ["治法", "原文未出脉象，仅言“色脉合参”，知气血两虚致肠燥便秘。治以“益气养血，兼以舒运”，使缓缓而解。此段主旨为治法，非论脉，故脉象要素从缺。", []], "15612": ["病机", "右脉虚滞主气虚而宿滞未净，左脉细弦主血少而肝木未和。进前方后虽下结粪，但“宿垢未尽”，因淋浊身热之后体虚肠燥，宿滞难尽，故脉仍虚滞细弦，主益气养血润燥以滑之。", ["虚", "滞", "细", "弦"]], "15613": ["病机", "原文仅言“色脉合参，食积挟虫”，未出具体脉象。腹痛块攻有时、甚则欲厥，乃食积与虫积交阻，气机逆乱所致。此段主旨为病机，脉象要素从缺。", []], "15614": ["病机", "右脉沉细、左脉虚微，沉细主寒邪内陷，虚微主阴阳两亏。患者泄精、溏泻后复感寒邪，他医误清误散，致“寒邪陷入于三阴”，四肢厥逆、神识模糊、舌根短缩，脉证合参，属阴阳两亏、邪难达表之危候。", ["沉", "细", "虚", "微"]], "15615": ["预后", "原文未出具体脉象，仅言“脉亦渐起”，结合四肢温暖、身热微汗、小便清白且长、舌缩渐伸，知里邪有出表之机，病势稍减。此段主旨为预后转佳，脉象要素从缺。", []], "15616": ["治法", "原文未出脉名，仅言「证脉合参」，据前诊阴阳两虚、邪恋少阳之证，立辅正兼和解之法。取小柴胡去黄芩加生地、姜汁，桂枝汤去芍药加葛根，使邪由少阳出阳明、由阳明出太阳，取微汗而解。脉象虽未明言，其治则体现虚体祛邪、标本两固之意，非以脉断病，而以证脉合参定方。", []], "15617": ["病机", "原文未出脉名，但言「脉形渐出，有鼓指之势」，是寒邪由三阴出表之象。前此寒陷三阴致四肢厥逆，今脉由沉伏渐出而鼓指，兼口干喜饮、溲转淡黄、大便黏腻而臭，皆邪从阴转阳、由里达表之征，故再以生津退热、调和荣卫取小汗彻热。", []], "15618": ["病机", "原文「脉尚细微，左关、尺更觉弦细」，细微为气血未复，弦细见于左关尺，是邪退而余波未尽、肝脾络脉尚滞。汗出热缓，陷阴之变可免，然脉未和缓，故议养阴生津和胃，以清余邪、复胃气，非纯补之候。", ["微", "细", "弦"]], "15619": ["治法", "原文未出脉名，仅言「证脉合参，尚有余垢未尽」。大病之后理应大补，而宿垢留恋中宫，昨始解之，余垢未净，故权以疏运和达之法，先祛余滞，再议补虚，体现先攻后补、以脉证合参定缓急之序。", []], "15620": ["病机", "原文「此脉之所以兼弦也」，指出弦脉由土虚不能生金、肺金失平木之职所致，即脾土虚弱、肝木偏亢而脉弦。又土虚不能制水，肾水泛痰带咸。伤寒后胃阴烁、脾阳虚，肌肉瘦削，故预为扶土，用六君子汤加归身、柏子仁，培坤元以资生。", ["弦"]], "15621": ["治法", "原文未出脉名，仅言「证脉合参，大病之后气血两亏」。然气阳血阴，当壮坎阳而滋离阴，使荣卫冲和、气血流通、精髓可填。填精益髓非草木所能尽，须借气血有情之品少佐导引，法宜补火生土、壮水滋木，使元气日充，非泛作气血不足之治。", []], "15622": ["主病", "原文「右脉沉紧，腹中频痛，寒与食并，小便短赤」。沉主里、紧主寒主痛，右脉候脾胃，沉紧并见，是寒邪与食积并结中焦，气机不通故腹中频痛；小便短赤为食积化热之征。故以温中运食法，温散寒邪、消运食积，使中焦通利。", ["沉", "紧"]], "15623": ["病机", "原文「脉形沉滞，尻骨酸疼」，沉滞为阳气不运、气血郁滞之象。尻骨属肾，肾阳虚则温煦无力，肝木失于条达而不舒，故酸疼。服后方四帖酸疼顿平，是温肾疏肝、通阳运滞之效，脉沉滞与肾阳虚、肝木不舒相应。", ["沉"]], "15624": ["病机", "右关濡软，为脾湿中阻之象。濡主湿，软主虚，右关候脾，湿困中焦，脾失健运，水湿上泛，故口吐涎沫，自觉从两腮涌出。涎涌无时、量多而味难言，皆湿浊上逆所致。此脉此症，病机在脾湿不化，非热非寒，故涎不酸不苦。", ["濡", "软"]], "15625": ["病机", "脉象过硬，非正常和缓之象，示其人性情刚勇急躁，肝火易升。劳力损膜致吐血，今夏复发，皆因性急火升，迫血妄行。血止后食入即吐，乃前医过用寒凉，胃土被遏，寒凝气逆。脉硬既主肝火，又示胃气受戕，故治呕佐温胃而效。", ["硬"]], "15626": ["病机", "脉息沉滞，沉主里，滞主气机不畅。素好食面、不忌生冷，寒湿与食交阻中焦，气机壅塞，故胸闷块攻、脐上下俱痛。沉滞之脉正合寒湿食积内阻之病机，宜温舒以化寒湿、行气滞。", ["沉", "滞"]], "15627": ["预后", "右脉软滑，软主脾虚，滑主湿盛。两足浮肿，朝退夕肿，乃脾虚不能运化水湿，湿邪下注所致。脉软滑示湿浊内蕴而正气已虚，若不速治，脾土日衰，水湿泛溢，恐成中满之证。此段重在警示预后，防病进深。", ["软", "滑"]], "15628": ["病机", "脉浮而不沉，似与气逆胸胀不符，然两关细小兼弦，细为心荣不足，弦为肝木乘土。怔忡时发，心荣不足，胃土失养，肺气不充，肝木乘之，故每至四鼓气由脐上达胸，胀疼拒按。脉浮为气浮于上，细小弦则关本虚而肝胃不和，源在心荣中气之亏。", ["浮", "细", "弦"]], "15629": ["病机", "右寸关浮数，左关尺虚数。浮数为湿火下注，虚数为相火不静、阴精亏虚。少不节欲，相火妄动，湿火蕴结下焦，故小溲频涩、溺后窍底酸疼刺痛。脉象示肺肝肾功能失调，虚中夹实，当从三经论治。", ["浮", "数", "虚"]], "15630": ["病机", "脉弦细小数，弦主疟，细为阴弱，小为荣虚，数为阳盛。风暑相搏，单热不寒，发为瘅疟。午后热甚，心热如焚，口渴喜饮，阳盛阴弱；热退无汗，睡著盗汗淋漓，荣卫两伤，水中火发。脉症合参，非泛泛疟疾，乃阳盛阴弱、荣卫俱伤之候。", ["弦", "细", "小", "数"]], "15631": ["病机", "右脉虚软，左脉弦细。右虚软主气虚脾弱，左弦细主肝气郁滞。素有肝胃气，腹胀由下而上，肢倦食减，嗳气失气则爽，此气虚气滞、脾阳不温之象。脉症相合，故用理中汤加味温运脾阳、疏理气机。", ["虚", "软", "弦", "细"]], "15632": ["病机", "脉右细软，左小弦。细软为脾虚不运、气血不足之象，小弦则肝木乘脾、气机郁滞。症见肌瘦肉削、不饥不纳、呕清水、吐白沫、腹疼水泻，皆脾不运、胃不和、中宫阻滞所致。前医误作暑湿，清攻杂投，更伤中气，故脉见细软无力，当先理中宫为急。", ["细", "软", "小", "弦"]], "15633": ["预后", "脉息仍细耎无力，虽进粥无呕、诸恙安妥，然细耎无力为脾胃气弱、气血未复之征。体倦神疲与脉相应，说明中气尚虚，恢复需时。此段以脉测预后，提示不可因症减而骤进峻补或攻伐，当缓缓调养脾胃，待脉起有力方为向愈。", ["细", "耎"]], "15634": ["预后", "脉息软弱，与神疲、肌瘦肉削相应，为脾胃气虚、营卫不足之象。服四君子加木香、砂仁等后大便不结不溏，知中焦渐和，然脉仍软弱，说明气血未复。年高病久，以脉弱为虑，提示当继续健脾和营，不可攻伐，待脉渐有力则安。", ["软", "弱"]], "15635": ["主病", "脉息浮紧，浮主表、紧主寒，为感寒之象。症先寒后热、小溲多，原文谓寒感于下焦，紧脉应寒邪凝滞、卫阳被遏。年近八旬，正气已衰，虽见浮紧表寒，亦只宜轻舒解表，不可峻汗攻下，以免伤正。此脉此症，主寒邪外束、下焦受寒之病机。", ["浮", "紧"]], "15636": ["病机", "脉形右关、尺并数。右关候脾胃，右尺候大肠，数主热。素有外痔、好酒喜茶，湿热内蕴，下注大肠，故肛脱胀坠、痛如鸡啄。数脉应湿火之邪，非清不能散、非通不能除，说明病机为湿火注于大肠，亟宜清通，免成痈漏。", ["数"]], "15637": ["病机", "右脉耎短，关中见数，按之不足；左关弦而按之软。耎短为脾虚气弱，数而按之不足为虚热非实火，弦而软为肝郁乘脾而非真弦。原文自谓弦非真弦、数非真数，正说明病后脾虚、气血未复、虚中夹郁之机，当于此消息，不可作实热实弦论治。", ["耎", "短", "数", "弦"]], "15638": ["病机", "脉软大无力，软为气虚，大为中气外浮、按之无力则非实。七旬老人脾土不运、食滞中宫，肝木横冲致腹胀且痛，不饮不纳，中焦气馁。脉软大无力正应中虚气馁之机，亟宜温中以和，若误作实胀攻伐，深虑中满之虞。", ["软", "大"]], "15639": ["治法", "脉弱为年高气血虚衰、中气不足之象。痛胀俱减而大便十日未解，仍宜温中运食。缘脉弱正虚，未便擅投攻伐，故用姜、附、茱萸温中，佐乌药、当归、柏子仁、首乌润养。此段以脉弱定治法，示年高正虚者当温运缓图，不可峻攻。", ["弱"]], "15640": ["其他", "原文未载具体脉象，仅言“证与脉合，药与病对”，强调脉证相符是取效关键。虽无脉形描述，但“脉合”二字点明脉象与胀痛之证相应，属寒凝气滞之机，故温中法能一剂知、二剂已。此段主旨在于说明脉证相合则效如桴鼓，非论具体脉象主病。", []], "15641": ["病机", "脉沉小主里虚寒，左弦细为寒凝气滞、饮邪内阻。汤水下咽即呕、胸胃作疼，正是寒气内蕴、食阻于中，胃气上逆之象。沉小示阳气不伸，弦细示痛与饮，故以温之和之，用苏梗、香附、木香等温运中焦，使寒散食消则呕止痛除。", ["沉", "小", "弦", "细"]], "15642": ["病机", "脉细小主湿邪内阻、阳气不宣，胸脘闭闷、腹中小疼、舌胎白腻，皆湿阻上中二焦之征。湿遏气机则小便赤、大便数日不解，非热结而是湿滞。细小之脉不任攻下，故治宜温舒，以化湿展气，使三焦通利则诸症自解。", ["细", "小"]], "15643": ["病机", "右脉细小乏力，左反关弦细小数，示失血过多、气阴两伤，虚热内扰。溺血日三十余次，茎中空冷如冰、应心而疼，腰腿酸软，食饮无味，皆血去阴亏、筋脉失养之候。弦细数为虚热挟瘀，故议益气养水、去瘀生新，深虑神疲难支。", ["细", "小", "弦", "数"]], "15644": ["病机", "脉仍细软无力，示进前方后溺血减半而气血未复，阴亏阳亦伤。茎中冷疼、瘀条尚有，乃虚冷挟瘀，非纯热之血。细软无力为气血大虚之脉，故强调“血之热”与“虚冷而见瘀”之别，照方续服以益气养荣、温通化瘀，不可妄增损。", ["细", "软"]], "15645": ["病机", "脉形沉细无力，主脾土大惫、阳气衰微。泄泻两月未止且痛，食纳脘中不爽，惟饮粥无妨，日夕数次，正是脾虚不运、寒湿内停之候。沉细无力为虚寒之脉，非实积可比，故曰“岂可渺视”，当以温补脾土为要。", ["沉", "细"]], "15646": ["误治", "脉细软无力为气血本虚，左反关弦紧乃寒凉攻伐后中下二焦为寒所遏、气机拘急之象。前医误用凉膈散大黄五钱，致大小腹剧痛、睪丸胀大、面青畏寒身热，表里不和。弦紧示寒凝痛甚，细软示正虚，故治在温舒以解寒遏，冀其转机。", ["细", "软", "弦", "紧"]], "15647": ["病机", "脉见芤数、按之无力，芤主失血，数主虚热，无力为气血大亏。大吐血量多，身壮热、咳呛气逆、痰稠带血、面浮光，皆血去阴伤、虚阳外浮之候。芤数之脉示血脱气耗，深恐汗脱，故亟宜益气养荣以固其本，不可纯用凉血。", ["芤", "数"]], "15648": ["预后", "原文谓“脉象仍空虚无力为虑耳”，热退痰血渐止，但脉空虚无力，说明邪虽退而正气未复，气血亏虚，故为可虑。虚、空脉主气血不足，无力为气虚，提示病后正虚，需防复病。", ["虚", "空"]], "15649": ["病机", "咳呛气逆减，痰少，但“脉右软大无力”，右脉候肺脾，软大无力为脾肺气虚，运化无力，故食饮未健、不知饥；心神不静亦因气虚不养。软大非实，乃虚象，主气虚湿滞。", ["软", "大"]], "15650": ["病机", "“两寸脉究嫌细耎难寻，左尺虚濡”，寸候心肺，细耎难寻为心肺气阴不足；左尺候肾，虚濡为肾虚。夜寐不安、心神不宁，乃心肾不交，荣卫不和，故法宜荣卫并治，佐以养神安魂。", ["细", "耎", "濡"]], "15651": ["病机", "“脉右急，关滑，皆无力；左关弦，两尺浮濡”，右关滑无力为脾虚痰滞，左关弦为肝木乘土，两尺浮濡为肾虚。病后气血大亏，又值冬寒，子母并虚，故食减、舌呆白、咳呛稠痰，皆脾肾肝虚损之象。", ["急", "滑", "弦", "濡"]], "15652": ["主病", "“尺脉沉紧”，尺候下焦，沉紧主寒主痛，结合手足逆冷、腰疼足蜷，为下焦感寒停食，受寒于房劳之后，寒凝气滞，故用散寒温通之品而愈。", ["沉", "紧"]], "15653": ["病机", "“右关虚软，左关弦细”，右关候脾，虚软为脾气虚；左关候肝，弦细为肝血不足、肝气郁。脾虚不能统血，肝虚不能藏血，故从肝脾治，探本穷源。", ["虚", "软", "弦", "细"]], "15654": ["主病", "“脉象弦细”，弦主痛、主寒，细主虚，结合畏寒腹痛、痛甚流涎、唇红舌腻，为外寒内虫，寒虫交争，气机不畅，故先宜散寒止痛。", ["弦", "细"]], "15655": ["病机", "“脉形虚濡”，虚为正气不足，濡为湿，结合嗜酒、肌瘦、咳呛、便泄，为湿热伤脾而土弱，虚火烁肺而金衰，脾虚湿盛，肺虚失养，故见诸症。", ["虚", "濡"]], "15656": ["病机", "脉浮弦，浮主表，弦主邪郁少阳、募原。暑热症见畏寒身热头胀，午后寒热呕吐，舌苔白腻，乃邪伏募原未达表，故脉浮弦。肤燥不松、汗出周体松爽，说明邪郁肌表，治宜解表和中，俾邪外彻。", ["浮", "弦"]], "15657": ["病机", "脉沉紧小滑，沉主里，紧主寒痛，小滑主气食交阻。脐上下痛，块结如石伏于脘底，按之稍缓，寒与气食交阻，病起二旬，脉显明征，故拟温中法，服后痛缓块小。", ["沉", "紧", "小", "滑"]], "15658": ["病机", "右关虚弦，弦主痰饮；尺脉迟耎，左关尺弦细虚濡，迟耎主肾阳亏，弦细虚濡主脾虚湿痰。素好浓茶，痰吐盈盂，精薄囊冷，脾土虚湿痰上溢，肾阳亏精气不充，故脉显此象，法宜脾肾同治。", ["弦", "迟", "耎", "细"]], "15659": ["其他", "本段为复诊丸方，未识别脉名，原文仅言「证脉合参，水火并济」，强调保肾固精即种子良法。脉象未具体描述，故脉素为空，主旨属治法延续与疗效观察，非主病或病机专论。", []], "15660": ["兼症", "脉象细小，细主阴血不足，小主气虚。怔忡有年，心荡无时，胸膺气筑，食增则脐腹收缩吊紧，背曲，头眩足浮，皆气血亏虚、心脾不足之兼症。进方后心荡大减，食后脐腹收缩顿平，背曲头眩俱缓，脉症相应。", ["细", "小"]], "15661": ["病机", "脉象弦硬，弦主疟邪，硬主邪食内蕴、气机壅滞。胎疟间发，寒轻热重，午后始至，舌苔白腻如粉，小溲色赤，大便稀粪，腹中有块，邪食内蕴，脉弦硬显有明征，故拟清脾饮速退疟邪。", ["弦", "硬"]], "15662": ["主病", "脉来浮缓，浮主风邪外袭，缓主营卫不和。头疼畏寒发热，骨节疼，舌苔腻，乃风邪外袭肌表，营卫失和，故脉浮缓。治宜于散，以解表祛风为法。", ["浮", "缓"]], "15663": ["病机", "脉右沉紧，左小弦。沉紧主里寒，小弦主气滞。胸脘腹胀闷痛难忍，呕吐酸水，舌苔白腻，小溲赤疼，乃寒湿中阻、气机不畅，故拟温中定痛止呕，服后呕酸腹痛顿止，胀闷未平。", ["沉", "紧", "小", "弦"]], "15664": ["病机", "脉形虚芤，为阴血骤脱、脉道不充之象；左弦数无力，弦主肝病，数而无力为阴虚内热。两日吐血七八盏，阴亏之体更伤血络，故脉虚芤。深虑汗脱者，阴血暴亡，阳气无所依附，有外脱之势，亟亟扶正以固脱。", ["虚", "芤", "弦", "数"]], "15665": ["病机", "脉象沉滞，沉主里、滞主气机壅塞。气食相凝，脐腹胀痛，得汤即呕，小溲短赤，皆由气食交阻中焦，升降失司，故脉沉滞。治宜温舒，以温通消导、舒展气机，使凝滞得行，胀痛呕逆自平。", ["沉", "滞"]], "15666": ["病机", "脉象弦细，右关浮缓而细。细主湿，浮缓主风，风湿感于肌肤而侵太阴湿土；左之细弦，为少阳兼太阴。仲景云「疟脉自弦」，疟不离少阳，故以弦为纲。用小柴胡汤加草果、藿香等，和解少阳、化湿祛风，疟日减轻。", ["弦", "细", "浮", "缓"]], "15667": ["病机", "脉息软大无力，左关弦细。软大无力为正气不足、阴气又亏；弦细为疟邪未净、肝木乘脾。连发有日，汗出过多，汗乃心液，神伤而臂痛伤神；不饥不食，胃土又伤。故议养阴祛邪，冀疟停而正复。", ["软", "大", "弦", "细"]], "15668": ["病机", "脉象虚豁似空，为阴气亏虚、脉道不充之候。疟后心中烦躁扰乱，食少妄语，目瞑见鬼，乃阴亏而阳不能入于阴，神不守舍。非阳虚见鬼致汗脱者可比，故以和阳益阴敛神法救之，使阴阳交合则神安。", ["虚", "豁"]], "15669": ["病机", "脉象虚弦，右脉沉细。泻久伤脾，脾虚肝乘而致转筋，虚弦为脾虚肝木乘之象；右脉沉细，中宫又为寒阻，故进汤即呕。舌苔白腻亦寒湿之征。治宜和胃、止泻、舒筋，使脾健肝平，筋脉得养。", ["虚", "弦", "沉", "细"]], "15670": ["病机", "脉左弦细，右小，舌白如粉。伏暑内陷，邪阻少阳，故左弦细；右小为邪陷正伤。身热一旬未解，误投清疏、生地羚羊等滋腻，致便溏胸闷、耳聋溺痛，皆邪陷之征。用香薷饮加赤苓、木瓜等，透邪化湿，身热渐减。", ["弦", "细", "小"]], "15671": ["病机", "未识脉名，然证脉合参，冲龄阴亏邪陷。伏邪晚发，头额潮润则热清，不潮润则身中干热不爽，足征伏邪内陷不能外达。阴亏则邪陷愈深，故议益阴彻热法，冀其转机，使阴复邪透，热势得清。", []], "15672": ["病机", "脉象软小而濡，左脉沉细而弦，濡主湿，细主虚，弦主痛，沉主里。患者素体丰肥，湿痰中虚，又冒暑贪凉，过服温热，致暑伏湿阻。脉软小濡为暑湿伤气，左沉细弦为湿阻气机，与舌苔糙白、胸闷呕痰、小便短赤相应，故知其暑伏湿阻，治法未当。", ["濡", "细", "弦", "沉"]], "15673": ["主病", "脉象濡细，濡主湿，细主虚。先寒凛后发热，口干喜饮却不渴，舌苔腻白，小溲短赤，胸闷不饥，两足小腿觉冷，皆湿温之象。湿遏热伏，故脉濡细；湿阻气机，故胸闷不饥；湿性黏滞，故热无已时。此湿温病，服清暑剂不应，当从湿温论治。", ["濡", "细"]], "15674": ["病机", "右浮左弦，浮主表，弦主疟。风暑之邪搏于表，故右脉浮；疟邪伏于少阳，故左脉弦。症见先头痛畏寒，约半时即热，热至更余汗出热退，此风暑搏而成疟之典型发作。脉浮弦与寒热往来、头痛畏寒相应，故知其风暑搏而成疟。", ["浮", "弦"]], "15675": ["病机", "脉右沉细而紧，沉主里，细主虚，紧主寒主痛。胸脘刺痛，痛剧则胀，渐横至脐腹，夜间更增，脘中时响，皆沉寒痼冷、脾阳不运所致。紧脉为寒邪内结，沉细为阳气不足，与秋发冬甚、得温则减相应，故议附子理中汤加味温运脾阳。", ["沉", "细", "紧"]], "15676": ["预后", "脉小，小主虚，亦主邪陷。风温症身热不退半月，胸闷口渴不喜冷饮，舌苔中心绛边白无津，耳聋溲赤，脉小为正气不足、邪有内陷之势。脉小与舌绛无津、耳聋相应，提示邪热伤阴，防其内陷，故亟亟祛邪，冀其热退为稳。", ["小"]], "15677": ["病机", "脉右软，左弦细。右软主肺胃气虚，左弦细主肝阴不足、虚火内扰。咳嗽喉痒，夜甚于昼，天明渐已，痰出稠黏，为肺胃阴亏、虚火上炎之象。弦细为阴亏火旺，软为气弱，与夜咳痰黏相应，故宜清补肺胃之阴，俾火降而咳平。", ["软", "弦", "细"]], "15678": ["病机", "左脉细小兼数，细主阴亏，小主虚，数主火。上下齿龈作痛偏左，为心肝虚火上炎所致。左脉候心肝，细小数为阴血不足、虚火内动，与龈痛偏左相应，故法宜养阴以降火，阴复则火自降。", ["细", "小", "数"]], "15679": ["病机", "右关浮软，左弦细。右关候脾胃，浮软为脾虚气弱；左弦细为肝血不足、筋脉失养。症见腹膨有块，小腹疼痛，由阴囊上冲，食少体瘦，夜间发热足肿，此内疝任脉为病，病根深沉。弦细为肝虚，浮软为脾弱，与疝块上冲、肌皮骨立相应，故先以和肝法缓其病。", ["浮", "软", "弦", "细"]], "15680": ["病机", "左脉弦劲、右脉滑数，为温邪留恋气分之象。弦劲示邪郁不解、正气尚能与争，滑数主热盛于气分，故身热愈热愈渴、日饮数十瓯而不解。原文言误投陷胸、承气，致便溏热增、舌苔糙刺无津，阴液已涸，脉之弦劲滑数正反映邪热未去而津伤，故议竹叶石膏汤清热生津。", ["弦", "劲", "滑", "数"]], "15681": ["病机", "右脉弱、左脉细涩，原文断为血凝气滞。胸膺痛痹由劳力而得，三载举发无时，右弱示气分不足，左细涩示血少而运行不畅，血凝气滞则胸膺痹痛。脉细涩与瘀滞相应，弱与气虚相应，故治以养荣祛瘀、佐疏之和之，使气血渐通。", ["弱", "细", "涩"]], "15682": ["病机", "左脉细小难寻、右关中按小数，胸腹俱痛、苔腻白根黄、小便短赤，进温中即吐，知寒湿与郁热错杂。左细小示气血不畅、痛甚而脉道不利，右关小数主中焦郁热。原文断其湿与寒并，故以温凉并进和之，服后脘腹痛减而苔仍腻白，寒湿未化。", ["细", "小", "数"]], "15683": ["病机", "脉形软细，素体肥胖好酒贪荤而肌瘦、腹膨足肿肢痛，屡进燥湿未效。软细示脾虚湿困、气血不足，湿浊内停则腹胀足肿，肢节作痛亦湿流关节之象。原文先宜调中却湿、佐以疏运，正合脉软细所主中虚湿滞之机，非单纯燥湿可解。", ["软", "细"]], "15684": ["治法", "本段未识脉名，原文仅言证脉合参。进前方后脘腹渐松、便结已解而食仍未贪，日饮粥二三盏，示邪去而胃气未复。证脉合参后法当养胃生津，以图胃气旺而食饮渐贪，主旨在于据脉证定治法，属病后调养胃气之议。", []], "15685": ["病机", "脉象耎小，舌苔滞白、口淡溲赤、不喜饮，原文断为脾土不运、命火不足以生之。耎小示阳气不足、鼓动无力，脾运失健则口淡苔白，命火不温则水湿不化。虽口淡似胃热，然按脉审症当理脾胃兼补肾阳，脉耎小正是虚象之据。", ["耎", "小"]], "15686": ["病机", "脉象沉滞，原文谓中虚气壅，壅则痛，痛则不通。沉示病在中里，滞示气机壅塞不畅，中虚而气壅则脘腹作痛、食不甘。脉沉滞与气壅不通相应，故治当和其中、调其气，气舒则痛缓而食自贪，属中虚气滞之病机。", ["沉", "滞"]], "15687": ["病机", "脉来弦细小数，夜间内热波及四肢、口唇燥裂、牙龈出血，原文断为脾阴虚而荣血不足。细小数示阴血亏虚而内有虚热，弦示阴虚不能涵养、脉道失柔。冲龄阴弱，缠延周年，尤防骨蒸劳热，脉之细数正虚热内扰之征，故亟宜调摄。", ["弦", "细", "小", "数"]], "15688": ["病机", "脉形濡数，濡主湿、数主热，合之则为湿热内蕴。原文述“滞下红白，昼夜二十余度”“所下污秽异常，肛门甚热，小溲短赤”，皆湿热积滞下注大肠之象；久痢三月，体瘦食减，脾虚已显。故脉濡数反映脾虚兼湿热为患，主久痢，与湿热痢之红白冻、肛热、溲赤相应。", ["濡", "数"]], "15689": ["病机", "脉形细数，右脉虚芤。细数主阴亏火旺，虚芤为失血伤阴之征。原文“左鼻出血，十有二日”“阴气弥伤”，又经苦寒误投，衄血反增，举头即眩，显系阴火潜然，非实火。脉细数虚芤正合阴虚阳浮、络伤血溢之病机，主鼻衄阴伤，与眩晕、暮热等症相应。", ["细", "数", "虚", "芤"]], "15690": ["病机", "脉形软滑，左关弦细。软滑主虚而兼痰湿，弦细为肝脾不和之象。原文“三疟年余”“寒少热多，肌瘦食减，便结溲赤”，乃正虚而疟邪留恋，邪伏肝脾。脉软滑示正气已虚、痰湿内蕴，左关弦细应肝脾失调，故主正虚疟邪留恋之病机，与寒热、呓语、口渴等症相应。", ["软", "滑", "弦", "细"]], "15691": ["病机", "右脉细小，左关、尺濡小。细小主虚，濡小主湿滞中焦。原文“脘痛已久，午后尤甚，且有泛泛欲呕之势。素好饮茶”，饮茶多则湿伤脾，脾虚湿滞，气机不畅，故脘痛欲呕。脉细小濡小反映中焦虚而湿阻，主脾虚湿滞之脘痛，与午后痛甚、泛呕等症相应。", ["细", "小", "濡"]], "15692": ["病机", "脉象虚软，按之细数。虚软为气阴两虚，细数为阴虚内热。原文“素有吐血症”“喘兼咳”“卧不著枕，痰不易出，口燥舌干，大便溏薄，食饮日减”，显系肺脾两虚、气阴耗伤，虚火上炎。脉虚软细数正合气阴两虚、虚喘痰咳之病机，与喘咳、口燥、便溏等症相应。", ["虚", "软", "细", "数"]], "15693": ["预后", "脉息濡小，右软。濡小主脾胃虚弱、气血不足，右软尤显脾虚。原文“阴虚体质，内热咳嗽上气，缠绵年余”“脾胃日损，便泄不止，食饮维艰”，更兼鼻衄常发，阳络又伤。脉濡小软反映脾胃日损、气血难复，故曰“虚损之门，已露先机”，主虚损预后不良，与肌瘦肉削、便泄、食减等症相应。", ["濡", "小", "软"]], "15694": ["误治", "脉右虚耎，左弦硬。右虚耎为脾肺气虚，左弦硬为肝木偏亢。原文述误用熟地、枸杞、附子等滋腻温补，“喘咳反增”“食减，不能卧”，显系滋腻滞脾、腻膈生痰之误。脉右虚耎示脾肺久虚，左弦硬示肝木乘之，故主误治后病增之病机，与喘咳、食减、便溏等症相应。", ["虚", "耎", "弦", "硬"]], "15695": ["病机", "脉象两关弦细。弦主肝木，细主不足，两关候肝脾。原文“食后脐下作胀，脘中闭闷，嗳之不畅，酸水时呕，黏痰并出”“大便秘结”，显系肝木乘脾、土制于木，气机郁滞，痰湿内阻。脉两关弦细正合肝脾不和、木郁土虚之病机，主土制于木之胀闷呕酸，与便秘、嗳气等症相应。", ["弦", "细"]], "15696": ["病机", "右软左濡，右候脾，软为坤土不足、运化无力；左候肾，濡为坎水亏虚、阴精不充。脾虚失统则上吐红，肾亏不固则下遗白。原文点明“攸关坤土之不足，坎水之有亏”，又言脾恶湿、肾恶燥，二者调摄最难，故脉见软濡，主脾肾两亏、上下失守之病机。", ["软", "濡"]], "15697": ["病机", "脉形细耎不能鼓指，左三部濡小不足，细耎为阴气亏虚、脉道不充，濡小为卫阳不护、鼓动无力。故动辄冷汗，舌苔肥白，尾骶骨痛。原文谓“阴气亏而卫阳不护”，正合细耎濡小之象，主病后中气不足、阴阳两虚、汗出不止之机，故当扶阳益阴以止汗。", ["细", "耎", "濡", "小"]], "15698": ["治法", "本段未出脉名，以“随证脉而增减”论治。述进药后冷汗减而稍动有小汗，食不贪、胸闷额疼、舌苔腻白，判为阴虚体质兼阳弱，不可概用温热。前用附子理中乃救急从权，暂用取效。主旨在于随证脉权衡温补分量，兼顾进谷，属治法斟酌之论。", []], "15699": ["病机", "左脉沉细如丝，右脉稍大于左。沉细如丝为阴血亏耗、脉道不利；右大于左，示病久津伤而气分尚存。暑湿内侵，屡经清疏、清凉、消导、更衣诸法，便秘十余日不通，反增口糜咽干、舌淡白湿润、痰黏如胶，乃阴伤液涸、燥结于下、虚火上炎之机，非实热可攻。", ["沉", "细", "大"]], "15700": ["病机", "脉形软小，左弦细。软小为正气不足、痰湿内蕴；左弦细为肝风内动、筋脉失养。患者体丰嗜酒，猝然身蜷语謇、痰声如锯、神识模糊、手臂牵掣转里，有劲厥之象。原文断为“类中之萌”，脉软小弦细正合虚风挟痰、湿浊蒙窍之病机，深恐昏厥。", ["软", "小", "弦", "细"]], "15701": ["病机", "右脉浮软，左弦大。浮软为阴亏阳浮、气不内守；弦大为相火上升、肝阳偏亢。去秋衄血几至昏晕而脱，今期年复衄，先胸闷三四日而鼻衄随至。原文断“相火上升”，脉之浮软弦大正示阴虚火旺、迫血上溢之机，故治宜养阴降火兼逐瘀。", ["浮", "软", "弦", "大"]], "15702": ["病机", "两关沉细，关候脾胃。沉为病在里，细为气血不足、阳运无力。食入至戌即嗳出腐气或朝食原味，中宫奔响、腹胀、气下行即便泄有声，匝月不愈。原文谓“寒与湿食交阻”，脉沉细正合中阳不振、寒湿食积内阻之机，久防成膈，故宜温中却湿运食。", ["沉", "细"]], "15703": ["病机", "脉象浮紧，右滑。浮紧为寒湿外侵、经络拘急；右滑为痰湿内蕴。寒湿上侵颈肩，酸疼转侧维艰，波及两臂。原文防有痛痹之虞，浮紧主寒邪束表、气血凝滞，滑主湿痰流注，合示寒湿痹阻经络之病机，故拟舒风活血法。", ["浮", "紧", "滑"]], "15704": ["病机", "脉息软弱，与胃阳虚食饮不贪、荣阴亏夜寐少安相应。虚羸有年、肌瘦肉削，正气已衰，脉来软弱无力，示脾胃阳气不振、荣阴亏耗，气血生化乏源。气逆痰鸣、舌白无苔，为虚痰上泛、胃气不降之象，故深虑虚波之险，属本虚标急之候。", ["软", "弱"]], "15705": ["病机", "左寸虚数卜心神失守，左尺虚浮知肾水有亏；右关虚数而滑，则膏粱厚味阻滞中州、痰火内结。虚数示心肾阴亏火动，滑为痰火内蕴，故见火升心惕足冷、口苦口甜、痰黄黑、梦泄诸症。总由脾不媒合心肾，水火难济，痰火交结为患。", ["虚", "数", "滑"]], "15706": ["病机", "右脉软，左关尺虚弦。疝症有年兼滑精，肝肾亏于下，故左关尺虚弦；体肥痰多、食后腹膨，坤土不运，湿痰内滞，故右脉软。软为脾虚湿困，虚弦为肝肾不足而气机郁滞，总属肝脾肾三脏同病、虚实夹杂之候，故宜汤药后丸剂缓调。", ["软", "虚", "弦"]], "15707": ["病机", "右三部浮小软滑，左脉虚弦尺濡，病关足三阴。浮小软滑为脾虚湿痰内蕴、运化失职；左虚弦尺濡为肝肾阴亏、水不涵木、精关不固。故用异功散益气调脾祛湿痰，佐壮水滋木、温肾固精，使脾土得令、疝平精止，正合肝脾肾并治之法。", ["浮", "小", "软", "滑"]], "15708": ["病机", "脉象虚濡，与面色痿黄、面目虚浮、大腹膨胀、两足浮肿、便溏溲少、食减肌瘦相应。疡科过投清火解毒，湿气内蕴，中阳受损，脾不运化，水湿泛溢肌肤，故脉虚濡。虚为中气不足，濡为湿邪内渍，证名肿满，中虚挟湿，治宜温中除湿。", ["虚", "濡"]], "15709": ["病机", "右脉细小微数是其征。喉中燥痒咳呛、痰不易出、如有物阻，日发数次，由气上壅、火郁脑门，清肃之令不降。细小微数示肺胃阴伤、虚火内郁，气为火伴，故痰黏难出。脉细为阴亏，数为火郁，微小为气机不畅，正合燥痒咳呛之候。", ["细", "小", "微", "数"]], "15710": ["病机", "脉左弦细，小腹有块且疼，此疟邪内伏。弦为疟邪郁于少阳、气机不畅，细为体瘦食减、正不胜邪、阴血不足。前医妄用桂枝解肌、茅术石膏，疟势愈剧，正虚不可再攻。当以和阴阳为法，冀寒热速减，弦细之脉正示邪伏正虚之机。", ["弦", "细"]], "15711": ["病机", "脉形弦紧，绕脐作楚，寒为气阻。弦主痛、主气机郁滞，紧主寒、主收引，寒邪客于脐腹，气为寒阻，不通则痛。旧疾有年今始复发，已十日，脉弦紧示寒凝气滞之实象，故治宜温舒，散寒行气以解其阻。", ["弦", "紧"]], "15712": ["病机", "右虚软为脾肺气弱，左弦劲为木旺，尺濡小为水亏。阴亏体质潮热匝月，金虚水亏则木旺火升，相火内动扰心，故心神不静、咳呛喉疼、食少肌瘦。脉象与阴虚火旺、心肾不交之机相应，治宜养水保心，使心肾交而水火济。", ["虚", "软", "弦", "濡"]], "15713": ["病机", "气、食、湿交阻致胸闷骨节疼、舌苔白，本属邪阻气机。误进大黄及青麟丸辈攻下，伤及中阳，致腹痛甚剧、坐立难忍。脉沉细为里虚寒之象，非实积可攻，故法宜温舒，以温运舒展为治，不可再行攻伐。", ["沉", "细"]], "15714": ["病机", "暑热挟湿，屡投川连、厚朴、犀羚芩连及竹叶石膏汤，寒凉遏抑暑邪，阳明胃津已涸。右浮软无力为胃气受伤，左关弦细、尺濡为津亏湿恋。故口干喜饮、喉舌干、黏痰咳呛、不纳谷、小便短赤，一身津液尽为寒凉所困，暑热不能外达。", ["浮", "软", "弦", "濡"]], "15715": ["病机", "骤然泄泻昼夜无度，脉息沉细。沉主里，细主虚，泄泻无度则中阳受损、寒湿内侵。受寒挟湿，脾运失司，清浊不分而暴泻。脉沉细正合里寒湿盛、阳气不伸之机，故法从温舒，温中散寒、运脾化湿以止泻。", ["沉", "细"]], "15716": ["病机", "身热起病，荤面肉点食阻中宫，又犯房劳，阴气亏而暑湿留恋于内，未克达表，故身热忽轻忽重。水湿不得膀胱气化，同走阳明大肠而便泄，足冷由阴亏兼湿阻。脉濡细显为湿盛阴虚之征，邪达阳明多气多血之乡，犹可求治。", ["濡", "细"]], "15717": ["病机", "原文未识脉名，故脉象要素从缺。此证初起夜烦躁、渐有昏语，庸工误认夹阴伤寒，欲用茅术、厚朴、姜、桂温燥。作者指出重在暑湿夹食兼房劳，不过阴气有亏，年壮邪盛宜祛邪外达，不使内陷；纵热盛亦只较常热增重，乃阴虚阳往乘之，不可概作阴症温燥误治。", []], "15718": ["病机", "服药四帖便泄止、咳嗽渐减、食饮稍增，惟脉象仍软濡，舌苔绛剥。软濡为脾胃气虚、湿浊未化之象，绛剥示胃津未复。究关胃津未复、脾气未旺，皆由咳嗽内热及他医日投养阴滋腻之误。故首重脾胃，坤土一健则肺金得令，便泄咳嗽可安。", ["软", "濡"]], "15719": ["病机", "前用四君子汤加味而血止，两足常冷如冰、天寒愈甚，续以四君子加女贞、枸杞、牡蛎、鹿角霜及归脾汤加减。至岁暮严寒脉象虚软，为气血两亏、脾肾阳弱之征，故间以益气养荣之法调理收功，终得体丰神健，乃再生之福。", ["虚", "软"]], "15720": ["病机", "脉形弦数，弦主湿郁气滞，数主火郁于内。患者好酒贪色、寓所潮湿，湿与火交蒸下注，故小便淋閟、涓滴难忍、内如刀割、出时腰弯背曲。弦数相合，正合湿火内郁之机，故用木通、赤苓、猪苓、泽泻、山栀、萹蓄、瞿麦等清利湿热而霍然。", ["弦", "数"]], "15721": ["病机", "脉息濡细，濡主湿滞，细主脾虚。素好酒面厚味，脾土久亏，湿食交阻，气机壅塞，故脘腹胀痛、得食愈增、舌苔厚浊腻滞、大便三日不通、小溲短赤热臭。濡细之脉正示脾虚湿困、气壅食阻之机，故先以舒通法治标。", ["濡", "细"]], "15722": ["病机", "右关细硬，左脉弦劲。右关候脾，细硬为脾虚湿阻、气机壅滞；左脉弦劲为肝木偏旺。病愈后胸脘作胀、小腹兼疼、知饥不敢多进，正是气壅湿阻、上胀下疼，病在脾而波及于肝。弦劲细硬并见，示土虚木乘、湿阻气滞之机，故宜温中运湿、舒补兼施。", ["细", "硬", "弦", "劲"]], "15723": ["病机", "脉象忽迟忽数、三五不调，忽止忽来，静则神安、烦则火升。胸中摇荡为怔忡，左乳下虚里跳动异常如沸羹，火升头眩、舌尖刺痛。土虚木摇、水亏火起，病关心脾肾肝，脉之迟数无常正示宗气不虚而虚、升降失司之机，故非轻候。", ["迟", "数"]], "15724": ["病机", "此段引《经》文释虚里之动，指出无常之脉指左乳下之动脉为言。有常则宗气不虚，无常则宗气大虚，上焦之气恹恹不足。动之应手而无常，正是宗气泄越、胃之大络失守之象，故以虚里动诊宗气盛衰，非寻常寸口之脉可比。", ["动"]], "15725": ["病机", "服此一帖诸恙若失，惟右脉弦硬、左脉未静。右脉弦硬示脾土湿滞未化、气机尚欠柔和；左脉未静则肝木未平。虽饥亦非昨之饥不待食可比，知胃气渐复而湿浊余邪未尽，弦硬之脉正提示中焦运化未全复常，故究宜加意图维。", ["弦", "硬"]], "15726": ["病机", "本段未识脉名，证脉合参而论病机。心荡则火升面红、舌中心裂纹两边红、口苦不喜饮、胸闷气阻，火欲升不能、欲降不得。固关中虚阴亏，亦由心思过度、郁闷不舒，升降不灵。屡发之由在七情郁结触发，故云实病易治、七情难疗，先以黄连汤治标。", []], "15727": ["预后", "脉象浮之小、中按沉滞、再按无力。浮小示表气不足，沉滞示里积未化，再按无力则正气已虚。滞下昼夜三十余度、寒热腹膨、面目虚浮，有表里两感之势；素喘咳痰饮、房帏不节、体弱肌瘦，脉证相参，正虚邪恋，故曰险在此耳，预后堪虑。", ["浮", "小", "沉", "滞"]], "15728": ["病机", "脉沉紧，沉主里，紧主寒主痛。原文述畏寒身热、脐腹绞痛、小便赤、大便秘、舌苔满白，显系寒邪与气食交阻于里，阳气不宣，故脉见沉紧。紧脉为寒凝气滞、痛势剧烈之征，与脐腹绞痛相应。法宜温散，方用苏叶、干姜等温通，正是针对寒凝气滞之病机。", ["沉", "紧"]], "15729": ["病机", "脉形细耎（软），细主阴血不足，软主气虚。患者体素瘦、食少溲赤、舌腻苔白，痛剧防厥，脉细软示正气已虚，不耐攻伐。原文强调“脉软痛甚，食少体弱，倘经攻伐，便泄、汗出而脱”，说明此脉主正虚邪滞之病机，故以温理中宫为法，忌用通便峻剂。", ["细", "软"]], "15730": ["病机", "脉象沉滞，沉主里，滞主气机不畅。痛症数年，举发无时，痛于脐之左右，甚则呕吐食物，显系肝胃气滞、寒湿内阻。沉滞之脉反映病在里而气机郁滞，与肝胃为病相合。法宜温舒，即温通疏理，使气机调畅，则痛可缓解。", ["沉", "滞"]], "15731": ["病机", "脉息濡软，关小弦。濡软主脾虚湿困，小弦为肝木不舒。原文谓“坤土虚而震木不滋”，又兼素好浓茶湿阻中宫，故肠红远血。此脉示肝脾同病、土虚木郁、湿阻中焦之病机，法宜肝脾并治，健脾化湿与柔肝并举。", ["濡", "软", "弦", "小"]], "15732": ["病机", "脉象弦细，弦主痛主滞，细主阴伤。滞下逼迫，水多于粪，昼夜十有余次，腹痛里急后重，显系暑湿挟积阻滞肠道，气机不通。弦细之脉反映积滞内阻而阴液已伤，故宜舒通，通则不痛，但须兼顾阴分，不可过用峻下。", ["弦", "细"]], "15733": ["病机", "脉右软小，左濡细。软小濡细皆主虚，右关候脾，左关候肝。冲年质弱，肌瘦食少，咳嗽将痊，脉见软小濡细，示脾肺气虚、阴液不足。原文谓“益气养阴则坎水自充”“调脾运食则坤土日旺”，说明此脉主气阴两虚、脾运不健之病机，治当培补。", ["软", "小", "濡", "细"]], "15734": ["病机", "脉形浮滑，继则滑数。浮主表，滑主痰食，数主热。过啖厚味，食填太阴，适感温邪，身热头胀胸闷，舌腻苔白，脉浮滑，示食滞兼表邪。后热不解，神昏乱语，痰黏如胶，脉转滑数，为食滞湿温化热，痰热蒙蔽心包之病机，故见神识似清非清、行坐不定。", ["浮", "滑", "数"]], "15735": ["病机", "脉形右滑数，左弦细。右滑数主痰热食滞，左弦细主肝阴不足、木郁不舒。过啖厚味，外受风寒，身热胸闷，神识似清非清，乱语，吐黏腻如胶之痰，证与前次颇同。此脉示痰食化热、蒙蔽心包，兼肝阴亏虚之病机，故见朝轻暮重、起坐不安。", ["滑", "数", "弦", "细"]], "15736": ["病机", "脉形右大左小，右候肺脾，左候心肝肾。暑风挟湿，热不发扬，邪内蕴，故右脉大主邪壅气分，左脉小示营分受抑、邪未外达。症见头疼如蒙、身热无汗、体倦好眠、口淡多痰、胸闷不饥，皆暑湿内蕴、气机不宣之象，故曰未可忽视，祛暑却湿为宜。", ["大", "小"]], "15737": ["病机", "脉息软弱乏力，为脾胃气虚、肾气亏损之征。原文言痰之生皆由脾胃不运、肾气有亏，脾为生痰之原，胃为贮痰之器。脉弱正合中气不足、运化无力，故痰凝厚结、咳咯艰难，气阻咽嗌如刀刺，呼吸不灵，皆虚中夹痰、本虚标实之候。", ["弱"]], "15738": ["预后", "脉息微弱，色脉同参，主脾土不温、坎阳不足。虚鼓将成，面目小腿虚浮波及小腹，手足阴囊肿胀，虚羸之体恐难胜任。脉微弱示阳气衰微、根本欲脱，故虑其一脱，以温中养胃、金匮肾气丸收摄肾气为法，属危候预后之判。", ["微", "弱"]], "15739": ["病机", "原文未识脉名，然详证可知阳弱阴衰。阴囊冷重胀大、阴头光亮如卵、小溲甚少、不能平卧，皆肾阳衰微、水气泛滥之候。作者斥峻攻痰积之误，主张肾气丸益火之源以消阴翳，收摄肾气使水不泛滥，故本段主旨在水泛阳衰之病机。", []], "15740": ["病机", "脉尚缓和，示胃气未败、生机尚存。服温中之剂后腹中甚热、手臂牵掣、目闭神呆、喉中痰声，有发厥之势，乃温药入胃与积痰相争，上则痰涎阻塞，下则遗屎，皆温热之性所致。脉缓和说明正气尚能承受，非真元骤脱，故可相机调治。", ["缓", "和"]], "15741": ["病机", "脉象濡数，濡主湿、数主热，合温邪十日、胸闷无汗、口干喜饮温汤、黏痰阻喉、舌胎淡黄无津、不饥溲赤，显系湿温蕴阻气分、热为湿遏之候。早投寒凉致恶心频频，邪未外达而内传，故宜泻心合陷胸，达邪退热，免其骤变。", ["濡", "数"]], "15742": ["病机", "右脉虚滑、左脉虚弦，右候脾肺，虚滑为脾阳不运、湿痰内停；左候肝肾，虚弦为肾阴有亏、木失涵养。素有湿痰，病起半载，误用滚痰丸、三子养亲汤消痰，脾土日亏，又投苦寒致腹痛不食、泻多白沫、畏寒，皆误治伤中之变，故先以苓桂术甘温运中焦。", ["虚", "滑", "弦"]], "15743": ["病机", "左小右大，脾胃脉来弦滑，中按无力。弦为肝木乘土、气机郁滞，滑为痰涎内壅，中按无力则胃土久伤、津液不充、胃中枯槁。酒火久伤，食入则噎、呕吐稠痰、粥饮即吐，正是反胃噎膈之渐，本虚标实，故议定呕化痰以急治其标。", ["弦", "滑", "小", "大"]], "15744": ["病机", "年高脉弱，示正气已虚，脾胃坤土受火酒所伤，运化失职，气机壅滞，遂成噎膈。脉弱为脾胃气衰之征，故服药应手后当加意调治，使坤土得令，庶可图安。", ["弱"]], "15745": ["病机", "右关脉来弦硬，左脉弦细，弦主痛、主饮，硬为气结，细为阴伤。自幼痛症，渐胀渐痛渐呕水，水声漉漉，右更甚，乃水饮内停、肝木乘脾、气机壅塞之候，久病大肉消瘦，正气已衰。", ["弦", "硬", "细"]], "15746": ["预后", "脉较前细小，趺阳脉亦较前细小，趺阳主胃气，细小为胃气衰少之象。虽呕痛暂平，然久病不节饮食、不能静养，病深药浅，胃气渐弱，故脉见细小，幸无头汗发厥，尚未至脱。", ["细", "小"]], "15747": ["病机", "原文未出脉名，然细绎病情，呕哕为反胃噎膈之渐。素好饮酒，酒后贪浓茶水果，坤土暗耗，寒气伤胃归肾，坎阳不升，离阴不降，水火隔而心肾乖，脾胃虚而君相动，遂致呕哕噎膈。", []], "15748": ["病机", "两寸细小，关脉虚耎，寸主心肺，关主脾胃。素多劳心会计，预事心烦，则心脾两伤，胃中郁郁不舒，呕哕咳呛喉痒。脉细小虚耎，示气血不足、心脾亏虚，故先调心脾。", ["细", "小", "虚", "耎"]], "15749": ["病机", "右关渐起，而两寸、尺尚嫌濡软，濡软为气血不充、真阳有亏之象。关脉渐起示脾胃稍复，寸尺濡软则心肾阳气未振，故宜调中益气，兼治心肾。", ["濡", "软"]], "15750": ["病机", "脉象虚细兼滑，虚细为正气不足，滑主痰湿。病起于潮湿受寒，胸前胀闷，心窝下起梗如指粗，按之如长竿，乃痰湿交阻、凝滞脘中，结郁成条，似伏梁之征，症经三载，沉疴积岁。", ["虚", "细", "滑"]], "15751": ["病机", "脉象虚细小数，两尺濡耎，虚细为肺金虚，小数为相火升，濡耎为肾水不充。素有喘咳呛血，逢节或劳心即发，今旧恙复发，咳痰挟血，乃肺虚肾亏、相火升而气逆呛血，幸胃脉尚平，犹可图维。", ["虚", "细", "小", "数"]], "15752": ["主病", "脉象沉紧，沉主里、紧主寒主痛。寒邪内伏，阳气被遏，故畏寒、舌白；寒凝气滞，胸阳不展则胸闷作痛；寒饮犯胃、胃气上逆，故得食即呕吐极重。沉紧相合，正示里寒凝滞、气机不通之病机，与畏寒、胸闷痛、呕吐症候相应。", ["沉", "紧"]], "15753": ["病机", "六脉沉紧，沉为在里，紧为寒凝。原文谓得之冬间伏寒，又纵啖湿面，致中宫气阻、食滞痰凝，故舌苔白泥如粉、胸前闭闷、食入气逆呕吐、脘中时痛；寒凝气阻，二便不疏，故溲赤如血、大便半月未解。沉紧正主里寒痰食交阻、表里两感之机。", ["沉", "紧"]], "15754": ["病机", "脉息细小，细主湿滞、小主正虚。素患脚气，侨居卑湿，暑湿夹食阻滞中宫，上下不疏，故两足肿胀、脘腹攻痛、头胀、舌苔糙泥、遍体酸疼、欲呕不饥、小溲少。脉细小示湿浊内阻而正气不畅，与暑湿夹食、中宫阻滞之病机相合。", ["细", "小"]], "15755": ["主病", "脉象浮缓小数，浮主表、数主热、缓主风。时行感冒，风火上攻，故头胀、耳聋且鸣、咽嗌不爽；热灼津伤，大便七八日未解，舌胎泥黄。浮缓小数示风火在表兼里热之候，原文谓是非轻候，法宜清解，正合此病机。", ["浮", "缓", "小", "数"]], "15756": ["病机", "脉息沉细软小，沉细主里虚，软小主湿盛正衰。西人好啖面食，南方卑湿，脾土不运，水湿浸淫，故肢体漫肿自腿足及阴囊茎俱肿，便溏腹胀。脉沉细软小示脾肾阳虚、水湿泛滥，原文谓湿鼓将成、脾肾攸关，正指此病机。", ["沉", "细", "软", "小"]], "15757": ["主病", "原文未识脉名，仅言证脉合参。因贪凉饮酒，暑湿挟食内阻，故半夜腹痛甚剧、呕之不畅、吐之不爽，此属霍乱。虽无脉象可引，然证脉合参示暑湿食滞交阻中焦、升降失司之机，治当温舒，与吐泻腹痛症候相应。", []], "15758": ["病机", "脉息濡软，濡主湿、软主气虚。湿阻中宫，胃土不和，故心似荡、不知饥、舌苔白腻。濡软之脉正示湿浊内蕴、脾胃气弱、运化失司之病机，原文谓当理阳明为最，即从湿阻中宫、胃土不和立论。", ["濡", "软"]], "15759": ["病机", "脉形虚濡小数，虚濡主肝肾亏虚、小数为阴亏内热。肝主疏泄、肾主闭藏，梦泄无时兼腰疼，晡热溲赤，固属肝肾有亏，亦关心荣不足。虚濡小数正示肝肾阴亏、虚热内扰、疏泄闭藏失职之病机，与梦泄、腰疼、晡热症候相应。", ["虚", "濡", "小", "数"]], "15760": ["病机", "脉息濡数，濡为湿滞，数为热象，合之则示相火不藏、湿热内扰。原文谓“相火升而水不能济”，故见晡热渐退而舌苔尚泥、耳鸣精滑，皆火升水亏、心肾不交之候。濡数之脉正是水火失济、相火妄动之征，故当于心肾求治，以媒合坎离。", ["濡", "数"]], "15761": ["病机", "右脉虚软，左部濡下，虚软为气弱，濡下为水亏。原文直指“肺肾两亏之征”，盖肾主水、肺主气，气水互化失司，则脉见虚软濡下。此脉象反映肺肾气水两亏，百脉流通不畅，故以“一气贯注”为要，提示当从肺肾调治。", ["虚", "软", "濡"]], "15762": ["主病", "脉象细耎，左弦紧，细耎为湿滞，弦紧为寒痛。原文述风寒湿三气合而为痹，致四肢肩背牵引板滞、头重筋强，舌苔泥白如粉。细耎示湿邪内蕴，弦紧主寒凝痛剧，合之正合痹证寒湿偏盛之病机，故亟以祛风逐湿、散寒温中为治。", ["细", "耎", "弦", "紧"]], "15763": ["预后", "原文未识脉名，然述大病后复感温邪，大汗而解，仍口渴昏语、舌绛痰多，证脉合参为“痰火留恋”“虚实相兼”。次日便先结后溏，断为“脱势之象”，虽用清热化痰之剂而依然如前，故预后难稳，不得已拟助正生津以应。", []], "15764": ["主病", "脉息浮小，浮为邪在表，小为正气不足。原文谓痛症有年，今感寒气阻、湿食相凝，致呕痰畏冷、胸脘痛剧。浮小之脉示寒湿食滞阻遏气机而正虚不充，故疏气活血不应，改用温中化滞、理气止痛而呕止，然胸脘仍痛，可见病机重在寒湿食积。", ["浮", "小"]], "15765": ["预后", "脉浮小况滑，浮小为正气衰微，滑为痰食内蕴。原文述伤寒垂危，因食年糕荤腥动伏寒，误投寒凉致神昏呓语、尿出无知。浮小示正虚欲脱，滑示痰食未化，奄奄一息而口鼻热气直冲，故断为难图救，属危候预后不良。", ["浮", "小", "滑"]], "15766": ["病机", "脉右软小，左弦大，软小为正气虚，弦大为邪气盛。原文述邪闭心包，神识昏昧、呓语绵绵、舌泥干糙，更见摄拳手痉，此正虚邪恋、肝风内动之象。右软小示正虚，左弦大示邪热鸱张，故曰“棘手极矣”，拟辅正祛邪。", ["软", "小", "弦", "大"]], "15767": ["预后", "原文述复诊时问答稍明、热退大半，脉右如昨，左之弦大已减。左弦大为邪盛之征，今减则示邪势渐退，故断为“倦怠而非脱势”，预后转佳。再以昨方去苦寒之品，服后日渐平妥，两剂而愈，可见脉象改善与症候相应，为向愈之兆。", ["弦", "大"]], "15768": ["病机", "原文未明言脉象，但据“寒时戛齿鼓颔，战栗恶寒”与“色脉”合参，可知寒甚于热，病机为风暑相搏、营卫不和。胎疟初发，寒热交作，虽热长寒短，然寒战之象显著，故治法先和营卫，使寒减热缓，再图他治。", []], "15769": ["病机", "脉象虚滑，左弦尺濡。虚滑主脾肺久虚，土不生金，痰湿内壅；左弦为木寡于畏，肝气犯肺；尺濡为肾水不足，肝失滋养。故见痰升咳嗽、多汗涎沫，法宜补土生金、滋水养木。", ["虚", "滑", "弦", "濡"]], "15770": ["主病", "脉形浮弦，浮主表邪，弦主气机不畅。症见陡然寒热、背疼胸闷、呕吐、脘腹痛有汗，显系外邪束表、内阻气机，故用疏解法，服后背疼止、呕平，脉证相应。", ["浮", "弦"]], "15771": ["兼症", "脉息浮滑，左弦细。浮滑主痰湿内蕴，弦细主气滞痛剧。症见脘腹痛甚叫呼、手指厥冷、有汗、便欲解不解、口不喜饮、苔糙刺泥黄，乃痰湿食滞交阻、蛔虫内扰之候，故宜舒运安蛔止痛，兼润燥通幽。", ["浮", "滑", "弦", "细"]], "15772": ["病机", "脉象浮弦，浮为风火升浮，弦为相火内动。右齿疼痛无宁，乃风火上攻，引动相火，火性急迫故痛无宁时。治在轻清，以清散风火，使火降痛止。", ["浮", "弦"]], "15773": ["病机", "脉息右弱，左弦细，后述右细耎、左小弦。右弱为脾虚，细耎为湿痰内蕴；左弦细为肝木乘脾。素体虚肥多湿痰，便溏多年，感冒后精神日疲、尿便不由自主，显系脾肾两虚、湿阻中宫，故宜却寒和中。", ["弱", "弦", "细", "耎"]], "15774": ["病机", "脉形浮软，浮主风暑在表，软主湿邪内郁。症见手足逆冷、皮寒毛耸，继而渐热有汗则爽，忽寒忽热，乃风暑挟湿、三气交阻，营卫失和。病前夺精只是阴亏，不可作夹阴论治。", ["浮", "软"]], "15775": ["病机", "脉右大于左，右脉主脾胃，大为邪盛。长夏湿升，胃土不和，脉络不利，故手臂肩项牵疼、口黏溲赤、舌苔泥白中黄。治宜和胃却湿，使湿化胃和，则脉络自利。", ["大"]], "15776": ["主病", "脉沉弦为寒邪内侵、气机凝滞之象。沉主里、主下焦，弦主痛、主寒凝收引。睾丸偏左肿痛，乃寒客厥阴、气血壅阻所致，故脉见沉弦。原文明言“受寒所致”，治以“温舒下焦”，正合寒者温之、结者散之之法，脉证相参，病机昭然。", ["沉", "弦"]], "15777": ["病机", "体伟脉软，两关弦细，左尺濡小，合参为“中虚挟湿”之躯。软、濡主虚主湿，弦细应肝脾。鼻洪过伙致阳络大伤，血去气不能统，胃络受损，湿浊内蕴，清阳不升，头风由生。头脑畏风、得汗方平，逢夏安遇冬发，皆中虚湿阻、卫外不固之征，脉象与证候丝丝相扣。", ["软", "弦", "细", "濡"]], "15778": ["主病", "左脉弦数，弦主痛、主气滞，数主热、主急。溲出茎中疼痛、败精留阻、频出无时，乃淋症之候，湿热败浊壅遏溺窍，气机不通则痛。原文斥“妄作白浊治故无功”，正因脉弦数示有郁热实邪，非虚滑之白浊可比，故宜舒通，通则不痛，脉证相符。", ["弦", "数"]], "15779": ["病机", "大病将痊而脉形虚软，虚软为气血未复、脾阳不振之象。脾阳未复则运化机迟，荣阴不滋则肠燥便闭。脉虚软正应中气亏虚、荣血不足，故治以补中调荣，使气充血行、阴阳和畅。高年恙后见此脉，示正气尚弱，须缓图补益，与原文“颇合时宜”相呼应。", ["虚", "软"]], "15780": ["病机", "脉息耎小，左弦细，耎小主脾土虚弱，弦细应肝木偏旺。脘痛八年、食入不爽似胀、午后发作，乃湿土气阻、中州失运，生湿成痰所致。坤土弱而震木乘之，故左脉弦细，预示呕吐酸苦之变。脉象已显土虚木乘之明征，与原文“尤显有明征耶”正合。", ["耎", "小", "弦", "细"]], "15781": ["病机", "脉来虚濡乏力，虚主阴亏、濡主湿滞。素好饮酒，酒湿伤阴，阴亏体质，夜间手足发热已久，乃阴虚内热之征。虚濡乏力示气阴两伤、湿浊未化，故防潮热骨蒸之变。原文亟宜退热，正因脉虚濡而热象已露，阴亏为本、虚热为标，脉证相参可明。", ["虚", "濡"]], "15782": ["病机", "脉右细耎，细主虚、耎主弱，右脉应肺脾。脾土不舒则胸脘易闷、食无味；肺卫表疏则易冒风、鼻流清涕。额热头疼时有时无，合脉细耎而无浮紧之象，故断“无风寒食阻”，究属内因，攸关脾肺。原文“护表和中”正合虚而兼疏之病机，非外邪实阻可比。", ["细", "耎"]], "15783": ["病机", "脉息沉细难寻，沉主里、细主虚，示胃络大伤、气血亏耗。脘痛经月、痛剧伛偻、朝轻夕重，舌苔淡黄泥浊边绛，乃久痛入络、胃气大伤之候。沉细难寻说明正气已虚，苦寒攻伐更伤中阳，故权拟温舒法以冀转机。脉证合参，虚中夹滞，不可再伐。", ["沉", "细"]], "15784": ["病机", "脉右弦数，弦主肝郁气滞，数主热，右部候肺脾，痧后余邪未楚，药饵乱投，致热邪蕴肺，故咳嗽痰厚、咽嗌色红、上腭红点、声哑音低、咽唾觉痛；食减饮粥为脾胃受困。脉症合参，示余热未清、肺胃阴伤，深虑痧劳之险。", ["弦", "数"]], "15785": ["病机", "脉象浮软，浮主表，软主虚，冲龄质弱，外为风搏，内为热阻，故似寒似热；屡进寒凉，热终不解而兼寒凛，食减神倦，乃正虚邪恋、表里不和。脉浮软示风邪在表、正气不足，防甚转疟，故拟轻舒法。", ["浮", "软"]], "15786": ["病机", "脉息软大、左弦，软大主中虚湿蕴，左弦主肝郁克脾。病后中虚，湿蕴坤土，发为黄疸，身目指甲俱黄、色滞而晦，乃湿浊内阻、脾运失健。脉软大为正虚湿盛，弦为土虚木乘，故先从温中却湿治。", ["软", "大", "弦"]], "15787": ["病机", "脉左虚弦，右软滑无力。虚弦为阳弱阴亏、肝木失养，软滑无力为脾土不运、湿滞内蕴。病后屡复，食饮不节，脾不运而积滞，水湿泛溢，故足跗渐浮、腿足皆肿、大腹如鼓、小溲甚少、便溏腹痛。鼓胀已成，虚实相兼，最难调治。", ["虚", "弦", "软", "滑"]], "15788": ["病机", "脉形弦急，弦主水饮内停、肝脾不和，急主病势急迫。伤寒后恣食油腻荤腥，病后屡复，脾土日惫，积滞丛生，湿气内蕴，水凌土位，故腿足皆肿、面目俱浮、大腹膨胀脐凸、便泄而小溲全无。此虚实相兼之鼓，脉弦急示水湿壅盛、脾土受困。", ["弦", "急"]], "15789": ["预后", "脉来濡耎，濡主湿，耎为软弱，高年见之，示湿阻而正气已衰。利由泄泻而起，便时一响而溜出、色黄不痛、小便短少、口不喜饮、舌苔淡黄边白，皆湿阻中焦之象。服药应手，惟高年脉濡耎，正气难复，究防变幻。", ["濡", "耎"]], "15790": ["病机", "脉象细小，细主阴伤，小主正虚，亦主邪闭。身热胸闷、苔腻白如粉、骨节疼痛、不饥不渴、体倦昏语，乃风寒内闭、食阻中焦，阳气不得宣通。脉细小示邪闭正虚，故治宜温舒，得汗为妥，汗后热退胸宽。", ["细", "小"]], "15791": ["病机", "脉形弦数，按之不足。弦主肝郁，数主火，按之不足为阴亏。淋症廿余日，溲出兼疼、茎中带痒、大便秘结，旧有痔疾脱肛，乃阴亏挟湿火，灯后浊甚、静少动多、色带淡黄。脉弦数示湿火内蕴，按之不足示阴分已亏，故拟益阴降火、升清降浊。", ["弦", "数"]], "15792": ["病机", "脉息濡小，濡主湿、小主虚，提示正气不足而湿浊内蕴。原文述喉腐未痊、舌苔泥白、中心淡黄、夜寐呓语，乃相火升而风痰上扰，湿热未清。脉濡小说明正虚湿恋，无力托邪外达，故虽溃脓后痛缓热平，忽复热而喉腐由右移左，深恐变幻。", ["濡", "小"]], "15793": ["病机", "脉息浮小，左手弦细。浮为邪在表，小为阴亏，弦细属阴血不足而邪伏于内。原文谓病得于夺精之后，阴亏之体，时邪内伏，故见凛凛而后热、胸前气闷、舌苔白泥、便溏、烦躁。脉浮小示邪欲外达而正虚无力，弦细示阴亏，故宜俾邪由内达外，免其变幻。", ["浮", "小", "弦", "细"]], "15794": ["病机", "脉形沉细，沉主里、细主虚，亦主湿滞。原文述素好湿面，脘腹痛胀难忍，乃寒与湿食交阻于中焦，气机壅塞。脉沉细说明病在里而正气不足，湿食内结，故用香附、草蔻、半夏、莱菔等温通消导，服后痛胀更剧，是邪正相争、药力未达之象。", ["沉", "细"]], "15795": ["病机", "脉仍沉细，说明寒湿食积仍阻于里，正气未复。原文述脐腹上下痛胀甚剧、舌苔中心淡黄、小溲赤、大便三日未解，乃湿郁化热、腑气不通之象。脉沉细而未见实大，故未便遽投攻伐，宜以温舒，冀痛缓胀平，示里实而正虚，不可峻下。", ["沉", "细"]], "15796": ["病机", "脉象浮紧，浮主表、紧主寒，为风寒束肺之征。原文述客途暴疾，气逆畏冷，咳嗽痰稠，舌苔白泥如粉，乃风寒外袭，肺气失宣，痰湿内蕴。脉浮紧说明邪在表而寒性收引，故气逆畏冷；素有吐血症，内虚之躯，不可藐视，示正虚而邪实。", ["浮", "紧"]], "15797": ["病机", "脉息弦数，弦主痛、主肝，数主热。原文述溲出痛如针刺，淋症初起，乃败精留阻，湿热蕴结下焦，气机不畅。脉弦数说明湿热内盛、气滞不通，故小便刺痛；治以舒通为最，示当清利湿热、通淋化浊，使败精去而淋自愈。", ["弦", "数"]], "15798": ["病机", "脉形弦细小数，弦主邪郁，细主阴亏，小示正虚，数主热。原文述身热忽辍忽作、胸脘稍闷、微咳、舌苔中心淡黄、四肢清凉，乃感冒时酸之邪，非湿温症。脉弦细小数说明邪伏半表半里，阴分不足，故寒凛而后热，热亦不盛，非阴虚内陷之候。", ["弦", "细", "小", "数"]], "15799": ["病机", "脉象弦细，弦主邪在半表半里，细主阴血不足。原文述申初先凛凛而后热，未几汗出热退如平人，乃时酸之邪伏于膜原半表半里之间，渐转为时疟。脉弦细说明邪郁少阳而阴分不足，故寒热间作，汗出热退，益信前言之不爽。", ["弦", "细"]], "15800": ["病机", "脉浮濡细小，浮为风邪外袭，濡细为湿食内阻、气血不充。外风搏结，内湿食交阻，气机不畅，故见身微热、舌苔白、腹痛水泻。脉症合参，病机为外风引动内湿食滞，脾胃升降失司。", ["浮", "濡", "细", "小"]], "15801": ["病机", "年近古稀，坤土弱而坎阳不足，脉息虚耎，为脾肾气阳两虚之象。脾虚不运则便溏、食入不运；肾阳不足则不能温煦。咳呛痰少，乃脾肺同病。脉虚耎正合火土衰微、气不充脉之机。", ["虚", "耎"]], "15802": ["病机", "脉右软尺弱，右关候脾，尺候肾。右软为脾土虚弱，尺弱为肾阳不足。脾肾火土并衰，故不饥纳少。议火土并治法，正合脉象所示火不生土、土不制水之病机。", ["软", "弱"]], "15803": ["病机", "暑湿夹食成疟，脉形弦细。弦主疟邪内踞、气机郁滞，细为湿食困阻、气血不充。寒热间日发、胸闷呕泻、苔白泥，皆暑湿食滞交阻膜原、脾胃升降失职之候。脉弦细正合邪郁湿滞之机。", ["弦", "细"]], "15804": ["病机", "脉息沉紧，沉主里、紧主寒主痛。气闭受寒，寒凝气滞，故身热胸闷、腹痛呕吐蛔虫、苔白泥。沉紧为寒邪内闭、气机不通之象，温舒散寒则脉症相应，故服后热退呕平痛缓。", ["沉", "紧"]], "15805": ["病机", "脉象沉迟，两尺浮耎。沉迟为脾土不运、寒湿内阻，故胸脘气闷、得食即胀、悠悠而疼、苔白泥、口不喜饮；两尺浮耎为肝肾亏虚。病经廿余日，脾运失职、肝肾不足，火土并亏，故温中不应，需扶脾温肾并治。", ["沉", "迟", "浮", "耎"]], "15806": ["病机", "脉来细耎小滑，细耎小为气血不足、湿痰内阻，滑主痰湿。痛痹复发，右腿膝壅滞不能下行，乃湿痰阻络、气血不畅。脉细耎小滑正合湿痰阻络、本虚标实之病机，故以温舒为治。", ["细", "耎", "小", "滑"]], "15807": ["病机", "脉息沉迟，沉主里、迟主寒。因舟底漏水惊吓，引动旧恙痛症，朝轻夕重如刀刺，在于歧骨间太阴少阴所居之地。沉迟为寒凝气滞、血行不畅之象，久痛恐见血，故先调气和荣、佐以温舒。", ["沉", "迟"]], "15808": ["病机", "年高脉弱，中气久虚，故痛症有年而此次最剧；心嘈易饥、得食渐平，乃胃虚求食自救之象。脉弱主气虚，脾肺不足，心荣失养，故治当益气和中，肺胃并治，兼养心荣。", ["弱"]], "15809": ["病机", "脉象沉滞，气荣交阻，故歧骨间痛复发，夜甚于昼。沉为气陷，滞为血涩，劳心之后气机郁滞，荣血不畅，不通则痛，权拟温舒以行气活血。", ["沉", "滞"]], "15810": ["其他", "此段为案语总结，强调医贵灵机活变，切脉审证不可拘泥板法，非专论某脉主病。原文未出具体脉象，故脉象要素为空，主旨在于治法当灵活变通。", []], "15811": ["病机", "脉息沉滞，左弦乏力，沉滞主气荣郁阻，左弦乏力为肝胃不和、肝气横逆。故痛起歧骨间，昼轻夜重，痛剧呕吐酸黄黑水，气逆呃忒，病关心荣肺胃兼肝胃，议仲景和法。", ["沉", "滞", "弦"]], "15812": ["预后", "原文未出脉名，但言「色脉合参，再痛防其厥脱」，乃据色脉判断预后险恶。痛呕酸黑水，胃气大伤，再痛则防厥脱，故议代赭旋覆汤以冀转机，属预后判断。", []], "15813": ["病机", "高年脉弱，左弦急，弱主气衰，弦急为肝木乘脾、动怒劳神所致。故痛呕呃逆并至，味酸色黑属肝肾，气逆且呃属肺虚，心脾肝肾皆伤，脉症不符，最不相宜。", ["弱", "弦", "急"]], "15814": ["预后", "原文未出具体脉名，仅言「平素脉带阴象」，阴象指脉沉细柔缓，为根基尚固之征，故谓永年之基。主旨劝静养调摄，戒烦劳多语，使食饮贪、精神健，痛疾可望常平，属预后。", []], "15815": ["病机", "脉软弱细小，尺按之如绵，主用心过度、色欲无禁、厚味伤中，致气血两虚。正虚则厚味之毒乘虚盘踞颧骨，坚如铁石推之不移，更兼寒气乘虚侵袭，此脉所以软弱细小也。", ["软", "弱", "细", "小"]], "15816": ["病机", "脉右虚耎、左脉细小、尺按之如绵，为脾虚肝损、精血亏耗之象。脾主肌肉，虚耎则运化无力；肝藏血，细小则血少；尺候肾，如绵则肾精亏虚。精血久亏，寒邪乘虚侵骨，发为骨疽。左颧漫肿坚如铁石、牙关难开，乃内虚外显之征，故曰“有诸内而形诸外”。", ["虚", "细", "濡"]], "15817": ["病机", "脉象沉紧，沉主里、紧主寒主痛。舌苔泥白如粉，脐腹绞痛，痛无宁刻，大便闭塞，显系寒与气食交凝于内，阳气不运，阴寒痼结。服桂附八味丸及脾约丸不应，知非单纯虚寒或燥结，乃寒凝气滞食积互结，故痛剧防厥。脉沉紧与痛无宁刻相应，为寒实内结之明证。", ["沉", "紧"]], "15818": ["兼症", "脉形尚滞，舌白如前，大便通而余滞未尽，说明里滞未全化，气机尚欠流畅。虽痛已大减，但脉滞、舌白泥未转，胃土津未复，故以和中之法佐舒涤肠滞，并嘱食宜少进、节制饮食，以防食复。此段重在述兼症与调护，非主病机。", []], "15819": ["病机", "脉象虚耎无力，为脾胃气虚、坤土失运之征。进前方后精神渐健，舌苔已退，但腹中偶有疼刺、得食即安，显系中虚未复、气血不充。虚耎无力正合脾虚，故用异功散加玉竹、归身、枣仁等调心脾，使坤土和而夜寐安，脉症相应。", ["虚", "濡"]], "15820": ["病机", "脉象虚耎，左关弦细。虚耎为脾阳不运，弦细为肝阴亏虚。素有肠红，操劳多步或贪凉饮冷则便血频下，色鲜红，乃脾不统血、肝不藏血所致。饮食睡卧如常，说明病未及他脏，先理坤元以复统血之职，再图肝阴。脉症合参，脾阳不运、肝阴有亏为便血之根。", ["虚", "濡", "弦", "细"]], "15821": ["预后", "咳血虽止，脉仍弦数。弦为肝旺，数为火炎，说明肝火未平、阴分未复，虽血止而病机未息，故究宜静养为最。脉仍弦数提示内热未清，若操劳或情志不遂，恐有复燃之虞，此段重在预后调摄，非主病机。", ["弦", "数"]], "15822": ["病机", "右脉软，左寸虚、关弦、尺浮小数。右软为肺胃气虚，左寸虚为心气不足，关弦为肝郁化火，尺浮小数为肾水不足、相火易升。肺胃虚则金不制木，肾水亏则水不涵木，相火升腾，灼伤血络，故吐血。脉象与“肺胃虚而肾水不足，相火易升”之病机丝丝入扣。", ["软", "虚", "弦", "数"]], "15823": ["病机", "昨诊左关弦硬，为肝火亢盛、相火上炎之象，故防吐血复发，至夜果吐。今日肝脉反不过弦，而按之不静，说明火势虽暂敛，然肝阳未靖，犹恐再吐。贪肥甘厚味生湿成痰，脾胃弗克健旺，痰湿郁而化火，上灼肺金，下伤脾土，故咳呛便溏并见。脉弦硬与相火上炎相应，按之不静为余焰未熄。", ["弦", "硬", "数"]], "15824": ["预后", "原文仅言“脉未平静耳”，未具体描述脉象，故脉象要素为空。此语提示病虽向安，但脉气尚未和缓，反映痰红虽止而阴液未复、虚火未靖，故以沙参、首乌、元参等滋阴润燥之品调治，继以丸剂缓图。", []], "15825": ["病机", "左关虚弦、尺濡，右脉虚软无力，总属肺脾肝肾皆虚。虚弦为肝虚木失水养，濡为肾虚精亏，虚软无力为脾肺气虚。原文以“土不生金”“水不养木”“金不生水”释其相生之链，故夏间吐红由此而发，治当调脾固肺，不可仅补肝肾之阴。", ["虚", "弦", "濡", "软"]], "15826": ["病机", "脉息弦细小数，弦主痛、细主阴亏、小为不足、数为有热。溲出茎中疼痛，乃阴亏火旺、湿热下注之淋证。脉细数示阴虚火动，弦为痛征，故议益阴降火佐以祛淋，使火降阴复则淋痛自缓。", ["弦", "细", "小", "数"]], "15827": ["病机", "脉息虚软迟小，虚软为阳气不足，迟小为阴寒内盛。症见头面浮肿、大腹虚膨、阴囊胀大、小溲少，显系脾阳不运、水湿泛滥之水肿。脉与症合，故断为“脾阳之不运所致”，拟温中法以复脾运。", ["虚", "软", "迟", "小"]], "15828": ["病机", "脉形细数，细为阴伤，数为火旺。淋浊症见溲时尿管疼痛、败精频出、口干喜饮，乃相火未清、阴虚火动之候。细数脉正合阴亏火旺之机，故宜益阴降火，使火清阴复则淋浊可愈。", ["细", "数"]], "15829": ["主病", "脉来细弦，细主正虚，弦主疟邪。疟发间日、寒甚于热、定时而作，为邪伏少阳、正虚邪争之象。细弦脉应其正虚而邪郁少阳，故治法取温舒和解，以扶正达邪、调和营卫。", ["细", "弦"]], "15830": ["病机", "脉左濡小，濡为湿滞，小为不足。两胁作疼波及于腰，兼有干呛，乃肝肾不足、湿阻络脉之候。左脉濡小正示肝肾亏虚而湿邪留恋，故法宜舒络，侑以却湿，使络通湿去则胁腰之痛可解。", ["濡", "小"]], "15831": ["病机", "脉息弦数，弦为肝旺，数为火盛。年近四旬、素多操劳、阴虚之体，忽呛血杯许色带紫红，乃阴虚火旺、迫血妄行之候。弦数脉示肝火未靖、血犹未尽，故拟去瘀生新法，使瘀去新生而血自止。", ["弦", "数"]], "15832": ["病机", "脉息细滑，细为阴血不足，滑为痰浊内蕴。患者长夏冒暑，暑热伤阴，愈后寒热复作，阴亏未复；又因闻鬼怪事而惊，惊则气乱，痰浊随气上逆，蒙蔽心窍，故发癫症，自言自语、东步西走、夜不成寐。细滑之脉正合阴亏痰扰之病机，非虚痫之虚象，故温补、滋阴皆不应。", ["细", "滑"]], "15833": ["主病", "新产之后，气血未复，脉带浮缓，浮为风邪在表，缓为营卫不和。风邪外袭，故身热欲呕、咳嗽；恶露未消，瘀血内阻，故少腹疼痛。脉浮缓与身热欲呕相应，示表邪未解；少腹疼痛、恶露未消则属瘀滞。治宜轻疏风邪，兼以散瘀，使表解瘀行则诸症自愈。", ["浮", "缓"]], "15834": ["病机", "脉象浮数，浮主风邪在表，数主火热内郁。风火相搏，上攻头目，故两目胀痛羞明，午后阳盛则更甚；火热上壅则上部觉热，阳郁不达则下部足冷。病经二旬，脉仍浮数，说明风火之邪未得外达，郁于内而不得散。治宜清散，使邪从表解，则胀痛羞明自止。", ["浮", "数"]], "15835": ["病机", "左关尺虚弦，右寸关虚弱。左关尺候肝肾，虚弦为肝阴不足、水不养木之象；右寸关候脾肺，虚弱为脾阳久虚、火不温土之征。肝阴弱则水不养，脾阳虚无火以温，气血两亏，经停半载。脉之虚弦虚弱，正显肝阴素弱、脾阳久虚之明证，故当早图温养。", ["虚", "弦", "弱"]], "15836": ["病机", "尺脉虚数，尺候肾，虚为肾阴不足，数为阴虚生内热。上齿虽属足阳明，然齿为骨之余，肾主骨，肾阴亏虚，虚火上炎，故上齿时痛无宁刻，午后阳盛阴微则痛尤甚。尺脉虚数正是肾阴不足、虚火上炎之明征，非阳明实火可比，故痛虽剧而脉不洪实。", ["虚", "数"]], "15837": ["病机", "时邪为寒凉所遏，脉象浮数。浮为邪在表，数为热郁内。前医过用犀角、大黄等寒凉，致表邪不得外达，热邪内陷，与痰互结而成结胸，故身热未解、胸闷按之痛、舌边白中黄、口渴喜饮。脉浮数示邪仍欲外透，症兼结胸则邪已内结，故拟小陷胸加味，以冀转机。", ["浮", "数"]], "15838": ["病机", "进前药后便解身凉，脉象小数。小为正气渐虚，数为余火未清。汗多口渴、舌色淡红，示热邪虽减而津液已伤；稍兼恶心，乃胃土未和、余火内扰所致。脉小数与汗多口渴相应，说明火未全清、胃未和降，故曰固余火之未清，亦胃土之未和也。", ["小", "数"]], "15839": ["病机", "右寸浮小，关脉沉滑。浮小为风邪外袭、正气不足；沉滑为气食交阻、积滞内结。病后体虚，又冒风邪，故微热舌白；食凝气滞，结于脐右，故少腹痛甚、按之愈痛、块攻约长五寸。脉浮小与微热相应，沉滑与食凝气滞、痛块相应，此冒风兼气食交阻，非温疏难以去疾。", ["浮", "小", "沉", "滑"]], "15840": ["病机", "脉数见于沉分，右关尤甚，说明暑湿郁于土中，发之不透。数主热，沉主里，右关候脾胃，故知暑湿内郁脾胃，郁而化热。原文谓“营气不从，逆于肉理，乃生痈肿”，指出外症痈肿由营气逆乱所致，但脉象显示病根在里，脓未成而根盘散漫，故不可早投寒凉，治宜托散清和。", ["沉", "数"]], "15841": ["病机", "脉左牢大，牢主寒主痛，大主邪盛，左脉候下焦血分，故知瘀血内蓄。原文谓“下焦感寒停经，腹痛不止，血块时下”，又“痛因行经房劳而起”，寒客下焦，血为寒凝，瘀阻不通，故脉见牢大。脉症相符，治在温疏，温经散寒以通瘀滞。", ["牢", "大"]], "15842": ["病机", "脉左牢大，牢主寒凝，大主瘀盛，左脉候下焦，故知寒郁血瘀。原文谓“经行房劳，下焦受寒，血紫块攻，痛剧防厥”，寒客下焦，血凝成瘀，瘀块攻痛，脉象牢大与症相符。前剂小效而药力尚轻，故再以温经散瘀佐以疏通，通则不痛而瘀块自消。", ["牢", "大"]], "15843": ["治法", "此段强调“必须按脉审症”，因脉左牢大，合血块攻痛之形迹，方敢重用温通散瘀之法。牢大之脉主下焦寒郁成瘀，故虽仲秋而敢用附子、炮姜重剂。若经非寒郁，不过气滞血凝，则脉不牢大，只宜疏气和血，不可重投温燥。示人凭脉辨证以定治法轻重。", ["牢", "大"]], "15844": ["治法", "此段说明不用补剂之由，在于“脉症之不虚”，即脉象与症候均无虚象，故非因乡僻藜藿之人而概不用补。强调补剂之取舍当以脉症虚实为凭，脉不虚则不可妄补，非泛论贫富。文虽简，实为凭脉定治之要义。", []], "15845": ["病机", "右寸关虚软无力，左关尺虚弦小数。右寸关候脾肺，虚软无力为脾肺阳气亏虚；左关尺候肝肾，虚弦小数为肝肾阴弱，虚阳不敛。原文谓“肝肾之阴弱，脾肺之阳亏”，故见经行迟速无期、午后发热、骨节酸疼、带下绵绵。治分两方，兼顾脾胃与肝肾。", ["虚", "软", "弦", "数"]], "15846": ["预后", "衄血昨止，今晨咳呛气逆，左鼻偶有一滴，而“脉之弦数已缓”，弦数主热主肝火，今已缓和，说明热势渐退，故原文断为“无足虑也”。脉象由弦数转缓，是邪热衰减之征，虽有小量衄血，不足为虑，预后良好。", ["弦", "数", "缓"]], "15847": ["病机", "六脉虚小乏力，关脉见芤。虚小为气血两亏，芤主失血，关候中焦，去血过多则阴亏阳弱。原文谓“去血过多，阴固亏也，阳愈弱矣”，故经水淋漓月余不止，头汗如雨，嘈杂头晕，不能安卧。亟宜益气扶阳，固气以统血，不可纯用阴品。", ["虚", "小", "芤"]], "15848": ["病机", "前因崩血月余，头汗剂颈，几乎欲脱，急固气以统血。今血停七日，脉象虚小，乃气血亏虚未复之象。虚小示气弱血少，脾胃运化无力，故当调和脾胃，俾饮食运化，气血渐充。不宜过补，过补妨食，反难运化。", ["虚", "小"]], "15849": ["病机", "新嫁月余，小溲涓滴疼痛尿血，经水无定。脉左关尺弦细小数，弦主肝郁，细小数主阴亏火旺。肝郁化火，下迫膀胱，故溺痛尿血；火郁筋脉，故手腕郁筋酸痛。他医误作手发背，外敷反增肿痛，实非疮毒。", ["弦", "细", "小", "数"]], "15850": ["病机", "经停半载非胎，因食茶虫积，腹胀时痛欲呕。脉两关沉细，沉主里，细主虚，关候肝脾。火郁于肝，湿郁于脾，肝脾不调，气血瘀滞，故经水不行。治宜调经解郁，俾经通诸恙平，否则恐成虫、血二蛊。", ["沉", "细"]], "15851": ["病机", "新产之后气血两亏，头痛虽分九宫，当别论。右脉虚大无力，左脉浮小而芤，虚大无力为气亏，浮小芤为血少。气血并亏，清窍失养，故头痛。治宜气血并补，少佐轻疏，最稳。", ["虚", "大", "浮", "芤"]], "15852": ["病机", "素属气血两亏，经行腹痛，今停经两月余忽行，腹痛腰疼淋漓。脉左虚涩，右细弱，虚涩示血虚兼滞，细弱为气弱。冲脉为病，痛在脐下。虚不能固，滞不能舒，故痛而兼淋漓。先治其标，经止后再治本。", ["虚", "涩", "细", "弱"]], "15853": ["病机", "肝肾阴亏，内挟痰火上升巅顶，脑痛丧明，发厥啮唇。脉弦滑，两尺虚数，左尤甚。弦滑主痰火，虚数主阴亏火旺。虚痰挟火，上扰清窍，故厥、痛、丧明。法宜壮水滋肝，佐降火豁痰。", ["弦", "滑", "虚", "数"]], "15854": ["病机", "背心酸疼，左腹有块，痛甚则厥，吐痰如破絮。察色按脉，知风痰痹于肺穴，三椎肺穴与鼻相应，故酸疼波及鼻。饮冷伤脾，脾土壅而生痰，脾肺虚而木来侮土乘金，故遇寒、风、停食即发。病经四载，肝木过旺。", []], "15855": ["其他", "九龄幼女，沉疴积岁，前医概作湿热、湿痰、肝气、肝风妄治，病日加深。予四诊详谛，知幼女症非七情，唯于六气内伤合参，定为风、痰、痹、肺四字求治，调中疏气。先治其标，四剂中的，数剂收功。此段强调审证切脉之要，非神也，理也。", []], "15856": ["病机", "脉右浮小，左虚弦，为营卫两虚之象。右脉浮小示卫气虚浮不敛，左脉虚弦示营阴不足而肝木失养。经停五月，咳嗽寒热，天明汗出热退，乃营卫不和、阴虚内热之征。法宜养阴和卫，使营卫调和则寒热退，经水自通，免成虚怯。", ["浮", "小", "虚", "弦"]], "15857": ["病机", "右寸关细小兼滑，左寸关弦涩而劲，两尺虚浮小数。细小为脾肺气虚，滑为痰湿内蕴；弦涩而劲为肝郁血少、木失柔润；尺虚浮小数为肾阴亏虚。五脏皆亏，脾虚不能生金，肺弱不能生水，肾水亏乏，故形羸气喘、咳哑食减，滋阴反增痰，土虚不运故也。", ["细", "滑", "弦", "涩"]], "15858": ["治法", "前案脉象未载，此段述治法。病起五月，百无一效，予扶土保金、益气养阴，更加壮水滋木，药进三十剂病除十有八九。盖脾土为后天之本，土旺则金生，金生则水足，水足则木荣，气血融和，脉络贯串，血海流通，经事自转。此从本论治，非见症治症。", []], "15859": ["病机", "左关弦数而滑，按之不足。弦为肝脉，数为火，滑为痰，按之不足为肝虚。发时左足筋惕，痰升气逆，耳闻目无视，皆肝风挟痰火冲逆之象。东方木郁生火，火郁生风，风火煽痰，痰火冲气。急则治标，探本属肝虚，虚不受惊，烦则气越，重投疏风破气降火消痰则虚虚矣。", ["弦", "数", "滑"]], "15860": ["病机", "两关双弦，按之不足。弦为肝脉，双关见弦，知木乘土位，犯胃则呕。呕吐两月，胃气弥伤，肝木愈强，木强则肝亦自伤。按之不足示胃气已虚。治以六君子汤养胃和肝，佐左金丸清肝火，使食入不出，再为之计。此木乘土位之呕，非单纯胃病。", ["弦"]], "15861": ["病机", "脉沉为气，沉而兼数为火，数而带滑为痰。形如梅核，阻咽关出入，经停三月，疑似胎。然有胎之脉当滑疾，今反沉细，故非胎。沉细为气郁痰凝，火郁于内。作梅核气治，不用碍胎之品，即曰有胎亦无妨。此气痰火郁结咽关之病机。", ["沉", "数", "滑", "细"]], "15862": ["病机", "大凡胎象三月脉必滑疾，今反沉细，故非胎。前案论之已明。所进丸药无关于胎。脐腹响而坠、坠而欲溲，乃气与痰火由上而下达脐腹，下焦膀胱之地，湿郁之火有从气化而出之象。药力未足，功亏一篑，非小产之征。此痰火下行之病机。", ["滑", "疾", "沉", "细"]], "15863": ["病机", "右寸关软小，按之不足；左三部缓涩无力。软小不足为气虚，缓涩无力为血少而肝失条达。经转七日，色淡绵绵不止，少腹微疼，此气虚不能统摄，血不归经。治以益气和肝，四君子汤去茯苓加黄耆、炮姜、炒黑当归等，两剂经止痛平。此气虚不摄之病机。", ["软", "小", "缓", "涩"]], "15864": ["病机", "左关弦数而虚，弦为肝旺，数为火郁，虚则肝体自伤；右寸关不任重按，示脾肺之气亦弱。原文谓“病起于肝而波及脾肺”，肝火冲肺烁金、木强侮脾克土，土虚不能生金、金虚不能平木，形成肝强脾肺弱之连锁。脉象正是肝郁化火而中气已虚之征，故不可专事降火消痰破气。", ["弦", "数", "虚"]], "15865": ["病机", "左关弦浮，卜肝风上扰，风热循经蒸于头皮而痒；右关濡数，知脾湿上蒸，湿与热合致发根腐；左尺沉涩而虚，见肾阴不能上达，发失真阴固济而脱。原文以“血虚”为枢，经事后期更证血虚。诸脉合参，示肝风、脾湿、肾阴虚兼血虚之病机，非单纯外风。", ["弦", "浮", "濡", "数"]], "15866": ["病机", "本段未明写脉象，仅言“从症脉合参”，故脉象要素从缺。原文断为“脾家之湿毒，肝经之郁火”，手足腿股溃烂、痒甚抓则水出，是湿毒郁火外发肌肤；前医误用麻黄、羌防及大风子等燥热伤血之品，反助火毒。脉虽未录，其病机在脾湿肝火，非疯瘫、非纯火毒。", []], "15867": ["病机", "左脉虚数，虚为血分不足，数为经行过多、阴血骤伤而虚热内生。原文“经行过多，未期先至，觉头眩身疼”，正是血虚不能上荣、筋脉失养之候。疮疡十去八九而脉转虚数，示邪退正伤，故以四物汤养血为主，佐女贞子、香附、陈皮调肝理气，不再过用寒凉攻毒。", ["虚", "数"]], "15868": ["病机", "脉虽弦数，弦主肝郁，数主热，合阴门生疮、疮口深肿痛无宁刻，为肝经湿热火毒下注。然正值经水临期，血室正开，脉数而投寒凉恐凝滞经血，故原文谓“未便过投寒凉”，以四物汤养血为本，加金银花、甘草、人中黄、贝母、青皮清解肝经郁热火毒，兼顾经期。", ["弦", "数"]], "15869": ["病机", "左脉虚弦，弦为肝郁，虚则肝阴不足；右脉软小乏力，软小为脾阳不运、中气虚弱。原文“体虚腹膨，两足浮肿，便溏食减”正是肝脾同病、木不疏土、水湿内停之征；头眩口干腹疼痰多内热，皆肝阴亏而脾阳不运所致。脉症相合，故主扶脾兼养肝。", ["虚", "弦", "软", "小"]], "15870": ["病机", "本段未录具体脉象，仅言“证脉合参”，故脉象要素从缺。原文辨为“暑风外袭，食饮中停”，舟中感冒风暑而寒热头疼，饮食停滞致乍寒乍热、似疟而阴阳未分。病机属外有暑风、内有食滞，表里同病而未入少阳定界，故治法以疏解为宜，不可遽作疟治。", []], "15871": ["病机", "脉左弦右滑，左弦应少阳，为邪伏少阳、枢机不利；右滑应阳明，为痰湿食滞内蕴。原文“疟发间日，寒热交作，舌苔白腻，不饥纳少”，正是邪伏少阳阳明、痰湿中阻之候。弦滑并见，示疟邪未离少阳而兼阳明痰滞，故宜从和解治，取疏达枢机、化湿和中之法。", ["弦", "滑"]], "15872": ["病机", "右关沉滑，沉主里、滑主痰饮宿食，是胃中不和、饮食停积之象；左关小弦，弦为肝脉，小则肝气郁而不伸。两关合参，正合原文“胃不和，肝不疏”，肝郁则胃气不降，食入少停即呕吐，故以旋覆代赭降逆、佐疏肝之品。", ["沉", "滑", "弦"]], "15873": ["病机", "脉右浮缓，浮为湿邪在表、缓为湿性濡滞，右脉候气，右浮缓正是湿气内侵、困阻中焦之象。原文点明“连日阴雨，地土卑湿，久坐针工，湿气内侵”，长夏湿盛，湿困则身微热、无汗、不欲食，故以平胃散损益燥湿运脾。", ["浮", "缓"]], "15874": ["病机", "脉右沉紧，沉主里、紧主寒主痛，右脉候脾胃，是寒积停阻肠胃之征。原文“解下纯是白冻”“里急后重”“舌苔腻白”，皆寒湿积滞内结、气机不通之候，故曰“寒积中停，温通为宜”，非温通则积不去。", ["沉", "紧"]], "15875": ["病机", "大黄减半而积反增，脉仍沉紧，沉紧为寒积内结未散之象，说明积垢犹存、病根未拔。原文强调“非姜、附佐之，则寒积必不能除”，又须大黄重于姜附方能推荡尽彻，脉仍沉紧正是积未尽之凭据，故仍以温通为法。", ["沉", "紧"]], "15876": ["病机", "左关尺虚濡、右寸虚软，关脉沉小，虚濡软为气血不足，沉小为脉道不充。经行愆期、痛甚经行、血中兼块，是气血两虚而兼瘀滞，故原文断为“气血两虚”，治以益气养营为主，佐调血通经，八珍加香附、元胡之类。", ["沉", "小", "虚", "濡"]], "15877": ["其他", "本段未识出脉名，纯叙病程：忿怒伤肝发寒热，继而大痛大吐大泻，汤饮下咽即呕，腹胀脐突如覆小锅，得汤仍呕。此为肝气犯胃、升降悖逆、痛剧气结之危候，故延老医改用金匮肾气丸，从温肾纳气着眼，非一般疏解降逆所能治。", []], "15878": ["病机", "脉右关细软无力，细为血少、软为气虚，右关候脾胃，是脾土虚弱之象。素有肝气，痛甚气逆、两胁块攻、呕出新谷旧谷觉酸，乃肝木乘脾、脾阳不运，故破气之品虽暂效而旋发，头汗肢冷更见阳气式微，单疏肝降气不能拔根。", ["细", "软"]], "15879": ["病机", "本段未识出脉名，以“证脉合参”断为脾阳不运、肝木乘之，肝气过旺而肝亦自伤。痛症停药又发、较前稍缓，说明病本在脾阳虚弱、肝木偏旺，故治法扶脾温中兼养肝舒木，标本兼顾，非一味破气攻伐可比。", []], "15880": ["病机", "右脉虚小，主脾虚挟湿，运化无力；左脉虚数，主肝虚血少，虚热内生。脾虚则四肢虚浮、小溲短赤；肝虚血少则夜热口干、经行腹痛、腰腿酸疼。脉症合参，皆肝脾为患，故曰“显有明征”。", ["虚", "小", "数"]], "15881": ["预后", "脉虚数不静，虚为气血两伤，数为恶血未尽、虚热内扰。下胎药后恶血甚多，气逆上冲、恶心头眩，脉不静示郁冒痉厥之险。原文谓“已属险途”“恐其郁冒痉厥之虞”，故主预后险恶。", ["虚", "数"]], "15882": ["病机", "脉浮而缓，按之小数，浮缓为微冒风邪、营卫不和；小数示邪入于阴、阴虚内热。故夜间身热、骨节疼痛。劳役恶热贪凉，阴虚邪乘，脉症相合，邪入阴分，一剂汗出而解。", ["浮", "缓", "数", "小"]], "15883": ["治法", "脉象浮小，浮为风热上扰，小为阴虚血少。牙龈肿痛如针刺、咽疼口干，经水未期，乃风热客于龈咽、阴血不足。脉浮小示病位在上在表，故“治在轻清”，以轻清之品疏风清热，不犯中下。", ["浮", "小"]], "15884": ["病机", "右部数急，主胃阳久弱、虚热内扰，故不饥纳少；左部弦紧，主肝阴不充、血海无潮，故经停、腹左块攻。数急弦紧并见，示阴虚内热与肝郁血滞交结，色脉合参，虚怯之征已露。", ["数", "急", "弦", "紧"]], "15885": ["病机", "右脉数虽缓，示胃热渐退；左部弦劲未平，主肝郁血滞、八脉未和。气血未旺，冲任不调，故中宫时有微疼。脉症相参，阴阳未和，经事未转，仍须加意图维。", ["数", "缓", "弦", "劲"]], "15886": ["病机", "右脉数急，主胃阳弱而虚热内扰，故贲门少纳；左脉弦劲，主肝阴涸而血海无潮，故经停、腹块攻痛。数急弦劲并见，干血之征已露。后脉症并参，究关中气大虚，故以益气为要。", ["数", "急", "弦", "劲"]], "15887": ["病机", "脉沉数而滑，重按无力。沉主里，数主热，滑主痢下积滞；重按无力示正虚。妊娠三月痢下红白百余度，正虚邪实，攻补两难。脉症合参，胃气犹存一线，故用攻补兼施，辅正驱邪，保母留胎。", ["沉", "数", "滑"]], "15888": ["预后", "脉浮小而不沉数，按之少有力，示邪已外达，正气渐复，故日进粥六七碗、粪带焦黄色，胃气渐旺。浮为邪在表，小为正气未充，按之有力则胃气渐振，故以四君子汤加黄芩、芡实、广木香健脾清热，继以香砂六君子汤调理而愈。", ["浮", "小", "数"]], "15889": ["病机", "脉沉而细，沉主里，细主虚，气食交阻于中焦，故腹痛且呕。沉细为气机郁滞、食积内停之象，痛甚则气机闭塞，有致厥之虞，故曰「痛甚防厥」，治当行气消食、和胃降逆。", ["沉", "细"]], "15890": ["病机", "右部虚小，左部虚濡，虚小为气弱，虚濡为血亏，乃气血两虚、表气不固之候。产后咳呛延绵、畏寒，误作冬温疏表、小柴胡加生地，更伤气血，故病日增。治当益气温营卫、降气化痰，使痰除逆平。", ["虚", "小", "濡"]], "15891": ["病机", "脉浮数而按之不足，浮为虚阳外浮，数为虚火不宁，按之不足则肺金之阴亏。行经后干咳无痰，乃肺燥津伤、虚火上炎，故治宜清润，用清燥救肺汤损益以润肺降火。", ["浮", "数"]], "15892": ["兼症", "脉浮小，浮为暑湿外袭，小为正气不足。咳嗽有年，起于产后，近感暑湿，咳嗽兼呕、气逆痰稠、骨节疼烦，乃正虚邪恋、暑湿犯肺。咳甚则气火上升，故防血溢，治当清暑化湿、降气止咳。", ["浮", "小"]], "15893": ["病机", "脉按之则数，数为邪热内蕴，按之而得则邪在里。寒热一日、经行而止，遍体不疏、食饮无味、口吐清水、舌腻欲呕，皆邪蕴于内、枢机不利之象，故治以和解，使微汗润泽而邪退。", ["数"]], "15894": ["病机", "色脉合参，见证多端，冲任俱虚，故经前趱前、生育维艰。肝火内动则眩晕、胸中跳跃，十指麻、腰背痛、肢节酸，口干唇燥、肌肤索泽，或外寒或内热，种种皆卫阳虚而营阴不足，治当固表扶阳、和里益阴。", []], "15895": ["预后", "脉象沉紧渐减，沉紧为肝脾郁滞、寒凝气结之象，渐减则郁滞渐开、气机渐畅，故仍宜疏理肝脾，使木达土和，则痛自平。此示病势向愈，治当守方缓图。", ["沉", "紧"]], "15896": ["病机", "脉数而虚，数主火，虚主不足。气郁痰凝，挟火而升，火扰心神则谵语妄言、不时歌泣。虚为正气不足，数因火动，故癫而非狂。狂脉多实大，癫脉多虚数，此虚数之脉正合癫疾痰火内郁、神不守舍之机。", ["数", "虚"]], "15897": ["病机", "左关弦紧主瘀血内停，右脉浮数如绵为虚阳外越。产后恶露无几，腹膨微热口干，头汗体倦，便泄未已，皆瘀阻而虚阳浮越之象。弦紧为瘀滞，浮数为虚阳不敛，绵软示气阴两伤，故断为恶血停留、虚阳外越，症险。", ["弦", "紧", "浮", "数"]], "15898": ["病机", "右脉数大而软，数大为热，软为气阴不足；左脉弦紧而数，弦紧主瘀滞，数主热。恶露全无，腹膨鼻煽，便泄数十次，气急神倦，乃瘀血内阻、虚阳外浮、阴伤及阳之危候。脉数大而软为虚热，弦紧为瘀，合示正虚邪实、瘀热交结。", ["数", "大", "软", "弦"]], "15899": ["预后", "脉急促为危候，急促者数而迫促，主正气衰败、邪热鸱张。前案便泄数十次、恶露全无、腹膨鼻煽，脉急促示阴阳将脱。然服温中逐瘀、敛阴固肠之剂后，便泄止、恶露下、热退神安，说明脉虽危而生机尚存，急促之脉在此为危笃之兆，非必死之脉。", ["急", "促"]], "15900": ["病机", "左弦右滑，弦主少阳，滑主痰湿。三阴疟先寒后热，热甚于寒，口渴喜饮，舌苔白腻，脉左弦右滑，乃少阳枢机不利、痰湿内蕴之象。弦为疟邪客于少阳，滑为痰湿滞于中焦，故用小柴胡汤加减以和解枢机、化痰湿。", ["弦", "滑"]], "15901": ["病机", "脉沉小，左弦细。沉小主里，弦细主湿郁气滞。身热头疼、恶心不饥、泄泻日数行、舌苔白，乃夏感暑湿，热交秋而发。暑湿内困，气机不畅，故脉沉小而弦细。治宜解表疏里，使暑湿从表里分消。", ["沉", "小", "弦", "细"]], "15902": ["病机", "脉虚大而弦，虚大为气血不足，弦为邪滞。产后热甚、头疼胸闷、舌苔糙腻、口渴、腹微痛、恶露全无，乃邪乘虚入，瘀热内阻。虚大示正虚，弦示邪实，故不可因壮热误进寒凉，当以生化汤加味行瘀退热，俾恶露行而热退。", ["虚", "大", "弦"]], "15903": ["病机", "脉象细小无力，细主阴血不足，小弱主气虚。干咳无痰、气逆喉痒、午后寒热、口舌干燥无津、不饥食少，乃阴虚内热、阳虚外寒、气血两亏。细小无力之脉正合气血双亏、肺阴不足之机，故亟宜补肺生津，防入虚损。", ["细", "小"]], "15904": ["预后", "原文未载具体脉名，仅言“脉仍如前”，说明服药后咳渐有痰、口舌有津、夜能睡、寒热盗汗俱减，诸症向安而脉象未变。脉证不符，提示病邪虽退而正气未复，或脉象变化滞后于症状，故药虽相宜，仍须守方续进，不可因脉未变而遽改治法。", []], "15905": ["病机", "右寸虚数、左脉虚弦，右寸候肺，虚数示肺金虚而火动；左脉候肝，虚弦为肝木失养、木火偏旺。金虚木旺，木挟火势乘金，肺窍受灼，故咳嗽、喷嚏而鼻衄直注。脉象明征与“金叩则鸣”“气逆火升”之病机相应，先治其衄，再商善后。", ["虚", "数", "弦"]], "15906": ["病机", "右寸浮紧，右寸主肺，浮为邪在表，紧为寒邪束表。寒邪客肺，肺气失宣，故身热、咳呛不已、舌苔腻白；经水适来，寒郁营分，故经水趱前。前医轻疏不应，咳转剧，正因寒邪未散。亟宜疏肺，拟麻黄汤加味，兼治经水。", ["浮", "紧"]], "15907": ["病机", "六脉沉小，沉主里、小主虚，示气郁食阻于内，正气不足。汤水入胃即呕、大腹阵痛、二便不通、胸闷不饥，皆气机壅塞、胃失和降之象；手指厥冷为痛剧气逆所致。舌中淡黄苔糙，亦里实之征。体质素弱，痛剧防厥，故议和中法，佐以定痛止呕。", ["沉", "小"]], "15908": ["病机", "右关虚而滞，左关细而弦。右关候脾胃，虚滞示脾土亏虚、运化无力；左关候肝，细弦为肝血不足、木失柔养。产后脾土先亏，又贪食荤腥，脾胃愈伤，气机壅滞，故呕痛愈甚，甚至黑汁黄浆泛出、两臂直竖有角弓反张之势。脉症合参，危在顷刻。", ["虚", "滞", "细", "弦"]], "15909": ["病机", "原文言“脉络滞涩之故耳”，滞涩示气血运行不畅。产后失调，脾胃虚弱，气血不和，不能营养贯注，故胁背刺痛不在肌肤，自觉经络中收束刺痛。大便结粪成条后腹中松爽，亦气机暂通之象。治以补脾益气、和血通络，五剂而前症悉除。", ["滞", "涩"]], "15910": ["病机", "右脉虚小、左脉虚大。右候脾肺，虚小为阳气弱；左候肝肾，虚大为阴血亏。经水延绵八日不止，血去过多，阴亏阳弱，肝脾两伤，故血下成块如鱼肠、腥秽不堪。值大暑湿热之时，亟宜扶土滋木、引血归经，俾其速止，庶无他虞。", ["虚", "小", "大"]], "15911": ["其他", "原文仅言“脉形如昨”，未载具体脉象，属复诊记录。说明服药后脉象未见明显变化，与初诊脉象相同，提示病情相对稳定或邪正相持，须结合前诊脉症继续观察，以定进退。", []], "15912": ["病机", "脉俱沉细，沉主里，细主虚，示时邪内伏于里而正气已虚。身热头痛、胸闷咳呛似表证，然口干不喜冷饮、舌苔黏滞淡黄，为湿遏热伏之象；凛凛畏寒、四末清凉乃阳郁不达。脉沉细与阴虚体质相合，虑邪陷内闭，故议和解透达，冀周体微汗以解。", ["沉", "细"]], "15913": ["预后", "前诊脉沉细，进和解一剂后汗出热退、头痛止、肢末温，而脉之沉细渐起，是邪退正复、脉气渐扬之佳兆。唯舌胎如前、口干无味、便结溲短，乃邪退而胃未和、津未复。脉由沉细渐起，说明里滞渐开，故断为清胃调中自平，预后向安。", ["沉", "细"]], "15914": ["病机", "脉象沉滞，沉主里、滞主郁，与寒热滞下、色兼红白、腹痛点滴相应，示暑湿之邪内蕴，又为寒凝食积搏结于肠腑，气血壅滞而成痢。表里俱病、昼夜无度，脉沉滞正是邪郁气滞、积阻不通之征。不饥纳少，胃气已困，故防噤口之虞。", ["沉", "滞"]], "15915": ["病机", "右寸关滑数而大，按之无力，滑数主痰火，大而无力则非实火，乃痰火郁于肺胃而中气不足。前医一派寒凉，反致身热胁痛加剧、昼缓夜甚、昏语耳聋，皆寒凉遏抑、痰火无路可出之故。脉证合参，知痰火非实，故力阻寒凉前方。", ["滑", "数", "大"]], "15916": ["兼症", "身热已退而神识尚似清非清、汗出黏手、咳频痰稠、气逆耳聋，脉形如昨，说明痰火湿浊未净，仍壅于肺胃，清肃之令不行，故神识不清、耳聋痰稠。脉象未变，示病机未转，仍当肺胃并调，使清肃下降，则胃中痰火湿浊可随之而除。", []], "15917": ["预后", "左寸虚涩，右关耎小无神，左寸候心，虚涩为心营亏虚；右关候胃，耎小无神为胃气衰败。舌形胖大、胎白如雪花片散布，正是胃气败绝之征。邪退正虚而日进滋补，胃土不醒，故不饥纳少、体倦神怯、怵惕不寐。脉舌合参，胃气已败，故难以许治。", ["虚", "涩", "耎", "小"]], "15918": ["病机", "脉象沉小，沉主里、小主虚，示风寒内蕴而正气不畅。似寒似热、头痛且重、呕恶痰涎，为风寒夹痰浊内阻；小溲赤痛、腹膨时疼、经水匝月未行，乃肝胃不和、气滞血阻。脉沉小与食饮不贪相应，故法宜疏通，俾经行则气机畅而渐安。", ["沉", "小"]], "15919": ["病机", "右寸微若秋毫、关虚小、尺软如绵，左脉弦细乏力，示肺脾大亏、肾阳不足生脾土，故咳嗽有汗、食减便溏；心肝久虚、肾阴不足滋肝木，故寒热、天癸未通。脉之微虚小软弦细，正阴阳两亏、虚劳之征，故难以许治。", ["微", "虚", "小", "软"]], "15920": ["预后", "原文述右寸脉“指下按之亦稍有力”，右尺“软如绵者渐转濡小，而浮分按之似无”，此由虚软转濡小、浮取似无，是脾气渐复、湿浊渐化之象，故称“佳兆”。脉象由弱转和，提示气血渐和、脾肺渐调，与“气血稍和，脾肺渐调”相应，预后向好。", ["濡", "小", "浮"]], "15921": ["病机", "脉细而小数，细为营阴不足，数为内热，合“外寒内热，卫阳虚而营阴不足”之机。经水淡少亦营虚之征，咳嗽交冬频发、痰红已见，是虚火灼肺、络伤血溢。脉细数主阴虚内热，与卫阳不固、营阴亏虚之病机相应。", ["细", "小", "数"]], "15922": ["误治", "右部软大按之无力，左关弦细，尺细小难寻，是血室空虚、时邪内陷，误用犀角地黄汤等寒凉，致身热愈增、神识不清。脉软大无力为虚阳外浮，弦细为阴伤，尺细难寻为下元虚竭。口不喜冷、舌有津，皆非实热，故寒凉难投，属误治变证。", ["软", "大", "弦", "细"]], "15923": ["病机", "脉右虚左弦，右虚主脾亏，左弦主肝郁，合“肝脾两亏，湿热下注”。两足肿痛、屈而不伸、紫斑成朵，是湿热壅滞下焦、络脉瘀阻之湿脚气，古称壅疾。脉虚弦正示肝脾两亏而湿热下注，故宗东垣疏理肝脾之法。", ["虚", "弦"]], "15924": ["病机", "脉象虚软，左尺独数，虚软为气血大亏，左尺数非小肠痈之脓成，乃产后瘀血凝滞、郁而化热。原文辨小肠痈当“小溲数如淋，身皮甲错”，今无此形此脉，故知为产后气血亏、恶血阻络，误投破血致块坚痛增，脉虚软正是诛伐无辜之征。", ["虚", "软", "数"]], "15925": ["病机", "脉象沉小，沉主里、小主虚，合经水停阻、淋漓不绝、小腹块攻时疼，是下焦瘀滞未清而正气已伤。口喜温饮、小溲少、赤带多、舌淡黄，皆瘀滞兼湿之象。脉沉小说明病位在下焦，瘀滞未净，故以清下焦瘀滞为治。", ["沉", "小"]], "15926": ["病机", "左关虚数、右寸虚小、关脉虚软，数而虚为火非实火，虚小软为脾土亏虚。原文谓“土虚不能生金而肺弱，金虚不能平木而肝强”，肝强亦自伤，故脉虽数而虚。此示肝火之标源于脾肺之虚，徒事平肝伐木非法，当清补肺胃、少佐养肝。", ["虚", "数", "小", "软"]], "15927": ["其他", "原文未识出具体脉名，仅言“病脉合参，理宜气营并补”，又述秋令初交、暑热未楚，药后颇效仍宗前法。此段重在复诊议治，脉象描述缺如，故脉素为空。其主旨为据病脉合参以定气营并补之法，属治法延续，非专论脉象主病。", []], "15928": ["病机", "脉浮小，浮为风邪在表，小示邪势不甚而正气略弱。原文巅顶作痛、畏寒恶风、咳嗽呕恶、舌胎白腻，乃风邪上受兼露水外侵，暑风闭肺胃之象。前医清疏后呕咳畏寒减而头痛仍、反内热不饥，说明表邪未彻、上部风邪留恋。脉浮小正合轻清散上焦风邪之治，故用轻解法。", ["浮", "小"]], "15929": ["病机", "脉浮数不弦，浮主表邪，数主热，不弦则非疟之弦脉，故断为似疟非疟。原文身热头胀、干热无汗、腹中时痛时止如啮、舌绛唇红，乃风暑内蕴兼蛔虫作痛。前用小柴胡加连翘青蒿反闭闷壮热，因邪未外达。脉浮数示邪尚在表分，故宜疏表和里佐祛虫，俾邪外达。", ["浮", "数"]], "15930": ["病机", "进药后白㾦发出、少有汗、热势减半、口干喜饮亦减，脉转浮小数，浮示邪仍留恋肌表，小为邪势已衰，数则余热未清。原文谓邪未尽彻，正合此脉。白㾦外透、微咳胸闷齿疼，皆余邪郁于肺卫未净之征，故脉浮小而数，提示当继续清透余邪，不可骤补。", ["浮", "小", "数"]], "15931": ["病机", "产后两月，气血未复，脉软小为正气不足之象，兼浮则示冒风感寒、邪客肌表。原文冒风头疼、感寒腹痛、滞下数次，乃产后体虚复感外邪、肠胃受累。脉软小兼浮说明正虚邪轻，故宜清疏法，疏解外邪而不伤产后之虚，正合脉证。", ["软", "小", "浮"]], "15932": ["病机", "脉象沉迟，沉主里、迟主寒，值三冬寒令，寒凝胞宫，气血运行不畅，故经行腹痛。原文直言非温不通，正点明寒邪内凝、阳失温运之病机。沉迟之脉与冬季寒邪相合，说明此痛属寒凝而非热郁，治当温通散寒，使阳气复而血行畅。", ["沉", "迟"]], "15933": ["病机", "六脉沉细，沉主里、细主虚，示阳气衰微、寒凝于内。原文胸腹急痛如锥、呕吐肢冷、汗多且厥，乃寒凝食滞、气阻中宫，阳气不能外达四末，故见肢冷厥逆、汗多。脉沉细正合寒凝阳衰之危候，来势甚险，故先以熨法温通，再投煎剂。", ["沉", "细"]], "15934": ["病机", "脉右弱左弦，右候脾、弱为脾阳不足，左候肝、弦为肝木偏旺。原文食入则胀、胀甚则痛，正是脾阳不运、肝木乘土之象。右弱左弦恰示土虚木亢之病机，故宜补坎中之阳以生己土。老年得此，脾阳日衰、肝木易横，故防成虚臌。", ["弱", "弦"]], "15935": ["病机", "脉虚而数，虚为阴气亏虚，数为肝火内郁、虚热鼓动。原文发热两月未退，正合阴虚火郁、热久伤阴之病机。前用四物去芍加鳖甲地骨皮等养阴退热而未已，因体虚远路冒风，药难奏功。脉虚数说明本虚标热并存，故议逍遥合养阴退热，疏肝养阴两顾。", ["虚", "数"]], "15936": ["病机", "脉虚而带数，虚为阴血不足，数为相火内动。舌绛无苔、欲饮冷卧凉，皆阴虚火旺之象。前服养阴方夜热反甚，因相火不静，药力未及潜降。此脉此症，明是阴虚而相火不静，故以养阴合逍遥散加减，戒怒酒以图功。", ["虚", "数"]], "15937": ["主病", "右关软小不疏，关候脾胃，软小为脾胃气虚，不疏为运化迟滞。中脘作疼、受凉则甚、喜温恶寒、食后不疏即疼，皆脾胃虚寒、气机不畅之征。幸左关肝木不弦，无肝木乘土之兼证，故以调和脾胃、温中运食为法。", ["软", "小"]], "15938": ["病机", "右脉虚滞，左脉见芤。芤主大血去多，虚滞为营阴不足、气滞不疏。新产旬日，恶露甚少而忽下血块，营阴亏耗，肝火内郁，故发热头疼、耳鸣咽疼、舌绛光剥。此产后大血去多、营阴不足、肝火内郁、恶露未尽之病机，宜先舒肝和血。", ["虚", "滞", "芤"]], "15939": ["病机", "右脉虚大无力，左三部虚小微数。虚大为气弱，微数为阴亏虚火。服前药后汗减、头角不疼、口干耳鸣缓，是虚火渐降；而足不温、知饥口淡，是脾阳未复。此气血两亏、虚火渐降之机，然胃气未旺，峻补腻膈之药嫌其骤，故益气扶阳佐养心宁神。", ["虚", "大", "微", "数"]], "15940": ["病机", "脉细无力，细为营血不足，无力为气虚。新产之后气弱血亏，诸恙俱平而大便数日未解，乃血海空虚、肠燥便结，非实邪内结。若擅用通幽之法，则虚者益虚。故必益气以充之，养血以润之，佐温肾以达之，使便自通。", ["细", "无力"]], "15941": ["病机", "原文未识脉名，然云「证脉合参究关气血两亏」。新产十日，头疼身热、腹痛耳鸣、汗出无时、口干咽疼、咳呛痰稠，种种似外因之象，而实由产后气血两亏、营阴不足、虚火内动所致。故专作新产论治，随机应变，逐日平可而收功。", []], "15942": ["病机", "右细耎无力为脾肺气虚，左寸涩为心血不足，关弦数为肝火内郁，尺濡小为肾阴亏虚。咳血颧红、痰沫常吐，虚怯之征已露。此素体阴亏阳弱，相火上炎，水不养木，而脾肺久虚，概用滋阴降火恐不利脾，故亟宜扶脾保肺佐养肝。", ["细", "耎", "涩", "弦"]], "15943": ["病机", "右脉虚软，左脉弦细极。虚软为脾阳不运，弦细为肝阴不足、肝火内郁。进前药咳呛渐缓，而喉干舌燥、咳呛痰红，是阴亏火炎；腹块攻冲、肠鸣白带，虽关任脉，亦由脾阳不运。此阴亏阳亦虚，气不充、火上炎之病机，再调肺胃佐养肝。", ["虚", "软", "弦", "细"]], "15944": ["病机", "脉细为气虚血少之象，然不见数急，神识安静，说明此吐血非热迫血妄行，乃肺气虚而胃土不充，气不摄血所致。原文以“阳络伤则血上溢”为据，结合行经趱前、临经骤吐，辨为倒经，病机重在肺胃气虚、清阳不升，故治以益气养胃。", ["细"]], "15945": ["治法", "原文未明言脉象，仅言“证脉合参”，结合肠覃有年、块坚，主张缓图可消，反对速投峻厉之剂。其病机为久病癥块，正气已伤，宜缓消渐磨，若峻攻则恐节外生枝。故本条主旨为治法，强调据证脉以定缓攻之策。", []], "15946": ["预后", "左脉弦数大减，说明痫病痰火渐平；右寸关反觉滑而少力，滑主痰，少力为脾虚，提示痰浊未净而脾胃气弱。原文以脉象变化判断痫病向愈，喉中痰少、食增、二便通利，故以二陈汤加味健脾化痰，终获全愈。", ["弦", "数", "滑"]], "15947": ["病机", "六脉沉小，沉主里，小主虚，结合素有胃气作楚、冒暑风、舌胎腻白、有汗恶风，说明暑湿伤中，阳气被遏，胃气不和。沉小非表实之脉，故治以和中法，佐以辛苦，以化湿和胃，而非单纯解表。", ["沉", "小"]], "15948": ["病机", "原文未出具体脉名，仅言“脉象似疟而阴阳未分”，结合日晡寒热、头胀恶心、小腹膨急、溲便不爽、舌苔白腻，辨为暑湿挟痰、阴阳未分。素属阴虚挟痰，经行一月两至，兼腰疼如针刺，故先解暑却湿，少佐治本。", []], "15949": ["病机", "左脉弦细而数，弦主少阳，细为阴伤，数主热，说明暑湿之邪未尽，少阳枢机不利，兼有阴血不足。原文寒热、腰疼俱缓而小腹尚急疼、胸闷恶心，脉象提示邪未彻解，且防经水骤至，故拟和中法佐以舒运。", ["弦", "细", "数"]], "15950": ["病机", "左脉小数兼弦，右脉小滑，小数主热，弦主少阳，滑主痰湿。结合呕恶、口干舌腻、经水未停、少腹疼、血块仍有，说明胃不和而少阳之邪未彻，痰湿内蕴。脉象与症相应，故还防寒热再作。", ["小", "数", "弦", "滑"]], "15951": ["病机", "左右脉俱沉细小弦，沉主里，细主虚，小主不足，弦主邪郁。结合头疼、齿痛、舌苔白腻、胸闷欲呕、二目羞明，说明邪由表达里，营虚邪陷，闭而未出。原文引仲圣“营弱卫强，阳邪内陷”，况经断后得之，故议调营和卫，佐以豁痰解郁。", ["沉", "细", "小", "弦"]], "15952": ["病机", "左脉弦细如前，弦主肝郁气滞，细主正虚。原文述汗后热退而胸胁不舒、欲嗳气、小溲少热、转失气极臭，显系阳明宿垢未清、余邪未尽，兼正虚挟滞、痰湿中阻。右关稍起示胃气略复，左脉弦细未改则肝郁阴伤仍在，故先宜舒中却湿。", ["弦", "细"]], "15953": ["病机", "脉左如丝，右脉稍起。左脉细如丝主气血虚衰、阳气不达，故陡然手足厥冷、谵语后默默不语。原文断为气凝痰厥，痰气交阻、阳气被遏则厥，竹沥姜汁半夏陈皮沉香汁冲服后厥回，正合痰厥气凝之机。", ["丝"]], "15954": ["病机", "右脉虚耎主气亏，左寸细涩主营血不足，关脉弦数主肝火易升，尺濡小主水不滋木。原文谓气营两亏、水不滋木、肝火易升，故心烦乱语；舌苔中央腻滞、转失气时下，示宿垢未尽。证属虚实相兼，议益气养水佐清降。", ["虚", "耎", "弦", "数"]], "15955": ["病机", "脉象浮大按之不足，为阴血亏虚、阳气浮越之象；两尺沉迟主下元虚寒，左关弦细主肝阴涸竭。原文断为肝阴涸而血海无潮、胃阳衰而贲门少纳，故产后停经两载、日晡潮热，缠绵有年将涉虚损，属虚实夹杂之候。", ["浮", "大", "沉", "迟"]], "15956": ["治法", "原文未载具体脉象，仅言证脉合参。左腹块大如杯口，属气血瘀滞结聚，故以调经为主，俾气血流通则块可渐消。此段主旨为立治法，非论脉主病，脉象要素无从取字。", []], "15957": ["预后", "原文谓气血并调、八脉融和、经事可行。脉融和即脉来和缓匀调，无弦紧涩滞之象，示气血调畅、冲任渐复，故预后经事可通。此段以脉象融和判断调治后向愈之机，属预后之论。", ["和平"]], "15958": ["病机", "右脉虚细耎小主脾虚气弱，左关沉弦小数主肝郁化火，寸浮小空虚主心气不足。原文谓产前受惊、产后肝郁，郁火不舒致玉门生菌，兼心悸易惊、小腹疼、子户肿痛、溲赤便结，断为病在肝脾而兼乎心，故治当解郁清火、健脾养心。", ["虚", "细", "耎", "小"]], "15959": ["病机", "脉右沉小，右主脾肺，沉小示脾阳不振、气机郁滞。原文谓脾不醒则胃络不舒，脾失健运则胃络气阻，故右胁疼刺不舒。此脉主脾虚气滞、络脉不和之病机，与胁痛症候相应。", ["沉", "小"]], "15960": ["病机", "右脉耎小无力主气虚，左寸涩主血少，关弦为肝木不舒，尺濡为脾虚湿滞。经水愆期、行时腹痛，乃气虚血少、肝脾失和之象；体瘦食少、贪凉恶热、腹膨时痛，皆脾弱肝郁所致。脉证合参，病机在气血两虚兼肝脾不调，故先理肝脾。", ["耎", "小", "涩", "弦"]], "15961": ["病机", "脉右缓滑，缓主湿，滑主痰，右脉候肺胃。喉痛缠延、右颐漫肿、悬乳腐白、舌胎腻白如糊，皆风痰秽浊上侵肺胃之征；喉不干燥、不欲饮，更证非火热而属痰湿。故断为风痰上侵，当理肺胃以化痰浊。", ["缓", "滑"]], "15962": ["病机", "左右脉来虚涩濡小，虚小为气血不足，涩为血少行滞，濡为脾虚湿困。经行前后多少不定、腰胯酸疼、半月复至缠绵不已，皆气血两虚、冲任失养之候。服养阴止经剂即停，亦示阴血亏虚。法宜气血并调，切中虚涩濡小之脉。", ["虚", "涩", "濡", "小"]], "15963": ["病机", "左关沉弦主肝郁气滞，右关沉滑主痰积于脾。腹块由疟而起、发则攻痛且胀，甚则发厥，乃气与痰并、挟块攻痛；肝木侮土，故右关见滑。值经行之际，当以疏通法行气化痰、调肝理脾，使块与痛俱减。", ["沉", "弦", "滑"]], "15964": ["主病", "脉右浮数，浮主上焦，数主热。渴而多饮，证名上消，乃肺胃燥热、津液受灼所致。右脉候肺，浮数示热郁于上，故饮多而渴。病经廿日，速治为最，宜清肺胃之热以生津止渴，防其传变为中下消。", ["浮", "数"]], "15965": ["妇人", "脉束滑而小数，滑为妊娠之常，数主有热，小示胃阴不足。经停三月、心烦欲呕、体倦食减、口干便结，皆恶阻之象，因胃阴亏虚、胎气上逆所致。脉证相符，故曰勿药有喜，议养胃阴以安胎止呕。", ["滑", "数", "小"]], "15966": ["病机", "脉右按之数，右脉候肺，数主火。二目白珠甚红，白珠属肺，乃肺火内郁、上攻于目之征。火郁于内，故按之而数。治宜清散法，清肺火兼散郁结，使火降则目赤自退，切合脉数之病机。", ["数"]], "15967": ["病机", "右虚小无力主气虚血少，左关举浮按弦主肝血不足而气滞。新产五朝，恶露未清，左目失明、瞳神不敛，乃血虚血滞、目失所养。头腹不痛、无他苦，排除外邪实火。故以气血并补，佐舒滞敛神，使目可复明。", ["虚", "小", "浮", "弦"]], "15968": ["病机", "六脉沉伏，沉为在里，伏为邪闭，合面青少神、背曲足踡、苔白腻、腹痛难忍，显系寒邪深伏三阴，阳气不能外达，故脉道潜伏不起。腹左兼麻，乃寒凝肝络、气血不充之象，深虑转筋入腹，亟宜温中舒肝以透伏寒。", ["沉", "伏"]], "15969": ["治法", "此段未载具体脉象，然前诊六脉沉伏，今云「色脉谛详，明明是夏月感寒」，是凭沉伏之脉与面青足踡之色合断为寒。暑月感寒，寒邪闭遏阳气，故虽暑热当令而必用温药，所谓「寒者温之」，治寒以温，不可因时令而废绳墨。", []], "15970": ["预后", "前诊六脉沉伏，今「脉之伏者渐起」，是寒邪渐透、阳气来复之佳兆；惟「软小不舒」，软小为气血未充、脉道未畅，故改用理脾和肝、扶脾养胃调理。脉由伏而起、由起而软小，反映邪退正虚、脾胃渐复之过程，预后向安。", ["伏", "软", "小"]], "15971": ["病机", "脉象虚耎无力，虚为气血不足，耎而无力为正气衰馁，合产后半月恶露未清、寒热频发、咳呛气逆、汗出无时，显系气血两亏、营卫失和。医作外感误汗，更伤其正，故深恐涉蓐劳之门，药饵不可妄投。", ["虚", "耎", "无", "力"]], "15972": ["病机", "右脉细软兼迟，细软为脾土虚弱，迟为阳气不运；左脉沉小而弦，沉小为肝阴不足，弦为肝气偏旺。合之素有肝胃气、胀痛兼呕、食入即胀，正是土被木乘、脾胃愈惫、运化失职之象，故中满之虞难免。", ["细", "软", "迟", "沉"]], "15973": ["病机", "此段未载具体脉象，然云「证脉合参，究属脾阳不运，卫气不充，八脉有亏」。前诊右脉细软兼迟，今腹胀减、浮肿退而身常畏冷、绵衣不离，是脾阳未复、卫气不充；经事趱前似血热，实为肝阴不足，冲任失养。", []], "15974": ["病机", "左关弦细，弦为肝气横逆，细为阴血不足；尺脉迟涩，迟为下焦虚寒，涩为气血滞涩。合脐下痛剧、重按始缓、气逆上冲，正是冲脉为病、足少阴经气上逆、下焦虚寒为患。痛甚防厥，勿可藐视。", ["弦", "细", "迟", "涩"]], "15975": ["病机", "右脉虚软无力，虚软为脾土亏虚、运化无力；左关小弦，小弦为肝血不足而肝气偏亢。合食后胀疼、腰腿漫肿、经停两月，显系肝血亏而脾土更亏，土虚金弱又兼咳呛，故防有中满之变。", ["虚", "软", "无", "力"]], "15976": ["病机", "右脉沉小乏力，沉主里、小主虚，乏力为气弱，反映阳明胃土久伤、中气不足；左关虚弦，关候肝，弦为肝脉，虚弦乃肝木乘土犯胃之象。呕吐不酸苦甜、腹不痛，说明非实邪阻滞，而是胃虚失降、肝气上逆。汤药入口即呕，胃气大虚不受纳。故脉象揭示脾胃虚弱、肝木犯胃之病机，主呕吐日久不愈。", ["沉", "小", "虚", "弦"]], "15977": ["病机", "原文未识出脉名，仅言“合证脉而详审之”，故脉象要素缺如。所述肝郁胸闷、目珠红肿、鼻衄舌痛，继发左鼻臭水如豆腐脑，皆肝火郁而冲肺、木火侮金之象。肺窍开于鼻，肝胆相表里，胆移热于脑发为鼻渊脑漏。脉虽未明，然据证推脉，当见弦数之类，主肝火郁冲、肺窍受灼之病机。", []], "15978": ["病机", "脉细软无力，细主阴血不足，软主气虚，无力为脾虚不运。泄泻有年、长夏尤甚，长夏湿盛，脾土本虚，湿更困之；食后膨胀、肠红，乃脾虚不摄、湿郁化热伤络。医以凉血清火更伤脾阳，泄泻益盛。脉象揭示脾土虚弱、运化失职，主久泻中满之病机，故当调坤土以免中满。", ["细", "软"]], "15979": ["病机", "脉象细小，细主阴伤、小主气弱，为冷茶阻遏经水、气血凝滞之征。经行饮冷，寒凝胞脉，经止结块伏于胁下，痛如刀割，舌绛无苔、口干喜饮，示寒遏热伏、阴血受损。脉细小而非数疾，说明非纯实热，乃寒凝气滞、血瘀成块。主冷茶阻遏经水、瘀结成块之病机，防成中满。", ["细", "小"]], "15980": ["预后", "脉象浮数，浮主邪在表、数主热，此处为痈脓将溃之兆。块痛中央一点渐软如龙眼大，按之最痛，乃痈之头，结合浮数脉，说明热毒聚而成脓、正气趋表托邪。脉浮数示脓已成而有溃脓之势，故再议托里排脓之法。此段以脉判断痈脓欲溃，属预后转归之论。", ["浮", "数"]], "15981": ["主病", "右脉沉迟，沉主里、迟主寒，右脉候脾胃，沉迟为寒邪内侵、食积停滞之象。每夜四鼓脐上微痛即泻，四鼓阴盛阳微之时，寒食内停、脾阳受困，故痛泻定时而作。脉右沉迟正合受寒停食之机，主里寒食积、脾运失司之病，故温散消导一剂而痛泻顿止。", ["沉", "迟"]], "15982": ["病机", "关尺沉中兼数，左稍大于右。沉主里，数主热，关尺候肝肾阴分，沉数并见为阴虚内热之征；左大于右，左候血、右候气，示阴血不足而虚热偏亢。经行半月余忽多忽少、色带紫泡，舌纯红无苔、口干不渴，皆阴虚内热、血不循经之象。脉象揭示阴虚内热、冲任不固之病机。", ["沉", "数"]], "15983": ["预后", "脉象虚弦，虚主正气不足，弦主肝木偏旺，为寒热两月、正虚邪恋之象。寒热久延，气血耗伤而肝郁未解，虚弦并见示正虚而邪未净。久热不退，阴液渐耗，恐成骨蒸劳热，故曰“速宜退热，久恐骨蒸之虑”。此段以脉测预后，提示当急退热以防阴伤骨蒸。", ["虚", "弦"]], "15984": ["病机", "脉左浮数，浮为风邪在表，数为风化为热。舟中不避风邪，风疹屡发，内热口干，骨节疼痛，皆风热郁于肌表、不得透达之象。风邪化热，故治在清散，清其热而散其风，脉症相应。", ["浮", "数"]], "15985": ["病机", "脉息虚数无力，虚为气血俱亏，数为产后阴血不足、虚热内生，无力则正气大虚。虽见寒热头汗兼痛，似外感而实非，乃产后气血亏虚、营卫不和所致。故引丹溪「产后气血俱亏，虽有他证，以末治之」，不可作外感攻散。", ["虚", "数", "无", "力"]], "15986": ["主病", "右关沉实而滑，沉主里，实主邪实内结，滑主痰饮壅盛。右关候脾胃，痰浊内阻，气机不畅，故胃脘痛、右胁痛交替发作，痛时牵引背骨，胸痛彻背，夜间尤甚。食饮尚贪，知胃气未败，故用瓜蒌薤白半夏汤涤痰开结。", ["沉", "实", "滑"]], "15987": ["病机", "六脉软大、小数，软大主气血亏虚、脉道不充，数主虚热。产后去血过多，新冒风邪，血虚不能濡养筋脉，故手指颤振；虚热上扰，故身热有汗、头疼耳鸣。病已四日，防其发痉，正合《金匮》新产三病之训。", ["软", "大", "数"]], "15988": ["病机", "原文未识脉名，仅言「六脉如昨」。产后去血过多，荣血大亏，孤阳外浮，神魂不守，故发厥于下床小溲时，顷之即醒。头痛渐减而食粥即呕，乃胃气上逆。此属险途，议益气养阳、和胃止呕，以免痉厥。", []], "15989": ["病机", "左脉空虚，右脉稍小无力，左候血、右候气，气血大亏之明征。产时去血过多，兼汗出不少，心血大亏，肝亦失藏，故昨见厥。血亏则虚热难退，神疲难支，视一人如两形。治当益气养血、调和营卫，扶阳以生阴。", ["虚", "空", "小", "无"]], "15990": ["病机", "脉软大而空，软大主气虚，空主血脱，乃阳气外越、阴不内守之象。不时呵欠、恍惚、视岐，皆神魂不守、虚阳浮越所致。阴不敛阳，阳不固阴，故议固纳一法，以冀转机，防其虚脱。", ["软", "大", "空"]], "15991": ["病机", "脉仍虚大无力，虚为气血未复，大为虚阳外浮，无力则正气难支。服气营两固方后精神稍健、耳聋渐减、舌绛稍淡，食饮渐贪，是胃气渐复；然忽热忽退、喉干引饮、小溲觉热，仍属阴血亏虚、虚热未清。故用六味地黄汤加参麦以滋阴益气。", ["虚", "大", "无", "力"]], "15992": ["病机", "原文未识脉名，但言“色脉合参”，结合产后“气血将复，食饮渐增，天癸已行”而“肌体未丰，八脉未充”，可知脉象当显气血未充之象。其病机为产后气血虽渐复而未尽复，八脉空虚，脾约症亦因气血未充而肠燥未润。故治以益气培阳，使气血融和，则精神自旺，脾约渐润。", []], "15993": ["主病", "脉浮数有力，浮主表、数主热，有力为实。患者素喜烧酒，湿热内蕴，左鼻瘜肉有年，近疼痛无时，牵连左目头角，痛极防失明。此湿热郁火上攻清窍，脉浮数有力正合风热或湿热壅盛之实象。病起数载，治之匪易，脉症相参，主病在鼻窍及头目。", ["浮", "数"]], "15994": ["病机", "初诊脉浮数，为风邪客肺、气闭火郁，故咳嗽痰黏，治宜疏解。服后咳减痰薄，但舌苔尚腻，脉仍弦数，夜间口干内热，经水过期旬日未至。弦数示风邪未净，肝火内郁，血分有热，故经候逾期。先理客邪，再调经血，脉象反映表邪未解而里热渐显。", ["浮", "数", "弦"]], "15995": ["病机", "脉息虚浮，虚为气弱，浮为表不固。咳嗽十去其八，痰少，天癸已止，知饥贪食，但夜间有汗，表气不固。此肺胃并调后邪退正虚，卫阳不固而汗出，脉虚浮正合气虚表疏之机，故以益气固表为治。", ["虚", "浮"]], "15996": ["病机", "右关虚大无力，左关沉弦而劲。右关候脾胃，虚大无力为脾虚气弱；左关候肝，沉弦而劲为肝郁化火、气结血瘀。患者体瘦性躁，左胁有块，寒热交作，块动则心下跳动，叫呼如狂，显系肝郁气逆、痰瘀互结。脉象虚实夹杂，主肝郁脾虚、气火内扰之病机。", ["虚", "大", "弦", "劲"]], "15997": ["病机", "脉息虚大无力，为阳虚气弱之象。经断四载，忽吐血盈盏，血止后头汗无时，耳聋昏倦，似热非热。吐血过多阴亦伤，而脉虚大无力主气阳不足，卫外不固，故头汗如淋。此血去气伤、阴阳两虚之病机，与“精脱者耳聋”“阳气虚也”之论相应。", ["虚", "大"]], "15998": ["预后", "脉形细小而劲，细小为阴血亏少，劲为脉失柔润、虚火内扰。患者寒热无期，舌苔光剥，唇齿干燥，食饮维艰，显系阳弱阴亏、荣卫两虚。脉细小而劲，正合虚损之征，故曰“虚损之征已露先机”，预后堪忧，亟亟护阳益阴。", ["细", "小", "劲"]], "15999": ["误治", "脉象浮小而细，浮主表邪未解，小细主气血不足。素体肥胖，经行落后，风寒湿三气合而成痹，痛剧难忍。他医误作痿证，妄用温补，致痛势更增，寒热交作。脉浮小细示外邪未祛而正已伤，温补壅滞反助邪，故法宜祛风渗湿、通经活络。", ["浮", "小", "细"]], "16000": ["病机", "脉象细软，细为气血不足，软为脾土虚弱。崩血渐减而便泄随至，缘贪食荤味，滋腻碍脾，脾失健运，故脉见细软。此脉主脾虚气弱、运化无力，与崩漏后气血未复、便泄日数次相应，故治以益气扶脾，冀坤土得令。", ["细", "软"]], "16001": ["病机", "左弦右缓，左关候肝，弦为肝郁气滞；右关候脾胃，缓为土气尚和。素有肝胃气，发时遍体不疏、腹痛胀呕，目疾频发，寒热经水应期，种种见端由肝郁波及于胃。脉形左弦右缓，正示木郁土中之象，法当土中疏木，使土木合德。", ["弦", "缓"]], "16002": ["病机", "脉右沉细、左小弦。沉细为里虚阴不足，小弦为肝郁冲脉失养。素有肝气，当脐作痛，痛甚则厥，得重手按脐方缓，腿膝觉冷得暖则缓，皆冲脉为病、里虚而痛、阴不足之征。脉沉细主下元虚寒，小弦主肝气内郁，故治以温养下元。", ["沉", "细", "小", "弦"]], "16003": ["病机", "脉形软数、尺脉虚濡。软数为虚火内扰，尺脉虚濡为肾水亏乏。下消症渴饮溲数，出如膏油，由肝郁波及心肾，水火不交，肾水不能上承，心火难以下降，正合未济之卦。脉软数示火在水上，尺虚濡示下元虚竭，故证非轻候。", ["软", "数", "虚", "濡"]], "16004": ["病机", "脉软滑而细。滑为宿食停阻，软为脾运不健，细为气机不畅。泄泻五日，由食面肉而起，胸闷不饥不食，食则呕吐，腹痛即泻，虽在高年而宿食停阻。脉软滑而细，正合食滞中焦、脾失运化之机，故以运食舒中为最。", ["软", "滑", "细"]], "16005": ["病机", "脉象沉滑。沉者气之滞也，滑者食之阻也。脘腹作痛，痛剧脐中块攻，气食交阻。沉脉主气机郁滞于里，滑脉主食积内停，气食相搏，故痛剧而块攻。法宜温中运食，防痛甚发厥，正合脉沉滑所主之气滞食阻病机。", ["沉", "滑"]], "16006": ["病机", "脉息细耎而涩。细耎为阴血亏虚，涩为血燥筋枯、脉道不利。干脚气小腿细小肉削，痛如锥刺，大小腹痛胀，食少便结，由水不滋木，木强乘土。脉细耎涩正示血燥筋枯、水亏木旺之机，故议养水滋木以舒筋。", ["细", "耎", "涩"]], "16007": ["病机", "右软小无力，左关浮之弦细，按之小数。软小无力为脾虚气弱，弦细为肝郁血少，小数按之示郁火内动。左胁块痛，吐血盈盂，疟止块至，食少体瘦，天癸未至，胸中郁郁不舒，肝火易动，直冲血溢。脉象正合脾虚肝郁、血燥火动之病机。", ["软", "小", "弦", "细"]], "16008": ["预后", "脉息沉细迟缓，沉细为阳气衰微，迟为脏寒，缓主中焦虚冷。中脘胀痛波及小腹膨急、痛无宁刻，更见厥逆，乃阴寒内盛、阳气欲脱之兆。深虑汗多则阳随汗泄，食不喜进则胃气已败，故曰病势颇险，勿得忽视。", ["沉", "细", "迟", "缓"]], "16009": ["病机", "右脉软小无神，右关候脾胃，软小无神为胃气大虚；左脉弦细，左关候肝，弦细为肝阴不足、木失柔养。肝胃并亏，故面色㿠白、神疲难支、二目半合、额有黏汗，食毫不进。痛剧见厥之后，深恐骤脱，议四君子加味亟固胃气，正合脉证。", ["软", "小", "弦", "细"]], "16010": ["病机", "两关弦大，按之不足，弦主少阳郁热，大而无力为邪热内伏、胃土受伤。寒热二十日未解，脘腹膨胀，舌苔早黑，耳鸣骨节疼，皆邪热内伏、胃土失令之象。疏表清凉未去病，故以和解退热、俾胃土得令为最，恐犯虚热之门。", ["弦", "大"]], "16011": ["病机", "脉形弦细，按之不足，弦为邪郁少阳，细为阴血亏虚。行经后血室空虚，暑湿热乘虚内陷，故寒热无期而朝轻暮重，吟咏呓语、口干喜饮，皆阴亏于下、邪终不解之征。脉证相符，故曰非无以也，姑拟益阴退邪以冀转机。", ["弦", "细"]], "16012": ["病机", "左脉弦滑且数，弦为肝郁，滑为痰火，数为火升。肝郁化火，火升痰涌，故脘腹作楚欲呕、发厥手颤、二日上窜、牙关紧闭；面色娇红、鼻衄色紫，皆火升迫血之象。脉证合参，知厥衄之所由来，正由肝郁火升使然。", ["弦", "滑", "数"]], "16013": ["病机", "脉象沉紧，沉主里，紧主寒主痛。内唇肿硬畏寒，波及鼻傍漫肿，疼痛难忍，得热熨稍缓，见风愈剧，皆风寒外束、荣气闭固、郁结不散之征，故成内唇疔。治宜外疏风寒、内散肿拔疔，针泄其气，敷以霞城散，内服苏叶、防风等疏解之品。", ["沉", "紧"]], "16014": ["病机", "右脉软小，左脉弦细。右关候胃，软小为胃土久虚；左关候肝，弦细为肝木失柔。临经前后小腹必痛、呕酸水、甚则增泻，乃肝木犯胃土，胃与大肠同属阳明，故痛泻并见。幼喜生冷、暑热水果不戒，益见阳明胃土久虚，治宜舒肝和胃。", ["软", "小", "弦", "细"]], "16015": ["病机", "脉浮小乏力，浮为外风相搏，小乏力为阴虚血少、不能荣筋。素多劳役，阴虚体质，血不荣筋，加以外风，故头痛且重、骨节疼如针刺、身微热、口苦舌干、内热不喜冷饮。进药后微汗而解，正合浮小之脉从表疏解、养血荣筋而愈。", ["浮", "小"]], "16016": ["主病", "脉浮小为风暑外袭、肝脾不和之象。风暑搏结则头胀，小腹闷痛难忍，带浊绵绵，病经六日而脉仍浮小，说明表邪未解、里气已伤。浮为风暑在表，小为正气不足，故治当疏解和肝，不可忽视。", ["浮", "小"]], "16017": ["病机", "脉形细耎主脾虚湿盛，左虚弦为肝气不舒，尺无滑疾之象则非胎。脾虚挟湿故稠痰盈盂、白带频下、阴户湿痒；肝气不舒则腹膨背胀、腰胯漫肿。食能进多则胀，经停三月，脉不滑疾，明非妊娠，诚恐脾土不运致中满。", ["细", "耎", "弦", "虚"]], "16018": ["预后", "脉右虚小无力，右脉候脾，虚小为脾土大亏之象。三疟年余方止，脾土已伤，夏间劳碌过度，食入即胀、胀时腹疼，左腹疟母成块，皆脾虚不运、气血瘀滞所致。失于将息，防成单腹胀，故脉见虚小无力，预后当慎。", ["虚", "小"]], "16019": ["治法", "脉息虚软，为脾胃两亏之征。红痢延绵，腹痛虽止而昼夜粉红冻七八次，小腹膨闷，带下直溜，腰疼食减，皆脾虚不摄、湿滞下焦所致。虚软脉不任攻伐，故亟理坤土，方用冬术、山药、扁豆、茯苓等益气健脾，痢止为最。", ["虚", "软"]], "16020": ["治法", "高年脉弱，为脾气虚弱之象。滑泻如冻、带下直溜，虽得食精神渐健，然脉弱示中气未复，滑脱未固。治以益气调中，兼厚肠固脱，亟平为妥。脉弱与滑泻并见，说明脾虚不运、肠滑不固，故以固脱为要。", ["弱"]], "16021": ["病机", "脉形濡小，濡主湿、小主虚，为寒湿内蕴、中阳不足之象。中虚挟湿则气声如鸣、大便溏泄日夜数行；寒湿内蕴则两足浮肿、面色痿黄、食入觉噎。深恐木乘土位，致令腹胀成膈，故法当温中运湿，以复脾阳。", ["濡", "小"]], "16022": ["主病", "脉来濡数，濡为阴血不足、湿滞不化，数为血热内扰。血崩旬日，每发于夜，血去过多则阴虚，阴虚生内热，热迫血行故崩不止。濡数脉示阴虚血热、冲任不固，速止为妥，不可迁延。", ["濡", "数"]], "16023": ["病机", "脉象沉细，沉主里、细主虚，为肝郁血虚、气滞不行之象。痛块作胀近于脘左，迄今四载，举发无时，乃肝气郁结、久病入络，气血瘀滞而成块。沉细脉说明病在里而正气已虚，故拟舒肝和胃法，理气而不伤正。", ["沉", "细"]], "16024": ["病机", "脉形软小，软为虚象，小为气血不足。小产后经血骤至，腰疼腹痛，下衣膜裹血，腹中尚有块，寒热更重，舌绛光滑，气逆呻吟，口干喜饮，时欲恶心，此瘀血内停，气血两虚，正虚邪实之候。脉软小提示正气已伤，无力托邪，故议去恶露、退寒热为紧要。", ["软", "小"]], "16025": ["预后", "脉象仍软小乏力，软小为气血虚衰之象。药后血缓痛减，腹块缩小，寒热未至，但气闷神倦欲呕，闭目神思恍惚，张目火光散大，此阴血亏虚，虚阳浮越，神不守舍，故属险候。脉软小乏力示正气难复，虚风内动之兆。", ["软", "小"]], "16026": ["预后", "脉仍耎小模糊，耎小为气血虚衰，模糊为胃气将败。胸背热气时升，鼻孔似煽，纳谷维艰，便后神疲多梦，此虚阳上越，阴不敛阳，有脱厥之虞。色脉合参，深虑虚阳上越防脱，故亟护真气，镇肝敛神。", ["耎", "小"]], "16027": ["病机", "脉虚小数，虚为气阴不足，小为血少，数为热。咳嗽痰红，喉痒气逆，旧恙复发，正值土旺，此肺阴亏虚，虚火上炎，灼伤肺络，故痰红。脉虚小数示阴虚内热，亟宜停止，服方一帖血止，示药证相符。", ["虚", "小", "数"]], "16028": ["主病", "脉形虚芤，虚为气血不足，芤为中空，主失血。血崩逾月，寒热兼厥，此血去过多，阴亏阳弱，荣阴不守，卫阳不固，故寒热而厥。脉虚芤为血崩正虚之应，治验在扶阳济阴，使崩止厥回。", ["虚", "芤"]], "16029": ["病机", "脉虚无力，左脉虚芤，虚为气弱，芤为血脱。血崩逾月，血去过多，阴亏阳弱，荣阴不守，卫阳不固，故寒热兼厥。脉虚芤示气血两亏，阴不敛阳，深虑骤变，亟宜扶阳济阴，俾崩止厥回。", ["虚", "芤"]], "16030": ["病机", "脉虚无力，虚为气弱，无力为脾虚。产后脾虚泄泻，昼夜廿余度，口干足肿，迄今匝月，此脾气下陷，运化失职，清浊不分，水湿下注。脉虚无力正合脾虚气陷之机，故先理中宫，以复健运。", ["虚"]], "16031": ["病机", "脉细如丝，左脉微弦，细为阴血亏少，弦为气逆，微为阳弱。喘症有年，肌瘦食减，咳则小便直溜，卧不着枕，此肺肾两虚，冲脉气逆，痰壅胸脘。前医投纳气反壅塞，便燥，脉细弦微示虚中夹实，气壅痰阻，非纯虚可补。", ["细", "弦", "微"]], "16032": ["预后", "原文述服药后胸脘渐松、喘急顿平、能坐立问答，但“脉仍如昨”，说明病虽减而脉象未变，脉证不符，故曰“能于斯而日渐减可，庶乎尽善”，提示需继续调治，不可因症减而忽视脉象未复。", []], "16033": ["病机", "产后恶露甚少即停，过食厚味，致瘀血内蓄，胸腹胀闷、错语、牙关紧闭、小腹膨胀。脉虚而滞、左脉弦紧，虚为产后体虚，滞为瘀阻，弦紧主痛主瘀，说明瘀血停滞、气机壅塞，非纯虚可补。", ["虚", "滞", "弦", "紧"]], "16034": ["病机", "原文未及脉象，但述脐下块大、时痛膨胀，前医误补致厥，急进逐瘀方而恶露瘀块顿下，说明病机为产后恶露停蓄、瘀血上攻，治当益气温经逐瘀，不可概作产后补纳。", []], "16035": ["病机", "服逐瘀剂后恶露又下、痛缓块平，但脘腹不舒、食饮未贪，脉象虚耎、右关沉小。虚耎为气血不足，右关沉小主脾胃虚弱、运化无力，说明瘀去而胃气未复，宿滞内停，故用和胃调中兼润燥之法。", ["虚", "耎", "沉", "小"]], "16036": ["兼症", "素有肝胃气，发则呕痛；今寒热、咳嗽、头疼，舌绛，脉右浮缓、左弦细。右浮缓为外感风寒、卫表不和，左弦细为肝胃气滞、阴血不足，故先理寒热，用苏梗、前胡等解表，兼以杏仁、瓜蒌仁等理肺化痰。", ["浮", "缓", "弦", "细"]], "16037": ["病机", "咳嗽愈后肝胃气复发，脐上下作痛、呕吐，发于申酉至夜半，面目小腿虚浮，脉息两关小弦。小弦为肝胃不和、气机郁滞，脾土久亏则虚浮，说明肝胃气逆、脾失健运，故当理肝胃。", ["小", "弦"]], "16038": ["病机", "齿痛夜间更甚，清火舒散不应，左脉虚数。虚数为阴血不足、虚火上炎，非实火可清，故用补虚降火之法而痛止，说明病机为肾阴亏虚、虚火上攻齿龈。", ["虚", "数"]], "16039": ["病机", "体丰多劳、中虚挟湿多痰，骤然头眩眼暗、呕吐酸苦、舌白胸闷、起立如舟车，脉浮滑弦紧。浮紧为外寒，滑为痰湿，弦为肝风，说明外寒引动内风，风火交煽、气阻痰凝，故头眩呕酸。", ["浮", "滑", "弦", "紧"]], "16040": ["病机", "脉形软弱无力，为产后气血大亏、虚热不已之象。原文谓“产后气血大亏，虚热不已，加之汗出过多，岂不虑其虚脱”，脉软无力正合气血两虚、气不固摄之机，故急宜气荣两固、扶养胃气，防其虚脱。", ["软", "弱"]], "16041": ["病机", "脉象沉紧弦细，按之无力，主痰饮内停、络脉不利。原文述“脘腹闭闷，不饥纳少，腹按之如裹水之状，漉漉有声”，沉紧弦细为饮邪内结、脾阳不运之征，病在脾、胃、肝，关冲、任脉，故断为痰饮无疑。", ["沉", "紧", "弦", "细"]], "16042": ["病机", "脉象沉紧弦细无力，四肢觉冷，为中脘寒痰凝阻成饮、中气有亏之候。原文谓“按之有声如水”“停经三月余”，沉紧弦细主寒饮内凝，无力为阳气不足，故当温理中宫，用附子理中汤合香砂六君子汤。", ["沉", "紧", "弦", "细"]], "16043": ["病机", "脉象细焮尺濡，素体瘦弱食少，气血不足，天癸逾期，白带频下，为阴阳两亏之体。细濡主气血亏虚、冲任失养，尺濡尤关肾阴不足，故宜温养血气，俾八脉融和，经行应期。", ["细", "濡"]], "16044": ["主病", "脉象耎小，寒热发于酉后，寒甚热微，舌苔白腻，为寒湿内蕴、阳气不振之象。耎小主正气不足、湿邪内阻，故寒热如期而作，法从温中和解，兼治头疼。", ["耎", "小"]], "16045": ["预后", "脉弱，按之若无，气逆不降，神疲肢冷，食少肉削，为脾阳大败、元阴亦亏之危候。原文谓“只恐骤变”“究防虚脱”，弱脉按之若无，示元气衰败，故议扶土益金法，以防虚脱。", ["弱"]], "16046": ["病机", "脉象浮小兼数，产后冒风咳嗽咽疼，忽吐鲜血，色带紫块，为阳明胃土攸关。浮小兼数主风热犯肺、胃火上升，阳络伤则血外溢，故宜清降则血散火退。", ["浮", "小", "数"]], "16047": ["病机", "脉右软小，左濡数，热未净尽，食不贪，为阴亏火旺、余热未清之候。右软小主脾弱，左濡数主阴伤火动，故议育阴降火一法，免其变幻。", ["软", "小", "濡", "数"]], "16048": ["病机", "脉软小无力、左濡小，软小为气血不足、脾土虚弱之象，濡小偏于左关则肝血亦亏。原文言“肝郁乘土”，大便溏泻日六次，正是肝气横逆乘脾、脾失健运，故脉见软弱无力而非实滞。脉症合参，病机在肝郁脾虚、中气下陷，故拟养胃止泻，以扶土抑木为法。", ["软", "小", "濡"]], "16049": ["预后", "脉形尚耎小无力，耎即软，软小为脾胃气虚、正气未复之象。然原文述“食贪神健，便溺调匀”，症情已趋平善，脉虽软弱而胃气渐回，故属病后调理收功之候。脉软小在此非主新邪，而是反映气血尚虚、脾运未充，故仍守前方出入，缓图恢复。", ["耎", "小"]], "16050": ["病机", "脉息右耎、左微弦，右候脾土，耎为脾土亏虚、运化无力；左候肝木，微弦为肝气不舒。脘腹膨胀有声，正是脾虚失运、气滞于中所致。原文断为“脾土亏而肝木不舒”，脉之右耎左弦恰与土木同病相应，故从土木并治，健脾疏肝并举。", ["耎", "弦"]], "16051": ["病机", "脉左虚弦，左关候肝，虚为肝血不足，弦为气机郁滞。原文言“肝虚气滞，热郁生风，发而为痫”，指出痫证由肝虚为本、气滞热郁化风为标，脉虚弦正合虚中夹郁之机。故特申“治在养肝，毋泛作风痰治”，强调不可徒事熄风化痰而伤其本。", ["虚", "弦"]], "16052": ["病机", "左寸关脉弦数，弦主风与气郁，数主热，寸关候心肺胸膈。原文述胸膈热闷、谵语烦躁、二便不通、惊惕怕火，断为“风暑相搏，内有郁热”。眼闭则魂不归肝而惊，眼开羞明怕火，皆郁热扰及肝魂之征。脉弦数正应风暑郁热之病机，故前服荆防藿香不应，改用清透而效。", ["弦", "数"]], "16053": ["病机", "脉象沉紧，沉主里、主寒，紧主痛、主寒凝气滞。原文述感寒腹痛起病，痛如刀割、朝缓夜剧、痛甚见厥，证名骨痹，断为“寒与气郁，湿阻关节，引动内风，肝虚气滞”。沉紧之脉正合寒湿闭阻、气血不通之机，故法从温舒，用温通散寒、行气舒筋之品。", ["沉", "紧"]], "16054": ["病机", "脉形虚芤，虚为气血不足，芤主失血、血虚，左弦细为肝血亏而气机不柔。原文述恶露未尽而心荡口苦、体倦神疲，正是产后失血、气血两虚、肝血不足之候。脉虚芤与恶露未净、血去正伤相应，故用生化汤类养血化瘀，加意图维，扶正兼祛瘀。", ["虚", "芤", "弦", "细"]], "16055": ["病机", "脉右软弱、左弦细，右候肺脾，软弱为肺金气虚、脾运不健；左弦细为肝血不足、肝火偏亢。原文述喘咳气逆、痰沫频频、纳谷维艰，又眼鼻作痒、易怒，断为“肺金虚”而“肝火冲肺”。脉右软左弦细正合肺虚肝旺之机，故深虑喘汗并至，亟宜益气定喘。", ["软", "弱", "弦", "细"]], "16056": ["病机", "脉弦数者，弦主肝郁气滞、痛胀，数主热。经行骤阻而小腹痛胀，经带并下、溲出疼痛涓滴不爽，是肝郁化热、气滞血阻，兼挟淋浊之邪。弦数相应于经阻挟淋之病机，故原文断为「经阻挟淋，兼而疗之」，示气滞热结与湿淋并存。", ["弦", "数"]], "16057": ["预后", "脉形虚软，虚为气血不足，软为胃气不充。吐血有年、白带频下、年逾半百天癸未停，久吐伤络，气血两耗，故脉不任按而虚软。原文虑其上溢、防其下崩，正因虚软之脉示阳明胃络久伤、阴络不固，故曰「预为调摄」，属预后调护之论。", ["虚", "软"]], "16058": ["病机", "右脉虚耎，左弦细。右候脾胃，虚耎为土虚湿盛；左候肝胆，弦细为木强风动。风寒湿痹始于左足，由左达右，原文谓「木强乘土，土虚金弱」，内风动而风生，故脉右虚耎、左弦细，恰证扶土祛湿、舒肝却风之治法所本。", ["虚", "耎", "弦", "细"]], "16059": ["病机", "脉象耎而左小弦。耎为荣虚卫弱，小弦为肝血不足、虚火内动。经行色淡且少、夜寐不宁、内热火升耳鸣、心凛凛毛耸易汗，皆血海不足、虚火上炎之候。脉耎示气荣两虚，左小弦示肝阴亏而阳扰，故原文主「气荣两固」，先调荣护卫以止汗。", ["耎", "小", "弦"]], "16060": ["病机", "脉形细数，细主阴血亏少，数主虚火内升。咳嗽朝轻夕重、内热口干、手足心热、痰中偶兼血丝、白带频下，正是阴气亏而肺胃不足、土虚金弱、水亏火升之象。细数之脉与滋泥之剂不相宜，故原文断为肺胃气阴两虚、虚火灼络之病机。", ["细", "数"]], "16061": ["病机", "脉形浮缓，浮主邪在表，缓主湿与风。暑风内侵，畏寒身热、头重无汗、胸闷、骨节疼、腰胯酸痛，舌苔白泥满布，是暑湿挟风袭于肌表、湿阻气机。浮缓正合风暑湿在表未解之机，故原文谓「其势匪轻，速于舒解，微汗为妥」。", ["浮", "缓"]], "16062": ["病机", "右脉软和，左脉濡细乏力。右候脾，软和为脾阴不足；左候肝，濡细乏力为肝血亏虚。两足大指夜睡即麻，属脾之隐白、肝之大敦，经事趱前甚至一月两至，虽似有热而脉呈虚象，原文谓「究属虚象，脉可凭耳」，故主肝脾阴血不足之病机。", ["软", "和", "濡", "细"]], "16063": ["病机", "脉象沉紧，沉主里、主气滞，紧主寒、主痛。肝气旧恙复发，胸脘刺痛、气逆呕吐、肢冷发厥，更感寒挟食、舌苔泥白，是肝郁气逆于里，寒食交阻，阳气不达四末。沉紧之脉正应里寒实滞、气机闭阻之病机，故宜温舒。", ["沉", "紧"]], "16064": ["病机", "脉形软滑主湿痰内盛，左弦细为肝肾阴亏之象。素体丰健多湿痰，软滑应脾土湿困；天癸愆期、头眩眼花、肠红频发、小溲频数，皆由肝肾阴亏、脾弱不能统摄所致。弦细见于左，正合肝阴不足、木失柔养，故原文断为肝肾阴亏与脾土弱不能统摄兼有。", ["软", "滑", "弦", "细"]], "16065": ["预后", "脉象弦涩，弦主气结，涩主血滞，合胸脘满痛高凸，知酸邪固结不散。年近七旬而见弦涩，正气已衰、邪滞不解，故原文谓证在垂危、未便许可，然不忍坐待。此段以脉弦涩断邪结正虚之危候，属预后判断。", ["弦", "涩"]], "16066": ["病机", "脉虚细而数，虚细为气血两亏，数为阴不敛阳、虚热内扰。始便血继呕血，脱血过多，肝不能藏、脾不能统，阳明受累。原文引有形之血不能速生、无形之气在所急固，正因虚细数之脉示气随血脱之机，故治当固气为先。", ["虚", "细", "数"]], "16067": ["预后", "原文仅言脉象稍静，未出具体脉名，故脉素取空。血止汗停而脉稍静，是邪势渐退、正气稍安之象，故称似好消息；然调治之法尚费经营，说明脉静仅为暂时转机，脱血之后根基未复，仍须谨慎调理，属预后判断。", []], "16068": ["预后", "未识脉名，原文以脉来五至而有余为说。五至近于平脉而稍有余，是阴气渐得、胃气来复之征，故胃口已开、食纳渐增，称为好消息。然脱血之后务须归经，引导之法不可躐等，示脉虽转佳而调治仍须循序，属预后。", []], "16069": ["预后", "本段未出具体脉名，仅言病在垂危尚有胃脉。胃脉存则胃气未绝，生机尚在，故敢用养阴吸阳法一剂回春。胀痛下血、呕血盈盆、虚汗欲脱，本属危候，因胃脉尚存而可治，全段主旨在于凭胃气判断预后。", []], "16070": ["其他", "此段为医案序文，述郑素圃先生生平与著述缘由，未及具体脉象，故脉素取空。文中苦医之多不精脉、不达阳生阴长之故，是感慨时医不精脉理，非论某病之脉，主旨属其他，不可强作病机解。", []], "16071": ["病机", "脉来弦细而紧，三脉皆阴，紧主寒，弦细主虚寒凝滞。伤寒似疟经汗下而邪不解，舌黑而滑、干哕、饮汤即吐、当胸结硬，皆少阴水寒凌心、亡阳之机。原文断已转虚寒、非温剂不效，故用生附子、茯苓、干姜温阳散寒，脉象正是虚寒亡阳之据。", ["弦", "细", "紧"]], "16072": ["病机", "脉洪大无伦，重取则散，乃误汗伤阳、苦寒损阳，致真阳欲脱。洪大无伦为虚阳外越，重取散乱为元气涣散，故主少阴寒化、阳脱危候，症见神昏蜷卧、耳聋默睡，与‘脉反散大，乃真阳欲脱之机’相应。", ["洪", "大", "散"]], "16073": ["病机", "脉弦数而无力，为时疫邪自里发，误汗伤正、清热寒中，致干呕吐蛔。弦数似热，无力则正虚，故非实热，乃邪伏正伤、胃寒蛔动之机，与‘邪自里发于表’及‘清热必定寒中’相应。", ["弦", "数", "大"]], "16074": ["预后", "脉细数近疾，重取全无，为阴寒内盛、虚阳外浮之亡阳脱证。细数疾似热，重取无根则真阳败绝，故见舌卷焦黑、齿垢枯黄、露胸取凉等阴极似阳之象，与‘亡阳脱证’相应，预后凶险。", ["细", "数", "疾"]], "16075": ["病机", "脉细如丝，因肥甘冷结、食压太阴，中宫壅滞，津液不能上输，致脉道不利。细为阴伤，然语音清响、身轻起卧，无烦躁下利厥逆，故病脉似少阴而实太阴，与‘食压太阴，致脉不出’相应。", ["细"]], "16076": ["死脉", "脉一息二至，似雀啄之象，为胃气衰败、真脏脉见之死候。雀啄脉来三五不调，如雀啄食，主脾胃气绝，故见神昏谬妄、舌黑而干、身痛不能转侧，与‘脉则一息二至，似雀啄之象’相应，预后不良。", ["雀啄"]], "16077": ["病机", "脉细如丝而弦紧，细为阴伤，弦紧为寒，乃时疫阴斑亡阳之危证。虽身发赤斑、狂乱谵语似阳明热证，然口不渴、脉不洪数，故知非热，与‘作时疫阴斑亡阳危证’相应，主以真武理中而阳回斑散。", ["细", "弦", "紧"]], "16078": ["病机", "脉弦而紧，弦主痛、紧主寒，为阴寒内盛、逼阳外越之阴斑证。虽胸发紫斑、结硬而痛似热，然哕声越邻、舌苔灰黑、大便利水，皆寒象，与‘因冷极于内，逼其阳于外’相应，故用四逆汤温里。", ["弦", "紧"]], "16079": ["病机", "脉沉弦而紧，搏手甚紧，为沉寒痼冷直入于里之象。沉主里，弦紧主寒主痛，故见恶寒身痛、胸中阻塞、呕逆喉痛，与‘此脉乃沉寒痼冷，未经温散，直入于里’相应，当表里双温以逼寒外解。", ["沉", "弦", "紧"]], "16080": ["病机", "本案脉由素体虚寒之细小，感寒后转为浮脉，示表证仍在；继而脉细如丝，为少阴亡阳、阳气衰微之象。细如丝者，阳气不能充脉，与舌黑下利、尿如煤水并见，正是少阴寒化、吐汗多而亡阳之候，故见筋惕肉𥆧、神昏蜷卧，主病在少阴，属虚寒危证。", ["细", "浮"]], "16081": ["病机", "脉弦紧为寒邪内盛、气机收引之象。因夏月贪凉食冷，寒伤中阳，故脉见弦紧；痛在脐旁季肋之下，属少阴部络，且已汗而热不退、便而痛不减，渐增烦躁，乃内真寒外假寒之少阴病。弦紧应寒主痛，与腹痛、烦躁相应，故用茯苓四逆汤温里回阳。", ["弦", "紧"]], "16082": ["病机", "脉弦涩，弦属肝、涩主血，与夜则独语、胸腹皆痛相应，提示厥阴畜血；脉不长、口不渴，说明非阳明实热。后下紫黑血块半盆、昏晕大汗，脉转散大，乃血去气脱、阳气外散之候。弦涩为瘀血内阻，散大为正气溃散，故本段主畜血致脱之病机。", ["弦", "涩", "散", "大"]], "16083": ["病机", "脉沉细紧滑，沉细紧为少阴中寒、阳气不振，滑主痰饮内停。症见熟睡不醒、胸背胀痛、呕吐不能食、恶寒足冷，正合少阴病但欲寐之旨，乃寒痰冷气上参阳部所致。脉沉细紧滑与寒痰内盛相应，故断为少阴中寒兼痰饮，用四逆汤加半夏、茯苓温阳化痰。", ["沉", "细", "紧", "滑"]], "16084": ["病机", "脉弦紧为寒邪内郁、气机收引之象。病起夏月贪凉过餐生冷，先见午后发热、腰疼腹痛、便泻咳血，前医误作阴虚；今脉弦紧，说明寒邪由厥阴深入少阴，与呕哕喉痛、烦躁不寐相应。弦紧主寒主痛，故用桂枝、细辛、附子、干姜表里兼温，使少阴寒衰仍归厥阴。", ["弦", "紧"]], "16085": ["病机", "脉沉而紧、按之甚坚、全无和柔胃气，为寒实内结、胃阳衰败之象。沉紧主里寒，坚而无胃气说明寒邪锢结、阳气不能敷布；与呕吐发呃、胸结如石、舌黑而滑、渴欲冷饮而滴水不能纳相应。前医误下凉药，反使寒结于胸，故用生附子、生干姜大辛大热温开寒结。", ["沉", "紧"]], "16086": ["病机", "脉尺寸皆伏、惟寸口尚应指，为寒极于下、阳气不能升达之象。孕三月而恶寒呕吐、腹痛下利，继则厥逆、喉哑，正是少阴寒证，肾脉循喉咙、散舌本，寒极则肾气不至舌而失音。脉伏与厥逆、喉哑相应，故断为少阴寒证，急用四逆汤加桔梗救阳，不能顾胎。", ["伏"]], "16087": ["病机", "脉数大无伦、重取无力，为虚阳伏阴之脉。数大似热，然重按无力，说明阳气浮越于外而里真寒；与烦躁席地、身发赤斑、目赤畏亮、渴欲冷饮复不能饮相应，乃阴极似阳之假热。前医误为中暑投香薷，更伤阳气。脉大而虚正是虚阳外越、里寒内伏之病机，故用茯苓四逆汤温里回阳。", ["数", "大", "虚"]], "16088": ["病机", "脉细紧为寒邪在里、误汗伤阳之象。原文谓\"寒邪在里，不在表\"，细为阳虚血少，紧主寒主痛。初作阳证伤寒用汗法，汗后热愈甚、身痛腹疼，是误汗伤营卫；继而少阴亡阳烦躁、少腹急痛、两足厥冷，脉细紧正合寒盛阳微、由里转少阴之机，故用四逆加人参回阳。", ["细", "紧"]], "16089": ["病机", "脉弦紧非血虚之脉，乃经行血虚而寒袭之。原文\"此非血虚之脉，必因经血虚而寒袭之也\"，弦主痛、紧主寒，故见头痛身疼、发热呕逆。药后脉犹弦紧，\"全见厥阴经病\"，是邪乘血海空虚入血室，夜则谵言、寒热混淆，故用当归四逆表里双温。", ["弦", "紧"]], "16090": ["预后", "初脉弦数，为时疫邪从内发、混合三焦；至第九日\"脉变细疾\"，细为阴伤、疾为阳浮欲脱，伴烦躁下利、干呕胸满、汗自出，是邪陷少阴、将致亡阳之危候。原文直告\"病危矣\"，脉由弦数转细疾，正示病进由阳入阴、预后凶险，故列预后。", ["弦", "数", "细", "疾"]], "16091": ["病机", "脉细紧而弦，合呕哕痰涎、神昏但寐、腹痛下利、足冷舌灰、谵语，是寒邪深入、阳衰阴盛之候。原文\"病经八日，正阳尽入阴之时\"，细紧弦主寒主痛、阳虚饮聚，前医误作协热下利，实将至亡阳，故急用四逆汤救逆；次日\"脉稍和\"，示阳回之兆。", ["细", "紧", "弦"]], "16092": ["病机", "脉浮弦滑，浮为风邪在表，弦主少阳，滑主痰食。原文作风暑夹食，见头疼身痛、寒热而呕，是外受风暑、内夹食滞之证。前医作厥阴用桂附失之过重，继用柴葛平胃得汗，原文谓\"风暑之汗，不足畏也\"，脉证相合，故主风暑夹食之病机。", ["浮", "弦", "滑"]], "16093": ["病机", "脉虚大而迟，虚大为阳气浮散、迟为阳衰，合小便难出、少腹胀满、头汗时出、坐不能卧、气微促，是误汗亡阳、气化不行之候。原文\"此误汗亡阳，非大剂人参不能救\"，脉虚大迟正示阳气虚衰、膀胱气化失司，故用参附回阳、茯苓通利。", ["虚", "大", "迟"]], "16094": ["病机", "脉细而涩，细为阴血不足，涩为血行不畅。病者素清癯、年近六十，畜血暴下后小便不通，原文引\"无阴则阳无以化\"，是阴血暴虚、气化无源。细涩正合阴亏血少之机，故不用五苓而用猪苓汤加阿胶滋阴和营，一剂小便如涌泉。", ["细", "涩"]], "16095": ["病机", "脉弦而细，弦主厥阴、主痛，细为血虚。原文\"此证阴阳错杂，寒热混淆，乃厥阴经病也\"，见身微热、足冷呕逆、胸满咳痛、吐血水、腹痛下利、尿血谵语，是邪搏厥阴血分、上下出血。弦细正合厥阴寒热错杂、血虚邪搏之机，故主表里兼温、用桂附。", ["弦", "细"]], "16096": ["病机", "脉沉细为少阴里虚寒之象。患者寒夜食冷，腹痛作泻后卒然喉哑，外无他证，手足不冷，但脉沉细，显系寒中少阴，阴寒内盛，阳气不振，故脉沉细。沉主里，细主虚，合之则属少阴寒化，非表证。", ["沉", "细"]], "16097": ["病机", "脉变沉弦，为少阳之邪直入厥阴，阴寒内盛，脉气郁滞；后脉复沉细，乃厥阴不解，传入少阴，阴寒上逼心阳，故笑不休。沉主里，弦主痛，细主虚寒，脉象演变反映邪从少阳→厥阴→少阴的传变过程。", ["沉", "弦", "细"]], "16098": ["病机", "脉弦细而不数，身不热，说明病属厥阴而非少阳。弦为肝脉，细为阴血不足，寒凝肝脉。服当归四逆汤后脉浮发热，是寒邪外解，正气来复，故发瘾疹作痒而愈。脉浮为邪从表解之兆。", ["弦", "细", "浮"]], "16099": ["病机", "脉沉细而紧，沉主里，细主虚，紧主寒主痛。汗出沾衣、面赤、腹痛胀大、干呕、小便频数、下利，少阴证全。此因前用苍朴耗气、白术闭气，致阳气更伤，阴寒内盛，故脉沉细紧，当急扶阳。", ["沉", "细", "紧"]], "16100": ["病机", "六脉沉细，为里虚寒之象。伤寒半月，两下后心下痞硬、肠鸣下利、干呕心烦，形容瘦削，此误下伤中，寒热错杂于中焦，脾胃气虚，故脉沉细。沉主里，细主虚，非结胸之实，乃虚寒痞硬。", ["沉", "细"]], "16101": ["病机", "脉弦细而紧，弦为肝脉，细为阴伤，紧为寒痛。盛暑贪凉饮冷，寒中肝经，厥气上逆则吐血，肺寒则咳，冷饮下注则腹痛下利。两足冰冷、舌紫苔白，皆阴寒内盛之征，故脉弦细紧，主厥阴伤寒。", ["弦", "细", "紧"]], "16102": ["病机", "脉弦细而紧，弦主肝，细主虚，紧主寒。喉痛误用苦寒直折，致寒热格拒，痹结胃口，呕吐胁痛，不进米饮。此厥阴吐逆，寒热错杂，脉象反映肝经寒凝、阳气被遏，故用乌梅丸开格拒。", ["弦", "细", "紧"]], "16103": ["病机", "初脉细紧无力，为寒伤阳气，细主虚，紧主寒。后寒入少阴，脉紧近疾，疾为阳极似阴、阴阳格拒之象，非真热也。脉转数亦为格拒假热，故用半硫丸、生附子等破阴回阳，脉象反映阴寒内盛、虚阳外越。", ["细", "紧", "疾", "数"]], "16104": ["病机", "六脉弦紧而细，弦主厥阴，紧主寒，细为阳虚。前医误用石膏、栀子苦寒，致寒极于下、逼阳于上，故面赤如妆、头痛如裂，此戴阳之象。厥阴之络络于巅顶，寒客内络则小便频数。脉弦紧细正合寒客厥阴、阳郁于上之机，幸未厥冷下利，邪犹在经，故可温经散寒而愈。", ["弦", "紧", "细"]], "16105": ["预后", "脉散大无伦，散为气散不收，大为虚阳外浮，合面赤戴阳，乃误服香薷凉药、大汗亡阳之候。狂谵躁扰非实热，乃阳亡神乱，瞬息即脱。故辞不治，勉以真武汤易干姜、生附子冷饮回阳，服后神清热退。散大无伦正是亡阳危候之脉，与戴阳、大汗相应，示预后凶险。", ["散", "大"]], "16106": ["病机", "初脉细紧近疾，细为阳虚，紧为寒，疾为邪正相争，证见发热头痛、胁痛牵引、干呕胸胀，作厥阴病温经而痛减。后因重裘逼汗大出，脉变数大无伦、重取近散，数大为虚阳外越，近散为气随汗脱，此汗多亡阳之机，与烦躁不寐、胸中大热、欲饮冷水相应，急宜回阳固脱。", ["细", "紧", "疾", "数"]], "16107": ["病机", "脉沉弦而紧，沉主里，弦主厥阴，紧主寒，足冷畏寒、胁肋皆痛、舌紫微喘，皆厥阴寒盛、厥气上逆之象。原文特言无少阳寒热头眩、口苦干呕、脉弦数等证，故不得作少阳治。沉弦紧正说明寒邪在里、厥气上逆，与不得卧而喘相应，温经下厥气则愈。", ["沉", "弦", "紧", "数"]], "16108": ["病机", "脉沉细紧，沉细为阳虚，紧为寒，外反发热头疼，是阳证阴脉，故以脉为主作厥阴病温经。后腹痛下黑血数碗、眩晕汗出，脉仍细小未因脱血散乱，说明桂附温经预固阳气，气未随血脱。沉细紧示寒搏于里、厥阴不回阳，恐转少阴下利，与腹隐痛、不饥相应。", ["沉", "细", "紧"]], "16109": ["病机", "初脉浮大重按无力，浮大为虚阳外浮，重按无力为里虚，合面赤、肠鸣欲便，知为夹阴伤寒。病复作后脉细沉紧，细紧为寒，沉为在里，断非胃热，乃肾藏寒邪、逼真气上出于口，故口中臭气逼人、吐痰亦臭，是亢害之证。脉由浮大转细沉紧，示寒邪复传少阴。", ["浮", "大", "细", "紧"]], "16110": ["病机", "原文未识脉名，然两尺脉全无，呕呃不已、手足厥冷、气塞喉中、耳聋神昏下利，皆少阴阳衰、阴寒内盛之候。尺脉全无示肾阳欲绝，故用生附子、干姜、吴萸重剂回阳。后忽索雀食，是真阳飞越、将亡阳之兆，随即大笑不止，与脉绝阳亡相应，属危候。", []], "16111": ["病机", "脉濡细带紧，濡细为太阴湿困、阳气不足，紧为寒，证见胸腹不宽、大便日行而无表证，故断为寒中太阴，宜温中断食。后脉变弦紧，弦紧为寒入厥阴，果呕哕腹痛、身热下利，是太阴病不解而传厥阴。脉由濡细转弦紧，正示寒邪由太阴深入厥阴之机。", ["濡", "细", "紧", "弦"]], "16112": ["病机", "初诊脉沉弦紧而无力，沉主里，弦紧主寒主痛，无力为阳虚，故断为厥阴伤寒，见手足微冷、寒而不热、少腹隐痛、腰腿冷疼。服温药后脉不沉而但弦紧，是里寒稍减而厥阴之邪未解，故少腹隐痛、下痢血水而增呕。后受冷劳复，脉反彰大，为正虚邪进、虚阳外浮之象，故身热腹痛、下利足冷、胸满作呕。", ["沉", "弦", "紧"]], "16113": ["病机", "脉沉细紧，沉主里，细为阳虚，紧主寒，合头疼身痛、微热恶寒、呕哕不纳药，知非太阳表证，乃厥阴表里齐病、阴寒上逆成格阳。前医因脉沉用姜附杂羌防，药不能下咽，正格拒之验。后用乌梅丸通格拒，呕止能下药，继以温里，两得微汗而表证除，惟骨寒痛未减，旋入少阴下利，皆阴寒内盛之征。", ["沉", "细", "紧"]], "16114": ["病机", "脉弦紧而细，弦主肝、紧主寒、细为阳虚，合左胁痛甚、两手清冷、面色纯青、咳则痛引头胁，断为寒中厥阴肝经，故用温经散寒而痛止。两汗后脉转细涩无力，细涩为阳亡血少，合少腹微痛、通夜不寐而不烦躁，是汗多亡阳、阴不摄阳，故仿误汗法用真武汤收阴摄阳。", ["弦", "紧", "细", "涩"]], "16115": ["病机", "脉细数俨似阴虚，然重按滑而有力，滑为食积、有力为实，合食塞胸中、药饮难下，知细乃食结中宫、脉道不利，非虚细；午后潮热为阳明内实，五更盗汗为湿热熏蒸。三证皆实非虚，故以泻心汤法泻胃中湿热，终以小承气两下而愈。若以脉细误认为虚，则失滑而有力之实据。", ["细", "数", "滑"]], "16116": ["病机", "脉大而数，按则无力，大数似阳盛，然无力为虚，合八日汗后不解、身微热、烦而不寐，断为虚阳伏阴、阳气外越，非阳明内实。脉大为病进，正虚邪陷之候，故用茯苓四逆汤温里收阳。世医见脉大面红、口中大臭，误作阳明内实而主凉下，恰与按之无力相悖，故服温药无疑。", ["大", "数"]], "16117": ["病机", "脉反细紧，细为阳虚、紧为寒，合寒战头疼、发热腰痛，属阳证阴脉。幸脉但细而不沉，犹有头痛身热，知邪尚在厥阴之表，故用当归四逆汤温里散寒，昼夜四剂得汗而解。后因饮酒茹荤、乘船远出，寒战发热、吐泻腹痛复作，仍用前剂得汗热退，皆厥阴表证反复、里阳未复之故。", ["细", "紧"]], "16118": ["病机", "初病脉沉细而紧，沉细为阳虚、紧主寒，合头眩身痛、呕哕、腹痛下利，知本质孱弱，邪即入少阴，故用姜附人参温里。里温利止后，疫气外彰，谵言狂妄、胸发赤斑、耳聋神昏，脉转弦数，弦数为邪由阴出阳、郁于少阳阳明之象，故为必须汗解之证，与初诊沉细紧迥异。", ["沉", "细", "紧", "弦"]], "16119": ["病机", "脉弦紧无常，寒则细、热即数，漫无专经，是邪气混合三焦、难分经络之象。初病巅顶微疼，故从厥阴论治，用解肌温里。五日病不减而增剧，中夜寒热不得汗、烦躁欲死，知非邪实无汗，乃正气虚不能作汗，故以人参生姜仿露姜饮法扶正助汗，服后颇安。", ["弦", "紧", "细", "数"]], "16120": ["病机", "初病脉弦紧，为寒邪直犯阴经，邪在表里之间；失治传至少阴，脉转沉紧而细，沉主里，紧主寒，细主虚，两足厥冷、舌紫苔白，皆少阴寒化之象。少阴肾开窍于二阴，故肛坠而痛。脉由弦紧转沉细，示寒邪深入肾之本位，非痈证也。", ["弦", "紧", "沉", "细"]], "16121": ["病机", "脉沉而紧，两尺如丝，沉紧主里寒，尺细如丝为少阴真阳不足。汗多热不退、烦躁欲席地、干呕欲饮冷水、舌紫无苔、少腹硬痛，皆阳证阴脉，属厥阴少阴同病。脉沉紧示寒邪内陷，两尺如丝示肾阳式微，故用温经回阳而脉起。", ["沉", "紧", "细"]], "16122": ["病机", "脉弦紧而细，皆阴脉也。弦紧主寒，细主虚，无长大之象，故口臭多饥非阳明；无腹满自利，非太阴。心悬如病饥、腐气上逆、清气下泄、舌紫便频，皆厥少二阴之病。脉细紧示邪从中发，时疫之势未彰，故用温里解肌，俾邪外出。", ["弦", "紧", "细"]], "16123": ["预后", "六脉散大，为汗多亡阳，气不敛摄；脉忽敛小如丝，是阳气暂敛而根本欲脱，旋即下脱，饮食倍常而大便频下，乃胃气将败。高年气血两虚，脉不起示生机难复。散大转为细丝，非病退，乃阳亡之危候，故预后不良。", ["散", "大", "细"]], "16124": ["主病", "脉浮而弦，浮主表，弦主暑邪郁于太阳。面垢齿燥口渴、小便频数，乃暑邪中于膀胱，膀胱失司出纳之权。脉弦为暑热内郁之象，非疟之寒热往来。此中暍证，暑伤气分，故用白虎加人参汤清暑益气，一剂而小便如常。", ["浮", "弦"]], "16125": ["病机", "脉细迟无力，重取欲绝，细为气血两虚，迟为阳气不足，无力欲绝乃胃气衰败。身热烦躁、舌干妄语、红疹，皆虚火外浮，非伤寒实热。唇口无血色、渴惟热饮、大便三日未通，乃腹馁胃虚，非阳明内实。斑为胃虚虚火游行于外，故急救胃气。", ["细", "迟"]], "16126": ["病机", "脉弦长有力，弦主风，长主阳热有余，有力为实。风暑中于阳明，多气多血之府，血为热郁而成斑。卧则气下色赤，坐则气上色紫，乃热郁血分、气机升降使然。此风暑瘾疹，非温热病发斑，故仿伤寒辛凉解散，使邪从外解。", ["弦", "长"]], "16127": ["病机", "脉散大而数，散大为阳气浮越不敛，数为虚阳外越。霍乱吐泻汗出，亡阳于外，故面赤戴阳、烦躁乱走、欲食冷水。散大数脉示阳气欲脱，急以大顺散、参附姜草回阳救逆，服后脉始收小，乃阳回之兆，否则一寒战即脱。", ["散", "大", "数"]], "16128": ["病机", "脉细如丝为气血两虚之象，兼数则虚中有热，暑邪内伏。患者素有经水似崩，气血本虚，暑月劳而中暑，汗出如浴更伤气阴。前医误作中寒，投姜附温燥，致暑热内炽，虚烦畏热、怔忡不寐、频餐似中消。脉虽虚细而数，至止调匀，说明虚而未至脱绝，暑热内伏膈间，故断为中暑之膈消，非亡阳急脱。", ["细", "数"]], "16129": ["预后", "脉细如丝，尚不及三至，是气血大虚、脉道不充之候。患者素失血咳嗽，夏月过劳伤暑，又误作伤寒中热，绝食五日，胃气空虚，致大喘大汗，脉证欲脱。然未厥冷，气从心下起，说明宗气未离原，胃中空虚而致喘汗，非真元脱绝。故急以粥食救胃，糜饭留胃，汗止喘定，脉细为虚象而非死脉，预后可治。", ["细"]], "16130": ["病机", "脉浮弦有力，浮主表，弦主风主痛，有力为实。盛暑在船，大吐泻后头汗如雨、水泻不禁、周身抽搐麻木，证类转筋。脉不虚软而浮弦有力，且头汗身热，断非虚寒，乃暑风外袭、热邪内迫之证。经云“暴注下迫，皆属于热”，暑热夹风，故脉浮弦有力，治以香薷、葛根等解表清暑，得汗热退痢止。", ["浮", "弦"]], "16131": ["病机", "脉细紧无伦，细为阳衰，紧主寒主痛。夏月恣食瓜果，伏暑霍乱，泻止而呕吐不止，他医误以紧数为热，欲用黄连。然紧寒数热，相去天渊，此乃中寒厥逆于上，阴阳格拒，药不能下。脉细紧无伦正是寒邪内盛、阳气被遏之象，失之不温则发呃烦躁厥冷，故先以米复丹开格拒，继用四逆汤温里，冷饮以顺格拒之势。", ["细", "紧"]], "16132": ["病机", "初诊脉得弦数，弦主疟邪在半表半里，数主热。酷暑乘马、恣食瓜果，寒热身痛，疟证确然。次日犯房事，里虚不能作汗，热不退，更医误下，气脱大汗遗尿，脉转细如丝，是阳气骤脱、气血大虚之候。细如丝为虚脱之象，非外邪未尽，故以附子理中汤回阳，里气得温，邪方外出，间日疟仍发，左胁胀痛咳嗽，乃疟痰未清、正气未复。", ["弦", "数", "细"]], "16133": ["病机", "脉尚浮弦有力，浮弦为疟邪在半表半里，有力示邪实未解。截药乱投，疟邪不得外解，内搏作痢，故疟痢并作。后大劳中气下陷，脉转虚大，有汗不热，是气虚下陷之候，用补中益气汤而愈。再延则脉弦滑而数，弦滑为痰，数为热，乃前疟痰未清、不药留病、劳而伤气，虚回痰作，故神昏谵语。脉象由实转虚、由虚转痰热，反映邪正进退。", ["浮", "弦", "虚", "大"]], "16134": ["病机", "脉单弦而硬，弦主疟主痛，硬为脉失柔和，示邪结深痼、元气大伤。患者年逾五十，疟久不愈，补泻温凉杂投，元气大虚，竟无汗解，身目皆黄，发时两足筋抽，上冲于腹，腹胀如鼓，脐旁动气。弦硬之脉说明疟邪深伏、肝木乘脾、气机壅塞，正虚邪实，故耆术下咽即胀痛，诸医束手，病势危笃。", ["弦", "硬"]], "16135": ["病机", "脉弦而紧，弦主少阳疟邪，紧主寒主表。患疟四十日，前医补截兼行，愈治愈甚，而不发时仍恶寒身痛，说明表邪未解，半入于里，似疟而非真疟。脉弦紧为邪在表里之间、寒邪束表之象，里气不虚，故不可补。治以羌活、桂枝、柴胡等表里两解，四剂得汗寒退，又四剂热退，六日寒热尽而似疟止，脉证相应。", ["弦", "紧"]], "16136": ["病机", "脉细紧如丝，细为阳衰，紧为寒盛，合之乃寒极于下、厥气上逆之象。两足冰冷、虽疟热而足不热，正是阴寒内盛、格阳于上之征；胸中塞满、呕哕不息、昼夜俯坐不能平卧，皆寒痰中阻、胃气上逆所致。此非寻常疟疾，乃寒疟危候，故辞不治。", ["细", "紧"]], "16137": ["病机", "脉弦而迟，弦主疟、迟主寒，乃阴寒脾疟之脉；后脉变虚数，因疟止而阴气稍伤，虚数非热盛，乃阴虚不敛。原文明言“若系中寒虚冷，脉必沉迟”，反衬此虚数属阴虚，故用地黄即退。脉象前后变化揭示病机由寒转虚。", ["弦", "迟", "虚", "数"]], "16138": ["预后", "六脉全无、手足厥冷、目合不语、牙关半开半闭，乃证脉全脱、阳气欲绝之危候。身体不僵、未全冷，说明生机尚存一线。原文以“药能下咽，方可救也”判断预后，后脉出如丝示阳气渐回，故属预后判断，非单纯主病。", []], "16139": ["病机", "脉弦细而紧，弦为厥阴之脉，细为阴血不足，紧为寒邪内束。寒多热少、巅顶痛、腰背疼、汗出不止，皆厥阴经脉受寒、阳气不布之象；疟发则小便不禁，乃寒伤下焦、膀胱失约。故断为厥阴疟，非三阳证，用温里解肌而效。", ["弦", "细", "紧"]], "16140": ["病机", "初诊脉浮弦而数，浮为风热在表，弦为疟邪，数为热盛，故见身痛、寒极而热、渴甚汗多、小便痛难，属风热未解，用阳旦汤两解。后复发脉细数无伦，细为阴伤，数无伦为邪热内陷、神扰，故谵妄若狂、渴饮不休，病机已变。", ["浮", "弦", "数", "细"]], "16141": ["病机", "脉沉弦而紧，重按滑而硬，沉主里，弦紧主寒，滑硬为寒痰胶结。平素多痰胃冷，又餐水果，更服芩知寒药，致疟邪全入于里，寒痰格拒，故呕逆滴水难下、舌苔全黑。此寒痰坚垒之病机，非寻常药可破，故用半硫丸温通。", ["沉", "弦", "紧", "滑"]], "16142": ["病机", "脉弦细数而无力，弦为疟邪未净，细为阴血亏少，数为虚热，无力为气阴两伤。梦遗不禁、胁肋气冲而痛、脐有动气、半身不能侧卧、腰膝酸疼、咳嗽盗汗、阴毛变白，皆肝肾两虚、真阴大损之候。故主补阴俾邪自解，仿建中法。", ["弦", "细", "数", "虚"]], "16143": ["病机", "脉弦细紧而搏手，按之无力，弦细紧为厥阴伤寒、表里皆寒之象，搏手无力示寒邪束表而正气不足。胁肋连腰痛甚、微热微寒、头疼咳嗽，邪犹未全入里。后紧退转弦细，更兼涩，涩为寒凝血脉、阳气不充，故胁痛不能侧卧、咳嗽不除，疟疾日发。", ["弦", "细", "紧", "涩"]], "16144": ["病机", "脉弦紧无伦，弦为厥阴之象，紧主寒凝。疟邪因截疟毒丸与香薷误治，阴寒内凝，邪陷厥阴，故脉弦紧失序。手足厥冷、腹肋隐痛、下痢红水，皆寒凝厥阴、阳气不达之候，故断为厥阴经疟，急宜温里使邪外发。", ["弦", "紧"]], "16145": ["病机", "脉浮而数，浮主表邪，数主热，合恶寒发热、头疼身痛、目赤口干，为疫毒痢表里皆病之象。先解表后攻里，汗出表热里痢减半；浮脉虽平而虚数不敛，示高年气虚未复，故加人参扶正，邪从外解。", ["浮", "数"]], "16146": ["病机", "六脉虽大而尚有力，继则更大而无力，大而不数、重取无力，是老人脉大为虚，中气虚寒逼阳外浮，非热也。小便秘、大便不禁为元气下脱，故主升阳温肾，用参附桂姜，不可因痢忌洪大而误作实热。", ["大"]], "16147": ["病机", "脉细数而重按则长，细为热郁于里，数为邪热，长则实象。干呕烦热、手足时冷、齿燥舌黄、食西瓜随即利下色不变，是热厥而非胃寒，邪热不杀谷、传化失常，暴注下迫皆属于热，故用大黄黄连下之。", ["细", "数"]], "16148": ["病机", "脉则细数身热，细为阴虚，数为热，合面白唇红、下痢纯红、愈便愈坠、左肋气冲而痛，是素属阴虚、巴豆大黄寒热乱投、下多亡阴之候。季肋属肾，痢亦肾病，故补阴为本、治痢为标，药后脉数唇红稍退。", ["细", "数"]], "16149": ["病机", "两尺全伏，舌苔灰黑，哕声近呃，足冷至膝，畏见日光，脉证皆大虚寒。尺伏为肾阳衰微、阴寒内盛，阳气不能布达，故寒痢日久转变虚寒，确当温补，用参附姜桂，服后足温呃止而痢减。", ["伏"]], "16150": ["病机", "脉弦而无力，两尺细紧，弦为肝象，无力为虚，尺细紧主肾气虚寒。腹不痛而腰下坠即脓血，大小便一齐并出，小便不能单行，是肾气不固、泻利前后之五虚证，非痢也，故主补气，以小便能单出为效。", ["弦", "细", "紧"]], "16151": ["病机", "脉弦细紧，弦属厥阴，细紧为寒，然反不恶寒而微发热、头疼身痛，是寒凝于内逼阳于外，不可以细紧为寒、头痛发热为湿热两相疑。必以脉为准，定属厥阴病，肝藏血，故用当归四逆加附子干姜吴萸，解肌温里使邪外解。", ["弦", "细", "紧"]], "16152": ["病机", "脉双弦紧硬，两尺尤甚，紧硬为寒凝收引之象，弦主痛、主肾。原文谓“肾藏虚寒之痢无疑”，因平素中寒，又食苦蔗菜、石膏豆腐等寒凉，致肾阳虚衰，寒凝气滞，故脉紧硬而腹不痛，脐旁动气，下痢无度，小便难通，皆肾虚寒凝、气化不行之候。", ["弦", "紧", "硬"]], "16153": ["病机", "脉虚大而参伍不调，两寸十数至一歇，乃心肾气虚、脉行无力之象。虚大为气衰，歇至为心掣肾病，故断为“心肾气虚，并无风邪六经形证”。后颈脉大动、尿如煤水，是肾藏真阳不足，水气上泛，将成水蛊，皆本于虚大不调之脉。", ["虚", "大", "动"]], "16154": ["病机", "脉弦而沉紧，弦主风，沉紧主寒，此“夙昔之风，加以雪天新中于寒，两邪并发”，风寒外束，故昏仆拘挛冷痛。服温里解表后脉略浮弦，是邪气外出之机，仍余风邪，故增咳嗽，续进麻黄、杏仁得汗而解。", ["弦", "沉", "紧", "浮"]], "16155": ["病机", "脉弦滑有力，弦主风、主痰，滑主痰湿内盛，有力为实。原文谓“此痰中也”，因善饮多劳，痰湿内蕴，随风上扰，故发晕、呕痰、手足不举、言语蹇涩。脉无虚象，故用六君子汤去人参，加胆星、天麻、竹沥等化痰熄风。", ["弦", "滑"]], "16156": ["病机", "六脉皆沉弦，沉主气郁，弦主气逆，歇至来去不乱为气机一时壅塞，非脏气衰败。原文辨“此中气也”，因酒后愤争，气逆上壅，故昏仆不语、手足厥冷，而喉无痰声、口眼端正、呼吸调匀，与中风身湿不同，故用顺气散加香、沉开郁降气而苏。", ["沉", "弦"]], "16157": ["病机", "脉虚大无伦，虚为阳气衰微，大为气浮外越，此“汗多亡阳而暴脱”之象。因老年贪浴，汗出过多，阳气骤虚，故昏睡不语、身重遗尿，而肢不偏废、口不歪斜、喉无痰声，原非中风。误用疏导，阳气愈虚，竟成脱证，急用归脾、八味温补固脱。", ["虚", "大"]], "16158": ["病机", "两手脉或大或小、或迟或数，全无一定，脉无定体，主神气混乱、邪祟干扰。原文谓“此中恶也”，因登楼见异，惊恐气乱，神不守舍，故昏仆、默默不语、避人面壁。脉象乍大乍小、乍迟乍数，正是神志失主、气机逆乱之候，故用灸鬼法。", ["大", "小", "迟", "数"]], "16159": ["病机", "两手脉相同，至止不乱，但虚大无力，虚为血虚气弱，大为气浮。原文谓“脱血心虚”，因经水半月未止，血脱气弱，又夜看城隍会，见鬼形心怖神乱，故昏仆、妄言、昏睡。脉至止不乱，非中恶之脉，乃血虚神怯之候，邪之所凑，其气必虚。", ["虚", "大"]], "16160": ["主病", "脉沉主里，此老年气弱，被严寒所迫，寒中于里，阳气不能外达，故昏厥、手足僵直厥冷、牙关咬紧、面青。脉沉与寒邪内中、阳气郁闭相应，非表证之浮，亦非虚脱之微，乃寒实内闭之象，故用四逆汤温里回阳。", ["沉"]], "16161": ["病机", "脉弦数而涩，弦主肝郁，数主火，涩为血少气滞。新丧悲郁，木郁化火，肝火暴甚，故卒倒无知、手抽掣、面赤。火郁于内，血行不畅故涩。独主火中，非风痰虚，以脉弦数不浮不滑，故用滋肝清火而愈。", ["弦", "数", "涩"]], "16162": ["主病", "六脉细濡无力，细为血少，濡为气虚，无力为元气大虚。酒后昏仆、手足不举、尿不禁、汗出、小便频下，皆元气大虚、类中风脱证之候。脉与症合，故急行温补，非风痰实邪，若误攻则亡阳。", ["细", "濡", "虚"]], "16163": ["病机", "两关沉滑有力，沉主里，滑主食积痰滞。饱食后久浴伤气，胃中食满，气虚不能运转，食滞中焦，故昏晕不语。脉沉滑有力，非风非痰非寒非虚，乃食中实证，故探吐而愈。", ["沉", "滑"]], "16164": ["病机", "初诊脉浮弦而细，浮为风，弦为暑热伤气，细为气虚。盛暑身疼发热呕吐，暑风证也。后脉不浮但弦细，神昏僵卧，乃气虚伤暑而卒中，面垢遗尿属暑病，非脱证。脉细为气虚，弦为暑热，故用消暑丸温胃涤痰。", ["浮", "弦", "细"]], "16165": ["病机", "脉虚大而数，重按豁然，虚大为气虚阳浮，数为虚热。暴怒伤阴，恐伤肾，肾水不升，心阳不降，魂不归肝，气不归肾，阳跷盛而阴虚，故昼夜不寐。脉虚大不敛，非实火，乃肝肾两病、阴阳不交之候。", ["虚", "大", "数"]], "16166": ["主病", "脉洪大无伦，重取即散，洪大为真阳外越，散为里气虚寒。暴寒所伤，寒霍乱吐泻大汗，里气虚寒，真阳外越，故面赤戴阳、腹胀如石、胁痛。脉洪散非实热，乃阴寒内盛、虚阳上浮之危候，破气劫药误治。", ["洪", "大", "散"]], "16167": ["病机", "两手脉大而数，重取全无神力，大数为虚火，无力为气虚。书写过劳伤血，秋燥咳嗽火逆，前医苦寒直折，火愈上逆，吐白血、头面赤汗多。脉大无力，劳则彰，气虚也，虚阳上泛，非阴虚火，故宜补气退火。", ["大", "数"]], "16168": ["病机", "脉大而芤，大示邪盛或虚阳外浮，芤主失血伤阴。患者大吐紫血、便紫黑血，阴血暴伤，脉道不充故芤；气血尚能外达故大。幸脉不散，说明元气未至涣散，但已显畜血成瘀、肝脾不藏不裹之机，故断为畜血证而非单纯阴虚。", ["大", "芤"]], "16169": ["病机", "脉沉而紧，沉主里、紧主寒，为太阴脾脏阴黄之候。原文言“本中寒，误作湿热”，寒湿困阻脾阳，故面目黄而黯、胸腹饱胀、腹痛便溏。紧脉不退、沉不起，说明寒邪深痼，非温不能化，故加附子易干姜而黄退腹消。", ["沉", "紧"]], "16170": ["病机", "脉细濡如绵、惟有三至，细涩不堪，为气血两亏、津枯髓减之象。疝坠囊中全不知痛，羸瘦色枯，元气下陷，虚寒极矣。细涩示营血不充、脉道不利，故温肾升阳得效；后脉细涩不堪，更确指气血亏耗、肝肾虚竭。", ["细", "涩"]], "16171": ["病机", "脉浮而濡，浮为卫虚外浮，濡为营弱不充。劳汗出而卫虚，梦遗而营弱，营卫俱虚，肌肤失养，故见四肢清冷、面惨、肌肤似麻似痒、不胜衣而肉苛。脉浮濡正合营卫两伤、皮腠不荣之机，故用黄芪建中汤加味而愈。", ["浮", "濡"]], "16172": ["病机", "脉初诊则细，重按反滑而有力。细为寒中阳郁，滑而有力为郁久化热、实结于内。原文谓“初因寒中，积之既久，郁而成热”，故姜桂反增痛，皮外虽冷而阳郁于内。脉象由细转滑，正示寒郁化热、结聚胸脘之病机。", ["细", "滑"]], "16173": ["病机", "脉弦细而数，尺寸皆涩。弦主肝郁，细为阴血不足，数为郁热，涩示血行不畅。原文言“脉不长滑，非痰非狂”，排除痰火狂乱，而见言语无伦、举止失常，乃肝郁血虚、神志失养之候，非实痰壅盛。", ["弦", "细", "数", "涩"]], "16174": ["病机", "脉浮数无伦，浮为邪在肌表，数为热盛。患者遍身红肿痒甚、滚擦不休，因食觝鱼中毒，风热毒邪外搏肌肤，故脉浮数而甚。原文疑“食觝鱼”中鱼毒，脉数甚示毒热充斥，与刺风证相似而更剧，故急用甘蔗汁等解之。", ["浮", "数"]], "16175": ["病机", "脉细数无力，细为阴血亏少，数为虚火内动，无力示真元不足。患者狎妓酣饮，真阴亏耗，津枯血少，火郁为结核，上则咳嗽，下则胯膝结肿不痛。原文断为“真阴虚竭，津枯血少，为火结核”，脉象正合阴亏火旺之机。", ["细", "数"]], "16176": ["病机", "两寸涩而数，涩主血瘀气滞，数主热，肺痈将溃，热毒壅肺，气血瘀阻，故脉涩数。胸背胀痛、咳不能卧、寒热、口出腥臭腐气，皆痈脓内溃之征。此非真寒，乃内痈作脓之寒，故畏寒虽甚而脉不迟紧。", ["涩", "数"]], "16177": ["病机", "脉细而数，两尺尤甚，细为阴精亏少，数为虚热内扰，尺部应肾，故主伤精失血。患者多饮茶汤、尿有浮脂浑浊、两足无力，乃精随溺出，下消将成痿躄。此阴虚火动之脉，非实热，故以六味补益取效。", ["细", "数"]], "16178": ["病机", "脉长而数，长为有余，数主热，痧后咳泻两月，前医误用温涩，致余热归肺胃。长数之脉示胃热未清，邪热不杀谷而洞泻。泻乃分消热毒之路，故不可止涩，清热则泻自止。此脉主胃热，非脾虚也。", ["长", "数"]], "16179": ["病机", "脉细濡微数，濡主湿，细主虚，数主热，合为气虚伤湿热。两足痿痹、肿痛、头微晕，乃湿着下体。脉不浮弦非风，不紧痛不甚非寒，故知非外邪。形盛气虚多痰火，治痿独取阳明，补脾燥湿，切中病机。", ["细", "濡", "数"]], "16180": ["病机", "脉细数无伦，细为阴亏，数为虚热，无伦者脉律不整，阴竭阳浮之象。初病阳脱，参附回阳，今阳回而阴竭，故心慌眩晕、多餐不寐，皆阴虚脉证。此脉主阴竭，非阳脱，故附子不宜，当阴阳平补。", ["细", "数"]], "16181": ["病机", "脉细涩无力，两尺尤甚，细主精亏，涩主血滞，无力为虚，尺甚应肾。便浊经年，久通伤精，故内痛连肛及尿管。此肾虚精亏、络脉涩滞之脉，非湿热实邪，故误用通利则痛剧，治当补肾填精。", ["细", "涩"]], "16182": ["病机", "脉沉弦细紧，沉主里，弦主痛，细主虚，紧主寒。初作厥阴中寒不效，详审沉细而紧为少阴脉，肾主二便，故小便频、肛门下迫。此少阴寒化、阳虚不运之脉，非厥阴，故用四逆加人参汤温阳而效。", ["沉", "弦", "细", "紧"]], "16183": ["病机", "脉亦细数，细为阴伤，数为虚热。久服姜附辛热，伤阴动血，故吐血；阴亏肺燥，渐增咳嗽、胁肋隐痛、喘咳不能卧。此辛热伤阴之脉，非真阴虚损，故暂用甘寒养阴，不可苦寒直折。", ["细", "数"]], "16184": ["病机", "脉大而面赤汗出如水，乃虚阳上泛之象。患者素体脾肾阳虚，痰饮内伏，寒邪外袭，致胸胁大痛、呕吐痰涎。脉大非实热，乃阳气虚浮于外，故用干姜、附子、人参等温阳化痰，后下紫黑血乃寒凝血瘀，瘀去痛减。", ["大"]], "16185": ["病机", "脉虚细无神，一派阳气虚弱之证；后脉虚大而尺数，虚大乃阳气外浮，尺数乃阴精亏虚、虚火内动。患者神思疲倦、畏寒、梦遗，皆由阳虚及阴，阴不敛阳，龙雷之火不藏，故脉数大而无力。", ["虚", "细", "数", "大"]], "16186": ["病机", "脉细紧，手足清冷，胸结而硬，舌紫苔白，乃冷食积中、寒凝气滞之象。细为阳衰，紧主寒痛，过用消克伤胃阳，食愈结而不化，故脉见细紧，治当温中化滞，用苍术、半夏、干姜、附子等。", ["细", "紧"]], "16187": ["病机", "脉细数，两尺尤甚，细为阴精亏虚，数为虚火内动。患者素有眩证昏仆，梦遗频作，乃阴精竭于下，阳火逆于上，龙雷之火一发即隐，即《内经》所谓煎厥。脉细数两尺甚，正合下焦阴虚火旺之机。", ["细", "数"]], "16188": ["病机", "脉弦而紧，头痛如破，身体僵直，烦躁面赤，口流脓血，乃破伤风之候。弦主肝风，紧主寒痛，风毒内袭，肝经拘急，故脉弦紧。前医误作火头痛治，用石膏、芩连，反伤阳气，此幸未柔汗厥冷，尚可温经散寒。", ["弦", "紧"]], "16189": ["病机", "左右脉皆沉弦细紧，沉细为阳虚，弦紧主寒主痛。跌伤后洗浴伤风，误行解表，致风寒内入，直伤肝经，破风反张，手足拘挛，角弓反张。脉沉弦细紧，正合寒邪深入、肝经拘急之病机，故用桂枝、附子、细辛等温经散寒。", ["沉", "弦", "细", "紧"]], "16190": ["病机", "脉弦紧，面赤舌紫，手冷多汗，乃肝经风病。患者足疮刀伤，为风寒所袭，又敷冷膏，致风寒内侵，证类破伤风。弦主肝风，紧主寒邪，风寒搏结肝经，故脉弦紧，治当急温，用桂枝、附子、细辛等以散寒祛风。", ["弦", "紧"]], "16191": ["病机", "脉已六至，细疾无伦，细为阳衰，疾数为虚阳外越。患者素有中寒痰饮，暑月头痛误作火治，投寒凉而痛甚，致阴盛格阳，身冷多汗，阴躁卧地。脉细疾无伦，乃阳气欲脱之危候，急进四逆汤温阳回阳。", ["细", "疾", "数"]], "16192": ["病机", "本案未载脉象，以意度之，断为肝火。因郁怒伤阴，继服香燥耗血，致火上逆则呕吐，下迫则后重欲便。症见胸腹不宽、两肋胀痛、食不能过膈、大便秘结、黄昏后重、空坐秽桶，皆肝火上下冲逆、阴血亏耗之象，故非清痰理气所能治。", []], "16193": ["病机", "六脉皆伏，推筋著骨皆无，乃吐甚伤气，气机一时闭塞，脉道不行而伏。然声高音朗、坐起如常、无厥逆汗出，知非脱绝，故断为吐伤气致脉全伏，主温里。后脉出如丝，渐至全见，证明伏为气闭而非真绝，每痛吐脉必伏，亦气逆壅塞之征。", ["伏"]], "16194": ["病机", "脉细如丝，两尺全无，为肾水泛溢、阳气衰微之候。孕妇水势泛溢，腹大如鼓而面反瘦，咳喘不能卧，两足水肿，皆肾阳虚不能化水，水气上逆射肺、外溢肌肤所致。两尺无脉，胎已息矣，故急以金匮肾气汤温阳利水，以全孕妇。", ["细"]], "16195": ["病机", "脉虚大而濡，便血未止，胃弱不食，面时火起，此气随血下而虚也。卫气行阳则寤，行阴则寐，气虚行于阴而不能周于阳，故合目则身麻、不敢合目而不寐。虚大为气浮于外，濡为气虚不敛，正合东垣补气升阳和中汤证，主中气下陷、血失统摄。", ["虚", "大", "濡"]], "16196": ["病机", "脉虚大如绵而不数，烦躁不得卧已六日，面赤如妆，舌苔灰黑而滑，喜热饮止一口，此虚阳外越也。本于劳倦内伤兼风暑，初医误用姜附，继医妄投苦寒，虚作实医，逼阳外越，俨如热病。脉虚大为正气不足、阳浮于外，不数为无实热，故合当归补血汤证。", ["虚", "大"]], "16197": ["病机", "两关虚大无力，食物便呕，呕止即腹痛，痛则下泻，满口白疮如米粒，此脾虚寒也。脾土虚则肾水乘之，逼心火上逆，致口舌生疮，乃上焦假热、中焦真寒。关脉虚大无力，正脾土虚而水乘火逆之象，故用附子理中汤冷饮，温中而暗度上焦假热。", ["虚", "大"]], "16198": ["病机", "两手脉沉细欲脱，耳聋神昏，唇焦舌黄，身微热，口苦干呕，身痛僵卧，夜谵语，此邪错杂，足三阳经皆病。沉细欲脱为正气大虚、邪陷于里，下后愈甚，知误下伤正。身痛僵卧太阳，夜谵语阳明，耳聋干呕少阳，脉沉细欲脱则阳衰欲脱，故先以三阳经药投之，观其应否。", ["沉", "细"]], "16199": ["病机", "脉细数，颈核渐大内逼咽喉，发热咳嗽，喘不能卧，汗出泄泻，阳气下脱。先结核乃肝木郁久化火，误用黄耆助肝火，火灼肺金而大喘。细为阴血亏虚，数为郁火内炽，火灼肺金则喘，阳气下脱则汗泄，故脉细数主肝火灼肺、阴伤阳脱之机。", ["细", "数"]], "16200": ["病机", "脉浮细如羹上之浮脂，指点便散，是阳气浮越于外、不能内守之象。素有饮证，过用生半夏、生附子、生姜汁耗气亡阳，致真阳外越，故脉浮细无根而散；阳越于上则巅顶双目光荡漾，卫外不固则遍身汗出、昏眩不知所在。此非寻常饮邪，乃阳气欲脱之危候，故急用附子汤温阳固脱。", ["浮", "细"]], "16201": ["病机", "脉细数而弦，因怒未伸、肝气上逆，血郁于上而吐紫血，胁肋胀痛、胃中硬满，皆肝逆血郁之征。高年血液枯衰，误用辛温宣气，津液愈耗，火结于上，故脉变细涩不堪，胸阻塞不开、食饮难下，有膈噎之虑。细涩示血枯津少，非辛燥所宜，故以甘润汁膏频咽。", ["细", "数", "弦", "涩"]], "16202": ["病机", "脉沉而紧，沉主里、紧主寒，手足清冷、胸腹胀大，皆里寒之象。暑月贪凉食冷，本质虚弱，气被暑伤，中宫益冷，不能健运，阳络结而血上溢，故暴吐紫血。此非阴虚血热，乃中宫寒冷、血不归经，急宜温里；若误作阴虚凉血，则寒凝益甚，指日成蛊。", ["沉", "紧"]], "16203": ["病机", "脉细濡不任寻按，有时忽大，是脾胃虚衰、气血不足之象，非真阴虚损。思虑伤心，脾虚不裹血，故吐血涎血、经水大行似崩；胃虚则血出上窍。细濡无力正合中宫虚寒，故以温补中宫、和营血取效，重用人参而血止胀减。", ["细", "濡"]], "16204": ["病机", "脉沉细紧，沉主里、紧主寒，表里皆寒之征。恣食生冷，形寒饮冷伤肺，前医不解表而清滋，致寒不解、咳甚吐血，更发寒战、手足厥冷、身痛腰疼、咳吐冷水。此非阴虚吐血，乃肺受寒邪、表里俱寒，正合小青龙加附子证，温散则手足回温、冷汗出而咳止。", ["沉", "细", "紧"]], "16205": ["病机", "脉弦而紧，弦主肝、紧主寒痛。产后冲任脉虚，寒气内袭，积瘀凝结，结于少腹如弹丸，发则长大如王瓜，痛冲于心、呕吐不食，自下而厥于上，此厥阴肝病之疝瘕。弦紧示寒凝气结、瘀阻肝经，故用桂附温经、柴胡川楝乌药疏肝散结而效。", ["弦", "紧"]], "16206": ["病机", "脉沉弦而紧，沉主里、弦主肝、紧主寒。左肋素有气积，孕后冲心而痛、昏厥、手足逆冷、口出冷气，是肝经积冷、结为冲疝，寒气自下上逆。沉弦紧正合寒凝肝脉之实，故非桂附莫效；投当归四逆汤温经散寒，应手取效而胎不伤。", ["沉", "弦", "紧"]], "16207": ["病机", "脉细涩无神，是脾胃败伤、气血交虚之象。疟后气血交虚，误服干姜、丁、沉、吴萸等燥剂，致呕酸腹胀、面目浮肿、形骸骨立、经绝不行。细涩无神示中气衰败而非真阴耗竭；后虽似阴虚劳病，然脉不细数，真阴未伤，故以六君子平补气血取效。", ["细", "涩"]], "16208": ["病机", "脉细缓，细为阴血不足，缓为脾虚有湿。患者素脾虚作泻，因悲恸经闭，腹中有形，发热咳嗽，腹胀作泻，虚劳证全。脉不涩不数，说明真阴未伤，病机重点在脾虚，血源不足，故经闭、腹中结块。脉缓主脾虚，细主血少，与脾虚作泻、经闭相应，尚属可治。", ["细", "缓"]], "16209": ["病机", "脉三部皆涩，涩主气滞血瘀，亦主痰湿内阻。患者咳嗽、寒热汗出、鼻流清涕、痰涎甚多，右身不能著席，脉不浮弦非风，不细紧非寒，不滑数非火，涩脉提示肺络瘀阻，痰瘀互结，酿成肺痈。痰腥甜为痈溃之征，涩脉与肺痈将溃病机相符。", ["涩"]], "16210": ["病机", "脉浮大而数，浮主表邪未散，大主热盛，数主热。患者伤风未解，寒热互作，咳喘不能卧，项强不能转侧，脉浮大而数，说明外风未散，郁而化热，热毒壅肺，肺痈将溃。浮为风邪在表，大数为热毒炽盛，与咳喘、寒热、项强相应，故主肺痈。", ["浮", "大", "数"]], "16211": ["病机", "脉细紧，两尺犹甚，细主阴血不足，紧主寒主痛。便血久不止，气随血脱，肺脾肾三经皆虚，细紧为虚寒内结之象。颈脉大动，咳而兼喘，为水气上逆，将成水肿。脉细紧与便血久、脾肾虚寒相应，说明阴络结而血下溢，虚寒为本。", ["细", "紧"]], "16212": ["病机", "脉濡溺如绵，濡主湿主虚，如绵为虚软无力之象。患者怀孕六月便血三月，爪甲全无血色，两足虚肿，食后腹痛泻去，脉证合参，为脾土大伤，统血无权，气血亏虚。濡脉与脾虚湿盛、便血、虚肿相应，故主脾虚不摄，急当补脾。", ["濡"]], "16213": ["病机", "脉弦细紧，弦主肝病，细主血虚，紧主寒。患者便血后过用苦寒，血去肝虚，苦寒伤肝，致手足拘挛、项背强痛、两胁结块，脉弦细紧为肝经虚冷、寒凝筋脉之象。弦应肝，细紧为虚寒，与拘挛、强痛、结块相应，故主肝虚冷。", ["弦", "细", "紧"]], "16214": ["病机", "脉浮细而紧，浮主表邪，细主正虚，紧主寒。患者产后感寒，咳嗽恶寒，呕吐痰水，又经水大行，前医误补，致表邪不解，里冷益深，恶寒发热，咳喘不能卧，腹胀作泻，遍身麻木。浮细紧为风寒积冷、表里皆邪之象，与咳喘、寒热、身痛相应，故主外寒内饮。", ["浮", "细", "紧"]], "16215": ["病机", "脉至骨，微细如丝，似有如无，微细主阳气衰微，阴寒内盛。患者形盛多痰，素有头风呕吐，感寒后周身浮肿，咳喘不能卧，呕吐不能食，足冷过膝，沉寒痼冷，证皆危笃。脉微细如丝为阳气欲绝、寒水泛滥之象，与浮肿、咳喘、足冷相应，故主沉寒痼冷。", ["微", "细"]], "16216": ["病机", "六脉沉紧而滑，沉主里，紧主寒，滑主痰，合为寒痰满中之象。原文谓\"寒痰满中，非辛热不醒\"，故昏卧不知人事、手足微温、身体软重，皆寒痰蒙蔽清阳、阳气不达所致。脉未回则寒邪犹在，温补反助其邪，遂致呕哕不息，正合紧滑未化之机。", ["沉", "紧", "滑"]], "16217": ["病机", "脉细紧而滑，细为虚，紧为寒，滑为痰饮。原文断为\"脾胃虚寒痰饮证\"，并言\"若血病则涩矣\"，以紧滑非涩，故知非血病。畏寒抱火、手足麻木、胸口胀即头眩呕吐、吐痰水稍愈，皆寒饮上逆之候；大便秘结乃津液上吐之冷秘虚秘，非燥秘。", ["细", "紧", "滑"]], "16218": ["病机", "脉弦数六至，原文谓\"胎脉固当数，然不滑数而弦数\"，滑数为胎之常，弦数则阴血大亏、阳无所依。引《脉经》\"阴虚阳无所依，令人多呕\"，故咳甚吐食非胃寒，乃阴虚致呕。虽平素胃寒，治病必以脉为准，脉弦数定属阴虚，滋阴补阴则咳止吐除。", ["弦", "数"]], "16219": ["病机", "两尺弦数、左关单弦，弦者肝病，数者火证。少腹乃肝部，妇人肝经内络廷孔，郁怒生肝火，火循经结于廷孔，故初病小便淋秘而痛。误用斑蟊毒剂攻劫，致血大下而痛愈甚，脉弦数正是肝火郁结、误治益甚之征，非梅毒可比。", ["弦", "数"]], "16220": ["病机", "脉细疾而硬，细为阴寒内盛，疾为阳格于外，硬则寒凝脉道。原文断为\"阴甚格阳，格拒不入\"，故阴躁不能卧、彻夜扶走、呕吐不纳药，皆阴寒脚气上冲、格阳于外之候。先通格拒后纳药，再以六物附子汤驱逐逆上阴寒，脚气方下归两足。", ["细", "疾", "硬"]], "16221": ["病机", "脉弦长而数，原文谓\"脉长而数，尚在阳明\"，两寸未变，知病未入心。脚气冲心故谵言乱走、跳跃如狂，申酉时火旺则发，天明阳气得助则安。此火迫上逆，须用肉桂引其下行，使脚复痛则病退，去病即所以安胎，合\"有故无殒\"之义。", ["弦", "长", "数"]], "16222": ["病机", "脉虚软而迟，原文谓\"脉不长不数\"，故口甜非胃火余热。前过用膏芩，热解而中寒生，口甜乃脾虚之真味、胃阳发露，无实热脉证反属虚寒。口不渴而喜唾、不思饮食、胃中隐痛，皆中寒之候，故用六君子加炮姜、益智温运而愈。", ["虚", "软", "迟"]], "16223": ["病机", "六脉沉弦而紧，原文谓\"沉弦主饮，紧则为寒\"，此外感风寒、内停冷饮，表里寒邪未解。怔忡作呕、昏厥逆冷、身疼头眩、手足冷麻、胸前嘈杂，皆痰饮寒邪为患，非虚证。故参术归脾不效，用桂枝、苍术、半夏、茯苓、炮姜等温散痰饮，呕止呃除而怔忡愈。", ["沉", "弦", "紧"]], "16224": ["病机", "脉沉弦而紧，沉主里，弦主痛主饮，紧主寒。右胁大痛、手不可近、手足厥冷，乃寒饮内结、厥阴寒气上逆之象。前曾吐虫，今胁痛，合为厥阴寒证，故脉沉弦紧相应。温里后痛移于左，加附子而现发热咳喘，是寒水冲逆，脉象示寒饮内伏、阳气不布。", ["沉", "弦", "紧"]], "16225": ["病机", "右尺脉全无，真阳外越，两足发热、面赤咳喘、右肋气冲不能卧，乃寒水上逆、水蛊之机。脉象虽未明言，然尺脉无根而虚阳上浮，正合虚寒毕露、阴盛格阳之病机。用真武汤意温阳镇水，使阳复寒散，则咳止胀消，反恶寒足冷，是阳回之征。", []], "16226": ["预后", "脉微似脱，是血脱气弱、阳气欲绝之候；继而脉散大无伦，面赤气促、不避亲疏，乃血脱于下、阳亡于上，虚阳外越之危象。散大无伦为胃气将败、真元涣散，故断为亡阳急证，不急救则瞬息脱矣。此脉由微转散大，示正气溃散，预后凶险。", ["微", "散", "大"]], "16227": ["病机", "脉虚大无伦，虚为正气不足，大为虚阳外浮。产后悲怒交加，胸胀寒热烦躁，医作瘀血疏消，反伤正气。此脉示产后虚烦、真阳外越，非实热瘀滞。虚大无伦与烦躁作渴、目中流火相应，乃内虚寒而外假热，故温补得安，胀满未解是虚中夹滞。", ["虚", "大"]], "16228": ["误治", "脉浮大而数，按之中空，是产后误用苦寒、中宫虚冷、逼阳于外之象。浮大数似热，中空则虚，故壮热喉痛、咳吐血涎而腹胀作泻。服温补后阳气内归，脉转细如丝，示虚寒本质显露。前医作阴虚治，反致脉证加剧，此脉正揭误治之害。", ["浮", "大", "数", "细"]], "16229": ["病机", "脉惟细迟无力，细主气血不足，迟主阳虚有寒，无力为虚。产后去血过多，虽虚回血止、饮食如常，然昼夜卧床、坐则头眩耳鸣，乃肝肾气虚、肝虚不摄气所致。脉细迟无力正合褥劳虚损之机，故用羊肉汤温补肝肾，十日后即能起坐。", ["细", "迟"]], "16230": ["病机", "脉愈大，继而散大，是产后虚烦、阳气外越之候。前医认作伤寒，断食发汗，更伤正气，故热躁愈甚而脉愈大。散大为胃气涣散、虚阳浮越，与呻吟狂躁、扬手掷足、热渴相应，乃真寒假热。温补加参，服毕即安，证明脉散大主虚脱而非实热。", ["大", "散"]], "16231": ["病机", "脉沉细而紧，沉主里，细主虚，紧主寒主痛。怀孕九月，冬月苦寒，发表攻里备尝，致中焦寒极，故畏寒极而痛在脐上、左右冲击。脉沉非欲产之候，乃寒凝气滞之痛。紧脉应痛，沉细示里虚寒盛，故非温不可，姜桂温中即所以去病安胎。", ["沉", "细", "紧"]], "16232": ["病机", "脉沉细紧，按之坚硬而长，沉主里，细为血少，紧为寒凝，长而坚硬示瘀血结块。小产后瘀血未尽，误用生地、白芍等凉药，血为寒凝，成血蛊。症见腹胀痛、呕吐不食、面黄浮肿、少腹结块、发热恶寒，皆瘀血内停、寒凝气滞之象。", ["沉", "细", "紧", "长"]], "16233": ["病机", "脉细数而涩，细为阴血不足，数为有热，涩为血行不畅。产后腹痛四月，午后发热、盗汗咳嗽，似虚损，但败浊不止、腹痛有形，脉不紧且姜桂附不效，非寒非积瘀。脉证属阴虚而现肠痈，因瘀腐成脓，故脉细数涩。", ["细", "数", "涩"]], "16234": ["病机", "两尺脉独数，尺脉候下焦，数为有热。产后瘀血未尽，积于肠回环处，寒化为热，将成肠痈。症见腹大痛、脐下块、里急后重、二便难、肠中水响，皆瘀热壅结肠道之征。脉数示热已成，故需通下。", ["数"]], "16235": ["病机", "脉涩而数，涩主血瘀，数主热。大产死胎，稳婆手重伤子肠，致二便不通、少腹肿痛如坟。脉不紧而反数，非寒痛；涩数示瘀血积久化热，但产后三日即肿痛，断非肠痈，乃外伤子肠、瘀血内结、气机壅塞之病机。", ["涩", "数"]], "16236": ["病机", "脉沉紧，沉主里，紧主寒。产后玉门未敛，久坐秽桶，寒气袭入下焦，阳气不通，前阴肿闭，小便反从大肠渗出。此厥阴中寒，非交肠病。沉紧示寒邪深伏下焦，故用四逆汤温阳散寒。", ["沉", "紧"]], "16237": ["病机", "脉弦细而紧，弦主痛主饮，细为血虚，紧为寒。中寒痰饮，产后十年不孕，下血胎脉不现。误服凉药增腹胀不食、冷痰上壅，脉更沉小，示寒饮内结、阳气衰微。弦细紧为阴寒内盛、痰饮阻滞之病机。", ["弦", "细", "紧", "沉"]], "16238": ["病机", "脉沉细而硬，沉主里，细为气血虚，硬为寒凝坚结。孕时食西瓜浸井，产后气血交虚，积寒在腹，症见胸腹胀满而坚、干呕不食、咳喘不能卧、足冷过膝。沉细硬示沉寒痼冷蟠结三焦，否塞不通，宜助阳消阴。", ["沉", "细", "硬"]], "16239": ["病机", "脉沉紧，坚而搏手，两尺脉皆伏，他部弦细而紧。沉紧主寒，伏主邪闭，弦细紧为寒凝肝脉。怀孕三月胎动下紫血，误用凉血益其冷。此下焦冷极，胎已无气，积冷下焦，肝藏中寒，故脉沉紧伏弦。", ["沉", "紧", "伏", "弦"]], "16240": ["病机", "产后气血大虚，复受风寒，脉不浮而单弦，说明表邪不显于外，而风邪已直入肝经。弦为肝脉，产后本虚，风邪乘虚内陷，故见头痛身疼、筋惕、汗多热不退；继而抽搐昏厥，是肝风内动、亡阳脱证之兆，故告病危笃。", ["弦"]], "16241": ["病机", "平素脾虚中冷夹痰饮，大吐后中虚，寒痰上涌。脉弦细而紧软，弦紧主寒饮内盛，细软主气血不足，正合大吐中虚、寒痰上逆之机，故见昏沉不语、手足抽搐、目珠上窜，类中风之候。", ["弦", "细", "紧", "软"]], "16242": ["病机", "产后六日，误认伤寒，辛温发汗太过，致大汗不止、血下如注、晕脱。脉细如丝，是血脱气衰、阴阳欲竭之象，血脱则脉道不充，故细如丝；汗血并脱，气随血耗，故不能言。治以血脱益气，人参附子回阳固脱。", ["细"]], "16243": ["病机", "艰产玉门久开，寒气袭入少阴。脉细如丝，手足厥冷，细为阳虚血少，厥冷为寒盛阳衰；少阴经络尽于喉，寒极于下，肾气不能上承，故卒然失音。脉细厥冷可征寒中少阴，用四逆汤驱寒以防变证。", ["细"]], "16244": ["病机", "产后积冷，复受寒邪，先见脉浮紧，为寒邪束表；表解后忽神昏不语、掐指剔牙、肠鸣下利，脉转弦细无力。弦细无力主里虚，产后未满月，气血本亏，寒邪内陷，虚风内动，故证类中风，属里虚之候。", ["浮", "紧", "弦", "细"]], "16245": ["病机", "体素虚寒，怀孕双胎，水气上溢。脉细如丝，两足冰冷，小便点滴不通，细为阳虚，冰冷为寒盛，水已上溢，阳不化气，故水湿泛滥，腹胀欲裂、气喘不能行立。不急治水，胎必浸伤，故用桂附姜参术苓泽大剂温阳利水。", ["细"]], "16246": ["病机", "脉沉静而不宣畅，沉主阳气内郁，静而不畅是阳𫏋偏盛、卫气不得入于阴之象。至夜宜静而反动，正合《内经》阳𫏋盛不得入阴故不寐之旨，故当体此意以行治法，或中病机。", ["沉"]], "16247": ["病机", "失血后干咳无痰，火升不得卧，脉象虚数。虚为阴血亏耗，数为虚火内动，皆由气火不下潜、真阴失守所致。阴不敛阳，虚火上炎，故咳而不得卧，治以大补阴丸滋阴降火。", ["虚", "数"]], "16248": ["病机", "失血后阴血亏耗，脉道不充故虚；阴不制阳，虚火内生故数。虚数并见，说明阴血不足而火热内扰，火性炎上灼肺，故见咳呛。此脉主阴虚火旺、火炎扰肺之病机，与失血后咳呛相应，虚为本、数为标，虑其火炎更伤肺阴。", ["虚", "数"]], "16249": ["病机", "右关候脾胃，脉弦搏为肝木偏旺之象，木旺乘土，气扰胃脘故痛，络伤则微见红。心中悸动、夜间多汗，乃阴虚阳浮不摄。弦搏示肝气横逆，与胃脘痛、失血、悸汗并见，说明肝木乘旺、阴虚阳浮，治宜滋填固摄以柔肝潜阳。", ["弦"]], "16250": ["病机", "经云长则气治、短则气病、数则烦心。脉短示气不足，脉数示营分有热，故曰气不足而营分热。短与数并见，说明正气虚而营热内扰，虚者益之、热者清之，两得其平。此脉主气虚营热之病机，与烦心相应，非单纯实热可比。", ["短", "数"]], "16251": ["病机", "失血后虽不咳嗽，上传之患可暂置，然脉数示火热内盛，右关微搏则火邪有侵犯中州脾胃之势。数而右关搏，说明火邪不独在肺，已渐及中焦，故不可不急防。此脉主火邪犯中之病机，与失血后口干燥等症相应，议进滋养以清火保中。", ["数"]], "16252": ["预后", "饮食如常而脉象少生动之气，说明胃气虽尚可，脉中生机已不足，正气有渐衰之兆。虽咳嗽未久，脉已失生动，故当未雨绸缪，防其病进。此段以脉神判断预后，非专主一病，示脉少生气为正气不足之征，宜早图调养。", []], "16253": ["病机", "脉神未旺，即脉象缺乏旺盛神气，原文指出以精气未充故也。精气为脉神之本，精亏则脉失充旺，故脉神不振。此段说明脉神未旺与精气未充相应，属正气不足之病机，转丸方即针对精气未充而设，非外邪实候。", []], "16254": ["病机", "脉数示内有热，寸部尤甚则热偏于上焦，故口干燥；便溏泄则太阴脾运不健。数而寸甚，说明手太阴肺与足太阴脾皆病，上热下虚并见。此脉主太阴二脏同病之病机，与口干燥、便溏泄相应，先宜调和二脏，清上温下。", ["数"]], "16255": ["病机", "脉小弱为气血不足、脉道不充之象，阴不恋阳则阳浮易动，循督脉上升，扰动心神，故心中震荡、惊惕不宁。小弱示正虚为本，阳浮为标，虚阳上扰。此脉主阴虚阳浮、心神不宁之病机，与惊惕震荡相应，治以填镇固摄以潜阳安神。", ["小", "弱"]], "16256": ["病机", "脉小而数，数为热盛，小为气液不足，热盛而津已伤，故见但热不寒、汗多渴饮。热在气分，汗多则津泄，渴饮则胃燥，脉小数正是热炽津亏之象。用竹叶石膏汤清透气热、益气生津，加桂枝者，恐汗多而阳亦伤，兼护卫阳，使清热而不碍阳。", ["小", "数"]], "16257": ["预后", "此段未明言脉象，重在叙述下痢厥逆服温补后神气略定、痢稍缓，似为向愈，然忽转下痢日夜不止、面赤戴阳、神昏谵语，诸恶毕集，是虚阳上浮、阴寒内盛之危候。后服方痢止、神静、脉亦循经，乃阳气渐复、脉归常度之兆，故以脉循经断为奇效，属预后转归之论。", []], "16258": ["病机", "左脉中部短促而急，短为气损，促急为虚阳躁动、阴精耗散之象。下痢不止，阴液下夺，面赤戴阳、神昏谵语、循衣摸床，皆虚阳飞越、神魂不守之候。脉短促急迫，正合下痢亡阴、虚阳上脱之机，故议参附术救逆、桃花汤固摄下焦，以挽飞越之阳、存耗散之阴。", ["短", "促", "急"]], "16259": ["病机", "脉微欲绝，阳气衰微已甚，鼓动无力，故指头寒而神气倦怠。寒热已微似病渐愈，然脉微欲绝、指头寒，正是少阴病阳衰之真凭，仲圣所谓少阴病即此。脉证相参，危机已兆，恐虚阳猝脱，故姑拟方以温救少阴。", ["微"]], "16260": ["预后", "服药后两手已温，脉微已现，是阴分转阳、阳气渐回之吉兆。然脉仅微现而未复常，胃腑未通、津液未复，邪热劫阴，正虚未复，故虽属转机，仍赖调理，危然后安。脉由欲绝转为微现，正是阳气来复之征，故断为吉兆而拟益阴通腑。", ["微"]], "16261": ["病机", "肝脉滞而涩，滞为气机不畅，涩为血行不利，合之是肝气郁结、血络不宣。肝郁则风不宣畅，风郁不能发越，故云焉能发鸣。治借金以开之，取金能制木、宣降肺气以疏肝郁之意。脉滞涩正主肝郁气滞、血行不畅之病机。", ["涩"]], "16262": ["病机", "此段未出脉象，以天道左升右降喻人身气机，肝位在左而其气常行于右。今营分大伤，络脉不营，故动作皆痛。营伤络虚，气血不能濡养筋脉，动则痛作，是营虚络痹之病机。治先调营为主，使营血充盈、络脉得养，则升降复常而痛可止。", []], "16263": ["病机", "脉小弱，小为气血不足，弱为脾胃虚馁，正合时吐蛔之候。风入胃，七日生虫，脾胃得温则虫伏，气塞则虫上出而呕。脉小弱说明中焦虚寒、气血不充，虫因虚而动。用药辛酸为主以安蛔，苦味为辅以清降，杀虫次之，皆本脉小弱所主之脾胃虚寒病机。", ["小", "弱"]], "16264": ["病机", "原文未载脉象，仅言“风阳鼓动，右手足筋脉抽引”。风阳内动，筋脉失养，故抽引；右手足属气血偏虚之处，风阳乘虚窜络。治宜养营熄风，营血充则风阳自潜，筋脉得柔。此段重在病机与治法，非凭脉断病。", []], "16265": ["病机", "原文未出脉名，直述“筋脉抽掣，风阳鼓动”。肝主筋，风阳亢逆则筋脉拘急抽掣。此属内风旋动之病机，非外感风邪。脉虽未言，按证当见弦劲或数急之象，然原文无脉，故不列脉素。", []], "16266": ["病机", "原文谓“气似浮，故脉不得沉而降，气亦随之”。气机浮越，脉应之而不沉，反见浮象。此非表证之浮，乃气虚或气逆不能降纳，脉随气浮。主病在气机升降失司，与“气似浮”相应，治当降气纳气。", ["浮"]], "16267": ["兼症", "原文未载脉象，述“两足筋脉时攻痛，攻之甚，头且晕”。筋脉攻痛属肝风窜络，头晕为风阳上扰清窍。此段以症候为主，示肝风内动、筋脉不利之兼症，脉象缺如，故不列脉素。", []], "16268": ["病机", "原文未出脉名，详论“风阳鼓动，燥火升腾”“火盛水衰，风随火动”“火空则发”。肝木化火，火盛灼阴，水不涵木，风火相煽，故筋脉抽掣、搐搦不已；海底湿为肝火盗母气所致。小便失溺、厥逆随至，示阴竭阳越，暴脱可虞。此段专审病机所向。", []], "16269": ["病机", "复诊“脉象带数”，数为热象。咳甚则肺气阻抑，便溏则胃阳不宣，土金俱病。脉数主热，热郁于肺胃，肺失肃降则咳，胃阳不宣则便溏。土金同病，脉数示内热未清，治以神农上品调中宫，使土金相生。", ["数"]], "16270": ["病机", "原文仅言“风阳鼓动，脉显其形”，未指具体脉象。风阳内动，脉必应之而显弦劲急数之形，然原文未明言何脉，故脉素从缺。此段主旨为风阳鼓动之病机，脉形外显，可佐证内风之动。", []], "16271": ["病机", "原文未载具体脉象，但言“诊脉肝火有余，肾水不足”，又“反并于阳明而益旺，右关之火”。肝火有余、肾水不足，水不涵木，火反并阳明，右关候脾胃，火旺于中。治宜壮阴和阳，滋水制火。此段以脉诊断病机，脉素缺如。", []], "16272": ["主病", "脉小无力，为正虚不能鼓动脉道之象。僧患单腹胀而兼瘕块作痛，本属积滞内结之实证，然脉不实反小弱无力，说明正气已衰，无力抗邪。脉小无力与胀满瘕痛并见，提示虚中夹实、正不胜邪，攻伐须慎，故以脉之无力辨其虚实本质。", ["小", "虚"]], "16273": ["病机", "脉沉主里、主水。谢某囊肿足浮、溲少，为水湿内停、泛溢肌肤之候；水气不行则小便短少，湿邪下注则囊肿足浮。脉沉说明病位在里，水湿停聚于内而不外达，与溲少、浮肿之症相应，是水病在里之脉证。", ["沉"]], "16274": ["病机", "原文未出脉名，仅言湿阻络脉。湿邪黏滞，阻遏经络，气血不得宣通，故见麻木；久则气血不荣，筋脉失养，发为痿痹。此为湿阻致气血不行之病机，治以宣通法，使湿去络通、气血畅行，则麻木痿痹可解。", []], "16275": ["病机", "两手俱弦滑，弦主湿郁、滑主湿痰留著。右半身时麻木，正是湿邪留著经络、气血不得流通之处，故脉滑而弦。原文指出治湿不可过燥，燥则伤阴，反不利湿，仿黑地黄丸治法，是于渗利中兼顾阴分，紧扣弦滑所示湿著之机。", ["弦", "滑"]], "16276": ["病机", "脉来弦滑，弦为湿郁气滞，滑为湿痰内盛。手足麻木乃湿邪阻滞经络、气血不能达于四末所致。脉弦滑与麻木并见，说明湿浊留著、络脉不畅，是湿邪为患之明证，与前述湿阻致麻之机一脉相承。", ["弦", "滑"]], "16277": ["病机", "右脉之滑较甚于左，右主气分、主脾肺，滑甚于右，说明湿浊偏聚于气分。原文点明为酒湿动之，酒性湿热，蕴于中焦，随气机流布而脉见滑象偏右。此以脉之左右偏甚辨湿邪所在，是酒湿内动之征。", ["滑"]], "16278": ["病机", "两手脉伏而不扬，伏为气机郁滞、脉道被遏之象。气机之滞，则脉气不能鼓动外扬，故按之沉伏不显。原文断为气机之滞，治宜助中宣达，使中焦气机通畅，则伏脉自起。此以脉伏辨气滞，非虚非寒，重在宣通。", ["伏"]], "16279": ["主病", "脉小弱为气血不足之象，素体肝气偏旺而脉反小弱，说明下焦亏虚、根本不足。疝证时发，多因下焦虚寒、气机失于温运而作。脉小弱与素有肝气、疝发相应，提示病本在下焦，治宜从下焦培补，不可徒治其标。", ["小", "弱"]], "16280": ["病机", "原文谓浊证日久'肾关开而精气大耗，筋脉无以濡养'，又诊'右寸大而不敛'。大而无力不敛，是精气耗散、肺气不固之象，非实火亢盛，故云'非木火旺令所宜'。肾精亏则筋脉失养，肺气散则咳嗽难愈，总属虚多实少，治当填补固摄，不可因咳嗽属风邪而轻视。", ["大"]], "16281": ["病机", "脉小而急，小为营血不足，急为热象内迫。原文断为'营热证'，症见月事先期、色紫黑，正是热扰血海、迫血妄行之候。营分有热则脉行急迫，血为热灼则色紫黑，故脉小急与经期提前、经色紫黑相合，主营热而非虚寒。", ["小", "急"]], "16282": ["治法", "原文未载脉象，仅述'经阻不行，肚腹连腰颇痛'，断为奇经为病。经阻而痛连腰腹，是冲任气血瘀滞、奇脉不通之象。'从奇脉治'即从冲任督带入手调治，非一般通经活血，故本段主旨为治法，示人辨奇经病位而施治。", []], "16283": ["病机", "原文谓气聚上冲'由两肋而升，肝亦觉冲为患'，又言'血虚而不能滋养肝冲'、'精血空乏'。冲脉隶于肝，血虚则肝冲失养而气逆上聚，聚于脐中则刺痛不休。其势聚而不散，是虚中夹滞，故'宜抚不宜剿'，以温养填补使精血渐充，不可峻攻。", []], "16284": ["病机", "原文谓'奇经河津空乏，以致厥阴经脉不司约束，发为阴挺'。河津空乏即精血津液亏虚，厥阴肝脉失养则约束无力，胞宫下脱成阴挺。治宜养阴清热以渐复，戒一切消克之品，正因虚为本、热为标，攻伐则更伤奇经。", []], "16285": ["预后", "脉象软弱，软为营血不足，弱为气衰，合之四肢麻痹，原文断'总由营亏，血不养筋'。营亏血少则筋脉失濡而麻痹，脉亦软弱无力。此与类中风先兆相类，故云'恐属类中根萌，殊可虑也'，属预后警示；脘痛则另以疏肝理胃为治。", ["软", "弱"]], "16286": ["预后", "年高麻木不仁、眩晕而脉弦，弦为肝脉，主风阳内动。风阳上旋则清窍被扰而眩晕，筋脉失和而麻木。弦脉劲急不柔，是肝阳偏亢、化风上扰之征，故'防其类中'，属预后之论，示人早为之备。", ["弦"]], "16287": ["预后", "胆虚中正无权则疑惧交至，脉弦为减，是弦象渐退而正气未复。弦本肝风之脉，减则风阳稍敛而虚象显露，然风阳易动，根基未固，故仍'防其类中'。本段以脉弦之减判断病情进退，主旨在于预后警示。", ["弦"]], "16288": ["病机", "左脉弦为肝风内动，右脉滑为痰湿内蕴，弦滑并见，是痰火生风之象。痰火循经上扰，故见左额胀痛。治法以和阳熄风、化痰去湿，正合脉证。", ["弦", "滑"]], "16289": ["病机", "脉形小弱为气血不足，右微数示虚阳浮动。言謇舌强、腰楚足酸、左股无力，乃肝脾肾三阴并亏，筋骨失养，日萌痱中之机。脉小弱正合三阴虚损，当究其本为要。", ["小", "弱", "数"]], "16290": ["病机", "脉濡小涩，濡为湿滞，小涩为气血不畅，主脾虚湿困、筋脉失养。痿躄四月，语言不利，痱风之象；腹痛便溏或结，皆中焦湿滞。故宗《内经》独取阳明，从中治以运脾化湿。", ["濡", "小", "涩"]], "16291": ["预后", "脉仍微细，是阴血亏虚未复，正气难支。前议三阴亏损，痿躄不减而脉无起色，说明痱中深重，最难取效。微细之脉与三阴亏损相应，预后不佳，故言难治。", ["微", "细"]], "16292": ["病机", "口眼常动则风生，风摇耗血，血衰无以营筋，故筋脉拘急，有歪僻之象。脉拘急正是筋脉失养、风动于内之征，与口眼瞤动、歪僻相应，说明血虚风动为其病机。", ["急"]], "16293": ["病机", "脉弦为肝郁，沉滞为气机不畅，带数为化风化火。阴亏肝郁，化风化火，故耳鸣、舌干起刺、不得寐、胁胀。弦沉数之脉正合肝郁化火、阴亏风动之机，议体用两顾。", ["弦", "沉", "数"]], "16294": ["病机", "脉弦不寐，心中嘈杂，总由肝阳亢逆，化风内动。弦为肝脉，肝阳上亢则扰心不寐，犯胃则嘈杂。以静药和阳，正针对弦脉所主之肝阳亢逆、风动于内。", ["弦"]], "16295": ["病机", "阴虚火升，水亏木火少藏，故咽燥、筋脉抽引、眩晕悸动、大便不爽。火升风动，游行变幻莫制，皆由水亏不能涵木。原文未识脉名，然诸症与阴虚火升、肝风内动之机相应，故宜滋养。", []], "16296": ["病机", "原文未识脉名，然述“迟眩晕跌仆，心悸蠕动，筋脉抽掣，肝风振荡”，显系肝阴亏虚、风阳内动之候。阴不制阳，风阳上扰则眩晕跌仆；风动筋脉则抽掣蠕动；心神被扰则心悸。治以养阴熄风，正合“肝风振荡”之病机，脉虽未录，其证已明。", []], "16297": ["病机", "脉弦数，弦主肝风，数主热，合“风阳上冒”之机。华高年阴液衰，春夏阳升，风阳化热上扰，故经脉抽胀、晕厥、身热面赤、汗出。苔黄厚尖紫为热郁痰滞。初养阴熄风未全瘳，转方诸水清热，脉渐和，苔减，然筋掣汗泄未已，示风阳未靖、阴未复。", ["弦", "数"]], "16298": ["病机", "脉濡而弱，濡主湿，弱主气虚。廉年六十三，向衰之岁，肝气挟湿化风，头晕耳聋，食后少运，显系中气不足、湿土司令、风阳上扰。濡弱之脉正合脾虚湿困、气血不充之机，故治当扶中为主，熄风佐之，以复中焦运化。", ["濡", "弱"]], "16299": ["病机", "原文未识脉名，但言“脉形窒滞”，窒滞者，气血郁阻不畅之象。孙操劳郁勃，肝木乘土，气机壅塞为胀，大便不爽，皆肝郁气滞、木不疏土之咎征。脉形窒滞正是气郁湿阻、升降失司之反映，与胀满、便不爽相应。", []], "16300": ["病机", "原文未识脉名，仅言“奇脉暗伤，阳浮作眩”。奇脉暗伤指奇经八脉亏虚，阴不涵阳，阳浮于上则为眩晕。此脉象虽未明录，然“暗伤”示虚损之机，阳浮为标，奇脉亏虚为本，故眩晕由下虚上实、阴阳不交所致。", []], "16301": ["病机", "原文未识脉名，述“厥阳眩晕跌仆，下部渐肿，腰楚带下，八脉暗损，风阳鼓动”。八脉暗损，下元亏虚，阴不制阳，风阳上冒则眩晕跌仆；下虚水湿不化则肿、腰楚、带下。脉虽未录，其证已示下虚上实、奇经受损、风阳鼓动之病机。", []], "16302": ["病机", "脉弦为减，弦主肝风，减为病势稍退。华风阳未熄，巅顶痛不休，下虚上实，素嗜酒挟湿生痰。脉弦示风阳未靖，减则厥暂止，然痰湿未化，发易。故预防须静药和阳、扶正利痰，以杜风痰复升。", ["弦"]], "16303": ["病机", "脉弦大而迟，弦主风痰，大主阳升，迟主阴寒或痰阻。癫痫发于阴，情志内伤，痰气阻遏，机窍郁勃阳升。弦大示风阳鼓动，迟示痰气壅滞、阳升不畅。苔浊腻、纳少、善欠多寐，皆痰湿内阻、阳不出阴之象，故厥易复作。", ["弦", "大", "迟"]], "16304": ["预后", "壮盛之年而春夏脉见濡细，形神消瘦，是正气不足、体用俱损之象。濡细为气血两亏、脾运不健之脉，当升发之令而脉反柔弱无力，故言\"殊为可虑\"。仍前法参以扶正、体用两调，正针对此虚损病机。", ["濡", "细"]], "16305": ["预后", "补剂颇适而脉象细弱，说明药已中病、虚损有可挽回之机，然细弱为气血俱衰、元气未复之脉，非旦夕可充，故\"难期骤复\"。此段以脉测恢复之缓急，属预后判断，非单纯言病机。", ["细", "弱"]], "16306": ["病机", "脉软弱而不寐目涩，软弱为营血不足、脉道失充之象。营血亏虚不能奉养心神则目不寐，不能上濡目窍则目涩，故直断\"责在营不足\"。以脉软弱定营虚，症脉相合，属病机分析。", ["软", "弱"]], "16307": ["病机", "消渴一年，形神渐瘦、溲多腻浊、大便燥而脉涩，涩为阴精亏少、血行不畅之象。阴精少奉则阳亢，亢则害，津液不布故便燥溲浊。脉涩正应阴精亏耗，故立壮水之主、保本之道。", ["涩"]], "16308": ["病机", "口干咳呛而脉虚数，虚为肺气阴不足，数为虚热内扰。阴虚火旺灼肺，故口干咳呛，久则肺叶焦枯，恐延为肺痿。脉虚数正是肺金气阴两伤、虚热内炽之征，故拟清金宁肺。", ["虚", "数"]], "16309": ["病机", "热久伤阴，脉弦数，弦为阴伤阳亢、肝木失柔，数为热邪未清。嗽甚则呕，胃气受戕，土不生金，金失所养，渐延肺痿。脉弦数应热久阴伤、木火刑金之机，故议培土生金以救胃气。", ["弦", "数"]], "16310": ["病机", "久咳涎沫、胃少纳而脉短，短为气虚不能鼓脉、胃气衰少之象。胃气不充则纳少，土不生金则久咳涎沫，肺金失养，恐延肺痿。脉短正示中气不足，故与益胃生金，从胃气着眼。", ["短"]], "16311": ["病机", "八十五岁郁勃之体，厥阳司升，耳鸣咳呛、脘窒不寐，脉短涩虚数。短为气虚，涩为阴亏血少，虚数为阴液内亏、虚热内扰。阴液内亏则秋燥将至更易伤肺，故预进清金益胃，恐延肺痿。", ["短", "涩", "虚", "数"]], "16312": ["病机", "热在上焦，肺为娇脏，热灼津伤则脉虚；虚数并见，非实热，乃肺痿津枯、气阴两伤之象。原文以“脉虚数者为肺痿”点明病机，又言“汗易泄，时恶风，肺主皮毛故也”，说明肺气不固、腠理疏松；唇口腐碎少纳，则兼阳明津亏。脉虚数正合肺痿虚热之候。", ["虚", "数"]], "16313": ["病机", "原文未出具体脉名，仅言“诊脉颇有力，非有余也，仲景谓之为减”。积劳伤阳，阳络伤则血外溢，失血后阴必伤，盛夏阴不配阳，故身热不耐劳。脉虽有力而实为减，乃胃气受损、阴血不足之征，非邪实有余。胃纳甚少，故宜柔药养胃，取“胃为阳土，得阴自安”之义。", []], "16314": ["主病", "气口脉大，身微热，恶寒不知味，原文断为“治从劳倦门”。气口主脾胃，脉大而身热恶寒、口不知味，非外感实邪，乃劳倦伤脾、中气不足、虚阳外浮所致。脉大为劳，正合东垣劳倦内伤之旨，故从劳倦门论治，补中益气以复脾胃升发之权。", ["大"]], "16315": ["病机", "水亏火炎，水火未济，故脉弦数。弦为肝旺，数为火炎，舌绛、小便艰涩皆阴亏火旺之征。原文以“黄河之水天上来”喻金能生水，水生则肝有制、胃有资，主张滋养金水以制肝火，反对通利。脉弦数正是水不涵木、相火偏亢之病机反映。", ["弦", "数"]], "16316": ["病机", "诛伐过多，胃气太伤，不容谷食，大便溏泄，中宫失砥柱之权；舌绛无苔，柔土少津。脉来数大，原文明言“非有余也，仲圣脉法为减耳”，即数大为胃气虚馁、津液亏耗之象，非实热。故拟麦门冬汤益胃生津，望其安谷，脉症合参皆属虚损。", ["数", "大"]], "16317": ["病机", "脉弦数大，原文断为“阴损阳浮”。弦为阴亏木旺，数为阳浮，大为虚阳外张；阴损于下则阳浮于上，大便艰涩亦由阴液不足、肠失濡润。脉弦数大非实火，乃阴虚阳浮之候，故法宜滋养，填阴潜阳，使阳得阴配而浮火自敛。", ["弦", "数", "大"]], "16318": ["病机", "交大节阴虚阳升，血症复发，每于戌亥为多，龙相少藏，血随气上。诊脉芤弦：芤为失血伤阴、血不循经之象，弦为肝阳亢逆、气升血动之征。芤弦并见，正合阴亏阳升、血随气逆之病机，故以填下摄纳为主，使龙相归藏而血自宁。", ["芤", "弦"]], "16319": ["病机", "漏疡暗耗日久，封藏不固，络血沸腾，咳呛、滑泄、盗汗并见。脉芤细数：芤主失血，细主阴亏，数主虚热，三者皆咎征。原文谓“皆是咎征”，说明阴精耗损、虚火内扰、封藏失职之病机，与咳呛滑泄盗汗诸症相应，属虚损劳怯之候。", ["芤", "细", "数"]], "16320": ["病机", "脉濡细为阴虚及阳之象。濡主湿、主气虚，细主阴血不足，二者并见，说明阴液亏虚日久累及阳气，卫外不固，故身热消瘦、汗出已多。汗多更伤卫阳，形成恶性循环，故虑其损怯。脉濡细正合气阴两虚、卫表不固之病机。", ["濡", "细"]], "16321": ["治法", "原文未识出脉名，仅言鼻衄不止，宗仲景当从冲脉治。鼻衄不止，多因冲脉气逆、血随气上所致。冲脉为血海，隶于阳明，冲气上逆则血溢鼻窍。故治从冲脉，降逆止血，非单纯治肺。此段主旨为治法，脉象原文未载，故脉象要素为空。", []], "16322": ["病机", "脉形虚芤带数，虚主气阴不足，芤主失血伤阴，数主阳亢有热。年逾五旬，冲任不固，八脉交损，正值经行则水愈亏而阳越亢，故热势转甚、腰楚怯弱。虚芤带数正反映阴亏阳亢、冲任不固之病机，故以和阳育阴为要。", ["虚", "芤", "数"]], "16323": ["预后", "脉来虚数，虚为劳损气阴亏耗，数为阴虚内热。热起于涌泉，下午入夜则剧，经断、脘痛时呕，皆劳损见端之象。虚数之脉示正气已亏而虚热不退，草木难期速功，说明劳损已成，预后需缓图，非旦夕可效。", ["虚", "数"]], "16324": ["病机", "脉左搏大，左脉候肝肾，搏大有力为阴虚阳浮之象。阴不敛阳，阳浮于上，迫血妄行，以致鼻衄走阳。上下耗损，既伤阴于下，又失血于上，故势非轻浅。搏大之脉正说明阳浮不潜、阴亏失守之病机。", ["搏", "大"]], "16325": ["预后", "脉数主阴虚内热。失血损症，经伤咳呛、骨蒸微热盗汗，皆阴亏火旺之象。胃少纳谷、频欲呕吐，为子病及母，脾胃受累，故为难治。数脉示虚热炽盛而正气日衰，见象甚著，说明损症已深，预后堪忧。", ["数"]], "16326": ["病机", "原文未识出脉名。封藏不固，滑泄频频，为肾失封藏之象。肾脉上循喉咙，肾阴亏虚不能上承，故呛咳失音。滑泄伤精，精亏则喉失濡养，呛咳失音由此而生。此段说明肾虚封藏失职、精亏及肺之病机，脉象原文未载。", []], "16327": ["病机", "脉象微弦，弦为肝脉，微弦示肝阴不足而肝阳偏亢。肝肾阴亏，封藏失职，则风阳易亢。乙癸同源，肝阴亏则肾阴亦虚，水不涵木，阳亢风动。微弦之脉正反映阴虚阳亢、风阳欲动之病机，故治从乙癸同源，滋水涵木。", ["弦"]], "16328": ["病机", "脉濡小为脾虚湿困、气血不足之象，尺部微弦则示肝气偏旺、下焦不固。原文谓“肝脾之气不和，少腹攻触作楚”，濡小应脾弱湿滞，微弦应肝郁攻触；“梦泄”乃肾真不固，尺脉微弦正是下焦失摄之征。大便稍干、胃气略开为休征，说明中焦尚可运化，故治法协和肝脾兼摄下焦。", ["濡", "小", "弦", "微"]], "16329": ["病机", "脉象濡弦，濡主湿滞、精血不足，弦主肝旺、相火不藏。原文“交节龙相少藏，又经梦泄”，龙相指肝肾相火，交节时相火失藏而梦泄，脉濡弦正合阴精亏而肝火动之机。濡为阴分不足、湿浊内滞，弦为相火扰动，故治法“填阴摄固”，以滋填阴精、固摄下焦为要。", ["濡", "弦"]], "16330": ["病机", "脉虚弦涩，虚为心肾气血不足，弦为肝郁或惊恐气乱，涩为精血滞涩、精关不固。原文“惊恐而作，惊则伤心，恐则伤肾，心肾失交”，故多梦悸动、精关淋沥。虚弦涩正应心肾两虚、气机郁滞而精道不固之病机，治宜摄固，即固摄下焦、交通心肾。", ["虚", "弦", "涩"]], "16331": ["病机", "脉颇弦，原文引“长沙脉法为之减也”，谓弦脉较前减轻，但仍属弦象。肾主水藏精，封藏失职则水亏火亢，弦为肝旺火升、阴不制阳之征。遗滑无度、将有淋浊，正是水亏火亢、精关不固所致。脉弦示相火偏旺，故治法以壮水为主，使水火无偏胜，阴平阳秘。", ["弦"]], "16332": ["预后", "脉虚为气血阴阳不足之象，原文“肾阴固亏，脾元亦弱”，食后不运而疮痍、入夜微热盗汗，皆脾肾两虚、阴不敛阳之候。脉虚正应脾元弱、肾阴亏，虚脉示正气不足，故“最易延入损门”，预后堪忧。此段重在以脉虚判断易入虚损，仿立斋治意，健脾滋肾。", ["虚"]], "16333": ["病机", "脉弦为减，承长沙脉法，谓弦象虽减而未除。原文“火升口干，阴精少奉，总由淋沥暗耗”，淋沥日久耗伤阴精，阴不制阳则火升口干，弦脉为肝火偏旺、阴精不足之征。脉弦减说明火势稍缓，但阴精难骤复，故“未能骤期速动”，病机在阴亏火升、精血暗耗。", ["弦"]], "16334": ["病机", "脉形虚数，虚为肝肾内伤、正气不足，数为湿热内蕴或阴虚火动。原文“右髀股筋挛作痛，渐延白浊，溲便不利”，此肝肾内伤、湿热下注之候。虚数并见，示正虚而湿热未清，口干怯弱为阴伤之征。脉虚数正应本虚标实之病机，故谓“殊非轻浅”。", ["虚", "数"]], "16335": ["病机", "脉形弦数，弦主肝旺、相火不藏，数主热、主湿郁化火。原文“肾阴亏乏久矣，湿邪下注，海底结痈之象”，舌苔滑腻示湿浊内蕴。阴虚者阳必凑之，至阴之地龙相所居，弦数为相火偏旺、湿热下注之征，故见结痈之象。治法泻南补北，泻火滋阴以探其本。", ["弦", "数"]], "16336": ["病机", "原文未识脉名，仅言“脉象中阳不运”，指脉象反映中焦阳气不运。脘闷气壅、大便不爽为气机壅滞之症，痿躄软麻乃阳明虚而四肢失养。中阳不运则水谷不化，湿浊内停，故仿胸痹法以通阳，独取阳明以治痿。", []], "16337": ["病机", "脉濡数，濡主湿，数主热，合为湿胜化热之象。患者嗜酒中虚，口苦舌黄黑，为湿热熏蒸；湿邪浸淫筋脉，渐延痿躄。此脉说明中虚湿盛，郁而化热，非轻浅之候。", ["濡", "数"]], "16338": ["主病", "脉仍革，右为甚。革脉主虚寒相搏，如按鼓皮，外坚中空。右脉候气，右甚则气分虚寒尤著。肠痹症见大便不通，乃阳气不运，阴寒内结，故脉革而右甚，主肠痹之病。", ["革"]], "16339": ["病机", "脉象短涩，短主气病，涩主血少。六日不更衣，胃腑失司下行，因液亏肠燥，脉道不充，故短涩并见。此脉说明津液亏耗，肠失濡润，法宜温润以通之。", ["短", "涩"]], "16340": ["预后", "尺脉尤虚，尺候肾，虚则肾元不足。得大便不爽，形气衰弱，尺脉尤虚，说明下元虚衰，气化无力。此脉症相合，殊为可虑，预后堪忧，故拟方商正。", ["虚"]], "16341": ["病机", "脉短，短主气郁或气虚。痰多纳少，脘痞色夺消瘦，便通而少腹胀满不减，此非胃实腑病，乃脾虚气弱，痰湿内阻，脉道不利故短。仿济川煎合肠痹例，寓通于补。", ["短"]], "16342": ["病机", "脉象小数，小主正虚，数主热，然非实火。延症一月，阴液耗伤，虚热内生，故脉小数。宗经旨泻南补北，即泻心火、补肾水，以调虚实。", ["小", "数"]], "16343": ["预后", "脉形小数，小为正气不足，数为热。少腹满、溲色赤、苔腻作渴，湿热蕴结膀胱，气化不利为癃。脉小数示正气渐亏，湿热未清，恐多变幻，不可轻视。", ["小", "数"]], "16344": ["病机", "脉交虚指八脉交虚，为血崩后气血大亏、肝肾空乏之象。前用益气摄血、清营分虚火而崩止，胸脘舒和、思纳谷，说明气机渐畅；然脉虚未复，冲任空乏，故最虑腹膨、漏带、干呛、寒热四变，皆由虚风内动、带脉不固所致，当预为防。", ["虚"]], "16345": ["预后", "原文未出脉名，但言“神脉皆振”，知脉已渐复胃气，为崩后向愈之兆。然头晕轰热时作，乃营阴未充、风阳游行未熄之象；必待营阴恢复，则虚风自平。此段以脉神振作为凭，断预后良好，而余症尚需时日。", []], "16346": ["病机", "脉细带弦，细为阳衰，弦为气郁，合之舌淡苔白、早食暮吐、完谷不化，显系脾肾阳衰、无火腐熟水谷，非火热暴迫之下趋。弦亦主土虚木贼，气分不和，故治以温中理气，使火复土温，则呕吐自止。", ["细", "弦"]], "16347": ["病机", "原文未出脉名，然“脉症合参”而知脾藏气血大伤。思虑郁怒伤脾肝，血崩后气营大虚，彻夜不寐、惊疑怔忡，非癫痫痰火，乃脾虚不能运液生血，心虚失养。大便溏、胆怯，更显不足，故切戒执痰火有余而妄清。", []], "16348": ["病机", "脉细弦而虚数，细为阴亏，弦为气陷，虚数为中气不足、虚热内生。血崩本属气虚下陷，血去阴伤，故心悸惕、惊疑无主。寻源求本，当补立中气为先；若专清痰火，则虚者愈虚，必延成痼疾。", ["细", "弦", "虚", "数"]], "16349": ["预后", "原文未出脉名，但言“脉象颇形起色”，知脉渐和缓，元气渐振，故恐惧忧疑之象已可支持。肝郁日畅，寡有恼怒，为佳机；然心脾血液未充，脉虽起色而未全复，尚须怡养，不可遽补，亦不可再耗。", []], "16350": ["病机", "新产两朝，脉芤舌红，芤为中空血脱，红为阴伤。瘀不下行，发热神蒙，肢麻汗多，乃酷暑外迫、阴气郁冒、血随气逆，时有昏晕，变险可危。急扶端坐、敞轩护风，切勿胶执热汤，以避暑热再伤阴气。", ["芤"]], "16351": ["病机", "原文未出脉名，但“以脉症参之”断非真寒。郁火越冒，冲心为厥，厥后心悸不寐、惊恐疑惧，劫肺痰血，形凛轰热，经行如崩，月行二次，盛暑厚衣、稀粥不敢下咽，皆疑虑过深、气机郁结所致，非劳损不起，当怡畅襟怀。", []], "16352": ["病机", "脉涩弦数，涩主阴伤营亏，弦主肝风内动，数主邪热炽盛。冬温乍发，月事适行，阴气先虚，邪从内传，失于开泄，邪转充斥肺胃，兼入营分，故昼夜烦躁、神魂飞越；舌绛苔厚、痰滞并阻、大便溏泄，皆热邪内迫、风动痰涌之象，深恐痉厥变险。", ["涩", "弦", "数"]], "16353": ["病机", "右脉洪数，洪为热盛气分，数为邪热内炽。病交两候，癸水淋漓未净，营热炽甚，通宵不寐，寅卯时肝风内动，指痉发厥，目窜痰涌，遍体汗泄而定；舌苔根厚灰黄，大便连泄，火热下注，温邪欲陷，昏闭可虑。营分渗泄于下，肺邪壅遏于上，故不可执热入血室古法。", ["洪", "数"]], "16354": ["病机", "脉较晨间数甚，数主邪热内盛，入暮病剧，乃温邪自口鼻吸入，肺先受之，逆传心包之象。热邪深入，故脉数加剧；再与清解，意在透邪外达，勿致昏闭为妙。此段以脉数甚示邪热鸱张、有内闭心包之势。", ["数"]], "16355": ["病机", "未识脉名，然述昨诊后狂躁厥逆，服至宝丹神志渐定，吐咳浓痰颇畅，黎明得寐，寐醒气逆，便泄已止，口苦咽关疳点密布。此冬温化毒，邪从内透外泄之机；狂躁厥逆为热陷心包，痰畅、疳点为毒邪外达，故曰外泄之机。", []], "16356": ["病机", "脉息左含静意，右寸关尚见滑数，滑主痰热，数主热盛。胸膈肌肤热势大减，额上解而不了了，舌绛苔少，疳点起腐痛甚，心中烦扰，月水将净。此上焦痰热未清，余邪留恋肺胃，故右寸关滑数；左脉静为营分热减之兆。清化上焦痰热为主。", ["滑", "数"]], "16357": ["病机", "脉数颇缓，数主余热未清，缓为邪势渐退之象。舌苔焦黄已化，汗多如注，疳势蔓延亦定，白腐渐退，音闪渴饮，痰多黄厚，口中腻涎若涌。此外邪将净，而脾虚血热，湿火内生，故脉数中见缓，治以玉女煎合甘露饮加减，清化余热、健脾渗湿。", ["数", "缓"]], "16358": ["病机", "脉象数实，数为热盛，实为邪结阳明。疳痛大缓，谷食可进，溲急欲遗，数而且多，余热宿垢蕴结阳明，迫膀胱津液下行；汗泄多而胃津伤，大肠愈燥，口竭引饮，舌苔老黄干裂，根厚浊，按腹微痛，皆急下存阴之确据。", ["数", "实"]], "16359": ["预后", "未识脉名，述昨晚大便后夜卧极安，胃思纳谷，神脉安静，小便合度，肠胃宿垢已彻，余邪下注肛侧结有小瘰，痉厥时擦伤皮肤滋水频滋，两相蔓延痛楚。神脉安静、纳谷为邪退正安之兆，虽微末节外生枝，不妨眠食，预后向好。", []], "16360": ["病机", "关脉弦数，弦为肝木之象，数为血分有热。原文谓“属血分之邪发越，肝木并逆也”，说明痢后余邪未清，郁于血分而化热，肝木之气因而上逆。虽痛在胃脘，但食下不作痛，可知非胃腑实积，乃肝经血分郁热循经上扰所致。舌苔渐化、纳谷较增、痢畅而稀，为邪有外达之机，弦数正是邪热发越、肝逆未平之征。", ["弦", "数"]], "16361": ["病机", "脉细为气血不足之象，舌白主寒湿。原文言“肝火湿热下注阳明之络，外束风寒”，两腿痛甚、艰于步履，是外寒束于肌表、湿热流注络脉。脉细而非浮紧，说明内伤虚痹为本，气血亏虚不能充脉，外风仅为其标。故虽先疏解外风，然“症系内伤虚痹，最属淹缠”，脉细正提示正虚难复、病程缠绵之机。", ["细"]], "16362": ["病机", "左脉转数，数为热象，左脉候肝。原文谓“外风已渐化火”，环跳痛缓而移于内臁，是邪从外入里、化热之征。阳明主一身之络，气血亏则络脉失灌，郁火湿热乘隙内踞而作痛。数脉在此非单纯外感，乃内伤气血不足、郁火湿热相合之象，与去秋流注“病虽异而其源则一”，皆根于血亏络空、湿热乘虚。", ["数"]], "16363": ["病机", "脉软带弦，软为气血不足、筋脉失养，弦为肝风内动、络脉拘急。原文谓“肝风湿热逗留经络，痹痛夜甚”，舌红苔黄为湿热之征。脉软说明正气已虚，弦则示风邪未息，故“不宜峻剂，攻风劫痰，再伤血液”，恐血枯筋挛而肢废，或痹乘中土而腹胀。此脉反映虚中夹实、血亏风动之病机，治当养肝阴、化瘀定痛。", ["软", "弦"]], "16364": ["预后", "脉数和，是邪退正复之象；舌苔稍化，亦为湿热渐解之征。原文“昨宵痛缓得寐”，说明气血渐和、痹痛减轻。病由气血两亏，用药须慎其偏胜，脉虽转和数而未全平，故以萎蕤加味养阴和血。此段以脉症好转言预后，数而不躁、和而渐平，提示药后气机调畅、病势向愈，但仍需缓调气血，防其反复。", ["数", "和"]], "16365": ["病机", "脉弦濡，弦主邪郁少阳、太阴，濡主湿浊内蕴。原文谓“痰阻胃阳恶心，暑邪乘虚内陷”，大疟四发而神疲纳少，舌白腻，是暑湿痰浊内困太阴、胃阳不展。弦为邪正交争之象，濡为湿邪黏滞之征，故言“邪在太阴，达之非易”，正虚邪陷、湿浊难化，须以东垣法升阳化湿、扶正达邪。", ["弦", "濡"]], "16366": ["预后", "脉尚弱，弱为气血两亏、正气未复之象。原文谓高年气阴两亏之体，痢已全止、邪达迅速，诚为大幸，然纳谷未旺、神脉尚弱，说明邪虽去而正未充。脉弱在此非死候，乃病后气阴未复之征，故拟益气生津以恢复之。此段以脉弱言预后，提示邪退正虚、需缓补调养，不可峻补碍胃。", ["弱"]], "16367": ["病机", "脉细如丝，为阴血亏耗、阳气式微之象。原文述气不摄血而血崩阴伤，又患大疟及产，产后腹胀如臌，病已磨久，腹大依然，半月或旬日一发。细如丝说明肝脾两伤、气血俱损，阳气不能温运，阴血不能充脉，故“当从症治之”，仿仲景法温阳利水、扶正消臌，非单纯攻邪可解。", ["细"]], "16368": ["预后", "原文述“阳回脉起”，虽未明言脉象，但“脉起”指脉由沉伏转为应指有力，为阳气来复之征。舌强渐平、肿胀亦减、神情颇振，皆气旺阳回之象。脉起与症减相应，说明正气渐复，故拟血脱益气法以固本，防便血崩漏，此为病之扼要。", []], "16369": ["预后", "原文“神脉皆段”中“段”通“断”，指脉气断续不续。交节前后便血未行，而神脉皆断，说明正气衰败，脉道不利，虽有便血未行，亦非佳兆。脉断与神衰并见，提示气血将竭，预后堪忧，故列于预后门。", []], "16370": ["妇人", "原文“癸水甫净”指月经刚净，此时血海空虚，奇经八脉失养。虽未言脉，但以养心脾佐调奇脉为法，说明病机为心脾两虚、奇脉不调。脉象虽未明载，从治法反推，当见细弱或虚缓之脉，主气血不足、冲任失和。", []], "16371": ["平脉", "原文“脉情和缓”指脉来从容和缓，为营卫气血流通之常脉。和缓之脉说明脾胃气旺、气血调畅，故曰“营卫气血流通”。此时拟培养奇经八脉、佐理肝脾，是借脉和之机调补奇经，属平脉调理，非病脉主病。", ["缓"]], "16372": ["病机", "原文“脉弦舌红”与乳房结疬、胸膈梗痛如束并见。弦为肝脉，主气郁不舒；舌红为郁久化热。乳房属阳明，肝郁气结于阳明部分，故结疬大小不一、痛则坚大。脉弦舌红正合“一派肝郁”之机，有关格根柢，宜怡养。", ["弦"]], "16373": ["病机", "原文未载具体脉象，但“脉症合参”后断为“营虚肝郁”。乳疬痛缓胀松、胸脘亦舒，说明气郁稍解而营血不足。脉虽未明言，从营虚肝郁推之，当见细弦或虚弦之象，主血虚肝郁、气机不畅，故痛胀得缓而病根未除。", []], "16374": ["病机", "原文“脉尚濡数”见于暑风暑热蕴伏于经、壮热汗出之后。濡主湿，数主热，濡数并见说明暑热未清、湿邪未化，伏邪留连气分。虽表热退净，但脉仍濡数，故曰“伏邪未必即化”，转疟可虑。舌红苔黄亦为湿热内蕴之征。", ["濡", "数"]], "16375": ["妇人", "原文“脉胎已至脱根”指妊娠脉象浮散无根，为胎气不固之兆。经居三月余，骤然腹痛酸坠，曾有小产，手厥阴经络受伤，气从下陷，脉失根柢，故深恐血崩。脉脱根与腹痛下坠并见，主胎元不固、气血下陷，属妇人胎漏危候。", []], "16376": ["预后", "脉细无神，为血崩后血去胎伤、正气衰败之象。原文见胎元跃跃、烦热、形冷发搐、神志模糊，乃血去胎殒、浊阴上蒙清窍，故脉细而无神，属至危至险之候。", ["细"]], "16377": ["预后", "原文谓“神脉皆涉和平”，虽瘀露下而黑色、停瘀未化，但胃纳渐安、寐稳，脉象和平，示正气渐复、病势向安；然恐胎元未化，故仍宜留意。", []], "16378": ["其他", "原文未出脉名，仅言“脉息稍静”，乃益阴通瘀后正气渐醒、夜寐得安之征。瘀中下茄蒂之象，即胞胎之根柢，故前日停经、崩漏之疑可剖判分明，仍守昨法。", []], "16379": ["病机", "脉见芤数，为小产后肝肾阴虚、虚阳易升之象。芤主阴血不足，数主虚阳浮动，故见汗泄气急；阳衰已复而阴血难速长，眠食向安，仍须百日慎养。", ["芤", "数"]], "16380": ["病机", "右寸关尚弦数，由盗汗自汗互伤营液，肝阳偏亢、虚热内扰，故易于心悸。今瘀已净，色㿠已转，可以补中寓收摄，使营液渐复而弦数自平。", ["弦", "数"]], "16381": ["病机", "脉细，左部虚细，右寸关弦数，为产虚未复、郁怒动肝、肝火上薰肺胃之象。虚细主阴血亏虚，弦数主肝火偏亢，故寅卯咳呛、五心烦热，虑涉损途。", ["细", "虚", "弦", "数"]], "16382": ["病机", "脉左见数象，胁中刺痛，为产后营虚肝郁、郁而化热之征。数主热，左关候肝，肝郁化火则胁痛；癸水先期、舌心露质，亦营虚内热之象。", ["数"]], "16383": ["病机", "脉息左部弦数，右尺虚软，为产后营虚肝郁、毓阴不足之象。弦数主肝郁化火，故寅卯咳呛；右尺虚软主肾阴亏虚，经事乍过，故以毓阴平肝为主。", ["弦", "数", "虚", "软"]], "16384": ["病机", "原文未明脉象，然述肝阳化火生风，冲脉之气逆而乘胃，巅顶胀痛、面肌跳跃，皆风阳上扰之征。烦劳则阳气越胃凌心，致煎厥，显系肝肾阴亏、阳亢失潜。进滋纳肾肝得平，佐证病本在阴弱阳浮。治宗镇守中州以靖逆气，即培土宁风、潜降逆气之法。", []], "16385": ["病机", "左脉细弦，细为阴血不足，弦乃肝阳偏亢。肝火逆上触心络，血从口溢盈碗，是火迫血溢。近增便泄，暑湿内袭，胃气衰则谷气少而旋晕。脉细弦应胃气虚馁、肝木乘之，故治以益气清暑，兼顾中州，非单纯凉血止血所宜。", ["细", "弦"]], "16386": ["病机", "脉息细数，细主阴血亏虚，数主虚热内扰。心脾两亏，经行先期、心悸寐少、舌心光剥，皆营阴暗耗、虚热迫血之象。气分亦怯，故养血毋庸重滋，恐滋腻碍脾。此脉细数非实火，乃虚热，治当益气养营、清虚热为要。", ["细", "数"]], "16387": ["病机", "左脉数、右脉弦，数主营虚血热，弦主肝阳未靖。哮发虽减半，而心中烦扰、寐不安贴，癸水将至，营虚血热，再防反复。脉左数右弦，示肝血不足而阳偏亢，金水失养。故当加意养金水，滋水涵木，以平其亢逆，非仅治哮。", ["数", "弦"]], "16388": ["预后", "脉形芤数虚弦，芤主失血，数主虚热，虚弦为肝脾气陷、阴血亏耗。便后下血数载，脱肛、血下无度、小溲淋痛、寒热时作、舌光起刺，皆阴血下夺、虚风内动之候。情志内伤，药力难奏，秋令肃降，虑血从下脱，故列预后之戒。", ["芤", "数", "虚", "弦"]], "16389": ["病机", "脉弦舌红，弦主肝郁，红为热象。郁火湿热内伤肝脾，痰火化风，升扰阳明，故有类中之机，防眩晕倾跌。脉弦应肝风内动，舌红示热灼阴伤。此非外风，乃内伤积热生风，治当清火化痰、平肝息风，以杜中厥之变。", ["弦"]], "16390": ["误治", "脉洪而无力，洪为热盛，无力为虚，合之不渴、舌黑谵语，乃伤寒化虚热，非实热实结。诸医误认大承气，几致虚虚。以姜片擦舌即淡，更证热非实。用人参竹叶石膏汤益气清热，一服见效。此案示辨虚实之要，误治则死生反掌。", ["洪", "虚"]], "16391": ["妇人", "脉虚，知为血晕非肝风。产时搐搦、不省人事，若肝风则脉当弦劲，今脉虚乃血去过多、气随血脱之候。用韭菜根醋熏鼻取嚏，立时苏醒，继以当归参耆千金汤补气血而安。脉虚为辨证眼目，误作肝风则差之毫厘，失之千里。", ["虚"]], "16392": ["病机", "脉沉濡而滑相等，沉主里，濡主气血不足，滑主痰湿内蕴。患者伤寒误用凉药，病剧卧床，痰喘欲绝，此脉象示正气尚存，痰湿未化，故尚可挽回。后脉缓和无力，为气血渐复但未充盛，故用十全大补汤调补，不至残疾。", ["沉", "濡", "滑"]], "16393": ["病机", "脉濡主气血虚弱。患者体素弱，小产胎不下十余日，误服攻伐，重伤气血，以致血竭而胎不下。脉濡正合气血两虚之机，故用十全大补汤助气血，加朴硝化死胎，后以生化汤加参耆扶气血而愈。", ["濡"]], "16394": ["病机", "脉急有力，急主邪盛，有力为实，示寒化为邪，邪正相争。虽年逾五旬，痢疾昼夜百余次，汗出如流，似有脱象，但脉实有力，知非虚脱，故用黄芩汤加减扶正清热，一服见效。后以真人养脏汤滋阴固摄收功。", ["急", "有", "力"]], "16395": ["病机", "脉洪实有力，洪主热盛，实主邪实，有力为正气未衰。痘出色紫周身无缝，登屋狂叫，舌苔黑，皆热毒炽盛之象。脉证相合，故用归宗汤去热邪燥粪，犀角地黄清热透发而愈。后脉细，细主正虚，知系卒中，非瘟病，故用小续命加参耆而效。", ["洪", "实", "有", "力"]], "16396": ["病机", "脉数无力，数主热，无力为虚，知为虚热，非实火。牙疼面肿，太阳筋跳如锥痛，乃气血相搏，邪火上蒸。故内服玉女煎加减滋阴退虚热，外以熏洗、热手巾、烧酒等法和气血，痛止肿消而愈。", ["数", "无", "力"]], "16397": ["病机", "脉沉细，沉主里，细主虚，知系虚寒气结。腹疼如绞，日久欲死，他医误用凉药病剧，正合虚寒之机，故用附子理中汤加减一服而愈。后脉虚细，为九结中之秘结，不可攻下，以前方加润导之品便而愈。", ["沉", "细"]], "16398": ["病机", "脉沉细，沉主里，细主阴亏。淋症误以血淋苦寒之药，数月病剧，卧床不起，仅存一息。脉沉细知为阴亏变色，非血淋也。因思想而得，欲心一动，精却离舍成淋，久则阴亏，故用人参菟丝丸大补心肾而愈。", ["沉", "细"]], "16399": ["病机", "脉沉细，沉主里，细主虚。产后病剧，四肢拘挛，瘫痿溺黑，知受风寒化热为痹，故用独活寄生汤加减而愈。后脉沉无力，为气血两虚，故用泰山磐石散、千金保胎丸合参以安胎。临产脉缓，舌苔面色无青赤，知胎无恙，非死胎也。", ["沉", "细"]], "16400": ["病机", "少阳脉弦，知为虚痞。脉弦主少阳枢机不利，气机郁滞，故见腹胀如鼓、癃闭。因寒致癃闭，非实热壅塞，乃虚痞使然。弦脉应肝胆，少阳受邪，疏泄失职，水液不行，故以柴胡半夏茯苓汤和解少阳、化气行水，汗解溺畅而愈。", ["弦"]], "16401": ["妇人", "六脉相等，阳搏阴别，孕兆也。脉象平和匀等，而阴阳有别，为妊娠之征。虽年近四旬，气血渐衰，素有肝气，胎气引动故胸胀大痛。世医误以经闭症瘕，几危。以手试腹如伏杂状，即知是胎非病。脉相等而阳搏阴别，正是胎孕气血调和之象。", []], "16402": ["病机", "脉洪无力，知为虚热。洪为热盛之象，无力则非实热，乃虚火上炎。世医误以瘟病苦寒治之，更伤阳气，致不眠谵语、狂叫大热、舌苔黑刺。以姜擦舌即白，的为伤寒非瘟。虚火内无实热，故以人参竹叶汤加减引火归原，四服全愈。", ["洪", "虚"]], "16403": ["病机", "脉沉紧，知寒邪入里。沉主里，紧主寒，世医误以犀角羚羊角等寒凉之品引邪入内，致不能言语。沉紧为寒邪闭阻、阳气不伸之象，故用羌活汤加附子肉桂温散寒邪，去黄芩生地之寒，一服能言发疹而愈。", ["沉", "紧"]], "16404": ["预后", "脉数不及，知为胃气欲绝之象。数而无力，乃虚阳外浮、胃气衰败之征。时医误以冬瘟苦寒治二十余日，伤败胃气，致烦躁不省人事、不能合眼。脉数不及示胃气将绝，故以人参汤加减引火归原，一服遂眠，复诊调治月余全愈。", ["数"]], "16405": ["病机", "脉浮数，知为风寒化热无汗。浮主表，数主热，风寒束表，郁而化热，故谵语暴病惊人。无汗则邪未外解，热郁于表。拟羌活汤加减解表散邪，一服汗解而愈。浮数之脉，正是表邪未解、郁热内扰之象。", ["浮", "数"]], "16406": ["病机", "脉沉细，知肺胃肾虚，火上冲喉咙成痹。沉主里，细主虚，虚火上炎故喉肿水不下咽。时医误以温补助邪，致项肿。沉细为阴亏火浮之象，最忌刀针及温散凉伏。先刺少商商阳出黑血浅毒，吹药消毒，以滋阴清肺汤加减和解，外溃内消而愈。", ["沉", "细"]], "16407": ["病机", "脉紧数，知系闭塞寒邪，化热痰喘。紧主寒，数主热，寒邪外束，郁而化热，痰喘不眠。时医以年老气衰重用参耆补药，固邪于内，病剧。紧数示寒邪未解而热已生，故以小青龙汤加减解寒疏肺化痰，开门逐盗，十日而愈。", ["紧", "数"]], "16408": ["病机", "脉涩无寒症，说明腹痛非寒邪所致。涩脉主气滞血瘀或虫积内阻，气血运行不畅。前医误用姜附肉桂温燥，反伤阴血，故疼逾甚。结合便出长白虫，可知虫积肠道，气机壅塞，脉道不利而涩。此脉涩不伴寒象，正是辨虫积之关键，与腹痛如绞、便虫相应。", ["涩"]], "16409": ["病机", "脉沉细，沉主里，细主虚，为气血亏虚之象。目昏花不能视物，前医作肝热清风退火，更伤气血，故病逾甚。沉细脉提示气亏内障，非实火，故用八味还睛散去风药、重加参耆补气而愈。此脉与目昏、气亏相应，说明病机在气虚不能上荣于目。", ["沉", "细"]], "16410": ["病机", "脉沉虚，年逾六旬，沉主里，虚主不足，为气虚下陷、阴血亏虚之象。脱肛肿痛，前医误作痔疮，肿疼逾甚。沉虚脉说明中气不足、升提无力，兼阴血亏虚，故内服滋阴清提补药而顿缩。此脉与脱肛便血相应，病机属气虚下陷兼阴亏。", ["沉", "虚"]], "16411": ["病机", "脉紧间日一发，紧主寒邪束表、少阳枢机不利。瘅疟先冷后热、谵语，误服凉药病剧，紧脉说明寒邪未解、疟邪伏于少阳。用清脾饮加减和解少阳，后诊脉见缓，知邪将解，疟止。此脉紧与间日发、先冷后热相应，病机为少阳不和、寒热交争。", ["紧"]], "16412": ["病机", "脉洪数，洪主热盛，数主邪热，为风寒闭肺、郁而化热之象。咳嗽昼夜不止、痰吐成盆，前医误用参茸温补，痰咳逾甚。洪数脉说明风寒闭于肺中，郁热不得宣散。其子黄疸秘结脉沉细，沉细主虚，为虚黄秘结，气血不足。两脉对比，一实一虚，各主其病。", ["洪", "数", "沉", "细"]], "16413": ["妇人", "脉和缓和，缓为胃气调和之象，和缓说明气血冲和、胎元未伤。胎中漏血而脉不躁不数，知胎漏而胎未动，非热迫血妄行。故用安胎养血之品，每月行血如经，十月而生，母子安然。此脉和缓与胎漏相应，说明病机在血虚胎漏，胎气尚安。", ["缓", "和"]], "16414": ["病机", "脉洪无力，洪主热盛，无力主正虚，为虚火上炎之象。病狂上屋，前医均用犀角三黄汤苦寒直折，不知风寒未解。洪而无力说明非实火，乃风寒未解、虚火上炎，故用参苓甘露饮加柴胡和解而愈。此脉与狂躁相应，病机属本虚标热、风寒未解。", ["洪", "无", "力"]], "16415": ["病机", "脉沉涩，沉主里、主气滞，涩主血瘀、郁结，为郁结气厥之象。每厥不省人事，诸医作肝风治不效。沉涩脉说明气机郁结于里，非肝风内动。询知张公纳妾、寝妾处时多，夫人气郁而厥。调气和血、劝常宿夫人房，数服而愈。此脉与气厥相应，病机为情志郁结、气机逆乱。", ["沉", "涩"]], "16416": ["病机", "脉涩为气机郁滞，血行不畅之象。小姐年已及笄，病剧而脉涩，知为情志不遂，气郁化火，故询其母氏、兄嫂，皆因家庭不和而病。气郁则脉道涩滞，非虚非实，治以调气之品，气顺则脉通，数服而愈。", ["涩"]], "16417": ["主病", "产后伤寒，谵语病重，脉紧有力，紧主寒邪，有力为实，知寒邪束表，内传阳明，故谵语。拟葛根汤合生化汤和解，一服汗澈而愈，紧脉去则邪解。", ["紧", "有力"]], "16418": ["病机", "疟病数月，脉沉紧，沉主里，紧主寒，知邪伏于太阴少阳之间，非表邪也。故用清脾饮加减，重草果以解两经之邪，外用椒蒜泥敷关脉，泄邪而愈。", ["沉", "紧"]], "16419": ["妇人", "脉流利不绝，为妊娠之象，虽夫人言无孕，而脉象昭然。故以安胎养血治之，后胎动举子。此段以脉断孕，非病脉也，属妇人妊娠脉法。", []], "16420": ["病机", "脉细为气虚，中满而脉细，知非实胀，乃气虚不运，胀满由虚所致。故用补中益气汤，补气则胀消，数服遂愈。细脉主虚，此其验也。", ["细"]], "16421": ["主病", "痢下日厕无数，他医误用桂附，病剧。脉数知系热邪，数主热，热邪内迫，故痢无度。拟黄芩汤加减，清热而痢减，后以养脏汤收功。", ["数"]], "16422": ["病机", "咳喘呕逆，脉七八至将绝，数而无力，乃虚热之象，非实热也。前医误用石膏、黄连，更伤阴阳。陈冠生辨脉数无力为灯油将尽，不可再清，宜救垂绝之阴阳，故用肾气汤加减。", ["数"]], "16423": ["妇人", "脉阴搏阳别，左大右小，为妊娠喜脉。阴搏阳别者，尺脉搏指与寸口有别，左大右小亦孕兆。故断为弄璋之兆，按月请诊，果举一男。此段以脉断孕，属妇人脉法。", []], "16424": ["主病", "脉沉主里，知为新受寒邪滞气，非热症。寒邪内侵，气机凝滞，胃脘作痛，故脉沉而不数。他医误为热症，余以脉论，的寒非热，拟排气饮加减温通，遂愈。", ["沉"]], "16425": ["病机", "脉来沉滑，沉主里，滑主痰湿。湿痰入络，荣卫交阻，故肢节作痛尚未全止；呛咳鼻塞痰多口干皆退，肝阳上亢之势已平，肺气下降。脉沉滑示湿痰内蕴，络脉不通。", ["沉", "滑"]], "16426": ["病机", "脉来沉弦而滑，沉主里，弦主肝，滑主痰湿。肝阳升腾无制，挟素蕴之湿痰流窜节络，荣卫不能通行，故右手无名、小指麻木作胀。脉沉弦滑示肝阳挟痰湿内阻。", ["沉", "弦", "滑"]], "16427": ["病机", "脉来沉弦而滑，脉症皆实。肝阳挟湿痰热流窜节络，筋络缩短，手足肩臂作痛浮肿，内热烦躁，齿痛苔黄，胸脘不舒，腹胀且硬。湿火痰热充塞三焦，流行之气皆阻，故脉沉弦滑而实。", ["沉", "弦", "滑"]], "16428": ["病机", "脉来沉弦而滑，沉主里，弦主肝，滑主痰。湿痰流窜节络，荣卫不能通行，故左肩臂酸痛、手指麻木；湿痰阻胃，宣布无权，故纳谷无多、动则气疾。脉沉弦滑示湿痰阻络兼胃气不和。", ["沉", "弦", "滑"]], "16429": ["病机", "脉来沉弦而滑，沉主里，弦主肝，滑主痰湿。阴血久虚，肝阳上亢，挟湿痰阻塞包络，胃气宣布无权，故脘闷气郁、目泪时下、肢节麻木阴酸、胸腹作胀、头眩欲跌。脉沉弦滑示肝阳挟痰湿内阻。", ["沉", "弦", "滑"]], "16430": ["预后", "脉弦之象稍减，沉细如常，示肝阳渐平，胃气宣布，胸脘痞闷、气短头眩、手指麻木已退。惟肾阴久亏，摄纳无权，遗精眼花、见色流精、小溲甚多、不能静坐。脉弦减而沉细，为肝阳退而肾虚未复之象。", ["弦", "沉", "细"]], "16431": ["病机", "脉来沉弦而滑，沉主里，弦主肝，滑主痰湿。肝阳上升，挟素蕴之湿痰阻塞胃气，宣布无权，故脘闷作恶、呕吐黄水、饮食少进；湿痰渐化，荣卫交阻，故肢节麻木作痛。脉沉弦滑示肝阳挟痰湿阻胃。", ["沉", "弦", "滑"]], "16432": ["病机", "脉来弦细，弦为肝阳升腾之势未靖，细为肺阴久虚、清肃无权。肝阳渐平而筋络酸痛、内热口干未退，呛咳日久、头眩眼花，皆肺阴亏虚、肝阳上扰之候。弦细并见，示肝阳未潜、肺阴不复，故治宜清肃肺气兼治肝阳。", ["弦", "细"]], "16433": ["病机", "脉来弦细而数，弦为肝阳升腾无制，细为阴血久虚，数为内热之征。肝阳上灼胃阴，胃失降令，故脘闷腹痛、内热口干、头眩且疼；阴血亏虚、筋络失养，则肢节酸痛、腰酸带下。弦细数并见，主阴血虚而肝阳亢、兼有内热。", ["弦", "细", "数"]], "16434": ["病机", "脉来细弦，细为脾肾久虚、中无砥柱、下少生发之气，弦为肝阳上升。肝阳挟湿痰流窜节络，荣卫不能通行，故左手臂麻木上及头面；痰阻肺气已著，则呛咳气喘。细弦之脉，示正虚而肝阳挟痰为患，治宜益肾清肝、运脾化痰。", ["细", "弦"]], "16435": ["病机", "脉弦略退，知肝阳升腾之势已缓；沉滑仍然，沉主里、滑主痰湿，示湿痰入络、荣卫不能通行之机未解。呛咳鼻塞、痰多口干、肢节作痛较前已减而未尽退，正合弦退而滑存之象。故宜宗前法进治，继续化湿痰、通荣卫。", ["弦", "滑"]], "16436": ["病机", "脉来细弦，细为脾胃久虚、气血不足，弦为湿热痰浊内阻。脾胃久虚则湿热下注，腿足暮肿朝消、大便溏泄；湿热痰上阻肺气，则右手臂麻木、呛咳口干。细弦并见，示正虚而湿热痰为患，故宜健脾化湿、消痰肃肺。", ["细", "弦"]], "16437": ["病机", "脉来细弦而数，细为阴分不足，弦为湿热郁阻、气机不畅，数为湿热内蒸。湿热无从宣泄，上阻清道，肺金清肃之令不能下行，故呛咳喉痛、牵引胸腹有如带束；湿热结于头面颈项，则起颗结块。细弦数并见，主湿热内蕴而阴液已伤。", ["细", "弦", "数"]], "16438": ["病机", "脉来细缓，细为阴液已虚，缓为湿热内蕴、虫积于中。湿热生虫，故寸白虫随大便而下，或不大便而从肛门而出。细缓之脉，非虚寒之缓，乃湿热蕴结、正气渐耗之象，故原文谓「阴液已虚，湿热内蕴，已可概见」，治宜清化湿热并益阴清肝。", ["细", "缓"]], "16439": ["病机", "脉来浮滑，浮主病在表分，滑主湿热痰浊。肺有湿热，散布分肉之间，故体热咳嗽、肌肤起颗作痒破碎、略有脂水即易结痂。湿热里达于表，脉应之而浮滑，原文谓「最是佳征」，示湿热有外透之势，故治宜清化湿热兼肃肺气，令湿热尽透于外。", ["浮", "滑"]], "16440": ["病机", "脉沉细而弦，沉主里、细主虚、弦主肝木乘脾。原文脾土久虚、运化无权，湿热淆乱清浊，升降失常，故脉见沉细而弦。弦为土虚木贼之象，与胸腹胀痛、泄泻带红、内热口干、小溲不利、纳谷无多相应，总属脾虚湿盛、肝木偏旺之病机。", ["沉", "细", "弦"]], "16441": ["病机", "脉来沉细，沉为湿热蕴结于里，细为阴分受灼。原文湿热下注、膀胱气化无权，小溲茎中作痛、白浊时下，又因投补太早禁锢湿热，无从宣泄而蕴结于中。沉细正合湿遏热伏、气化不利之机，与茎痛、白浊相应，故治宜清化湿热兼养阴调气。", ["沉", "细"]], "16442": ["病机", "脉来沉细，沉主里、细主阴血不足。原文肾阴久虚、封藏不固，湿热下注、销铄荣阴，故虽呛咳内热口干自汗已减，而遗精便血、小溲浑浊未除。沉细为肾虚不固、湿热伤阴之征，与遗精便血、溲浊相应，治宜益肾化湿清肝。", ["沉", "细"]], "16443": ["病机", "脉来细弦，细为气血耗伤，弦为肝阳上升。原文脾胃久虚、中无砥柱之权、下少生发之气，肝阳上升挟素蕴湿痰，耗气灼阴、流灌失职，故脉细弦。此脉与内热口干、头眩神倦相应，主脾肾两虚、肝阳挟痰之病机，治宜脾肾并补、清肝化痰。", ["细", "弦"]], "16444": ["病机", "脉来沉细，沉主里、细主虚。原文胸腹作痛已止、大便亦调、湿痰渐化、胃气通降，惟脾土未健、运化失职，故腹胀贲响、夜寐不酣而脉仍沉细。此脉示湿痰虽减而脾虚未复，属脾运不健、湿滞内停之病机，治宜健脾渗湿兼和胃气。", ["沉", "细"]], "16445": ["病机", "脉弦已减而沉细如常，弦减示肝木渐平、湿热下泄、胃气宣布，故大便通畅、胸腹较舒、呕吐亦止；沉细如常则示脾失运化之权、肾少生发之气未复，故纳谷运化不速、腿足软弱无力。此脉主脾肾气虚、湿滞未净之病机，宜宗前法进治。", ["弦", "沉", "细"]], "16446": ["病机", "脉来弦滑，弦主痰饮气逆，滑主湿痰壅盛。原文湿痰上阻肺络、肺气不降、肾气不纳，呛咳气疾举发无常，甚则喉际痰声漉漉，寝食俱废，抱恙多年根深蒂固。弦滑正合湿痰阻络、肺肾不纳之机，与呛咳痰声相应，治宜渗湿消痰兼肃肺气。", ["弦", "滑"]], "16447": ["病机", "脉来沉细而滑，沉细主脾虚，滑主痰湿内壅。原文脾土不运、积湿生痰、阻塞胃气不能下降，故胸脘痞闷、饮食少进不易消化、苔黄神倦、四肢无力。沉细而滑正合脾虚生痰、胃气不降之病机，与痞闷少食、苔黄神倦相应，治宜健脾化食、消痰和胃。", ["沉", "细", "滑"]], "16448": ["病机", "脉来沉细，沉主里、细主虚，与文中“脾肾久虚，中无砥柱之权，下少生发之气”相应。湿痰虽化、呕止便通，然精神萎顿、腿足软弱，正是脾肾虚衰、气血不足之象，脉沉细为里虚不足之征，主脾肾两亏、正气未复。", ["沉", "细"]], "16449": ["病机", "脉来沉弦，沉为在里，弦主肝木。原文谓“脾肾久虚，肝阳上亢，耗气灼阴”，内热口干、头眩目赤皆肝阳上扰之症。湿痰渐化而气机未畅，脾肾虚于下、肝阳亢于上，脉沉弦正合里虚而肝旺之病机。", ["沉", "弦"]], "16450": ["病机", "脉来细弦，细为血虚，弦为肝旺。原文“肝气上升，克脾犯胃，土受木制”，积湿生痰、胸胁作痛、受寒咳嗽，皆木克土、痰阻气机之候；居经不行四载，亦因血虚肝郁。脉细弦主肝旺脾弱、血少痰凝之病机。", ["细", "弦"]], "16451": ["病机", "脉来细弦，细主虚、弦主肝。原文“脾肾久虚，中失运化之权，下少生发之气，积湿生痰，阻塞气机”，故胸腹胀痛贲响、便溏或结、便后带血。脉细弦示脾肾虚而肝木乘之、湿痰内阻，主虚中夹实之病机。", ["细", "弦"]], "16452": ["病机", "脉来细弦，细为脾肾不足，弦为肝气偏旺。原文“脾肾久虚，中失运化之权……积湿生痰，阻塞胃气，不能下降”，故胸腹胁肋胀痛、纳谷无多。脉细弦正反映虚体之中湿痰阻胃、肝木不舒，主脾肾虚而痰阻气滞。", ["细", "弦"]], "16453": ["病机", "脉来沉细而弦，沉细主肾虚里弱，弦主肝阳。原文“肾气久虚，肝阳上升，湿痰阻塞，胃气宣布无权”，故纳少难化、口干破碎、腿足怯冷、便溏日二三行。脉沉细弦示下元虚寒、肝阳上扰、湿痰中阻，主虚实错杂之病机。", ["沉", "细", "弦"]], "16454": ["病机", "原文“脉弦已减，沉细仍然”，弦减示肝旺渐平、湿痰渐化，故胸脘较舒、大便亦调；沉细仍在，则脾土久虚、运化无权未复，腹内结块、咯痰觉冷、纳谷无多皆虚寒痰凝之候。脉象变化正合病情进退，主脾虚痰结之病机。", ["弦", "沉", "细"]], "16455": ["病机", "脉来沉弦而滑，沉主里、弦主肝脾、滑主痰湿。原文“脾土久虚，运化无权，积湿生痰，阻塞肺气”，故呛咳气喘、脘闷鼻塞、喉际痰声漉漉。脉沉弦滑正为痰湿内盛、肺气不降之征，主脾虚痰阻、肺失肃降之病机。", ["沉", "弦", "滑"]], "16456": ["病机", "脉来沉细而弦，沉主里、细主虚、弦主湿郁气滞。原文谓脾土久虚、运化无权，积湿蕴结阻塞胃气，故脉沉细示脾虚，弦示湿阻气机。胸腹不舒、纳谷无多、大便溏薄皆脾虚湿困之症，脉症相合，主病机为脾虚湿阻、胃气失和。", ["沉", "细", "弦"]], "16457": ["病机", "脉来细弦而数，细为阴伤，弦为肝阳亢逆，数为痰热内灼。原文谓肝阳上升、挟痰热销铄津液，故内热口干、头眩作痛、眼花痰多。细弦数并见，示肾阴亏而肝阳化火挟痰，脾失运化，病机为阴虚阳亢、痰热内扰。", ["细", "弦", "数"]], "16458": ["病机", "脉来细弦而数，细主阴伤，弦主肝郁，数主湿热内蒸。原文谓湿热无从宣泄，肺金清肃之令不能下行，故呛咳喉痛、胸腹如带束、头面颈项手臂起颗结块。细弦数示湿热郁遏、肝肺气机不畅，病机为湿热蕴结、肺失肃降。", ["细", "弦", "数"]], "16459": ["病机", "脉来浮弦而滑，浮主外邪，弦主风邪犯肺、气机郁滞，滑主痰食内积。原文谓饮食不节兼受风邪，肺不清肃、胃不宣通，故呛咳鼻塞头痛、胸腹贲响、食入疼胀。浮弦滑示外风引动内滞，病机为风邪外袭、痰食内阻、肺胃失和。", ["浮", "弦", "滑"]], "16460": ["病机", "脉来弦滑，弦主肝阳化火，滑主痰热内盛。原文谓肾阴久虚、水不涵木，肝阳化火挟痰热上阻包络，神明无主，故神昏发厥、肢节抽掣。弦滑示肝阳痰热鸱张，病机为阴虚阳亢、痰热蒙蔽包络，属本虚标实之候。", ["弦", "滑"]], "16461": ["病机", "脉弦略迟、沉细如常，弦为肝阳未靖，迟为阳气不足，沉细为肾阴久虚。原文谓肝阳升腾之势渐平，脘痛已止，惟头眩心悸、小溲频数，乃肾阴久虚、下失封藏之固。脉弦迟沉细示阳亢渐敛而肾虚未复，病机为肾阴亏虚、封藏失职。", ["弦", "迟", "沉", "细"]], "16462": ["病机", "脉来弦滑，弦主肝阳亢逆，滑主湿痰内壅。原文谓肝阳上升挟湿痰阻塞肺胃，宣布无权，故呛咳脘闷、饮食少进、疝气偏坠于右、睪丸胀大作痛。弦滑示肝经痰湿郁滞，病机为肝阳挟痰湿阻滞肺胃、下注厥阴。", ["弦", "滑"]], "16463": ["预后", "原文谓脉弦已退，风邪外解，此以脉象变化判断外感风邪已解之预后。弦脉本主风邪郁滞，今弦退则知表邪渐散。然肺肾阴虚、湿热下注未除，故屡次遗精、溲前带浊、间或呛咳。脉弦退示邪减，病机转以阴虚湿热为主。", ["弦"]], "16464": ["病机", "脉来弦细软，弦为肝郁化火，细为阴血亏虚，软为胃气冲和不足。肝火销铄肺胃阴液，故呛咳内热、口渴引饮、饮食少进；阴血枯涸、心神失养，入夜神迷谵语，干血痨症已成。脉象正示阴亏火旺而胃气已弱之机。", ["弦", "细", "软"]], "16465": ["病机", "脉来弦细而数，弦主肝阳升腾无制，细主阴血久虚，数主火旺销铄。肝阳上灼肺阴，金受火刑，清肃无权，故呛咳、内热、口干、头眩、卧难著右；阴血亏而居经不行，势已入损。脉象示阴虚阳亢、火刑肺金之病机。", ["弦", "细", "数"]], "16466": ["病机", "脉弦略退，知肝阳升腾之势渐平，胃气下降，故内热口干较减；然细数如常，示肺阴久虚、清肃无权未复，呛咳头眩、卧难著右、居经不行仍在。弦退而细数存，正是标热稍缓、本虚未复之象，故宜宗前法进治。", ["弦", "细", "数"]], "16467": ["病机", "脉弦略退，肝阳上亢之势渐平，故痰带血丝止、内热气急便溏均减；沉细如常，示肺肾阴虚已极、胃气宣布无权，呛咳作恶未尽退。弦退为标缓，沉细为根本虚损，说明病机重在肺肾阴亏、摄纳与宣布失职。", ["弦", "细", "沉"]], "16468": ["病机", "脉来沉细，沉主病在里，细主阴血不足。肝阳升腾之势已缓，肺金清肃下行，故内热口干衄血止、呛咳气急皆减；然纳谷不易消化，示肺肾阴虚、摄纳无权，根本未复。沉细正合里虚阴亏之病机，故仍宗前法。", ["沉", "细"]], "16469": ["病机", "脉弦略退，肝阳升腾之势渐平，津液宣布，故内热苔黄腻退；沉细如常，示肺阴久虚、清肃无权，故呛咳气急牵引胸背、肢节酸痛、夜寐不酣。弦退而沉细存，说明标热渐解而肺阴亏虚之本未复，宜宗前法续治。", ["弦", "沉", "细"]], "16470": ["病机", "脉来弦滑，弦主气机郁滞，滑主痰热内蕴。风邪外解而余邪未清，挟痰热销铄津液，肺气肃降无权，故发热未尽退、咳嗽气急甚则鼻扇。弦滑并见，正示余邪挟痰热壅肺、清肃失降之病机，治宜生金肃肺兼泄余邪。", ["弦", "滑"]], "16471": ["病机", "脉来浮弦，浮主邪在表分，弦主气机不和。风热留恋气分，肺失清肃之权，故发热咳嗽、不思饮食；肺与大肠相表里，脏气不和则府气不宣，故大便不畅。浮弦示邪恋气分、肺气失肃之病机，治宜生津泄邪兼肃肺气。", ["浮", "弦"]], "16472": ["病机", "脉来弦细而数，弦主肝郁，细为阴伤，数示内热。本案咳嗽延久，肺阴受伤，络血上溢，内热口干，脉象与症相应，反映肺阴亏虚、虚热内扰、肝郁化火之病机。势已入损，故脉细数无力，为虚损之候。", ["弦", "细", "数"]], "16473": ["病机", "脉来沉滑，沉主里，滑主痰。本案痰热销铄胃阴，胃气宣布无权，故脘闷咯血、大便不畅；痰热内蕴，肺失清肃，则呛咳气急、鼻塞有血。脉沉滑正是痰热内结、胃阴受伤之象，治宜清化痰热、肃肺和胃。", ["沉", "滑"]], "16474": ["病机", "脉来缓滑，缓为胃气调和之象，滑主痰。本案血分之热已清，咯血止而饮食增，胃气流行，故脉见缓滑；惟肺阴尚虚，清肃无权，呛咳气急未尽退，痰热未净，故滑脉仍在。此脉示胃气渐复而肺中痰热未清之病机。", ["缓", "滑"]], "16475": ["病机", "脉来细数，细为阴血不足，数主内热。本案阴血久虚，肝阳上升，消灼肺胃阴液，故呛咳、内热、口干、喉际作梗、头眩神倦；湿热内蕴，则痰味热腥、痔疮下血。脉细数正合阴血虚而湿热内蕴之病机，治宜清肝和胃、肃肺化湿。", ["细", "数"]], "16476": ["病机", "脉来沉细，沉主里，细主虚。本案湿痰渐化，呛咳气喘未发，惟饮食过多不易消化，胸脘气觉不舒，乃脾土未健、运化无权所致。脉沉细反映脾虚湿滞、运化无力之病机，治宜甘温运脾、化痰肃肺。", ["沉", "细"]], "16477": ["预后", "脉来细弱，细为阴伤，弱为气衰。本案外感风邪化热灼津，肺失清肃，发热三候未解，又大便泄泻，津液愈伤，气失所养，肌肉消瘦，面浮肢肿，苔白不渴。脉细弱示邪少虚多，脱象已著，预后堪忧，故姑拟生津兼泄邪以望转机。", ["细", "弱"]], "16478": ["病机", "脉来弦细，弦主肝郁气滞，细主虚。本案外感风邪挟食滞，淆乱清浊，升降失常，故大便泄泻、少腹作痛、头眩且胀、口干苔白。脉弦细示虚体受邪、肝脾不和、清浊相干之病机，治宜泄邪消食、升清降浊。", ["弦", "细"]], "16479": ["病机", "脉来弦细，弦主肝郁，细主正虚。本案进泄邪消食法后发热退，但内陷肠胃之邪因体虚气弱难以外透，挟食滞耗气灼营，泄泻转为痢疾，红白俱下，少腹作痛，舌苔白腻，口不作干。脉症细参，正虚邪陷，故脉弦细，治宜补散兼行、佐以消导。", ["弦", "细"]], "16480": ["病机", "脉来弦滑，弦主肝旺气机不畅，滑主痰湿内蕴。原文谓湿热已化而余邪未清，风邪乘虚遏抑营卫，胃失降令，故脉见弦滑。弦为风邪扰动、气机郁滞之象，滑为湿浊痰热未净之征，与内热口干、大便溏畅相应，示余邪夹湿滞于中焦。", ["弦", "滑"]], "16481": ["病机", "脉来浮弦，浮主外感风寒在表，弦主气机郁滞、痰湿内阻。原文谓风寒挟素蕴湿痰阻塞气机，肺不清肃、胃不宣通，故脉浮弦。浮为邪在卫表，弦为痰湿壅遏、气不通降，与脘闷腹痛、呕吐痰水、二便不利相应，示表邪与内湿相合为患。", ["浮", "弦"]], "16482": ["病机", "脉来细弱，细主阴血不足，弱主气虚无力。原文谓风邪外解、寒热已退，惟知饥少纳、头昏神倦，胃气未和、宣布无权，故脉见细弱。细弱为脾胃气虚、荣血不足之象，与少纳神倦相应，示病后胃气未复、气血两虚。", ["细", "弱"]], "16483": ["病机", "脉来浮弦，浮主外感风寒在表，弦主气机郁滞、痰湿阻胃。原文谓外感风寒、肺失清肃，湿痰阻胃、气不通降，故脉浮弦。浮为邪犯肺卫，弦为痰湿壅遏中焦，与恶寒咳嗽、胸脘不舒、纳谷无多相应，示表邪未解而痰湿内阻。", ["浮", "弦"]], "16484": ["病机", "脉来弦细，弦主肝阳上亢、气机郁滞，细主荣血亏虚。原文谓脾肾久虚、肝阳上升，挟痰耗气灼荣，流灌失职，病在无形之气，故脉弦细。弦为肝阳挟痰之象，细为荣血不足之征，与内热口干、头眩、胸腹结块作痛相应，示虚中夹实、气聚为患。", ["弦", "细"]], "16485": ["病机", "脉来沉弦而滑，沉主病在里，弦主肝阳上亢，滑主痰热蕴结。原文引「诸风掉眩，皆属于肝」，谓肝阳上升、挟痰灼阴、痰热蕴结已著，故脉沉弦而滑。沉为病位在里，弦为肝阳亢逆，滑为痰热内盛，与头眩偏左、眼花、劳动口干相应，示阴虚阳盛、痰热内蕴。", ["沉", "弦", "滑"]], "16486": ["病机", "脉来弦细，弦主肝阳上灼、气机郁滞，细主荣血久虚。原文谓冲任隶于阳明，荣血久虚、肝阳上灼胃阴、冲任失司，故脉弦细。弦为肝阳亢逆之象，细为荣血亏虚之征，与月事愆期、胸腹胀痛、呕吐头眩相应，示血虚肝旺、冲任失调。", ["弦", "细"]], "16487": ["病机", "脉来沉弦而滑，沉主病在里，弦主肝阳上亢，滑主痰热内蕴。原文谓荣血久虚、肝阳上亢、销灼胃阴、胃失降令，居经不行已三阅月，故脉沉弦而滑。沉为病位在里，弦为肝阳亢逆，滑为痰热内盛，与胸脘不舒、内热口干、头眩相应，示血虚肝旺兼痰热。", ["沉", "弦", "滑"]], "16488": ["病机", "脉来沉细而弦，沉为在里，细为阴血不足，弦为肝阳升腾之象。阴血久虚不能濡养，肝阳无制而上扰，胃失和降，故见胸腹胀痛、纳谷无多、内热口干、苔腻头眩、月事不调。沉细示虚，弦示肝旺，虚中挟亢，正合养血清肝兼和胃气之法。", ["沉", "细", "弦"]], "16489": ["病机", "脉来沉细而弦，沉细主阴血内损、诸经失濡，弦主肝阳升腾无制。阴血亏虚则头眩目燥、腿足阴酸、神疲力乏；肝阳销灼胃阴、胃失降令则脘闷腹胀。脉沉细为虚损之本，弦为肝亢之标，故治宜培补阴血兼潜肝阳。", ["沉", "细", "弦"]], "16490": ["病机", "脉来沉弦而滑，沉弦主肝阳上亢、荣血久虚，滑主痰热内蕴。肝木化火销铄胃阴，胃失降令，故胸腹作痛、内热口干、甚则头眩。原文谓「调胃必先平肝，木火不升，胃气自降」，正说明弦滑之脉反映肝旺挟痰、胃气不降之机，治以养血平肝兼和胃气。", ["沉", "弦", "滑"]], "16491": ["病机", "脉来细弦而滑，细为阴血内损，弦为肝阳升腾无制，滑为痰热。肝阳挟痰热上阻清道，故头眩欲跌、内热口干。原文引《经》「诸风掉眩，皆属于肝」，说明弦脉应肝、风阳上扰之机；滑示痰热内蕴。脉象虚实挟杂，故治宜养阴清肝兼化痰热。", ["细", "弦", "滑"]], "16492": ["病机", "脉来虚弦，虚主脾肾久虚、中无砥柱、下少生发之气，弦主肝阳偏亢。脾肾虚则积湿生痰，痰积化热销铄肺阴，故鼻塞头痛、内热口干。虚弦并见，示本虚标实、痰热阻肺之机，治宜益肾运脾、化痰肃肺，标本兼顾。", ["虚", "弦"]], "16493": ["病机", "脉来细弦，细为荣血久虚，弦为肝阳上升。肝阳销铄胃阴，胃气宣布无权，故胸脘不舒、纳谷不易消化、大便溏泄；阴血不足、肝阳上扰则心悸内热、头眩苔腻。细弦之脉正合血虚肝旺、胃失和降之病机，治宜养血清肝兼和胃气。", ["细", "弦"]], "16494": ["病机", "脉来细弦而数，细主阴血不足，弦主肝阳上灼，数主热。肝当冲脉，冲任隶于阳明，肝阳灼胃阴则冲任失司、带脉约束无权，故月事淋漓、白带时下、乳胀腹痛；内热口干、头眩、喉痹红肿皆热象。细弦数合示阴虚肝旺挟热之机，治宜养血清肝兼益胃阴。", ["细", "弦", "数"]], "16495": ["病机", "脉来弦细，细主荣阴耗伤，弦主气机郁滞。肺有蕴热，耗气灼荣，络血上溢而咯血；痰为热遏无从宣泄，清肃无权，故口干不欲多饮。弦细示热灼营阴、肺失清肃之机，非单纯外感，治宜化痰清热兼肃肺气。", ["弦", "细"]], "16496": ["病机", "脉来弦细，弦为肝阳升腾之象，细乃血少湿阻之征。原文言“病不在血而在气，肝阳上升，挟湿痰阻塞胃气，宣布无权”，故胸腹作痛牵引腰背、吐血而痛不减，皆气机壅滞、肝阳挟痰上逆所致。弦细并见，说明肝旺而阴血不足，痰湿内阻，胃气不降，故纳谷无多。治以养血清肝、化痰和胃，正合脉证。", ["弦", "细"]], "16497": ["病机", "脉来沉细，沉主里、细主虚，为脾肾久虚之候。原文谓“脾肾久虚，痰热灼阴耗气”，肝阳升腾之势虽渐平，津液得以宣布，日晡凛寒肌热已退，然每早痰内带血虽减未止，正是虚火灼络、气阴耗伤之征。沉细说明病位在里，正气已亏，故治宜脾肾并培、清化痰热，标本兼顾。", ["沉", "细"]], "16498": ["病机", "脉来沉弦而滑，沉主里、弦主肝、滑主痰。原文言“肾阴久虚，封藏不固，屡次遗精”，又见“气逆痰多，肝阳上灼肺阴，清肃无权”，鼻塞且衄。沉弦为肝阳内郁、肾虚不藏，滑为痰湿内蕴。脉象反映肾虚肝旺、痰热上扰、肺失清肃之病机，故治宜益肾清肝、化痰肃肺。", ["沉", "弦", "滑"]], "16499": ["病机", "脉来细弦，细为脾虚血少，弦为肝木偏旺。原文述内热鼻衄皆退，肺金清肃下行，惟“脾土未健，积湿阻胃，宣布无权”，故肚腹作痛、即欲大便、纳谷无多。细弦说明脾虚湿困而肝气乘之，木郁土中，运化失职。治宜健脾化湿兼和胃气，使脾健湿化，肝气得舒，则诸症可减。", ["细", "弦"]], "16500": ["病机", "脉弦略退而沉滑如常，弦减示风邪外解、荣卫流行，恶寒发热已止；沉滑如常则说明湿痰内阻未除。原文谓“湿痰阻胃，宣布无权”，故胸胁作痛、呕吐清水虽减未尽退，痰阻喉际咯不易出，居经不行已三阅月。沉滑主痰湿在里，弦退为肝郁稍缓，脉象反映痰湿仍阻、气机未畅之病机。", ["弦", "沉", "滑"]], "16501": ["病机", "脉来沉弦，沉主里、弦主肝，为肝郁气逆之象。原文言“肝郁气逆，胃失降令，胸脘胀痛，举发无常，甚则口多涎沫”，说明肝木郁而不达，横逆犯胃，胃气不降，浊阴上泛。沉弦正合肝郁在里、气机壅滞之病机，故调胃必先平肝，木能条达则胃自宣通，治以养血柔肝兼和胃。", ["沉", "弦"]], "16502": ["病机", "脉来弦细，弦为肝气上升，细为血少湿阻。原文谓“肝气上升，挟素蕴之湿痰，阻塞胃气，宣布无权”，故胸腹胀痛、腰腿阴酸、头眩口干；腿足破皮时有脂水，乃湿痰下注；月事愆期，为肝血不足、冲任失调。弦细说明肝旺脾弱、湿痰内蕴、血分不足，治宜调肝化湿、消痰和胃。", ["弦", "细"]], "16503": ["病机", "脉来细弦而数，细为阴血不足，弦为木火升腾，数为火热内炽。原文言“木火升腾无制，挟素蕴之湿痰，阻塞气机，宣布无权”，故胸腹作痛、心悸、内热口干、头眩，赤白带下甚则腰酸。细弦数说明阴虚火旺、湿热下注、痰阻气机，治宜养阴清火兼化湿热，使火降痰消、气机宣通。", ["细", "弦", "数"]], "16504": ["病机", "脉沉弦而滑，沉主里、弦主肝、滑主痰。原文谓“荣血久虚，肝气上升犯胃”，血虚则肝失濡养而气逆，犯胃则阳明宣布无权，故胸腹作痛、牵引腰背、纳谷无多。弦滑并见，示肝气挟痰上逆，久延有噎膈之虞，治宜养血调肝兼和胃气。", ["沉", "弦", "滑"]], "16505": ["病机", "脉弦细而数，弦主肝、细主阴血不足、数主热。原文谓“久咳伤肺，清肃无权，湿热无从宣泄，上蒸清道”，呛咳牵引胸腹作痛、头面颈项手臂起颗结块，皆湿热为病。弦细数示湿热内蕴而阴分已伤，治宜清化湿热兼肃肺气。", ["弦", "细", "数"]], "16506": ["病机", "脉沉细而弦，沉主里、细主阴血虚、弦主肝阳。原文谓“阴血久虚，肝阳上升，销铄胃阴，胃失降令”，故胸腹胀痛、结块甚多、懊𢙐呕吐、内热口干、头眩惊惕。沉细示阴血不足，弦示肝阳亢逆，治宜养血清肝、调和胃气。", ["沉", "细", "弦"]], "16507": ["病机", "脉沉细而弦，沉细主阴血亏虚，弦主肝火亢盛。原文谓“抑郁伤肝，火升无制，挟痰销铄心营，神魂飞越”，故夜不成寐、喜笑呓语、坐立偏倚。引《经》“神伤则恐惧自失，魂伤则不正当人”，示火痰灼营、神魂失守，治宜清火化痰、镇魂安神。", ["沉", "细", "弦"]], "16508": ["病机", "脉弦滑，弦主肝阳上亢，滑主湿痰内蕴。原文谓“肝阳上亢，挟湿痰蒙蔽包络，神明无主，如浮云蔽日”，故神识乍清乍昧、时常喜笑、夜不成寐；大便燥结、肌热、手足心热，皆痰火灼阴见症。弦滑示痰火内盛，治宜清通神明、降火消痰。", ["弦", "滑"]], "16509": ["预后", "原文未识脉名，仅言“脉象模糊”，故脉象要素为空。外邪自肺内陷包络，神明出入之窍皆闭，故牙关紧强、神昏不语、戴眼肢掣，肝风鼓动。脉象模糊示正气溃散、邪闭心包，原文断为“危在旦夕”，交阴更甚，阴虚火旺已可概见，姑拟芳香宣窍、豁痰生津以尽人事。", []], "16510": ["病机", "脉沉弦而滑，沉主里、弦主肝阳、滑主痰热。原文谓“水不涵木，肝阳升腾无制，挟素蕴之痰热，上阻包络，心不自主”，故神思恍惚、疑虑惊恐、时常健忘。沉弦滑示肝阳挟痰上扰、根蒂已深，治宜清通神明、调肝化痰。", ["沉", "弦", "滑"]], "16511": ["病机", "脉沉细而弦，沉细主阴血亏虚，弦主肝火亢盛。原文谓“肝火上升，挟胃中痰热蒙蔽包络，神明无主，如浮云蔽日，虽照无光”，故神识迷昧、语言无次、时带喜笑。沉细弦示火痰内扰而阴分已伤，抱恙多年根深蒂固，治宜清通神明、降火化痰。", ["沉", "细", "弦"]], "16512": ["病机", "脉细弦而数，细为阴血不足，弦为肝阳升动，数为湿热内蕴化热之象。原文谓阴血久虚、肝阳上升挟湿热，销铄胃阴心营，故见夜寐不酣、喉痛目燥、牙关流血、作恶欲吐、腰酸带下、下体起颗作痒，皆阴虚阳亢兼湿热下注之候，脉象正合此虚实夹杂之机。", ["细", "弦", "数"]], "16513": ["病机", "脉弦略退，知湿痰渐化、胃气下降，胸腹胀痛已减；然沉细仍然，沉主里、细主虚，示脾土未健、运化失职，故大便溏泄日五六次、纳谷无多、夜寐不酣。弦退而沉细存，说明标实减而本虚未复，病机重心在脾虚湿滞。", ["弦", "沉", "细"]], "16514": ["病机", "脉弦略退，为湿痰渐化、肺气下降之征，喘哮较减；而沉滑仍然，沉主里、滑主痰，示脾肾久虚、摄纳无权，痰浊内伏未净，故喉际痰声漉漉、寝食俱废、举发无定。弦退滑存，说明病本在脾肾虚而痰浊留恋。", ["弦", "沉", "滑"]], "16515": ["病机", "脉来沉细而弦，沉细为肾阴久虚、封藏不固，弦为肝阳上烁。原文谓水不涵木，肝阳上烁肺阴，清肃无权，故失音半载，兼遗精、耳鸣、气急。沉细示下元虚损，弦示肝阳亢逆，虚中夹实，势已入损，脉症相符。", ["沉", "细", "弦"]], "16516": ["病机", "脉来弦数，弦主肝火，数主热盛。原文谓肝火上升，销铄肺阴，清肃无权，故呛咳音喑、咽喉红痛、入夜内热。弦数为肝火炽盛、阴液受灼之象，火旺灼金则音喑，势已成损，脉象揭示火盛阴伤之病机。", ["弦", "数"]], "16517": ["病机", "脉弦已减，知肝阳上升之势已平，故咽喉白腐、齿浮且痛、手足心内热皆退；沉滑如常，示痰热虽化而未尽净，仍留于里。弦减为阳亢得制，沉滑为痰热未清，病机由肝阳上扰转为痰热留恋、阴液待复。", ["弦", "沉", "滑"]], "16518": ["病机", "脉来细弦而数，细为阴血久虚，弦为肝阳升腾无制，数为痰热内蕴。原文谓挟痰热销铄胃阴，津液宣布无权，故蒂丁色红作痛、喉起红颗、头眩且疼、内热口干。细弦数并见，示阴虚阳亢兼痰热，虚实夹杂之候。", ["细", "弦", "数"]], "16519": ["病机", "脉弦细，弦主湿热蕴结、气机不畅，细主脾虚气弱。原文谓恙由下痢而起三月，大便带红、气觉下坠、口干苔腻，乃脾虚不运、湿热留恋之候。弦细并见，示虚中夹实，治宜益气培脾兼化湿热，脉象正合脾虚湿滞之机。", ["弦", "细"]], "16520": ["病机", "脉来沉细而弦，沉主里、细主阴亏、弦主肝阳。原文谓脾土久虚、湿热下注、肾阴更亏、肝阳上升，脉沉细示阴营销铄于内，弦示肝阳挟湿痰阻气，故见脱肛作痛、带血、胸脘不舒、内热口干，脉象与脾肾虚而肝阳亢之病机相应。", ["沉", "细", "弦"]], "16521": ["病机", "脉来沉细而弦，沉细为肾阴久虚、封藏不固之征，弦为肝阳不潜。原文谓屡次遗精、劳力伤脾、精神萎顿、四肢无力，脉沉细应脾肾两虚，弦应肝阳偏亢，故治宜脾肾并补兼固精气，脉象正合虚而兼亢之病机。", ["沉", "细", "弦"]], "16522": ["病机", "脉来细缓，细为肾阴尚虚，缓为肝阳疏泄之势渐平、下元封藏已固。原文谓遗精已止、内热盗汗均退，惟间或口干、劳动气急，是肾阴未复、气不收纳，脉细缓示虚象渐和而未尽，故治宜补肾益气兼清肝阳。", ["细", "缓"]], "16523": ["病机", "脉来弦滑，弦主脾肾久虚、中无砥柱之权，滑主积湿生痰。原文谓屡次遗精、胸腹作胀、呛咳气急，是痰湿阻塞肺胃、气不通降，弦滑相合正示虚中挟痰湿壅阻之机，故治宜脾肾并培兼化湿痰。", ["弦", "滑"]], "16524": ["病机", "脉来弦细，细为肾阴久虚，弦为湿热内蕴、气化无权。原文谓流浊匝月、茎中作痒牵引后阴、小溲短数、间或咳嗽，是阴亏而湿热下注、气化不利，弦细之脉正合虚中挟湿之病机，故宜宗前法进治。", ["弦", "细"]], "16525": ["病机", "脉来沉弦而滑，沉主肾虚于里，弦主肝阳上亢，滑主挟痰。原文谓肾虚腰痛、头痛眼花、内热口干、腿足阴酸，是木少水涵、肝阳挟痰销铄肺阴、清肃无权而呛咳，沉弦滑正示肾虚肝亢痰阻之病机。", ["沉", "弦", "滑"]], "16526": ["病机", "脉弦略退而细滑仍然，弦退示肝阳升腾之势渐平，细滑示肺肾阴虚、痰热蕴结未解。原文谓内热口干较减，而腰痛咳呛腿酸未止、大小便时懔寒，是虚未复而痰热仍恋，脉象进退与症相应，故宜宗前法进治。", ["弦", "细", "滑"]], "16527": ["病机", "脉来缓滑，缓为肝阳升腾之势已缓、肺金清肃下行，滑为痰热未清。原文谓呛咳已止，而内热口干、头眩目痛、遗精腰酸、胸腹不舒，是脾肾久虚、痰热耗气灼阴、流灌失职，缓滑正示虚中挟痰热之病机。", ["缓", "滑"]], "16528": ["妇人", "原文以「脉左寸动滑，有摇摆之状者，怀孕也」辨妊娠，左寸候心，动滑摇摆为胎气初结、血聚养胎之象；又言「脉皆虚」者，经带胎产诸病多本于血虚气弱，故经行腹痛责之气阻血虚，崩漏久者养阴清火，带下则阴虚火旺兼湿热，脉虚正合气血不足之机。", ["动", "滑", "虚"]], "16529": ["病机", "原文未出脉名，专论白带时下之病机为「肝阳挟湿热灼阴，带脉不固」。肝阳偏亢，湿热内蕴，灼伤阴液，带脉失于约束，故带下绵绵。治宜清肝化湿，使肝阳平、湿热去而带脉自固，此段重在阐发病机而非凭脉断病。", []], "16530": ["病机", "原文未载脉象，述黄带时下乃「任脉有火，挟湿热灼阴，带脉不固」。任脉主一身之阴，火旺则湿热相合，灼耗阴津，带脉约束无权而见黄色带下。治宜清火化湿，火清湿化则任脉安、带脉固，全段以病机立论。", []], "16531": ["病机", "原文无脉名，言青带时下「如绿豆汁，腥秽异常」，断为「肝郁化火灼阴，带脉约束无权」。肝郁日久化火，火灼阴液，湿浊下注，故带色青而腥秽。治宜清肝，解郁泻火则带脉复其约束之职，此段亦属病机分析。", []], "16532": ["妇人", "原文「怀孕月余，内热呕吐」，因胎初结成，胃失宣布，浊气上逆而呕；「左寸脉动滑，有摇摆之状」为妊娠之脉，左寸候心，胎气内动、血聚养胎故见动滑摇摆。脉症相合，断为妊娠恶阻，治宜苦降辛通以和胃降逆。", ["动", "滑"]], "16533": ["病机", "原文「先天肾虚，后天脾弱，中失运化之权，下少生发之气，湿痰阻气，凝结成块，脉来沉弦」。沉主里、主虚，弦主气滞痰凝，脾肾亏虚则运化无力，湿痰内阻、气机不畅而结块，故脉沉弦。治宜益肾健脾、化痰理气，脉象正合虚中夹实之机。", ["沉", "弦"]], "16534": ["病机", "原文「脾肾久虚，肝阳太旺，挟湿热耗气灼荣」，肾囊流脂水血水、少腹恶寒，乃湿热生痰阻塞气机；「脉来沉细而弦」，沉细主脾肾久虚、气血不足，弦主肝阳偏旺、气机郁滞。虚为本、湿热痰浊为标，故治宜益肾清肝、健脾化湿。", ["沉", "细", "弦"]], "16535": ["病机", "原文「肾阴肝血俱亏，精华不能上注，左目散光，右目作痛，阳升无制，挟热痰销铄营阴，脉来沉弦」。沉主阴血亏虚于里，弦主肝阳升动无制、痰热内扰，故目失血养而散光作痛。治宜清肝益肾兼化痰热，脉沉弦正示阴虚阳亢、痰热夹杂之病机。", ["沉", "弦"]], "16536": ["病机", "脉来沉弦，沉为在里，弦主肝木。营血久虚，木火升腾无制，销铄营阴，故左目散光、视物不清、咯血鼻衄、内热口干。沉弦示肝火内郁阴分，非表证之浮弦，与目为肝窍、瞳神属肾之病位相应，主阴血亏虚、肝阳上亢之病机。", ["沉", "弦"]], "16537": ["病机", "脉来弦滑，弦主肝木，滑主湿痰。肌肤起颗成片、破碎流脂水、腿足内热、暮肿朝消，乃湿热外发、下行自寻出路之象。弦滑示湿热蕴结肝经，痰湿内盛，与抱恙多年、根深蒂固相应，主湿热痰浊互结之病机。", ["弦", "滑"]], "16538": ["病机", "脉弦略退，沉滑如常。弦为肝阳升腾之势渐平，沉滑主脾肾久虚、痰热蕴结。颈生瘰疬、腋下痰核，乃痰热耗气灼阴所致。脉弦退而沉滑存，示肝阳虽减而痰热未清，与脾肾久虚、痰热蕴结之病机相应。", ["弦", "沉", "滑"]], "16539": ["病机", "脉来弦细，弦主肝阳上亢，细主阴血久虚。肝阳渐平而肺气肃降，故内热口干、脘闷腹胀轻减；腿足暮肿朝消、月事愆期、白带时下、怯冷手震，皆阴血亏虚、湿痰阻胃之候。弦细示阴血不足而肝阳未靖，主虚中夹实之病机。", ["弦", "细"]], "16540": ["病机", "脉来沉细而弦，沉为在里，细主阴血亏虚，弦主肝阳上灼。阴血久虚，肝阳上灼胃阴，冲任失司，带脉约束无权，故血崩成块、带下甚多、心悸内热、头眩眼花、肢节酸痛、腿足浮肿。沉细弦示阴亏阳亢、冲任不固之病机。", ["沉", "细", "弦"]], "16541": ["病机", "脉来细弦，细为气血皆虚，弦为肝阳升腾。中无砥柱，肝阳无制，销铄肺胃阴液，故知饥少纳、心悸、内热口干、头眩、带下腰痛。细弦示气血亏虚而肝阳偏亢，带脉约束无权，主气阴两虚、肝阳上扰之病机。", ["细", "弦"]], "16542": ["病机", "脉来细弦而数，细主阴血内损，弦主木火升腾，数主内热。脾土久虚，湿热阻胃，气失降令，故脘痛腹胀、内热口干、头痛眼花、腰酸带下。细弦数示阴亏火旺、湿热内蕴，木火销铄津液，主脾虚湿阻、阴伤阳亢之病机。", ["细", "弦", "数"]], "16543": ["病机", "脉浮数，浮主风邪在表，数主风已化热。风邪自口鼻吸入，肺先受之，发为风疹、目赤、面如渥丹、发热咳呛、头胀脘闷、咽痛、小便短涩、大便不行。浮数示风热弥漫上焦，急宜清肃肺卫，俾疹点透达，主风热犯肺之病机。", ["浮", "数"]], "16544": ["病机", "脉左弦数、右细数，左弦应肝，数主热，右细数示肺胃阴亏而热。原文述风疹透发后胸闷头胀愈，惟咽干喉痛、痰中映红，且素有咯血遗泄，阴亏体质易感风热，故脉见弦数细数，主肺胃郁热、阴分不足，热伤血络则痰红。", ["弦", "数", "细"]], "16545": ["病机", "脉双弦，弦主饮主痛，亦主肝旺。原文谓素有痰湿、肺胃留热且有心火，痰湿内阻则胸脘不舒、夜不成寐，肝火犯肺则咯血复发，火扰精室则遗泄。双弦之脉正应痰湿与肝火交阻之病机，故治以清泄。", ["弦"]], "16546": ["预后", "原文仅言脉亦较和，未列具体脉象，故脉象要素为空。投清泄心火之剂后咯血、遗泄均愈，脉较和即邪热渐退、脉气趋于平和之征，属病退向愈之预后。惟胸脘气分未舒、时作太息，素痰湿未净，故转以调理脾胃为治。", []], "16547": ["病机", "脉细数，细为阴血不足，数主内热。原文述咳呛多痰不爽、咯血色紫、舌起红点、面色㿠白，断为肺胃郁热不能宣通、阴分素亏。细数之脉正合阴亏火旺、郁热内蕴之机，热灼肺络则咯血，故先宣通肺气、佐泄热存阴。", ["细", "数"]], "16548": ["病机", "咯血虽止而脉仍细数，说明阴亏火旺之本未复。原文见咳呛多痰浓厚青绿、夜间轰热、舌红点已退，痰色青绿示热郁于肺，轰热为阴虚阳浮，细数脉应阴分不足而火未清，故以降火滋阴涤痰为治，脉象提示病机仍在阴虚火旺。", ["细", "数"]], "16549": ["病机", "脉数而浮，数主火旺，浮示阳浮不敛。原文谓阴亏火旺之体，又交春令、值少阳相火司天，故虑水不涵木、火不刑金。今晨咯出紫黑色血一口，为虚火灼络之象，数浮之脉正应阴亏阳浮、木火内动之病机，故仍守前法兼泄木火。", ["数", "浮"]], "16550": ["病机", "脉数如故，示上焦之热尚未清肃。原文见夜咳、喉间痰声、鼻吸紫红涕、多梦汗出，皆阴虚火旺、热扰上焦之候；又值天暖如暮春，恐阳气升动而咯血复发。数脉不去，说明火未清、阴未复，故与甘寒凉润以清养。", ["数"]], "16551": ["病机", "脉数仍未稍减，为阴亏之体阳不潜藏之明证。原文述昨交春令即夜间咯血三口，春令阳气升发，阴虚不能涵阳，虚火上炎灼伤肺络，故血复出而脉数不减。数脉持续提示火旺阴亏未复，故拟清养肺胃、复以介类潜阳。", ["数"]], "16552": ["预后", "脉数较前略平，说明热势渐减，肺胃肾阴虚火旺之象有所缓解。咳嗽十减五六，但黎明盗汗，乃阴虚内热、卫气不固所致。脉数本主热，今较前平和，示热退而阴未复，故治法仍以清肺养胃滋肾为要，巩固疗效。", ["数"]], "16553": ["病机", "脉两手软弱无力，为气血两虚、脾肾亏虚之象。连年吐血、血崩，阴血耗伤，气随血脱，故脉软弱无力。腰痛、头晕、手麻、耳鸣、小溲频数不禁，皆肾虚不固、精血不足之征。舌脱液、中心猪肝色，示阴虚液涸。新感咳呛痰红音嘶，属虚体感邪，本虚标实。", ["软", "弱", "无", "力"]], "16554": ["病机", "脉数主热，风邪袭于肺络，郁而化热，故脉数。咳呛多痰、夜间发热、右颐作痛，皆风热壅肺、肺失清肃之象。右颐属肺胃分野，热邪循经上攻则痛。治以清肃肺胃，使风热得解，肺气宣降，则咳热自平。", ["数"]], "16555": ["病机", "脉两寸皆数，左关弦。两寸候肺，数主热，肺虚有热，故寸数；左关候肝，弦为肝旺。素有咯血，喉痒呛嗽吐薄痰，乃肺阴不足、虚火灼津，肝火犯肺所致。脉症合参，病机为肺虚有热、肝木偏亢，治以清肃肺气，兼平肝火。", ["数", "弦"]], "16556": ["兼症", "复诊脉左弦右数，左弦主肝，右数主肺热。投清肺之剂后喉痒咳呛渐愈，惟胁痛，乃肝络不和、气机郁滞。咳呛时左右胁微痛，为肺病及肝、木火刑金之兼症。前法佐以通络，既清肺热，又疏肝络，使气血通畅，胁痛自止。", ["弦", "数"]], "16557": ["病机", "脉形细数而滑，细为阴血不足，数为有热，滑主痰湿。病起懊恼，肝火胃热郁蒸，疏泄失常，乳汁外溢。乳属肝胃，肝火胃热迫液妄行，故胀痛流乳。天癸仍至，非乳泣虚证。脉症合参，病机为肝火胃热、郁蒸乳络，治以疏肝清胃缓调。", ["细", "数", "滑"]], "16558": ["病机", "脉数主热，舌黄亦为热象。经事先期而至，色鲜不多，腹痛阵作，骨节腰脊酸，胸脘闷得嗳则舒，口腻，乃气血交滞、郁而化热。气滞血瘀则腹痛阵下，肝胃不和则脘闷口腻。脉数示热因滞生，治当行气活血、清热调经。", ["数"]], "16559": ["病机", "脉细数，细为阴虚，数主热。经事先期，阴虚生内热，血热妄行故先期。胃中泛呕、脘下气耕作痛，木乘土之征；头微痛非外感，乃阴虚阳浮。脉症合参，病机为阴虚血热、肝胃不和，治宜凉肝清胃，使热清阴复，经自调。", ["细", "数"]], "16560": ["病机", "脉弦数，弦主肝络瘀滞，数主郁热。患者少时咯血，旧疾复发，遇阴天血多痰少，乃素体湿盛、络中瘀血，湿瘀化热，肺肝络脉不和。弦数为肝经郁热、络瘀之象，故治以通肺肝之络，用旋覆花汤合苇茎汤法。", ["弦", "数"]], "16561": ["病机", "脉左细数，右沉数。细为气血不足，数为虚热，沉主里。腹胀如臌、脐凸、小便不利，乃气虚作胀，误治伤残脾胃，致中阳不运，水湿内停。细数沉数示脾胃虚损、阳气不通，故勉以温补通阳。", ["细", "数", "沉"]], "16562": ["病机", "脉涩，涩主湿滞血瘀、气机不畅。嗜酒豪饮，湿中伏火结于阳明，胃热消谷善饥，脘间不舒，恐成中消。涩脉反映湿火内结、津液运行受阻，故以苦辛通湿中之火。", ["涩"]], "16563": ["预后", "脉涩者难治，涩为津液亏耗、血行不畅之象。此时火盛，火盛则灼津，后来津液枯矣，恐成嗝证。涩脉示津液已伤，预后不良，故李师云难治。", ["涩"]], "16564": ["病机", "脉左弦右数，左弦主少阳风火，右数主风邪化热。感受时令风邪，头痛甚于额，咳呛，耳痒出脓水，入暮神倦，乃风邪挟少阳之火上升。弦数为风火相煽之象，故治以清泄。", ["弦", "数"]], "16565": ["病机", "脉细弦数，细为阴血不足，弦主少阳木火，数为火盛。感冒后头痛、鼻塞、呕恶吐酸，月事四月不至，舌苔黄腻，系少阳木火上升，犯胃及肺。细弦数示木火内炽、阴血受灼，故拟抑木和中法。", ["细", "弦", "数"]], "16566": ["病机", "脉仍细弦数，细为阴血养胎而不足，弦数主少阳相火。怀麟四月，手少阳相火养胎，春令木火用事，火曰炎上，犯胃作恶，犯肺鼻塞且衄。脉仍细弦数，示木火未清，故拟清泄少阳之火。", ["细", "弦", "数"]], "16567": ["病机", "脉弦滑，弦主少阳风火余焰，滑主痰湿未净。头痛已愈，胃逆亦平，惟皮肤痒、燥而板木，右鼻仍塞，恶闻煎熬气，乃血分素亏，少阳风火余焰未熄，肺气不宣。弦滑示余热夹痰，故以轻剂宣上焦余热。", ["弦", "滑"]], "16568": ["病机", "脉两手皆弦，弦为肝木之象，主气机郁滞、脏腑失和。本案心肾不交，夜不成寐，寐则遍体不适，时患溃泄，乃心脾肾三脏同病。弦脉反映肝郁气滞，木不疏土，脾运失职则溃泄；水火不济则夜寐不安。脉弦与心肾不交、脾虚泄泻相应，故以心脾肾兼治。", ["弦"]], "16569": ["病机", "脉右数左伏，右数主热郁于气分，左伏为湿遏营卫、邪阻不达。症见寒热、胸闷、腹痛、齿焦、舌白腻而厚、不食不便，显系湿温重证。湿浊壅遏，热不得透，故右脉数而左脉伏。数示郁热内蒸，伏示湿邪闭阻，与辛凉开泄法相应。", ["数", "伏"]], "16570": ["病机", "复诊左脉伏略起，右仍数，齿焦退，舌白腻转淡黄中有裂纹，胸闷腹痛稍舒而不食不便依然。左伏略起示湿邪渐透、营卫稍通；右数未减、舌转淡黄裂纹，为郁热未泄、阴液渐伤。脉象变化反映湿温重证郁热未清，仍宗前法出入。", ["伏", "数"]], "16571": ["病机", "脉两手皆数，右寸尤甚。数主热，右寸候肺，寸甚则热留肺经。症见屡咳不已、失血、音嘶、咽痛、咳甚于夜，显为肺有留热、久咳伤阴。热灼肺络则失血，阴伤津涸则音嘶咽痛，夜咳甚者阴虚火旺。脉数与肺热伤阴相应，故拟清润肺经。", ["数"]], "16572": ["病机", "投清润后血止、夜咳不甚、咽痛稍减，脉数渐和，惟音不响亮、流涕如故。数脉渐和示肺热渐退，但音嘶未复，乃辛温开泄太过、肺阴受伤不能还复。脉象由数转和，说明热减而阴未复，故以滋养肺金为治。", ["数"]], "16573": ["病机", "脉软，右关尤甚，舌淡。软为虚象，右关候脾胃，关部尤软则脾胃气虚。症见朝食暮吐、完谷不腐、二便俱秘，乃脾胃虚寒、运化无权、升降失司。软脉主气虚不运，与关格渐成之候相应，故断为关格之渐。", ["软"]], "16574": ["病机", "投温补辛通后胃反已止、大小便通，脉迟而软，右关略起，畏寒、胸脘时痛。迟主寒，软主虚，右关略起示脾胃阳气渐复。脉迟而软反映中焦虚寒未复，畏寒胸痛为寒凝气滞。脉象与温补后阳复未全相应，仍以前法出入。", ["迟", "软"]], "16575": ["病机", "脉涩，舌黄。涩主气滞血瘀、湿阻脉络。症见口苦、纳减、神倦、头晕、耳聋、鼻塞、大便艰，值夏令湿热郁蒸之时，显为痰湿郁滞、湿热内蕴。涩脉示湿浊壅遏、气血不畅，与痰湿郁滞病机相应，故治以辛开。", ["涩"]], "16576": ["病机", "脉两手细数，细为阴液亏少、脉道不充，数为五志之火燔灼于内。原文谓'素体阴亏，兼以情怀抑郁，五志之火燔灼于内'，故见寐中盗汗、掌心灼热、日晡发热、便艰等阴亏火旺之候。细数并见，正示阴虚为本、火旺为标，故治宗黄连阿胶汤毓阴清热。", ["细", "数"]], "16577": ["病机", "脉数而濡，数为热郁于内，濡为湿邪偏胜、脉道软缓。原文谓'热郁湿中，不能外达'，故口渴不引饮、泛泛欲呕、舌白而润，皆湿遏热伏、气机不得宣达之征。数而不洪、濡而不滑，说明热为湿裹，病在气分上焦，故急宜宣泄上焦气分。", ["数", "濡"]], "16578": ["病机", "脉来数甚，较前数而濡更进，示湿热蕴结心肺之分、壮热鸱张。原文'壮热气急，渴不引饮，胃中泛恶，懊𢙐，大便不行，小便短赤，舌转微黄而不润'，皆湿热内结、热势偏重之候。数甚说明邪热炽盛而湿未化，故急以辛凉开泄中上二焦。", ["数"]], "16579": ["病机", "脉弦数大，弦主肝火鸱张，数主热迫，大主邪盛势猛。原文谓'暑热客邪迫血妄行，倾盆盈碗，色紫而厚'，咳呛血随上溢、胸闷胁痛、肌肤灼热，皆暑热燔灼肝胃、迫血上溢之征。弦数大示火势凶暴，故急以清热通瘀、凉血止血复方救之。", ["弦", "数", "大"]], "16580": ["预后", "复诊脉弦数较昨稍敛，较前弦数大已见收敛，示大剂清热通瘀后火势渐退。原文'呕血已止，胸闷亦开，惟咳呛时作，唇口干燥，余焰尚未熄也'，舌黄腻边紫绛，说明瘀热未尽、阴津未复。脉稍敛为向愈之兆，故仍以甘寒清热佐消瘀。", ["弦", "数"]], "16581": ["病机", "脉弦而涩，弦为肝郁气滞，涩为血行不畅、食积内停。原文谓'抑郁停食致病，胸满，左侧有块……胸次板实满闷，胃纳顿减，病经三月'，正合木郁土中、肝脾胃交困之机。弦涩并见，示气郁血滞、食阻中焦，故遵'木郁达之'经旨以疏达为治。", ["弦", "涩"]], "16582": ["病机", "脉细数，细为阴血不足、脉道不充，数为郁火内扰。原文谓'情怀抑郁，经水不至，胸闷，气急，大病之后，元气不复'，情怀抑郁则气郁化火，大病后元气阴血俱亏，故经闭不行。细数示郁火伤阴、血海空虚，故拟解郁参以育阴，标本兼顾。", ["细", "数"]], "16583": ["主病", "脉濡数，濡主湿邪黏滞、脉道软缓，数主湿热蒸腾。原文谓'酒客湿蕴中焦，寒热得汗不解，渴而引饮，胸闷，小便短赤，舌垢腻堆积'，酒客素蕴湿热，湿遏热伏则寒热汗而不解。濡数相合，正湿温重证之脉，故断为湿温，主病在中焦气分。", ["濡", "数"]], "16584": ["病机", "脉濡数，濡主湿，数主热，为湿热交蒸之象。原文“目黄，爪甲微黄，足跗起泡累累”乃湿热充斥三焦、外发肌肤之症；“舌黄腻”亦湿热内蕴之征。脉症合参，病机为湿热弥漫三焦，发越未透，故宗仲景法以清利湿热、透邪外达。", ["濡", "数"]], "16585": ["病机", "脉沉按弦数，沉主里，弦主肝，数主热，为肝阳素旺、风火内动之象。患者“素有肝疾，常患头痛”，今“晨起登高受风”，外风引动肝阳上升无制，故见眩晕欲厥、两颧色赤、愁眉欲哭。脉沉按弦数正合肝阳化风、风火相煽之病机，且怀麟六月，治当直折厥阴而避芳香开泄。", ["沉", "弦", "数"]], "16586": ["病机", "脉细紧弦数，细主阴伤，紧主痛主痰，弦主肝，数主热，合为痰凝肝胆、化热生风之象。原文“痫证病经半载，月必一发，发则卒仆，角弓反张，手足扬掷，口吐涎沫”，正是痰聚肝胆胞络、久郁化热、热极生风之候。脉症相应，故治以熄风除痰清热。", ["细", "紧", "弦", "数"]], "16587": ["病机", "脉细弦数，细主阴液亏虚，弦主肝阳偏亢，数主内热。患者久嗽痰出不爽，咽中炙脔，喉痒头晕，前服辛散燥烈十余剂，致“阴液已涸，肝阳随之而上”。舌绛无苔亦阴伤之征。脉细弦数正合肺阴涸竭、肝阳上亢之病机，故以滋润肺阴为补救。", ["细", "弦", "数"]], "16588": ["病机", "脉浮涩满指，浮主燥气伤表，涩主津伤血滞。患者白喉兼泄泻，身无寒热，口不渴，舌胎淡白而薄，底露鲜红，小便时清时浊，审由燥气所发。燥伤肺津，肺移热于大肠，故兼泄泻，病邪自寻去路。脉浮涩满指正合燥气伤津、肺热下移之病机，故用清燥救肺汤。", ["浮", "涩"]], "16589": ["误治", "脉浮大而芤，浮大主热盛于外，芤主阴血大伤。患儿燥症红喉转白，服发散药后米饮不入，口渴身大热无汗，心烦不寐，舌无苔鲜红多刺，脉浮大而芤，显系燥症误表，阴液被劫，邪热内陷。原文“此乃燥症误表，挽回甚难”，脉象正示阴伤热炽之危候，故急予养阴清肺。", ["浮", "大", "芤"]], "16590": ["病机", "脉沉迟而涩，沉主里，迟主寒，涩主血滞。患者干脚气，两足缓纵不能行，足不寒热、不红肿、不疼痛，舌苔如常，口不渴，前医作风寒、痹症治皆不效。脉沉迟而涩，示气血虚滞、经络失养，非外邪实痹，故照陈修园四物汤加味法养血通络而愈。", ["沉", "迟", "涩"]], "16591": ["误治", "脉浮大而芤，浮大主热盛，芤主阴血亏耗。患者春温症，前服表散温燥，致大热、大渴、大汗，身无汗，舌无苔鲜红多芒刺，心烦不寐，米饮不入，脉浮大而芤。此春温误表，阴液大伤，邪热内炽之危候。幸小便利，阴未全绝，犹存生机。脉象正示误治后阴伤热炽之病机。", ["浮", "大", "芤"]], "16592": ["病机", "脉浮大而缓，按之无神，浮大非阳盛，乃阴寒内盛、虚阳外浮之象；缓为胃气衰败，无神则根本已亏。原文谓‘阴霾滔天、阳光将熄’，故见满面青黯、痰涎如潮、手足不仁、汗出津津等阴寒重症，脉症合参，主阴寒内盛、阳气欲脱之病机。", ["浮", "大", "缓"]], "16593": ["病机", "脉浮大而缓，浮大无力，缓而失神，乃阳气虚浮、阴寒内踞之候。症见四肢不仁、潮热、微汗、面青、震动、多痰、语艰，显系虚阳上浮、痰浊蒙蔽。脉浮大非实热，缓非和缓，合参诸症，主阴寒内盛、虚阳外越之病机。", ["浮", "大", "缓"]], "16594": ["预后", "脉三五不调，即结代散乱之象，主脏气衰败、根本已离。后脉忽三部调和，非病愈，乃残灯回焰、六脉相会之死候。原文‘脉固佳，然而余不能立方’，正谓脉乍和而脏气将绝，故主预后不良，死在即日。", ["结", "代"]], "16595": ["死脉", "脉微数不可按指，微为阳衰，数为阴耗，按之无根，已见雀啄之形。雀啄脉来三五不调，如雀啄食，乃胃气已绝、真脏脉现。服参茸后脉略平，无神，正是回光返照。原文‘脉露雀啄形’‘命在数日’，主死脉，预后极恶。", ["微", "数", "雀啄"]], "16596": ["病机", "脉沉迟而紧，沉主里，迟主寒，紧主痛。症见便闭、溲涩、腹满、胸痞、呕恶、面惨骨瘦、苔厚灰白，显系阴寒内结、阳气不行。前医误用滋润及硝黄，更伤阳气。脉沉迟紧，主阴寒痼结、气机壅塞之病机。", ["沉", "迟", "紧"]], "16597": ["病机", "脉沉迟而涩，沉迟为阴寒内盛，涩为血少气滞。症见便艰、溲涩、月事不通、身微热、腹满、食少、困倦，舌苔湿滑而暗，乃阴寒误药，由气分累及血分，气血交病。脉沉迟涩，主阴寒内结、气血凝滞之病机。", ["沉", "迟", "涩"]], "16598": ["妇人", "本段论娠脉及男女分别，强调问诊与脉诊合参。原文‘脉有疑义，幸余先已问明’，说明寡妇之脉疑似孕脉，须结合问诊辨析。虽未出具体脉名，主旨属妇人娠脉鉴别，故归妇人类，示脉诊不可孤恃。", []], "16599": ["妇人", "脉似代非代，流利中时一跌，即歇至之象。原文‘孕脉歇至，古有明训’，妇人月事不来两月，脉歇至而流利，非死候，乃孕脉特殊表现。前医以歇至为病，不敢用方，实误。此段主妇人孕脉鉴别，脉代而流利，当参症辨孕。", ["代"]], "16600": ["病机", "脉弦数，弦主风动，数主热。患者风作时手足瘛疭、面皮震动、头晕眼花，乃肝风内动之象；风息则口苦头晕、手足顽麻，面色如醉、舌苔黄厚尖红点，显系肝胆郁热、风火相煽。弦为肝脉，数为热象，故脉弦数主肝经风热、风火内动之病机，与风引汤证相应。", ["弦", "数"]], "16601": ["病机", "脉沉弦而劲，沉主里，弦劲主肝风鸱张、寒饮内伏。患儿下利清谷、口不渴、舌苔灰白厚滑，为脾肾虚寒、水谷不化；目上视、气喘、手足躁扰而厥，乃虚风内动、痰饮上逆。沉弦而劲示里寒夹风、本虚标实，故主慢惊风之脾肾虚寒、虚风内动病机。", ["沉", "弦", "劲"]], "16602": ["病机", "脉沉迟而弦紧，沉迟主里寒阳虚，弦紧主寒凝气滞、痛证。患者气痛数年，胸背胁牵痛、头重不举、手足酸软不温、面色黧黯、舌苔湿滑厚、时时欲呕，皆阴寒内盛、阳气不布、寒饮上逆之候。脉沉迟弦紧正合寒饮痼结、胸阳不振之病机，故主乌头赤石脂丸证。", ["沉", "迟", "弦", "紧"]], "16603": ["病机", "脉微弱不可按指，微主阳气衰微，弱主气血不足。患儿素羸弱，项疽溃久脓尽流清汁，更服凉药致身冷汗出、困顿不支，显系阳气虚脱、气血两亏。脉微弱为阳气欲绝之征，故主阴疽溃后阳气衰微、气血虚脱之病机，与四逆加人参汤回阳救逆相应。", ["微", "弱"]], "16604": ["病机", "脉弱无神，弱主气血虚衰，无神示胃气不振。患者腹旁生疽，久溃脓尽、清汁泫流不断，面色黧黯、舌苔湿滑，乃气血亏耗、阳气不足、阴寒凝滞之候。脉弱无神正合疮疡溃后气血两虚、阳气衰惫之病机，故主阳和汤温补托毒之证。", ["弱"]], "16605": ["预后", "脉浮大濡缓无神，时而歇止。浮大无力、濡缓无神，为脾胃气败、阳气浮越之象；歇止则示脏气衰微、脉气不续。患者年七十，五更洞泄日久，昏迷不醒、手足痿废、溲便不禁、面目黑气弥漫，皆脾肾阳衰、元气欲脱之候。脉证相参，故断为不治之预后。", ["浮", "大", "濡", "缓"]], "16606": ["预后", "脉沉而微，沉主里、主水，微主阳气衰微。患者水肿半年，头面四肢腰腹胸背皆肿如瓜形，气喘、小便不利，皮肤胀痛不可支，更兼缺盆平、掌无纹、脐突、足底平等水肿死证。脉沉微示肾阳衰微、水气泛滥、气化不行，故主水肿危重、阳气欲竭之预后不良。", ["沉", "微"]], "16607": ["预后", "平素脉沉潜不露，乃素禀偏阳、脉藏于里之常；临终脉细欲绝，细主阴血亏竭，欲绝示胃气将绝。患者头晕难堪、牙关紧闭、舌喑不言、手足痿废、滴水难入，口无涎、鼻无涕、目无泪，皆阴液竭绝、无以上承外润之征。脉细欲绝正合阴竭阳亡之病机，故断为阴竭不治之预后。", ["沉", "细"]], "16608": ["病机", "脉浮大而迟，浮大示气血浮越于外而中气不足，迟为虚寒，合之精神困顿、自汗不止、舌苔灰白，显系母体孱弱、胎元不固而崩漏，气血大虚之候。脉浮大非实热，乃虚阳外浮；迟则阳气衰微，故不可误作正产而用催生，惟大剂补养培母气，胎自受益。", ["浮", "大", "迟"]], "16609": ["病机", "脉沉涩，沉主里、涩主血行不畅，合少腹满胀、舌苔黄暗底面鲜红、如狂欲击人，正是瘀热结于下焦血分。前医但治气分故不效，《内经》「血在下如狂」、仲景「热结膀胱其人如狂」即此，故用桃核承气汤下其瘀热。", ["沉", "涩"]], "16610": ["病机", "脉沉结，沉为病在里，结为气血瘀滞不行，合精神恍惚、欲就溲桶、伸拳击人、舌苔微黄而晦，正是伤寒蓄血、热结膀胱之候。溲便如常更排除气分水道之病，瘀血内结故脉结，与「血在下如狂」相应，桃核承气汤下瘀而愈。", ["沉", "结"]], "16611": ["病机", "脉弦数，弦主少阳、主痛，数主热，合经行感寒中断、往来寒热、少腹及胁下痛如被杖、舌苔白而暗，正是热入血室、其血必结之候。邪结血分故脉弦，热郁故数，如疟状者少阳枢机不利，故以小柴胡汤加归、芍、桃仁、红花等和解兼行瘀。", ["弦", "数"]], "16612": ["病机", "脉弦结，弦主痛、主瘀滞，结为血行不畅，合形色瘦暗、左乳下痛、夜不能寐、按之愈痛，且三年前乳下曾被推压，显系瘀血内伏、久病入络。脉结正是瘀阻之征，故断为瘀血成痨之根，以小柴胡汤加归、芍、桃仁、红花等行瘀而愈。", ["弦", "结"]], "16613": ["预后", "脉弱而散，弱为气血衰微，散为根本离散、五脏真气将绝，合肌肉大退、面色惨白、舌淡红干晦、语声不扬、二便艰涩、饮食锐减，显系五液俱竭、阴阳离决之候。脉散无根，故断为疾不可为，仅以参膏淡汁少延时日，属死脉预后之论。", ["弱", "散"]], "16614": ["病机", "脉微细无神，微为阳气衰微，细为阴血不足，无神则胃气将败，合两目俱盲、神思昏乱、舌无苔而干晦，系久服姜附毒烈劫烁肾精，水阴不能上济，心肾俱伤。目盲由精劫，神乱由心失所养，故曰「并盲于心」，脉微细无神正应此阴精阳气两竭之机。", ["微", "细"]], "16615": ["其他", "本段未识别脉名，纯论时行水痘挟疫之传染与轻重转归，谓疫痘多由淫毒传染，见症轻重随其人阳气强弱及已否出痘、内毒微甚为转移，阳气强而未出痘者热轻。所论在疫毒病机与证候轻重，不涉脉象，故脉象要素为空。", []], "16616": ["病机", "脉缓略带弦象，缓为脾虚血少，弦为肝郁血滞。患者年五十，体羸素偏血虚，舌裂作痛无苔色紫暗，乃心肝脾血虚兼瘀、郁而化热之象。脉缓非平和之缓，而是气血不足、脉道不充之缓；弦为肝血瘀滞、木郁不达。故前医补血活血清血热不效，后以温通活血（当归、川芎、姜黄、桂尖等）而愈，正合脉弦主瘀、脉缓主虚之机。", ["缓", "弦"]], "16617": ["病机", "脉弦主少阳枢机不利，兼瘀血内阻。产后瘀血未净，复感外邪，往来寒热、舌苔白滑，为少阳证兼瘀。弦脉应肝胆，主气机郁滞，故用小柴胡去参加桂尖和解枢机，寒热止。后腹痛有形拒按，瘀血内结，脉仍当弦，以四物去地黄加桃仁、肉桂、大黄下瘀而瘳。弦脉在此示少阳不和与瘀血内结之病机。", ["弦"]], "16618": ["病机", "脉沉实主里实热结。产后虽多虚，然此妇外感后复作，日晡发热、烦躁谵语、大便难、腹痛拒按，显系阳明腑实。沉为病在里，实为邪气盛，故用大承气汤峻下。前医拘于“产后责虚”而进四物加味，反益剧。此段以脉沉实证明产后亦有实证，当凭脉辨证，不可拘泥产后多虚之说。", ["沉", "实"]], "16619": ["病机", "脉弦数主瘀热内结。产后两足痛如锥刺、痛处微热拒按、舌苔黄，为瘀血久留化热、阻滞经络。弦主痛、主瘀滞，数主热，故用桃核承气汤以肉桂易桂枝，下黑粪而瘥。此脉弦数非表热，而是瘀血化热之里实证，与舌苔黄、痛处热拒按相应，示瘀热互结之病机。", ["弦", "数"]], "16620": ["病机", "脉弦数主湿热内蕴兼木郁。腹脐畏寒而痛、火炉贴熨，似属寒证，然舌红苔黄厚、脉弦数，实为湿热郁遏、阳气不达之假寒。弦为肝木郁滞，数为湿热内蒸。前服温补无效，反助湿热。故用平胃散合左金丸清化湿热、疏肝解郁，冷痛大减。此脉示湿热木郁之真象，揭假寒之误。", ["弦", "数"]], "16621": ["病机", "脉浮而带数，浮主表、主上部，数主热毒。面及四肢露痘形，实为广疮（梅毒）之疹，非水痘。浮数之脉示热毒郁于肌表血分，故用龙胆泻肝汤加味清泻肝经湿热毒邪。此段脉浮数说明毒热在表在络，与面上四肢疹形相应，非时行水痘之表证，乃花柳毒邪外发之病机。", ["浮", "数"]], "16622": ["病机", "脉弦数主疟邪内郁、热盛伤津。瘅疟舌苔黄、口大渴，弦为少阳疟邪，数为热盛。前服杂乱方无效，故重用白虎汤清阳明气分大热，后合黄连阿胶汤加减，热退后以甘寒养阴收功。此脉弦数示疟热炽盛、津液受灼之病机，与口渴苔黄相应，非寻常疟疾可比。", ["弦", "数"]], "16623": ["病机", "脉洪数无伦、洪促，主瘟热毒邪充斥表里、气分热盛。口渴、身大热、汗如注，洪为热盛脉道宽大，数为热急，促为热盛而脉行急迫不匀。此瘟热重症，非大剂清凉不克，故疏清瘟败毒散。病家疑药过凉，卒以桂附戕命。此脉示热毒鸱张、正气受迫之危候，与大汗大渴相应。", ["洪", "数", "促"]], "16624": ["病机", "脉洪数，洪为热盛，数为热急，此热毒内陷，燔灼气血，故见咳嗽吐血、口破流血、牙龈唇舌皆肿、臭涎如泉涌出。热结大肠则大便亦结。洪数之脉正合大黄黄连泻心汤苦寒直折之治，三剂平复，说明脉证相应，热毒得解。", ["洪", "数"]], "16625": ["病机", "脉沉实搏指，沉主里，实主邪盛，搏指为有力，滑数主热与积滞。此里实热结，腑气不通，故肚腹硬痛、手不可按、大便不利、小便黄、身微热汗出。舌鲜红苔黄亦为热象。脉证合参，当为阳明腑实，宜攻下泄热。", ["沉", "实", "滑", "数"]], "16626": ["病机", "脉浮大，浮主表、主上，大主热盛。此肺热壅盛，无从宣泄，急奔大肠，故身热咳嗽、下利清谷、口渴。舌红苔白亦示热郁于肺。喻嘉言所谓肺热移于大肠，泻白散清肺热兼润大肠，数服而瘥，脉证相符。", ["浮", "大"]], "16627": ["病机", "脉浮而虚，浮为气浮于外，虚为正气不足。秋燥泄泻日数十度，阴液大伤，气随液泄，故脉虚浮。身热微咳为燥热伤肺，舌淡白薄而杂露红点，示气阴两伤。前医消散疏利温补升提皆误，愈治愈乖，喻氏法养阴清燥始平。", ["浮", "虚"]], "16628": ["病机", "脉浮缓，浮主虚阳上浮，缓主湿或虚。咳嗽喘急涌痰，昼夜不能安枕，舌苔白而黯，此阴虚于下，冲气上逆，痰饮随冲气上壅。浮缓非表证，乃虚阳夹痰之象。金水六君煎滋阴化痰降冲，一剂知，二剂愈，脉证相合。", ["浮", "缓"]], "16629": ["病机", "脉微缓，微为阳气衰微，缓为脾土虚弱。泄泻两月，仅余皮骨，肚腹不作胀痛，舌淡红苔白薄，时以开水漱口而不欲咽，此脾肾虚寒，下多亡阴。温燥固涩升补不效，景岳胃关煎温补脾肾，初服即十愈七八，脉证相应。", ["微", "缓"]], "16630": ["病机", "脉沉紧，沉主里，紧主寒主痛。呕吐清汁、头痛不能举，舌苔白湿滑，口中和，此寒邪内犯，浊阴上逆，胃气不降。医以风寒发散益剧，因里寒非表。吴茱萸汤温中降逆，一剂知，三剂疾如失，脉沉紧正合里寒之机。", ["沉", "紧"]], "16631": ["病机", "脉弦数，弦主痛主肝胆，数主热。先患外感，杂投方厚一寸，后更腹痛而呕，舌红苔黄口苦，此邪郁少阳，胆热犯胃，气机不畅。黄连汤清上温下，和胃降逆，一剂可愈。脉弦数示热郁而痛，与腹痛呕逆相应。", ["弦", "数"]], "16632": ["病机", "脉微缓，微为阳气不足，缓为脾胃虚弱，合之中气下陷。患者年六十，泄泻日十余行，腹胀痛，误行气消胀益剧，舌苔白、口中和、饮食不美、困顿不能行，皆脾虚气陷、运化失职之象。脉证相参，非实胀，故用补中益气汤升提中气，加固脂、益智温涩止泻而瘥。", ["微", "缓"]], "16633": ["病机", "脉弦数，弦主痛、主肝经郁滞，数主热；洪大弦数则热毒炽盛、气血壅滞。症见两胯横痃胀痛红肿、口中苦、舌苔黄，显系淫毒下注、热壅血瘀。前医败毒清解不应，因毒坚凝非峻利不能胜，故以桃核承气汤去甘草合控涎丹加木鳖、甲珠，下黑臭水而消。", ["弦", "数", "洪", "大"]], "16634": ["病机", "脉弦，为气机郁滞、寒热错杂之象。患者外感数月屡变不愈，胸满、上身热而汗出、腰以下恶风，夏月以被围绕，舌苔淡黄，乃上热下寒、枢机不利。前服清利之品不效，故用附子泻心汤寒热并用，泻心通痞、温经回阳，二剂而疾如失。", ["弦"]], "16635": ["误治", "脉浮数，为温邪在表；洪大则热盛于里。冬温发热口微渴，舌无苔，本宜辛凉平剂频服。主人疑药凉，三日仅进一剂，致邪不外解而内陷，转见大渴大汗、脉洪大，乃阳明热盛之候。此段明言温病误表、温补升提之害，故改白虎汤清解，示人不可延误。", ["浮", "数", "洪", "大"]], "16636": ["主病", "脉紧，主寒、主痛。胸满头痛喜呕，舌苔白滑，为寒饮内停、浊阴上逆，胃失和降。前医发散不愈，因非表邪，乃肝胃虚寒、饮邪上犯。吴茱萸汤温中降逆、散寒化饮，方证相应，两服而瘥。", ["紧"]], "16637": ["病机", "脉沉缓，沉主里、主水，缓主湿。外感屡变后，两脚跟肿痛热如火燎、不可履地，舌苔白滑，乃肾阳不足、水湿下注，郁而化热。此非实热，故用附桂八味加独活、豆黄卷温肾利湿，一剂热减肿退，三剂步履如常。", ["沉", "缓"]], "16638": ["病机", "脉沉数，沉主里，数主热，与上案脉沉缓异。同见脚跟肿痛热如火燎，舌苔白滑，而脉沉数，为湿热下注、蕴结筋骨。故不用温补，而用六味加苍术、黄柏滋阴清热、燥湿降火，湿热去则肿痛自瘳。", ["沉", "数"]], "16639": ["病机", "脉弦缓，弦主湿郁气滞，缓主湿。夏月外感误治，下痢红白日数十行，腹不痛胀但满而多气，口中淡、不饮食、傍晚微热、头重晕，小便时黄时清，乃风湿未从外解、久郁化热，似痢非痢。故以胃苓汤加减化湿和胃，非套方治痢。", ["弦", "缓"]], "16640": ["主病", "脉弦滑，弦主肝经湿热郁滞，滑主湿浊痰热内蕴。患者喜狎邪游而淋浊赤白交下、痛不可支，乃湿热下注膀胱、气机不畅之象，弦滑正合湿热壅盛之实。故以八正散清利湿热，后转二陈加萆薢、苍柏、滑石化湿浊而瘥，脉证相符。", ["弦", "滑"]], "16641": ["病机", "原文未识脉名，仅言不可按脉、舌苔淡白。痛处适当骨节，断为历节风，乃风寒湿干于血分、阻遏气道，肝主筋藏血，血分受邪故剧痛。舌淡白示寒湿偏盛，不可按脉因痛剧拒按，非脉象本身。治以养血通络、以节入节，属病机推求而非凭脉。", []], "16642": ["预后", "脉细数按之散，细为阴血亏耗，数为虚热内扰，散则元气涣散不收。疟母日久，左胁少腹扛起如臂、骨瘦如柴、饮食不入，正气已竭，脉见散象乃胃气将绝、元气就绝之征，故断为治亦无功、抵家而没，属凭脉决预后之例。", ["细", "数", "散"]], "16643": ["主病", "脉浮大而缓，浮大似表实，然缓为脾虚气弱之象，合口味淡、舌苔白滑，知非外感风寒风热，乃中气不足、清阳不升致头痛。前医疏散风热益剧，正因虚作实治。补中益气加川芎、蔓荆、细辛升清止痛，一服知，脉证相合。", ["浮", "大", "缓"]], "16644": ["病机", "脉沉弦，沉主里、主水饮，弦主痰饮癖积。两胁蛙声鼠叫、咳则乳下痛、吐清水、泻水，皆痰饮停聚胁下、走窜上下之象。沉弦正合仲景痰饮脉，故断为痰饮作祟，以控涎丹攻逐，非鬼神之奇疾。", ["沉", "弦"]], "16645": ["病机", "脉沉微，沉主里、微主阳气衰微。年六十痰嗽日久，忽手足麻痹、喘急痰涌、汗如泉溢、口不能言，乃阳气暴脱、痰浊上壅之危候。沉微示元阳欲绝，故用黑锡丹镇纳、通脉四逆回阳，姜汁灌服、吴茱萸敷足心以拖住元气，脉证俱属虚脱。", ["沉", "微"]], "16646": ["主病", "脉沉紧，沉主里、紧主寒主痛。冒风远行患寒疾，变脐腹绞痛、冷汗不止、手足痹软、二便不通，舌苔厚白而暗，乃寒积内结、阳气被遏之实寒证。沉紧正合寒积在里作痛之脉，故断为寒积，非寻常药饵可治，须温下攻积。", ["沉", "紧"]], "16647": ["主病", "脉浮滑，浮主病位在上在表，滑主痰热壅盛。咳嗽胸痛、痰涎臭不可近，乃热毒壅肺、血腐成痈之象，浮滑正合肺痈痰热之脉。故直断为肺痈，与《千金》苇茎汤清肺化痰排脓，数服而瘥，脉证相应。", ["浮", "滑"]], "16648": ["病机", "脉浮而微数，浮为表未解，微数为里有热。前医见咳嗽发热口渴，误作小青龙汤证，然小青龙汤证脉当浮紧，今脉不紧而微数，知非寒饮，乃水热互结之猪苓汤证。小便不利、口渴、发热，正是水热内蓄之征，脉浮微数反映表邪未罢而里热已生，故以猪苓汤清热利水。", ["浮", "数"]], "16649": ["主病", "脉浮紧为外感风寒之象。患者腹痛里急、赤白杂下、身微恶寒，先日食面受凉，遂发痢疾。浮紧脉说明新感外邪束表，表气不通，里气不和，故先以平胃散加羌活、防风等剪除外邪，表解后再用大承气汤攻逐里积。此脉主外感诱发痢疾，表邪未解之际，当先解表。", ["浮", "紧"]], "16650": ["病机", "脉弦数，弦主肝胆，数主热。患者头晕痛猛不可当、心烦口苦、手足热而麻木、舌红苔黄、小便黄涩，皆肝火内盛、风阳上扰之候。弦数脉反映肝经火热亢盛，风火相煽，故用风引汤清热降火、平肝熄风。此脉主肝火化风之病机，与头晕痛、心烦口苦等症相应。", ["弦", "数"]], "16651": ["病机", "脉紧而数，紧主寒，数主热，紧数并见，为寒热错杂之象。患者胸中痞满、欲呕不呕、大便溏泄、腹中水奔作响，正是胃中不和、寒热互结于中焦。紧数脉反映寒热错杂、升降失常之病机，故用生姜泻心汤寒热并用、辛开苦降，以调中焦。此脉主寒热错杂之痞证。", ["紧", "数"]], "16652": ["主病", "脉沉迟，沉主里，迟主寒。患者时有气痛自脐下小腹上冲至心，夜间尤甚，舌苔白滑，乃下焦阴寒之气上逆之奔豚证。沉迟脉说明里阳不足、阴寒内盛，寒气循冲脉上冲，故用桂枝加桂汤温通阳气、平冲降逆。此脉主下焦寒逆之奔豚病机。", ["沉", "迟"]], "16653": ["病机", "脉弦数，弦主肝，数主火。患者气痛从少腹上冲胸及咽喉，口苦咽干，寒热往来，舌苔白，乃肝火上逆之奔豚。弦数脉反映肝经火盛、气火上冲之病机，与肾水上逆之奔豚脉沉迟者不同。故用《金匮》奔豚汤清肝降火、平冲逆。此脉主肝火奔豚，为罕见之证。", ["弦", "数"]], "16654": ["病机", "脉涩，涩主血行不畅、瘀血内阻。患者胸中窒塞无聊、短气难言、呼吸艰阻，按摩或足抵其胸则舒，舌色暗，乃肝著之证。涩脉说明肝经气血瘀滞，胸阳不展，故用旋覆花汤或通窍活血汤活血通络。此脉主肝著瘀血阻络之病机，与胸中窒塞、短气等症相应。", ["涩"]], "16655": ["病机", "脉微涩，微主气血不足，涩主血行不畅。患者瘦弱异常，时时欲哭不可忍，状如神灵所作，乃脏躁之证。微涩脉反映阴血亏虚、脏气不足、神失所养之病机，故用甘麦大枣汤养心安神、缓急润燥。此脉主脏躁之阴血不足，与悲伤欲哭、数欠伸等症相应。", ["微", "涩"]], "16656": ["主病", "前案脉洪数，为胃热炽盛之象，热灼津伤则大便硬，胃热上逆则食入即吐，故用大黄甘草汤泻热存阴。后案脉微缓，为胃虚气逆，舌苔白亦示中焦虚寒，故用大半夏汤补虚降逆。两案脉象对比，一实一虚，皆主反胃，然病机迥异，洪数主实热，微缓主虚寒。", ["洪", "数", "微", "缓"]], "16657": ["病机", "脉弦发热，腹痛恶寒，少腹如扇，舌苔白滑，此子脏开而寒邪内侵，阳虚阴盛之候。脉弦为寒饮内动，发热非表热，乃阳浮于外。仲景以附子汤温其脏，正合《内经》「有故无殒」之旨。脉弦在此主寒，与妊娠禁忌无关，示医者不可拘泥。", ["弦"]], "16658": ["兼症", "脉两寸浮，两尺如无，为呕恶不止、气逆于上而中下焦虚竭之象。寸浮主气逆，尺无主根本空虚，故气息奄奄，势甚危急。用六君加旋覆花代赭石，补中降逆，使吐少咽多，脉象当随症减。此段示妊妇病急，不可拘禁，当以适可为止。", ["浮"]], "16659": ["主病", "脉沉滑，腹中隐痛胀满，乍寒乍热，口渴，按腹濡而痛，间露紫筋，此肠痈已成，热毒壅聚于内。沉主里，滑主实热，故宜大黄牡丹汤下之，使热毒从下而解。若误以发散，则益剧。脉沉滑在此主里实热结，与肠痈内溃相应。", ["沉", "滑"]], "16660": ["预后", "此段未识脉名，专论肠痈溃后之预后。脓血从便出或脐出，皆属内溃危候，医者误作痢治或外掺，多致死亡。文中「腹热肿胀，筋露青紫，满面青暗，气息奄奄」为脓毒内陷、正气衰败之象，食指商阳穴疮溃烂不休，亦大肠痈之外候。脉象虽缺，然症候已示凶险。", []], "16661": ["病机", "脉弦缓，产后烦热不得卧，小便不得，腹胀满，此转胞之候。弦为气机郁滞，缓为湿浊内停，肾气不化，膀胱气化不利，故不得溺。肾气丸温阳化气，使小便通而烦热除。脉弦缓在此主肾虚气化失司，非表证，亦非五苓散所宜。", ["弦", "缓"]], "16662": ["主病", "脉浮数，咳嗽喘急，目突泪流，舌苔白薄，时值夏至，此肺胀之候。浮主邪在表，数主热，然喘急目突为饮热壅肺，气逆于上。越婢加半夏汤宣肺泄热，降逆化饮，使邪从表解，饮从下降。脉浮数在此主表邪兼肺热，不可拘泥时禁而纯用疏散。", ["浮", "数"]], "16663": ["平脉", "脉平不弦，患疟每日申时发热，不恶寒，身疼痛，欲呕不呕，舌苔白薄，此温疟之候。脉如平，示邪不在表，亦非少阳弦脉，乃热盛于内而外无寒邪。白虎加桂枝汤清里热兼透表，使热从外达。脉平在此非无病，乃温疟之特殊脉象，与《金匮》「其脉如平」相应。", ["平"]], "16664": ["病机", "脉不弦而沉数，沉主里，数主热，结合舌黑少液、口干漱水，知非少阳疟疾，乃肾阴虚而相火内动。前医误用柴胡、温燥，更伤阴液，故烦躁不宁。此脉说明病机在肾阴亏虚、相火妄动，主阴虚发热类疟症，与舌黑、口干、漱水等症相应。", ["沉", "数"]], "16665": ["病机", "脉紧数，紧主寒邪外束，数主热郁于里，结合寒热、骨节烦疼、无汗、口渴、二便不通，舌红苔白，为表寒外闭、里热壅盛之证。紧数并见，说明寒热交争、表里俱实，故用防风通圣散双解表里而瘥。", ["紧", "数"]], "16666": ["病机", "脉沉缓，沉主里，缓主湿，结合两脚骨节疼痛、舌苔淡白、欲食、二便如常，知为寒湿痹阻下焦，气血不畅。沉缓说明病在里而湿邪偏胜，非热非实，故用七节汤加牛膝温通渗湿而愈。", ["沉", "缓"]], "16667": ["病机", "脉缓，缓主湿，结合手足迟重、口中淡、不饮食、懒言语，知为寒湿困阻中焦，阳气不布。缓脉说明湿邪黏滞、非急非数，故断为寒湿，用麻黄加术汤散寒除湿而愈。", ["缓"]], "16668": ["病机", "脉浮，浮主表、主虚，结合大病一月后近状如百合病，知为热病后阴液未复、虚热浮越。浮脉说明病位偏表而正气已虚，故以百合、玉竹、麦冬甘润养阴，使虚热自退而愈。", ["浮"]], "16669": ["病机", "脉弦，弦主饮、主痛，结合背冷如冰、按之不痛、舌苔白滑，知为寒痰留饮凝结心下，阳气不达。弦脉说明水饮内停、气机不畅，与《金匮》留饮背冷相合，故用控涎丹下痰涎而瘳。", ["弦"]], "16670": ["病机", "脉细涩，细主血虚，涩主血滞，结合顿呛连声、头倾胸曲、手足痉挛，知为毛窍受寒、胞血凝涩，血不濡养筋脉。细涩说明血虚而滞、肝失濡养，故以当归四逆汤养血通脉而愈。", ["细", "涩"]], "16671": ["病机", "脉弦滑，弦主饮、主痛，滑主痰，结合体肥嗜酒、胸中痞满、重捶少止、舌苔白，知为湿热素盛、痰饮内结，甚则生虫。弦滑说明痰湿壅盛、气机郁滞，故用莱菔子涌吐痰涎而疾失。", ["弦", "滑"]], "16672": ["主病", "脉沉紧，沉主里，紧主寒主痛。疝病疼痛肿胀异常，恶寒，舌苔白，显系寒邪内盛，凝滞肝脉。初与当归四逆加吴茱萸汤不应，乃因寒重药轻，加附子、干姜温阳散寒，三剂而愈。脉沉紧正合寒疝里实之机。", ["沉", "紧"]], "16673": ["主病", "左手沉数，沉主里，数主热。前阴热痒，爪搔至皮破血流，舌苔白，乃肝经湿热下注。龙胆泻肝汤清泻肝火、利湿止痒，服之而瘳。脉沉数提示热郁于里，与阴痒症候相应。", ["沉", "数"]], "16674": ["病机", "脉濡缓，濡主湿，缓主脾虚。患者坐卧湿地，湿热侵入血室，致恶食、月事不行，舌红苔白。濡缓之脉反映湿阻气机、脾运不健。以小柴胡汤合二妙散加萆薢、桃仁、归、芍，清利湿热、活血通经，三剂月事行。", ["濡", "缓"]], "16675": ["病机", "脉弦缓，弦主肝郁，缓主湿滞。体肥嗜酒，酒食侵淫，肺失治节，肝木郁而生虫，肤痒搔之虫蠕蠕。弦缓之脉示肝郁脾湿。以补中益气汤倍柴胡加白芍、蒺藜等，升清疏肝、化湿杀虫，并戒酒，旬日而愈。", ["弦", "缓"]], "16676": ["病机", "脉弦滑，弦主少阳，滑主痰热。往来寒热，胸中痞塞，前医发散益剧。此痰热阻于膈膜，少阳之气通于膈，故寒热。弦滑之脉正合痰热内阻。以小柴胡合小陷胸汤和解少阳、清热化痰，一剂知，二剂已。", ["弦", "滑"]], "16677": ["主病", "脉沉微，沉主里，微主阳衰。肚腹膨胀，饮食锐减，骨瘦身微热，贪眠，舌苔白暗而黑，显系阴寒重症，阳气衰微。沉微之脉与阴寒内盛相应。疏理中汤加附子温中散寒、回阳救逆，连服数剂而平复。", ["沉", "微"]], "16678": ["妇人", "娠已及期，腹痛甚，脉沉缓无力，舌苔白。沉缓无力非正产之脉，乃气血不足、胞宫无力。与十全大补汤去桂加鹿胶、艾叶，补益气血、温养胎元，一服平复，后又十余日而娩，母子俱安。此案示人勿先事慌张。", ["沉", "缓"]], "16679": ["主病", "脉沉紧，沉主里，紧主寒主痛。当暑月忽左足疼痛，卧床不可转侧，舌苔白，口中和，此风寒直中少阴。沉紧之脉与少阴寒证相应。用麻黄附子细辛汤温经散寒，药仅三钱，一服知，二服步履如常。", ["沉", "紧"]], "16680": ["病机", "脉浮大而滑，浮主上焦，大示邪实，滑为痰饮之征。患者头晕、面色惨晦、状如痴人，舌苔白，显系痰饮上逆，蒙蔽清窍。滑脉主痰，浮大示饮邪上泛，故断为痰饮上逆，与温胆汤加旋覆、赭石、南星等降逆化痰，一剂知，二剂愈。", ["浮", "大", "滑"]], "16681": ["病机", "脉浮洪而数，浮为表邪未解，洪数主里热炽盛。症见恶寒发热、无汗、口渴、二便不通，舌红苔白如霜，乃表症未除、里症复急。浮洪数脉提示表里俱热，故用防风通圣散表里两治，两剂而瘳。", ["浮", "洪", "数"]], "16682": ["妇人", "脉涩弱，涩主血少，弱主气虚。患者素体弱，孕后昏迷、四肢冷、面惨白，乃气血虚弱，胎结阻滞正气，不能周流所致之子痫。涩弱脉正合气血两虚，故用归脾汤补养调之，一剂知，数剂愈。", ["涩", "弱"]], "16683": ["病机", "脉浮大满指，按之紧数。紧为寒，数主热，浮大示邪在表。症见寅卯时喉间火冲、连咳、口微苦、气粗、舌红苔白，乃寒包热也。紧数并见，说明外寒束表、内热伏郁，故用小青龙汤加石膏解表清里，一服知，再服已。", ["浮", "大", "紧", "数"]], "16684": ["病机", "脉弦缓，弦主湿阻气机，缓主湿邪黏滞。患者大小便不通、腹胀、舌苔白、口淡，前医误作暑热或通利，益剧。弦缓脉提示风湿阻滞，肺失治节，脾失转输，故用麻黄加术汤加紫菀宣肺健脾化湿，一剂知，再剂已。", ["弦", "缓"]], "16685": ["病机", "脉洪大而数，洪大为热盛，数主热毒炽盛。症见大热大渴、汗出、目红肿、口舌肿裂流血、头痛如劈、腹痛泄泻臭秽，乃温热疫毒充斥表里。洪大数脉示热毒鸱张，故用大剂清瘟败毒散加减，后发红斑，仍守方而愈。", ["洪", "大", "数"]], "16686": ["妇人", "脉涩弱，涩主血少，弱主气虚。患者体素羸弱，经断三月，腹动似娠，两乳略起有清汁，然脉始终涩弱不变。涩弱脉示气血虚衰，非真胎之滑数，故断为娠殊未确，纯由气积，酷肖真胎，脏腑无碍，可美膳调之，不必用药。", ["涩", "弱"]], "16687": ["病机", "脉弦迟，弦主痛、主积，迟主寒。患者每月事将行时腹中痛、大便下白脓，乃内有积寒，寒凝气滞，故脉弦迟。弦迟脉示寒积内结，当以温药下之，用温脾汤。后服法得当，下黑粪甚多而愈，印证积寒得下。", ["弦", "迟"]], "16688": ["主病", "脉弦紧主寒湿内盛、气机郁滞。患者泄泻日数十行，腹胀痛不可忍，舌苔白湿滑，显系寒湿困阻中焦，脾胃升降失司。弦为气滞，紧为寒凝，脉证相合，故主寒湿泄泻。前医误补，致邪愈壅，病势转危，正合‘脉之弦紧’所示实邪未去之机。", ["弦", "紧"]], "16689": ["病机", "脉数而促，主热盛邪实、气机壅遏。患儿发热口渴、腹痛拒按、苔黄燥、便不畅，乃食积化热、腑气不通之候。数脉为热，促脉示热盛而气促急迫，与‘痛处不可手按’相应。下后脉不促，证明邪去热退，脉随病解。", ["数", "促"]], "16690": ["病机", "脉沉微主肾阳衰微、虚阳浮越。前阴后阴肿痛、咽痛，似热而实非真热，乃‘肾阳不潜，浮游之火蔓延上下’。沉为在里，微为阳衰，舌苔白滑更证虚寒。故以肾气丸温纳浮阳，三剂而愈，脉证相参，知非实火。", ["沉", "微"]], "16691": ["主病", "脉沉紧而弦，主寒饮内结、胸阳不振。胸背痛遇寒加剧，晚间噎食臭、腹胀，晨泄，舌苔灰白，显系寒饮上逆、中阳不运。沉紧为寒饮内伏，弦主痛主饮，与‘胸背作痛’相应。温下后痛止，脉证相符。", ["沉", "紧", "弦"]], "16692": ["主病", "脉浮紧主太阳伤寒表实证。发热恶寒、身痛无汗、烦躁，苔白薄，正合大青龙汤证。浮为邪在表，紧为寒束，脉证相应。虽年近七旬，体气素旺，仍从表实论治，服大青龙而疾减大半，证明脉浮紧确为表寒实证之凭。", ["浮", "紧"]], "16693": ["病机", "脉弦数主少阳郁热、疟邪内蕴。疟热多寒少、大渴多汗，服金鸡纳霜后疟止复作，渐至浮肿，舌红苔白。弦为少阳枢机不利，数为热盛，故以小柴胡和解，加花粉、知母清热生津，疟止肿消，脉证相合。", ["弦", "数"]], "16694": ["主病", "脉紧而缓，主寒湿内盛、水气不化。遍身肿胀色黄暗，饮食锐减，苔灰白厚滑，显系寒湿困脾、水湿泛滥。紧为寒，缓为湿，与‘肿胀’相应。先以五皮饮加风药微汗，继以真武汤温阳利水，脉证相符。", ["紧", "缓"]], "16695": ["病机", "脉浮大而虚，主虚寒中气下陷、阳气外浮。腹胀痛泄泻不止，肌冷汗出，呼吸急促，饮食不入，苔灰暗湿滑，显系误用破气消耗致中气败伤。浮大无力为虚阳外越，虚为正气亏耗，故以补中益气汤加乌附、干姜温补升提而瘳。", ["浮", "大", "虚"]], "16696": ["病机", "原文以脉浮紧、弦数言太阳病不解，热结膀胱，热入血室。浮紧为表寒未罢，弦数主热入血分，血热互结，故见如狂、少腹急结。脉象反映表邪入里化热，与血相搏，病机在血分热结，非单纯气分热盛。", ["浮", "紧", "弦", "数"]], "16697": ["主病", "脉洪大而缓，洪大为阳明热盛，缓主湿邪。症见大汗大渴、身大热、谵语，为三阳合病；足下畏风而冷，兼湿之征。脉洪大应白虎汤证，缓则示湿，故用白虎加苍术，脉象与症合参，主湿热内蕴。", ["洪", "大", "缓"]], "16698": ["病机", "脉弦数，弦主痛、主瘀，数主热。小产后瘀血停蓄，少腹硬痛拒按，溲便不通，舌红苔白，脉症合参，为瘀热互结下焦。弦数反映瘀血化热，气血壅滞，故用桃核承气变通下瘀，脉象示病机在血分。", ["弦", "数"]], "16699": ["病机", "脉沉弦而缓，沉主里，弦主痛、主寒，缓主湿。久处窿内，寒湿蓄积，两足腰酸痛肿，面目暗黄，舌苔白湿滑，脉症合参，为寒湿痹阻经络。沉弦缓示寒湿内盛，阳气不布，故用麻黄五积散加附子温散寒湿。", ["沉", "弦", "缓"]], "16700": ["病机", "脉沉弦而滑数，沉弦主肝经病变，滑数主湿热。前阴热肿痛痒，口苦咽干，溲数短热，舌红苔白，为厥阴风湿化热生虫。沉弦滑数反映湿热下注肝经，与症相应，故用龙胆泻肝汤清利湿热。", ["沉", "弦", "滑", "数"]], "16701": ["病机", "脉显滑数，滑主痰湿，数主热。素嗜酒多湿，温补锢闭，痰热内蕴，胸痞呕逆，神昏耳聋，舌红苔垢，口臭。滑数脉示湿热痰浊壅盛，气机失降，故用小陷胸合温胆汤清利湿热、涤痰开结。", ["滑", "数"]], "16702": ["病机", "脉沉微，沉主里，微主阳虚。年四十余，前阴热肿痛痒，赤白淋漓，舌暗淡，口干不渴，头眩脚软，为肾家虚风。沉微示肾阳虚衰，内风煽扰，似热非热，故用八味丸加味温肾熄风，脉症合参。", ["沉", "微"]], "16703": ["病机", "脉之沉紧，沉主里，紧主寒主痛。阴寒大症，少腹有块，痛时膨胀，手足痹软，遍身冷汗，不省人事，为寒凝下焦、阳气欲脱。沉紧脉示阴寒内盛，气血凝滞，与症相应，故用乌附温阳散寒。", ["沉", "紧"]], "16704": ["病机", "脉沉极而滑，沉主里，滑主痰热。患者胸中窒塞、口苦呕恶、便滞、气喘谵妄，舌绛苔浊，显系痰热内闭。前医误用温补，阻塞肺胃升降之机，致痰热无从宣泄，故脉见沉滑。此脉象反映邪实内壅、气机不通之病机，非虚寒可温补。", ["沉", "滑"]], "16705": ["主病", "脉紧数，紧主寒、主痛，数主热，滑主痰。症见恶寒发热无汗、骨节烦疼，为伤寒表实；腹胀、二便不通、舌绛苔垢，为里热壅盛。脉紧数滑，示表寒里热、痰热内结之病机。先以防风通圣散双解表里，后转疟见脉滑数，为痰热未清，故用小陷胸合温胆汤清化痰热。", ["紧", "数", "滑"]], "16706": ["误治", "脉洪大而滑数，洪大主热盛，滑数主痰热。症见大渴大汗、舌绛苔厚如积粉、胸满而喘、谵语，为湿热挟痰壅盛。脉不弦，则非少阳证，前医误用柴胡升发，致肺胃失降，诸经之气上逆，助桀为虐。此段明辨脉不弦者与少阳无涉，误用柴胡反增病，救误当荡涤痰饮、清利湿热。", ["洪", "大", "滑", "数"]], "16707": ["病机", "脉浮大而虚，浮大似实，按之虚软，为元气浮越之象。患者陡患狂妄、手足躁扰，似狂非狂，实因惊骇忧思，心神飞越，非实热狂乱。脉虚为关键，断为虚狂，故用大剂归脾汤补益心脾，一帖而安。此脉示元气外浮、心神不守之病机，与实狂脉实大者迥异。", ["浮", "大", "虚"]], "16708": ["兼症", "脉弦缓，弦主痛、主积，缓主脾弱。患儿喜食糖点成积，间作腹痛，下白脓，舌苔淡白，脉弦缓示脾虚积滞、肝木乘土。赋禀薄弱，不敢迳下，故用理中汤加大黄，不应，继以理中合小承气，下黑粪而愈。此脉反映虚中挟积之病机，攻补兼施乃对。", ["弦", "缓"]], "16709": ["病机", "脉弦缓，弦为肝急，缓为脾虚。患者午至子手足心热、心烦不卧、短气懒言、食减身弱，舌淡白，口干喜漱不欲咽，为脾虚肝乘、虚热内扰之象。脉弦缓示土虚木贼、阴阳不和，故用黄耆建中汤温中补虚、缓肝和营，守服三十剂而安。", ["弦", "缓"]], "16710": ["预后", "脉浮缓而虚，浮为气浮，缓为湿滞，虚为正气大伤。患者昏睡不能答、气息仅属、粒米不入、舌灰暗面惨晦，疟久正溃，危殆已极。脉虚示元气衰败，预后堪忧，幸午后微热，胃气未绝，故用大剂六君加香砂草果乌梅扶正截疟，渐获转机。此脉主正虚邪恋之危候。", ["浮", "缓", "虚"]], "16711": ["病机", "脉弦滑，弦主肝、主痛，滑主痰饮。患者痰嗽呕吐、左胁下痛不可耐、舌绛苔白厚，为肝邪挟痰饮上逆，肺胃之气不能通降。前医温燥升提，愈服愈乖。脉弦滑正示肝旺痰逆之病机，故治以涤降痰饮、肃清肺胃、清热平肝，用温胆汤加旋覆赭石等而愈。", ["弦", "滑"]], "16712": ["病机", "原文“诸脉如常，惟左寸略微细”，左寸候心，细为气血不足，心气亏虚，故“每有劳动，或用心稍过，即痛甚”，劳则耗气，心脉失养而痛。舌淡白、面㿠白、神不敛，皆气虚血弱之征。脉细主虚，与心气痛因虚而作相应，故用归脾补益心脾而效。", ["细"]], "16713": ["病机", "原文“脉浮大，按之虚散”，浮大似实，按之虚散则中空，为血虚气浮、阴不敛阳之象。产后患感，身微热、口渴漱水、面若火烘、头晕目眩，皆血虚阳浮所致。脉浮大而虚散，正合“血虚发热”之机，故用当归补血汤补气生血而安。", ["浮", "大", "虚", "散"]], "16714": ["病机", "原文“脉浮数而促”，浮为邪在肺卫，数为热盛，促为热迫气急。秋燥之邪，误用表散温燥，致肺金受伤，热移大肠而泻，喉痛咳血、身热汗出、红斑，皆燥热燔灼之候。脉浮数而促，主燥热内盛、肺失治节，故用养阴清肺加石膏、知母清润而愈。", ["浮", "数", "促"]], "16715": ["病机", "原文“脉浮大而数”，浮大数为阳明余热未清之象。伤寒逾月，口渴时呕，小溲不禁而遗，乃余热上灼肺金，治节无权，不能收摄津液。脉浮大而数，主热盛于上而气不降，与竹叶石膏汤清余热、复治节，故三帖霍然。", ["浮", "大", "数"]], "16716": ["病机", "原文“脉洪大而缓”，洪大为阳明热盛，缓为湿热蕴蒸，且“脉无弦象”以别少阳。单热无寒、大渴大汗、两足冷，系阳明湿热，热盛于里而湿阻于下。脉洪大而缓，主湿热内蕴，故用白虎加苍术清阳明、化湿浊。另一例脉浮大而缓，兼身痛喜呕，为表有风寒，故加桂枝。", ["洪", "大", "缓"]], "16717": ["病机", "原文“脉浮洪而弦数”，浮为表有风寒，洪数为里热炽盛，弦主痛、主实。两手拳曲振掉、身大热、面赤口渴、二便不通，皆表寒外束、里热内结之候。脉浮洪弦数，正合表里俱实之机，故用防风通圣散表里两解，汗下兼行而愈。", ["浮", "洪", "弦", "数"]], "16718": ["病机", "原文“脉洪大而促”，洪大为阳明热盛，促为热盛气急。冬温误表，致身大热、大渴、汗出如浴、头痛如劈、咳嗽欲呕，舌鲜红有刺，皆热炽于里、迫于气分。脉洪大而促，主热盛而气机急促，故用大剂白虎加黄连、黄芩清泄里热而愈。", ["洪", "大", "促"]], "16719": ["病机", "原文先“脉模糊不清”，为温邪初袭经络、游行肌腠，尚未内犯，故脉象云遮雾隐；至三日“脉转滑数”，滑主痰湿，数主热，示温邪渐入气分，热势显露，故旋覆胸膈痞满不舒、欲呕。脉由模糊转滑数，反映邪从表入里、热象渐著之病机。", ["滑", "数"]], "16720": ["病机", "初诊脉弦数，弦主少阳枢机不利，数主热，与左胁少腹痛连尾脊、寒热往来相应，故用小柴胡加减和解。后陡然大热大渴微汗头晕痛，脉转浮洪而促，浮洪为热盛于外，促为热迫急数，舌鲜红，示温邪内炽，与前丹药余毒之少阳证不同，属新感热病。", ["弦", "数", "浮", "洪"]], "16721": ["病机", "冬温初起误用消风败毒，致大热大渴、汗出如浴、头痛如劈、谵语舌红有刺，脉浮数而洪。浮为邪在表分未解，数洪为里热炽盛，热蒸津泄故汗多，热扰神明故谵语，脉症合参属表里俱热之温病，故用白虎加生地花粉清解。", ["浮", "数", "洪"]], "16722": ["病机", "下窿失足伤损后咳嗽、往来寒热、胸胁作痛，脉弦数。弦主少阳与痛，数主热，舌苔淡白示兼外寒。审系内部蓄瘀未尽兼感外寒，瘀阻则痛，寒束则寒热，故以小柴胡去参加桃仁红花归尾等活血散寒，药后下黑粪为瘀去之征。", ["弦", "数"]], "16723": ["病机", "遍身重痛、头晕、冷汗不止、咳嗽多涎，脉沉缓而迟，舌苔湿白。沉主里，缓迟主寒湿困阻阳气，湿性重浊故身重，寒湿遏阳故冷汗、微热，湿聚成涎故咳嗽多涎，属寒湿内盛之证，故用五积散去麻黄温散寒湿，后加附片杜仲温肾。", ["沉", "缓", "迟"]], "16724": ["病机", "大便下血如注已一月，脉弦缓，舌苔湿白。弦为肝脾不和、血不循经，缓为湿滞，舌苔湿白示湿浊内蕴，脾虚不能统血，故下血如注。属脾虚湿困、统摄失职之下血，故用黄土汤温脾摄血，以赤石脂易黄土加强固涩止血。", ["弦", "缓"]], "16725": ["病机", "下血稠黏、里急后重，脉弦数而沉，舌鲜红苔黄燥。沉主里，弦数主热，弦又主里急，舌红苔黄燥为湿热蕴结肠道、灼伤血络之象，故下血稠黏而里急后重。属湿热下利便血，故用白头翁汤清热燥湿凉血，加僵虫乌梅以缓里急。", ["弦", "数", "沉"]], "16726": ["误治", "产后恶露已尽，感冒夹食腹痛胁痛，医误作瘀血，屡用桃仁红花三棱莪术破血降气，更进桃仁承气，遂昏愦妄语。脉如蛛丝不绝、气息奄奄、手足如冰、汗出、面黑唇白、舌苔黑滑，皆阳气衰败、阴寒内盛之危候，显系破血攻下诛伐无过所致，故用通脉四逆回阳救逆。", []], "16727": ["病机", "阴寒白喉，饮水咽津痛甚，身微热，舌苔灰白或浅黄厚如结痂，脉多沉紧而弦或沉缓无神。沉紧弦主阴寒内盛、寒凝经脉，缓而无神为阳气不振，非热毒白喉，故表散寒凉十治十死，先考用通脉四逆汤温阳散寒，重剂乌附连服而愈，示寒疫白喉之脉证。", ["沉", "紧", "弦", "缓"]], "16728": ["病机", "原文未识脉名，然先考“审证究脉”后断为“中气下陷”，其脉当见虚软无力。泄泻日数十行，泻止而腹胀、欲登厕而“了而不了”，是脾胃气陷、清阳不升之征；前医误用行气疏降，反耗中气。故以补中益气汤升举中气，两帖而安，正合“中气下陷”之病机。", []], "16729": ["主病", "脉形浮弦，浮主风邪在表，弦主肝络不和。风邪袭肺则咳嗽尤甚，舌滑腻、形寒为风痰内蕴、卫阳不宣；左腋刺痛乃肝络气滞。故以清肺、和络、疏风为治，脉浮弦正提示风邪未解而络脉不和之病机。", ["浮", "弦"]], "16730": ["病机", "脉形浮弦而咳嗽尤甚，浮为风邪在肺，弦为肝络不和。风邪于肺、肺气阻痹，故咳嗽；肝络不和，故左腋刺痛。介按强调辛散轻开、俾病从表出，正合浮弦之脉所主风邪外束、肺痹络滞之病机，清肺疏风兼和络为对症之治。", ["浮", "弦"]], "16731": ["主病", "脉寸浮滑，寸候上焦肺卫，浮主风邪，滑主痰涎。风邪伏肺、咳嗽久累，已曾失血，音嘶，是风痰壅肺、肺失清肃，久咳伤络之象。故宜清肺、疏风、化痰，并“防损”，提示浮滑之脉主风痰恋肺、恐致虚损之病机。", ["浮", "滑"]], "16732": ["主病", "脉弦，舌微白，咳嗽日久，咽干音嘶，头疼。弦脉主肝，亦主饮邪与气机郁滞；久咳肺伤，木火刑金，故咽干音嘶。舌微白示风邪未尽。脉弦与呛咳、头疼相应，提示风邪恋肺、肝肺气机不和，治宜清肺疏风。", ["弦"]], "16733": ["主病", "左脉浮滑，左候肝与表，浮主风邪未清，滑主痰浊内蕴。风邪未清则咳逆，舌薄白、头疼较差，皆风痰上扰之征。浮滑之脉正说明风邪在表、痰阻肺络之病机，故治以止嗽、化痰、疏风，使表邪与痰浊并解。", ["浮", "滑"]], "16734": ["主病", "脉弦，舌薄白，迎风头疼，呛咳不已。弦主风动与气机郁滞，风邪未尽，上扰清窍则迎风头疼，犯肺则呛咳不已。舌薄白示邪未化热。脉弦与风邪恋肺、肝风上扰之症相应，故宜清肺疏风为主，使风去则咳止。", ["弦"]], "16735": ["主病", "脉数主热，风热上攻则头胀、气轮红；外寒束表、内热郁蒸，故称外寒内热；热扰心神则心悸。数脉与头胀、目赤、心悸相应，说明风热内蕴、表寒未解之病机。治宜清疏为稳，清其内热、疏其表邪，使寒热两解。", ["数"]], "16736": ["病机", "脉小数，数为热，小为阴虚，风热未清，余邪内伏，故脉小数；不时汗出乃厥阳上越，热迫津泄，阳越于上则热，此脉示风热未净而阴分已伤，阳不潜藏，主热势未解，汗出为阳越之征。", ["小", "数"]], "16737": ["主病", "脉弦细数，弦主少阳，细为阴伤，数为热，午后寒热不清，乃少阳枢机不利，邪郁半表半里，舌微黄为热渐入里，此脉主少阳邪热未解，阴分渐伤，故宜清少阳为主。", ["弦", "细", "数"]], "16738": ["兼症", "脉浮虚，浮为风邪外袭，虚为正气不足，带下腰疼乃带脉不固、肾液未充，更夹风邪犯肺，故呛咳、牙缝出血，癸涩为血虚，此脉示正虚感风，肺失清肃，宜清肺疏风为主。", ["浮", "虚"]], "16739": ["病机", "原文未出脉象，介按明言带脉不固、肾液未充，故带下腰疼；更感风热之邪，犯及肺胃，致咳呛、牙缝出血。此段论病机为肾虚带脉失约，复感风热，肺胃受邪，治当清肺胃、补肾液，调经先去病。", []], "16740": ["病机", "脉濡主湿，暑风湿热交蒸，湿性濡滞，故脉濡；舌滑微黄、脘闷欲呕，皆湿浊中阻、暑热内蕴之象，寒热交作乃邪正交争，此脉示湿邪偏盛，暑热夹湿，困阻中焦，宜和中祛邪。", ["濡"]], "16741": ["主病", "脉弦数，弦主少阳，数主热，暑邪内侵，少阳枢机不利，故寒热交作；头疼脘闷、溲数，皆暑热内扰、气机不畅之症，此脉主暑邪客于少阳，热势偏盛，宜和中清邪。", ["弦", "数"]], "16742": ["病机", "脉虚细，虚为气弱，细为阴伤，清解已效而脉转虚细，乃暑热渐退、气阴两伤；寒热交作、午后稍瘥，舌滑白根微黄、便利，示余邪未清而正已虚，此脉主暑病后气阴不足，余邪留恋，宜清暑和中。", ["虚", "细"]], "16743": ["病机", "脉濡右大，濡主湿，右大主邪盛于气分，暑风夹湿，湿性濡滞，故脉濡；右大示邪热壅盛，寒热如疟、渴饮、溲数，舌白中心嫩黄，皆暑湿内蕴、邪正交争之象，此脉示暑湿偏重，防其传变加重。", ["濡", "大"]], "16744": ["病机", "脉弦为暑湿郁阻气机、木土不和，濡为湿邪偏盛、困阻中焦。寒热未除而见弦濡，说明暑湿未清、枢机不利；舌黄滑、腹中濯濯为湿浊内停、水气走肠之象。脉症合参，主暑湿挟滞、脾胃升降失司，故治以清暑和中，使湿化气畅则寒热可解。", ["弦", "濡"]], "16745": ["主病", "右脉浮濡，浮为邪在表、肺卫受邪，濡为暑湿伤气、湿性黏滞。暑风伤肺，故头疼发热、汗微不出、身痛；肺气郁则水道不利而溲数，舌微黄为湿郁化热之征。脉浮濡正合暑湿袭表、肺气不宣之病机，宜清解透邪，防其入里变重。", ["浮", "濡"]], "16746": ["病机", "脉濡为暑湿伤气、湿困中焦，右弦细乃湿郁肝脾、气机不畅之象。脘闷发热、恶心、舌滑白、溺数，皆暑湿内蕴、气分不开所致。脉濡而右兼弦细，说明湿浊偏重而气机郁滞，故治宜开气分，使湿化气行则脘闷恶心可除。", ["濡", "弦", "细"]], "16747": ["病机", "脉虚为暑热耗气、正气不足，右濡为湿邪内蕴、脾运不健。汗出发热、舌灰黄、头目不爽、溲数，乃暑湿伤气、湿热交蒸之候。脉虚右濡正示气伤湿滞，本虚标实，故宜清热利湿，兼防正气更伤而病重。", ["虚", "濡"]], "16748": ["病机", "此按语申明肺气被郁则自汗发热、头目不爽，脉虚右濡为伤暑挟湿之征。虚因暑热耗气，濡因湿邪黏滞，右部应肺，故病位在肺卫。脉症相合，说明暑湿郁肺、气分不宣，治以辛凉轻剂清解上焦兼渗湿，正合脉虚右濡之病机。", ["虚", "濡"]], "16749": ["病机", "脉弦为暑湿郁阻、木土不和，濡为湿盛困脾，数为热邪内蒸。呕渴身热、大便自利、腹痛、舌黄滑，皆暑湿热交阻中焦、升降失常之象。弦濡数并见，说明湿热壅遏、气机逆乱，症非轻藐，故宜清热和中，使湿热分消则呕利腹痛可减。", ["弦", "濡", "数"]], "16750": ["病机", "前法后呕渴自利悉瘥，而脉仍濡、右弦数，舌黄滑，身热已缓，说明暑湿未尽、余热未清。濡主湿留，弦数主郁热未解，头晕耳鸣乃湿热上扰清窍。脉症示湿浊渐化而郁热尚存，故仍遵前法加减，清余热、化余湿以稳病情。", ["濡", "弦", "数"]], "16751": ["病机", "脉濡为暑湿伤气、湿困中焦，细为湿郁气弱、正气受困，数为湿热内蒸。潮热、溺赤、大便如酱、舌心焦黄、口甜，皆湿热蕴结、脾运失司之候。濡细数并见，说明湿中有热、气分受困，故宜清利湿热，防其变生他症。", ["濡", "细", "数"]], "16752": ["病机", "脉左濡右细，濡为湿滞，细为阴伤，结合舌黄燥、口甜、溲赤便闭，显系湿热内蕴、脾瘅化燥之机。左濡主湿郁在脾，右细示胃津受灼，故潮热虽退而口甜便闭未除，防其湿热蒙窍或化燥伤阴，故宜泻心汤加减以清渗。", ["濡", "细"]], "16753": ["病机", "两手脉弦细，弦主土虚木乘，细主阴血不足。舌嫩黄尚腻、口甜，为脾瘅未清、胃钝不运之象。弦细并见，说明湿热久羁伤及脾胃气阴，肝木易乘，故宜泻心汤加减以调中清湿热，防其虚风内动。", ["弦", "细"]], "16754": ["病机", "脉濡主湿，左弦细为肝阴不足而木气偏亢。舌黄、便结、心泛，乃胃气不振、湿热未净、津液不布。濡与弦细并见，示湿阻中焦而肝胃不和，故宜养胃清利，最怕变端者，虑其湿浊上逆或化燥生风。", ["濡", "弦", "细"]], "16755": ["病机", "六脉虚细，为脾胃气阴两虚之征。虽大便稍下、湿热犹存，然饥不欲食、胃逆恶心，显系胃气已伤、受纳无权。虚细脉说明正虚为主，湿热余邪未清，故仍遵前法加减，扶正兼清余邪，则不致变端。", ["虚", "细"]], "16756": ["病机", "脉浮数主暑风在表，右关劲为热壅阳明、肝风内动之兆。头疼发热、肢战、脘闷气冲、咽阻，皆暑风夹痰热上扰之象。浮数而劲，说明表邪未解而里热已炽，最防热极生风，故宜防痉厥。", ["浮", "数", "劲"]], "16757": ["病机", "脉浮大主暑风夹湿、热邪外扬。舌滑白、汗多发热、渴饮，为暑湿郁蒸、气分热盛而湿未化。浮大之脉示邪在气卫，稚孩脏腑娇嫩，热盛易引动肝风，故恐变惊风，姑宜清热祛邪以解表里。", ["浮", "大"]], "16758": ["病机", "脉弦濡，弦主暑湿郁遏肝脾，濡主湿滞。右耳下肿、便泻腹痛、舌根微黄，为暑湿夹滞、少阳阳明同病。弦濡并见，说明湿阻气机而木土不和，故宜清暑和中，使湿化气畅则肿痛泻利自减。", ["弦", "濡"]], "16759": ["病机", "脉濡滑数，濡主湿，滑主痰，数主热。素患痰饮，新受暑气夹湿，潮热咳嗽气急，舌白根微黄，显系暑湿引动痰饮、痰热交阻于肺。濡滑数说明湿痰热邪壅盛，故宜清气消痰，使暑湿痰热分消。", ["濡", "滑", "数"]], "16760": ["病机", "脉濡数，濡主湿、数主热，正合暑风热湿交蒸之候。原文见呛咳、耳木、舌白根微黄，乃湿热郁于肺卫、蒙蔽清窍；神识乍愦则湿热有内陷厥阴之势，故断为症势重险，宜防厥闭。濡数并见，说明湿未化而热已炽，非单纯表证可比。", ["濡", "数"]], "16761": ["病机", "脉寸大，寸候上焦肺金，大则邪气壅盛。原文暑风夹湿、咳嗽吐血、潮热并见，是暑湿郁肺、热伤血络，肺气不降而咳，络损则血上溢。寸大提示上焦邪实，潮热示阴分渐伤，故有防瘵之虑，即防其久咳成劳。", ["大"]], "16762": ["病机", "脉寸滑数，滑主痰湿、数主热，寸部独盛说明暑热痰湿壅于上焦。原文伏暑呕渴发热、冲气撞脘、溲数，是湿热内阻、胃气上逆、气化失司之象；癸水趱迟则热灼阴分。故用泻心汤加减清上焦湿热，慎恐变端者，虑其热陷生闭。", ["滑", "数"]], "16763": ["病机", "脉濡细，濡为湿困、细为气阴不足，合原文伏暑秋发、始起寒热、潮热、头胀肢楚、大便不爽，是暑湿内蕴、气机不宣、湿滞经络之候。舌微白底红，示湿未化热而阴分已见不足。故姑宜清利，以宣湿清热、调畅气机为治。", ["濡", "细"]], "16764": ["病机", "脉弦细，弦主邪郁气滞、细主阴伤，合原文阳明伏暑、舌焦腻、脘闷呕恶、暮夜烦热，是暑湿郁阻阳明、胃气上逆、热灼阴津之象。舌焦腻示湿浊未化而津已伤，暮夜烦热为热入阴分。症属棘手，故防外脱内闭。", ["弦", "细"]], "16765": ["病机", "脉涩滞，涩主气滞血少、滞主运行不畅，合原文秋暑未清、气机不和、神识乍愦、溺后精关不固、腹痛，是暑湿余邪阻滞气机、升降失司、下元不固之候。舌微白示湿未化，神识乍愦为浊蒙清窍。仍遵前法加减，意在宣畅气机、清化余邪。", ["涩", "滞"]], "16766": ["病机", "脉弦濡，弦主湿郁经络、濡主湿盛，合原文湿著经络、寒热交作、舌黄滑、口渴、足跗冷彻骨中，是湿邪痹阻经络、阳气不能下达之候。足跗冷彻骨中为湿遏阳郁之明证，故用桂苓甘露饮宣阳化湿、通利经络。", ["弦", "濡"]], "16767": ["病机", "脉濡数，濡主湿、数主热，合原文寒热不清、舌滑白、咳嗽稍减，是湿热阻隔气分之候。咳嗽稍减示肺气渐宣，而寒热不清、舌滑白则湿邪仍恋。故治手太阴以宣肺化湿，佐淡渗使湿从下泄，湿热分消则寒热自解。", ["濡", "数"]], "16768": ["病机", "咳逆已除而脉弦，弦主气机郁滞、木旺克土。舌白根微黄、便溏溺赤涩，为湿热蕴结中焦，气机不畅则脉见弦象。弦脉在此非单纯寒证，乃湿热阻遏、肝脾不调之征，故断为湿热蕴结，与便溏溺涩相应。", ["弦"]], "16769": ["病机", "脉沉弱主里虚气陷，湿热伤气则阳气不振。寒热交作、肢冷呕逆、便利脘闷，皆湿热内蕴、气机升降失司之象；舌黄滑两边微白，湿遏热伏。沉弱脉说明正气已伤，故用桂苓甘露饮宣化，并防昏厥之变。", ["沉", "弱"]], "16770": ["病机", "脉弦濡，弦主气滞，濡主湿困。湿热寒热、中痞气滞、腹痛便滑，为湿阻中焦、肝脾气机不和。濡脉示湿邪偏盛，弦脉示气机郁滞，二者合见说明湿热互结、脾胃运化失职，故宜和中利湿。", ["弦", "濡"]], "16771": ["病机", "脉滞涩主气机不畅、湿阻血行。中焦未和、气冲脘闷，湿热蕴蓄日久，气机壅滞则脉道不利，故见滞涩。涩非血虚，乃湿浊阻滞、气行不畅之象，与脘闷气冲相应，治宜顺气和中以化湿滞。", ["涩"]], "16772": ["病机", "脉濡主湿邪未净，胃气稍振而湿犹留恋。舌滑嫩黄、腰坠，为湿浊下注、脾运未复。濡脉说明湿性黏滞、正气渐复而邪未尽除，故宜渗利以清余湿，使湿从小便而去。", ["濡"]], "16773": ["病机", "脉濡细，濡主湿，细主正虚。湿热未清而阴分已伤，舌薄滑、午后背寒乍热，为湿遏热伏、营卫不和。濡细并见说明湿邪留恋而气阴不足，故用桂苓甘露饮加减，化湿兼护正气。", ["濡", "细"]], "16774": ["病机", "脉细数，细主阴伤，数主热郁。舌微黄、背寒肢木、脘中窒痹，为湿邪内阻、阳气不达四末，郁而化热。细数脉示湿郁化热伤阴，非单纯虚证，故断属湿邪，宜温胆祛邪以宣通痹阻。", ["细", "数"]], "16775": ["病机", "脉濡细，濡主湿困，细主气阴不足。舌黄滑根厚、头晕肢楚、恶寒微热、溲数便结，为湿热内蕴、表里同病。濡细脉说明湿邪偏盛而正气已伤，故用甘露饮加减，清利湿热兼顾气阴。", ["濡", "细"]], "16776": ["病机", "脉弦为湿阻肺卫、气机郁滞之象。湿邪困表，肺失宣降，气机不畅故脉见弦；舌微黄、溲赤示湿郁化热，呃逆频频乃肺胃气逆。原文断为「症属重险」，正因湿阻肺卫而气逆势急，故治宜宣化肺气以解郁滞。", ["弦"]], "16777": ["病机", "脉濡细主湿邪内蕴、脾运不健。濡为湿象，细示正气不足，湿阻中焦则头胀肢懈、咳逆；舌滑微黄为湿热之征。原文明言「此属湿热」，脉濡细正合湿重于热、脾肺同病之机，故以保和丸加减化湿和中。", ["濡", "细"]], "16778": ["病机", "疟邪虽除而脉仍弦濡，弦主气机郁滞、濡主湿邪留恋，故原文断为「湿热犹存」。舌滑白、屡次衄血，示湿郁化热、热伤血络。脉弦濡与湿热未清、络脉不和相应，故宜清利湿热以善其后。", ["弦", "濡"]], "16779": ["病机", "脉弦濡为湿热内蕴、气机不畅之象。弦主郁滞，濡主湿邪，湿阻中焦则胃钝，湿热下注则跗肿溺赤；舌黄滑罩灰更证湿热胶结。原文「此属湿热」点明病机，故用越鞠丸法加减以解郁清利。", ["弦", "濡"]], "16780": ["病机", "脉涩滞主湿邪内著、气血运行不畅。湿热壅阻，气机痹滞故脘闷便结；湿郁化热则骨热，湿热下注则足肿冷；舌厚嫩黄为湿热之征。涩滞之脉正应「湿热内著」、气血不畅之机，故宜清利以通滞。", ["涩", "滞"]], "16781": ["病机", "脉弦濡示湿热蕴于经络、气机郁滞。弦主郁，濡主湿，湿热阻络则身潮热，下迫则便溏溺赤；舌黄罩灰为湿热之象。原文明言「湿热蕴于经络」，脉弦濡正合此机，故宜清热利湿，慎防变幻。", ["弦", "濡"]], "16782": ["病机", "脉涩滞主湿热未罢、气机痹阻。湿阻中焦则脘闷，湿热下注则足跗酸楚；舌厚微黄为湿热留恋之征。涩滞之脉说明湿邪壅遏、气血不畅，与「湿热未罢」相应，故宜和中清利以化湿通滞。", ["涩", "滞"]], "16783": ["病机", "脉涩滞主湿热壅盛、气血痹阻。湿热郁蒸发黄，湿泛肌肤则面跗浮，舌滑为湿象。原文断「症属重极」，正因湿热胶结、气机涩滞不通，脉涩滞与发黄、浮肿相应，故急宜清利湿热以图转机。", ["涩", "滞"]], "16784": ["病机", "脉濡主湿，左劲主络瘀，跌仆伤筋致环跳肿痹作痛，湿热内蕴则舌黄滑、作泻。濡劲并见，说明湿阻络瘀、气血壅闭，不通则痛，故以和络、清热、利湿为治。", ["濡", "劲"]], "16785": ["病机", "原文未出脉，介按明言跌仆伤筋而湿郁肿痹，气窒络瘀，壅闭不宣，不通而痛；湿胜便泄，故用宣通脉络、健脾渗湿、清热止泻之剂，米仁、木瓜为治湿热阻滞足筋酸痛之妙品。", []], "16786": ["病机", "脉濡细主湿郁中焦、气机不宣，故脘闷；湿热下注则溲溺赤；湿郁肌表则汗出津津；舌滑白亦为湿象。治宜和中清利，使湿化热清，气机调畅。", ["濡", "细"]], "16787": ["病机", "秋燥发热，脉浮数，浮为邪在表，数为热盛；咳嗽气急、舌微黄、渴不多饮，乃燥热犯肺、肺气上逆。症非轻貌，防昏变，故宜清燥透邪。", ["浮", "数"]], "16788": ["病机", "脉滑数主痰热内蕴，秋燥发热，呛咳痰阻，乃燥热灼津、痰热阻肺，肺失清肃。症非轻貌，姑宜清燥消痰，使痰热去而肺气宣。", ["滑", "数"]], "16789": ["病机", "脉右浮滑主燥热犯肺、痰湿内蕴，左微劲主木火偏亢；头晕而疼、咳逆发热、舌黄尖红，皆燥热上扰、肺失清肃之象。姑宜辛凉清解，透邪泄热。", ["浮", "滑", "劲"]], "16790": ["病机", "脉细右大，细为阴伤，右大主燥热内逼；童年咳嗽失血后，身热火胀，舌微黄，乃燥伤肺络、阴虚内热。宜防成损，故当清燥养阴。", ["细", "大"]], "16791": ["病机", "血后咳嗽较减，而脉两手皆弦，弦主肝郁、亦主燥气劲急；舌尖红、头晕，乃阴血亏虚、肝阳上扰、燥热未清。宜清燥以育阴，使阴复而弦脉自缓。", ["弦"]], "16792": ["病机", "原文述燥气挟肝经燥火，上蒸冲肺则咳呛失血，冲脑则头晕目眩，初诊脉细右大。细为阴血不足、燥火内灼，右大为燥热壅于气分，故先治气分而咳嗽较减；继则清肝肃肺、和胃止血，使肺复肃降之权，则咳晕自止，此脉示燥火伤及气分营络之病机。", ["细", "大"]], "16793": ["主病", "原文述遗风漏风温发热咳嗽，气急不耐，脉弦数，舌厚腻，症势非轻。弦为肝风内动、气机郁滞，数为温邪化热，舌厚腻则兼痰湿内蕴；风温之邪挟痰热壅肺，故咳逆气急而不耐，脉弦数正示风热痰浊交阻、有内陷生变之虞，故宜治防变。", ["弦", "数"]], "16794": ["病机", "原文述风温先伤肺分，肺气不舒，以致咳嗽气急，脉数舌腻。数为温邪化热之象，舌腻为痰湿未化，热壅肺气则咳急；故治法大忌辛温汗散，宜辛凉轻剂肃降肺气、清解表邪，姜半夏虽消痰止咳亦宜慎用，脉数示温邪在肺、热势偏盛之病机。", ["数"]], "16795": ["病机", "原文述温邪未净，脉尚大，午后肌热，舌白滑，呛咳面浮，大便溏薄。脉大示温邪留恋、正气尚与邪争，午后肌热为邪热未清，舌白滑、便溏、面浮则脾肺气分受伤、湿浊未化；呛咳为肺失清肃，故宜养胃、清肺熄邪，此脉示邪未尽而正渐伤之病机。", ["大"]], "16796": ["主病", "原文述温邪上郁，头目不爽，脉数，舌微黄，身热肢楚。数为温邪化热之征，温邪上郁清窍则头目不爽，郁于肌表则身热肢楚，舌微黄示热已渐入气分；脉数与身热肢楚相应，主温邪郁表、热势方张之病，故宜清解为主，使邪从表解。", ["数"]], "16797": ["主病", "原文述温邪发热，神识乍清乍愦，脉滑数，口燥，咳逆，便闭。滑为痰热内壅，数为温邪化热，痰热蒙蔽心包则神识乍清乍愦，热灼津伤则口燥便闭，痰热壅肺则咳逆；脉滑数正示痰热交炽、有内陷变端之险，故宜防变端。", ["滑", "数"]], "16798": ["病机", "原文述大便稍下，热犹不解，脉滑数，咳逆。便下而热不退，说明邪不在肠腑而在上焦气分；脉滑数为痰热仍壅于肺，故咳逆不止。滑主痰、数主热，痰热恋肺、清肃失司，此脉示上焦痰热未清之病机，故宜清上焦为主，则不致变端。", ["滑", "数"]], "16799": ["主病", "原文述妇人癸水色尚紫，正夹温邪，咳嗽尤甚，脉浮大，舌红，头疼身热。浮为邪在表分，大为邪热亢盛，舌红、头疼身热皆热象；温邪挟营热上扰，邪热已极营络，故咳嗽尤甚而经色紫；脉浮大与身热头疼相应，主温邪炽盛、涉营之病，宜清解消痰。", ["浮", "大"]], "16800": ["病机", "脉浮大主气分热炽。阴虚内热复感温邪，上犯于肺，致咳嗽身热头疼，脉浮大显为气分热盛之征。浮为邪在表，大为热盛，两热相并易入营分，故治在清肺止咳中兼顾营热。", ["浮", "大"]], "16801": ["预后", "脉促数主热盛邪陷，正虚邪实。温热言谵，疹点隐约，咳逆发热肢战，脉促数示热毒内炽，心营受扰，有痉厥之变。促为急促不匀，数为热，故症属棘手，宜防痉厥。", ["促", "数"]], "16802": ["病机", "脉涩滞主湿温杂受，中焦格拒，气机不畅。舌厚嫩黄，便溺不利，湿浊内阻，气机壅滞，故脉涩滞。藉小陷胸汤以开结泄热，防其变证。", ["涩", "滞"]], "16803": ["预后", "脉濡数主湿热内蕴。湿热温邪杂受，寒热交作，大便自利，舌心灰黄，脉濡数示湿阻热蒸，有昏蒙之变。濡为湿，数为热，湿热蒙蔽清窍，故宜防昏蒙。", ["濡", "数"]], "16804": ["预后", "脉数舌黄主热邪内盛。湿温杂受，烦热口燥，身发疹斑，神识乍清乍愦，脉数示热炽营分，清窍失聪，症属棘手，宜防厥闭之变。", ["数"]], "16805": ["病机", "脉濡数主湿热未清。血舍已清，泻痢较差，舌黄呛咳微热，胸前发斑白㾦，脉濡数示余湿未尽，热邪未彻，故宜清解为主。", ["濡", "数"]], "16806": ["病机", "脉濡细主湿邪未净，正气已伤。泻痢已瘥，身热亦退，脘腹胀闷，咳逆，脉濡细示湿阻气机，脾运未复，故宜治咳逆防变。", ["濡", "细"]], "16807": ["预后", "脉数气口滑主热邪未清，痰湿内蕴。血舍已清，呛咳头晕，身热未退，舌黄尖红，腰疼肢楚，脉数滑示热盛痰阻，还防变幻。", ["数", "滑"]], "16808": ["病机", "脉数右劲，数主热盛，右劲为气分邪实之象，与舌心黄厚、咳逆吸短、右胁刺痛相合，示冬温邪热内蕴肺胃，热势鸱张，有内陷厥阴、闭阻心包之虞，故神识乍愦，症势重险，宜防厥闭。", ["数", "劲"]], "16809": ["病机", "脉滑数，滑主痰湿，数主热，痰热互结于肺，故右胁犹痛、吸粗、咳逆痰阻；舌黄、神色乍愦，为痰热蒙扰心神之兆，还防变幻，即防痰热内闭心包。", ["滑", "数"]], "16810": ["病机", "脉弦寸口芤，弦主肝郁，芤主阴血不足，寸口见芤尤关肺阴亏虚；呛咳咽痛、舌白尖赤，为阴虚肺燥、虚火上炎之候，故症属阴虚，宜防喉燥，即防燥热伤肺、咽喉干痛加剧。", ["弦", "芤"]], "16811": ["病机", "脉弦右寸大，弦为肝郁，右寸大主肺热壅盛；咽痛稍瘥而舌黄红、呛咳、寒热不清，示肺中郁热未清，肝火仍旺，阴分受灼，故宜防喉燥，即防燥热复炽、咽喉干痛再作。", ["弦", "大"]], "16812": ["病机", "脉濡数，濡主湿，数主热，湿热内蕴，故自利未除、舌滑根焦；咳逆稍减而形光尚润，示湿热未化、气阴渐伤，最怕变幻，即防湿热蒙窍或阴伤风动之变。", ["濡", "数"]], "16813": ["病机", "脉浮弦，浮主风邪在表，弦主肝木气郁；风热上扰，故目涩头疼、呛咳；胃馁、便结、舌微黄，示风热未解而胃气已伤，故宜清疏为妥，即清透风热、疏肝和胃。", ["浮", "弦"]], "16814": ["病机", "脉弦濡，弦为肝郁未舒，濡为湿滞中焦；风热未净而头疼已减，目涩胃馁，示表邪渐退而肝胃不和、湿阻气机，故仍遵前法清疏，以疏肝和胃、化湿清热。", ["弦", "濡"]], "16815": ["病机", "脉虚细，虚为气不足，细为阴血亏少；胃气尚馁，故脉虚细，舌微黄、夜寐少安，示胃虚失养、心神不宁，故宜养胃凝神，即补益胃气、安和心神。", ["虚", "细"]], "16816": ["病机", "脉细数，细为阴伤血少，数为热郁于内。原文“温邪上郁，齿浮口臭，牙缝出血”，乃温邪化热，迫血上溢于龈，兼肢木者，热灼阴血、脉络失养。细数之脉正示阴虚热郁，故宜防牙疳，防其热毒腐龈成疳。", ["细", "数"]], "16817": ["病机", "本段未出脉象，专论牙疳病机。原文“胃脉络于上龈，大肠脉络于下龈”，邪热入胃，逼动肝阳，血溢上结于龈，转成牙疳。指出牙疳由胃热肝阳相激、血热上壅所致，故以清肝凉胃为治，非泛论脉候。", []], "16818": ["病机", "脉弦细，弦为肝木偏旺、气机不舒，细为阴分不足。原文“咳呛不已，口甜，舌色嫩黄”，口甜属脾胃湿热，舌嫩黄为热象，咳呛乃肺失清肃。弦细示肝旺乘肺、肺胃蕴热，故宜清肺胃以化痰，使木火不刑金。", ["弦", "细"]], "16819": ["病机", "脉弦主气机郁滞、肝木不疏。原文“咳痰不爽，舌微白，脐下气机不运”，脐下属下焦，气机不运则痰湿内停，上逆犯肺而咳痰不爽。弦脉正应气郁痰阻之机，故以清气消痰为主，兼运下焦气机。", ["弦"]], "16820": ["预后", "脉细数，细为阴血亏虚，数为虚热内扰。原文“舌白滑，咳嗽痰迷，咯不易出，气逆，周身骨骱痛”，痰浊内阻而阴分已伤，骨骱痛为久咳损及肝肾、筋骨失养。细数之脉示正虚邪恋，故“宜防损”，虑其成虚损之候。", ["细", "数"]], "16821": ["病机", "脉濡细，濡主湿，细主阴血不足。原文“咳不减，喉中贮痰不爽，咳不易出，舌滑，头晕肢楚”，湿痰内蕴，肺气不降则咳痰难出；湿阻清阳则头晕，湿留经络则肢楚。濡细正合湿痰兼阴伤之机，故宜清气熄风、利湿化痰。", ["濡", "细"]], "16822": ["病机", "脉濡细，濡为湿象，细为湿郁血分不畅。原文“湿热酿痰，舌微白，咳逆，右胁刺痛，溲溺赤，腹痛”，湿热酿痰阻肺则咳逆，阻络则右胁刺痛，下注则溲赤腹痛。濡细示湿痰内蕴、络气不和，故宜清气、和络、化痰。", ["濡", "细"]], "16823": ["病机", "脉弦细，弦为肝木偏亢，细为阴分不足。原文“呛咳喉痒，舌转微白，潮热较差，食入恶心”，呛咳喉痒属肺失清润、木火刑金；潮热减而食入恶心，乃胃气不和、肝胃同病。弦细示肝旺阴伤、肺胃失调，故宜清肺胃化痰。", ["弦", "细"]], "16824": ["病机", "脉弦细数，弦为肝郁，细为阴伤，数为热盛。潮热不清、溲溺赤，是热郁于内；咳嗽如前，为肺受热灼。细数并见，阴分已伤而热未退，故宜清热通肺化痰，并防血溢，因热伤肺络则血上溢。", ["弦", "细", "数"]], "16825": ["病机", "脉尚虚数，虚为气阴不足，数为余热未清。咳嗽不已而胃纳已和，说明胃气渐复而肺中余热未净，虚数之脉正是肺阴亏虚、虚热内扰之象，故宜润肺以清降，不可苦寒伤正。", ["虚", "数"]], "16826": ["病机", "脉小数，小为阴血不足，数为余热内蕴。咳嗽未除、仍属汗出，微热已退，是热势虽减而肺阴未复，虚热迫津外泄故汗出。脉小数为阴虚内热之征，故宜清肺敛液以固其津。", ["小", "数"]], "16827": ["病机", "脉滑数，滑主痰湿，数主热。酒湿伤肺，湿聚成痰，痰热壅肺，故咳嗽气急、痰稠；舌赤苔薄腻亦痰热之象。滑数之脉正合痰热内盛，故防变幻，须清化痰热以宣肺气。", ["滑", "数"]], "16828": ["病机", "脉滑数，滑为痰，数为热。呕减热缓而呛咳渴饮，是痰热恋肺、肺失清肃；经停月余、小溲稍利、偶有呃逆脘痛，为痰热中阻、气机不降。滑数之脉主痰热内蕴，故宜宣肺和中化痰。", ["滑", "数"]], "16829": ["病机", "脉小滑，小为阴分不足，滑为痰湿未净。呕逆已瘥而呛咳脘闷、气冲欲呕，是肺胃痰浊未清、气逆不降。脉小滑说明痰热渐减而阴分已伤，故宜清养肺胃化痰，不可过用温燥。", ["小", "滑"]], "16830": ["病机", "脉滑数，滑主痰，数主热。呛咳未除、舌红潮热，是痰热恋肺、阴分受伤；经停、胸闷心惕，为痰热内扰、心神不宁。滑数之脉示痰热仍盛，故宜清养肺胃为主，兼顾阴分。", ["滑", "数"]], "16831": ["病机", "右脉小数，小为阴伤，数为内热；左关弦细，弦为肝郁，细为血少。气喘呛咳、舌灰黄底红、癸水不调，是外寒束表、内热郁肺，肝血不足而气机不畅；胃钝便闭为热结。故宜防血溢，因热伤肺络可致出血。", ["小", "数", "弦", "细"]], "16832": ["兼症", "脉虚为气血不足，左弦细主肝肾阴虚、肝气不柔。腰疼乃肾虚失养，癸涩早期为血虚有热、冲任失调。咳嗽较减而脉仍虚，示肺气虽略清肃而本元未复，故宜前法加减，兼顾补虚调经。", ["虚", "弦", "细"]], "16833": ["病机", "经水趱早为血热之征，脉虚腰疼为肾虚之候。咳嗽略减是肺气略见清肃，脉虚而细是胃液尚未恢复。虚细并见，示气阴两伤，肺胃津亏而肾亦不足，故治法清养肺胃兼滋液补肾。", ["虚", "细"]], "16834": ["病机", "左脉弦细为肝阴不足、风阳内动，气口搏大主肺胃气壅。呛咳头晕乃风阳上扰、肺失清肃，形寒钝胃为胃气不和，经停二月余属血虚气滞。脉症合参，病机在肺胃不清、肝风内动，故宜清肺胃熄风。", ["弦", "细", "大"]], "16835": ["病机", "原文未出脉名，以冲脉为病立论。冲气上逆犯胃则呕吐涎沫，冲肺则咳呛不止；冲脉即血海隶于阳明，腹瘕呕恶乃冲气挟肝胃之逆。细揣病情，治宜镇冲养胃，清肺平肝为佐，此即冲脉气逆、胃失和降之病机。", []], "16836": ["病机", "大便已通、胃气稍振，而脉虚细、舌滑白，示脾胃气阴未复、运化无力。虚细为气血不足之象，舌滑白主湿浊未净。胃气虽稍振而本虚未复，故宜养胃凝心神，以缓图恢复。", ["虚", "细"]], "16837": ["主病", "脉弦主肝气郁结、气机不畅，故肝气作痛。经闭为气滞血瘀、冲任不通，咳痰带红乃肝火犯肺、灼伤肺络。弦脉与肝气痛、经闭、咳红相应，损怯已成，示病深及肺肾，非轻藐之症。", ["弦"]], "16838": ["病机", "脉弦数为肝阳亢盛、火热内炽。肝阳烁肺则咳痰带红，舌色透明为阴伤，便血乃热伤血络。弦数之脉与肝阳化火、灼肺动血相应，防其成损，故宜清肺化痰、平肝凉血。", ["弦", "数"]], "16839": ["病机", "脉弦劲为肝阳亢逆、风火内动之象，较弦数更显劲急。痰红较差而呛咳不已，示肺络未清、肝火仍灼；咽痛已减是上焦热势稍退。弦劲脉与呛咳并见，主肝肺郁热未平，故宜清肺化痰以平其亢。", ["弦", "劲"]], "16840": ["病机", "脉劲数，劲为肝阳亢逆之象，数为热盛，合之咳嗽带红，显系肝阳上升、木火刑金，灼伤肺络而咳血。原文直指“肝阳上升”，故治宜清降为主，以平肝降逆、清肺止血。", ["劲", "数"]], "16841": ["病机", "脉弦数，弦主肝胆，数主热，舌微黄亦热象，寒热交作乃少阳枢机不利。原文断为“木火刑肺”，肝火循经犯肺，咳血气促。治宜清少阳为主，以解枢机、清肝火。", ["弦", "数"]], "16842": ["病机", "血已除而脉数、舌黄，咳嗽气促不已，数脉主热，舌黄为热象，知肝火犹炽未清，火热上逆迫肺故气促。原文谓“肝火犹炽”，治宜清降为妥，以清肝降火、肃肺止咳。", ["数"]], "16843": ["病机", "原文无脉名，以“阳明脉络日衰则发冷，阴亏而阳不潜藏则发热”论病机，总由肝阳横逆、血上溢。初方柔肝肃肺、降气凉血获效，次方清降中参养胃，示肝阳上逆、阴亏阳浮之机。", []], "16844": ["病机", "脉数主热，右关弦主肝木乘土，胸闷、舌微黄皆痰热内蕴之象。咳血未除，乃肝火灼肺、痰热阻络所致。原文宜“清降消痰”，正合清肝降火、化痰止咳之法。", ["数", "弦"]], "16845": ["病机", "脉弦细，弦为肝郁气逆，细为阴血不足，舌微黄为郁热。遭忿动肝，气冲咳血，乃肝气上逆、灼伤肺络。原文“气冲咳血”点明病机，治宜清降消痰，兼平肝降逆。", ["弦", "细"]], "16846": ["病机", "脉细数，细主阴亏，数主内热，阴虚内热则便结、精关不固；咳痰带红乃虚火灼肺、络伤血溢。原文“阴虚内热”为病机核心，治宜存阴为主，以滋阴降火、固精止血。", ["细", "数"]], "16847": ["病机", "脉弦主肝阳偏亢，肝阳上灼肺金则咳嗽带红；迎风头疼、耳鸣作痛、舌心光，皆肝阳化风、上扰清窍之象。原文“肝阳烁肺”点明病机，治宜清少阳为主，以平肝潜阳、清肺止咳。", ["弦"]], "16848": ["病机", "痰血已除而脉虚数，虚为气阴耗伤，数为余热未清；咳嗽不已、气逆，是肺失清肃、虚热上逆之象。脉虚数正合痰血后阴伤热恋之机，故主清降，以复肺气下行。", ["虚", "数"]], "16849": ["病机", "脉滑数为痰热内盛之征，舌黄燥底赤更示阴火上升、津伤热炽；咳嗽气喘、著枕不耐，乃痰火壅肺、气逆不能平卧。滑主痰，数主热，故防变幻，候正以清降痰火。", ["滑", "数"]], "16850": ["病机", "脉弦细，弦为肝郁气逆，细为营血不足；脘痹气冲、得嗳稍舒，是气机郁滞；腹中有瘕、咳逆，乃肝气挟痰上逆犯肺。弦细合瘕咳，主肝郁络痹、肺气不降，故用栝蒌薤白汤通阳宣痹。", ["弦", "细"]], "16851": ["病机", "右脉涩主肺气不宣、痰阻胸脘，左沉弦为肝郁不舒；舌厚腻示痰湿内蕴。胸脘窒痹乃肺气痹阻、痰湿交阻之候，涩脉正应气机不畅，故仍遵前法加减以宣肺化痰。", ["涩", "沉", "弦"]], "16852": ["病机", "脉濡细数为湿痰内蕴、郁而化热之象，濡主湿，细主阴伤，数主热；呛咳痰阻、胸冷窒痹，是痰湿阻遏胸阳、肺失清肃；舌微黄亦示郁热。故宜清气化痰，使湿去热清而肺气宣畅。", ["濡", "细", "数"]], "16853": ["病机", "血后脉弦，弦为肝气偏旺；咳痰不爽、脘闷，是肝逆上冲、肺气窒痹，木火刑金之候。血后阴伤而肝失柔养，气逆不降，故仍遵前法柔肝肃肺、降逆化痰为妥。", ["弦"]], "16854": ["病机", "脉浮滑，浮主肺气上逆，滑主痰浊内盛；肺痹气逆、呛咳稠痰，正是痰浊壅肺、气失宣降之象；耳木乃痰阻清阳、少阳经气不利。浮滑合稠痰，故宜清降消痰为治。", ["浮", "滑"]], "16855": ["病机", "原文未识脉名，介按以肝性上升、胆脉贯耳立论，谓厥阳与少阳挟稠痰上腾，阻遏清阳；苦降辛通、柔肝肃肺，正针对痰火挟肝胆之气上逆之机，故属病机阐发而非脉象主病。", []], "16856": ["病机", "脉小数见于呛咳、形寒盗汗、失血之后，数主虚热内扰，小主气阴耗损。肺气受戕，宣降失职则呛咳；卫外不固则形寒；虚热迫津则盗汗；曾失血更伤阴络。脉小数为虚劳内热之征，故断为非轻藐之症。", ["小", "数"]], "16857": ["预后", "脉仍属小数，说明虚热未退、气阴难复。咳痰脓厚带红，为肺络损伤、热灼津液成痰之象；形寒属肺气虚馁、卫外不固。脉证相参，肺气受戕日深，故列为虚劳重症，预后堪忧。", ["小", "数"]], "16858": ["病机", "暑湿伤气，咳嗽潮热，清窍已蒙，右脉小数主肺胃虚热，左劲为肝阳偏亢。舌光红中有白屑，津液重伤之明证。虚热内灼、肝阳上扰，已成虚劳，故势在棘手，宜清降养胃消痰以顾护津液。", ["小", "数", "劲"]], "16859": ["病机", "劳嗽潮热而脉涩，涩主血少脉道不利；左细数为阴血亏虚、虚热内生。经阻形怯，乃阴血不足、冲任失养所致。舌白中心红，亦示虚热。脉涩与经阻相应，说明血虚劳损，非轻藐之症。", ["涩", "细", "数"]], "16860": ["病机", "脉虚细为气阴两虚，右弦主土虚木乘。咳嗽未除、形怯潮热，肺脾两伤；脘闷便泻，脾运失职、肝木犯土。舌微黄示兼有郁热。虚细中见右弦，正虚而邪扰，究属重险之症，宜清气和中。", ["虚", "细", "弦"]], "16861": ["病机", "六脉虚细，为气血阴阳俱不足之象。盗汗未除，卫气不固、阴津外泄；咳嗽气促，肺气虚逆；脘痛，中焦失养。舌白少津，津液已伤。虚细脉示正气亏虚，气不摄血，故宜防血溢。", ["虚", "细"]], "16862": ["预后", "咳嗽已减、盗汗较差，病情向愈。脉左虚细，右较缓，左候阴血仍亏，右缓为胃气渐复之象。舌滑白示痰湿未净。虚细中右脉转缓，说明正气渐回，仍遵前法加减损益以巩固疗效。", ["虚", "细", "缓"]], "16863": ["预后", "前药已效，咳嗽盗汗悉减，而脉仍虚细，舌滑白，力怯，腰跗不健。虚细为气血未复，腰跗不健属肾气不足、下元亏虚。症减而脉未复，说明邪退正虚，还宜前法损益，缓培气血以善其后。", ["虚", "细"]], "16864": ["病机", "脉数右劲，数主热，右劲为阳亢不潜，阳不交阴故寤不成寐；舌尖赤、咳嗽气逆乃肺热上炎，胃馁则中气不足。脉症合参，病机为阳浮不敛、肺胃失和，故治以清肺安神化痰。", ["数", "劲"]], "16865": ["病机", "脉右尚弦，弦为肝阳未静之象；左细数，细属阴亏，数主虚热。肝阳不潜则夜寐少安，呛咳亦由阳升气逆。脉弦细数并见，示肝肾阴亏、阳失潜藏，故宜柔肝肾以和阳。", ["弦", "细", "数"]], "16866": ["病机", "脉虚细，虚为气弱，细为阴血不足，心气失养则心悸、夜不安寐；肺虚气逆则呛咳；胃钝恶心乃中虚失运。脉症相合，病机属心肺气虚、胃失和降，故以温胆和胃、清肺安神为治。", ["虚", "细"]], "16867": ["病机", "脉虚细为心阴心气不足，左关细劲则肝阳偏亢。心惕如悬、夜寐不安、舌红、偶然语蹙，皆心虚阳扰之候。脉虚细而关部劲，示心肝阴亏、阳不潜藏，故用补心丹加减养心安神。", ["虚", "细", "劲"]], "16868": ["病机", "脉劲为肝阳亢盛、筋脉失柔之象，晕眩并作、心悸少寐皆阳升扰神所致；舌色透明、力怯跗肿则兼气虚湿滞。脉劲与晕眩并见，主肝肾阴亏、阳亢风动，故宜柔肝肾以安神。", ["劲"]], "16869": ["病机", "脉虚为正气不足，晕眩已减、夜寐稍安示前法见效，而睡中汗出、力怯仍属气虚不固、阴液外泄。脉虚与汗出、力怯相应，病机为气阴两虚、卫外不固，故仍遵前法加减调治。", ["虚"]], "16870": ["病机", "脉濡细，濡主湿，细主虚，舌黄滑更证湿浊未罢；湿困中焦则胃气仍钝，湿扰心神则夜不安寐。脉濡细与舌黄滑并见，示湿浊内蕴、胃失和降，故以温胆汤加减化湿和胃安神。", ["濡", "细"]], "16871": ["病机", "脉右弦濡，弦为肝旺，濡主湿滞；左虚细为阴血不足。湿热较减、胃纳略增示湿渐化，而夜寐少安、大便艰涩乃阴亏肠燥、神失所养。脉弦濡与虚细并见，示湿余阴亏、肝胃不和，故宜和胃安神。", ["弦", "濡", "虚", "细"]], "16872": ["病机", "脉濡数，舌黄滑，为湿火未清之象。濡主湿，数主热，湿火交蒸，故脉濡数；舌黄滑亦湿火之征。遗风徐血后阴耗，阴血亏虚，湿火乘虚内扰，致心悸健忘。此脉象说明湿火未清、阴血已耗之病机，主湿火扰心之证，与心悸健忘相应。", ["濡", "数"]], "16873": ["病机", "左脉虚细，右劲，舌滑白，心虚悸惕。左脉候心，虚细为心阴心血不足；右劲为肝阳偏亢。咳嗽盗汗悉瘥后，阴血未复，心失所养，故心悸惕惕。此脉象说明心虚阴亏、肝阳未潜之病机，主心虚悸惕之证，与舌滑白、心悸相应。", ["虚", "细", "劲"]], "16874": ["病机", "脉弦，脘痛气冲，语蹙心悸，为肝逆乘中之候。弦为肝脉，肝气横逆，乘犯中土，故脘痛气冲；肝逆上扰，心神不宁，故语蹙心悸。此脉象说明肝气逆乱、乘中扰心之病机，主肝逆脘痛之证，与气冲、语蹙、心悸相应。", ["弦"]], "16875": ["病机", "脉弦细，舌白，冲气未平，心无所主，语蹙。弦为肝逆，细为阴血不足；肝逆未平，冲气上逆，心神失守，故心无所主而语蹙。此脉象说明肝逆未平、阴血不足、心神不宁之病机，主冲气上逆之证，与语蹙、心无所主相应。", ["弦", "细"]], "16876": ["病机", "脉细劲，音低，心悸，寝寐恍惚，舌心微黄。细为阴血亏虚，劲为木旺阳亢；水亏木旺，肝阳上扰，心神不宁，故心悸、寝寐恍惚；肾液不能上承，故音低。此脉象说明水亏木旺、心神不宁之病机，主阴虚阳亢之证，与音低心悸相应。", ["细", "劲"]], "16877": ["病机", "原文未识脉名，介按以少阴之脉循喉咙、挟舌本为据，指出肾液未能上承，致音低心悸。此段从经络病机立论，说明少阴肾液亏虚、不能上承之病机，主心肾不交之证，与音低心悸相应。方宗阿胶鸡子黄汤加减，使心肾交合，则诸恙自除。", []], "16878": ["病机", "右脉寸关虚细，左弦，舌心红，呛咳久累不已，癸水始淡继紫。右寸关候肺脾，虚细为气阴不足；左弦为肝风偏亢。肝风烁肺，肺失清润，故呛咳久累；癸水异常亦肝风扰动之征。此脉象说明肝风烁肺、气阴两虚之病机，主肝风犯肺之证，与呛咳相应。", ["虚", "细", "弦"]], "16879": ["病机", "脉左涩右弦，舌心光，头晕音哑，癸水先后不一。左涩为阴血不足、血行不畅；右弦为肝风偏亢。肝风烁肺，肺失清润，故音哑；风阳上扰，故头晕；癸水不一亦肝风扰动冲任之征。此脉象说明肝风烁肺、阴血不足之病机，主肝风犯肺之证，与头晕音哑相应。", ["涩", "弦"]], "16880": ["病机", "脉涩细为冲任内怯、血少气滞之象，涩主血行不畅，细主阴血不足，故带下癸涩、腰酸腹痛；右细数乃肝风浮越化热，上扰清窍则头疼牙痛。脉症合参，病本在冲任虚损、肝风内动，故以柔肝熄风为主。", ["涩", "细", "数"]], "16881": ["病机", "带下未除、腹中疼痛而脉涩数，涩为血滞湿阻，数为郁热内蒸，示湿热未清、气血不畅；头疼牙痛悉瘥，说明肝风浮越之势已减，而冲任湿滞未解，故治法转为柔肝、调经、涩下，兼顾标本。", ["涩", "数"]], "16882": ["病机", "脉弦为肝风内震之象，右虚示中气不足、心神失养，故见心惕、头晕、肢战；肝风扰及冲任，则癸来夹杂腰疼。弦而兼虚，说明风动因于虚，非实火亢盛，故治宜柔肝熄风，仍镇摄心神以安其虚。", ["弦", "虚"]], "16883": ["病机", "脉濡主湿，兼示气血不足，湿浊内蕴则大便稍润、舌根微黄；内风浮越，循经上扰，故头角筋惕作痛。濡脉不弦不数，说明风动与湿滞相兼而热势不显，故治以清肝熄风、渗利湿浊，使风湿并解。", ["濡"]], "16884": ["病机", "脉濡为湿盛之征，本案血虚气滞，湿热盘踞，肝逆犯胃，故每癸来心泛、腹满带下。濡脉示湿浊内阻、气机不利，血虚则脉道不充，湿热与气滞相搏，故治宜和肝调经，兼化湿热，使肝气和而经候调。", ["濡"]], "16885": ["病机", "此段未出脉象，纯以证候立论。带脉不固则腰溶溶如坐水中，湿热盘踞更伤带脉，厥阴逆乘犯胃则心泛。病机关键在带脉失约、湿热内蕴、肝胃不和，故治以和肝除湿为首要，与前案脉濡之湿热盘踞相互印证。", []], "16886": ["病机", "脉右细滞，细主不足、滞主气机不畅，示中焦湿滞；左弦为肝气偏旺。肝逆犯胃，胃失和降，故脘格呕恶。舌色还和说明热象未深，故以苦辛通降为妥，辛开苦降以调肝胃、畅气机。", ["细", "滞", "弦"]], "16887": ["病机", "呕恶已除而脉弦细，弦为肝气未和，细为湿滞血少；舌微白、著根淡黄，示湿热未净、气机不利。脉症合参，肝胃渐和而湿热余邪未清，故宜和中利湿，使气机通畅、湿浊分消，以防余邪复聚。", ["弦", "细"]], "16888": ["兼症", "脉弱细，弱主气虚，细主血少，合而示胃气馁弱、气血不足。原文“便泻未除”伤脾，“呕恶已瘥”而胃气未复，“脘闷少寐”乃胃不和则卧不安。脉弱细正合胃馁失运、肝血不足之机，故治宜养胃、和肝、凝神。", ["弱", "细"]], "16889": ["病机", "脉沉弦，沉主里，弦主肝。带下未除而呕恶、舌微黄，是肝气内郁、横逆犯胃，胃失和降则呕恶，肝郁化热则舌黄。原文断为“肝胃不和，癸水不调”，脉沉弦正应肝郁于里、胃气上逆之病机，故宜防隔症。", ["沉", "弦"]], "16890": ["病机", "左脉沉弦，右脉弦滑。沉弦为肝郁气逆，弦滑为胃有痰饮。隔气作吐、经停五月、舌根厚，是肝逆犯胃、痰气交阻，胃失和降。原文谓“肝逆犯胃，宜厥阴阳明同治”，脉象正合肝郁胃逆、痰阻气机之病机。", ["沉", "弦", "滑"]], "16891": ["兼症", "两手脉弦滑，弦主肝郁，滑主痰饮。隔气较差、脘中稍和，是肝逆犯胃之势稍缓，然脉仍弦滑，示痰气未净、肝胃未和。经停五月、舌根微黄，仍属肝郁胃逆、痰热内阻之象，故遵前法加减。", ["弦", "滑"]], "16892": ["其他", "脉滑而经停五月，兼呕吐，滑为血盛之脉，经停而脉滑，似妊娠之象。原文虽断肝胃不和，然“未曾叙明孕育”，故存疑。脉滑在此提示气血充盛，与肝郁气逆之呕吐并见，当辨妊娠与隔症，不可径用通经活血。", ["滑"]], "16893": ["病机", "脉弦紧，弦主肝逆，紧主气机收引。食入脘中窒格，是肝气乘中、脾气失运，气结不舒。舌滑白示中焦湿滞。原文谓“肝逆乘中，脾气失运”，脉弦紧正合肝郁气结、脾运受困之病机，故宜和中疏肝。", ["弦", "紧"]], "16894": ["预后", "脉弦濡，弦为肝郁气逆，濡为湿滞中焦。脘痛窒格、呕恶、汤水难入，是肝胃气逆、湿浊阻隔；食后潮热、便闭，示郁热内结。原文断“症属重险”，脉弦濡正应气郁湿阻、通降失司之重候，故宜苦辛通降。", ["弦", "濡"]], "16895": ["病机", "脉沉弦，沉主里，弦主肝。血虚气冲、腰腹痛、带下、背板，是血虚而肝气上逆、带脉不固；脘中偶痛，肝胃不和。原文谓“养血、和胃、平肝”，脉沉弦正合血虚肝郁、气逆于里之病机。", ["沉", "弦"]], "16896": ["兼症", "脉细主气血不足，带下未除而舌厚黄、腹痛恶心，示湿浊内蕴兼阴血亏虚。细脉为血少脉道不充，湿浊阻滞气机则腹痛恶心，舌厚黄为湿热之征，故仍遵前法加减，兼顾养血化湿。", ["细"]], "16897": ["病机", "原文未出脉象，介按明言肾虚带脉失固则背板腰痛带下，肝阳逆行阻气则脘腹作痛，总因血虚肝滞。病机在肾虚不固、肝郁气滞，故治以和胃平肝、补肾养血，腹痛恶心参理气之品。", []], "16898": ["病机", "脉弦主肝郁气滞，脘痛窒极、口涌清水欲呕、肢乍冷，为肝气横逆犯胃、厥阴寒气上冲。舌白中心微黄示寒湿夹郁热，故宜厥阴阳明同治，疏肝和胃。", ["弦"]], "16899": ["病机", "脉弦为肝横之象，脘痛未除而呕恶已瘥，舌厚嫩黄，示肝气仍郁、湿浊未化。弦脉主痛主肝，肝失疏泄则脘痛，故宜疏泄厥阴为治，使肝气条达。", ["弦"]], "16900": ["病机", "脉弦主肝木未和，脘痛较减而嗳气上逆，为肝气犯胃、胃失和降。弦脉应肝，肝郁气逆则嗳气，故宜镇逆和胃，平肝降逆以复胃气和降之职。", ["弦"]], "16901": ["预后", "脉弦细主肝郁血虚，脘腹联痛有瘕、便溺涩，为气滞血瘀、癥瘕内结。弦为肝郁，细为血少，症属重险，宜治防厥，示肝郁血瘀日久恐致昏厥，故先事预防。", ["弦", "细"]], "16902": ["预后", "脉弦细示肝郁血虚未复，脘痛未除、大便已通而舌腻，呕逆，肝胃不和。弦细为肝横血少，仍宜防厥，故以和肝胃为主，兼顾厥逆之变。", ["弦", "细"]], "16903": ["病机", "脉弦主肝横，嗜酒湿胜，脘腹痛，为酒湿内蕴、肝气横逆。弦脉应肝，湿胜则气机不利，肝横犯胃则脘腹痛，故宜解酒、分消利气，化湿疏肝。", ["弦"]], "16904": ["病机", "脉弦细，弦为肝郁气滞，细主湿邪内蕴、气血不充。脘腹联痛虽减而腰胯坠，是湿热未清、下注腰胯，气机不畅。弦细并见，说明肝郁与湿热并存，故曰\"湿热犹存\"，仍守前法加减，以清化湿热、疏调气机为治。", ["弦", "细"]], "16905": ["病机", "脉濡细，濡主湿、细主虚，是湿邪困阻而脾胃气血不足之象。腹痛已缓而腰胯犹坠、背掣，为湿浊下注、经络不利；口甜乃脾湿上泛之征。故以和肝胃为主，调畅中焦以化湿浊。", ["濡", "细"]], "16906": ["病机", "脉弦主肝郁气滞、木旺克土。脘痛较减而脉仍弦，舌黄根厚，是里有湿热积滞未化；寒热交作，为湿热郁阻、少阳枢机不利。弦脉示肝气未舒，故仍遵前法加减，疏肝兼清湿热。", ["弦"]], "16907": ["病机", "脉弦为肝郁不舒，舌根黄厚、溲溺赤乃湿热内蕴之征。脘痛已瘥而大便不快，是肝气犯胃、胃失下行，湿热阻滞肠道传导。故治以启膈通阳、和中疏肝，使气机畅达而湿热得化。", ["弦"]], "16908": ["病机", "此按语明言湿热阻遏清阳、肝阳上逆、胃不下行，致大肠失传导、小肠失变化而二便不爽。脉象仍弦，说明肝阳上逆之势未平，弦为肝旺之应，故治以泄肝和胃、启膈通阳，使清阳得升、浊阴得降。", ["弦"]], "16909": ["病机", "两手皆弦，为水亏木旺、肝阳偏亢之象。食入脘格是肝气犯胃、胃失和降；脐下胀闷为肝郁气滞；暮夜手足心热乃阴虚内热。弦脉应肝，木旺则克土，故宜养胃和中、清肝以平木亢。", ["弦"]], "16910": ["病机", "脉弦主肝气横逆，原文直言\"肝横\"。腹痛联脘、嗳气上逆，是肝木乘土、胃气上逆之候。弦脉为肝郁气滞之应，气机横逆则脘腹作痛、嗳气频作，故治宜疏肝和中，使肝气条达、胃气和降。", ["弦"]], "16911": ["病机", "脉虚主营气不足、气血亏虚。营虚则胃络失养而作痛，心失所养故心悸。虚脉为正气不足之征，与营虚胃痛、心悸相应。治以辛甘，辛能行气、甘能补中，温养营气而缓胃痛。", ["虚"]], "16912": ["病机", "胃痛未除而脉虚，示中气不足；左弦为肝木偏旺之象。虚弦并见，乃土虚木乘、肝血不足而肝阳上扰，故心悸如悬。原文以「养血平肝」为治，正合虚弦所主之肝血亏虚、肝气横逆病机，非单纯胃实之痛。", ["虚", "弦"]], "16913": ["病机", "脉弦主气滞，濡主湿盛。沈秋暑湿内逼，湿滞气阻则腹痛如绞、大便赤不爽；弦濡并见，示暑湿夹滞、肝脾气机壅遏。舌赤、呕恶为湿热上蒸。原文「防痢」即虑湿热积滞下迫肠腑，脉弦濡正是湿滞气阻之征。", ["弦", "濡"]], "16914": ["病机", "腹痛已除、胃气较振，而两手皆弦，知病本未净。弦为肝脉，两手皆弦示肝气横逆、气滞不舒，阴火不得敛藏。原文明言「肝横气滞，阴火不敛」，故虽痛止仍宜养胃泄肝，弦脉所主在肝郁气滞而非胃实。", ["弦"]], "16915": ["病机", "寸脉弦滑，弦主气滞，滑主痰食。闺女腹痛欲呕、咳逆，原文断为「寒温失调，夹食为患」，食滞中焦、气机不利则腹痛呕恶，上逆犯肺则咳。寸部候上焦，弦滑见于寸，示食痰壅遏上中二焦，故宜开提和中以防变。", ["弦", "滑"]], "16916": ["病机", "便泻已止而脉弦，腹痛肠鸣仍在，知泻虽止而肝木未平。弦为肝旺，肝气横逆乘脾，则肠鸣腹痛；木郁化热，故原文主「清肝和中」。此弦脉示肝气偏亢、脾土受制，非虚寒下利之脉。", ["弦"]], "16917": ["病机", "腹痛已瘥而脉弦不退，脘闷气冲、舌微黄，示肝气仍逆、气机不畅。弦主肝郁气滞，气冲于上则脘闷，郁而化热则舌黄。原文「顺气和中」，正针对弦脉所主之肝气横逆、中焦气滞，痛减而气未顺也。", ["弦"]], "16918": ["病机", "腹痛较瘥而脉沉弦，沉主里、弦主肝，示病位在里、肝气郁滞未解。头晕为肝阳上扰、清窍不利之象。沉弦并见，说明气滞深在里分，虽痛减仍遵前法加减，即从里疏肝理气，不可因痛缓而弃治。", ["沉", "弦"]], "16919": ["病机", "脉弦濡，弦主气滞，濡主湿。舌厚黄滑、便泻不化、小便不利、脘闷，原文断为「湿热」。湿阻气机则脘闷、小便不利，湿热下迫则便泻不化。弦濡相合，正示湿盛气滞、湿热内蕴之病机，故宜和中清利。", ["弦", "濡"]], "16920": ["病机", "脉弦细，弦为肝木偏旺、气机郁滞，细主阴血不足、湿邪内蕴。原文见舌滑白、便溏、小便不多、脘闷、气冲欲呕，是肝气犯胃、湿浊中阻之象。弦细相合，说明木郁乘土、湿阻气逆，故以猪苓汤加减分利湿热、降逆和胃。", ["弦", "细"]], "16921": ["病机", "脉涩滞，涩主血行不畅、湿阻气机，滞为气机壅遏之象。原文言湿热未清、腹中胀闷、便泻，是湿热蕴结中焦，气机被阻，血行亦不畅，故脉来涩滞不利。仍用猪苓汤加减，意在清化湿热、通利气机，使湿去则脉滞可解。", ["涩", "滞"]], "16922": ["兼症", "右脉涩主湿阻气滞、脾运不健，左弦细主肝阴不足、肝气偏亢。原文便泻腹痛、经停四月、腰酸带下、心泛、舌微白、咳呛，是肝脾同病、湿滞下焦而冲任不调。涩与弦细并见，说明气滞湿阻兼阴血亏虚，故先以清气和中治其标。", ["涩", "弦", "细"]], "16923": ["病机", "此段为介按，无脉象描述。原文指出肝肾阴亏则带脉不固而腰酸带下，肝阳横逆则腹痛便泻，上乘于肺则咳嗽心泛。说明病本在肝肾阴虚、肝阳偏亢，标在肺脾受累，故先清肺扶脾、兼理气机，是急则治标之法。", []], "16924": ["病机", "右脉涩主气滞湿阻、脾土受困，左弦主肝木偏旺。原文木克土便泻、气滞经阻、舌心光、胃钝脘闷、腹中有瘕，是肝气横逆乘脾，气聚血滞而成瘕，冲任受阻故经闭。涩弦并见，正合木克土、气滞血阻之机，故宜泄木和中。", ["涩", "弦"]], "16925": ["病机", "此段为介按，无脉象描述。原文言肝阳侮胃、气聚成瘕，又指出阳明隶于冲脉、冲脉即是血海，胃被肝乘则血海同时为病而经阻。说明病机为肝阳犯胃、气聚血滞、冲任受阻，治以泄肝救胃，使肝胃和则血海自调。", []], "16926": ["病机", "脉弦濡，弦主肝木偏旺、气机郁滞，濡主湿邪内蕴、脾土受困。原文舌黄滑、便利腹痛，是湿热蕴结中焦、肝脾不和之象。弦濡相合，说明湿阻气滞、木郁乘土，湿热下迫故便利腹痛，宜治以防痢，即清化湿热、调气和中也。", ["弦", "濡"]], "16927": ["病机", "脉虚主正气不足，尤以脾肾气虚为要。原文便泻较减而脉虚、气机不和、舌滑，说明泻虽减轻而脾肾之气未复，气机升降失和，舌滑为湿浊未净之象。脉虚与便泻并见，提示久泻伤正，故宜固肾止泻、理气和中，标本兼顾。", ["虚"]], "16928": ["病机", "左脉虚细，右弦濡，虚细为气血不足，弦濡为湿痰内蕴。原文谓“中虚气馁，水谷酿湿，成痰作泻”，脾虚失运则湿盛，湿聚成痰而作泻；舌微黄、心肾不交、寝不成寐，皆由中虚湿阻、升降失司所致，故脉象主脾肾两虚、痰湿内停之病机。", ["虚", "细", "弦", "濡"]], "16929": ["病机", "脉沉涩，沉为气滞于里，涩为血行不畅。原文“木克土便泻腹满”，肝郁乘脾，气机壅滞，故脉沉涩；舌黄、心泛欲呕、癸涩，皆肝逆犯胃、冲脉失调之象。脉沉涩主肝郁气滞、脾运受困之病机，宜防腹胀加重。", ["沉", "涩"]], "16930": ["病机", "原文未出脉象，专论冲脉隶阳明、厥阴对峙之病机。肝病犯胃则心泛欲呕，乘脾则便泻腹满；冲脉受肝逆影响，则癸水难以应期。治以苦辛泄降，使肝逆平、胃气和，诸恙自退。此段主述肝逆犯胃乘脾、冲脉失调之病机。", []], "16931": ["预后", "脉弱细，弱为气衰，细为血少。原文“上咳下泻，形肉日削，经闭脘格”，咳泻并作、肌肉削瘦、经闭、脘格，皆气血大虚、脾胃衰败之候。脉弱细正合虚损之机，属棘手重症，预后不良，故列于预后。", ["弱", "细"]], "16932": ["病机", "脉涩滞，涩为血少气滞，滞为湿阻不行。原文“呕渴已瘥，舌心厚，腹尚大，胃钝便滑”，呕渴虽减而舌苔厚、腹大、便滑，显系湿浊内滞、脾胃运化未复。脉涩滞主湿滞中焦、气机不畅之病机，仍遵前法加减。", ["涩", "滞"]], "16933": ["病机", "脉弦细，弦为肝旺，细为脾虚。原文“腹形不减，气逆便溏，舌薄滑，身微热，口渴”，腹大不减、气逆便溏，乃肝木乘脾、脾运不健；身热口渴为兼夹湿热。脉弦细主肝脾不和、湿滞中焦之病机，宜和中分消，防疳。", ["弦", "细"]], "16934": ["病机", "脉弦濡，弦为肝气偏旺，濡为湿滞中焦。原文“虫气内著，腹痛乍作乍止，便溏”，虫扰肠间则腹痛阵作，脾虚湿盛则便溏。脉弦濡主肝胃不和、湿浊内蕴之病机，故宜安胃和中。", ["弦", "濡"]], "16935": ["病机", "脉弦，弦为肝旺，亦主气机郁滞。原文“瘄后受暑，夹食化泻，舌黄，口渴”，瘄后余热未清，暑食交阻，肝胃不和，故脉弦；舌黄口渴为暑热内蕴。脉弦主肝胃气滞、暑食内伤之病机，宜清热和中。", ["弦"]], "16936": ["病机", "时瘄之后便泻腹痛，右脉弦，弦主木旺克土、气机不和。瘄后正气未复，脾土受抑，故腹痛而泻；潮热似疟乃余邪未清、营卫失和之象。脉弦与腹痛便泻并见，说明肝脾不调、湿热余邪内蕴，故治宜和中清利，以调气机、清余邪。", ["弦"]], "16937": ["病机", "便痢未除而脉弦急，弦主气机郁滞，急则示邪势较盛、气不和畅。舌厚黄滑为湿热壅盛之征，潮热乃湿热郁蒸、营卫失调所致。脉弦急与舌厚黄滑、潮热并见，说明暑湿内蕴、气机不和，故姑宜清暑和中，以疏气机、化湿浊。", ["弦", "急"]], "16938": ["病机", "肠澼久累而脉弦，弦为木旺，久痢伤阴，肝木失养而偏亢，木旺乘土、阴血耗伤。舌滑示湿浊未净，头晕而疼乃阴血不足、肝阳上扰之象。脉弦与久痢、头晕并见，说明阴虚而肝木偏旺、湿热余邪未清，故用黄连阿胶汤清热坚阴、养血柔肝。", ["弦"]], "16939": ["病机", "休息下痢而脉弦濡，濡主湿、弦主气机不和，跗浮为水湿泛溢，脘闷为湿阻中焦。脉弦濡与跗浮脘闷并见，说明湿热蕴蓄、气机不畅、水湿不化，故曰湿热蕴蓄，治宜和中清利，以化湿浊、调气机。", ["弦", "濡"]], "16940": ["病机", "休息下痢，圊而不爽，脉涩滞，涩滞主气机郁阻、湿浊黏滞不行。胃钝、舌微白示湿浊困阻中焦、运化失司。脉涩滞与圊而不爽、胃钝并见，说明湿热犹存、气机壅滞，故宜和中清利，以疏滞化湿。", ["涩", "滞"]], "16941": ["病机", "太阴湿疟而脉弦濡细，濡细主湿盛而正气偏弱，弦主疟邪郁于少阳、气机不和。面跗浮为水湿泛溢，食入脘中胀闷为湿阻中焦、运化失职。脉弦濡细与面浮脘胀并见，说明湿邪偏盛、脾运不健，故姑宜渗湿和中。", ["弦", "濡", "细"]], "16942": ["病机", "疟邪犹来而脉弦濡，弦主疟邪郁于少阳、气机不和，濡主湿浊内蕴。舌滑示湿浊未化，湿热未清。脉弦濡与舌滑并见，说明疟邪未解、湿热留恋，故仍遵前法加减，以化湿和中、疏解疟邪。", ["弦", "濡"]], "16943": ["病机", "气虚邪留，寒热久羁，脉虚左弦。虚主正气不足，左弦主邪郁少阳、肝木不和。寒热久羁耗伤正气，夜寐少安乃正虚邪扰、心神不宁。脉虚左弦与寒热久羁并见，说明正虚而邪留，故宜补中益气汤加减，以扶正达邪。", ["虚", "弦"]], "16944": ["病机", "原文谓寒热较差而脉虚，按之弦细，虚为正气不足，弦细为邪留未净之象。益气升阳后寒热虽减，脉仍按之弦细，说明余邪尚恋，正虚未复，故曰邪犹未净，仍遵前法加减，属病机判断。", ["虚", "弦", "细"]], "16945": ["病机", "暑热内著、口腹不慎而化胀，脉濡主湿，左弦主肝脾不和、气机壅滞。舌白罩灰、呛咳脘闷，皆湿浊内阻、肺胃失降之候。脉濡左弦正示湿阻气滞之病机，故列为最重之症，宜分消。", ["濡", "弦"]], "16946": ["病机", "复诊浮肿消减而脉浮濡，浮主水湿在表，濡主湿邪黏滞。舌滑白、呛咳音嘶、脘中略和，说明湿浊尚恋肺胃，气化未复。脉浮濡与浮肿、呛咳相应，示湿邪未清之病机，故仍宜分消为稳。", ["浮", "濡"]], "16947": ["病机", "浮肿已退而脉弦劲，弦劲为肝阳偏亢、气逆不降之象。呛咳音嘶、舌滑，示肺失清肃、湿浊未净。浮肿退而脉反弦劲，说明水湿虽减而肝肺气机未和，故宜清肺利湿，属病机分析。", ["弦", "劲"]], "16948": ["病机", "高年痰湿胶固，腹满跗浮溺少，脉濡细，濡主湿，细主正虚。舌厚腻微灰两边白、呛咳，皆痰湿内壅、脾肺气虚之候。脉濡细正合高年正虚湿盛之病机，故断为最重之症。", ["濡", "细"]], "16949": ["病机", "腹中胀闷、食入尤甚，脉涩滞，涩滞主气机壅塞、血行不畅。舌滑尖红、大便溏、跗浮，示湿浊内阻、脾运失职。脉涩滞与胀闷、跗浮相应，说明湿阻气滞之病机，故称重极之症。", ["涩", "滞"]], "16950": ["病机", "湿久化肿而脉涩滞，涩滞为湿浊壅阻、气血运行不畅之象。舌滑、溲数，示湿邪内停、脾阳受伤。原文明言脾阳受伤，脉涩滞正应湿阻阳伤之病机，故非轻藐之症。", ["涩", "滞"]], "16951": ["病机", "浮肿稍减而脉尚涩滞，涩滞仍主湿浊未化、气血壅滞。舌滑、溲数，示脾阳伤残、运化无力。浮肿虽减而脉未转和，说明湿阻阳伤之病机未除，故曰究非轻藐之症，属病机判断。", ["涩", "滞"]], "16952": ["病机", "脉濡为湿浊内蕴，右大主脾胃受困，食积不化则湿浊壅滞，故舌滑、便溺涩。食积化肿者，脾运失职，水湿停聚，脉濡右大正合脾虚湿盛、积滞内阻之机，宜消食消肿以复中焦运化。", ["濡", "大"]], "16953": ["病机", "脉弦濡者，弦主肝木乘脾，濡主湿浊内停。舌微黄、便利稀水，湿浊下注；浮肿已退而脉仍弦濡，示肝脾不和、湿滞未净。宜分消为稳，即调肝运脾、分利湿浊，防其复肿。", ["弦", "濡"]], "16954": ["病机", "脉涩滞为气血壅滞、湿浊阻络之象。痢后浮肿腹大，舌滑白、溺少，乃痢伤脾胃，湿浊不化，气机壅塞，水湿停聚。涩滞之脉正应气血不畅、湿阻三焦，宜和中分消以通利气机、化湿消肿。", ["涩", "滞"]], "16955": ["病机", "脉濡主湿，伏暑湿热内蕴，湿性黏滞故脉濡。舌滑微黄、跗肿溲赤，为湿热下注、水湿外溢。脉濡与跗肿溲赤相应，示湿热未清、水湿停聚，尤宜防胀，即防湿浊壅盛而成胀满。", ["濡"]], "16956": ["病机", "左脉濡细为脾虚湿盛、气血不足，右寸关弦滑主痰湿壅肺、肝木犯脾。呛咳气急、胸满溺少，乃痰湿化肿、肺失宣降、脾不运湿。脉症相参，示痰湿内盛、脾肺同病，症非轻藐，宜治防变。", ["濡", "细", "弦", "滑"]], "16957": ["病机", "脉沉弦者，沉主里、弦主肝木乘脾。木克土化胀，两跗皆肿、便泻不爽、气逆溺少，乃肝气横逆、脾土受困，水湿不运，气机壅滞。沉弦之脉正合肝郁脾困、水湿内停之机，非轻藐之症。", ["沉", "弦"]], "16958": ["病机", "浮肿已退而脉虚细，示邪去正伤，脾肾两虚。腰痛为肾虚之征，胃纳尚和则脾运未败。虚细之脉主气血不足、肾精亏虚，故宜《金匮》肾气丸加减温补肾阳、化气行水，以固本善后。", ["虚", "细"]], "16959": ["病机", "诸款悉减而脉虚，夜不安寐、临晚跗浮，乃病后正气未复，脾肾气虚，水湿不化，入夜阳气衰而水气泛溢。嘈杂已瘥示胃气渐和，脉虚为正虚之象，仍遵前法加减以扶正化湿、调补脾肾。", ["虚"]], "16960": ["兼症", "脉虚细为气血不足之象，结合“临晚跗浮酸楚”，示脾肾气弱、水湿下注。虚细主正虚，湿滞致跗肿酸楚，故宜分消，防虚中夹湿。", ["虚", "细"]], "16961": ["病机", "脉涩滞主湿阻气机、血行不畅。两跗犹肿、面浮，为水湿泛溢，气化不利。涩滞示湿郁脉络，故宜分消，防化胀。", ["涩", "滞"]], "16962": ["病机", "脉弦细主气滞阴伤。屡有遗滑、腹中不和、呛咳、舌微灰，示肝气郁滞、肺胃不清，虚火内扰。弦为气滞，细为阴亏，故宜清肺胃为主。", ["弦", "细"]], "16963": ["病机", "脉虚细主心肾并亏、气血不足。咳嗽较减而湿未净，屡次滑精，示肾虚不固、湿浊留恋。虚细为精血亏虚之征，故宜清养肝肾，佐清肺渗湿。", ["虚", "细"]], "16964": ["病机", "脉形小数主阴虚内热、心肾不交。痰红已除而溺白、精关不固、溺后有淫，示虚火扰动精室。小数为虚热之象，故宜固补心肾。", ["小", "数"]], "16965": ["病机", "脉虚细主心肾亏虚。阴火已敛而精滑，舌白稍润，示心肾不交、精关不固。虚细为气血两亏之征，故宜补心丹加减以交通心肾。", ["虚", "细"]], "16966": ["病机", "脉细劲主阴血亏虚而兼气滞血瘀。精滑未除、舌微白、大便难有血，示肾虚不固、肠燥络伤。细为阴亏，劲为郁滞，故宜补益润肠。", ["细", "劲"]], "16967": ["病机", "左脉虚细、右濡，主脾肾气阴两虚。泻犹未除、小便不禁，示脾虚湿盛、肾气不固。虚细为阴亏，濡为湿滞，故宜分清养阴。", ["虚", "细", "濡"]], "16968": ["病机", "脉濡主湿，右弦应脾，合参舌滑跗肿，知湿热下注、脾运失司，水湿泛溢肌肤而跗肿；溺赤为湿热下渗膀胱。脉濡右弦正示湿浊偏盛、脾土受困之病机，故治以分清养阴，使湿去而阴不伤。", ["濡", "弦"]], "16969": ["病机", "身热已退而脉弱，示邪去正衰、阳气未复；舌滑、小溲淋漓，乃余湿未清、太阳气化不利。脉弱为正气不足之象，故不任苦寒峻利，只宜清利太阳，使湿浊从小便去而正气不伤，属病后余湿、正虚邪恋之机。", ["弱"]], "16970": ["病机", "脉濡为湿盛之征，湿热下注膀胱，故小便涩痛带血；湿遏阳气不能外达，则肢冷背寒；舌黄为湿热内蕴之据。脉濡与舌黄、溲涩痛相合，正说明湿重于热、下注下焦之病机，故以分清利湿为主，使湿化热清而血自止。", ["濡"]], "16971": ["病机", "涩痛较差而溺后仍有血，脉仍濡，舌滑，知湿热虽减而未清，蕴蓄下焦，伤及血络。脉濡主湿浊留恋，故血尿缠绵不去。既属湿热未清，又虑阴血受损，故借四物汤加减，于清利之中兼养阴血，标本兼顾。", ["濡"]], "16972": ["病机", "尿血遇劳即发，脉濡细，舌黄滑，濡主湿、细主阴血不足，合示湿热蕴蓄下焦、劳则气耗而血不循经。湿热久羁伤阴，故脉见细象；劳倦触发，说明正虚为本、湿热为标。治宜凉血、清热、分利，清利中兼护阴血。", ["濡", "细"]], "16973": ["病机", "脉涩主血行不畅，数主有热，尿血屡发屡瘥而见涩数，知热伤血络、血行瘀滞；肺气窒痹、胸次痰阻，则气机不利，血络更滞。涩数之脉正示热瘀互结、肺气不宣之病机，故以瓜蒌薤白汤宣痹化痰、通阳行气为治。", ["涩", "数"]], "16974": ["病机", "脉弦主肝火，濡主湿浊，弦濡并见，合茎肿作痛已溃、舌白厚，知湿火下注肝经，蕴结前阴。肝脉络阴器，湿火循经下注，故茎肿溃痛；舌白厚为湿浊内盛之征。脉弦濡正示肝经湿火之病机，故用龙胆泻肝汤清泻肝火、分利湿浊。", ["弦", "濡"]], "16975": ["病机", "脉濡主湿浊内蕴，浊流未除、小便涩痛，知湿热仍注下焦；气口滑、舌根黄，示中焦痰湿与下焦湿热并存；咳逆为湿痰上阻肺气。脉濡与气口滑相合，说明湿浊弥漫三焦、肺气不降之病机，故仍遵前法加减，清利之中兼化痰降气。", ["濡"]], "16976": ["病机", "脉细为阴分亏虚、脉道不充，数为阴虚生内热。原文言「阴分尚亏」「心肾不交」，故脉细数；手心热、精竭形怯、小溲乍赤皆阴亏火动之候。细数并见，说明虚火内扰而非实热，故治法以养阴清热为主。", ["细", "数"]], "16977": ["病机", "复诊「脉尚细数」，说明前法虽使精浊较差，而阴分未复、虚热未清仍在。细主阴血不足，数主热，合之则阴亏内热未除；耳鸣、寝寐恍惚为阴精不能上奉、心神失养之症。脉象未变，故仍遵养阴清热前法加减。", ["细", "数"]], "16978": ["病机", "脉涩滞为气血运行不畅、湿浊阻滞脉道之象。原文言「湿热郁遏」，湿性黏滞，郁遏气机，故脉来涩滞不利；脐下胀闷、睪丸偏坠、舌黄腻，皆湿热下注、气机壅遏之候。涩滞在此非血虚，而是湿郁气滞，故治宜疏利。", ["涩", "滞"]], "16979": ["病机", "此按语承上段而论，脉涩滞主气机郁滞、湿浊内阻。原文指出系「七疝中之气疝」，又「舌黄腻」为夹湿热之候，故涩滞说明气滞与湿热相搏、脉道不利。睪丸偏大、痛引脐腹正是气疝夹湿热之典型症候，故治法以疏利湿热、行气散结为主。", ["涩", "滞"]], "16980": ["病机", "右脉弦细，弦主气机郁滞、痛证，细主不足或湿滞脉道。原文「小便流浊涩痛，睪丸偏坠」，为肝经气滞、湿热下注之候；弦应肝主痛，细示湿浊阻滞、气血不畅。右脉候气，弦细并见说明气郁而兼湿滞，故以金铃子散行气疏肝止痛为主。", ["弦", "细"]], "16981": ["病机", "脉滑数为湿热壅盛之象。滑主湿浊痰积，数主热，湿热下注则生痔、下疳；原文又言「九月身发疹痘，系是结毒」，说明湿热毒邪蕴结血分，外发疹痘。滑数正是湿热毒盛、气血沸腾之征，故治宜清解热毒，并请外科参酌。", ["滑", "数"]], "16982": ["预后", "左脉细数为阴血亏虚、虚热内生；右寸关弦主气机不畅、疮毒郁结。原文「溃而不敛」「不时汗出」「形体怯弱」，说明疮疡日久耗伤气血阴液，正虚而毒恋。细数示阴亏，弦示余毒未清，故「宜防疮劳」，即防疮疡日久转为虚劳之候。", ["细", "数", "弦"]], "16983": ["病机", "脉弦细数，弦主虚火上炎，细主阴血不足，数主内热。原文「疮毒未敛」而「阴火上升，齿痛，舌白少津」，说明疮疡日久耗阴，阴虚不能制火，虚火上冲致齿痛；舌白少津为阴津亏乏之征。弦细数合见，正是阴亏火升之病机，故宜养阴清降以防疮劳。", ["弦", "细", "数"]], "16984": ["病机", "脉虚濡者，虚为气不足，濡为湿滞。原文言「疮劳胃钝」，胃气已钝，湿热伤气，故脉见虚濡；舌滑白亦湿象。虚濡并见，说明正气已虚而湿邪未化，清窍不利由此而生，故宜清利湿热、兼顾胃气，不可纯补。", ["虚", "濡"]], "16985": ["病机", "脉虚细，虚为气弱，细为血少。原文「疮劳形怯，胃气稍振」，形怯示气血未复，胃气虽稍振而湿热犹存，故脉仍虚细；舌滑白为湿未化。此脉主正虚湿恋之病机，故仍遵前法清利湿热、兼顾扶正。", ["虚", "细"]], "16986": ["病机", "脉虚细，主气血两亏。原文「诸款悉减，脉虚细，疮口未敛」，症减而脉仍虚细，说明邪退而正未复，疮口不敛乃气血不足以生肌长肉。此脉主虚，故宜补虚扶元，使气血渐充则疮口自敛。", ["虚", "细"]], "16987": ["病机", "六脉涩细，涩为血少气滞，细为血虚。原文「便泻已除」而「癸来涩少，脘中胀闷」，皆缘肝横气滞，气滞则血行不畅，故脉涩细、经量涩少；脘胀为肝气犯胃。此脉主肝郁血滞、冲任不畅之病机。", ["涩", "细"]], "16988": ["病机", "本段为介按，引秦天一论血气化生于水谷，水谷之海即阳明胃气，又为冲脉之本。原文「胃被肝乘，失其生化之源，是癸来涩少」，说明经少脘胀之病机在肝乘胃、生化之源受抑，故以清肝和胃养血为治，使太冲脉盛则月事以时下。", []], "16989": ["病机", "六脉细涩，细主血虚，涩主气滞血瘀。原文「癸来腰腹联痛如刺」，刺痛为瘀血之征，经行腰腹联痛说明冲任气血瘀滞不通。头晕心泛已瘥而脉仍细涩，示营血未充、瘀滞未化，故宜和营卫以调气血。", ["细", "涩"]], "16990": ["病机", "右脉涩主胃气滞而血少，左关沉弦主肝郁。原文「潮热不清」「大便忽泻，经停，腹中有瘕，脐下痛」，瘕与经停为肝郁气滞血瘀，潮热为郁热，便泻为肝木犯胃。脉涩弦沉正合肝郁气滞、胃热之病机，故宜清热养胃和肝。", ["涩", "弦", "沉"]], "16991": ["病机", "右脉虚主胃气不足，左弦细主肝郁血少。原文「寒热较差，胃纳已和」而「经停，腹中有瘕，脐下偶痛」，说明胃气渐复而肝木抑郁未解，瘕与经停皆肝郁气滞血瘀所致。脉虚弦细正示正虚肝郁之病机，故仍宜逍遥散加减疏肝养血。", ["虚", "弦", "细"]], "16992": ["病机", "脉涩细，涩主血少，细主阴亏，冲任内损，血海不充，故腰疼背掣、头疼心悸、癸涩。血虚不能荣养筋脉则腰背掣痛，血不养心则心悸，血不上奉则头疼，冲任亏虚则月事涩少。治宜柔肝、补心、调经，正合养血填冲之法。", ["涩", "细"]], "16993": ["病机", "脉涩细而右弦，涩细为血虚，右弦为气滞。脘闷气滞、癸涩、带下腰酸，皆血虚气滞、冲任不调之象。血虚则经水涩少，气滞则脘闷，带脉不固则带下腰酸。治宜养血和中，使血充气畅，则诸症自减。", ["涩", "细", "弦"]], "16994": ["病机", "脉沉涩，沉主里，涩主血滞。闺女月事仍闭，腹痛脘闷，肢体浮肿，乃血凝气滞、水湿内停。血滞则经闭腹痛，气滞则脘闷，水湿泛溢则浮肿。顷经少安，示血行略畅而病未全退。治当利水活血行气，以通经消肿。", ["沉", "涩"]], "16995": ["病机", "原文未出脉名，介按明言血液被湿热逼出，旁流膈膜，致肢体浮肿；经来时湿热乘虚而入，阻碍血脉周流，血凝滞则经闭腹痛。此段专论湿热与血瘀互结之病机，故治以利水活血行气，面面顾到。", []], "16996": ["病机", "脉虚细，虚主气血不足，细主阴血亏少。带下腰疼、癸涩、腹左有瘕，病在冲任。冲任虚损则带脉不固而带下腰疼，血海不充则经水涩少，气血凝滞则结为瘕块。治宜柔肝调经，以养冲任。", ["虚", "细"]], "16997": ["病机", "脉涩而右寸关弦，涩主气滞血涩，弦主肝郁。气郁成痹，音嘶，腹痛有瘕，癸水早期，皆肝郁气滞、血行不畅所致。气滞则脘闷，血涩则成瘕，肝火上炎则音嘶，肝热迫血则经水早期。治宜泄降清肝。", ["涩", "弦"]], "16998": ["病机", "右脉虚细，左关沉弦。右脉虚细为胃气不足，左关沉弦为肝木偏横。便泻未除、脘闷气滞、癸水早期，乃肝木乘胃、胃弱不运之象。肝横则脘闷，胃虚则便泻，肝热则经早。治宜养胃、平肝、调经，双方兼顾。", ["虚", "细", "沉", "弦"]], "16999": ["病机", "左脉沉弦，右脉虚细。沉弦为肝阳横逆，虚细为胃被肝乘。便泻未除是挟时令湿热，癸水早期是肝热不藏血。肝横则脘闷气滞，胃弱则不能与冲脉生化血液。治宜养胃和血、平肝渗湿，双方顾到。", ["沉", "弦", "虚", "细"]], "17000": ["病机", "脉弦为木旺之象，右虚细示血虚不充。血虚则肝木失养而亢旺，故脉弦；项背掣痛为肝血不能濡筋；癸水先后不一、脘中偶痛、夜寐少安，皆血虚木旺、心肝失和之候。治宜补心平肝，正合脉证。", ["弦", "虚", "细"]], "17001": ["病机", "脉虚为气血不足，左涩为血少滞涩。血海不充则经行后期而癸涩；腰酸带下为肾虚带脉不固；胃纳不旺则化源不足，血虚益甚。脉证合参，病机在胃弱血少、肾虚不固，故治以养胃、调经、涩下。", ["虚", "涩"]], "17002": ["病机", "此段无脉象，以症推机。胃纳不旺则血海渐涸，故癸涩后期；肾虚则带脉不固，故腰酸带下。冲脉隶于阳明，胃弱则冲脉失养，经带同病。治以养胃补肾，使化源充而经调带止，正合病机。", []], "17003": ["病机", "脉左涩为血少滞涩，右弦滑为痰湿内蕴。痰湿下注为滞，故气冲脘闷、癸涩迟滞；血虚气滞则经行不畅。脉证相参，病机为血虚气滞、痰湿下注，故治以养血理气为主，兼化湿痰。", ["涩", "弦", "滑"]], "17004": ["病机", "此段无脉象，以症析机。湿痰下注带脉，带脉失约则下浊液；带脉又系于冲任，冲任并亏则气冲癸涩。病本在脾肾气虚、冲任亏损，标为湿痰下注。治以补脾肾之气，佐舒肝之品，使血旺气和则诸恙自愈。", []], "17005": ["病机", "脉濡涩细为血虚湿滞之象。血虚则脉细涩，湿阻则脉濡；癸涩过滞、腰酸、脐下痛为血虚气滞、带脉不固；心悸为血不养心；头疼、龈起胀泡为虚火上炎。病机在血虚湿滞、虚阳上浮，故用胜金丹加减养血化湿。", ["濡", "涩", "细"]], "17006": ["病机", "此段无脉象，引傅青主论带任两脉。带脉通任，任脉走唇齿，热邪存下焦则津液不能化精而反化湿。今案为带任两脉液虚热炽之象，故见带下、龈胀等症。治用胜金丹加减养血清热、柔肝安神，正合液虚热炽之机。", []], "17007": ["病机", "脉虚细为血虚不足之象。血虚则嘈杂、知饥少纳，为胃失濡养；腰酸带下为血虚及肾、带脉不固；舌色灰厚示兼有湿浊。病机在血虚胃弱、肝脾不和，故治以养血、和中、平肝，使血充胃和则诸症自减。", ["虚", "细"]], "17008": ["病机", "原文未出脉名，以胃液已虚、未能容纳水谷而致知饥嘈杂立论，又言肝肾并亏致腰酸带下。病机属阳明胃液不足、纳化失司，兼肝肾阴亏、带脉不固，故治以柔肝、和胃、养血，属虚损兼带下之候。", []], "17009": ["病机", "脉关尺涩细，涩主血少气滞、脉道不利，细主阴血亏虚。关尺候肝肾冲任，涩细见于关尺，说明冲任血亏、脉道不充，故经停七月、腹中有形、腰酸带下，病在冲任，治宜柔肝涩下以摄冲任。", ["涩", "细"]], "17010": ["病机", "原文未出脉，以冲任并亏立论：任脉不通、太冲不盛则经停七月；肝郁不畅则腹中有形；肾虚带脉不固则腰酸带下。病机为冲任亏虚、肝郁肾虚，柔肝涩下即所以摄冲任，属虚中兼郁之带下经闭候。", []], "17011": ["病机", "脉尚涩，涩主气血滞涩、冲任不畅。小腹仍滞痛、白带未除、冲任腰胯酸痛，皆由冲任气血涩滞、肝失疏泄所致。脉涩与滞痛带下相应，故治以和肝涩下为稳，示病机未离滞涩一层。", ["涩"]], "17012": ["病机", "原文未出脉，引王叔和带脉为病左右绕脐、腰脊痛、冲阴股之说，断此症为带脉失司、肝逆未平。带脉不约则诸脉松弛，肝气上逆则腰脊冲痛，病机在带脉失司兼肝逆，属带下腰脊痛之候。", []], "17013": ["病机", "脉涩细，涩主血滞、细主血虚，合见则为冲任血亏而运行不畅。冲任内怯故腰疼背掣、带下；癸涩不调、头疼亦由血虚不荣、脉络涩滞。脉症相合，治以养血、调经、涩下，病机重在冲任虚而兼涩。", ["涩", "细"]], "17014": ["病机", "脉涩左弦细，左脉候肝，弦细为肝阴不足、肝气郁逆，涩则气血滞涩。带下如注、小腹滞痛、癸涩不调、舌厚腻、汗出濈濈，皆厥阴疏泄失职、湿浊下注之象，故以疏泄厥阴为主，病机在肝郁湿滞。", ["涩", "弦", "细"]], "17015": ["病机", "右脉滑数，滑主痰湿亦主妊娠气血壅盛，数主热。经停二月余而见脘格呕恶、食入即吐，右脉滑数与之相应，故断宜防妊育。病机属胃气上逆、痰热内阻，然滑数亦为妊脉之兆，须辨妊娠与恶阻。", ["滑", "数"]], "17016": ["病机", "脉左虚细，右稍滑，左脉候肝，虚细为肝阴不足，肝阳上亢，化风犯胃，故见头蓬、头疼晕眩、呕恶；右滑为胃有痰湿，经停厌食，虑其孕育，脉证合参，病机为肝风犯胃，胃失和降。", ["虚", "细", "滑"]], "17017": ["病机", "脉弦濡滑，弦主肝旺，濡主湿，滑主痰，妊育头胀，腹中气机不和，溲弱短数，呕恶涎沫，胃钝，乃肝旺犯胃，痰湿中阻，胃失和降，治宜和中理气护胎。", ["弦", "濡", "滑"]], "17018": ["病机", "小产后带下如注，脉弦细涩，弦为肝郁，细涩为营阴亏耗，冲任不固，脘中有形攻触而痛，癸水不调，乃肝郁血涩，冲任虚损，带脉失约，治宜涩下平肝。", ["弦", "细", "涩"]], "17019": ["病机", "刘宗厚谓带下多本阴虚阳竭，营气不升，经脉凝涩，冲气下陷，精气积滞下焦。今脉凝涩，系肝郁耗营，带脉失固，冲气下陷，故小产后带下如注，冲任虚气挟肝阳上逆则脘腹作痛，治宜平肝补肾。", ["涩"]], "17020": ["预后", "产后湿臌，溲黄腹满足肿，脉滞舌黄，脉滞为湿阻气机，舌黄为湿热内蕴，湿浊壅滞，气化不利，症势棘手，预后堪忧。", []], "17021": ["预后", "产后臌胀，舌仍黄，溲较长，脘未展，脉尚滞，湿浊未化，气机未畅，症尚棘手，脉滞示湿阻气滞仍在，预后未可乐观。", []], "17022": ["预后", "产后臌胀，脉尚滞，溲长，舌黄，症尚棘手，脉滞为湿浊壅滞未解，气化未复，虽溲长而舌黄不退，病机仍属湿阻气滞，预后堪虑。", []], "17023": ["病机", "癸涩趱迟，带注腹痛有症，左脉涩右沉弦，中脘胀闷背掣，左涩为肝血瘀滞，右沉弦为气郁湿阻，冲任不调，带脉失约，治宜顺气利中平肝。", ["涩", "沉", "弦"]], "17024": ["病机", "脉滞滑，滞为气机不畅，滑主痰湿虫积内蕴。稚孩虫气内著，阻滞中焦，气机不利则腹痛；虫扰肠腑、湿浊下迫则作泻；苔白、口渴呕恶，皆虫湿内阻、胃气上逆之象。脉滞滑正合虫气内著、湿浊壅滞之病机，故治以安胃利中，使中焦和而虫湿化。", ["滑", "滞"]], "17025": ["病机", "脉弦滑，弦主肝郁气滞、水湿内停，滑主痰湿。便泻虽减而面跗浮肿不退，经停，乃肝脾不调、水湿泛溢肌肤。脉弦滑示水气太过、气机壅滞，与浮肿、经停相应，故仍遵前法加减，以调气利水为稳。", ["弦", "滑"]], "17026": ["病机", "脉清数，数主热，清数示营分有热而兼虚。崩漏后阴血亏耗，营卫不和，虚热内扰，气滞不畅则腹满作痛；血虚水湿不化则腿跗浮肿。脉数与崩漏后营虚内热相应，故宜和营卫为主，使营卫调而虚热退。", ["数"]], "17027": ["病机", "脉弦苔滑，弦主气机郁滞，滑主痰湿壅盛。宿恙夹新邪，痰壅气塞，肺失清降，故咳嗽暮夜尤剧。脉弦滑正示痰气交阻、肺络壅塞之病机，与痰壅气塞、咳剧相应，故姑宜清降化痰，使痰化气降则咳平。", ["弦", "滑"]], "17028": ["病机", "脉两手沉弦，沉主里、主水，弦主肝郁气滞、寒凝。癸涩迟滞，腹中㽲痛，带下为注，乃肝郁血滞、寒湿下注之病机。沉弦示病在里、气机郁滞，与经迟、腹痛、带下相应，故宜四物汤主治，以养血调肝、行滞止痛。", ["沉", "弦"]], "17029": ["病机", "脉清气口浮滑，左沉弦。浮滑主新邪在表、痰湿上壅，沉弦主里气郁滞。咳逆痰阻、午后恶寒，乃外邪引动痰湿；癸水适至、脘闷便利，示里气不和。脉浮滑与沉弦并见，正合宿恙夹新邪、痰阻气塞之病机，故宜清解为主。", ["浮", "滑", "沉", "弦"]], "17030": ["病机", "右脉沉涩，左关弦。沉涩主里虚血滞，弦主肝郁。产后载余，癸水未至，腹痛心涎，胃钝大便忽泻，乃肝郁脾虚、血涩气滞之病机。沉涩示血行不畅，弦示肝气偏旺，与腹痛、便泻、经闭相应，故姑宜理气平肝为主。", ["沉", "涩", "弦"]], "17031": ["病机", "脉两手混滞，混滞示气机失利、湿浊内阻。中焦未和，气机失利，故大便稍下不畅。脉象模糊混滞，正合中焦气滞、湿阻不化之病机，与大便不畅相应，故仍遵前法加减为妥，以调和气机、化湿和中。", []], "17032": ["主病", "脉沉细主里虚，湿浊内停。虫气作痛，腹泻肢肿面浮，乃脾虚湿盛、气机壅滞之象；苔白口渴为湿阻津不上承。沉细示正气不足，湿邪深陷，症属重极，故宜利中分消以祛湿健脾。", ["沉", "细"]], "17033": ["病机", "脉弦主邪郁少阳，两尺虚细为肾气亏虚。体虚受邪，寒热久羁，正虚邪恋，故脉弦而尺部虚细；苔白腰痛乃肾虚湿着。此虚人外感，宜补中益气汤加减以扶正祛邪。", ["弦", "虚", "细"]], "17034": ["预后", "两手细数，细为阴亏，数为虚热。咳嗽日久，癸水不调，周身脉络不舒，乃肺肾阴虚、虚火内灼之候。阴亏则脉细，热扰则数，症势防入损途，示久咳伤阴，有成劳之虞。", ["细", "数"]], "17035": ["病机", "寸浮滑主邪客肺卫，风痰上扰。呛咳气促，苔白形寒，为风邪束表、痰阻气道之象。浮脉主表，滑脉主痰，寸部独显，病位在肺，故宜清肺疏风化痰。", ["浮", "滑"]], "17036": ["兼症", "左涩主血滞，右关沉弦主气郁湿阻。痛气滞，带下如注，乃奇经气血不畅、湿浊下注。苔白里半截微黄示湿郁化热之渐。涩脉示血行不畅，沉弦示气机郁滞，治在奇经以调气血。", ["涩", "沉", "弦"]], "17037": ["预后", "右小数左细，数为热，细为阴伤。呛咳声重音哑，苔黄络血上溢，乃肺热伤络、阴液受灼。脉细数示正虚热盛，络血上溢为热迫血行，究非轻藐之症，预后堪忧。", ["小", "数", "细"]], "17038": ["主病", "脉弦数主热盛邪郁。温邪未清，身热口燥，痰壅气塞，苔黄腻，乃痰热壅肺、气机闭阻。弦为邪郁，数为热盛，呛咳便利示热邪下迫，症尚重险，宜防变幻。", ["弦", "数"]], "17039": ["病机", "脉虚细主气阴两虚，左弦已缓示肝郁渐解。呛咳稍差，胃纳略增，为病势向愈；苔腻肢楚乃湿浊未净。虚细脉示正虚未复，故宜清肺胃化痰以善其后。", ["虚", "细", "弦"]], "17040": ["病机", "脉小数，小为阴血不足，数为阴火内动。咳痰未除而阴火不敛，苔黄中心红、彻夜不寐，皆阴亏火旺、虚热扰神之象；形肉日削乃壮火食气、肌肉失养。脉症合参，属肺劳重症，病机为肺阴亏虚、阴火不敛。", ["小", "数"]], "17041": ["病机", "脉弦细，弦主气滞，细主湿郁阴伤。痢下赤白、苔滑白尖红、小腹下坠，为湿热蕴蓄肠道、气血壅滞，兼阴分已伤。脉弦细正合湿热内蕴而阴血受灼之病机，故仍遵前法加减，清化湿热兼护阴。", ["弦", "细"]], "17042": ["病机", "脉弦细，弦为虫扰气滞，细为脾虚湿蕴。闺女虫气作泻，苔滑白，两足浮肿，乃虫积内扰、脾运失健、水湿下溢。脉弦细应虫气与脾虚湿滞并见，故断势恐增剧，非轻浅之候。", ["弦", "细"]], "17043": ["病机", "寸脉浮滑，浮主风邪在表，滑主痰湿内蕴。风邪袭肺则呛咳形寒，苔微黄、胃钝肢楚，为风邪外束、痰湿中阻、肺胃失和。寸浮滑正合风痰袭肺之病机，故宜清肺化痰，表里兼治。", ["浮", "滑"]], "17044": ["病机", "脉涩左弦，涩主血瘀，弦主气滞。产后瘕泻、腹中隐隐作痛，舌光、呛咳形怯，乃产后气血亏虚，瘀滞内结，肝气横逆，脾运失司。脉涩左弦应瘀滞与肝郁并见，形怯舌光示正虚，故非轻藐之症。", ["涩", "弦"]], "17045": ["病机", "脉浮弦数，浮主风邪，弦主气滞，数主热。屡受风邪，咳嗽多痰，苔滑，为风邪外袭、痰热内蕴、肺失清肃。浮弦数正合风痰热邪壅肺之病机，故宜止嗽散加减，疏风宣肺、化痰止咳。", ["浮", "弦", "数"]], "17046": ["病机", "脉滞滑，滞主气机壅阻，滑主湿痰内盛。便泻未除、经停脘闷、肢体浮肿，乃湿浊内困、脾运失健、气机不畅，冲任受阻。脉滞滑应湿阻气滞之病机，故仍遵前法加减，化湿理气调经。", ["滞", "滑"]], "17047": ["病机", "脉细数，细主阴血亏虚，数主阴火内动。小孩肝泻化肿，唇舌均红，溺少，为肝泻日久，阴液耗伤，阴火不敛，水湿不化。脉细数正合阴亏火旺、水湿内停之病机，故属棘手凶危之症。", ["细", "数"]], "17048": ["病机", "左脉涩细，涩主血少，细主阴亏，故癸来涩少；右寸关弦滑，弦为气滞，滑主痰湿，气冲脘闷心涎、苔滑腹痛，皆气滞痰阻之象。气滞作泻，脉证相合，故以和肝调经为主。", ["涩", "细", "弦", "滑"]], "17049": ["病机", "脉两手皆弦，弦主气滞，腹满有瘕、经停九月、气滞如痛，皆肝气郁结、冲任不利之候。便泻稍减而脉仍弦，说明气滞未解，故仍遵前法加减为妥。", ["弦"]], "17050": ["病机", "脉右涩，涩主血滞；左关弦，弦主气郁。产后冲任不固，带注腰酸，腹痛有瘕，皆奇经亏虚、气血瘀滞之象。涩弦并见，故宜治奇经，以调补冲任为要。", ["涩", "弦"]], "17051": ["病机", "脉弦细，左沉涩，弦细主肝郁脾虚，沉涩主气滞血少。脾泄腹痛脘闷、胃钝足跗浮、癸水趱迟，皆脾虚湿滞、肝木乘土之候。脉见沉涩，示水湿内停，故宜防肿胀。", ["弦", "细", "沉", "涩"]], "17052": ["病机", "脉寸浮滑，浮主风邪在表，滑主痰热内蕴。风湿条热、身疼肢楚、气冲脘闷欲呕、苔黄咳逆、咽中不爽，皆风热挟痰上扰之象。寸浮滑，邪在上焦，故尤宜防剧。", ["浮", "滑"]], "17053": ["病机", "六脉涩细，涩主血瘀，细主阴亏。肝风未静，头晕惊怖，带注腰疼，子后鸣鸣便利，皆肝风内动、阴血不足、冲任失养之候。脉证合参，仍遵前法加减再进。", ["涩", "细"]], "17054": ["病机", "脉两寸关弦，弦主肝郁气逆。心惕如悬、胸闷胃馁少谷、舌色透明、偶觉晕眩，皆肝气上逆、胃气不和之象。弦脉见于寸关，示病位在中上焦，故宜泄降平肝。", ["弦"]], "17055": ["病机", "脉虚细，虚细主气阴两亏；左弦数，弦主肝郁，数主热。脱力腰跗酸、咳痰曾患失血、苔黄有小红星、搜溺赤，皆阴虚内热、肝火偏亢之候。虚细为本，弦数为标，故宜清上益下。", ["虚", "细", "弦", "数"]], "17056": ["病机", "脉两手弦细，弦主气机郁滞、肝木失疏，细主血少脉道不充。气阻经隧则血行不畅，结为瘕聚而腹痛；木郁克土，故脘闷便泻；带注腰疼乃冲任受累、湿浊下注。弦细并见，示气滞血涩、虚实夹杂，故以青娥丸法加减温养通滞。", ["弦", "细"]], "17057": ["病机", "脉濡右弦，濡为湿盛脉道弛缓，右关弦则湿郁中焦、土壅木乘。湿热盘踞，气机不利，故脘闷腹痛；苔黄滑、肢体浮肿，皆湿郁化热、水气泛溢之征。濡弦并见，主湿浊内阻而兼气滞，故用分消利中法，使湿热从上下分利。", ["濡", "弦"]], "17058": ["病机", "产后四月，脉涩弱，涩主血少行滞，弱主气虚不充，正合产后气血两亏。便泻未除、跗浮，为脾虚湿盛、水气下趋；腹痛已缓而嘈杂少谷，乃胃气未复。苔滑亦湿象。涩弱之脉示虚中夹滞，故以猪苓汤加减分利水湿，兼顾产后正虚。", ["涩", "弱"]], "17059": ["病机", "脉弦细而气口滑，弦细主湿郁气滞、体虚形怯，气口滑则湿痰内蕴。苔白根微黄，寒热交作、肢冷不暖，是湿邪夹杂、阻遏营卫出入；曾患失血而形怯体虚，正虚邪恋。脉示湿浊壅遏、气机不畅，故先治标以祛湿化浊，待邪去再议扶正。", ["弦", "细", "滑"]], "17060": ["病机", "脉弦细，弦主气逆、肝木犯肺，细主阴血不足、脉道不充。咳嗽气急乃肺失肃降、气逆于上；苔白滑、胃纳不旺，为痰湿内停、脾运不健。弦细并见，示本虚而气逆痰阻，故姑宜泄降利胃化痰，先调气机以复肃降之常。", ["弦", "细"]], "17061": ["病机", "脱身受邪，湿著阻气，脉弦主气机郁滞、湿阻脉络。苔滑白为湿浊内蕴，呛咳气逆乃湿痰上犯于肺、肺失宣降；跗酸溲溺赤，是湿郁下趋、渐有化热之势。单弦之脉紧扣湿著阻气，故治以清肺利湿化痰，使气行湿化则咳逆自平。", ["弦"]], "17062": ["病机", "脉弦濡，弦主少阳枢机不利、疟邪伏于半表半里，濡主湿盛脉道弛缓。湿热化疟，寒热互作，正邪交争于枢；食入脘胀、小溲乍赤，为湿阻中焦、热扰下焦。弦濡并见，示湿遏热伏、气机不畅，故宜利中祛邪，化湿畅中以解疟。", ["弦", "濡"]], "17063": ["病机", "脉涩数，涩主血行不畅、郁滞不通，数主火热内扰。肝火上郁，循经上扰则右耳失聪；木火犯及冲任，故带注腹满、癸水不调；苔滑为兼夹湿浊。涩数并见，示火郁血滞、虚实夹杂，故以清少阳为主，清降胆火以解郁热。", ["涩", "数"]], "17064": ["主病", "脉细滞，细主气血不足，滞主湿浊内阻。原文“癸涩迟滞，腹痛胀闷”提示湿滞中焦，气机不畅，故腹痛胀闷；湿浊下注则便泻，胃气上逆则恶心。脉细滞与脾虚湿滞之病机相应，故宜利中化湿。", ["细", "滞"]], "17065": ["主病", "脉两寸关浮滑，浮主表，滑主痰湿。原文“风湿外乘，身热恶寒”为风湿袭表，卫阳被遏；寸关浮滑提示风湿之邪在表，兼有痰湿内蕴，故见呛咳身酸楚。脉症合参，属风湿外感，宜辛凉轻解。", ["浮", "滑"]], "17066": ["病机", "脉混滞，原文未明确脉名，但“混滞”提示湿浊内阻，气机不畅。虫痛尿白悉差，大便仍滑，为脾土失运，湿浊下趋。脉混滞与脾虚湿滞相应，久则易成疳患，故宜防之。", []], "17067": ["主病", "脉细数，细主阴血亏虚，数主虚热内扰。原文“肺劳咳血，苔黄，腹痛便结，胃钝背寒”提示肺阴亏虚，虚火灼络则咳血；阴虚肠燥则便结；虚热内蒸则苔黄。脉细数与肺劳阴虚火旺之病机相应，故非轻藐之症。", ["细", "数"]], "17068": ["主病", "脉左弦右涩，左弦主肝气郁结，右涩主血行不畅。原文“肝块作痛，脘中嘈杂”为肝郁血瘀，气机不利；癸涩带注、腰酸背制为肝血不足，冲任失调。脉弦涩与肝郁血瘀、血虚之病机相应，故宜养血平肝。", ["弦", "涩"]], "17069": ["主病", "脉弦右滑，弦主疟邪郁于少阳，滑主痰湿内蕴。原文“大疟未除，呕恶脘闷”为疟邪犯胃，痰湿中阻；咳逆痰阻、腿跗酸楚为痰湿上逆下注。脉弦滑与疟邪痰湿之病机相应，故宜利胃化痰祛邪。", ["弦", "滑"]], "17070": ["主病", "脉细左关弦，细主脾虚气血不足，左关弦主肝郁。原文“脾泄较差，食入脘闷”为脾虚不运；癸水未至、口渴跗浮为肝郁血虚，水湿不化。脉细弦与脾虚肝郁之病机相应，故仍遵前法加减。", ["细", "弦"]], "17071": ["预后", "脉两手皆细，细主气血两虚。原文“便泻稍减”但“食入脘腹胀闷，经停”，为脾虚不运，气血生化不足，冲任空虚。脉细与脾虚气血亏虚之病机相应，久则水湿停聚，故防成肿胀。", ["细"]], "17072": ["病机", "左脉小数主阴虚内热，右弦主肝横气滞。阴虚呛咳、失血、咽痛音低，皆阴亏火旺、金水不济之象；苔滑白、便溏则兼脾湿不运。肝横气滞与右弦相应，故云不易图治。", ["小", "数", "弦"]], "17073": ["病机", "右涩主营虚血少，左弦主肝郁气滞。营虚嘈杂、癸水先后不一，带注腰坠、膻左有瘕，皆奇经失养、肝郁络滞之候。舌心空亦营虚之征，故治在奇经。", ["涩", "弦"]], "17074": ["兼症", "脉濡滑主湿浊内蕴，苔腻为湿浊上泛。小孩便泻未除而虫积尚存，濡滑之脉正合湿滞虫扰之机，故仍宜前法加减，化湿驱虫并进。", ["濡", "滑"]], "17075": ["主病", "脉浮数主风湿外乘、表卫不和。头疼发热乍寒、身疼肢楚为风湿袭表之症；呛咳不寐乃风邪犯肺、痰阻气逆。浮数之脉与表证相应，故宜轻解化痰。", ["浮", "数"]], "17076": ["病机", "脉虚主气阴不足，右弦滑主肝郁痰滞。呛咳未除、头晕目暗为肺虚肝亢、痰浊上扰；苔滑微灰、便结乃痰滞津亏。虚而兼弦滑，故宜清肺安神。", ["虚", "弦", "滑"]], "17077": ["病机", "脉弦细主肝郁阴亏、中气不足。前药已效而寒热较轻，呛咳不已、腿跗酸楚，乃中虚肝乘、营卫不和之象；苔滑白亦脾弱湿滞。弦细应建中，故宜建中汤加减。", ["弦", "细"]], "17078": ["病机", "脉小数主阴虚内热，右寸关弦主肝肺气郁。大腹已润而头晕呛咳未除，苔白根微黄、子后寐不安，皆阴亏火浮、肺肝不降之候，故仍遵前法加减。", ["小", "数", "弦"]], "17079": ["病机", "脉小数主阴虚内热、血分不清。血舍未清、舌心灰黄为热郁血分；呛咳较减而腹痛便下滞，乃阴亏肠燥、气滞不畅。小数之脉与血热阴伤相应，故仍遵前法加减。", ["小", "数"]], "17080": ["病机", "脉濡为湿困，左弦细乃肝郁血少，合苔黄滑、尖边红、颜红汗出口渴，显系湿郁化热、肝阳偏亢、阴血暗耗之机。腹满气逆、便弱不爽为湿阻气滞、肝胃不和之象，故断为棘手重症，非单纯表里可解。", ["濡", "弦", "细"]], "17081": ["主病", "大疟久发，脉虚为正气已耗，盗汗乃卫外不固、阴液外泄之征；苔黄咳痰、四肢酸楚，示疟邪未净而兼痰湿留连。脉虚与盗汗并见，说明正虚邪恋，故用何人饮扶正截疟，非一味攻邪可效。", ["虚"]], "17082": ["预后", "叠进建中汤已效，脉较有神，是胃气渐复、生机未绝之佳兆；气口滑主痰食内滞未清，溺热形寒、汗出稍饮，示营卫未和、里热未净。脉有神而气口滑，说明正复而余邪未尽，故仍守前法加减，不可骤补骤攻。", ["滑"]], "17083": ["主病", "脉细为阴血不足，左弦主肝郁气滞；苔微白、脘闷、大便忽泻，乃肝木乘脾、湿浊内阻；寒热交作、呛咳肢楚、胃钝溲赤，示邪郁少阳、表里失和。脉细弦与寒热脘闷相应，故用活人败毒散加减，疏解达邪兼和肝脾。", ["细", "弦"]], "17084": ["预后", "左脉虚细为阴血亏虚，右寸滑数主肺有痰热；盗汗较差、呛咳已减而痰红未除，示虚损未复、热伤肺络；苔心微黄、便滑形怯，乃脾弱阴伤。脉虚细与滑数并见，说明正虚邪热交织，故断为不易之症，须防虚中夹实。", ["虚", "细", "滑", "数"]], "17085": ["病机", "两手小数，小为阴血不足，数为热象；苔转微白、尖边尚红，示热势稍退而阴分未复；呛咳较减而音犹嘶，乃肺津受灼、金失濡润。脉小数与音嘶并见，说明热灼阴伤、津液有涸竭之势，故虑防涸阴，治当顾护阴液。", ["小", "数"]], "17086": ["主病", "脉浮滑数，浮主风邪在表，滑数为痰热内盛；风湿发热口燥、苔黄厚，示表邪化热、里热炽盛；咳痰吸短、右胁刺痛，乃痰热壅肺、络气不利。脉浮滑数与诸症相应，说明风湿夹痰热、表里俱急，故列为重险，宜防变端。", ["浮", "滑", "数"]], "17087": ["病机", "脉弦细，弦主气机郁滞，细为阴血不足；呛咳未阴、痰不易出，乃肺燥津伤、气逆不降；苔滑气逆，示痰湿内停而气机上逆。脉弦细与呛咳痰难、气逆相应，说明阴亏气郁、痰阻肺络，故仍遵前法加减，以养阴化痰降逆为要。", ["弦", "细"]], "17088": ["病机", "脉滑主痰湿内蕴，数主热邪偏盛，合苔黄、咳痰带红、咽痛音嘶，知湿邪侵肺已从热化，痰热交阻肺络，故倏热乍寒头疼。滑数并见，为痰热壅肺之征，治宜清解化痰，使痰热去则肺气宣降复常。", ["滑", "数"]], "17089": ["病机", "左脉沉弦，沉主里、弦主肝郁气滞；右寸转坚，坚为气结不柔。头晕且疼、心惕肢楚、腹满左偏有瘕，皆肝气郁结、横逆犯中所致。弦坚并见，示肝郁化火、气机壅滞，故以柔肝理气和中为治，使木气条达则诸症自缓。", ["沉", "弦", "坚"]], "17090": ["预后", "脉小数，小为气阴不足、数为余热未清。清窍未和、睡即呛咳、音犹嘶，示肺胃余热未净、阴液已伤。胃气稍振为向愈之机，然脉仍小数，说明邪未尽而正未复，故原文断为「还防变幻」，提示须继续清养，不可遽补。", ["小", "数"]], "17091": ["病机", "脉数主热，左浮滑示风热挟痰在表在络。风湿发热口燥、呛咳痰阻、左胁痛，为风热痰浊痹阻肺络；癸水适至淋漓、大便黏滞不爽，示湿热下注。数而浮滑，热势方张，痰热内扰，故原文特言「尤防痉厥之变」，乃热盛动风之虞。", ["数", "浮", "滑"]], "17092": ["预后", "脉细数为阴液亏耗而余热未清。痢已带粪、小溲略利，示肠道湿热渐化、胃气来复；然咽干音嘶、苔红稍淡，仍属热伤肺胃之阴。细数之脉与症相符，邪退正虚而未至危候，故曰「宜清热解毒，不致变幻，无虑」，为预后尚佳之判。", ["细", "数"]], "17093": ["病机", "右脉弦滑，弦主肝火、滑主痰热，右寸候肺，知肝火刑肺、痰热内蕴；左逾转坚，坚示肝郁化火之势未减。咳痰带红、苔黄头晕、寝寐恍惚，皆肝火挟痰上扰、灼伤肺络之象。弦滑坚并见，火痰交炽，故治以清降为主。", ["弦", "滑", "坚"]], "17094": ["预后", "脉涩主血少瘀滞，右弦细示肝郁而阴血不足。呛咳稍减而经阻脐下胀闷、舌心空、寒热交作，为阴血亏虚、肝郁气滞、冲任不调之象。涩细并见，精血已损，故原文断为「究属损怯之症」，提示虚损已成，预后须慎。", ["涩", "弦", "细"]], "17095": ["预后", "脉数主热，左弦主肝郁。呛咳未除、音出犹嘶，肺热未清；恶寒潮热、子后汗出则退、苔黄，示阴虚内热、营卫不和。数弦并见，热郁阴伤，正虚邪恋，故原文诫「尤宜防损」，虑其久咳耗阴，渐成虚损之候。", ["数", "弦"]], "17096": ["病机", "六脉涩细，涩主气滞血瘀，细主气血不足。气滞则脘闷，血虚不荣则头晕而疼，腰胯胀为气机不畅，苔滑白示湿浊内蕴。心惕较差乃气血不足、心神失养。脉涩细与气滞脘闷、腰胯胀、头晕疼相应，故仍遵前法调气养血化湿。", ["涩", "细"]], "17097": ["病机", "脉沉弦左细，沉主里，弦主痛主气滞，细主不足。虫气作痛故脉弦，足跗浮、大便滑为水湿不化，苔白口渴示湿阻津不上承。左细为肝血不足，虫扰气机则痛。脉沉弦细与虫痛、足浮、便滑相应，故宜安胃利中，调其气机。", ["沉", "弦", "细"]], "17098": ["病机", "脉细右弦，细主气血不足，右弦主气滞于中焦。泻痢未除而胃气已振，脉细为泻痢伤阴之象，右弦为肝木乘脾、气机不畅。肛坠作痛乃气虚下陷兼气滞，舌红较和为阴伤渐复。脉细右弦与泻痢、肛坠痛相应，仍遵前法调气和营。", ["细", "弦"]], "17099": ["病机", "脉虚数，虚主气血不足，数主热或虚阳浮动。心惕如悬乃心血亏虚、心神不宁，经停腰腹痛为血虚气滞、冲任失调。虚数之脉示阴血不足而内有虚热，与心惕、经停、腰腹痛相应。法宜养胃柔肝，培补气血以安神调经。", ["虚", "数"]], "17100": ["病机", "脉滞寸口浮大，浮主表主风，大主邪盛，滞为气机不畅。风湿内并，苔微黄示湿郁化热，腹痛脘闷、头疼晕眩为风湿上扰、气机壅滞。癸水适至，血室正开，风湿易乘虚内陷，恐变痉病。脉浮大而滞与风湿内并、头晕脘闷相应，故宜疏利为稳。", ["滞", "浮", "大"]], "17101": ["病机", "脉弦主气滞、主肝木偏旺。呕恶腹痛悉差而潮热汗微，脉弦经阻嘈杂，示肝气郁滞、木乘土位，经血受阻。潮热汗微为郁热内蒸，嘈杂为胃气不和。脉弦与经阻、嘈杂、潮热相应，仍照前法加减以疏肝调经、和胃降逆。", ["弦"]], "17102": ["主病", "脉弦苔白，弦主疟邪伏于少阳、气机不和，白苔示寒湿。寒热间日而作已发三期，头疼咳逆、胃钝胸闷，皆疟邪阻遏少阳、气机升降不利所致。脉弦与寒热间日、头疼胸闷相应，故藉清脾饮加减截疟，以和少阳、化湿浊。", ["弦"]], "17103": ["病机", "脉沉涩，沉主里主气滞，涩主血瘀。经停两月而咳血气促、脘中空闷，此属倒经，乃瘀血内阻、气逆上冲，血不循经而随气上逆。脉沉涩与经停、咳血、气促相应，示瘀阻气逆之机，故宜清降为主，降逆化瘀以调经。", ["沉", "涩"]], "17104": ["兼症", "脉细涩为阴血不足、脉道不充且行涩，血虚不能养心则心惕夜寐不安，五心烦热；血少气滞则中脘胀闷，腹痛虽缓而癸水趱迟。细涩主血虚有滞，故宜养胃清热佐宁神，以滋化源而安神。", ["细", "涩"]], "17105": ["病机", "脉弦右涩，弦主气滞，右涩主气机不利，故腹满气滞；气滞血亦不畅，冲任失调则癸水不调。此脉象反映气滞为主、兼有血行不畅之病机，故宜顺气利中，气行则血行。", ["弦", "涩"]], "17106": ["病机", "脉弦细而涩，弦为气滞，细涩为血虚，合之乃血虚气滞之象。血虚不能充脉则细涩，气滞不行则脉弦；血虚气滞，冲任失养，故经水数月不至，腹痛便艰，周身脉络板掣。宜活任脉以通调气血。", ["弦", "细", "涩"]], "17107": ["病机", "脉虚主气血不足，癸涩面带黄色为血少脾弱之征；血虚不能荣养脉络则络脉抽掣，肝血不足、虚风内动，故宜柔肝熄风。脉虚腹痛、便血，皆因肝虚不能藏血、脾虚不能统血所致。", ["虚"]], "17108": ["病机", "脉虚为气血两亏，冲任不固，故腰疼带下如注；血海不充则癸水趱迟。腰为肾府，带脉不约则带下如注，皆由血虚不能濡养、气虚不能固摄所致。故宜补血涩下为主，以固冲任。", ["虚"]], "17109": ["预后", "脉弦左数，弦主肝郁，数主热，左关候肝，肝郁化热；瘰疬已溃而舌心空，倏热乍寒，经闭，症属重极。此脉象示肝郁热炽、阴血耗伤，正虚邪恋，故断为重极，以逍遥散加减疏肝清热。", ["弦", "数"]], "17110": ["病机", "脉弦细，弦为气滞，细为血虚，乃肝郁血虚之象。冲任失调则癸不及期，气滞血瘀则腹痛有瘕；带脉失约、督脉不利则带下督背掣。此脉示血虚气滞、冲任不调，故宜胜金丹加减以调经。", ["弦", "细"]], "17111": ["病机", "脉涩右沉弦，涩主血滞，右沉弦主气滞于内；先腹痛而后经至，气滞为多。气滞血行不畅则脉涩，肝郁气滞则脉沉弦；头晕腰酸为气滞血瘀、肾府失养。故姑活血理气调经，以通滞为主。", ["涩", "沉", "弦"]], "17112": ["病机", "呛咳不减、音出不扬，是肺气失宣、金实不鸣；脉数主热，左弦主肝木偏旺，木火刑金则咳逆、寒热犹来。数而兼弦，说明热郁于内而肝气不舒，故仍守前法加减，清肺平肝以解寒热。", ["数", "弦"]], "17113": ["病机", "咳血较瘥而肺气不降，脉右涩数，涩为血行不畅、离络之血未净，数为余热未清；左弦细乃肝阴不足、木火内扰。苔滑、便清、脏腹痛，示痰湿内滞、气机不利，故宜降气化痰利便，防其复剧。", ["涩", "数", "弦", "细"]], "17114": ["病机", "湿邪上受始犯喉痹，脉弦数主湿热郁蒸、肝胆火旺；苔灰腻、痰黏为湿浊内蕴，便闭乃外寒束表、内热壅结。弦数相合，说明邪势鸱张、表里同病，故原文断为“非轻藐之症”，当清热化湿、通腑解表。", ["弦", "数"]], "17115": ["病机", "风湿外乘，头胀而痛、恶寒发热，是邪在卫表；脉寸浮滑，浮主表邪未解，滑主痰湿内蕴，寸部候上焦肺卫，故见咳逆。浮滑并见，说明风湿袭表而痰湿阻肺，宜开达肺气、轻清解表，使邪从表散。", ["浮", "滑"]], "17116": ["病机", "风热侵窍致两耳失聪，左脉细为少阳阴血不足、清窍失养，右弦滑乃风热痰浊上扰；呛咳苔白示肺气不宣、痰湿内停。细与弦滑并见，说明正虚邪扰、少阳经气不利，故以清少阳为主，兼宣肺化痰。", ["细", "弦", "滑"]], "17117": ["病机", "闺女腹痛、便滑、癸水不调、头疼，脉弦主肝气郁结、木旺克土；便滑为脾运不健，癸水不调乃冲任气血失和，头疼则肝阳上扰。弦脉独见，说明气机郁滞为病本，故宜和中调经，疏肝健脾以复冲任。", ["弦"]], "17118": ["病机", "闺女痛经中满、头疼，脉细涩苔白，细为血虚、涩为血行瘀滞，苔白示寒湿内阻；冲任气血不畅则经行腹痛，瘀阻气机则中满，血虚风扰则头疼。细涩相合，说明血虚兼瘀、寒凝胞宫，故宜活血疏风以通经止痛。", ["细", "涩"]], "17119": ["病机", "产后载余，冲任内损，腹痛有瘕，脉弦细，弦主气滞瘕聚、细主阴血亏虚；大便忽泻、形肉日削，是脾肾两伤、精血耗损之象。弦细并见，说明正虚而瘀滞未消，故原文断为“非轻藐之症”，当扶正消瘕兼顾。", ["弦", "细"]], "17120": ["病机", "脉滞细苔黄，为湿热内蕴之象。湿性黏滞，故脉滞；热邪伤阴，脉道不充，故脉细。湿热阻于肺卫，肺失宣降则咳逆；湿注下肢则跗酸；湿热下迫膀胱则小溲乍赤。苔黄为热征。此脉主湿热阻肺卫之病机，与咳逆、跗酸、溲赤相应。", ["滞", "细"]], "17121": ["主病", "脉虚为气血不足之征。癸水不调而见脉虚，乃血海空虚、气血亏少，不能充脉养身，故手足酸楚、步履不耐。虚脉主虚证，此段以脉虚统摄经水不调及肢体酸软，属血虚失养之病机，宜四物汤养血调经。", ["虚"]], "17122": ["病机", "脉涩为气滞血瘀、脉道不利之象。心惕如悬、脘闷，乃气机郁滞、心神不宁；癸来腰腹聊痛、苔厚腻，为湿浊内阻、气血不畅；倏寒汗彻，营卫失和。涩脉主气滞血瘀湿阻，防遂厥者，虑其气血逆乱。此脉与心惕、脘闷、痛经、寒热汗出相应。", ["涩"]], "17123": ["病机", "脉弦细，弦主气滞，细主血少。闺女经闭，腰痛，气滞中痞，乃肝郁气滞、血行不畅，冲任受阻而经闭；气滞中焦则痞满；腰为肾府，气血不通则痛。弦细脉示气滞血虚之病机，故宜活血调经为主，以通其滞。", ["弦", "细"]], "17124": ["病机", "脉涩寸口大，涩主血瘀气滞，寸口大主阳浮气逆。闺女晕眩心涎，乃风痰上扰；每经来腹中胀闷而痛，为气血瘀滞、经行不畅。涩脉示瘀滞，寸大示风阳上亢，故安胃熄风为主，兼调其经。此脉与晕眩、心涎、痛经相应。", ["涩", "大"]], "17125": ["病机", "两手皆涩，涩为气滞血瘀之脉。癸水腹痛肢酸，乃经行之际气血壅滞，不通则痛；肢酸为气血不荣。原文明言“此气阻经隧”，涩脉正合气阻血滞之机，故当养血理气为主，使经隧通利。", ["涩"]], "17126": ["病机", "脉弦右涩，弦主肝郁，涩主血滞。癸涩迟滞而痛，为经血不畅、气滞血瘀；带下如注，乃肝郁乘脾、湿浊下注。弦涩脉示肝郁血滞、湿浊内阻之病机，故宜养血平肝调经，肝平则经调带减。", ["弦", "涩"]], "17127": ["病机", "脉弦细，弦主气滞，细主血虚。经阻腹痛，倏寒忽热，腹中有瘕，乃肝郁气滞、血瘀成瘕，营卫失和而寒热。弦细脉示气滞血虚、瘀阻胞宫之病机，故宜加减逍遥散疏肝解郁、养血调经。", ["弦", "细"]], "17128": ["病机", "脉细微为气血亏虚之象，冲任内隙则血海不充，故脉道细而微。腰腹痛、带下、心惕，皆因冲任虚损、气血不能温养所致；癸涩迟滞、气滞中满，进一步说明血虚气滞、奇经失养。治在奇经，正合脉细微所主之虚损病机。", ["细", "微"]], "17129": ["主病", "脉细数主阴伤液耗，细为阴血不足，数为虚热内扰。阴液亏耗则舌红少津、根薄白；虚热消灼则渴饮善饥、溺多；肌肉失养则形肉日削。此脉象与消证之阴亏液耗病机相应，故宜存阴增液为主。", ["细", "数"]], "17130": ["预后", "脉弦数主肝郁化火、阴血暗耗。经停数月而脉弦数，说明气郁血滞、虚热内生；呛咳气促、曾失血，为木火刑金、络伤血溢之征；腰腹痛亦由气血郁滞所致。脉症合参，正气渐损而邪热未清，故宜防损怯之虑。", ["弦", "数"]], "17131": ["预后", "脉小数形怯，小为气血不足，数为虚热内扰，形怯则正气已衰。病延日久，呛咳气冲为肺阴亏虚、虚火上逆；腹中有瘕、癸涩不调，为气血瘀滞、冲任失调。脉症皆示正虚邪恋，故宜防损怯之虑。", ["小", "数"]], "17132": ["主病", "脉弦细主肝郁血虚。久咳经闭，咳久伤肺，肺失宣降则气机郁滞；经闭则血海不充，脉道失养，故弦细并见。腹痛脘闷为肝气犯胃、气滞中焦之象。脉症合参，症属重极，宜清肺胃利中，以调气机。", ["弦", "细"]], "17133": ["预后", "脉小数主虚热内扰、阴液不足。久嗽伤肺，苔黄少液为肺胃郁热、津液受灼；背掣癸涩，为气血亏虚、冲任失调、筋脉失养。脉症合参，正虚而邪热未清，故宜防损怯之虑。", ["小", "数"]], "17134": ["预后", "脉虚主气血不足，脘闷形怯为正气亏虚、脾胃运化无力。咳呕较减，说明邪势稍退；癸来涩少，为冲任血海不充。脉虚与形怯、经少相应，究属重极之症，仍遵前法加减，以扶正调理为要。", ["虚"]], "17135": ["预后", "脉涩主气滞血瘀、血行不畅。气逆稍缓而浮肿不减，说明气机虽稍顺而水湿仍停；脉涩经闭，为瘀血内阻、冲任不通。脉症合参，气血瘀滞与水湿互结，究属棘手重症，仍照前法加减以化瘀利水。", ["涩"]], "17136": ["病机", "脉弦滑，弦主肝郁气逆，滑主痰湿内蕴。晕眩肢酸为肝风挟痰上扰、筋脉失养；经停数月乃气滞痰阻、冲任不调；呛嗽气促、睡中汗彻，显系肝火犯肺、肺失清肃，迫津外泄。故以清肺敛液为主，兼调肝脾。", ["弦", "滑"]], "17137": ["病机", "脉涩主血少精亏、脉道不利，气口滑主痰热内蕴。带下腰疼、癸涩为肝肾不足、湿浊下注；潮热气冲呛咳、少寐，乃阴虚火旺、痰热扰肺及心神。故宜清肺凝神，兼养阴血。", ["涩", "滑"]], "17138": ["病机", "脉细微主气血阴阳俱虚。冲任内隙、癸涩迟滞为精血亏虚、冲任失养；带下腰痛乃肾虚湿注；心惕呛咳为肺肾两虚、心气不足。故用六味地黄丸法加减，滋肾填精、调补冲任。", ["微", "细"]], "17139": ["病机", "脉虚主营血不足、阳气亦弱。营虚胃痛乃中焦营亏、胃络失养；肢稍冷为阳虚不达四末；癸水不调系营血亏虚、冲任失调。故以当归桂枝汤加减，温营养血、和胃止痛。", ["虚"]], "17140": ["病机", "脉浮弦主外感风邪、内挟湿滞。暑风夹湿，寒热交作、汗彻不出，为表邪郁遏、湿阻肌腠；咳逆、腰疼肢酸乃风邪犯肺、湿滞经络。法当和解，防邪内陷化风成痉。", ["浮", "弦"]], "17141": ["病机", "脉弦虚主体气滞而血分不足。癸来腹痛联腰，乃肝郁气滞、血行不畅，冲任胞脉受阻；体气滞则弦，血虚则虚。故宜活血疏肝，使气畅血行，痛自止。", ["弦", "虚"]], "17142": ["病机", "两关皆弦，左关候肝，右关候脾胃，弦为肝气偏旺。肝逆犯胃则呕酸作吐，乘脾则作泻；苔白根微黄、脐下滞痛，示肝气挟寒湿滞于下焦。治厥阴阳明，即疏肝和胃、平木安土。", ["弦"]], "17143": ["病机", "脉虚数主气阴两虚、虚热内扰。咳嗽未除、气冲脘闷，为肺虚气逆、痰阻中焦；癸来涩少乃阴血不足、冲任亏虚。虚数之脉示正虚而有虚火，故宜润肺止嗽化痰，兼养阴血。", ["虚", "数"]], "17144": ["预后", "久嗽不已、喉有血腥，阴液已伤，虚火内灼；脉小数者，阴亏而热不显，潮热、癸水不调皆阴虚内热之征。脉小为正气不足，数为热象，故原文断为“宜防损怯之虑”，提示久嗽阴损有转虚劳之虞。", ["小", "数"]], "17145": ["病机", "湿热不退，苔滑呛咳，神倦脉濡，肢酸溺赤胃钝，皆湿热内蕴、气机不宣之象。脉濡主湿，湿性黏滞，故湿热缠绵不退；湿阻中焦则胃钝神倦，湿热下注则溺赤肢酸。原文以“清气利湿化痰”为治，正合濡脉主湿之机。", ["濡"]], "17146": ["病机", "肝逆稍平而脉来细涩，足跗犹酸，是肝气虽减而阴血未复。细为血少，涩为血行不畅，阴血亏虚不能濡养筋脉，故足跗酸软。原文以“养血调经为妥”立法，说明细涩之脉主血虚而兼瘀滞，经血失调之病机。", ["细", "涩"]], "17147": ["病机", "头晕心悸而脉虚右弦，虚为气血不足，弦主肝风。右关见弦，是肝风犯胃、胃气不和之象；癸水不调亦由肝风扰动、气血失和所致。原文明言“此肝风犯胃”，故以安胃熄风、佐理气调经为治，脉虚弦正合此病机。", ["虚", "弦"]], "17148": ["病机", "血虚生风，脉虚癸涩，身发肿块瘙痒。虚为血不足，涩为血行滞涩，血虚不能濡养肌肤，风燥内生，故见肿块瘙痒。原文以四物汤加减养血，说明虚涩之脉主血虚风燥、经水涩少之病机，而非外感风邪。", ["虚", "涩"]], "17149": ["病机", "咳嗽多痰，脉弦数，潮热胸次痛，癸水适至。弦主气郁痰阻，数主热，痰热壅肺则咳嗽多痰、胸次作痛；潮热为热象之征。原文以“清肺利络化痰”为治，脉弦数正说明痰热内郁、肺络不和之病机。", ["弦", "数"]], "17150": ["病机", "咳嗽未除，脉虚细右弦，腰疼肌体麻木，心惕，癸水月余不至。虚细为阴血不足，右弦为肝气偏旺；阴亏不能养筋则麻木腰疼，血虚不能养心则心惕，冲任失充则经闭。原文以六味地黄丸加减，示虚细弦主肝肾阴亏、肝阳偏亢之病机。", ["虚", "细", "弦"]], "17151": ["预后", "呛咳音嘶，脉虚数便泻，形怯经闭。虚为正气亏弱，数为虚热内扰；久咳音嘶是肺阴耗伤，便泻为脾土亦弱，形怯经闭则气血生化无源。原文断为“究非轻藐之症”，说明虚数之脉主正虚邪恋、肺脾两伤，预后堪虑。", ["虚", "数"]], "17152": ["病机", "疟疾久累，正气已伤而邪热未清，脉弦主肝胆气郁、疟邪伏于少阳，数主热盛。弦数并见，说明久疟后邪热内郁、阴液受灼，故见呛咳、癸来涩少、盗汗、苔微黄，皆阴虚内热之象，治宜扶羸汤加减以扶正清邪。", ["弦", "数"]], "17153": ["预后", "胃纳稍振而呛咳便泻不已，脉弦细，弦为肝郁木旺，细为阴血亏少。木旺克土则便泻不止，阴亏肺燥则呛咳，苔滑经闭示痰湿内阻、冲任不充。脉症相参，正虚邪恋、脾肺两伤，故断为「重险之症」，预后堪忧。", ["弦", "细"]], "17154": ["预后", "腹痛较缓，脉仍弦细，弦主肝郁气滞，细主阴血不足。经闭呛咳并见，乃肝郁化火刑金、阴血亏虚之候。腹痛虽缓而脉象未和，说明病根未除，正气日削，故原文告诫「宜防损怯之虑」，即防其渐成虚损劳怯之证。", ["弦", "细"]], "17155": ["预后", "上咳嗽、下便泻、癸水不调，脉弦细。弦为肝木偏旺，细为阴血亏虚。木旺刑金则咳，克脾则泻，阴亏冲任失养则癸水不调。上咳下泻并见，脾肺同病、虚实夹杂，脉细示正虚难复，故原文断为「最重之症」，预后不良。", ["弦", "细"]], "17156": ["病机", "右脉浮滑，浮主风邪在表，滑主痰涎内盛。头疼咳逆、寒热不清为风邪袭肺，心涎脘闷、苔黄厚、颊车紧为痰热内蕴、经络不利，经停月余、手足麻木亦痰阻血滞之征。脉症合参，属风痰壅肺、肺失清肃，故宜清肺疏风。", ["浮", "滑"]], "17157": ["病机", "脉沉涩，沉主气机内郁、病在里，涩主血行不畅、气滞血瘀。癸水先后不一示冲任失调，腹满气冲呛咳乃气逆上冲、肺失肃降。沉涩相合，说明气滞血涩、肺气不降，故原文以清肺降气和中为治，使气行则血行、逆降则咳平。", ["沉", "涩"]], "17158": ["病机", "胸胁刺痛已减而脉寸弦滑，寸候上焦，弦主肝郁气滞、络脉不和，滑主痰浊内蕴。胸胁刺痛减而未除，舌厚胃馁呛咳，说明肝郁痰阻、肺胃不和之病机仍在，故原文「仍遵前法」，继续清气和络以化痰降逆。", ["弦", "滑"]], "17159": ["病机", "暑风夹湿，微热畏风、汗出不休，脉虚而手尖冷，虚主正气不足、卫阳不固。暑湿伤气耗津，卫外失固则汗出畏风，阳气不达四末则手尖冷，咳逆舌厚嫩黄为湿郁化热。脉虚与汗出不休相应，示气阴两伤，故用瓜蒌桂枝汤加减。", ["虚"]], "17160": ["病机", "脉两手浮弦，浮为邪在表，弦为少阳主脉，结合寒热间日而作、头胀痛、咳逆胸闷，说明邪客少阳，枢机不利，正邪分争，故见寒热交作；少阳经气壅滞，故头胀痛、胸闷咳逆。苔白厚为兼湿浊。脉症合参，病机为邪在少阳，治宜和解。", ["浮", "弦"]], "17161": ["病机", "脉弦细，弦主肝病，细主阴血不足。咳动肺而胸胁刺痛，乃肝络不和、气滞血瘀之象；苔微黄提示郁热。弦细之脉见于咳而胸胁刺痛，说明肝肺同病，阴血暗耗，肝火犯肺，灼伤血络，故曰“尤防血溢”，当警惕咳血之变。", ["弦", "细"]], "17162": ["病机", "脉左细右微，细为阴液亏耗，微为阳气不足。咳嗽不已、舌红口干渴饮，显系阴液耗伤；动溺犹多、大便始结继溏，乃湿热未清、脾运不健。左细右微反映阴亏于下、气弱于中，湿热尚存而阴液已伤，故仍遵前法加减，标本兼顾。", ["细", "微"]], "17163": ["病机", "脉细涩，细主阴血不足，涩主血行不畅。心惕已减，说明心神不宁有所缓解，但癸水不及期而至，结合苔微白，乃阴血亏虚、冲任失调之候。细涩脉提示血虚而兼瘀滞，心失所养故惕，血海不充故经期提前，仍照前法加减以养血调经。", ["细", "涩"]], "17164": ["病机", "脉虚细，虚为阳气不足，细为阴血亏少。腰酸带下、苔白便滑，乃脾肾两虚、湿浊下注之象；癸水不调，冲任失养。虚细脉主气血俱虚，脾虚则便滑，肾虚则腰酸带下，冲任不充则经水失调，故宜青娥丸法加减以补益脾肾、调摄冲任。", ["虚", "细"]], "17165": ["病机", "脉虚，主气血不足。头痛较瘥、脘中稍和，说明前证有所缓解，但腹痛心惕仍在，且癸水不调，乃心脾两虚、气血不足之候。虚脉提示正气亏虚，心失所养故惕，脾运不健故腹痛，冲任不充故经水不调，宜补心和中以复气血。", ["虚"]], "17166": ["病机", "脉滞寸口短，滞为气机不畅，短为气郁不伸。内伤夹外感，头痛心涎脘闷，癸水不调，说明正气内虚、气机郁滞，复感外邪，表里同病。寸口脉短滞反映气机壅遏，外邪与内伤相合，故宜治标为先，先解外感、畅气机，再图调经。", ["滞", "短"]], "17167": ["病机", "脉沉涩，沉主里，涩主气滞血瘀。癸水趱迟、气冲脘闷欲呕，苔白如粉，乃寒湿内阻、气机逆乱之候。沉涩脉说明病在里，气血运行不畅，寒湿困阻中焦，胃气上逆故欲呕，冲任受阻故经水迟延，宜顺气和中以化寒湿、调气机。", ["沉", "涩"]], "17168": ["病机", "寸脉滑数，滑主痰壅，数主热盛，痰热交阻于肺，肺失肃降，故咳逆痰壅。癸水适至不多，苔根厚，为痰热内蕴、气机不畅之征。脉症相合，病机为痰热壅肺，故宜清热消痰。", ["滑", "数"]], "17169": ["病机", "左脉弦，弦主肝郁气滞。前药已效，脘胀闷减，但脉仍弦，癸不及期，说明肝气未疏、血海失调。脉弦与脘胀、经期异常相应，病机为肝郁气滞，故仍照前法加减以疏肝调经。", ["弦"]], "17170": ["病机", "脉弦气逆，弦为肝脉，气逆乃肝气上逆。肝逆乘中，当脘胀闷，癸不及期，皆肝气横逆、脾胃受克之象。脉弦与气逆、胀闷相应，病机为肝气犯中，故宜防肿胀，治当疏肝降逆。", ["弦"]], "17171": ["病机", "脉滑数，滑主痰湿，数主热。血后心惕，苔白而干，经停三月，脘闷，为血去阴伤、痰热内扰之候。脉滑数与心惕、脘闷相应，病机为胃阴不足、痰热中阻，故宜养胃和中。", ["滑", "数"]], "17172": ["病机", "脉数右寸特大，数主热盛，右寸特大主肺气壅盛。经停吐血，苔微黄，心惕脘闷，为气火上逆、迫血妄行之象。脉数与吐血、心惕相应，病机为肺胃热盛、气逆血溢，故宜降气凉血。", ["数", "大"]], "17173": ["病机", "脉虚细，虚主气弱，细主血少。癸水涩少不调，带下，便泻不已，中痞气滞，为脾虚气弱、血海不充之候。脉虚细与经少、泄泻相应，病机为脾虚湿盛、气血两亏，故宜和中止泻为主。", ["虚", "细"]], "17174": ["病机", "脉涩，涩主血少气滞。癸涩迟滞，腰疼，带下便泻中痞，为气血运行不畅、脾湿下注之象。脉涩与经迟、腰疼相应，病机为气滞血瘀、湿阻中焦，故宜理气和中以调经止带。", ["涩"]], "17175": ["病机", "脉沉涩，沉主里，涩主血滞。便泻腹痛悉减，癸涩带下，为里虚湿滞、血行不畅之候。脉沉涩与经涩、带下相应，病机为脾虚湿阻、气血不和，故宜和中调经为妥。", ["沉", "涩"]], "17176": ["病机", "脉细为血虚不足，涩为气滞血行不畅，故见癸来腹痛作泻。血虚气滞，冲任不畅则经行腹痛；气不化水、脾运失司则作泻。脉细涩与心惕并见，示血虚不能养心。原文以五苓散主治，重在化气利水以止泻，兼调气血。", ["细", "涩"]], "17177": ["兼症", "右脉弦滑，弦主气滞、滑主痰湿内蕴。腹痛便利不减、苔黄呕恶，为湿热积滞中焦；月事过期不至，因气滞血阻、冲任不畅。右脉候脾胃，弦滑示中焦湿滞化热。原文防其成痢，故仍照前法加减，兼顾调经与清化湿热。", ["弦", "滑"]], "17178": ["病机", "脉虚细为气血不足，便滑示脾虚失运、湿浊下注。癸来涩滞因血少气弱、冲任不充；脘闷脐下不爽，为脾虚气滞、升降失司。脉症合参，病机在脾胃虚弱、气血两亏兼气滞，故宜养胃和中，佐理气下行，使中焦健运而经自调。", ["虚", "细", "滑"]], "17179": ["病机", "脉沉主里、主水湿内停，便泻、中痞肠鸣皆中焦湿盛、脾运失职之象。癸涩迟滞因湿阻气机、血行不畅。沉脉与便泻肠鸣相应，说明病在里、在脾胃，水湿内困。原文用胃苓汤加减，正是燥湿健脾、分利水谷以调经止泻。", ["沉"]], "17180": ["病机", "脉涩主血少气滞，右沉弦示中焦气滞、湿阻不化。便泻腹痛稍减而苔仍黄厚，为湿热未尽；癸涩二月不至，因气滞血瘀、冲任受阻。中痞气滞为病机关键，涩脉与经闭相应，沉弦与中痞相应。故仍守前法加减，理气化湿以通经。", ["涩", "沉", "弦"]], "17181": ["病机", "脉弦主气滞，左涩主血少而行不畅。大便不爽为气机郁滞、传导失司；癸水已至不多，因血虚气滞、冲任不畅；头晕脘闷，为气滞湿阻、清阳不升。弦涩并见，示气血郁滞之病机，故仍照前法加减，理气和血以调经。", ["弦", "涩"]], "17182": ["病机", "脉细涩为血虚气滞之象。癸水先后下一，因气血不调、冲任失养；腹痛气滞，为血虚而气行不畅；大便滑泻、胃钝带下，示脾虚湿盛、运化失职。细涩与腹痛气滞、便滑带下相应，病机重在血虚气滞兼脾湿，故宜和中为妥，健运中焦以调气血。", ["细", "涩"]], "17183": ["病机", "脉小数主热邪内蕴、正气略伤。潮热不清、苔黄口渴，为热盛伤津；大便自利、瘄疹已现，示热邪外透而里热未清；癸水适至，热扰冲任。神识恍惚，为热扰心神。小数脉与潮热、口渴、神识恍惚相应，病机属热邪充斥表里，故宜清热祛邪。", ["小", "数"]], "17184": ["主病", "脉来弦数为少阳郁热、肝脾不和之象。寒热日作，邪在少阳半表半里，故脉弦；数则内有郁热。心涎便利示痰湿内扰，癸水适至说明经期适逢其会，气血下注，邪热易与血相结。弦数并见，主寒热往来而兼里热，故宜柴平汤加减和解少阳、平调肝脾。", ["弦", "数"]], "17185": ["病机", "脉沉弦右涩滞，沉主里、弦主气郁、涩滞主湿阻血行不畅。原文言湿郁气阻、遍体浮肿，正合沉弦涩之机：湿邪郁遏气机，水湿泛溢肌肤则浮肿；右脉涩滞，右主脾肺，脾运失司、水湿内停。癸涩迟滞示经行不畅，中痞防胀乃气阻中焦、有胀满之势，故当化湿行气。", ["沉", "弦", "涩"]], "17186": ["病机", "脉弦为肝木偏横之象，原文直言肝木偏横。湿热发黄本有湿郁，而弦脉示肝气横逆、疏泄失职，木旺克土，脾运受困，水湿不化，故腹臌跗浮。癸趱迟为经行先期而迟滞，示肝郁血滞。脉弦而见腹臌跗浮，属肝木乘脾、湿热壅盛之重极证，故宜鸡金散加减化湿消臌。", ["弦"]], "17187": ["病机", "脉濡细为湿邪内蕴、气血不足之象。濡主湿、细主虚，风湿化疟则湿邪留恋、正气已伤。苔心灰示湿浊内阻中焦，经阻腹满为湿阻气机、血行不畅，头面跗浮乃湿溢肌肤。濡细之脉说明正虚湿盛，疟邪与湿相合，故宜防其化胀，治当化湿扶正兼顾。", ["濡", "细"]], "17188": ["病机", "脉细滞，细为气血不足，滞为湿阻气机、血行不畅。原文脾泄化肿，脾虚失运则泄泻，水湿不化泛溢则肿；经阻跗浮示湿阻冲任、血行不利，水湿下注足跗。细滞之脉正合脾虚湿盛、气血两亏之机，故宜利中分消，健脾利湿以消肿胀。", ["细", "滞"]], "17189": ["病机", "脉弦中满，弦主肝郁气滞，中满为气机壅塞于中焦。原文夹气夹食化肿，气食交阻、脾运失司，水湿不化而肿；癸水沥示经行淋漓不畅，肝郁血滞。弦脉见中满肿胀，属气食湿浊交阻之重险证，故当和营卫为主，调畅气血以消胀满。", ["弦"]], "17190": ["兼症", "右脉细左弦，左弦为肝阳偏亢、肝气横逆，右细为脾胃虚弱、气血不足。肝阳犯胃则脘痛彻背、呕酸作吐；苔白痰气交阻，肢尖不煦乃阳气不达四末，恐有厥逆之变。左弦右细正示肝强脾弱、厥阴阳明同病，故宜厥阴阳明同治，佐祛瘀化痰以平肝和胃。", ["细", "弦"]], "17191": ["病机", "脉两手皆弦，弦为肝郁气滞之象。苔白示寒湿内蕴，肝块作痛乃肝气郁结、血瘀成块；癸涩已闭为肝郁血滞、经闭不行；大便忽泻、倏热忽寒示肝木乘脾、营卫不和。两手皆弦说明肝郁遍及左右，气血壅滞，故宜疏肝和中以调畅气机。", ["弦"]], "17192": ["病机", "脉弦为肝气偏旺之象，肝气上逆射肺，肺失肃降则呛咳；潮热乃肝郁化热、少阳枢机不利所致；经阻、喉有血腥，皆肝逆犯肺、血随气逆之征。故脉弦在此主肝逆射肺之病机，与呛咳、潮热、经阻、喉血腥相应。", ["弦"]], "17193": ["病机", "脉涩主血虚滞涩，左弦细为肝血不足而木旺，癸水涩迟滞示冲任血少。血虚不能荣养则腰酸，肝木乘脾则腹胀，血不养心则心惕，带下亦由血虚湿滞。故脉涩左弦细主血虚木旺之病机，与腰酸、腹胀、心惕、带下相应。", ["涩", "弦", "细"]], "17194": ["病机", "脉沉弦为肝气郁逆于里，癸涩示冲任气血滞涩。肝逆上冲，气机壅塞则脘痛；背为肝俞所布，气逆则背掣。故脉沉弦癸涩主肝逆上冲、厥阴疏泄失常之病机，与脘痛、背掣相应，治宜疏泄厥阴。", ["沉", "弦", "涩"]], "17195": ["病机", "脉虚为肝血不足、正气亏虚，癸涩示冲任血少滞涩。肝虚不能上荣则晕眩目暗，肝木犯胃则食入欲呕。故脉虚癸涩主肝虚血少之病机，与晕眩、目暗、食入欲呕相应，治宜柔肝养血。", ["虚", "涩"]], "17196": ["病机", "脉细涩为血虚气滞、寒凝不通。腹痛有形联腰，乃血滞胞络、寒凝经脉；肢冷为阳气不达，呕渴为肝胃不和、津不上承；癸水适来而脉细涩，示冲任滞涩。故脉细涩主血虚寒滞之病机，症重防厥，与腹痛、肢冷、呕渴相应。", ["细", "涩"]], "17197": ["病机", "脉弦为肝木偏旺，舌尖红示心火偏亢。木克土则脾运失职，便泻心涎；肝气郁结、血瘀成瘕则腹中有瘕、经闭。故脉弦主肝木克土、气滞血瘀之病机，与便泻、心涎、腹中瘕、经闭相应，治以猪苓汤加减。", ["弦"]], "17198": ["病机", "脉弦滞即弦而涩，为肝气郁逆、气血壅滞之象。肝逆攻冲则作痛，气逆犯胃则呕恶欲厥；经阻乃气滞血瘀、冲任不通。症属重极，脉弦滞主厥阴肝逆、气血壅滞之病机，与攻冲作痛、呕恶欲厥、经阻相应。", ["弦", "涩"]], "17199": ["病机", "脉弦为肝气偏旺，微热示肝郁化热之轻。肝逆犯胃，胃失和降则腹痛作吐；癸水趱迟为肝气郁滞、冲任不调。故脉弦主肝逆犯胃之病机，与腹痛、作吐、微热、癸水趱迟相应，治宜厥阴阳明同治。", ["弦"]], "17200": ["病机", "脉弦细，弦为肝木亢盛，细为脾土不足，木克土化泻，中焦窒格，气机升降受阻。经停防胀，乃肝郁脾虚、血海不充而气滞湿阻，故宜利中分消为治，以疏肝健脾、行气化湿。", ["弦", "细"]], "17201": ["病机", "脉涩脘格，涩主气滞血瘀、痰湿内阻，木克土化泻，中焦痞塞，心涎欲呕，癸涩不调。此肝郁犯脾、痰湿中阻、胃气上逆之机，故宜泻心汤加减以辛开苦降、调中泻热。", ["涩"]], "17202": ["兼症", "左脉弦细，弦为肝郁，细为血少，苔白呛咳气逆，头疼倏热乍寒，腹左有瘕，经停四月，胃钝防肿胀。此肝气郁结、血虚夹瘕、木火刑金之候，故见咳逆寒热，防其肿胀。", ["弦", "细"]], "17203": ["病机", "脉弦而涩，弦主肝郁，涩主气滞湿阻，木克土化泻，舌滑脘闷，带下癸涩。此肝郁脾虚、湿浊下注、冲任不畅之机，故宜顺气和中，以调肝脾、化湿浊。", ["弦", "涩"]], "17204": ["病机", "脉细涩，细为阴血不足，涩为血脉瘀滞，任脉为病，腹痛有瘕，癸水涩少，苔心黄，肢木心烦。此阴血亏虚、瘀阻任脉、郁热内扰之候，宜治防厥，候正以观变。", ["细", "涩"]], "17205": ["病机", "脉沉弦，沉主里、弦主肝，肝块作痛，气滞为满，癸水先后不一，大便忽泻。此肝郁气滞、木横克土、疏泄失常之机，故宜疏肝和中，以调气机、和脾胃。", ["沉", "弦"]], "17206": ["病机", "脉弦苔厚腻，弦为肝逆，厚腻苔主痰湿内蕴，肝逆中脘闷窒，癸水不调，心惕胃钝欲呕。此肝气上逆、痰湿中阻、胃失和降之候，当和肝胃为主，以平肝降逆、化痰和胃。", ["弦"]], "17207": ["病机", "苔黄脉涩左弦，涩主气滞血瘀，左弦为肝郁，脘腹联痛呕恶，此厥阴顺乘阳明，癸水趱迟。乃肝郁化热、横逆犯胃、气血不畅之机，宜泻心汤加减以清肝泻热、和胃降逆。", ["涩", "弦"]], "17208": ["病机", "脉细涩为气血两亏、脉道不利之象。肝逆未平则气机横逆，中满气滞则升降失司，气血运行涩滞，故脉细而涩。细主血少，涩主气滞血瘀，与腹痛经停相应，示肝郁脾困、气血瘀阻，久则水湿不化，故防肿胀。", ["细", "涩"]], "17209": ["病机", "脉沉涩主里、主气滞血瘀。木克土则脾运失职，便泻中痞；气机壅滞，血行不畅，故脉沉涩。面跗浮为水湿泛溢，经阻为血瘀不行，皆由肝郁乘脾、水湿内停所致，故宜治以防胀。", ["沉", "涩"]], "17210": ["病机", "右脉弦为木克土之象，弦主肝旺。肝气横逆犯脾，脾失健运，故中痞气滞腹痛、化泻；舌红经阻示肝郁化热、血行不畅。脉右弦独见于关部，正合肝木乘土病机，故宜养胃和中平肝。", ["弦"]], "17211": ["主病", "脉浮弦主外感风邪、痰饮内停。浮为邪在表，弦主痰饮、主痛。风邪上扰清窍则头疼不已，犯肺则呛咳多痰；苔微黄、恶风微寒为表邪未解、渐有化热之势。脉症合参，属风痰上扰、表邪未净，故宜解表消痰。", ["浮", "弦"]], "17212": ["主病", "脉浮数主表热未解。浮为邪在肌表，数为热盛。感邪未解，正邪交争，故身热乍寒；苔黄滑示热邪渐入气分、兼有痰湿。脉浮数与此相应，说明表邪未罢而里热已萌，故宜清解以防病剧。", ["浮", "数"]], "17213": ["病机", "脉浮滑主痰热内蕴、邪在肺卫。浮为邪犯上焦，滑主痰湿。秋感化燥，燥邪夹痰，故呕恶发热、呛咳；苔黄燥为燥热伤津之征。脉浮滑与苔黄燥并见，示痰热壅肺、燥邪未清，症势非轻，故防昏蒙变幻。", ["浮", "滑"]], "17214": ["预后", "脉动为热盛气逆、阴阳相搏之象，多见于热病极期。热犹不解，脉动苔黄口燥，示热邪炽盛、津液受灼；便痢赤色为热伤血络、下迫大肠。热毒内陷，易引动肝风，故还防痉厥，候正以观变。", ["动"]], "17215": ["病机", "脉弦濡主湿阻气机、肺卫失宣。弦为气机郁滞，濡为湿邪内蕴。湿阻肺卫，宣降失常，故咳逆、寒热交作；苔白根微黄示湿郁渐有化热之势，腹中气机不和为湿困中焦。脉症合参，属湿邪弥漫三焦，故宜桂苓甘露饮加减。", ["弦", "濡"]], "17216": ["主病", "脉弦濡，弦主湿阻气滞、经气不畅，濡主湿邪偏盛、阳气不伸。脚气酸痛乃湿邪下注、经络壅滞所致；苔滑白心灰，更示湿浊内蕴、阳气不振。脉症相合，故以祛风利湿为主，弦濡正是湿滞络脉之征。", ["弦", "濡"]], "17217": ["主病", "脉浮数，浮主邪在表，数主热，为外感风热之象。秋感发热乍寒、头胀而疼，乃风热袭表、经气不利；苔黄亦示里已有热。脉浮数应表热，故宜辛凉轻解，使邪从表散，防其入里。", ["浮", "数"]], "17218": ["病机", "脉濡细，濡主湿，细主气弱，合示暑湿伤气、湿阻气机。苔滑白为湿浊内停；腹痛泻痢溺少，乃湿困中焦、清浊不分、水道不利。脉症相参，病机在暑湿伤气、阳明湿滞，故宜清阳明经为主。", ["濡", "细"]], "17219": ["病机", "脉弦濡，弦主气滞湿阻，濡主湿盛，合示湿热内著、气机壅滞。稚孩身微热、腹痛坚满、大便忽泻，乃湿热积滞中焦、升降失司。脉弦濡与苔白、腹痛坚满相应，故用太安丸法加减以化滞和中。", ["弦", "濡"]], "17220": ["主病", "脉浮数，浮为邪在表，数为热，主外感风热。发热、头胀痛、苔滑微黄、脘闷肢楚，皆风热袭表、经气不畅、湿阻气机之象。脉浮数应表热未解，故宜达表为主，使邪从外解，防其传里增剧。", ["浮", "数"]], "17221": ["兼症", "脉濡细，濡主湿浊，细主气弱，示湿浊内阻、正气不足。头晕目暗、腹痛吐利、胃钝带下，乃湿浊中阻、清阳不升、脾胃失运，夹杂痧秽更伤气机。苔黄示湿中有热。脉濡细与诸症相应，故先治标以化湿浊。", ["濡", "细"]], "17222": ["病机", "脉弦主少阳枢机不利、气机郁滞。痰疟二期寒多热少，苔白，乃邪踞少阳、痰湿内阻，正邪交争于半表半里。脉弦与寒多热少、苔白相应，说明邪在少阳，故用小柴胡汤加减以和解枢机、化痰截疟。", ["弦"]], "17223": ["病机", "两脉皆弦，弦主肝郁气滞、经气不畅。闺女腹痛气滞、苔白、癸水不调，乃肝气郁结、疏泄失职、冲任不调所致。脉弦与腹痛气滞、月经不调相应，说明病机在肝郁气滞，故宜疏肝和中以调气机。", ["弦"]], "17224": ["主病", "脉濡滑主脾虚湿盛，左弦为土虚木乘之象。女孩脾疳化肿，苔白便泻、口渴、腹大溺少，皆脾不运湿、水湿泛溢之候。濡为湿困，滑为水聚，弦则肝木犯脾，故知疳积日久化肿，属虚实夹杂、本虚标实之证，原文谓“非轻藐之症”，正言其病机深重。", ["濡", "滑", "弦"]], "17225": ["兼症", "左脉涩为血少气滞，右弦数为肝胃郁热。苔微黄、脘腹胀闷，是气机壅滞；癸水早期、咳痰，示血分不调兼痰热上扰。涩主经血不畅，弦数主郁热内迫，故治宜和中调经，以疏肝理气、清热和胃为法，脉症相参，病在气血不调而非单纯外感。", ["涩", "弦", "数"]], "17226": ["病机", "左脉濡为湿邪伤中、气血不充之象。风湿相搏，寒热如疟，苔白根微黄，腰痛身痛头目皆疼，神识皆愦，是风湿之邪痹阻经络、上蒙清窍。濡脉主湿主虚，湿性黏滞，故寒热缠绵、身痛不去。原文“宜防柔痉”，正虑风湿化燥动风，筋脉失养而致痉，病机在湿阻络脉、营卫不和。", ["濡"]], "17227": ["病机", "脉沉弦主气机郁滞、痰饮内结。咳痰稠白、苔厚微黄、胃钝食入脘闷，是痰浊壅阻肺胃、气失宣降。沉为病在里，弦为气郁饮聚，痰稠苔厚示湿郁化热。肺胃同病，故治宜清肺胃和中，以化痰降气、和胃畅中为要，脉沉弦正合内伤痰湿之机。", ["沉", "弦"]], "17228": ["主病", "脉弦数为热郁少阳、里实壅结之象。苔黄厚、呕渴发热、脘格腹痛不便，是伏暑内发、热结阳明。弦主少阳枢机不利，数主热盛，呕渴示热迫胃津，腹痛不便示腑气不通。原文断为伏暑，用陷胸承气汤加减，防厥者，虑热盛动风、内陷心包，病机在暑热内结、腑实不通。", ["弦", "数"]], "17229": ["病机", "脉搏沉数细弱，沉为病在里，数为有热，细弱为阴血不足。目痛不红不肿、无翳障，惟黑珠起红一点，是阴虚血热郁于肝脏，非实火外障。前用黄连山栀等寒凉不效，正因虚火非实火可折。沉数细弱四字，明示阴虚内热之本质，故以杞菊地黄汤滋阴凉血而效。", ["沉", "数", "细", "弱"]], "17230": ["病机", "右寸关脉坚凝而滑，几乎搏指。滑为痰象，坚凝为痰结，见于寸关之间，知顽痰结于肺胃之管。肺为清道，胃为浊道，两道为痰所壅，故咳甚则晕绝。廿余年喘咳，前医皆作阴虚滋补，不知痰结为患。坚滑并见，正痰浊胶固、壅塞气道之明证，非虚损可比。", ["坚", "滑"]], "17231": ["病机", "脉必沉数，沉为热郁于里，数为热盛。十三岁女孩发热身面皆赤，无头痛、无腹痛吐泻、无扪之炙手、无烦渴出汗，则非瘟疫、非中暑、非脾郁、非实火。午后转甚、眼黑耳鸣、口干咽痛，是阴虚内热、虚火上炎之候。沉数之脉，正合阴虚阳浮、热郁于内之病机，故诸般清散攻下皆不效。", ["沉", "数"]], "17232": ["病机", "原文“提腕诊脉，无一丝可见；按太奚，则沸如涌泉，心头突突乱动”，脉伏而内沸，乃红痧疫毒闭遏，邪热内陷，气血壅滞，脉道不通，故外候无脉而内实沸腾。主红痧危症，症见四肢椎床、昏不知人，为毒邪内闭、神明受扰之候。", []], "17233": ["病机", "原文“六脉微弱，右关尤甚，右尺脉细如丝”，脉微弱主气虚，右关尤甚则脾虚不能转运，右尺细如丝为下焦气弱。脾虚中气不摄，故大便不通，非实热肠燥，乃“塞因塞用”之证，主脾虚不运之便秘。", ["微", "弱", "细"]], "17234": ["病机", "原文“六脉缓大，惟右关坚欲搏指”，缓大为中气不足而湿痰内盛，右关坚搏指为胃腑实积。体肥嗜食，风邪中府，痰热内闭，故口不能言、四肢不运、胸腹满闭，主邪风中府之实证，非续命汤所宜。", ["缓", "大", "坚"]], "17235": ["病机", "原文“俱微弱沉细，然至数匀称，惟右关独大，按之搏指”，微弱沉细为气血虚衰，右关独大搏指为食积内停。因食积致痢，误下伤正，积滞未去而正气已馁，故主虚实夹杂之食积痢疾，症见胸满腹胀、委顿不起。", ["微", "弱", "沉", "细"]], "17236": ["病机", "原文“左寸独虚，右三部俱滑而缓，并见弦象”，左寸虚为劳心过度，右滑缓弦为脾湿停痰、肝木乘脾。脾虚生痰，痰阻清阳，故头晕呕逆旋转欲跌，身体重困，主脾湿痰晕之病机。", ["虚", "滑", "缓", "弦"]], "17237": ["病机", "原文“脉浮而弱，而津津有汗出，而神气清明，语言便利”，浮为风邪在表，弱为正气不足。肩臂中风而痛，风在皮肤腠理，误用大秦艽汤固补，致痛增。脉浮弱主风邪袭表、营卫不和之臂痛，病极微末。", ["浮", "弱"]], "17238": ["预后", "原文未识脉名，述脾劳病“面目四肢俱浮肿，而烦满益不堪”，断为“脾绝矣”，并谓“肝木克脾土，促春必难过”。脾虚日久，痰嗽喘满，运化失职，水湿泛溢，至春木旺克土，故主预后不良，属死候。", []], "17239": ["病机", "原文“六部皆沉细迟微，右关更不三至”，沉细迟微为阳气虚衰、中气大馁，右关不三至为脾胃虚寒尤甚。疟疾屡用草果、常山劫药，克伐中气，致满腹虚寒，主疟病误治、中气衰败之虚寒证，非再作疟治。", ["沉", "细", "迟", "微"]], "17240": ["病机", "右脉寸关滑而泉涌，滑主痰湿内盛。原文谓“酒肉内薰，风寒外搏，且晚间煤火，渐而生痰”，说明膏粱厚味与煤烟之毒酿湿生痰，痰浊壅于中上二焦，故脉滑如泉涌；痰阻胸膈则烦闷欲吐，痰扰心神则心头突突动，风寒外束则颤汗转侧。脉证合参，病机为痰浊内蕴兼风寒外搏。", ["滑"]], "17241": ["其他", "本段未载具体脉象，仅言“病症脉象与莲舫无少区别”，即小园之脉亦当寸关滑而泉涌。原文以兄弟同病、同药同愈，说明二人同因酒肉煤火酿痰、风寒外搏而病，脉象相类，故治法一致。此段重在印证前案脉证与疗效，非另立脉象主病，故脉象要素从缺。", []], "17242": ["病机", "六脉浮濡，按之反不见。浮主邪在表，濡主湿、主气虚，浮濡相合为暑湿伤中之象。原文谓“此中暑阳邪也”，伶人盛暑演剧、身体束缚、旋舞过久，暑热内逼，气机逆乱，故大吐、腹中绞痛、昏不知人；汗出如油、气息促迫，为暑邪耗气伤津。脉浮濡按之不见，正合暑湿蒙蔽、阳气不伸之机。", ["浮", "濡"]], "17243": ["病机", "脉细数而有力，细主阴血不足，数主热，有力为实热内蕴。原文谓“阴亏血热”“鸦片最燥肺，肺主气，气燥而血亦不润”，说明素体阴亏、痔疾血热，又误用桂附温补，助火灼阴，故脉细数有力；热扰则烦躁，阴亏肠燥则痔痛增剧，腹膨如鼓为温补壅滞之变。脉证合参，病机为阴亏血热兼误补助火。", ["细", "数"]], "17244": ["病机", "左关弦滑如涌，且有坚象。左关候肝，弦主肝郁气滞，滑主痰血内壅，坚象示郁结日久、气血凝滞。原文谓“此肝郁也”，因暴怒伤肝，肝气横逆，血随气逆则呕血色紫黯，气滞络阻则胁间时时刺痛。脉弦滑而坚，正合肝郁化火、气滞血瘀之病机，故以解郁舒肝、养血平肝取效。", ["弦", "滑", "坚"]], "17245": ["病机", "六脉浮数，浮主邪在表分，数主热盛。原文载校书“扪其肌，热可烙手，面赤气粗，昏不识人”，为热邪充斥内外、蒸腾于外之象。浮数相合，说明热邪虽盛而尚在气分肌表，未全入里，故脉浮；热势鸱张，故脉数。此脉主外感热病或热邪内蕴之实热证，与肌热烙手、面赤气粗相应。", ["浮", "数"]], "17246": ["病机", "六脉俱伏，伏主邪气内闭、阳气不伸。原文谓“此谓水肿信不谬，而阳则不虚，盖由湿热相搏，水不由小便去，泛于皮肤”，说明湿热壅盛，气机闭阻，水湿泛溢肌肤，故脉伏不见；手足渐肿、喘咳不能卧，为水湿上凌于肺。前医误作阳虚，用肾气丸温补，反致肿喘增剧。脉伏而证实，正合湿热内闭、水气太盛之病机。", ["伏"]], "17247": ["病机", "脉象沉迟，沉主里、主气滞，迟主寒、主凝涩。原文谓“此寒疝也，病由肝气凝结，胁下如柱，非温血养胁不可”，说明寒邪客于肝经，气血凝滞，故脉沉迟；肾囊重坠、膀胱痛楚、季肋丸丸直上直下，皆肝经寒凝气结之征。前医误作湿热下陷，以利水清火治之，反增剧痛，正因寒证误用寒凉。脉沉迟主寒疝肝凝。", ["沉", "迟"]], "17248": ["病机", "六脉沉细而数，沉细为阴亏，数为内热，故主阴亏生内热；脾部尤甚，兼思虑伤脾，脾不统血，故有唾血疾；肺部浮短而涩，非病脉，说明病本在脾肾而非肺。脉症合参，午后发热、水泛为痰等症皆由阴亏脾伤所致。", ["沉", "细", "数", "浮"]], "17249": ["病机", "脉浮而缓，浮为表邪，缓为风；沉取内甚实，说明内有积热。疟疾本外感病，阿二内有积热，外伤于风，故脉浮缓而沉实。前医误作虚寒用桂附，转寒为热，烦渴汗出，正合内热之象。治当先解表后清里。", ["浮", "缓", "实"]], "17250": ["病机", "六脉乱动，沸如泉涌，为风痰壅盛、气血逆乱之象，故见昏乱颤汗、口噤腹满；下之后六脉俱平，说明邪去正安。脉乱动主风痰实证，非虚候，故用祛风至宝丹下之而愈。", ["乱", "平"]], "17251": ["预后", "产后脉宜缓小，今两脉实大而坚，为脉症相反，正气虚而邪气实，瘀血内结，故主预后不良。坚大之脉示邪盛正衰，虽用人参泽兰汤亦难奏效，终至不救。", ["实", "大", "坚"]], "17252": ["病机", "左寸关脉坚凝而涩，坚为邪实，涩为血瘀，寸关候胸膈，故知瘀血停于胸膈，发为心胃痛。前医误作虚治，补气益瘀，故不效。用失笑散散瘀定痛而愈。", ["坚", "涩"]], "17253": ["病机", "原文仅存标题“肝郁气逆脉不应病”，无具体脉象描述。其意指肝郁气逆之证，脉象与病症不相符，提示气机郁滞，脉气不畅，故脉不应病。", []], "17254": ["预后", "脉多伏，惟肝部沉坚而涩，且三二至辄一息，为肝郁气滞、瘀血内结之象，故主气逆症。服降气散瘀之剂后脉转长象，但复诊脉息如故，肝脏已绝，预后不良。", ["伏", "沉", "坚", "涩"]], "17255": ["其他", "原文未载具体脉象，仅述小梅患热病，烦躁昏瞀，外似实症，内实虚寒，已进桂附理中汤。脉象缺如，无法分析脉理，故仅录病情。", []], "17256": ["病机", "两寸浮数，浮为风邪外袭，数为热蕴于内。原文谓“内蕴积热，外伤于风，以致火郁经络”，故脉浮数应于寸部，主风热上攻之发颐，症见项脖高肿焮红、寒热头疼、眩掉汗出。非瘰疬之痰核，乃风火郁于经络，故治以连翘败毒饮疏风清热而效。", ["浮", "数"]], "17257": ["主病", "岳母脉沉而数、右关坚大，沉数主里热，坚大主实，右关候脾胃，故断为胃热，症见浑身发热、烦渴汗出、胸满便闭、腹中增痛，宜下。内嫂六部迟缓、右关尤甚，迟主寒，缓主虚，右关甚则脾寒，症见肚腹闷胀、不热不渴、四肢无力、精神困倦、饮食不思，宜温。两脉对举，明辨寒热虚实。", ["沉", "数", "坚", "大"]], "17258": ["病机", "脾部细弱，细弱主脾虚气血不足，由思虑伤脾、饮食不化所致，故平日必有健忘惊悸之疾。左寸滑数特甚，滑主痰，数主热，左寸候心，痰热扰心，故心烦发呕、坐卧不安、粉汗淫淫、捧心作状。脉症合参，断为脾虚停痰，先清痰后理脾。", ["细", "弱", "滑", "数"]], "17259": ["病机", "左脉弦而牢，弦主气郁，牢主病深牢固，左脉候肝，故知气郁于肝；右寸坚而滑，坚主实，滑主痰，右寸候肺，故知痰壅于肺。症见胸胁大痛、喘嗽不宁、饮食俱减，正合肝郁气滞、痰阻肺络之病机。服左金丸合颠倒木金散后吐痰涎数碗，脉转少软，郁开痰去而渐平。", ["弦", "牢", "坚", "滑"]], "17260": ["预后", "原文仅存“劳倦失眠脉坏难治”八字，未载具体脉象，故脉象要素为空。其旨以“脉坏”为眼目，言劳倦过度、失眠日久，脉气败坏，失其常度，故为难治之候。此属预后判断，提示脉失胃神根则病深，非一般劳倦可比。", []], "17261": ["预后", "六脉俱形沉数，沉主里，数主热，似属心火；然右关毫无神气，乍沉乍浮、乍缓乍急，且二至而一息，是胃气将绝、脉无神根之败象。原文虽以“心火上炎、心肾不交”为辞，实因脉非吉象而不便明言。沉数中见乍变与二至一息，故断为危候，预后不良。", ["沉", "数"]], "17262": ["病机", "六脉俱伏，伏为脉气深藏不显，主气机闭郁。文泉因受乔某诟谇，恚怒难泄，气结于中，故脉伏不应；气逆上冲则呕吐大作、痰涎溢地，气滞不通则腹痛。此非虚寒之伏，乃情志郁怒、气闭痰逆所致，脉伏正应其气机壅闭之病机。", ["伏"]], "17263": ["预后", "六脉沉弱，沉主里，弱主虚，为阴虚血弱之象，故腹痛喜按、时作时止、痛在脐下，投七味都气汤加肉桂而痛止。然两尺细仅如丝、毫无胃气，尺候肾，细如丝则肾阴竭，无胃气则生机败，故断为“恐命之不久”，越年果以瘵终。沉弱中见两尺无根，主阴虚劳瘵之危候。", ["沉", "弱"]], "17264": ["病机", "六脉缓大，缓主湿、大主虚，合而观之乃寒湿下注、阳气不运之象。原文断为'寒湿下注，关节不灵'，故见骨节痛楚、时作肿、不可屈伸。缓为湿邪黏滞之征，大为久病正虚之应，非下痿之虚火，亦非瘫痪之风痰，故用羌活胜湿疏利、五苓理中温化而效。", ["缓", "大"]], "17265": ["预后", "肝脉滑数、脾部弦急且三至一息，滑数为郁热，弦急为木旺克土，三至一息则胃气已败。原文断'肝气郁结，木来侮土，土已败矣'，故曰'病可小愈，命不可保'。后诊肝脉稍长而脾脉如故，知土败难复，虽暂以逍遥合左金取效，终不能愈，此脉示病机兼决预后。", ["滑", "数", "弦", "急"]], "17266": ["病机", "六脉浮弱、右关尤甚，浮为气虚外浮，弱为阳气不足，右关主脾胃，尤甚则中气下陷明矣。原文断'此气虚，非血虚也'，故饮食不思、精神减少、面黄肌瘦、胸满，皆清阳不升、浊阴不降所致。前医误作血虚痨瘵，用清降血药反馁其气，故以补中益气升举而中病。", ["浮", "弱"]], "17267": ["病机", "六部俱缓而沉、兼带弱象，缓主湿、沉主里、弱主气虚，合为寒湿痹着、阳气不充之候。原文辨其口舌便利、口眼无歪斜、手足不麻木，惟时作痛，故非瘫痪，乃老年阳气衰而湿邪痹阻经络。脉沉缓弱正合'年老得痹'之虚中夹湿，故前医以瘫痪治之罔效。", ["缓", "沉", "弱"]], "17268": ["病机", "左关弦滑、尺微细，左关候肝，弦滑为肝郁化火；尺候肾，微细为阴精亏耗。原文断'此阴亏肝郁也'，故两珠痛楚、夜甚、黑珠起白膜带红血点，皆水不涵木、郁火上炎之象。先疏肝散解郁，继杞菊地黄汤滋水，正合弦滑宜疏、细微宜补之脉。", ["弦", "滑", "微", "细"]], "17269": ["预后", "脉沉细迟弱，凡虚象无所不有，沉细为阴血亏、迟弱为阳气败，血崩日久，气血阴阳俱脱。原文见'面白如灰，气息仅属'，断'危如朝露，过半月恐不救'，此脉示元气欲竭之危候。虽投大剂六味回阳饮精神暂起，而崩仍如故，脉证相印，预后凶险。", ["沉", "细", "迟", "弱"]], "17270": ["病机", "脉俱弦直，弦为气机郁滞、直为筋脉拘急，合见吐泻交作、时时转筋，原文断'知为霍乱'。霍乱挥霍撩乱，清浊相干于中焦，气机逆乱则脉弦直，津液暴脱则筋失所养而转筋。刺尺泽、委中出紫黑血以泄浊，进藿香正气散芳化，脉证相符。", ["弦", "直"]], "17271": ["病机", "六部弦数尤甚，弦为热郁肝胆、数为火盛，合目赤如珠、口干唇破、小便如血、大便闭，原文断'此热疟也，单热不寒'。热邪炽盛充斥表里，故脉弦数尤甚，须内清其热则火退疟止，徒用截法无效，故投大剂白虎重用石膏而愈。", ["弦", "数"]], "17272": ["病机", "左关弦滑，余俱细弱。左关候肝，弦为肝郁，滑为脾湿痰滞；余脉细弱，是脾虚气血不足之象。合而观之，乃脾虚肝郁，木郁乘土，故头痛发呕、饮食不思。原文明言“此脾虚肝郁也”，并戒“虚而散，则大误”，正恐细弱之虚脉误作外感而发散。逍遥散健脾疏肝，药二服而病除，脉证相符。", ["弦", "滑", "细", "弱"]], "17273": ["主病", "疟疾脉“弦而迟”。弦为疟之正脉，因疟邪伏于半表半里，少阳枢机不利，脉气紧张故弦；迟则主寒，示此疟偏寒或阳气不足。原文先言“弦是疟正脉”，继以“而迟”申明其兼寒之性，故治当温散截疟，与常山酒之温通相合。此段以脉定疟之属性，属主病之论。", ["弦", "迟"]], "17274": ["病机", "两关坚劲，关候肝胃。坚劲者，脉体坚硬有力，主实热内结、气血壅滞。患者月事不至而腹大如鼓，前医误补益甚，正是实邪得补而愈壅。原文断为“胃热血结”，以坚劲之脉应胃中热盛、血结成块；热灼津伤则前半日渴，血结胞门则经闭腹大。三黄四物破血泻热，紫块下而腹减，脉证相印。", ["坚", "劲"]], "17275": ["病机", "右寸浮滑而数，余脉平平。右寸候肺，浮主邪在表分，滑主痰，数主热，合为痰火郁于肺经。故咳则面赤气急、声声接续，痰嗽俱出，胸膈满闷。原文辨其“面色红润，知非虚证”，断为“大实热证”，与虚劳之细弱脉迥异。芩连二陈加桑皮、木通清肺化痰，热退而滑存，示痰未净，仍当涤痰。", ["浮", "滑", "数"]], "17276": ["病机", "脉极沉数。沉主里，数主热，极沉极数乃热邪深伏于里、郁而化火之象。前医投白虎、承气而热如故，正因“中无实物”，热非阳明腑实可下，乃阴火大炽、肠胃燥甚，火热熏心故神昏发狂、口渴汗出。原文断“下之无可下，宜清降之”，以地黄汤加山栀、三黄清降，脉沉数示热在阴分血分，非表非腑。", ["沉", "数"]], "17277": ["其他", "此段叙家君年过七旬，新年劳攘、多食厚味，又感风寒痰咳流连，渐致口下暴肿、手足增胀，而延杨医诊治之经过。原文未载脉象，仅述症状与延医情状，故脉象要素为空。主旨在于记述误延庸医之事，非论脉理，归入其他。", []], "17278": ["病机", "原文标“脉极沉极数”。沉为邪在里，数为热盛，极沉极数示温邪深陷营血，热毒内炽。新妇得温病，呻吟叫号、反侧不安，前医误作痧症、胃寒，或用犀角解毒，或用平胃温散，皆未中病。沉数之脉明示里热，非表散温燥所宜，当从清透营热立法，此段借脉以纠误治。", ["沉", "数"]], "17279": ["病机", "脉沉而数。沉主里，数主热，沉数相合为热邪在里。斑疾浑身如丹、目睛皆赤、面汗如流、口唇焦破，似阳明胃热，然大便如常、腹绵软，知非腑实可下。原文断“阴热无可下，宜清之”，以知柏地黄汤清阴分伏热，三服热清。沉数之脉正示热伏阴分，故清而不下。", ["沉", "数"]], "17280": ["病机", "脉沉数而肝部涩、左寸微，沉主里，数主热，涩为血少，微为阳虚。合而观之，乃血虚肝郁，阴不涵阳，虚热内生。肝血不足则肝气不舒，故头痛、胸中烦扰；左寸微者，心气亦弱。治以滋阴润血，血润则肝舒，热退痛止，正合“乙癸同源”之理。", ["沉", "数", "涩", "微"]], "17281": ["主病", "脉浮数特甚，浮为在表，数则为热。然痢疾屡治不效，人枯瘦，发热渴甚，腹必胀痛，此非虚寒，乃实热内蕴，逼脉外浮。浮数之脉在此示热邪炽盛，非表证也。故告以“外似虚，却是实证”，非下不可，迟则内蕴攻胃成噤口，宜大承气汤急下存阴。", ["浮", "数"]], "17282": ["病机", "脉沉而滑，沉主里，滑主痰。病者体素肥，痰膜凝结，故数年不孕、月事不至；痰热上潮，结于喉中成痰核累累如贯珠，痛若口疮。头不痛、鼻不塞、项不肿、喉不闭、不渴不热、不汗不昏，皆非外感瘟疫风火，乃痰热为患。去其痰则血自通，经自调。", ["沉", "滑"]], "17283": ["病机", "脉微弱特甚，面如石灰，唇指皆白，此血虚之极而中气下陷。脾虚不能摄血，故崩不止；前医误用寒凉，转益甚。微弱之脉主气血大虚，非热非实，故不宜峻补，但提其中气，气能统血则崩自止。若再服寒凉，恐血脱而危。", ["微", "弱"]], "17284": ["病机", "六脉坚大而迟，坚大主实，迟主寒。病者面黄肌瘦、月事不至、腹大如鼓、见食辄吐，似虚而实为寒凝食积。自幼生冷风寒伤胃气，气凝血闭，故补之增剧。坚大迟之脉示寒实内结，非虚也，当温胃散结，五积散投之，结散则气行血通。", ["坚", "大", "迟"]], "17285": ["病机", "此段未诊脉，然据症可辨：经闭数月，腹中胀痛，痛有止时，胀则时时如此，大便不利，身不肿。不肿则非蛊，痛有止时则非瘀血固定，乃气滞碍血也。气机郁结，血行不畅，故经闭腹胀。治当行气开郁，气行则血行，无须诊脉而病机显然。", []], "17286": ["病机", "六脉坚实，人迎脉尤弹指，坚实主实，人迎候胃。病者抱郁而病，胸膈满闷，胃气增痛，转侧不食，前医误补益甚。此气郁而成痰，痰气交阻，胃失和降，故脉坚实弹指。久则胃连脾病，恐成蛊。治以疏气化痰，香砂平陈汤加大黄、枳实，二服而解。", ["坚", "实"]], "17287": ["病机", "右关弦甚，余各平平。右关候脾胃，弦主饮主痛。吐食非霍乱、非气郁，乃水积于中。水饮内停，胃气上逆则吐，小便不利，好饮水，胸膈闷滞，时兼头晕，皆水气为患。弦脉独见于右关，正示水饮结于脾胃。治以五苓散加苍术、木通利水，水去则吐止。", ["弦"]], "17288": ["平脉", "原文强调“诊脉以胃气为验”，胃气盛则脏腑皆盈，衰则脏腑皆败，故脉以胃气为生死之关。虽未言具体脉象，但指出脉证合参时须审胃气之盛衰，胃气存则脉有神，主生；胃气败则脉无神，主危。此段主旨在于平脉以胃气为本，非论某病之脉。", []], "17289": ["病机", "脉多弦急，弦主饮邪，急主气机紧张。患者素嗜茶，茶饮过多则水停心下，水气凌心则彻夜不寐，天明益渴。此非血虚不寐，乃水停不寐，故脉见弦急。弦为水饮内停之象，急为饮邪迫急之征，与“就枕则心”下文相应，说明水气上逆扰乱心神。", ["弦", "急"]], "17290": ["兼症", "脉颇弦大，弦主停食，大主邪盛，四岁小儿停食发热，见食作吐，小便赤如血，大便绝无，腹胀按痛，此食积化热之候。下后脉已小，说明邪去正衰，惟胃气尚滞，故续用保和丸加槟榔末消导。脉由弦大转小，反映实邪渐退而胃气未复。", ["弦", "大", "小"]], "17291": ["病机", "原文未出具体脉象，而言痰病“奇奇怪怪，千变万化”，凡不可名状、无从考核者大抵皆痰。痰为病，脉无定象，或滑或弦或沉，随证而异，故不能以一定之脉拘之。此段主旨在于说明痰病脉象多变，当参合症候辨识，非执一脉可断。", []], "17292": ["病机", "六部弦缓而滑，寸部浮取尤甚。弦主痰饮，缓主湿，滑主痰，浮主病在表分。体肥多湿，忧思气结，湿聚成痰，痰浊上蒙心窍，故见痴呆、独言独语、梦鬼等症。脉弦缓滑为痰湿内盛之象，寸浮尤甚说明痰浊上扰胸膈心神，非心血亏损之虚证。", ["弦", "缓", "滑", "浮"]], "17293": ["病机", "脉缓而坚，右关尤甚。缓主湿，坚主实，右关候脾胃，脉坚为湿热内蕴之征。湿热内淫，阻滞气机，故胸膈闷滞、大便后重；湿热下注，扰动精室，故遗精。此非虚证，乃湿热实证，当消导渗湿，用震亨渗湿汤。脉缓坚而右关甚，正合湿热困阻脾胃之病机。", ["缓", "坚"]], "17294": ["其他", "此段仅为标题“诊脉如审案”，无具体脉象与病机论述，故脉象要素为空。其主旨是以审案比喻诊脉，强调脉证合参、详审病因，属诊法原则之论，非主病、病机或平脉之具体内容，故归入其他。", []], "17295": ["病机", "原文明言“脾湿停痰一证，脉必沉滑”。沉主里，滑主痰，脾湿内停，痰浊内生，故脉见沉滑。沉滑为痰湿内蕴之正凶，而脾湿必便难、停痰必减食为佐证。此段以审案喻诊脉，强调脉证合参，沉滑脉紧扣脾湿停痰之病机，非虚证可比。", ["沉", "滑"]], "17296": ["其他", "原文强调诊脉须合三部十二脏腑参考斟酌，若诊寸忘尺、诊右忘左，见滑治痰、见数去火，虽有小效亦难去病。此段未出具体脉名，主旨在于批评片面诊脉、孤立凭脉用药之弊，属脉法原则讨论，故归其他。", []], "17297": ["病机", "左部沉实非病脉，右关沉弦而数。沉弦主气郁饮积，数主热，右关候脾胃，酒积化热伤胃，胃络受损则吐血；遇郁益甚，气郁化火。非思虑伤脾之怔忡健忘，非血热妄行之身热发渴，乃有余之病，故脉沉实弦数。", ["沉", "实", "弦", "数"]], "17298": ["病机", "六脉俱虚而无数象，右关尤甚。右关候脾胃，虚甚则脾土衰微，中气不能健固，故精神委顿、饮食不思、月事不调、怀孕辄坠。无数象排除火证，非痨瘵阴虚火旺，乃脾虚土衰之候，久则泄泻、咳嗽发热面赤恶寒，方成真痨。", ["虚"]], "17299": ["病机", "脉弦而滞。弦主气郁，滞主水积不行。患者先抱忧郁，后增愤争，气机郁滞，水湿不化，故胸满腹泻。气滞水积为病之本，弦滞并见正合气郁水停之机，故用香砂胃苓丸消之。", ["弦", "滞"]], "17300": ["病机", "六脉坚实，右关硬欲搏指。右关候脾胃，坚实硬搏主有形实邪内结，乃饮食伤胃、有余之病。胃实气阻，胸膈满闷、饮食不进，水湿不化而手足肿胀。前医疑水肿用利水、疑虚用肾气丸皆不效，正因未识此实脉。", ["实", "坚"]], "17301": ["病机", "六脉平，左关带滑象。左关候肝，滑主痰湿气壅。脉平而独左关滑，知非胎脉，乃肝气不舒、郁而生火，肝冲犯胃土，故胸满、饮食不进、呕嗽。以逍遥散加丹皮、山栀清之，二服而瘥。", ["滑"]], "17302": ["病机", "六脉平和，惟左关滑、右关弱。左关候肝，滑主气郁；右关候脾，弱主脾馁。患者终日抱闷气，气不伸则肝郁，脾运受困则脾馁，故成疾。乃气不伸而脾馁之候，非死证，投逍遥散疏肝健脾。", ["滑", "弱"]], "17303": ["病机", "六脉沉而数，兼带弱象。沉主里，数主热，弱主虚。耳主肾，肾气热则耳塞，阴火上冲故耳聋。前医皆作肝气平肝不效，因脉沉数弱非肝郁之弦，乃肾虚阴火内炽，故断为肾热而非肝气。", ["沉", "数", "弱"]], "17304": ["病机", "左关滑数、右寸关俱甚，滑主痰，数主热，关部候肝脾，寸部候肺。肝气郁滞，横逆犯肺，气郁化火，灼津为痰，痰热内蕴，故见喘咳交臻、呻吟不食。前医误作痨瘵，多服补药，反增壅滞。此脉证实为气郁停痰，非虚损之候，故以平胃、二陈、四七汤合进而取效。", ["滑", "数"]], "17305": ["病机", "脉细数，肺部兼滑，细为阴血不足，数为热，滑主痰。热入血室，血分有热，故癸水不至；热灼肺津，炼液为痰，故肺部滑。初因少阳感冒，邪热内陷，与血相结。前医误用桂附，以热济热，如油沃火，致喘咳、午后发热、头目昏晕。治宜小柴胡加生地、丹皮凉血透邪。", ["细", "数", "滑"]], "17306": ["病机", "六脉浮滑，两寸俱出鱼际者半寸。浮主上焦，滑主痰，寸脉过寸口入鱼际，为痰壅上焦之象。痰厥头痛，非外感风邪，故散之不效。痰浊上蒙清窍，则脑后疼、起卧不敢转侧；甚则痰阻经络，发为刚痉，角弓反张；缓则半身不遂，口眼歪斜。此实大症，须久服除根。", ["浮", "滑"]], "17307": ["病机", "原文未诊脉，以症测机。两腿连脚作肿，午后益盛，皮皱光亮，小便不利，胸膈发闷，皆水气下注之征。饮水太多，脾失健运，水湿泛溢肌肤，下注于腿。若不泻其水，小便利则肿自已，否则水气渐至腰腹，则成水肿危候。此段重在阐明水气病机，非凭脉断证。", []], "17308": ["病机", "六部沉数，右关坚欲搏指。沉主里，数主热，坚主实，右关候脾胃。素有积滞，兼忧郁气结，积滞与热相搏，壅塞中焦，故胸膈胀满、饮食不思。前医误作大虚，用桂附补之，反助热壅滞，满益甚。脉坚搏指，实证显然，宜泻其积滞，非虚证可补。", ["沉", "数", "坚"]], "17309": ["病机", "脉象沉数，身热如火。沉主里，数主热，热邪内蕴血分，故身热不退。前医误作风温，用荆防败毒、通圣散发散，不知长夏皮肤开泄，有汗而散之，反耗其气。此非外感，乃血分有热，但清其血，热自止。脉沉数正是热在里、在血之征，与风温表证迥异。", ["沉", "数"]], "17310": ["病机", "六脉沉弱，两尺如丝。沉弱主虚，尺部如丝为肾气衰微。因贫窘忧郁，思虑伤脾，日久及肾，气血大虚，故面目黄瘦、气息仅属、饮食不思。喉中如有物塞，即梅核气，由气郁痰凝所致，非时气也。此大虚证，须大剂峻补，兼节思忍气，方可万全。", ["沉", "弱"]], "17311": ["病机", "脉象沉伏，按之至骨而后见。沉伏主气郁痰食内闭，邪实壅塞，阳气不能外达。因情志不遂，气郁生痰，痰积碍食，胃气为痰气所壅，清阳不升，浊阴不降，故头晕目眩、项粗口干、腹满便秘。此气郁痰实证，非痨损，故以胃苓承气汤下秽物而快，继以香砂六君丸调补。", ["沉", "伏"]], "17312": ["病机", "原文诊得“六部沉伏”，沉伏之脉主郁滞。夫人因家道式微、翁姑俱老、诸事赖之，情志不遂，气机郁结，故脉沉伏不起。此郁滞之脉，主气郁内结，与“衣饰楚楚”而病、日与夫人反目等情志症候相应，治宜逍遥散解郁。", ["沉", "伏"]], "17313": ["病机", "此段未出具体脉象，而论“病机万变”“以色合脉，以脉合症，以症合问”，强调脉症互参以穷病源。脉象虽未明言，然其旨在于脉症合参以辨病机，非主一病一脉，故列病机。", []], "17314": ["病机", "原文“举之则濡，按之则滑”，濡为湿，滑为痰，举按异象示痰火内蕴。断为“胃中有火，膈上有痰”，痰火浸淫，侵犯膻中，壅遏心窍，故胸中奇痛、神昏如醉。濡滑之脉与痰火壅遏之症相应。", ["濡", "滑"]], "17315": ["病机", "原文“浮之则濡，沉之则弱”，浮濡沉弱示营卫俱虚。疟久不瘥，正气虚惫，营卫俱穷，故脉濡弱而“绵延不已”。此脉主正气亏虚，与“脉如悬丝”、久疟不愈之症相应，故用人参、何首乌扶正截疟。", ["濡", "弱"]], "17316": ["病机", "原文“脉虽潜伏，而气口则隐隐见也。但真微之脉，粗浮者不能察耳”，脉潜伏而微，主气虚卒倒。东垣以卒倒为气虚，正谓此症。脉微伏不起，与周身如冰、晕绝不苏之气虚症候相应，故重用人参益气回苏。", ["伏", "微"]], "17317": ["预后", "原文“寸关已不可见，左尺犹瞥瞥如𤸒上肥珠”，寸关无脉而左尺尚存如珠之象，示胃气未绝。症虽万无一生，脉可百中救一，故断为可救。此以脉判预后，与产后蒸热昏困、瞑目治凶具之危候相应，果一服目开而愈。", ["瞥瞥如𤸒上肥珠"]], "17318": ["病机", "原文“阴脉细矣，按之至骨则坚”，脉细而坚，非虚细，乃湿热壅结之象。两足肿重痛若虎啮、两膝如绯、拊之烙手，皆湿热下注。细为湿郁，坚为热结，故不可竟以虚责，当以黄柏清湿热，木通、槟榔通利。", ["细", "坚"]], "17319": ["病机", "原文“寸脉乍大乍小”知为鬼祟，“两关弦滑且大”定为痰饮之疴。弦滑大主痰饮内积，痰浊上扰，故遍体如虫螫、口舌糜烂、幻见鬼物。弦滑大之脉与痰饮症候相应，投滚痰丸、小胃丹下痰积而愈。", ["大", "小", "弦", "滑"]], "17320": ["病机", "脉数而沉软，非实火，乃土惫火衰。原文谓“脉诚数矣，独不察其沉则软乎？不第土惫，抑且火衰”，数脉虽似热，但沉软示中阳不足，故用六君子加姜、桂温补而痛减。此脉主虚寒性腹痛，与上脘抵少腹奇痛、服寒凉弥甚相应。", ["数", "沉", "软"]], "17321": ["病机", "伤寒八日大热不休，胸腹满痛，而脉细且软，为阳症得阴脉。细软示正气已虚，邪气犹在，故攻补两难。原文谓“欲攻之，则形体已虚；欲补之，则邪气犹在”，治以润下缓攻，结粪下而热退。此脉主正虚邪结之候。", ["细", "软"]], "17322": ["病机", "脉大无力，非实热，乃火衰不能生土。年高忧思，发热头疼，误汗致喘促神昏，脉大而无力，示中气大虚、虚阳外浮。原文谓“此火衰不能生土耳”，故用参、耆、术、附温补而愈。此脉主虚证，与汗出气喘、神昏倦相应。", ["大", "无", "力"]], "17323": ["预后", "原文“真藏脉未见也”，脉象未详，但强调真藏脉未现，故虽洞泄百余次、肌肉尽消、神气愦乱，犹有生机。此甚虚之症，法当甚补，用参、附固脱救气。脉无真藏，示胃气未绝，预后尚可挽回，与危重症状形成对比。", []], "17324": ["主病", "左尺独数，皮肤甲错，腹痛面黄体瘦，是小肠有痈。原文“脉数知脓已成”，数脉主热，热聚成痈，脓成则数。故以葵根、皂角刺溃脓，脓血下而愈。此脉主小肠痈，与腹痛、皮肤甲错相应。", ["数"]], "17325": ["病机", "右尺偏大，皮肤甲错，腹满痛喘急，先断为大肠痈。托里三日后“脉始数，数则脓已熟矣”，数脉示热毒壅聚、脓已成。故用角刺、山甲、葵根溃脓而愈。此脉主痈脓已成，与腹满痛、皮肤甲错相应。", ["数"]], "17326": ["病机", "六脉缓大而软，缓大非实，软示不足。原文谓“皆缘以泄伤脾”，妊娠腹胀泄泻、肢体肿重，因泄伤脾，脾虚湿盛，故脉缓大而软。先止泻后补中，用参、术、茯苓等而愈。此脉主脾虚湿盛，与泄泻肿胀相应。", ["缓", "大", "软"]], "17327": ["病机", "伤寒六日，谵狂笑语，头痛有汗，大便不通，脉浮而大，腹不硬不痛。浮大示病仍在表，非里实。原文引仲景“知不在里，仍在表也”，故用桂枝汤和营卫而愈。此脉主表证，与谵语、汗出、头痛相应，不可误下。", ["浮", "大"]], "17328": ["病机", "脉沉且数，沉为在里，数为有热，结合“按其腹便攒眉作楚”，说明热邪与燥屎结于肠腑，属协热自利之旁流，非正粪。燥屎内结，热迫津液下趋，故下利日数十行；热扰心神则懊𢙐，燥屎阻滞气机则目胀。脉症合参，病机为里热燥结，故用承气汤下之，得结粪而利止。", ["沉", "数"]], "17329": ["病机", "六脉皆无而趺阳脉大而有力，趺阳候胃气，大而有力为胃中实热内结。虽四肢俱冷、体不能动、口不能言，似阴症，但“以手柱其腹，则热且坚”，腹热且坚为燥屎内结之明证。热结于里，阳气不达四末，故肢冷；燥屎阻滞，腑气不通，故神昏不语。此乃大实有羸状，脉症合参，病机为阳明腑实，故下之得燥屎而愈。", ["大"]], "17330": ["病机", "脉滑而无力，滑主痰湿，无力为气虚。泄泻无度而服燥湿分利达气药不效，说明中气本虚，运化失职，痰滞不化，清阳下陷。脉滑为痰滞，无力为中虚，故病机为中虚下陷兼痰滞不化。治以六君子加升、柴、沉香、五倍子，补中升提、化痰涩肠，十剂而安。", ["滑", "无力"]], "17331": ["病机", "脉滑主痰湿，遇天阴痛辄甚，天阴湿气偏盛，外湿引动内湿，故痛增。背心一点痛，久而渐大，行气和血药不效，说明非单纯气滞血瘀，而是湿痰凝滞经络。脉滑与天阴痛甚合参，断为湿痰无疑。湿痰阻络，气血不畅，故痛。治以胃苓汤加半夏，燥湿化痰，数剂而痛消。", ["滑"]], "17332": ["病机", "脉滑而软，滑主痰，软主气虚。劳与怒并，汗出昏倦，语言错乱，危笃殆甚，为气大虚而痰上涌。气虚则清阳不升，痰浊上蒙清窍，故昏倦、语言错乱。脉滑为痰涎内盛，软为正气大虚，故病机为气虚痰涌。治以补中益气汤加半夏、附子，补气升阳、化痰降逆，渐得苏醒。", ["滑", "软"]], "17333": ["病机", "六脉结而有力，结脉主气机阻滞，有力为实邪内结。久忧暴惊，发为颠妄，服补心神、逐痰涎药均无效，说明痰积胶固，非一般逐痰可解。脉结有力，为痰浊壅盛、阻滞脉道之象，故病机为痰实内结、蒙蔽心窍。治以宁志膏安神，继以小胃丹峻下痰积，去痰始尽，后以归脾、妙香加牛黄、龙骨收功。", ["结", "有力"]], "17334": ["病机", "脉无虚数之象，惟浮大而滑，浮主表、主上，大主邪盛，滑主痰。经年咳嗽，医谓虚劳，但脉不虚数，说明非阴虚内热。浮大而滑，为风痰胶固于至高之府（肺），未得宣越；又多服酸收之剂，致痰邪留恋，故久而日剧。病机为风痰壅肺，肺失宣降。治以麻黄、杏仁、半夏、橘红等宣肺化痰，五剂而愈。", ["浮", "大", "滑"]], "17335": ["病机", "阳脉滑而阴脉搏，阳脉候气，阴脉候血。滑主痰，搏主血瘀，痰血互凝，阻于胸膈，故食下辄噎，胸中隐隐痛。忧愤交乘，气机郁滞，痰血互结，形成噎膈。脉滑为痰，搏为血瘀，故病机为痰血互凝。治以二陈汤加归尾、桃仁、郁金、五灵脂，后入人参益气行血，血从大便出而愈。", ["滑", "搏"]], "17336": ["病机", "脉细为气衰，沉为寒痼，说明病机是气虚寒凝，非瘀血。胸腹奇痛而经阻，乃气衰寒凝所致，故攻瘀则加重。用参、耆、术补气，木香、姜、桂温寒，药入即快，证明病本在虚寒。", ["细", "沉"]], "17337": ["病机", "脉大而软，两尺尤甚，是火衰不能生金，属虚证。大而软为元气不足，尺甚则肾火衰微。胸膈闷满、畏食，因火衰不能腐熟水谷。误用寒剂则伤阳，故用六君子加姜、桂温补而效。", ["大", "软"]], "17338": ["病机", "六脉沉迟，两尺益甚，为衰火不能生弱土。沉迟主里寒阳虚，尺甚则肾阳衰微，水泉不藏而小便不禁，转输违度而谷食不安。用理中汤、八味丸温补脾肾，火旺则土强，诸症自愈。", ["沉", "迟"]], "17339": ["病机", "脉不浮紧，故非表证；不沉实，故非里实。只有少阴大而无力，为劳神太过，虚烦类伤寒。大而无力是气虚火浮，禁食则胃气更伤，故先饮糜粥，用归脾汤补养心脾而愈。", ["大", "无力"]], "17340": ["病机", "六脉洪盛，按之搏指，是至虚有盛候。洪盛为邪气实之象，但按之搏指而形色衰惫，知为心肺俱虚，虚阳外浮。法当从症不从脉，补中为主，用补中益气加味而神清，证明脉症相逆时当舍脉从症。", ["洪", "盛"]], "17341": ["病机", "六脉不数，右寸细且涩，右关大且软，是思虑伤脾之象。细涩为血少气滞，大软为脾虚不运。心劳太过，脾伤不能统血，故吐血多痰、喉间如鲠、日哺发热。用归脾汤补脾养心而愈。", ["细", "涩", "大", "软"]], "17342": ["预后", "脉来七至，数而急，主阴虚火旺，灼热咳嗽、吐血、消瘦、便溏，法在不救。然脉尚有根，说明胃气未绝，犹可救十中一二。用大剂参、耆、术、附补气温阳，壮水丸滋阴，终得起床。", ["数", "有根"]], "17343": ["病机", "右寸浮滑，是风痰胶固于太阴之经。浮主表，滑主痰，右寸候肺，故哮喘二十年，病位在肺。脉尚有神，说明胃气未败，可治。用宣肺化痰之剂，三剂减，继以丸药及六君子汤调理而愈。", ["浮", "滑"]], "17344": ["病机", "脉洪而软，洪为气浮于外，软则中候无力，合之见阴阳并虚。原文谓'虚风鼓动'，正因真元日削、攻治太深，气血不能内守，虚阳浮越而鼓动成风，故两足麻痹、两手亦患。洪软非实热之洪，乃虚风内动之象，治以神效黄耆汤补气，继以十全大补加秦艽，正合虚风当补之意。", ["洪", "软"]], "17345": ["预后", "六脉皆代，代为止而有常数，是脏气衰微、真元将绝之候。原文见痞闷而喘、肌肤如灼、汗出如洗、目不得瞑，乃神气外越、阴阳离决之象。医者言十剂决效，而脉已见代，故断为'灯将灭而复明'，汗如油、喘不休则明旦死。代脉在此非病机推断，实为决死生之凭。", ["代"]], "17346": ["病机", "六脉滑大，滑主湿浊，大主邪盛，合之见湿热壅盛。原文谓纵饮违度，'曲药中湿热下干精道'，故小便后滴点数点、时有精漏，服固涩药益漏，正因湿热未清而涩之反闭。滑大之脉不主虚，主湿热下注精道，故以干葛、豆蔻、白术、茯苓、黄柏清利湿热，湿热去则精自止。", ["滑", "大"]], "17347": ["病机", "脉大而无力，大为气虚外张，无力则中气不足，合之见中气虚而下陷。年十六精滑，闻女子声即下莫禁，非相火妄动，乃气虚不能固摄，清阳下陷而精关不守。故以补中益气汤倍升、柴升举下陷之气，佐六味丸加芡实、金樱、五味固涩，服三月而精固，正合虚者补之、陷者举之。", ["大", "无力"]], "17348": ["病机", "脉散，散为气散不收、根本已亏之象。原文色欲过度，梦遗精滑，服清火药、固涩药弗效，正因肾气耗散，非火非涩所能治。散脉主肾元不固、精气外泄，故以玉华白丹温固，人参汤送下，兼生脉散、六味丸交互服之，使散者收、亏者复，一月而愈。", ["散"]], "17349": ["病机", "寸与尺交数而滑，数为有热，滑为有痰，寸尺俱见则心肾同病。原文谓'心肾不交之症'，白浊因心火不能下交于肾、肾水不能上济于心，湿热痰浊下注而成。故以六味丸滋肾、加杏仁远志麦冬丹参通心肾，朱砂为衣、生脉散送下，使水火既济而浊自清。", ["数", "滑"]], "17350": ["病机", "原文未识脉名，然言'久虚之人脉如蜘丝，气将竭绝'，蜘丝即细如蛛丝、若有若无之象，主气血大虚、阳气欲脱。精滑经年、膀足肿痛、困顿床席，本已久虚，又误以黄柏、井泥寒凉外敷致遍身糜烂，医更拟凉药，故断非参、附无生理。脉如蜘丝正是虚脱之凭，温补二月始安。", []], "17351": ["病机", "脉缓大而无力，缓主湿，大而无力主正虚，合之见风湿交侵而正气不足。腰痛不得坐卧，服补肾药弗效，正因非纯虚，乃风湿客于腰膝、气血痹阻。故用独活寄生汤祛风胜湿，四剂痛止；邪去则正虚，续服八味丸补之。缓大无力既示湿邪，又示本虚，攻补先后有序。", ["缓", "大", "无力"]], "17352": ["主病", "寸脉左手滑而急，滑主痰气壅盛，急主痛甚气逆。心腹大痛、伛偻不能仰，气不能息，咳则攒眉欲绝，显系心疝急痛之候。滑急之脉应于心脉，气滞寒凝，不通则痛，故断为心疝无疑。", ["滑", "急"]], "17353": ["病机", "脉盛大而滑，按之不甚虚，乃膏粱厚味酿痰、郁怒伤肝，气壅血滞之实象。腹胀气粗，为肺肝气逆、痰食内阻。盛大滑示邪实有余，非虚损可比，故用疏肺达肝而效，后以参术香砂调补收功。", ["大", "滑"]], "17354": ["病机", "六脉大且结，大主气壅，结主气滞不行。郁怒伤肝，又感暑邪，气机闭塞，故小便不通、气高而喘。脉大非虚，结为气结，乃气滞实证，故用枳壳、木通、生姜急通其闭，一剂遂通。", ["大", "结"]], "17355": ["病机", "疟发间日，脉见弦紧。弦为少阳疟邪，紧主寒束，阴阳相争，寒热交作。弦紧示邪踞半表半里，未可强截，故用升麻柴胡提阳、黄芩知母引阴，使邪离阴阳而寒热自止，佐以和胃。", ["弦", "紧"]], "17356": ["主病", "痢下一月，脉大而无力。大而无力为虚象，久痢伤脾耗气，气血两亏，故脉虽大而按之无力。其虚可知，禁痢药攻伐，径用十全大补兼补中益气加姜桂温补，二十余日而安，示虚痢当补。", ["大", "虚"]], "17357": ["兼症", "急喉痹颈肿喉痛且麻，胀而喘，脉浮恶寒。浮脉主表，恶寒为表邪未解之征。毒势方张而病在表，故用荆防牛蒡薄荷辛散，加姜汁、刺少商出血。原文强调见脉浮恶寒者，寒凉敛剂均在禁例。", ["浮"]], "17358": ["病机", "年十六发尽脱落，脉数而大。数主热，大主邪盛，多食甘则骨痛发落，此胃热炽盛、肾阴受灼之候。揣股髀间骨果大痛，印证《内经》甘伤骨之论。故用还少丹加生地当归滋肾，兼清胃汤泻热。", ["数", "大"]], "17359": ["病机", "肌肤灼热、神昏呕逆，热处在骨间，脉沉而搏，此伏火内郁，火伏于里故脉沉，搏指为火郁搏激。若脉散则示正气欲溃。用黄连山栀黄柏清透伏火，佐枳壳陈皮姜汁宣通，四剂而痊。", ["沉", "搏", "散"]], "17360": ["病机", "原文谓“六脉忽大忽小、忽沉忽浮”，脉象变动不居、无一定之形，非气血偏盛偏衰之常脉，乃邪祟凭附、扰乱神明之象。脉无定体，故谵妄终日，安神化痰祛邪诸剂不效。此脉象本身即提示病机不在脏腑虚实，而在邪祟干扰，故以八毒赤丸内服、艾灸外治而祟绝。", ["大", "小", "沉", "浮"]], "17361": ["病机", "原文谓“肝脉浮濡，肺脉沉数”，又言肝脉“当沉长而弦”今反浮濡，肺脉“当浮短而涩”今反沉数，是肺燥失相傅之权，肝木无所畏制而飞扬上越，魂不能藏，名离魂。脉之浮濡沉数，正示肺燥肝越、金不制木之机，故见蒸热引饮、谵语如见户外事。", ["浮", "濡", "沉", "数"]], "17362": ["病机", "原文谓“脉浮之细小，沉而坚搏”，浮取细小似虚寒，沉按坚搏则内有实热郁伏，不得宣越，故外显战栗恶寒、五月向火之假寒。脉细而按之搏指，正是郁火内伏、热极反兼胜己之化之据，故以栀连柏柴凉药热饮，恶寒减而火炉辍。", ["细", "小", "沉", "坚"]], "17363": ["病机", "原文谓“六脉冲和，独有中州涩而无力”，六脉虽和而中州涩弱无力，是土虚不能制水，湿气下注下焦，故两足酸软、神气不充。脉虚下陷之症，若用牛膝、苡仁、黄柏下行之剂则愈陷，故前服补肾清热去湿诸药无功，以补中益气加苍术升举脾土而愈。", ["涩", "虚"]], "17364": ["病机", "原文谓“六脉俱涩，喉有喘呼”，引《内经》肺所生病上气喘满、臂痛、掌中热、溺色变。脉涩主气机不利、肺失宣降，故两臂痛甚、两手灼热而溺色如泔。涩脉应肺病气滞，非血少之涩，故用枳桔茯苓知母宣肺利气，三剂而安。", ["涩"]], "17365": ["病机", "原文谓“脉大而滑，痰气胶固也”，大主邪盛，滑主痰涎，痰气胶结于中，扰乱神明，故十昼夜不得瞑，服归脾汤反中夜见鬼。脉大而滑正是痰积胶固之征，故以滚痰丸下痰积甚多而瞑眩，继以六君子汤调理一月而愈。", ["大", "滑"]], "17366": ["病机", "原文谓“脉弦而细”，弦主肝急、主痛，细主血少，女子腹痛肠鸣、身伛偻而气喘呼，脉弦细乃肝经寒凝气滞、疝气内结之象，故断为女子之疝。以青木香、川楝、茴香、肉桂等温肝行气散结，一剂痛止，四剂已。", ["弦", "细"]], "17367": ["病机", "原文谓“脉小腹濡”，脉小为正气未复，濡为邪气已尽而胃气未充，故伤寒汗下后时时灼热，非邪深重，乃谷气不加、阳明失养之饥也。脉小濡示邪退正虚，禁食清剂反困倦已极，徐进糜粥日五六次，不药而愈。", ["小", "濡"]], "17368": ["病机", "脉大而鼓，按之如无，大鼓为外强之象，按之如无则中空无根，是元气浮越于外、真气欲绝之候。年高入房，昏倦不食，目不能瞬，口不能言，肌体如烙，皆虚阳外浮、真阴内竭之症。故断为真气欲绝，病重药轻，非大剂人参附子不能挽回。", ["大", "鼓", "虚"]], "17369": ["病机", "脉浮而濡，浮为风邪外客，濡为肺金薄弱、气阴不足。喘咳吐血十余年，金脏既薄，风邪乘虚客之，故脉见浮濡。治以薄荷疏风，人参、麦冬补肺气养肺阴，桔梗、苏子、橘红、茯苓宣降化痰，标本兼顾，故二剂效而三月除根。", ["浮", "濡"]], "17370": ["病机", "脉大无力，大为气虚外张，无力为正气不足，故断为气虚之候。气虚则清阳下陷，足疮浸淫三载，前服解毒、燥湿、清热祛风诸药皆疏利伤正，愈下愈陷。以补中益气升举清阳，加萆薢、苍术化湿，外用膏散收湿，更以六味丸加苍柏间服，缓缓收功。", ["大", "虚"]], "17371": ["病机", "肝脉沉而坚，沉为病在里，坚为郁结不散，故断为怒火久伏、木郁宜达。烦躁发热、肌体骨立、目不得瞑，皆郁火内伏、肝魂不归之症。以柴胡、白芍、丹皮、栀子疏肝达郁、清泄伏火，少佐桂枝通阳，药后熟寐，正合卧则魂归于肝之义。", ["沉", "坚"]], "17372": ["病机", "六脉虚软，虚软为正气不足、中气下陷之象。阳气不充则头痛，阴气衰少则内热，发热困倦头痛皆非外风，前以风治转剧，正因误散其虚。补中益气加葛根升举清阳，使中气复位、阳升阴长，故一剂而减，数剂而愈。", ["虚", "软"]], "17373": ["病机", "左脉独沉牢，沉为病在里，牢为坚积内著，左脉属心肝，故断为惊气入心、畜血为祟。触惊后身如在车船、开目则眩、起立欲仆，皆瘀血内阻、神明不安之症。前医补虚化痰弗效，正因未识畜血。用大黄、山甲、归尾、桃仁等破血下瘀，血下而愈。", ["沉", "牢"]], "17374": ["病机", "脉大而软，大为气虚外浮，软为正气不充，故断为脾肺气虚、风乘经隧。多思善郁伤脾，昏冒痰涌、口㖞语涩、四肢不随、时时悲泣，皆气虚风中之候。以补中益气加羌活、防风、秦艽、天麻、半夏、钩藤扶正祛风，后去风药倍参耆，兼八味丸收功。", ["大", "软"]], "17375": ["预后", "孟秋诊得石脉，石为冬脉，沉坚如石，非时令所宜。新秋见冬脉，是肾气先绝、真脏脉现，故断其果殁于冬。中风昏愦、面赤发笑、难饮食月余，本属危候，脉与时反，预后不良。此段以脉测时令之逆，属死脉预后之论。", ["石"]], "17376": ["病机", "脉右关浮缓，右关候脾，浮为风湿在表，缓为湿邪黏滞。脾土不足，风湿交浸，运化失司，故肠风下血、面色枯黄、腹高不快。此脉主脾虚湿盛、风邪内侵之病机，与便血、腹胀相应。", ["浮", "缓"]], "17377": ["病机", "脉大而数，按之极软，大数似热而软为虚，此中气积虚，凉剂更伤中阳，致虚劳濒危。脉大数非实火，乃气虚外浮；极软为脾胃衰败之象。主中气亏虚、虚阳外越之病机，与久困虚劳、汗多精耗相应。", ["大", "数", "软"]], "17378": ["病机", "脉状如丝，即细脉，主阳气虚衰，无力鼓动血脉。蒸热干咳、肌体骨立，似阴虚而实为阳损，滋阴降火更伤中阳，致食减泄泻。此脉主阳气虚馁、脾肾不足之病机，与虚热、咳喘、泄泻相应。", ["细"]], "17379": ["预后", "初诊手太阴脉搏指洪大，足少阴脉如烂绵，为水衰火乘金，贼脉见矣。复诊洪大变为细，肾脉软者变而为大，尺寸反者死。肺脉如丝悬绝，主金气将败，预后不良。此段以脉变测病机，判死期在即。", ["洪", "大", "细"]], "17380": ["病机", "六脉大且坚，大主邪盛，坚主实积，怒后大醉，肝气横逆，水湿内停，肢体肿胀、烦满欲绝。脉证相合，为水气太过、实邪壅盛之病机，故当逐其水，用疏凿饮子而小便大行。", ["大", "坚"]], "17381": ["病机", "脉沉涩而软，沉主里，涩主血少气滞，软为虚象。积劳善郁，肢体胀满，服胃苓汤转增痞闷，色黄而枯，此虚寒内盛、气血涩滞之病机。脉不任攻伐，宜大温大补，误治则危。", ["沉", "涩", "软"]], "17382": ["病机", "右手脉滑，滑主痰食积热，右关候胃，知为胃火内蕴。形羸善饭，忽胀满，医误认食积，服槟榔、枳、楂等消导，胀势转增。此脉主胃火亢盛、气机壅滞之病机，故用石膏、黄连、大黄清泻而愈。", ["滑"]], "17383": ["病机", "六脉俱浮，浮主表邪。纵饮嗜瓜果，泄泻日十余次，分利燥药不效，因思春伤于风，夏生飧泄，风邪内陷，非大汗不解。此脉主风邪外束、表气不宣之病机，与飧泄相应，故用麻黄、升麻取汗而泄止。", ["浮"]], "17384": ["病机", "左脉数大无伦，为痨虫蚀脏、邪热嚣张之象；右脉沉缓无力，示中气已馁。数大无伦非实热，乃传尸虫毒内燔，故见蒸热咳嗽、目不明、腰肢无力、吐清涎、唇白点。脉证合参，断为传尸痨瘵，虫蚀脏腑，非寻常滋阴开郁所能治，故用加芎归血余散加甘遂、天灵盖以攻虫。", ["数", "大", "沉", "缓"]], "17385": ["病机", "脉缓而涩，缓为气虚，涩为血少兼滞。痛甚而脉不弦紧，反见缓涩，知非实邪壅塞，乃气血两虚、运行无力所致之痛。前服理气药不效，正因虚痛不可更耗其气。故曰法当峻补，用参、耆、术各三钱，佐陈皮、甘草，补中兼运，是夕痛定，证明痛亦有属虚者。", ["缓", "涩"]], "17386": ["病机", "左脉涩为血少而滞，右脉濡为气弱不运。盛暑腹痛、自汗淋漓，前服清火行气无效，因非实火气滞，乃气弱不能运行，血因以阻。故用参、耆补气，姜、桂温通，桃仁、归尾、苏木、玄胡索、郁金活血行滞。当暑用姜、桂，正是舍时从症，凭脉辨证之要。", ["涩", "濡"]], "17387": ["预后", "前诊左寸大而滑、右关弱而沉，以参、附制用而肿胀减。后因忧劳复作，脉数大无伦，按之了不可见，是根本败坏。数大为虚阳外越，按之不见为元气脱根，与初诊之滑沉迥异。脉证相失，故断为根本败坏，预后不良，非复前方所能挽回。", ["数", "大"]], "17388": ["预后", "六脉俱濡，为气口独牢。濡主中气太虚，牢主坚积内着。虚而兼积，乃攻积太过、中气戕伤所致，故困惫不食。虽用补中汤，只可延时日，不能消积复元。脉见虚中夹实、正不胜邪，故断月余毙，属预后不良之候。", ["濡", "牢"]], "17389": ["病机", "脉举之则大，按之则缓。大而举之有力，为风邪外袭；缓而按之无力，为湿滞内蕴。风与湿俱，故肌痒且麻、发黑块、便痛呕恶，反复发作。前服热毒药不效，正因风湿相搏，非纯热毒。故用荆、防、羌、独祛风，二术、苓、通渗湿，芎、归、耆、甘调气血。", ["大", "缓"]], "17390": ["病机", "脉大而数，按之如蜘丝，大数为其假，如蜘丝为其真。久痢发热不食，腹痛喜按，前服香、连、芩、芍寒凉，愈伤中阳。此火衰不能生土，内真寒而外假热，故脉浮大数疾而按之细微欲绝。用附子理中汤冷服，从治假热，一剂而减，二十余剂而起。", ["大", "数"]], "17391": ["预后", "疟后汗如雨，本风伤卫，医误认气虚用参、术，致邪留而病复。既下后愈而复发，一月之疟、两月之痢，脉如悬丝，其虚已极。悬丝之脉为气血衰微、根本将绝，虽欲大补，杯水不救车薪，故二剂少安而逾旬不起，属预后不良。", []], "17392": ["主病", "脉坚实为邪实内结之象。患者夏令饮冷，水湿内停，胀满不食，腹如抱瓮，气高而喘，证属土伤不化、水气太过。暴病脉实，正气未虚，故可峻剂攻逐，舟车丸下之而愈。", ["实", "坚"]], "17393": ["主病", "脉细如丝，主气血虚衰。身冷如冰、口不渴，为阴寒内盛，发黄属阴黄。寒湿困脾，阳气不布，故脉细身冷。治以温阳化湿，六君子加姜附茵陈而效。", ["细"]], "17394": ["病机", "脉滑而有力，主实积内滞。下痢两月不衰，前医仅用清化，未予攻下，积秽未去，故脉象滑实有力。加大黄通腑，下积秽甚多而愈，此失下之过也。", ["滑", "有", "力"]], "17395": ["病机", "脉虽洪大，按之濡软，右尺倍甚，为命门火衰，不能生土。洪大乃虚阳外浮，濡软示中气大虚。痢如鱼脑、肠鸣切痛、闻食即呕，皆脾肾虚寒之候，故用参附温补而效。", ["洪", "大", "濡", "软"]], "17396": ["主病", "脉大而长且搏指，主坚积内结。酒后腹痛，痛处渐坚，为积滞之征。然两尺濡软，示肾气不足，故不敢峻攻，先补胃气，后以攻积丸下之，衰其半而止。", ["大", "长", "搏", "指"]], "17397": ["病机", "六脉沉细，主里虚寒盛。疟邪干犯太阴，中寒而蛔动，吐蛔、昏闷不能食，皆中阳不足之象。沉细为寒湿内困，阳气不伸，故以理中汤温中，加乌梅、黄连安蛔而愈。", ["沉", "细"]], "17398": ["病机", "脉沉而大，主邪伏于里。疟发寒甚于热，头痛恶寒，为太阳之邪未解，误截则邪不能伏，愈猖獗矣。沉大示邪结于内，故以石膏、黄芩清阳明，豆蔻、生姜救太阴，使脾胃和合而愈。", ["沉", "大"]], "17399": ["病机", "脉大而无伦，按之如无，为阴寒内盛，虚阳外浮之象。面赤足冷、索水不能饮、手扬足掷，皆内真寒而外假热，谓之阴躁。浮大沉小，阴证似阳，故用附子理中汤温补，冷服而愈。", ["大", "无", "伦", "按"]], "17400": ["预后", "原文未明言脉象，但医案强调“元气虽虚，幸脉有根蒂”，以脉有根判断元气虽虚却未至脱绝，故预后可调。患者劳怒后晕厥频作，显系元气大虚、虚风上扰，然脉有根蒂说明根本未拔，故断为“非三年调摄不可”，需久服参、附、四君等温补元气，佐羊肉羹养形，方得渐复。", []], "17401": ["病机", "原文未出脉名，但言“察君之脉，望君之色，俱合补气”，又云“肺素有热”，故虽虚当补而肺热不受参。其病机为久咳吐血五年，气阴两伤而肺金蕴热，虚中夹热，故用秋石咸润制人参上升之性，使补气而不助热，金气得振，嗽减而愈。", []], "17402": ["病机", "“六脉数而有力”为实热之象，数主热，有力主邪实。两颊俱赤、发热干咳、呼吸喘促，显系金木两家蕴热不得外越，热郁于内，肺失清肃，肝火偏亢。前服温补反助其热，故以逍遥散疏肝、地黄丸滋水，济以秋石、龟胶咸润制火，使蕴热得解。", ["数", "实"]], "17403": ["预后", "原文未出具体脉名，但言“脉法则已违度矣”，又引经“至如颓土，按之不得，是肌气予不足”，此即脉失胃气、按之无根之败象。暴怒伤阴，血菀于上而薄厥，血脱气耗，金虚木亢，木来克土，故脉违常度，主肌气不足，预后不良，果如期而殁。", []], "17404": ["病机", "“脉大如波涌，软若𤸒肥”为表虚不固之象。大而软者，气浮于外而中不守，玄府不密，故易感风邪。频发频服风剂，是开门延寇，更伤卫气。脉大非实热，乃卫阳浮越；软为气虚不敛。故制玉屏风散固表实卫，使玄府密而邪不再犯。", ["大", "软"]], "17405": ["病机", "“脉阳强而阴弱”指寸浮尺弱、阳浮阴亏之象。病得之酒且内，酒助湿热，内伤肾阴，阴不制阳，虚阳上扰，故嘈杂不宁。阳强非实火，乃阴弱不能涵阳；阴弱则下元亏虚。故用连理汤温中健脾，合加减八味丸滋阴配阳，使阴阳相济，三月而胸楚尽释。", ["强", "弱"]], "17406": ["病机", "“脉浮而大”主风邪在表。浮为风邪客于太阴皮毛，大为邪气盛于外。遍身细点有头粒，是太阴风疹而非阳明热毒之癍。癍在肌肉属阳明，疹在皮毛属太阴。前医误以升麻、犀角凉血解毒，反遏风邪，故烦闷懊𢙐。改用荆防蝉退疏风透疹，二剂而疹透。", ["浮", "大"]], "17407": ["预后", "“脉沉而涩，两尺为□”，沉主里，涩主精血枯滞。虚劳醉饱入房，汗出如雨，痰涌如泉，乃精伤气耗、痰瘀互结。涩脉见于痰家，已属难治，况尺涩更甚，为伤精之象，按重无根，是胃气已败。故断“在法不治”，虽勉用六君补中，涩象不减，果十六日而殁。", ["沉", "涩"]], "17408": ["病机", "脉大且疾，按之豁然，乃大虚之象。大而无力为虚，疾为虚阳外越，沉取豁然更证实内真寒。外见喘急自汗、得食即吐，是假热；脉症合参，病机为真寒假热，当用理中汤冷饮。", ["大", "疾"]], "17409": ["其他", "原文仅存“朱修之脉痿”五字，未载脉象描述，无法据脉析机。脉痿属痿证之一，多因心阳亢盛、壮火炎蒸所致，然此段无脉可凭，故脉象要素为空，主旨归为其他。", []], "17410": ["病机", "六脉有力，按之搏指，为实热壅盛之象。心阳独亢，壮火炎蒸，故称脉痿。脉实证实，故用承气下之，积滞去而肢节舒；后以参汤送丸，攻补兼施，终以三才膏补真元。", ["有力"]], "17411": ["病机", "脉浮之则大，沉之则濡，浮取大而无力，沉取濡软，为荣卫交损之象。大而濡示气血两虚，故痿废著床。用十全大补加附子、鹿茸等温补，百日机关利，半载而康。", ["浮", "大", "沉", "濡"]], "17412": ["病机", "脉大而数，按之辄减，大数似实，减则示虚，为虚而挟湿、湿热相兼之象。中气素虚，湿热蕴结生虫，故腹中嘈杂、呕吐涎沫、咽嗌异物感。当以参汤送槟榔丸涤虫，攻补兼施。", ["大", "数"]], "17413": ["病机", "六脉弱薄，为脾胃虚寒、气血不足之象。年近五旬，多欲善怒，患噎三月，日粥一钟犹吐其半，神情困倦，喜饮热汤，小便清白，皆虚寒之征。脉弱薄与症相应，故用理中汤温补而愈。", ["弱"]], "17414": ["病机", "原文仅言“脉有根本”，未载具体脉象，故脉象要素为空。脉有根本示胃气未败，可任攻下。因鼓盆之戚太过，气滞血瘀，胸痛不能饭，涎如卵白，溲便坚涩，畜血可下，用酒蒸大黄加桃仁等逐瘀而黑皆下。", []], "17415": ["病机", "六脉洪大，按之有力，为实热有余之象。大醉大劳，吐血二十余碗，服滋阴药后两颊俱赤，时仲春重裘登火炕，显系形体过暖、热壅血溢。脉洪大有力证实热，法当凉之，用生地、芍药、栀、连而止。", ["洪", "大"]], "17416": ["病机", "阴脉疾而鼓，疾为热盛急迫，鼓为脉来鼓指有力，合之阴部见实，乃龙火虚炎、虚阳妄动之象。淋沥大痛而脉不虚软，似实而实由虚火上炎，故前医泥“痛无补法”转通转虚。用六味加车前、牛膝等补中寓通而痛减，正说明此脉主肾虚火炎、本虚标实之淋痛，非实火可通。", ["疾", "鼓"]], "17417": ["病机", "脉数而沉且搏，数为热，沉为病在里，搏为邪实搏结。吐血两年而见沉搏，痛不可按、甚于夜分，是坚血畜积于里，瘀血内结、郁而化热之征。故非单纯滋肾补中可解，必以下瘀为治，下血如漆而痛减，印证此脉主瘀血内积、血瘀化热之病机。", ["数", "沉", "搏"]], "17418": ["其他", "此段述曾祖手录李士材脉案之流传经过，残编古架、凋落不堪，吾父珍重秘藏，续全之后复叹不知何人重较。全段无脉象描述，亦不涉病机症候，仅记医书传承源流与珍重之意，故脉象要素为空，主旨归入其他。", []], "17419": ["其他", "此段引张长沙之言，叹医道与六经并重，非可以艺术名之；又自述庚寅一病坐困八年，与谢鹿圆讲论、聚古今方书数年，始悟诸症坌集皆庸医金石妄投所致。全段论医道之重与学医经历，无脉象可辨，故脉象要素为空，主旨属其他。", []], "17420": ["其他", "此段评述朱丹溪著作，《脉因症治》先脉次因次症后论治，为无方之书；《丹溪心法》专以知柏寒凉治阴虚，为有方之书。指出唯阴虚有实火者宜之，否则不可胶柱。全段论医家方书之得失，未及具体脉象，故脉象要素为空，主旨归其他。", []], "17421": ["其他", "此段介绍李时珍《本草纲目》及所附《濒湖脉学》，称其辨释精详、二十七脉编为七编最便记诵，又及后人辑《普门医品》可便览，但古方用于今多无验、不可胶柱。全段评述脉学著作与方书，无具体脉象，故脉象要素为空，主旨属其他。", []], "17422": ["其他", "此段推许李士材为开宗第一家，无偏无弊、寒热适中，历举《颐生微论》《医宗必读》《士材三书》，而《诊家正眼》专论脉理、极其精详，称千古脉法之大成，学脉者当宗之。全段评介脉学典籍，未出具体脉象，故脉象要素为空，主旨归其他。", []], "17423": ["其他", "此段批评《医学入门》徒采四大家书、挂一漏万、毫无折衷定论，且其脉诀宗叔和，而不知叔和之诀实为高阳生伪诀，故斥其不可为训。全段论医书之失，未及具体脉象，故脉象要素为空，主旨属其他。", []], "17424": ["其他", "原文批评《东医宝鉴》杂辑成书，内治阴虚宗丹溪、脉诀宗叔和，认为“不可为训”。此段未直接描述具体脉象，而是对脉学传承的评判，指出盲目宗奉叔和脉诀会导致脉理不明，故无脉象要素可提取，主旨在于对脉书源流的辨析。", []], "17425": ["其他", "原文仅题“论脉”，未给出具体脉象描述或病机分析，无法提取脉象要素。此段属于脉学总论性质的开篇提示，未涉及具体脉象主病或病机内容，故归为其他类。", []], "17426": ["其他", "原文辨叔和《脉诀》为高阳生伪造，批评坊间俗本“鱼目混珠”，致使“脉理不明，大为所误”。此段未描述具体脉象，而是脉学文献的辨伪与评价，推重李士材《诊家正眼》等书，属于脉学源流考证，故无脉象要素。", []], "17427": ["其他", "原文论述三部九候及脏腑分属，指出“每候五十至”“三部共四百五十至”，批评“今人胡乱看之”。此段讲诊脉部位与至数要求，未涉及具体病机脉象，属于脉诊方法学内容，故无脉象要素可提取。", []], "17428": ["其他", "原文辨人迎、气口所属经脉，指出“寸口即气口也，非指左右而言也”，并引李士材、张景岳之辨，强调“不可胶柱而鼓瑟”。此段讨论脉诊部位概念，未描述具体脉象与病机，属于脉学概念辨析。", []], "17429": ["其他", "原文载寸关尺三部脏腑分属歌诀，依《内经》改正高阳生伪诀将大小肠列于心肺上部之谬。此段为脉诊部位与脏腑配属的规范，未涉及具体脉象主病或病机分析，故无脉象要素，归为其他类。", []], "17430": ["其他", "原文新编二十八脉名目歌诀，以“浮沉迟数”四字提纲，以“虚实”二字作结，称“极有深意”。此段列举脉名并说明编次用意，非论某脉主某病，故脉象要素取提纲四字，主旨在于脉名分类与学习次第，属脉学总纲。", ["浮", "沉", "迟", "数"]], "17431": ["病机", "原文以浮沉迟数四字提纲，将洪虚散芤濡微革七脉归浮分，伏牢细弱实五脉归沉中，缓涩结代属迟形，滑紧促动属数列，而弦与长短“不在四部设”。此段阐明脉象分类与阴阳浮沉之机，示人从四纲辨脉性，故归病机类。", ["浮", "沉", "迟", "数"]], "17432": ["其他", "此段仅言「景岳十六脉，有论在前」，为篇章承上启下之语，未出具体脉象，亦未论及某脉所主何病。故无从据脉析机，只可视为对前文十六脉论述的提点，提示读者回看前论，不涉病机、主病、症候等内容。", []], "17433": ["死脉", "原文以「雀啄连来三两啄」「屋漏半日一点落」「虾游静中忽一跃」「弹石硬来寻即去」「搭指散乱如解索」等状写死脉，明言「此即无胃气之脉」「真藏脉见」。脉失从容和缓之胃气，或断续如雀啄屋漏，或散乱如解索，或硬劲如弹石，皆脏气败绝、胃气已亡之征，故「六脉一见休下药」，主死不治。", ["散", "革", "牢"]], "17434": ["其他", "此段只列举奇经八脉之名：督、任、冲、带、阳𫏋、阴𫏋、阳维、阴维，说明其「在二十八脉之外」。原文未描述任何具体脉象形态，也未言其所主病机症候，属脉学名目之罗列，故不能据以推断病机，仅作奇经名目备考。", []], "17435": ["其他", "此段仅有「诊脉法」三字标题，未出脉象，未述诊法内容，亦未论病机主病。属篇目提示性文字，无实质脉理可析，故脉象要素为空，主旨归入其他，不作病机推断，以免凭空附会原文所无之义。", []], "17436": ["平脉", "原文述诊脉先「调自己气息」，次中候、轻候逐部寻究，以「一呼一吸之间脉行四至为率，闰以太息五至，为平脉也」。四至五至为胃气调和、气血周流之常，故称平脉；「其有太过不及，则为病脉」，是从至数之常变判平病，各以寸关尺分部断之，示平脉为辨病之基准。", ["平"]], "17437": ["平脉", "原文以「三部之内大小浮沉迟数同等，尺寸阴阳高下相符，男女左右强弱相应，四时之脉不相戾」为平人；若「独大、独小、独疾、独迟」及左右强弱相反、四时相背，则「皆病脉也」。强调脉以匀和相应为平，一处独异即脏气偏颇，并以左手不和病在表属阳主四肢、右手不和病在里属阴主腹藏分判病位。", ["大", "小", "浮", "沉"]], "17438": ["病机", "原文提出「察脉须识上下、来去、至止六字」，谓「上者为阳，下者为阴，来者为阳，去者为阴，至者为阳，止者为阴」。上自尺上干寸口为阳生于阴，下自寸口下于尺部为阴生于阳；来为气之升、去为气之降，应曰至、息曰止。此以脉势升降出入辨阴阳虚实，不明此则阴阳虚实不别，是脉机之总纲。", ["浮", "沉"]], "17439": ["病机", "原文以持脉轻重分五脏：三菽与皮毛相得为肺，六菽与血脉相得为心，九菽与肌肉相得为脾，十二菽与筋平为肝，按之至骨举指来疾为肾。由轻至重层层按寻，测脏腑之气所居深浅，脉位浮沉与脏气相应，故可据按之轻重别病在何脏，是分部候脏之脉法。", ["浮", "沉"]], "17440": ["病机", "原文仅言「脉分四时六气」，未出具体脉名，主旨在于说明脉象随四时六气而分，非论某一种脉所主之病。四时六气各有所主之脉，脉应时而变即为常，逆时则为病，故此段属脉与天时相应的总纲，不涉具体病机与症候。", []], "17441": ["病机", "原文「厥阴之至其脉弦」，言大寒至春分初之气，厥阴风木主令，故脉应之而弦。风木之气主升发条达，脉道紧张而端直，故见弦象。此为六气主时之常脉，说明此时脉弦乃风气当令、肝木应时的表现，而非病脉；若弦太过或不及，则示风木偏胜或不及之病机。", ["弦"]], "17442": ["病机", "原文「少阴之至其脉钩」，春分至小满二之气，少阴君火主令，火性炎上而盛，脉来洪大而曲，如钩之象，故曰钩。此说明君火当令之时脉应洪钩，属六气应时之常。脉钩反映火热之气偏盛于时令，若钩过甚或非其时见钩，则主心火亢盛之病机。", []], "17443": ["病机", "原文「太阴之至其脉沉」，大暑至秋分四之气，太阴湿土主令。湿为阴邪，其性重着下行，阳气为湿所困，脉气不能浮显，故脉来沉。此说明湿土当令则脉应之而沉，为六气应时之象；沉脉在此反映湿气偏盛、阳气受困之病机，与湿困中焦、身体重着等症相应。", ["沉"]], "17444": ["病机", "原文仅标「脉分五脏」，未列具体脉形，主旨为脉象分属五脏，以五脏配五脉论脉。此段为总纲，说明不同脏气各有其应脉，诊脉可据脉之形态推知病在何脏，属脉与脏腑相应的病机纲领，未及具体脉象与症候，故不取脉素。", []], "17445": ["病机", "原文「肝脉弦，心脉钩，脾脉代，肺脉毛，肾脉石」，以五脉分属五脏。肝主风木，气机条达故脉弦；心主火，脉来洪曲如钩；脾主土，脉来更代而和缓；肺主金，脉来轻浮如毛；肾主水，脉来沉石。此说明五脏各具本脉，脉象反映脏气特性，为凭脉辨脏腑病机之依据。", ["弦", "代"]], "17446": ["平脉", "原文标目「五藏平脉」，未出具体脉形，主旨为论述五脏之平脉，即五脏无病时的常脉。平脉各应其脏气而和缓有胃气，说明脉以胃气为本、和缓为平。此段为五脏平脉总纲，用以别于病脉，提示脉失和缓、独见一脏之象则为病，属平脉范畴。", []], "17447": ["平脉", "原文「肝脉来耎弱，招招如揭长竿木稍，曰肝平」，言肝之平脉虽弦长而兼和缓柔软，如高举长竿，梢末迢迢柔和。耎弱、和缓示胃气存，弦长为肝木之体，二者相合方为肝平。说明肝脉贵在弦而有胃气，若纯弦劲急无柔和之象，则为肝病甚至肝死之脉。", ["弱", "长", "弦", "缓"]], "17448": ["平脉", "原文以“累累如贯珠”“如循琅玕”状心之平脉，强调“盛满流行，而无太过不及之弊”。珠玉之象言其圆润流利、节律匀整，非洪大躁急，亦非细弱断续，故属心气充盛、血脉通利之常脉。既无太过之洪数，也无不及之微细，故曰心平，为无病之象，非主某病。", []], "17449": ["平脉", "原文谓“脾脉来和柔”“如鸡践地”，又释“和柔者悠悠扬扬”“相离者不模糊”“缓而不迫胃气之妙”。此脉从容和缓、节律匀净而不含糊，正是脾胃气充、中土健运之常象。缓而有神、不迫不躁，说明胃气未败，故曰脾平，属平脉而非病脉。", ["缓", "和"]], "17450": ["平脉", "原文以“厌厌聂聂，如落榆荚”状肺平脉，自注“厌厌、聂聂涩之象”“如落榆荚毛之象”“轻浮和缓为和平之象”。轻浮毛涩而兼和缓，正合肺主皮毛、宣降有常之性；涩而不滞、浮而不躁，是肺气清肃、治节不失之常脉，故曰肺平，非主病之脉。", ["浮", "涩", "缓"]], "17451": ["平脉", "原文谓肾脉“喘喘累累，如钩按之而坚”，自注三者“皆心脉之阳”，而“济之以沉石，则阴阳和平”。如钩言其来势圆滑有阳和之象，按之坚沉则见肾水沉石之体，阳中有阴、沉而有力，正是肾气封藏、阴阳相济之常脉，故曰肾平，非病脉。", ["沉", "坚"]], "17452": ["其他", "本条仅列“反关脉”之名，未及脉形描述与主病。反关脉指脉不由寸口正位而行，属脉位异常之生理变异，非病机所主。原文无脉象要素可录，故脉象留空；其义当与下条“脉不行于寸口”互参，本条主旨在于标目，故归其他。", []], "17453": ["其他", "原文言脉“不行于寸口，由列缺络入臂后”，故曰反关，“必反其手而诊之乃可见”。此属脉位生理变异，非病脉；又以“左手主贵、右手主富、左右俱反富贵两全”附会推断，非言病机。全段重在辨反关脉之诊法及旧说，故归其他，脉象无要素可录。", []], "17454": ["预后", "原文指冲阳即趺阳，为“胃脉”，在足面大指间骨间动脉处。病势危笃时候此“以验其胃气之有无”，因“土为万物之母，资生之本”，故“冲阳绝死不治”。此处动脉之有无直接反映胃气存亡，脉绝则化源竭而预后凶险，故主旨属预后判断。", ["动"]], "17455": ["预后", "原文指太谿为“肾脉”，在足内踝后跟骨上陷中动脉处。病势危笃时候此“以验其肾气之有无”，因“水为天一之元，资始之本”，故“太谿绝死不治”。此动脉之存绝反映肾气根本之存亡，绝则元气竭而主死，故本段主旨在于凭脉判断危候预后。", ["动"]], "17456": ["预后", "原文以“太冲”为肝脉，诊其有无可决生死，并引《难经》“上部有脉下部无脉，是人当吐，不吐者死”。此非论具体脉象，而是以脉之有无判断气机升降：上部有脉而下部无脉，为气逆于上、下焦虚竭，故当吐；若不吐则气机闭绝，预后不良。", []], "17457": ["其他", "原文仅言“脉有不可言传之说”，未及具体脉象与病机，属脉学理论中强调脉理幽微、难以言传的论述，故列其他。", []], "17458": ["平脉", "原文论脉理幽微，虽提及滑、涩、紧等脉名及“如杨花散漫”之形容，但主旨在于说明胃气之脉“不浮不沉”“不疾不徐”“意思欣欣、悠悠扬扬”难以名状，强调脉贵有神、不可拘于迹象，属平脉神气之论。", []], "17459": ["平脉", "原文论脉随人变通：肥盛之人气居于表，六脉常带浮洪；瘦小之人气敛于中，六脉常带沉数；性急者五至为平，性缓者四至作热；少壮脉大，老年脉虚；酒后脉数，饭后脉洪；远行脉疾，久饥脉空；室女尼姑多濡弱，婴儿常七至。皆言生理常脉因形气而异，非病脉。", ["浮", "洪", "沉", "数"]], "17460": ["病机", "原文以阴阳分脉之纲领：左手为阳，右手为阴；关前为阳，关后为阴；浮取为阳，沉取为阴；长大为阳，短小为阴。约而言之，只浮沉迟数已见梗概。此段旨在以阴阳统摄脉象，说明脉为气血之先、阴阳之兆，属脉学纲领性病机论述。", ["浮", "沉", "迟", "数"]], "17461": ["其他", "原文仅言“脉有相似宜辨”，未列具体脉象与病机，属脉学辨识方法之提示，故列其他。", []], "17462": ["病机", "原文辨相似脉：洪与虚皆浮，浮而有力为洪，浮而无力为虚；沉与伏皆沉，沉行筋间重按即见，伏行骨间重按不见；数与紧皆急，数以至数言，紧则弦急如切紧绳；迟与缓皆慢，迟三至，缓四至；实与牢皆兼弦大实长，实三取皆然，牢但沉候取；革与牢皆大而弦，革浮取，牢沉取；濡与弱皆细小，濡浮分，弱沉分。", ["洪", "虚", "沉", "伏"]], "17463": ["其他", "原文仅言“脉有相反宜参”，未列具体脉象与病机，属脉学辨识方法之提示，故列其他。", []], "17464": ["病机", "原文以浮沉言脉之升降，迟数言脉之急慢，滑涩言脉之通滞，虚实言脉之刚柔，长短言脉之盈缩，洪微言脉之盛衰，紧缓言脉之张驰，牢革言脉之内外，动伏言脉之出处，促结言脉之阴阳，濡弱言脉之穷于进退，芤弦言脉之见于盛衰。此段总论脉象要素的对立统一关系，阐明脉象变化所反映的阴阳、气血、升降、通滞等病机，非主一病，而是脉学总纲。", ["浮", "沉", "迟", "数"]], "17465": ["病机", "原文仅存“脉无根有两说”一句，未展开具体脉象描述。脉无根指脉象失去根本，多主肾气衰败或胃气将绝，为病机深重之候。因原文过简，无法进一步分析具体脉象要素与症候相应关系。", []], "17466": ["妇人", "原文仅存“女人脉法”标题，未给出具体脉象描述与病机分析。妇人脉法涉及经、孕、胎、产等生理病理特点，然此段无具体内容，无法推断其脉象要素与所主病机。", []], "17467": ["妇人", "原文言“阴搏阳别谓之有子”，谓尺中阴脉搏大，与寸部阳脉迥别，主妊子；“阴虚阳搏谓之崩”，阴血衰于下，阳火上亢，血为火迫而崩漏；“手少阴脉动甚者妊子也”，心脉动甚形如豆粒、急数有力，心主血，血旺成胎，故主妊子。此段以脉象辨妇人妊娠与崩漏。", ["大", "动", "数"]], "17468": ["妇人", "原文言“身有病而无邪脉”知怀子且生，谓腹痛拘急等症虽见而脉无病象，主妊娠；“妇人欲生，其脉离经”，离经谓脉离常经，如昨小今大、昨涩今滑、昨浮今沉之类，主临产。此段以脉症合参判断妊娠与产期，脉象要素为动态变化描述，未固定为某脉。", []], "17469": ["小儿", "原文仅存“小儿脉法”标题，未给出具体脉象描述与病机分析。小儿脉法涉及年龄、诊法及常见病脉，然此段无具体内容，无法推断其脉象要素与所主病机。", []], "17470": ["小儿", "原文论小儿五岁以下看虎口食指三关脉纹：风关脉见易治，气关病深，命关命危；紫脉为热，红脉伤寒，青脉惊风，白脉疳疾，黄脉隐隐为常候，黑脉多危；纹入掌为内钩，纹弯里为风寒，纹弯外为食积。此段以脉纹颜色与形态辨小儿病机与预后，非成人之脉象要素。", []], "17471": ["病机", "原文言九候七诊中“独小者病，独大者病，独疾者病，独迟者病，独热者病，独寒者病，独陷下者病”，谓九候之中独见之脉与他部不同，即按其部而知病所在。独疾主热，独迟主寒，独寒独热则于阴部得沉微迟涩或洪实滑数之脉；独陷下为沉伏不起。形肉已脱，九候虽调犹死，主脾气脱绝之危候。", ["小", "大", "疾", "迟"]], "17472": ["预后", "原文言“七诊虽见，九候皆从者不死”，强调脉象虽见独大独小等异常，但九候皆顺四时五脏之常，则预后良好。脉顺四时之令、合五脏之常，说明正气未败，故虽病不死。此以脉之顺逆判断生死，非主具体病机。", []], "17473": ["其他", "原文仅言“必先问明然后诊脉”，强调问诊为先，未涉及具体脉象与病机。此属诊法次第，告诫医者不可卒持寸口而妄言病名，须先问明病因，方能切中病情。", []], "17474": ["误治", "原文引《素问·征四失篇》批评“卒持寸口，妄言作名”，指出不问忧患饮食、起居过度、伤毒等病因，径自切脉，必致模糊揣度，不能中病。此段主旨在于针砭不先问症而专恃切脉之误，非论具体脉象所主。", []], "17475": ["其他", "原文引王海藏云“热则脉数，寒则脉迟，实则有力，虚则无力”，说明数脉主热、迟脉主寒，此可凭脉而知。然又强调“一脉管数十症，得病之由不可以脉知”，故虽脉数主热、脉迟主寒，仍须四诊合参，不可仅凭脉断病。", ["数", "迟"]], "17476": ["其他", "原文仅存“持脉有道”四字，未及具体脉象与病机。此属诊法总纲，提示切脉有其法度，当虚静为保，非论某脉主某病。", []], "17477": ["其他", "原文引《素问·脉要精微论》“持脉有道，虚静为保”，强调切脉贵在心虚身静，方能察脉之微、不失病情。此处“微”指脉中微妙变化，非微脉主病。若躁动不安、轻言谈笑，则不能得脉中之巧，属诊法态度之戒。", ["微"]], "17478": ["平脉", "原文标题“脉以胃气为主”，指出有胃则生，无胃则死。胃脉之象为不大不小、不长不短、不滑不涩、不浮不沉、不疾不徐，应手中和，悠悠扬扬，难以名状。此段总论平人胃气之脉，为诊家判断生脉之关键，非主具体病机。", []], "17479": ["平脉", "原文以“缓脉即胃脉”立论，谓脉经所谓不大不小、不长不短、不滑不涩、不浮不沉、不疾不徐、应手中和者，即胃脉。强调六脉皆可有胃气，从容和缓乃谷气贯乎一身，不论何症何脉，但得从容和缓即为有胃气，此生脉也。此段专论平脉胃气之象。", ["缓"]], "17480": ["平脉", "原文论脉贵有神，不论病之轻重与脉之大小，但得脉有力即为无害，有力即有神。此以脉之大小与有力无力对举，强调有神有胃气为要领。脉有力即胃气未绝，虽病重亦无害，故属平脉之辨，非主一病。", ["大", "小"]], "17481": ["其他", "此段为作者自述脉学著述之缘起，论脉之大要，并推荐李士材《诊家正眼》、李濒湖《脉学》、张景岳《脉神章》等书，又言纂有《脉法大成》续刻。纯属文献交代，未涉具体脉象主病，故脉象要素为空。", []], "17482": ["病机", "原文强调医要明白阴阳表里寒热虚实八字，而八字之中阴阳虚实四字足以尽之，虚实二字又为百病之会归、八字之纲领。此段论辨证纲领，非论具体脉象，然指出虚实尤要紧，惟精于脉理者可与言，示脉诊为辨虚实之关键。", []], "17483": ["病机", "张景岳论诊病先审阴阳，以脉而言浮大滑数之类皆阳也，沉微细涩之类皆阴也。浮大滑数脉象属阳，主阳证、热证、表证、实证；沉微细涩属阴，主阴证、寒证、里证、虚证。此以脉之阴阳统摄病机，为医道纲领。", ["浮", "大", "滑", "数"]], "17484": ["病机", "原文辨真热假寒，真白虎证得之外感实热内盛，故脉洪大而长、按之有力；类白虎证得之内伤血虚发热，脉洪大而无力，即《内经》所谓脉虚血虚。洪大长有力主实热，洪大无力主血虚阳浮，脉之有力无力为辨假热之关键。", ["洪", "大", "长", "虚"]], "17485": ["病机", "原文论阴盛格阳、阳盛格阴二症至难辨，阴盛极格阳于外则外热内寒，阳盛极格阴于外则外冷内热。辨之固以脉之有力无力为凭，又当参小便清赤、口中燥润及舌苔浅深。此段以脉之有力无力辨真假寒热之病机，未出具体脉名。", []], "17486": ["病机", "原文论舌黑有实火虚火，若六脉细弱而形困气倦，则最为虚候，是寒水乘心、火不归源之病。细弱脉主虚，形困气倦为气虚，故知非实热，乃虚阳不敛、寒水凌心。此以脉症合参辨虚火病机，不救本而治标则万无一生。", ["细", "弱"]], "17487": ["病机", "李士材论虚劳诸症，谓明先天后天根本之治则无不痊安。血之源头在乎肾水为先天，气之源头在乎脾土为后天，二藏安和则百脉受调，二藏虚伪则千疴并起。此段论虚损病机根本在脾肾，未涉具体脉象，故脉象要素为空。", []], "17488": ["病机", "原文以脉分虚实：烦渴喘呼而脉数大有力，为肺热炽盛、火亢伤阴，故当润肺为主；食少善泄而脉细数无力，为脾虚气弱、阴血不足，故当扶脾为主。数大有力主实热，细数无力主虚损，脉症相参以定脾肺之主次。", ["数", "大", "细", "虚"]], "17489": ["病机", "原文未出脉名，而论血虚补气之理。引仲景“身热亡血，身凉脉凝”以明血脱须益气，因血不自生，须阳和之药乃生，阳生则阴长。若专用血药，则中州有碍而血无由生。此段重在阐发补气生血之病机，非以脉象为主。", []], "17490": ["病机", "原文未出具体脉象，而强调治病求本。谓万病之本只在表里寒热虚实六者，须察因何而起，起病之因便是病根。若初病不治或误治，则病变日多，皆从病本生出，不可头痛治头、脚痛治脚。此段主论病机之本，非脉诊专论。", []], "17491": ["治法", "原文未出具体脉象，而论大寒大热药之用法。强调热病须有热症热脉，寒病须有寒症寒脉，内外相符、确凿可据，方可用药。若仅以意揣度，则大寒大热之药力悍，极易坏事。此段以脉症相合为用药凭据，属治法准则。", []], "17492": ["其他", "原文未出脉象，而论服药后气味相投则安，不相投则知中止。举肾气上逆误认怔忡案，诊脉后以八仙长寿方加砂仁、沉香纳气归肾，初服不安而连服四十贴愈。此段强调认证之真确与守方，非专论脉象病机。", []], "17493": ["其他", "原文未出脉象，而比较外感暴病与内伤虚劳之难易。谓内伤虚劳积之有素，非旦夕可去，须精于脉理、信任得专、从容调治，甚有服至一二百帖或三五年而后愈者。此段主论内伤调治之难，非脉象主病之论。", []], "17494": ["误治", "原文未出具体脉象，而辨伤寒阳经与阳症不同：阳经为邪在表，阳症为热在里。若内无实热脉候，却以阳经作阳症，妄用寒凉攻火，则外内合邪而不可解，必死。此段以“无实热脉候”为眼目，戒误治，属误治范畴。", []], "17495": ["小儿", "原文未出具体脉象，而论小儿痘疹发热为正候，赖此热力以透毒、起化、收靥。惟热甚毒甚者，必有内热真火脉症，方可清凉；若无内热而但外热，必不可攻热，否则伤脾肾之源。此段专论小儿痘疹之脉症与治禁。", []], "17496": ["病机", "原文未出脉名，以\"经脉滞逆\"\"过期不至\"言妇人经病，归因于\"冲任不足\"。冲任为血海，不足则血少而脉道滞涩，故经行后期；若只知\"通经逐瘀\"而不\"培养血气\"，则血日涸，终致崩漏血枯。此段论虚为本、瘀为标，戒攻伐伤正。", []], "17497": ["误治", "\"脉虚证热\"点明脉虚而外见热象，此热由虚而生，\"本非真火\"。脉虚为正不足之据，虚阳浮越故作热。若误作实热\"肆用寒凉\"，则虚者更虚，轻者必重，重者必死。此段以脉虚定病性，戒寒凉误治。", ["虚"]], "17498": ["病机", "三疟后\"风邪入络\"，症见口眼歪斜、肢麻筋掣、脘痛腹鸣、头蒙发眩、燔灼艰寐。脉细为营血不足，弦为风动络滞，细弦并见示营虚生风、风窜经络。故\"防成风瘫\"，治以和养，养营熄风而非峻散。", ["细", "弦"]], "17499": ["病机", "寒热后\"风湿入络\"，肢骱酸痛甚于腰膝，当脘似寒似痛。脉沉主病在里、湿着于内，弦主风湿阻络、气机不畅，沉弦相合示风湿痹阻于里。治以疏和，疏风渗湿、和其络脉。", ["沉", "弦"]]});